import * as THREE from 'three';
import { N, CHUNK, DIRS, World, idx, heightOnTile } from '../world/tiles';
import { ROAD_INFO } from '../world/roads';
import { LAND_H, TWO_WAY, padAt, rampLift } from '../world/jumps';
import { hex, type RGB } from '../world/biomes';
import { SolidBuf } from './lamps';

/**
 * Boost pads, kickers and landing decks (world/jumps.ts), one chunk at a time. The glowing faces share one
 * unlit material whose chevrons run the way the piece shoves, so they read from far off and at night alike;
 * tickJumps (main.ts) moves them. The kicker's frame, rails and flag posts are ordinary lit solids.
 */

const TIME = { value: 0 };
/** Advance the chevrons (real seconds). */
export function tickJumps(dt: number): void { TIME.value = (TIME.value + dt) % 600; }

const glowMaterial = new THREE.ShaderMaterial({
  uniforms: { uTime: TIME },
  vertexShader: /* glsl */ `
    attribute vec2 auv;
    attribute vec3 tint;
    attribute float lamp;
    varying vec2 vUv;
    varying vec3 vTint;
    varying float vLamp;
    void main() {
      vUv = auv; vTint = tint; vLamp = lamp;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: /* glsl */ `
    uniform float uTime;
    varying vec2 vUv;
    varying vec3 vTint;
    varying float vLamp;
    void main() {
      if (vLamp > 0.5) {
        // a light bar or a flag: lit through, flickering a touch
        gl_FragColor = vec4(mix(vTint, vec3(1.0), 0.25) * (0.9 + 0.1 * sin(uTime * 9.0 + vUv.x * 4.0)), 1.0);
        return;
      }
      // u across the piece, v along the way it shoves: chevrons streaming forward, a bright rim
      float u = vUv.x, v = vUv.y;
      // + the distance from the middle: each chevron's point leads (with - it trailed, so every arrow pointed
      // back against the way it streams and the piece shoves, 19 Oct 2026)
      float c = fract(v * 2.6 + abs(u - 0.5) * 1.3 - uTime * 2.2);
      float chev = smoothstep(0.0, 0.07, c) * (1.0 - smoothstep(0.36, 0.44, c));
      float rim = 1.0 - smoothstep(0.05, 0.11, min(u, 1.0 - u));
      vec3 col = mix(vTint * 0.16, mix(vTint, vec3(1.0), 0.4), chev) + vTint * rim * 0.8;
      gl_FragColor = vec4(col * (0.85 + 0.15 * sin(uTime * 5.0 - v * 6.0)), 1.0);
    }`,
  side: THREE.DoubleSide,
  polygonOffset: true,
  polygonOffsetFactor: -2,
  polygonOffsetUnits: -2,
});

const PAD = hex(0x22e6ff), PAD2 = hex(0xffc93a), KICK = hex(0xff8a1a), LAND = hex(0x86ff3c), LIP = hex(0xfff2b0), FLAG = hex(0xff2fa0);
const FRAME = hex(0x3a3f4a), RED = hex(0xd8342a), WHITE = hex(0xf2f0ea), POLE = hex(0x9aa0a8);

class GlowGeo {
  pos: number[] = [];
  uv: number[] = [];
  tint: number[] = [];
  lamp: number[] = [];

  /** A quad from four corners in order round it, with (u, v) at each. */
  quad(p: [number, number, number][], uv: [number, number][], tint: RGB, lamp = 0): void {
    for (const k of [0, 1, 2, 0, 2, 3]) {
      this.pos.push(...p[k]);
      this.uv.push(...uv[k]);
      this.tint.push(...tint);
      this.lamp.push(lamp);
    }
  }

  mesh(): THREE.Mesh | null {
    if (!this.pos.length) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('auv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setAttribute('tint', new THREE.Float32BufferAttribute(this.tint, 3));
    g.setAttribute('lamp', new THREE.Float32BufferAttribute(this.lamp, 1));
    g.computeBoundingSphere();
    const m = new THREE.Mesh(g, glowMaterial);
    m.name = 'jumpGlow';
    return m;
  }
}

/** The road's surface at (x, z) on tile (tx, tz), the jump's ramps included. */
function roadY(w: World, tx: number, tz: number, x: number, z: number): number {
  const r = w.road[idx(tx, tz)];
  return heightOnTile(w, tx, tz, x, z) + (r ? ROAD_INFO[r].lift : 0) + rampLift(w, x, z);
}

/**
 * A glowing strip on tile (tx, tz) along DIRS[d], `hw` either side of the middle, following the road (and the
 * ramp) in a grid of nu × nv quads, `lift` over it.
 */
function strip(w: World, g: GlowGeo, tx: number, tz: number, d: number, hw: number, hl: number, tint: RGB, lift = 0.018, nu = 2, nv = 6, off = 0): void {
  const [fx, fz] = DIRS[d], rx = fz, rz = -fx;
  // `off` slides it along d from the tile's middle (a two-way pad's two halves)
  const cx = tx + 0.5 + fx * off, cz = tz + 0.5 + fz * off;
  const at = (su: number, sv: number): [number, number, number] => {
    // (kept a hair inside the tile, so the ramp's height is read from this tile, not the next)
    const x = cx + rx * su * hw + fx * sv * hl * 0.999, z = cz + rz * su * hw + fz * sv * hl * 0.999;
    return [x, roadY(w, tx, tz, x, z) + lift, z];
  };
  for (let a = 0; a < nu; a++) for (let b = 0; b < nv; b++) {
    const u0 = a / nu, u1 = (a + 1) / nu, v0 = b / nv, v1 = (b + 1) / nv;
    g.quad([at(u0 * 2 - 1, v0 * 2 - 1), at(u1 * 2 - 1, v0 * 2 - 1), at(u1 * 2 - 1, v1 * 2 - 1), at(u0 * 2 - 1, v1 * 2 - 1)],
      [[u0, v0], [u1, v0], [u1, v1], [u0, v1]], tint);
  }
}

/**
 * The body under a ramp on tile (tx, tz) along d: `segs` slabs from the ground to the ramp's surface, `hw`
 * either side of the middle, with rails along its top in red and white.
 */
function rampBody(w: World, solid: SolidBuf, tx: number, tz: number, d: number, hw: number, segs: number, rails: boolean): void {
  const [fx, fz] = DIRS[d], rx = fz, rz = -fx;
  const cx = tx + 0.5, cz = tz + 0.5;
  const P = (su: number, s: number, up: boolean): [number, number, number] => {
    const x = cx + rx * su * hw + fx * (s - 0.5) * 0.999, z = cz + rz * su * hw + fz * (s - 0.5) * 0.999;
    const ground = heightOnTile(w, tx, tz, x, z);
    return [x, up ? roadY(w, tx, tz, x, z) : ground - 0.08, z];
  };
  for (let k = 0; k < segs; k++) {
    const s0 = k / segs, s1 = (k + 1) / segs;
    const top0 = roadY(w, tx, tz, cx + fx * (s0 - 0.5), cz + fz * (s0 - 0.5)) - heightOnTile(w, tx, tz, cx + fx * (s0 - 0.5), cz + fz * (s0 - 0.5));
    const top1 = roadY(w, tx, tz, cx + fx * (s1 - 0.5), cz + fz * (s1 - 0.5)) - heightOnTile(w, tx, tz, cx + fx * (s1 - 0.5), cz + fz * (s1 - 0.5));
    if (top0 + top1 < 0.02) continue;
    solid.hull([P(-1, s0, false), P(1, s0, false), P(1, s1, false), P(-1, s1, false), P(-1, s0, true), P(1, s0, true), P(1, s1, true), P(-1, s1, true)], FRAME);
    if (!rails) continue;
    const c = k % 2 ? WHITE : RED;
    for (const su of [-1, 1]) {
      const a = P(su * 1.08, s0, true), b = P(su * 1.08, s1, true);
      const o = su * 0.05;
      solid.hull([
        [a[0], a[1] - 0.02, a[2]], [a[0] + rx * o, a[1] - 0.02, a[2] + rz * o], [b[0] + rx * o, b[1] - 0.02, b[2] + rz * o], [b[0], b[1] - 0.02, b[2]],
        [a[0], a[1] + 0.07, a[2]], [a[0] + rx * o, a[1] + 0.07, a[2] + rz * o], [b[0] + rx * o, b[1] + 0.07, b[2] + rz * o], [b[0], b[1] + 0.07, b[2]],
      ], c);
    }
  }
}

/** A pole at (x, z) from height y, `h` tall, with a pennant on top facing along (fx, fz), glowing in `tint`. */
function flagPole(solid: SolidBuf, g: GlowGeo, x: number, y: number, z: number, h: number, fx: number, fz: number, tint: RGB): void {
  solid.box(x, y, z, 0.035, h, 0.035, POLE);
  const top = y + h;
  // a pennant streaming back from the pole, and a lamp-bright cap
  g.quad([[x, top, z], [x - fx * 0.32, top - 0.07, z - fz * 0.32], [x - fx * 0.32, top - 0.11, z - fz * 0.32], [x, top - 0.18, z]],
    [[0, 0], [1, 0], [1, 1], [0, 1]], tint, 1);
}

export function buildJumpChunk(w: World, cx: number, cz: number): THREE.Group | null {
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const inChunk = (i: number) => { const x = i % N, z = (i - x) / N; return x >= x0 && x < x0 + CHUNK && z >= z0 && z < z0 + CHUNK; };
  const glow = new GlowGeo(), solid = new SolidBuf();
  // the pads
  for (let z = z0; z < z0 + CHUNK; z++) for (let x = x0; x < x0 + CHUNK; x++) {
    const d = padAt(w, idx(x, z));
    // a two-way pad: two half pads back to back, streaming out from the middle each way, in gold
    if (d >= TWO_WAY) for (const e of [d - TWO_WAY, d - TWO_WAY + 2]) strip(w, glow, x, z, e, 0.3, 0.215, PAD2, 0.02, 2, 1, 0.225);
    else if (d >= 0) strip(w, glow, x, z, d, 0.3, 0.44, PAD, 0.02, 2, 2);
  }
  for (const j of w.jumps) {
    const [fx, fz] = DIRS[j.d], rx = fz, rz = -fx;
    if (inChunk(j.kick) && w.road[j.kick]) {
      const tx = j.kick % N, tz = (j.kick - tx) / N;
      rampBody(w, solid, tx, tz, j.d, 0.36, 6, true);
      strip(w, glow, tx, tz, j.d, 0.3, 0.5, KICK, 0.012, 2, 8);
      // the lip: a light bar right across, and a flag either side
      const lx = tx + 0.5 + fx * 0.495, lz = tz + 0.5 + fz * 0.495;
      const ly = roadY(w, tx, tz, lx - fx * 0.01, lz - fz * 0.01);
      glow.quad([
        [lx - rx * 0.4, ly, lz - rz * 0.4], [lx + rx * 0.4, ly, lz + rz * 0.4],
        [lx + rx * 0.4, ly - 0.07, lz + rz * 0.4], [lx - rx * 0.4, ly - 0.07, lz - rz * 0.4],
      ], [[0, 0], [1, 0], [1, 1], [0, 1]], LIP, 1);
      for (const su of [-1, 1]) {
        const px = lx + rx * su * 0.46 - fx * 0.05, pz = lz + rz * su * 0.46 - fz * 0.05;
        flagPole(solid, glow, px, heightOnTile(w, tx, tz, px, pz) - 0.05, pz, ly - heightOnTile(w, tx, tz, px, pz) + 0.55, fx, fz, FLAG);
      }
    }
    if (inChunk(j.land) && w.road[j.land]) {
      const tx = j.land % N, tz = (j.land - tx) / N;
      rampBody(w, solid, tx, tz, j.d, 0.36, 4, false);
      strip(w, glow, tx, tz, j.d, 0.3, 0.5, LAND, 0.012, 2, 6);
      // a lamp post either side of the near edge, to aim at
      const nx = tx + 0.5 - fx * 0.45, nz = tz + 0.5 - fz * 0.45;
      for (const su of [-1, 1]) {
        const px = nx + rx * su * 0.46, pz = nz + rz * su * 0.46;
        flagPole(solid, glow, px, heightOnTile(w, tx, tz, px, pz) - 0.05, pz, LAND_H + 0.5, -fx, -fz, LAND);
      }
    }
  }
  const parts = [solid.mesh(), glow.mesh()].filter((m): m is THREE.Mesh => m !== null);
  if (!parts.length) return null;
  const g = new THREE.Group();
  g.add(...parts);
  return g;
}
