import type { CargoClass, VehicleDef } from '../vehicles';

/**
 * Rushes (docs/rushes.html): five minutes on the clock, a pickup A that fills the hold to the brim every time
 * the vehicle stops in it, a drop B close by, and the score is the units that reach B before the bell.
 *
 * Fifteen kinds over four families (road, sea, air, rail). Each finds its A and B in a county as generated
 * (game/rushes/sites.ts), so nothing is written into the world and GEN_VERSION stays.
 */

export type Family = 'road' | 'sea' | 'air' | 'rail';

/**
 * Where an end may be: a building kind, or one of the places that aren't buildings:
 * `port` a harbour's mouth, `shore` a town's waterfront (water by a town), `shoal` open water away from the shore,
 * `station` a railway station's platform, `pithead` the track beside a mine or quarry's works, `mill` the track
 * beside a power plant, steelworks or factory, `field` the ground in front of a park, square or plaza (a heli's pad).
 */
export type EndKind = string;

/**
 * What makes a kind more than the same loop: `spill` a hard knock tips a unit off the top; `melt` a unit aboard
 * longer than MELT_S counts half; `late` arriving at B over SLOW_V counts the load half; `rain` the rain comes
 * at 2:00 left; `crowd` the stands fill with what arrives; `site` the houses go up with what arrives;
 * `trawl` a trawler fills over the shoal without stopping; `island` B is on land A's roads don't reach.
 */
export type Twist = 'spill' | 'melt' | 'late' | 'rain' | 'crowd' | 'site' | 'trawl' | 'island';

export interface RushKind {
  id: string;
  name: string;
  icon: string;
  family: Family;
  /** A family besides its own that may run it too (the Island Lifeline: boats and helicopters). */
  also?: Family;
  /** What is carried, for the card and the strip. */
  goods: string;
  /** The class a hold must take; 'any' for anything with a hold (the Fleet Rush). */
  cls: CargoClass | 'any';
  from: EndKind[];
  to: EndKind[];
  /** The game hours a run may start in, [from, to) of the day. */
  hours: [number, number];
  /** Only in this season (0 spring, 1 summer, 2 autumn, 3 winter). */
  season?: number;
  /** Only on Saturdays and Sundays. */
  weekend?: boolean;
  /** Dollars a unit delivered, before the medal's bonus. */
  perUnit: number;
  twist?: Twist;
  /**
   * A long rush (docs/rushes.html "Long rushes"): ten minutes, its family's long band (twice the way, par still
   * five round trips), offered only to a fleet with an HQ of grade 4 or more and 4 vehicles, a third of the time.
   */
  long?: boolean;
  blurb: string;
}

