/** A kind's clock and its band, short or long. */
export const secsOf = (k: RushKind): number => (k.long ? RUSH.longSecs : RUSH.secs);
export const bandOf = (k: RushKind): [number, number] => (k.long ? RUSH.longBands : RUSH.bands)[k.family];

export const RUSH_KIND = new Map(RUSH_KINDS.map((k) => [k.id, k]));

/** Can this vehicle run this kind: its family, and a hold that takes the goods. Followers' classes count too. */
export function fits(k: RushKind, def: VehicleDef, also: readonly CargoClass[] = []): boolean {
  const fam: Family | null = def.kind === 'land' ? 'road' : def.kind === 'water' ? 'sea' : def.kind === 'air' ? (def.jet ? null : 'air') : def.kind === 'rail' ? 'rail' : null;
  if (!fam || (fam !== k.family && fam !== k.also)) return false;
  if (k.cls === 'any') return def.holds.length > 0 || also.length > 0;
  return def.holds.includes(k.cls) || also.includes(k.cls);
}

/** The medal a score earns against the hold the run started with: 0 none, 1 bronze, 2 silver, 3 gold. */
export function medalOf(units: number, hold: number): number {
  let m = 0;
  RUSH.medals.forEach((n, k) => { if (hold > 0 && units >= n * hold) m = k + 1; });
  return m;
}

export const MEDAL_NAME = ['', 'Bronze', 'Silver', 'Gold'];
