import { mulberry32, type Rng } from '../world/rng';
import { fieldPt, type Act, type FieldRect, type StadiumPlan, type Team } from '../world/stadiums';
import { clamp } from '../util/math';

/**
 * What happens on the field on a stadium's big day (docs/stadiums.html): a soccer match, a football game,
 * a ballgame, or a concert. Each is a little simulation in the stadium's local frame (world/stadiums.ts):
 * it moves its people and its ball, keeps the score, and says what is going on; game/stadiums.ts draws
 * it and fills the stands round it. Nothing here touches three.js, so the gate (npm run stadiums) plays
 * whole fixtures headless.
 */

/** Someone on the field or the stage: a player, an umpire, a singer, a fan in the pit. */
export interface Actor {
  x: number; z: number; y: number; yaw: number;
  /** 0 home, 1 away, 2 officials, 3 the act, 4 a fan. */
  side: number;
  /** Shirt colour; the act's and the fans' are their own. */
  col: number;
  moving: boolean;
  /** How high off the ground they are jumping. */
  hop: number;
  hidden: boolean;
  /** Drawn bigger: a goalkeeper, the singer. */
  big?: boolean;
}

export interface Ball { x: number; y: number; z: number; shown: boolean }

/** Something the stadium should do or say: a roar, a whistle, a line at the foot of the screen. */
/** `end` on a say: the full-time line, which is the final score (game/stadiums.ts says that once either way). */
type Cue = { t: 'cheer' } | { t: 'whistle'; final: boolean } | { t: 'say'; title: string; body: string; end?: boolean };

export interface Sim {
  readonly kind: 'soccer' | 'football' | 'baseball' | 'concert';
  actors: Actor[];
  ball: Ball | null;
  done: boolean;
  /** How loud the stands are, 0..1: they bounce with it. */
  buzz: number;
  cues: Cue[];
  /** What to warm up with while the crowd comes in. */
  warm(dt: number): void;
  step(dt: number): void;
  /** The strip at the foot of the screen. */
  strip(): string;
  /** The two lines on the big screen. */
  board(): [string, string];
  /** One line for the inspector and the gate: the score or the set. */
  line(): string;
}

const esc = (s: string) => s.replace(/[<&]/g, (c) => (c === '<' ? '&lt;' : '&amp;'));

function actor(side: number, col: number, x = 0, z = 0): Actor {
  return { x, z, y: 0, yaw: 0, side, col, moving: false, hop: 0, hidden: false };
}

/** Walk or run toward a point; true once there. */
function toward(a: Actor, x: number, z: number, speed: number, dt: number): boolean {
  const dx = x - a.x, dz = z - a.z, d = Math.hypot(dx, dz);
  if (d < 1e-3) { a.moving = false; return true; }
  const s = Math.min(d, speed * dt);
  a.x += (dx / d) * s;
  a.z += (dz / d) * s;
  a.yaw = Math.atan2(dx, dz);
  a.moving = s > 1e-4;
  return d <= speed * dt;
}

function face(a: Actor, x: number, z: number): void { a.yaw = Math.atan2(x - a.x, z - a.z); }

/** The field's own frame: a along its length, c across; and back. */
const toField = (f: FieldRect, x: number, z: number) => (f.axis === 'x' ? { a: x - f.cx, c: z - f.cz } : { a: z - f.cz, c: x - f.cx });

// =====================================================================================================
// soccer

const SOCCER_SHAPE: [number, number][] = [
  [0.02, 0], [0.2, -0.62], [0.17, -0.22], [0.17, 0.22], [0.2, 0.62],
  [0.42, -0.66], [0.38, -0.22], [0.38, 0.22], [0.42, 0.66], [0.6, -0.24], [0.6, 0.24],
];
/** Real seconds in a half. */
const SOCCER_HALF = 48;

export class SoccerSim implements Sim {
  readonly kind = 'soccer';
  actors: Actor[] = [];
  ball: Ball = { x: 0, y: 0.02, z: 0, shown: true };
  done = false;
  buzz = 0.2;
  cues: Cue[] = [];
  score = [0, 0];
  private r: Rng;
  private f: FieldRect;
  private L: number; private Wd: number;
  private players: Actor[][] = [[], []];
  private ref: Actor;
  private bA = 0; private bC = 0; private vA = 0; private vC = 0;
  private owner: Actor | null = null;
  private last = 0;
  private target: Actor | null = null;
  private think = 1;
  private shot: { goal: boolean; side: number } | null = null;
  /** 'kick' before a kickoff, 'play', 'goal' while they celebrate, 'half', 'full'. */
  private phase: 'kick' | 'play' | 'goal' | 'half' | 'full' = 'kick';
  private t = 0;
  private clock = 0;
  private half = 1;
  private scorer: Actor | null = null;
  /** Which way team 0 attacks this half. */
  private dir0 = 1;
  private kickTeam = 0;

  constructor(private p: StadiumPlan, private home: Team, private away: Team, seed: number) {
    this.r = mulberry32(seed);
    this.f = p.field;
    this.L = this.f.len; this.Wd = this.f.wid;
    for (let s = 0; s < 2; s++) {
      for (let i = 0; i < SOCCER_SHAPE.length; i++) {
        const a = actor(s, s === 0 ? home.colour : away.colour);
        if (i === 0) { a.col = s === 0 ? 0x2a2d33 : 0xf2c14e; a.big = true; }
        this.players[s].push(a);
        this.actors.push(a);
      }
    }
    this.ref = actor(2, 0x1f2329);
    this.actors.push(this.ref);
    // they start in the tunnel's mouth and run out to their places
    for (const a of this.actors) { const q = fieldPt(this.f, (this.r() - 0.5) * 0.4, -this.Wd / 2 - 0.15); a.x = q.x; a.z = q.z; }
    this.ball.shown = false;
  }

  private dirOf(s: number): number { return s === 0 ? this.dir0 : -this.dir0; }
  private at(a: number, c: number) { return fieldPt(this.f, a, c); }

  /** Where a player should be: their place in the shape, pushed up or back with the ball. */
  private home_(s: number, i: number, pushed: boolean): { a: number; c: number } {
    const d = this.dirOf(s), [fa, fc] = SOCCER_SHAPE[i];
    let a = d * (-this.L / 2 + fa * this.L * (pushed ? 1 : 0.85));
    let c = fc * (this.Wd / 2) * 0.85;
    if (pushed && i > 0) {
      a += clamp(this.bA * 0.45, -this.L * 0.25, this.L * 0.25);
      c += this.bC * 0.2;
    }
    if (!pushed) a = d * Math.min(-0.08, d * a);
    return { a: clamp(a, -this.L / 2 + 0.05, this.L / 2 - 0.05), c: clamp(c, -this.Wd / 2 + 0.05, this.Wd / 2 - 0.05) };
  }

  warm(dt: number): void {
    // run out, and jog to their places
    for (let s = 0; s < 2; s++) this.players[s].forEach((a, i) => { const h = this.home_(s, i, false), q = this.at(h.a, h.c); toward(a, q.x, q.z, 0.35, dt); });
    const q = this.at(0, -this.Wd * 0.3);
    toward(this.ref, q.x, q.z, 0.35, dt);
    this.bob(dt);
  }

  private kickoff(team: number): void {
    this.phase = 'kick';
    this.t = 0;
    this.bA = 0; this.bC = 0; this.vA = 0; this.vC = 0;
    this.owner = null;
    this.target = null;
    this.shot = null;
    this.kickTeam = team;
  }

  step(dt: number): void {
    this.t += dt;
    this.buzz += ((this.phase === 'goal' ? 1 : Math.abs(this.bA) > this.L * 0.3 ? 0.45 : 0.15) - this.buzz) * Math.min(1, dt * 2);
    if (this.phase === 'kick') {
      this.ball.shown = true;
      let ready = true;
      for (let s = 0; s < 2; s++) this.players[s].forEach((a, i) => { const h = this.home_(s, i, false), q = this.at(h.a, h.c); if (!toward(a, q.x, q.z, 0.5, dt)) ready = false; });
      const k = this.players[this.kickTeam][9], q0 = this.at(-this.dirOf(this.kickTeam) * 0.05, 0);
      if (!toward(k, q0.x, q0.z, 0.5, dt)) ready = false;
      if ((ready && this.t > 1.2) || this.t > 5) {
        if (this.clock === 0 || (this.half === 2 && this.clock === SOCCER_HALF)) this.cues.push({ t: 'whistle', final: false });
        this.phase = 'play';
        this.owner = k;
        this.last = this.kickTeam;
        this.think = 0.4;
      }
    } else if (this.phase === 'play') {
      this.clock += dt;
      this.play(dt);
      if (this.clock >= SOCCER_HALF * this.half && this.phase === 'play') {
        this.cues.push({ t: 'whistle', final: this.half === 2 });
        if (this.half === 1) {
          this.phase = 'half'; this.t = 0;
          this.cues.push({ t: 'say', title: 'Half time', body: this.line() });
        } else {
          this.phase = 'full'; this.t = 0;
          const w = this.score[0] > this.score[1] ? this.home : this.score[1] > this.score[0] ? this.away : null;
          this.cues.push({ t: 'say', title: 'Full time', body: `${this.line()}${w ? ` · ${w.nick} win` : ' · a draw'}`, end: true });
          if (this.score[0] >= this.score[1]) this.cues.push({ t: 'cheer' });
        }
      }
    } else if (this.phase === 'goal') {
      // the scorer wheels away to the corner flag, and the team catch up with them
      const s = this.scorer!.side, d = this.dirOf(s);
      const flag = this.at(d * (this.L / 2 - 0.1), (this.scorer!.z > 0 ? 1 : -1) * (this.Wd / 2 - 0.1));
      toward(this.scorer!, flag.x, flag.z, 0.6, dt);
      this.players[s].forEach((a, i) => { if (a !== this.scorer && i > 0) toward(a, flag.x + (i % 3 - 1) * 0.12, flag.z + (i % 2 ? 0.1 : -0.1), 0.45, dt); });
      for (const a of this.players[s]) a.hop = a.moving ? 0 : Math.abs(Math.sin(this.t * 9 + a.x * 7)) * 0.05;
      if (this.t > 4) { for (const a of this.players[s]) a.hop = 0; this.kickoff(1 - s); }
    } else if (this.phase === 'half') {
      if (this.t > 5) { this.half = 2; this.dir0 = -1; this.kickoff(1); }
      else for (let s = 0; s < 2; s++) this.players[s].forEach((a, i) => { const h = this.home_(s, i, false), q = this.at(h.a, h.c); toward(a, q.x, q.z, 0.3, dt); });
    } else {
      const win = this.score[0] > this.score[1] ? 0 : this.score[1] > this.score[0] ? 1 : -1;
      for (let s = 0; s < 2; s++) for (const a of this.players[s]) { a.moving = false; a.hop = s === win ? Math.abs(Math.sin(this.t * 8 + a.z * 9)) * 0.05 : 0; }
      if (this.t > 5) this.done = true;
    }
    // the referee keeps up with play
    const rq = this.at(this.bA * 0.8, clamp(this.bC - 0.4, -this.Wd / 2, this.Wd / 2));
    if (this.phase === 'play' || this.phase === 'kick') toward(this.ref, rq.x, rq.z, 0.4, dt);
    const b = this.at(this.bA, this.bC);
    this.ball.x = b.x; this.ball.z = b.z;
    this.bob(dt);
  }

  private bob(dt: number): void { void dt; for (const a of this.actors) if (!a.moving && this.phase !== 'goal' && this.phase !== 'full') a.hop = 0; }

  private play(dt: number): void {
    const RUN = 0.52, DRIB = 0.42, gw = Math.min(0.32, this.Wd * 0.12);
    const pos = (a: Actor) => toField(this.f, a.x, a.z);
    if (this.owner) {
      const o = this.owner, s = o.side, d = this.dirOf(s), me = pos(o);
      // carry it toward goal, drifting in from the wing
      const goalA = d * this.L / 2;
      const ta = me.a + d * 0.6, tc = me.c * 0.9;
      const tq = this.at(clamp(ta, -this.L / 2, this.L / 2), tc);
      toward(o, tq.x, tq.z, o.big ? DRIB * 0.6 : DRIB, dt);
      const now = pos(o);
      this.bA = now.a + d * 0.05; this.bC = now.c;
      this.think -= dt;
      const pressed = this.players[1 - s].some((q) => Math.hypot(q.x - o.x, q.z - o.z) < 0.14);
      const range = Math.abs(goalA - now.a) < this.L * 0.33;
      if (this.think <= 0) {
        this.think = 0.5 + this.r() * 0.8;
        if (range && this.r() < 0.7) this.shoot(o, gw);
        else if (pressed || o.big || this.r() < 0.45) this.pass(o);
      }
      // a tackle
      if (this.owner === o) {
        for (const q of this.players[1 - s]) {
          if (Math.hypot(q.x - o.x, q.z - o.z) < 0.08 && this.r() < dt * 0.9) {
            this.owner = q; this.last = q.side; this.think = 0.3 + this.r() * 0.5;
            break;
          }
        }
      }
    } else {
      // the ball runs on, slowing
      this.bA += this.vA * dt; this.bC += this.vC * dt;
      const k = Math.exp(-(this.shot ? 0.15 : 1.1) * dt);
      this.vA *= k; this.vC *= k;
      // over the goal line
      if (Math.abs(this.bA) >= this.L / 2) {
        const side = this.bA > 0 ? 1 : -1;
        const scorer = this.shot && this.shot.goal ? this.shot.side : null;
        if (scorer !== null && Math.abs(this.bC) < gw) { this.goal(scorer); return; }
        // wide, or the keeper's: a goal kick
        const defending = this.dirOf(0) === side ? 1 : 0;
        this.bA = side * (this.L / 2 - 0.08); this.vA = 0; this.vC = 0;
        this.owner = this.players[defending][0]; this.last = defending; this.shot = null; this.think = 0.6;
        return;
      }
      // over a touchline: a throw to the other side
      if (Math.abs(this.bC) >= this.Wd / 2) {
        this.bC = Math.sign(this.bC) * (this.Wd / 2 - 0.03); this.vA = 0; this.vC = 0;
        const s = 1 - this.last;
        const b = this.at(this.bA, this.bC);
        const near = this.players[s].slice(1).sort((p, q) => Math.hypot(p.x - b.x, p.z - b.z) - Math.hypot(q.x - b.x, q.z - b.z))[0];
        near.x = b.x; near.z = b.z;
        this.owner = near; this.last = s; this.shot = null; this.think = 0.3;
        return;
      }
      // the keeper of a goal-bound shot that isn't going in saves it
      if (this.shot && !this.shot.goal) {
        const s = 1 - this.shot.side, gk = this.players[s][0], g = pos(gk);
        if (Math.abs(g.a - this.bA) < 0.12 && Math.abs(g.c - this.bC) < 0.2) {
          this.owner = gk; this.last = s; this.shot = null; this.think = 0.8; this.vA = this.vC = 0;
          this.cues.push({ t: 'say', title: 'Save!', body: `${s === 0 ? this.home.nick : this.away.nick} keeper gathers it` });
          return;
        }
      }
      // whoever reaches it first has it
      if (!this.shot && Math.hypot(this.vA, this.vC) < 1.4) {
        const b = this.at(this.bA, this.bC);
        for (const a of this.actors) {
          if (a.side > 1) continue;
          if (Math.hypot(a.x - b.x, a.z - b.z) < 0.06) { this.owner = a; this.last = a.side; this.target = null; this.think = 0.4 + this.r() * 0.6; break; }
        }
      }
    }
    // everyone else: the nearest of each side chases, the receiver comes to meet it, the rest hold their shape
    const b = this.at(this.bA, this.bC);
    for (let s = 0; s < 2; s++) {
      let chaser: Actor | null = null, best = Infinity;
      for (const a of this.players[s].slice(1)) {
        const d = Math.hypot(a.x - b.x, a.z - b.z);
        if (d < best) { best = d; chaser = a; }
      }
      this.players[s].forEach((a, i) => {
        if (a === this.owner) return;
        if (i === 0) {
          // the keeper on the line, with the ball
          const d = this.dirOf(s), q = this.at(-d * (this.L / 2 - 0.06), clamp(this.bC * 0.5, -gw, gw));
          toward(a, q.x, q.z, 0.4, dt);
          return;
        }
        if (a === this.target || (a === chaser && (!this.owner || this.owner.side !== s))) { toward(a, b.x, b.z, RUN, dt); return; }
        const h = this.home_(s, i, true), q = this.at(h.a, h.c);
        toward(a, q.x, q.z, RUN * 0.6, dt);
      });
    }
  }

  private pass(o: Actor): void {
    const s = o.side, d = this.dirOf(s), me = toField(this.f, o.x, o.z);
    // the furthest forward, give or take: scored once each, then sorted (never a random comparator)
    const mates = this.players[s].filter((a) => a !== o && !a.big)
      .map((a) => { const p = toField(this.f, a.x, a.z); return { a, p, k: d * p.a + (this.r() - 0.5) * 0.6 }; })
      .sort((x, y) => y.k - x.k);
    const pick = mates[Math.floor(this.r() * Math.min(4, mates.length))];
    if (!pick) return;
    const da = pick.p.a - me.a, dc = pick.p.c - me.c, len = Math.hypot(da, dc) || 1;
    const sp = 1.3 + len * 0.6;
    this.vA = (da / len) * sp; this.vC = (dc / len) * sp;
    this.owner = null; this.target = pick.a; this.last = s; this.shot = null;
  }

  private shoot(o: Actor, gw: number): void {
    const s = o.side, d = this.dirOf(s), me = toField(this.f, o.x, o.z);
    const dist = Math.abs(d * this.L / 2 - me.a);
    const goal = this.r() < clamp(0.5 - dist * 0.1, 0.15, 0.45);
    const wide = !goal && this.r() < 0.45;
    const c = goal ? (this.r() - 0.5) * gw * 1.6 : wide ? Math.sign(this.r() - 0.5) * gw * (1.3 + this.r()) : (this.r() - 0.5) * gw;
    const da = d * this.L / 2 + d * 0.1 - me.a, dc = c - me.c, len = Math.hypot(da, dc) || 1;
    this.vA = (da / len) * 2.6; this.vC = (dc / len) * 2.6;
    this.owner = null; this.target = null; this.last = s;
    this.shot = { goal, side: s };
    this.scorer = o;
  }

  private goal(side: number): void {
    this.score[side]++;
    this.phase = 'goal';
    this.t = 0;
    this.vA = this.vC = 0;
    this.owner = null;
    this.shot = null;
    const t = side === 0 ? this.home : this.away;
    this.cues.push({ t: 'cheer' });
    this.cues.push({ t: 'say', title: `⚽ Goal — ${t.name}!`, body: `${this.line()} · ${Math.min(90, Math.floor((this.clock / SOCCER_HALF) * 45))}'` });
  }

  strip(): string {
    const m = this.phase === 'half' ? 'HT' : this.phase === 'full' ? 'FT' : `${Math.min(90, Math.floor((this.clock / SOCCER_HALF) * 45))}'`;
    return `<span>⚽ <b>${esc(this.home.nick)}</b> ${this.score[0]} – ${this.score[1]} <b>${esc(this.away.nick)}</b></span><span class="clock">${m}</span>`;
  }
  board(): [string, string] {
    const m = this.phase === 'half' ? 'HALF TIME' : this.phase === 'full' ? 'FULL TIME' : `${Math.min(90, Math.floor((this.clock / SOCCER_HALF) * 45))}'`;
    return [`${this.home.abbr} ${this.score[0]}-${this.score[1]} ${this.away.abbr}`, m];
  }
  line(): string { return `${this.home.nick} ${this.score[0]}–${this.score[1]} ${this.away.nick}`; }
}

// =====================================================================================================
// American football

type Play = 'run' | 'pass' | 'fg' | 'punt';
/** Plays a quarter. */
const FOOTBALL_PLAYS = 7;

export class FootballSim implements Sim {
  readonly kind = 'football';
  actors: Actor[] = [];
  ball: Ball = { x: 0, y: 0.05, z: 0, shown: false };
  done = false;
  buzz = 0.2;
  cues: Cue[] = [];
  score = [0, 0];
  private r: Rng;
  private f: FieldRect;
  private YD: number;
  private team: Actor[][] = [[], []];
  private refs: Actor[] = [];
  private off = 0;
  private los = 25;
  private down = 1;
  private togo = 10;
  private q = 1;
  private plays = 0;
  private phase: 'huddle' | 'snap' | 'action' | 'dead' | 'final' = 'huddle';
  private t = 0;
  private call: Play = 'run';
  /** Where the play ends, in yards from the offense's own goal, and what came of it. */
  private gain = 0;
  private result: 'gain' | 'inc' | 'int' | 'fumble' | 'td' | 'fg' | 'nofg' | 'punt' = 'gain';
  private carrier: Actor | null = null;
  private dur = 2;
  private flight: { x0: number; z0: number; x1: number; z1: number; t0: number; t1: number; h: number } | null = null;
  private yardC = 0;
  private receiver = 7;

  constructor(private p: StadiumPlan, private home: Team, private away: Team, seed: number) {
    this.r = mulberry32(seed);
    this.f = p.field;
    this.YD = this.f.len / 120;
    for (let s = 0; s < 2; s++) for (let i = 0; i < 11; i++) { const a = actor(s, s === 0 ? home.colour : away.colour); this.team[s].push(a); this.actors.push(a); }
    for (let i = 0; i < 3; i++) { const a = actor(2, 0xf4f2ec); this.refs.push(a); this.actors.push(a); }
    for (const a of this.actors) { const q = fieldPt(this.f, (this.r() - 0.5) * 0.6, (a.side === 1 ? 1 : -1) * (this.f.wid / 2 + 0.12)); a.x = q.x; a.z = q.z; }
    this.off = this.r() < 0.5 ? 0 : 1;
  }

  private dirOf(s: number) { return s === 0 ? 1 : -1; }
  /** A spot on the field: yards from this side's own goal line, and across. */
  private spot(s: number, yards: number, c: number) { return fieldPt(this.f, this.dirOf(s) * (-this.f.len / 2 + (10 + yards) * this.YD), c); }

  /** The two sides lined up at the line of scrimmage. */
  private formation(): { x: number; z: number }[][] {
    const W = this.f.wid / 2, o = this.off, d = 1 - o, L = this.los, Y = (yd: number) => yd, cy = (k: number) => k * W;
    const offence: [number, number][] = [
      [-1, -0.16], [-1, -0.08], [-1, 0], [-1, 0.08], [-1, 0.16], [-5, 0], [-7, 0.04], [-0.5, -0.85], [-0.5, 0.85], [-1.2, 0.26], [-1.6, -0.5],
    ];
    const defence: [number, number][] = [
      [1, -0.14], [1, -0.05], [1, 0.05], [1, 0.14], [5, -0.25], [5, 0], [5, 0.25], [3, -0.82], [3, 0.82], [12, -0.3], [12, 0.3],
    ];
    const out: { x: number; z: number }[][] = [[], []];
    out[o] = offence.map(([yd, c]) => this.spot(o, L + Y(yd), cy(c)));
    out[d] = defence.map(([yd, c]) => this.spot(o, L + Y(yd), cy(c)));
    return out;
  }

  warm(dt: number): void {
    const f = this.formation();
    for (let s = 0; s < 2; s++) this.team[s].forEach((a, i) => toward(a, f[s][i].x, f[s][i].z, 0.3, dt));
    this.refs.forEach((a, i) => { const q = this.spot(this.off, this.los + (i === 0 ? -9 : i === 1 ? 8 : 0), (i === 2 ? -1.05 : 0.5) * this.f.wid / 2); toward(a, q.x, q.z, 0.3, dt); });
  }

  step(dt: number): void {
    this.t += dt;
    this.buzz += ((this.result === 'td' && this.phase === 'dead' ? 1 : this.phase === 'action' ? 0.45 : 0.15) - this.buzz) * Math.min(1, dt * 2);
    for (const a of this.actors) a.hop = 0;
    if (this.phase === 'huddle') {
      const f = this.formation();
      let ready = true;
      for (let s = 0; s < 2; s++) this.team[s].forEach((a, i) => { if (!toward(a, f[s][i].x, f[s][i].z, 0.5, dt)) ready = false; });
      // set, they face each other across the line
      const up = this.ahead();
      for (let s = 0; s < 2; s++) {
        const k = s === this.off ? 1 : -1;
        for (const a of this.team[s]) if (!a.moving) face(a, a.x + k * up.x, a.z + k * up.z);
      }
      this.refs.forEach((a, i) => { const q = this.spot(this.off, this.los + (i === 0 ? -9 : i === 1 ? 8 : 0), (i === 2 ? -1.05 : 0.5) * this.f.wid / 2); toward(a, q.x, q.z, 0.5, dt); });
      const c = this.team[this.off][2];
      this.ball.shown = true;
      this.ball.x = c.x; this.ball.z = c.z; this.ball.y = 0.03;
      if ((ready && this.t > 1.1) || this.t > 4) { this.phase = 'snap'; this.t = 0; this.callPlay(); }
    } else if (this.phase === 'snap') {
      if (this.t > 0.35) { this.phase = 'action'; this.t = 0; }
    } else if (this.phase === 'action') {
      this.action(dt);
    } else if (this.phase === 'dead') {
      if (this.result === 'td') for (const a of this.team[this.carrierSide()]) a.hop = Math.abs(Math.sin(this.t * 9 + a.x * 5)) * 0.05;
      if (this.t > (this.result === 'td' ? 2.6 : 1.0)) this.next();
    } else {
      const win = this.score[0] > this.score[1] ? 0 : this.score[1] > this.score[0] ? 1 : -1;
      if (win >= 0) for (const a of this.team[win]) a.hop = Math.abs(Math.sin(this.t * 8 + a.z * 9)) * 0.05;
      if (this.t > 5) this.done = true;
    }
  }

  /** A step toward the defence's goal, for the offence facing downfield. */
  private ahead(): { x: number; z: number } {
    const d = this.dirOf(this.off);
    return this.f.axis === 'x' ? { x: d, z: 0 } : { x: 0, z: d };
  }

  private carrierSide(): number { return this.result === 'int' || this.result === 'fumble' ? 1 - this.off : this.off; }

  private callPlay(): void {
    const r = this.r, toGoal = 100 - this.los;
    if (this.down === 4 && this.togo > 1) this.call = toGoal <= 37 ? 'fg' : 'punt';
    else this.call = r() < 0.52 ? 'run' : 'pass';
    const roll = r();
    if (this.call === 'run') {
      this.result = roll < 0.02 ? 'fumble' : 'gain';
      this.gain = roll < 0.09 ? 18 + Math.floor(r() * 45) : Math.round(-1 + r() * 9 + r() * 5);
    } else if (this.call === 'pass') {
      if (roll < 0.035) { this.result = 'int'; this.gain = 8 + Math.floor(r() * 20); }
      else if (roll < 0.09) { this.result = 'gain'; this.gain = -(4 + Math.floor(r() * 5)); }
      else if (roll < 0.4) { this.result = 'inc'; this.gain = 8 + Math.floor(r() * 18); }
      else { this.result = 'gain'; this.gain = roll > 0.86 ? 26 + Math.floor(r() * 45) : 6 + Math.floor(r() * 18); }
    } else if (this.call === 'fg') {
      const dist = toGoal + 17;
      this.result = r() < clamp(1.25 - dist / 55, 0.2, 0.97) ? 'fg' : 'nofg';
      this.gain = toGoal + 10;
    } else {
      this.result = 'punt';
      this.gain = 36 + Math.floor(r() * 14);
    }
    if (this.result === 'gain' && this.los + this.gain >= 100) { this.result = 'td'; this.gain = 100 - this.los + 3; }
    this.dur = this.call === 'run' ? clamp(1.0 + Math.abs(this.gain) * 0.07, 1.2, 4) : this.call === 'pass' ? clamp(1.6 + Math.abs(this.gain) * 0.05, 1.8, 4.2) : 2.2;
    this.carrier = this.call === 'run' ? this.team[this.off][6] : this.team[this.off][5];
    this.receiver = this.r() < 0.5 ? 7 : 8;
    this.flight = null;
    this.yardC = (this.r() - 0.5) * this.f.wid * 0.6;
  }

  private action(dt: number): void {
    const o = this.off, dset = this.team[1 - o], oset = this.team[o];
    const T = this.t, k = clamp(T / this.dur, 0, 1);
    const qb = oset[5];
    if (this.call === 'run') {
      const c = this.carrier!;
      const end = this.spot(o, this.los + this.gain, this.yardC * 0.6);
      const sp = Math.max(0.35, Math.hypot(end.x - c.x, end.z - c.z) / Math.max(0.2, this.dur - T));
      toward(c, end.x, end.z, sp, dt);
      this.ball.x = c.x; this.ball.z = c.z; this.ball.y = 0.08;
    } else if (this.call === 'pass') {
      const drop = this.spot(o, this.los - 7, 0);
      toward(qb, drop.x, drop.z, 0.4, dt);
      const catchAt = this.spot(o, this.los + this.gain, this.yardC);
      // the receivers run their routes, the one it's going to toward where it will come down
      for (const i of [7, 8, 9]) {
        const q = i === this.receiver ? catchAt : this.spot(o, this.los + this.gain * (i === 9 ? 0.5 : 0.8), i === 7 ? -this.f.wid * 0.3 : i === 8 ? this.f.wid * 0.3 : this.yardC * 0.4);
        toward(oset[i], q.x, q.z, 0.6, dt);
      }
      if (!this.flight && T > 0.7) {
        if (this.gain < 0) {
          // sacked: a lineman gets through
          toward(dset[1], qb.x, qb.z, 0.7, dt);
          this.ball.x = qb.x; this.ball.z = qb.z; this.ball.y = 0.08;
        } else {
          this.flight = { x0: qb.x, z0: qb.z, x1: catchAt.x, z1: catchAt.z, t0: T, t1: T + 0.6 + this.gain * 0.012, h: 0.25 + this.gain * 0.01 };
        }
      } else if (!this.flight) { this.ball.x = qb.x; this.ball.z = qb.z; this.ball.y = 0.08; }
      if (this.flight) {
        const fl = this.flight, u = clamp((T - fl.t0) / (fl.t1 - fl.t0), 0, 1);
        this.ball.x = fl.x0 + (fl.x1 - fl.x0) * u; this.ball.z = fl.z0 + (fl.z1 - fl.z0) * u; this.ball.y = 0.08 + Math.sin(u * Math.PI) * fl.h;
        if (u >= 1 && this.result === 'inc') this.ball.y = 0.02;
        this.dur = Math.max(this.dur, fl.t1 + 0.4);
      }
    } else {
      // a kick: the holder and the kicker, and the ball high over the field
      const holder = oset[5], kicker = oset[6];
      const kp = this.spot(o, this.los - (this.call === 'fg' ? 7 : 12), 0);
      toward(holder, kp.x, kp.z, 0.5, dt);
      toward(kicker, kp.x, kp.z + 0.05, 0.5, dt);
      if (!this.flight && T > 0.6) {
        const to = this.call === 'fg' ? this.spot(o, 110, (this.result === 'nofg' ? (this.r() < 0.5 ? -1 : 1) * 0.15 : 0)) : this.spot(o, this.los + this.gain, this.yardC * 0.3);
        this.flight = { x0: kp.x, z0: kp.z, x1: to.x, z1: to.z, t0: T, t1: T + 1.3, h: this.call === 'fg' ? 0.9 : 1.2 };
      }
      if (this.flight) {
        const fl = this.flight, u = clamp((T - fl.t0) / (fl.t1 - fl.t0), 0, 1);
        this.ball.x = fl.x0 + (fl.x1 - fl.x0) * u; this.ball.z = fl.z0 + (fl.z1 - fl.z0) * u; this.ball.y = 0.06 + Math.sin(u * Math.PI) * fl.h;
      } else { this.ball.x = kp.x; this.ball.z = kp.z; this.ball.y = 0.04; }
      this.dur = 2.6;
    }
    // the line pushes, the defence converges on the ball
    oset.forEach((a, i) => { if (i < 5) { const q = this.spot(o, this.los + (k < 0.5 ? 0.5 : 0) , (i - 2) * 0.08 * this.f.wid / 2); toward(a, q.x, q.z, 0.15, dt); } });
    dset.forEach((a, i) => {
      const chase = i < 4 ? 0.42 : 0.5;
      const tx = this.ball.x + (i % 3 - 1) * 0.06, tz = this.ball.z + ((i >> 1) % 3 - 1) * 0.06;
      toward(a, tx, tz, chase * (k > 0.6 ? 1.2 : 1), dt);
    });
    if (T >= this.dur) this.whistle();
  }

  private whistle(): void {
    this.phase = 'dead';
    this.t = 0;
    this.cues.push({ t: 'whistle', final: false });
    const o = this.off, mine = o === 0 ? this.home : this.away, theirs = o === 0 ? this.away : this.home;
    const switchTo = (los: number) => { this.off = 1 - this.off; this.los = clamp(los, 1, 99); this.down = 1; this.togo = 10; };
    switch (this.result) {
      case 'td':
        this.score[o] += 6 + (this.r() < 0.94 ? 1 : 0);
        this.cues.push({ t: 'cheer' });
        this.cues.push({ t: 'say', title: `🏈 Touchdown ${mine.name}!`, body: this.line() });
        this.pending = () => switchTo(25);
        return;
      case 'fg':
        this.score[o] += 3;
        this.cues.push({ t: 'cheer' });
        this.cues.push({ t: 'say', title: `Field goal is good`, body: `${mine.nick} · ${this.line()}` });
        this.pending = () => switchTo(25);
        return;
      case 'nofg':
        this.cues.push({ t: 'say', title: 'No good!', body: `${mine.nick} miss the field goal` });
        this.pending = () => switchTo(100 - this.los + 7);
        return;
      case 'punt':
        this.pending = () => switchTo(this.los + this.gain >= 100 ? 20 : 100 - (this.los + this.gain));
        return;
      case 'int':
      case 'fumble':
        this.cues.push({ t: 'cheer' });
        this.cues.push({ t: 'say', title: this.result === 'int' ? 'Intercepted!' : 'Fumble!', body: `${theirs.nick} take over` });
        this.pending = () => switchTo(100 - (this.los + Math.max(0, this.gain)));
        return;
      case 'inc':
        this.pending = () => this.advance(0);
        return;
      default:
        this.pending = () => this.advance(this.gain);
    }
  }
  private pending: (() => void) | null = null;

  private advance(g: number): void {
    this.los = clamp(this.los + g, 1, 99);
    this.togo -= g;
    if (this.togo <= 0) { this.down = 1; this.togo = Math.min(10, 100 - this.los); }
    else if (++this.down > 4) {
      this.cues.push({ t: 'say', title: 'Turnover on downs', body: `${(this.off === 0 ? this.away : this.home).nick} take over` });
      this.off = 1 - this.off; this.los = 100 - this.los; this.down = 1; this.togo = 10;
    }
  }

  private next(): void {
    this.pending?.();
    this.pending = null;
    if (++this.plays >= FOOTBALL_PLAYS) {
      this.plays = 0;
      this.cues.push({ t: 'whistle', final: this.q === 4 });
      if (this.q === 4) {
        this.phase = 'final'; this.t = 0;
        const w = this.score[0] > this.score[1] ? this.home : this.score[1] > this.score[0] ? this.away : null;
        this.cues.push({ t: 'say', title: 'Final', body: `${this.line()}${w ? ` · ${w.nick} win` : ' · a tie'}`, end: true });
        if (w === this.home) this.cues.push({ t: 'cheer' });
        this.ball.shown = false;
        return;
      }
      this.q++;
      if (this.q === 3) { this.off = 1 - this.off; this.los = 25; this.down = 1; this.togo = 10; }
    }
    this.phase = 'huddle';
    this.t = 0;
  }

  private clockText(): string {
    const left = Math.max(0, 15 * 60 - Math.round((this.plays / FOOTBALL_PLAYS) * 15 * 60));
    return `Q${this.q} ${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')}`;
  }
  private downText(): string {
    const nth = ['1st', '2nd', '3rd', '4th'][this.down - 1];
    const yd = this.los <= 50 ? `own ${this.los}` : `opp ${100 - this.los}`;
    return `${nth} & ${this.togo >= 100 - this.los ? 'goal' : this.togo} · ${yd}`;
  }

  strip(): string {
    if (this.phase === 'final') return `<span>🏈 Final: <b>${esc(this.home.nick)}</b> ${this.score[0]} – ${this.score[1]} <b>${esc(this.away.nick)}</b></span>`;
    const has = this.off === 0 ? this.home : this.away;
    return `<span>🏈 <b>${esc(this.home.nick)}</b> ${this.score[0]} – ${this.score[1]} <b>${esc(this.away.nick)}</b></span><span>${esc(has.abbr)} ball · ${esc(this.downText())}</span><span class="clock">${this.clockText()}</span>`;
  }
  board(): [string, string] {
    return [`${this.home.abbr} ${this.score[0]}  ${this.away.abbr} ${this.score[1]}`, this.phase === 'final' ? 'FINAL' : this.clockText()];
  }
  line(): string { return `${this.home.nick} ${this.score[0]}–${this.score[1]} ${this.away.nick}`; }
}

// =====================================================================================================
// baseball

type PA = 'k' | 'bb' | 'go' | 'fo' | '1b' | '2b' | '3b' | 'hr';
/** Innings in a game: six, a short exhibition — nine would keep the crowd past midnight. */
const INNINGS = 6;

export class BaseballSim implements Sim {
  readonly kind = 'baseball';
  actors: Actor[] = [];
  ball: Ball = { x: 0, y: 0.06, z: 0, shown: false };
  done = false;
  buzz = 0.2;
  cues: Cue[] = [];
  score = [0, 0];
  private r: Rng;
  private roster: Actor[][] = [[], []];
  private ump: Actor;
  private hx: number; private hz: number;
  private e1: [number, number]; private e3: [number, number]; private cf: [number, number];
  private base: number; private fence: number;
  private inning = 1;
  private top = true;
  private outs = 0;
  /** Who stands on first, second and third. */
  private bases: (Actor | null)[] = [null, null, null];
  private batter: Actor | null = null;
  private order = [0, 0];
  private phase: 'change' | 'windup' | 'pitch' | 'play' | 'final' = 'change';
  private t = 0;
  private pa: PA = 'k';
  private pitches = 0;
  /** Runners on their way: who, the bases still to touch, whether they score at the end. */
  private running: { a: Actor; path: { x: number; z: number }[]; to: number }[] = [];
  private fielder: Actor | null = null;
  private flight: { x0: number; z0: number; x1: number; z1: number; t0: number; t1: number; h: number; roll?: boolean } | null = null;
  private throwTo: { x: number; z: number } | null = null;

  constructor(private p: StadiumPlan, private home: Team, private away: Team, seed: number) {
    this.r = mulberry32(seed);
    const dm = p.diamond!;
    this.hx = dm.hx; this.hz = dm.hz; this.base = dm.base; this.fence = dm.fence;
    const S = Math.SQRT1_2;
    this.cf = [dm.dx, dm.dz];
    this.e1 = [dm.dx * S - dm.dz * S, dm.dx * S + dm.dz * S];
    this.e3 = [dm.dx * S + dm.dz * S, -dm.dx * S + dm.dz * S];
    for (let s = 0; s < 2; s++) for (let i = 0; i < 9; i++) { const a = actor(s, s === 0 ? home.colour : away.colour); this.roster[s].push(a); this.actors.push(a); }
    this.ump = actor(2, 0x1f2329);
    this.actors.push(this.ump);
    for (const a of this.actors) { const q = this.dugout(a.side === 2 ? 0 : a.side, 0); a.x = q.x; a.z = q.z; }
  }

  /** A point down the lines from home: u toward first, v toward third. */
  private P(u: number, v: number) { return { x: this.hx + this.e1[0] * u + this.e3[0] * v, z: this.hz + this.e1[1] * u + this.e3[1] * v }; }
  private baseAt(n: number) { return n === 0 || n === 4 ? this.P(0, 0) : n === 1 ? this.P(this.base, 0) : n === 2 ? this.P(this.base, this.base) : this.P(0, this.base); }
  /** The home side's dugout is down the first-base line, the visitors' down the third. */
  private dugout(s: number, i: number) { const k = this.base * (0.35 + i * 0.09); return s === 0 ? this.P(k, -0.22) : this.P(-0.22, k); }
  private fieldSpot(i: number): { x: number; z: number } {
    const b = this.base, R = this.fence;
    const at = (deg: number, d: number) => { const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a); return { x: this.hx + (this.cf[0] * c - this.cf[1] * s) * d, z: this.hz + (this.cf[0] * s + this.cf[1] * c) * d }; };
    switch (i) {
      case 0: return this.P(b * 0.47, b * 0.47);
      case 1: return this.P(-0.1, -0.1);
      case 2: return this.P(b * 1.05, b * 0.15);
      case 3: return this.P(b * 1.15, b * 0.6);
      case 4: return this.P(b * 0.6, b * 1.15);
      case 5: return this.P(b * 0.15, b * 1.05);
      case 6: return at(-30, R * 0.72);
      case 7: return at(0, R * 0.78);
      default: return at(30, R * 0.72);
    }
  }
  private get bat(): number { return this.top ? 1 : 0; }
  private get fld(): number { return this.top ? 0 : 1; }

  warm(dt: number): void {
    // the home side takes the field; the visitors wait to bat
    this.roster[0].forEach((a, i) => { const q = this.fieldSpot(i); toward(a, q.x, q.z, 0.3, dt); });
    this.roster[1].forEach((a, i) => { const q = this.dugout(1, i); toward(a, q.x, q.z, 0.3, dt); });
    const u = this.P(-0.17, -0.17);
    toward(this.ump, u.x, u.z, 0.3, dt);
  }

  step(dt: number): void {
    this.t += dt;
    this.buzz += ((this.pa === 'hr' && this.phase === 'play' ? 1 : this.phase === 'play' ? 0.4 : 0.15) - this.buzz) * Math.min(1, dt * 2);
    for (const a of this.actors) a.hop = 0;
    const F = this.roster[this.fld], B = this.roster[this.bat];
    if (this.phase === 'change') {
      let ready = true;
      F.forEach((a, i) => { const q = this.fieldSpot(i); if (!toward(a, q.x, q.z, 0.6, dt)) ready = false; });
      B.forEach((a, i) => { const q = this.dugout(this.bat, i); if (!toward(a, q.x, q.z, 0.6, dt)) ready = false; });
      const u = this.P(-0.17, -0.17); toward(this.ump, u.x, u.z, 0.5, dt);
      this.ball.shown = false;
      if ((ready && this.t > 0.6) || this.t > 4) this.upToBat();
    } else if (this.phase === 'windup') {
      this.ball.shown = true;
      const m = this.fieldSpot(0);
      this.ball.x = m.x; this.ball.z = m.z; this.ball.y = 0.1;
      this.stand(F, B, dt);
      if (this.t > 0.35) { this.phase = 'pitch'; this.t = 0; }
    } else if (this.phase === 'pitch') {
      const m = this.fieldSpot(0), h = this.P(-0.04, -0.04), u = clamp(this.t / 0.3, 0, 1);
      this.ball.x = m.x + (h.x - m.x) * u; this.ball.z = m.z + (h.z - m.z) * u; this.ball.y = 0.1 - u * 0.03;
      this.stand(F, B, dt);
      if (u >= 1) {
        if (this.pitches > 0) { this.pitches--; this.phase = 'windup'; this.t = -0.25; }
        else this.resolve();
      }
    } else if (this.phase === 'play') {
      this.play(dt);
    } else {
      const win = this.score[0] > this.score[1] ? 0 : this.score[1] > this.score[0] ? 1 : -1;
      if (win >= 0) for (const a of this.roster[win]) a.hop = Math.abs(Math.sin(this.t * 8 + a.z * 9)) * 0.05;
      if (this.t > 5) this.done = true;
    }
  }

  /** Everyone at their stations between pitches: fielders out, the batter at the plate, runners on base. */
  private stand(F: Actor[], B: Actor[], dt: number): void {
    F.forEach((a, i) => { const q = this.fieldSpot(i); toward(a, q.x, q.z, 0.5, dt); });
    const box = this.P(-0.06, 0.05);
    if (this.batter) toward(this.batter, box.x, box.z, 0.5, dt);
    this.bases.forEach((a, n) => { if (a) { const q = this.baseAt(n + 1); toward(a, q.x, q.z, 0.5, dt); } });
    for (const a of B) if (a !== this.batter && !this.bases.includes(a)) { const q = this.dugout(this.bat, B.indexOf(a)); toward(a, q.x, q.z, 0.4, dt); }
  }

  private upToBat(): void {
    const B = this.roster[this.bat];
    // the next in the order who isn't on base
    for (let k = 0; k < 9; k++) {
      const a = B[this.order[this.bat] % 9];
      this.order[this.bat]++;
      if (!this.bases.includes(a)) { this.batter = a; break; }
    }
    const r = this.r();
    this.pa = r < 0.22 ? 'k' : r < 0.3 ? 'bb' : r < 0.51 ? 'go' : r < 0.72 ? 'fo' : r < 0.87 ? '1b' : r < 0.93 ? '2b' : r < 0.945 ? '3b' : 'hr';
    this.pitches = this.r() < 0.35 ? 1 : 0;
    this.phase = 'windup';
    this.t = 0;
  }

  /** The pitch that settles it: the swing, and where the ball goes. */
  private resolve(): void {
    this.phase = 'play';
    this.t = 0;
    this.running = [];
    this.flight = null;
    this.fielder = null;
    this.throwTo = null;
    const F = this.roster[this.fld], bt = this.batter!;
    const deg = (this.r() - 0.5) * 80;
    const at = (d: number, dist: number) => { const a = (d * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a); return { x: this.hx + (this.cf[0] * c - this.cf[1] * s) * dist, z: this.hz + (this.cf[0] * s + this.cf[1] * c) * dist }; };
    const h = this.P(0, 0);
    const advance = (n: number, batterToo: boolean) => {
      // forced or hit home: every runner goes n bases, the batter too
      const moves: { a: Actor; from: number }[] = [];
      for (let b = 2; b >= 0; b--) if (this.bases[b]) moves.push({ a: this.bases[b]!, from: b + 1 });
      if (batterToo) moves.push({ a: bt, from: 0 });
      this.bases = [null, null, null];
      for (const m of moves) {
        const to = Math.min(4, m.from + n);
        const path = [];
        for (let k = m.from + 1; k <= to; k++) path.push(this.baseAt(k));
        this.running.push({ a: m.a, path, to });
        if (to < 4) this.bases[to - 1] = m.a;
      }
    };
    switch (this.pa) {
      case 'k': this.outs++; this.say('Strike three!', `${this.nickOf(this.bat)} batter goes down swinging`); break;
      case 'bb': {
        // a walk moves up only the runners it forces: those with every base behind them filled
        const moves: { a: Actor; from: number }[] = [{ a: bt, from: 0 }];
        for (let n = 0; n < 3 && this.bases[n]; n++) moves.push({ a: this.bases[n]!, from: n + 1 });
        for (const m of moves) if (m.from > 0) this.bases[m.from - 1] = null;
        for (const m of moves) { const to = m.from + 1; this.running.push({ a: m.a, path: [this.baseAt(to)], to }); if (to < 4) this.bases[to - 1] = m.a; }
        break;
      }
      case 'go': {
        const i = 2 + Math.floor(this.r() * 4), f = F[i], spot = { x: f.x + (this.r() - 0.5) * 0.15, z: f.z + (this.r() - 0.5) * 0.15 };
        this.flight = { x0: h.x, z0: h.z, x1: spot.x, z1: spot.z, t0: 0, t1: 0.45, h: 0.02, roll: true };
        this.fielder = f; this.throwTo = this.baseAt(1);
        this.running.push({ a: bt, path: [this.baseAt(1)], to: -1 });
        this.outs++;
        break;
      }
      case 'fo': {
        const i = 2 + Math.floor(this.r() * 7), f = F[Math.min(8, i)], spot = { x: f.x + (this.r() - 0.5) * 0.3, z: f.z + (this.r() - 0.5) * 0.3 };
        this.flight = { x0: h.x, z0: h.z, x1: spot.x, z1: spot.z, t0: 0, t1: 1.1, h: 0.55 };
        this.fielder = f;
        this.running.push({ a: bt, path: [this.baseAt(1)], to: -1 });
        this.outs++;
        break;
      }
      case 'hr': {
        const land = at(deg, this.fence * 1.15);
        this.flight = { x0: h.x, z0: h.z, x1: land.x, z1: land.z, t0: 0, t1: 1.5, h: 1.1 };
        advance(4, true);
        this.cues.push({ t: 'cheer' });
        this.say(`⚾ Home run, ${this.teamOf(this.bat).name}!`, this.line());
        break;
      }
      default: {
        const n = this.pa === '1b' ? 1 : this.pa === '2b' ? 2 : 3;
        const land = at(deg, this.fence * (0.55 + n * 0.12));
        this.flight = { x0: h.x, z0: h.z, x1: land.x, z1: land.z, t0: 0, t1: 0.8 + n * 0.15, h: 0.15 + n * 0.08 };
        const of = F.slice(6).sort((p, q) => Math.hypot(p.x - land.x, p.z - land.z) - Math.hypot(q.x - land.x, q.z - land.z))[0];
        this.fielder = of;
        advance(n, true);
        if (n >= 2) this.say(n === 2 ? 'Double!' : 'Triple!', `${this.nickOf(this.bat)} · ${this.line()}`);
      }
    }
  }

  private play(dt: number): void {
    const T = this.t, F = this.roster[this.fld], B = this.roster[this.bat];
    // the ball: off the bat, then thrown in
    if (this.flight) {
      const fl = this.flight, u = clamp((T - fl.t0) / (fl.t1 - fl.t0), 0, 1);
      this.ball.x = fl.x0 + (fl.x1 - fl.x0) * u; this.ball.z = fl.z0 + (fl.z1 - fl.z0) * u;
      this.ball.y = fl.roll ? 0.03 : 0.06 + Math.sin(u * Math.PI) * fl.h;
      if (u >= 1 && this.fielder && this.throwTo) {
        this.flight = { x0: this.ball.x, z0: this.ball.z, x1: this.throwTo.x, z1: this.throwTo.z, t0: T, t1: T + 0.45, h: 0.08 };
        this.throwTo = null;
      }
    } else if (this.pa === 'k' || this.pa === 'bb') {
      const c = this.P(-0.1, -0.1);
      this.ball.x = c.x; this.ball.z = c.z; this.ball.y = 0.06;
    }
    if (this.fielder && this.flight && (this.pa !== 'hr')) toward(this.fielder, this.flight.x1, this.flight.z1, 0.7, dt);
    // the runners round the bases
    let busy = false;
    for (const run of this.running) {
      const next = run.path[0];
      if (!next) continue;
      busy = true;
      if (toward(run.a, next.x, next.z, this.pa === 'hr' ? 0.55 : 0.9, dt)) run.path.shift();
    }
    if (this.pa === 'hr') for (const a of B) if (!this.running.some((q) => q.a === a)) a.hop = Math.abs(Math.sin(T * 9 + a.x * 7)) * 0.04;
    const minT = this.pa === 'k' || this.pa === 'bb' ? 0.7 : this.pa === 'hr' ? 2.2 : 1.3;
    if (busy || T < minT) return;
    // the play is over: runs in, outs out, the out-made batter back to the bench
    for (const run of this.running) {
      if (run.to === 4) { this.score[this.bat]++; const q = this.dugout(this.bat, B.indexOf(run.a)); run.a.x = q.x; run.a.z = q.z; }
    }
    if (this.running.some((q) => q.to === 4) && this.pa !== 'hr') this.say('Run scores', `${this.teamOf(this.bat).name} · ${this.line()}`);
    if (this.pa === 'k' || this.pa === 'go' || this.pa === 'fo') this.batter = null;
    this.running = [];
    this.flight = null;
    if (this.walkoff()) return;
    if (this.outs >= 3) this.changeSides();
    else this.upToBat();
    void F;
  }

  private walkoff(): boolean {
    if (!this.top && this.inning >= INNINGS && this.score[0] > this.score[1]) { this.end(); return true; }
    return false;
  }

  private changeSides(): void {
    this.outs = 0;
    this.bases = [null, null, null];
    this.batter = null;
    if (this.top) {
      this.top = false;
      if (this.inning >= INNINGS && this.score[0] > this.score[1]) { this.end(); return; }
    } else {
      if (this.inning >= INNINGS && this.score[0] !== this.score[1]) { this.end(); return; }
      if (this.inning >= INNINGS + 2) { this.end(); return; }
      this.top = true;
      this.inning++;
    }
    this.phase = 'change';
    this.t = 0;
  }

  private end(): void {
    this.phase = 'final';
    this.t = 0;
    this.ball.shown = false;
    this.cues.push({ t: 'whistle', final: true });
    const w = this.score[0] > this.score[1] ? this.home : this.score[1] > this.score[0] ? this.away : null;
    this.cues.push({ t: 'say', title: 'Final', body: `${this.line()}${w ? ` · ${w.nick} win` : ' · a tie'}`, end: true });
    if (w === this.home) this.cues.push({ t: 'cheer' });
  }

  private teamOf(s: number) { return s === 0 ? this.home : this.away; }
  private nickOf(s: number) { return this.teamOf(s).nick; }
  private say(title: string, body: string) { this.cues.push({ t: 'say', title, body }); }

  private inningText(): string {
    const n = this.inning, th = n === 1 ? 'st' : n === 2 ? 'nd' : n === 3 ? 'rd' : 'th';
    return `${this.top ? '▲' : '▼'}${n}${th}`;
  }
  strip(): string {
    if (this.phase === 'final') return `<span>⚾ Final: <b>${esc(this.away.nick)}</b> ${this.score[1]} – ${this.score[0]} <b>${esc(this.home.nick)}</b></span>`;
    const on = this.bases.map((b) => (b ? '◆' : '◇')).join('');
    return `<span>⚾ <b>${esc(this.away.nick)}</b> ${this.score[1]} – ${this.score[0]} <b>${esc(this.home.nick)}</b></span><span>${this.inningText()} · ${this.outs} out · ${on}</span>`;
  }
  board(): [string, string] {
    return [`${this.away.abbr} ${this.score[1]}  ${this.home.abbr} ${this.score[0]}`, this.phase === 'final' ? 'FINAL' : `${this.inningText()}  ${this.outs} OUT`];
  }
  line(): string { return `${this.away.nick} ${this.score[1]}–${this.score[0]} ${this.home.nick}`; }
}

// =====================================================================================================
// a concert

const ACT_SHIRTS = [0x1f2329, 0xf4f2ec, 0xe2412f, 0x8e5cc7, 0xf2c14e];
const FAN_SHIRTS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0x3a3f45, 0xd98fb0, 0x1f2329];

export class ConcertSim implements Sim {
  readonly kind = 'concert';
  actors: Actor[] = [];
  ball = null;
  done = false;
  buzz = 0.3;
  cues: Cue[] = [];
  /** The song being played (index into the act's songs; the encore is the last), and how far into it. */
  song = -1;
  songT = 0;
  /** Beats per second of this song, and the beat's phase 0..1. */
  bps = 2;
  beat = 0;
  /** How hard the song is going, 0..1: lights, lasers, fog and the pit follow it. */
  energy = 0;
  /** Seconds left of a pause between songs. */
  gap = 0;
  encore = false;
  private r: Rng;
  private band: Actor[] = [];
  private fans: { a: Actor; ph: number; x: number; z: number }[] = [];
  private lens: number[] = [];
  private t = 0;

  constructor(private p: StadiumPlan, readonly act: Act, seed: number) {
    this.r = mulberry32(seed);
    const s = p.stage;
    // the singer out front, guitar and bass either side, keys and drums at the back
    const spots: [number, number][] = [[0, s.d * 0.35], [-s.w * 0.3, s.d * 0.1], [s.w * 0.3, s.d * 0.1], [s.w * 0.22, -s.d * 0.22], [0, -s.d * 0.28]];
    spots.forEach(([u, v], i) => {
      const a = actor(3, ACT_SHIRTS[i % ACT_SHIRTS.length]);
      const q = this.stagePt(u, v);
      a.x = q.x; a.z = q.z; a.y = 0.12 + (i === 4 ? 0.06 : 0); a.yaw = s.yaw;
      if (i === 0) a.big = true;
      this.band.push(a); this.actors.push(a);
    });
    // the pit: as many fans as the floor holds
    const pit = p.pit, n = Math.round(clamp(pit.len * pit.wid * 36, 50, 240));
    for (let i = 0; i < n; i++) {
      const a = actor(4, FAN_SHIRTS[Math.floor(this.r() * FAN_SHIRTS.length)]);
      // packed tighter toward the stage, and facing it
      const q = fieldPt(pit, this.toStage() * (0.5 - Math.pow(this.r(), 1.6)) * pit.len, (this.r() - 0.5) * pit.wid);
      a.x = q.x; a.z = q.z; a.yaw = Math.atan2(s.x - q.x, s.z - q.z) + (this.r() - 0.5) * 0.5;
      a.hidden = true;
      this.fans.push({ a, ph: this.r() * Math.PI * 2, x: q.x, z: q.z });
      this.actors.push(a);
    }
    this.lens = act.songs.map(() => 13 + this.r() * 5);
  }

  /** Which way along the pit's length the stage lies (+1 or -1). */
  private toStage(): number {
    const s = this.p.stage, pit = this.p.pit;
    return (pit.axis === 'x' ? s.x - pit.cx : s.z - pit.cz) >= 0 ? 1 : -1;
  }
  /** A point on the stage: u across it, v toward the audience. */
  stagePt(u: number, v: number): { x: number; z: number } {
    const s = this.p.stage, c = Math.cos(s.yaw), sn = Math.sin(s.yaw);
    return { x: s.x + u * c + v * sn, z: s.z - u * sn + v * c };
  }

  warm(dt: number): void {
    // the pit fills as the gates open
    this.t += dt;
    const shown = Math.floor(clamp(this.t / 20, 0, 1) * this.fans.length);
    this.fans.forEach((f, i) => { f.a.hidden = i >= shown; });
    this.energy = 0.1;
    this.beat = (this.beat + dt * 1.2) % 1;
  }

  step(dt: number): void {
    for (const f of this.fans) f.a.hidden = false;
    if (this.song < 0) { this.startSong(0); }
    if (this.gap > 0) {
      this.gap -= dt;
      this.energy += (0.15 - this.energy) * Math.min(1, dt * 3);
      this.buzz += (0.7 - this.buzz) * Math.min(1, dt * 3);
      for (const f of this.fans) f.a.hop = Math.abs(Math.sin(this.t * 6 + f.ph)) * 0.02;
      if (this.gap <= 0) {
        const next = this.song + 1;
        if (next >= this.act.songs.length) { this.done = true; return; }
        this.startSong(next);
      }
    } else {
      this.songT += dt;
      const len = this.lens[this.song];
      // verses and choruses: the energy builds, drops, and builds bigger to the end
      const u = this.songT / len;
      const shape = 0.45 + 0.35 * Math.max(0, Math.sin(u * Math.PI * 3 - 0.6)) + 0.2 * u;
      this.energy += (shape - this.energy) * Math.min(1, dt * 2);
      this.buzz += (0.25 + this.energy * 0.5 - this.buzz) * Math.min(1, dt * 2);
      if (this.songT >= len) {
        this.cues.push({ t: 'cheer' });
        const last = this.song === this.act.songs.length - 2;
        this.gap = last ? 6 : 3;
        if (last) { this.encore = true; this.cues.push({ t: 'say', title: `${this.act.name}`, body: 'Encore! Encore!' }); }
      }
    }
    this.t += dt;
    this.beat = (this.beat + dt * this.bps) % 1;
    // the band: everyone moves to the beat, the singer works the front of the stage
    const b = Math.abs(Math.sin(this.beat * Math.PI));
    const s = this.p.stage;
    this.band.forEach((a, i) => {
      if (i === 0) {
        const q = this.stagePt(Math.sin(this.t * 0.35) * s.w * 0.35, s.d * 0.38);
        toward(a, q.x, q.z, 0.25, dt);
        a.yaw = s.yaw + Math.sin(this.t * 0.7) * 0.4;
      }
      a.hop = this.gap > 0 ? 0 : b * (i === 4 ? 0.006 : 0.018) * (0.4 + this.energy);
    });
    // the pit jumps on the beat, the front rows highest
    for (const f of this.fans) {
      f.a.hop = this.gap > 0 ? f.a.hop : Math.max(0, Math.sin(this.beat * Math.PI * 2 + f.ph * 0.25)) * 0.05 * this.energy;
    }
  }

  private startSong(i: number): void {
    this.song = i;
    this.songT = 0;
    this.bps = 1.5 + this.r() * 1.1;
    this.cues.push({ t: 'say', title: `🎤 ${this.act.name}`, body: i === this.act.songs.length - 1 ? `Encore: “${this.act.songs[i]}”` : `“${this.act.songs[i]}”` });
  }

  strip(): string {
    const n = this.act.songs.length;
    const now = this.song < 0 ? 'Doors open' : this.gap > 0 ? (this.encore ? 'Encore…' : 'Between songs') : `“${esc(this.act.songs[this.song])}”`;
    return `<span>🎤 <b>${esc(this.act.name)}</b></span><span>${now}</span><span class="clock">${Math.max(1, this.song + 1)}/${n}</span>`;
  }
  board(): [string, string] {
    return [this.act.name.toUpperCase(), this.song < 0 ? this.act.tour.toUpperCase() : this.act.songs[this.song].toUpperCase()];
  }
  line(): string { return `${this.act.name} · ${this.act.tour}${this.song >= 0 ? ` · song ${this.song + 1} of ${this.act.songs.length}` : ''}`; }
}

/** Play a whole fixture headless, for the gate: the sim and how long it ran, in seconds. */
export function runHeadless(sim: Sim, warm = 24, limit = 900): { secs: number; sim: Sim } {
  const dt = 1 / 30;
  for (let t = 0; t < warm; t += dt) sim.warm(dt);
  let t = 0;
  while (!sim.done && t < limit) { sim.step(dt); t += dt; sim.cues.length = 0; }
  return { secs: t, sim };
}
