import { esc } from './cargoHud';
import { ALL_VEHICLES, type VehicleDef } from './vehicles';
import { topperOf } from './parts';
import { DRESS_KINDS, type DressKind, type Fleet, type Unit } from './fleet';
import { CROWNS, FAMILIES, FAMILY_LABEL, HELD_FAMILIES, HOLDER_TOPPERS, TOPPERS, TOPPER_BY_ID, deedsRecord, earned, toppers, type Topper } from './toppers';
import { CARGO_CROWN_KINDS, CROWN_FLOOR, METAL_ICON, METAL_NAME, crownId, isCrownId } from './crownIds';
import { ARCH_LABEL } from './missions/passport';
import { TreatsTab } from './treatsTab';
import { Turntable } from './techWindow';
import type { CrownRow, GoodsBoardKind } from '../../shared/social';
import { RECORDS, type HolderBoard, type RecordId } from '../../shared/records';

/** A record's or a track trophy's board, in a line: who holds it with what, and this fleet's own. */
function boardLine(id: string, b: HolderBoard): string {
  const rec = /^rk:(high|deep|jump|haul)$/.exec(id)?.[1] as RecordId | undefined;
  const fmt = (v: number) => (rec ? RECORDS[rec].fmt(v) : `${v} record${v === 1 ? '' : 's'}`);
  return `${b.holder ? `${b.holder} · ${fmt(b.top)}` : 'Nobody yet'} · you ${b.you ? fmt(b.you) : 'none'}`;
}
const modelName = (id: string): string => ALL_VEHICLES.find((d) => d.id === id)?.name ?? id;
const boardName = (k: GoodsBoardKind, kind: string): string => (k === 'g' ? kind : k === 'v' ? `${modelName(kind)} Loads` : k === 'e' ? `${modelName(kind)} Earnings` : kind === 'visitor' ? 'the Visitors' : (ARCH_LABEL as Record<string, string>)[kind] ?? kind);
const ordinal = (n: number): string => `${n}${n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] ?? 'th'}`;

/**
 * The HQ window's Treats & Toppers tab (docs/toppers.html, "The Topper Rack"; the user, 6 Nov 2026: the Treats and
 * Toppers tabs as one, so Tech is 9 again, and easier to find your way round). From the top:
 * - Dress the fleet: a square for each kind of vehicle (road, rail, sea, air), each with the fleet's most driven vehicle
 *   of that kind turning on a stand wearing the topper picked for the kind beside it, so a pick is seen at once;
 * - the Passport's treats (game/treatsTab.ts);
 * - the kept toppers by family, then the boards' held ones, and the crowns last (hundreds of cargo boards to scroll).
 * Every topper, treat and crown is one row; in each family the ones kept or held and those nearest come first, and the
 * rest fold under "See more". One vehicle at a time is the Fleet tab's pane (game/unitPane.ts).
 */

const KIND_LABEL: Record<DressKind, string> = { land: 'Road', water: 'Sea', air: 'Air', rail: 'Rail' };
/** The squares' order: road and rail on top, sea and air under them. */
const SQUARES: DressKind[] = ['land', 'rail', 'water', 'air'];
const num = (n: number): string => (n >= 1e6 ? `${+(n / 1e6).toFixed(n >= 1e7 ? 0 : 1)}M` : n >= 1e4 ? `${Math.round(n / 1e3)}k` : n.toLocaleString('en-GB'));
/** How many rows a family shows before the rest fold away, unless more are kept (then up to SHOW_MAX); and the crown boards'. */
const SHOW = 6, SHOW_MAX = 12, CROWNS_SHOWN = 12;
/** The stands' size, CSS pixels. */
const STAGE_W = 168, STAGE_H = 110;

export class ToppersTab {
  readonly el = document.createElement('div');
  /** The Passport's treats, a section of this tab. */
  readonly treats: TreatsTab;
  private head = document.createElement('div');
  private rest = document.createElement('div');
  private headHtml = '';
  private restHtml = '';
  say: (text: string) => void = () => {};
  /** Every podium wanted from the server (net/crownsNet.ts want): asked while the tab is shown. */
  want: () => void = () => {};
  /** Which crowns list is open: cargo, culture, vehicle loads or earnings. */
  private side: GoodsBoardKind = 'g';
  /** Families (and 'crowns') shown whole rather than folded. */
  private open = new Set<string>();
  /** A stand for each kind of vehicle, made the first time the tab is shown and let go when the window shuts. */
  private stands = new Map<DressKind, Turntable>();
  private visible = false;

  constructor(private fleet: Fleet) {
    this.treats = new TreatsTab(fleet);
    this.treats.say = (t) => this.say(t);
    this.el.className = 'hq-treats hq-toppers';
    this.head.className = 'tp-head';
    this.rest.className = 'tp-rest';
    this.el.append(this.head, this.treats.el, this.rest);
    this.el.addEventListener('click', (e) => {
      const more = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-fold]');
      if (more) {
        const k = more.dataset.fold!;
        if (this.open.has(k)) this.open.delete(k); else this.open.add(k);
        this.render(true);
        return;
      }
      const b = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-side]');
      if (!b) return;
      this.side = (['g', 'c', 'v', 'e'] as GoodsBoardKind[]).includes(b.dataset.side as GoodsBoardKind) ? b.dataset.side as GoodsBoardKind : 'g';
      this.render(true);
    });
    this.el.addEventListener('change', (e) => {
      const s = e.target as HTMLSelectElement;
      const kind = s.dataset.dress as DressKind | undefined;
      if (!kind || !DRESS_KINDS.includes(kind)) return;
      const id = s.value || null;
      if (id && !toppers.has(id)) return;
      const n = this.fleet.dressKind(kind, id);
      const t = id ? TOPPER_BY_ID.get(id) : undefined;
      this.say(t ? `${t.icon} ${t.name} on ${n} ${KIND_LABEL[kind].toLowerCase()} vehicle${n === 1 ? '' : 's'}, and on every new one` : `${KIND_LABEL[kind]} vehicles' roofs are bare again`);
      this.render(true);
    });
  }

  /** The tab shown or hidden (the HQ window's show and close): the stands turn only while it is up. */
  setVisible(v: boolean): void {
    if (v === this.visible) return;
    this.visible = v;
    if (v) { this.render(true); return; }
    for (const t of this.stands.values()) t.stop();
    this.stands.clear();
  }

  /** The fleet's most driven vehicle of a kind (tiles at anyone's wheel), or null with none. */
  private mostDriven(kind: DressKind): { u: Unit; def: VehicleDef } | null {
    let best: { u: Unit; def: VehicleDef } | null = null;
    for (const u of this.fleet.units) {
      const def = this.fleet.defFor(u);
      if (def.kind !== kind) continue;
      if (!best || u.log.tiles > best.u.log.tiles) best = { u, def };
    }
    return best;
  }

  render(force = false): void {
    this.want();
    const mine = toppers.owned();
    const picks = SQUARES.map((k) => ({ k, top: this.mostDriven(k), cur: this.fleet.dress[k] ?? '' }));
    const squares = picks.map(({ k, top, cur }) => {
      const t = cur ? TOPPER_BY_ID.get(cur) : undefined;
      const opts = `<option value="">No topper</option>${mine.map((m) => `<option value="${m.id}"${cur === m.id ? ' selected' : ''}>${m.icon} ${esc(m.name)}</option>`).join('')}`;
      return `<div class="tp-sq${top ? '' : ' none'}"><div class="tp-stage" data-stage="${k}">${top ? '' : `<span>No ${KIND_LABEL[k].toLowerCase()} vehicle yet</span>`}</div>`
        + `<div class="tp-pick"><b>${KIND_LABEL[k]}</b>`
        + `<small>${top ? `${esc(top.u.name)}${top.u.name === modelName(top.u.model) ? '' : ` · ${esc(modelName(top.u.model))}`} · ${num(Math.round(top.u.log.tiles))} tiles` : 'New ones will wear it'}</small>`
        + `<select data-dress="${k}"${mine.length ? '' : ' disabled'}>${opts}</select>`
        + `<small class="tp-now">${t ? `${t.icon} ${esc(t.look)}` : mine.length ? 'Pick a topper to see it on the stand' : 'Earn a topper below to wear it'}</small></div></div>`;
    }).join('');
    const kept = mine.filter((t) => !isCrownId(t.id)).length;
    const head = `<div class="tr-lead"><b>${kept} of ${TOPPERS.length}</b> toppers kept${toppers.held.size ? ` · <b>${toppers.held.size}</b> crown${toppers.held.size === 1 ? '' : 's'} held` : ''} · roof ornaments earned over a long career, free to wear and seen by every player; and a treat for every page of your Passport.</div>`
      + `<h4 class="tp-fam">Dress the fleet <small>a topper for every vehicle of a kind, and its new ones · one vehicle at a time from its pane on the Fleet tab</small></h4>`
      + `<div class="tp-grid">${squares}</div>`;
    if (force || head !== this.headHtml) {
      this.headHtml = head;
      this.head.innerHTML = head;
    }
    this.stage(picks);
    this.treats.render(force);

    const fams = FAMILIES.map((f) => {
      const list = TOPPERS.filter((t) => t.family === f);
      const got = list.filter((t) => earned(t)).length;
      return this.family(f, `${FAMILY_LABEL[f]}`, `${got} of ${list.length}`, list, (t) => earned(t));
    }).join('');
    // the boards' other held toppers: worn while the fleet holds a rush board, a challenge line or a range record
    const holders = HELD_FAMILIES.map((f) => {
      const list = HOLDER_TOPPERS.filter((t) => t.family === f);
      const got = list.filter((t) => toppers.has(t.id)).length;
      return this.family(f, FAMILY_LABEL[f], `${got} of ${list.length} held`, list, (t) => toppers.has(t.id), (t) => toppers.boards?.find((b) => b.tp === t.id));
    }).join('');
    // the crowns last: hundreds of cargo boards (the user, 6 Nov 2026)
    const rest = `<h3 class="tp-part">Toppers</h3>${fams}${toppers.known ? holders : ''}${this.crowns()}`;
    if (!force && rest === this.restHtml) return;
    this.restHtml = rest;
    this.rest.innerHTML = rest;
  }

  /** The stands: each kind's vehicle wearing the topper picked for it, turning while the tab is up. */
  private stage(picks: { k: DressKind; top: { u: Unit; def: VehicleDef } | null; cur: string }[]): void {
    if (!this.visible) return;
    for (const { k, top, cur } of picks) {
      const slot = this.head.querySelector<HTMLElement>(`[data-stage="${k}"]`);
      let t = this.stands.get(k);
      if (!top || !slot) { if (t) { t.stop(); this.stands.delete(k); } continue; }
      if (!t) {
        t = new Turntable(STAGE_W, STAGE_H, 'tp-canvas');
        // a train's engine alone, and every stand framed close by its vehicle alone, so a topper never changes the
        // zoom and can be seen (the user, 6 Nov 2026)
        t.railCars = 1;
        t.tight = true;
        this.stands.set(k, t);
      }
      t.show({ ...top.def, topper: cur || undefined }, `${top.u.uid}|${top.def.id}|${cur}`);
      if (!t.running) t.start();
      if (t.canvas.parentElement !== slot) slot.replaceChildren(t.canvas);
    }
  }

  /**
   * A family's rows: kept or held first, then the nearest by progress, then the rest in their own order; the first
   * few shown and the rest under "See more" (all of them once opened).
   */
  private family(key: string, label: string, count: string, list: Topper[], has: (t: Topper) => boolean, board?: (t: Topper) => HolderBoard | undefined): string {
    const share = (t: Topper) => { const [a, b] = t.progress(deedsRecord); return b ? a / b : 0; };
    const order = list.map((t, i) => ({ t, i, has: has(t), p: share(t) })).sort((a, b) => Number(b.has) - Number(a.has) || b.p - a.p || a.i - b.i);
    const got = order.filter((o) => o.has).length;
    const cap = Math.max(SHOW, Math.min(SHOW_MAX, got + 2));
    const open = this.open.has(key);
    const shown = open ? order : order.slice(0, cap);
    const more = order.length > cap ? `<button type="button" class="tr-more" data-fold="${key}">${open ? 'Show fewer ▴' : `See ${order.length - shown.length} more ▾`}</button>` : '';
    return `<h4 class="tp-fam">${label} <small>${count}</small></h4><ul class="tr-list tr-rows">${shown.map((o) => this.row(o.t, board?.(o.t))).join('')}</ul>${more}`;
  }

  /**
   * The crowns: what this fleet holds and its Crown Roll, then one board list at a time (cargo, culture, vehicle loads or
   * earnings), the fleet's own boards first, then the rest by the gold holder's count: each with its gold, silver and
   * bronze, this fleet's count and place, how far it is from a place, and when a podium is due to move.
   */
  private crowns(): string {
    const head = `<h3 class="tp-part">Crowns <small>held by the three fleets that have delivered the most of each cargo, brought home the most of each culture, or delivered and earned the most in each vehicle</small></h3>`;
    if (!toppers.known) return `${head}<p class="tr-foot">Crowns are held online: who wears each is shown once you are signed in.</p>`;
    const rows = toppers.rows ?? [];
    const roll = toppers.roll.length ? `<p class="tr-foot">👑 Crown Roll: ${toppers.roll.map((r) => `${METAL_ICON[r.place]} ${esc(boardName(r.k, r.kind))}`).join(' · ')}</p>` : '';
    const seg = (k: GoodsBoardKind, label: string, n: number) => `<button type="button" data-side="${k}" class="${this.side === k ? 'on' : ''}">${label} · ${n}</button>`;
    const total = (k: GoodsBoardKind) => (k === 'g' ? CARGO_CROWN_KINDS.length : CROWNS.filter((t) => t.family === (k === 'c' ? 'cultureCrown' : k === 'v' ? 'loadsCrown' : 'earnCrown')).length / 3);
    const side = rows.filter((r) => r.k === this.side);
    const held = (r: CrownRow) => r.p.some((h) => h && h.id && toppers.held.has(crownId(r.k, r.kind, r.p.indexOf(h) as 0 | 1 | 2) ?? ''));
    side.sort((a, b) => Number(held(b)) - Number(held(a)) || Number(b.you > 0) - Number(a.you > 0) || (a.you > 0 && b.you > 0 ? a.place - b.place : 0) || (b.p[0]?.n ?? 0) - (a.p[0]?.n ?? 0));
    // the fleet's own boards always show; the rest fold after the first few
    const own = side.filter((r) => held(r) || r.you > 0).length;
    const cap = Math.max(CROWNS_SHOWN, Math.min(40, own));
    const open = this.open.has(`crowns:${this.side}`);
    const shown = open ? side : side.slice(0, cap);
    const list = shown.map((r) => this.crownRow(r)).join('');
    const claimed = side.filter((r) => r.p[0]).length;
    const more = side.length > cap ? `<button type="button" class="tr-more" data-fold="crowns:${this.side}">${open ? 'Show fewer ▴' : `See ${side.length - shown.length} more boards ▾`}</button>` : '';
    return `${head}${roll}<div class="tp-dress tr-seg">${seg('g', 'Cargo', total('g'))}${seg('c', 'Culture', total('c'))}${seg('v', 'Vehicle loads', total('v'))}${seg('e', 'Vehicle earnings', total('e'))}<small>${claimed} gold crown${claimed === 1 ? '' : 's'} worn · ${total(this.side) - claimed} unclaimed</small></div>`
      + (rows.length ? `<ul class="tr-list tr-rows">${list}</ul>${more}` : '<p class="tr-foot">Asking the server…</p>');
  }

  private crownRow(r: CrownRow): string {
    const floor = CROWN_FLOOR[r.k];
    const mineAt = r.p.findIndex((_, i) => toppers.held.has(crownId(r.k, r.kind, i as 0 | 1 | 2) ?? ''));
    const icon = TOPPER_BY_ID.get(crownId(r.k, r.kind, 0) ?? '')?.icon ?? '👑';
    const pod = r.p.map((h, i) => `${METAL_ICON[i]} ${h ? `${esc(h.name)} ${num(h.n)}` : '—'}`).join(' · ');
    let you: string;
    if (mineAt >= 0) you = `You hold ${METAL_NAME[mineAt].toLowerCase()} · ${num(r.you)}`;
    else if (r.you > 0) {
      // the nearest place above: the one this count would take, its holder's count and the floor both to beat
      const target = Math.min(2, Math.max(0, r.place - 1));
      const need = Math.max(floor[target], (r.p[target]?.n ?? 0) + 1) - r.you;
      you = `You ${num(r.you)} · ${ordinal(r.place)}${need > 0 ? ` · ${num(need)} to ${METAL_NAME[target].toLowerCase()}` : ''}`;
    } else you = `${num(floor[2])} for bronze`;
    const due = r.due ? ` · moves in ${Math.max(1, Math.round((r.due - Date.now()) / 3600000))}h` : '';
    return `<li class="tr-row${mineAt >= 0 ? ' got' : ''}" title="${esc(pod)}"><span class="tr-icon">${icon}</span>`
      + `<span class="tr-name"><b>Crown of ${esc(boardName(r.k, r.kind))}</b><small>${you}${due}</small></span>`
      + `<span class="tr-mid"><small class="tr-what">${pod}</small></span>`
      + `<em>${mineAt >= 0 ? METAL_ICON[mineAt] : ''}</em></li>`;
  }

  private row(t: Topper, board?: HolderBoard): string {
    const held = isCrownId(t.id), has = held ? toppers.has(t.id) : earned(t);
    const [a, b] = t.progress(deedsRecord);
    const pct = b ? Math.min(100, Math.round((a / b) * 100)) : 0;
    const wearing = this.fleet.units.filter((u) => topperOf(u.parts) === t.id).length;
    const mid = board ? `<small class="tr-what">${esc(boardLine(t.id, board))}</small>`
      : has || held ? `<small class="tr-what">${esc(t.look)}</small>`
      : `<span class="tr-bar"><i style="width:${pct}%"></i></span>`;
    return `<li class="tr-row${has ? ' got' : ''}" title="${esc(t.look)}"><span class="tr-icon">${t.icon}</span>`
      + `<span class="tr-name"><b>${esc(t.name)}</b><small>${esc(t.how)}${b > 1 ? ` · ${num(a)}/${num(b)}` : ''}</small></span>`
      + `<span class="tr-mid">${mid}</span>`
      + `<em>${has ? (wearing ? `On ${wearing}` : held ? 'Held' : 'Kept') : held ? 'Not held' : `${pct}%`}</em></li>`;
  }
}
