import * as THREE from 'three';

/**
 * The four camera pitches P cycles through, in degrees down from the horizontal. 3 is the game's own
 * view, the one every new game starts on. 4 puts the horizon 5/6 of the way up the screen: with an 18° field of view that is
 * atan(2/3 · tan 9°) ≈ 6°. 1 is all but straight down, a couple of degrees off so the view still turns.
 */
export const PITCHES = [
  { deg: 88, label: 'overhead' },
  { deg: 52, label: 'high' },
  { deg: 32, label: 'standard' },
  { deg: 6, label: 'horizon' },
] as const;
/** Which pitch the game starts on: 3, the standard view. */
export const DEFAULT_PITCH = 2;
/** The fixed zoom levels + and − step through, nearest to farthest. */
export const ZOOM_STEPS = 8;
/**
 * How far in a new player's camera starts, from fully out (0) to fully in (1): the first road on the loading screen and the
 * first drive in the world alike (the user, 8 Nov 2026). On the zoom steps' own ratio scale (zoomTo).
 */
export const FIRST_DRIVE_ZOOM = 0.8;

/** The pitch that lies along the horizon, and may be zoomed right in on the vehicle. */
const HORIZON_PITCH = 3;

export class FollowCamera {
  yaw = 0;
  pitch = THREE.MathUtils.degToRad(PITCHES[DEFAULT_PITCH].deg);
  /** The index into PITCHES the camera is on. */
  pitchLevel: number = DEFAULT_PITCH;
  /**
   * The ground's height under a point in world units, when known: a low camera is kept above the
   * hills behind the car rather than looking out from inside one.
   */
  groundAt: ((x: number, z: number) => number | null) | null = null;
  dist = 70;
  maxDist = 140;
  /**
   * How near the camera may come, when a tool has not set its own. The horizon pitch is a chase
   * camera, and a chase camera wants to sit a few lengths behind the vehicle; the others look down and
   * would only see the roof.
   */
  get minDist(): number { return this.nearLimit ?? (this.pitchLevel === HORIZON_PITCH ? 6 : 20); }
  set minDist(v: number) { this.nearLimit = v === 20 ? null : v; }
  private nearLimit: number | null = null;
  target = new THREE.Vector3();
  private initialised = false;

  constructor(public camera: THREE.PerspectiveCamera) {}

  reset(carHeading: number): void { this.yaw = carHeading + Math.PI; }

  /**
   * One of ZOOM_STEPS fixed zoom levels in (dir −1) or out (+1), evenly spread (by ratio) from as near as
   * the camera may come to as far as it may go: + and − on the keyboard. From between two levels it goes
   * to the next one that way; the camera eases there as it does from the wheel.
   */
  zoomStep(dir: 1 | -1): void {
    const lo = this.minDist, hi = this.maxDist, n = ZOOM_STEPS - 1;
    const level = (d: number) => lo * Math.pow(hi / lo, d / n);
    const at = Math.log(this.dist / lo) / Math.log(hi / lo) * n;
    const next = dir > 0 ? Math.floor(at + 1e-3) + 1 : Math.ceil(at - 1e-3) - 1;
    this.dist = THREE.MathUtils.clamp(level(Math.max(0, Math.min(n, next))), lo, hi);
  }

  /**
   * `f` of the way in from as far out as the camera may go (0) to as near as it may come (1), on the ratio scale the zoom
   * steps and the wheel use; the camera eases there.
   */
  zoomTo(f: number): void {
    const lo = this.minDist, hi = this.maxDist;
    this.dist = hi * Math.pow(lo / hi, THREE.MathUtils.clamp(f, 0, 1));
  }

  /** Go to a pitch level (0..3); the camera eases there. */
  setPitchLevel(level: number): void {
    this.pitchLevel = ((level % PITCHES.length) + PITCHES.length) % PITCHES.length;
    this.pitch = THREE.MathUtils.degToRad(PITCHES[this.pitchLevel].deg);
    // zoomed in along the horizon and then tilted up: back out to where the other pitches begin
    this.dist = THREE.MathUtils.clamp(this.dist, this.minDist, this.maxDist);
  }

  /**
   * Locked to the vehicle (R): the camera swings round after the vehicle whichever way it turns,
   * until R frees it again. Turning it by hand (Q, E, a right-drag or the pad's stick) while locked is a
   * look round, not a release (the user, 5 Nov 2026): it stays where it was turned for LOOK_HOLD seconds
   * after the last turn, then eases back behind the vehicle. Only R leaves it where it was turned to.
   */
  get locked(): boolean { return this.isLocked; }
  set locked(on: boolean) {
    // locking (R) starts straight behind the vehicle
    if (on && !this.isLocked) { this.lockAngle = 0; this.lookHold = 0; }
    this.isLocked = on;
  }
  /** Seconds a look round by hand holds, while locked, before the camera eases back behind the vehicle. */
  private static readonly LOOK_HOLD = 5;
  /** Seconds left of the look round in hand; 0 when the lock is chasing. */
  private lookHold = 0;
  private isLocked = false;
  /** Where a locked camera sits round the vehicle, in radians from straight behind it. */
  lockAngle = 0;
  /** How quickly a locked camera catches up with a turn, per second. */
  private static readonly CHASE = 4;

  /** Whole-island view for orientation; toggled with M. */
  overview = false;
  /** How far back the overview pulls: one island, or the whole neighbourhood. */
  overviewDist = 900;
  private overviewCenter = new THREE.Vector3();
  private curDist = 70;
  /** A share the camera stands further back by, for a moment (nitrous); eased in and out by update. */
  pull = 0;
  private curPitch = THREE.MathUtils.degToRad(52);

  setOverviewCenter(x: number, z: number): void { this.overviewCenter.set(x, 0, z); }

  /** How much a knock moves the view, from the settings: 1 full, 0.5 gentle, 0 off. */
  shakeScale = 1;
  /** The jolt: a sprung offset and its velocity, in fractions of the camera distance. */
  private jolt = new THREE.Vector3();
  private joltV = new THREE.Vector3();
  /** Rattle left over from a knock, 0..1; the shake goes as its square, so small knocks barely show. */
  private trauma = 0;
  private shakeT = 0;
  private offset = new THREE.Vector3();
  private look = new THREE.Vector3();

  /**
   * A knock. The view is shoved along (dx, dz), the way the vehicle was going when it hit, and
   * springs back; a hard enough one rattles it for a moment too.
   */
  kick(dx: number, dz: number, strength: number, rattle = true): void {
    const k = strength * this.shakeScale;
    if (k <= 0) return;
    this.joltV.x += dx * k * 0.11;
    this.joltV.z += dz * k * 0.11;
    this.joltV.y -= k * 0.05;
    if (rattle) this.trauma = Math.min(1, this.trauma + k * 0.7);
  }

  /** `heading` is the vehicle's, when the camera is following it; a locked camera chases it. */
  update(dt: number, carPos: THREE.Vector3, orbit: number, dragDX: number, wheel: number, heading?: number): void {
    if (!this.initialised) { this.target.copy(carPos); this.initialised = true; }
    if (this.locked && heading !== undefined && !this.overview) {
      // turned by hand while locked: a look round, held a few seconds after the last turn, then back behind
      const turn = orbit * THREE.MathUtils.degToRad(90) * dt - dragDX * 0.005;
      if (turn) {
        this.yaw += turn;
        this.lookHold = FollowCamera.LOOK_HOLD;
      } else if (this.lookHold > 0) {
        this.lookHold = Math.max(0, this.lookHold - dt);
      } else {
        const want = heading + Math.PI + this.lockAngle;
        const diff = Math.atan2(Math.sin(want - this.yaw), Math.cos(want - this.yaw));
        this.yaw += diff * (1 - Math.exp(-dt * FollowCamera.CHASE));
      }
    } else {
      this.yaw += orbit * THREE.MathUtils.degToRad(90) * dt;
      this.yaw -= dragDX * 0.005;
    }
    this.dist = THREE.MathUtils.clamp(this.dist * Math.exp(wheel * 0.0012), this.minDist, this.maxDist);

    const k = 1 - Math.exp(-dt * 6);
    const wantDist = this.overview ? this.overviewDist : this.dist * (1 + this.pull);
    const wantPitch = this.overview ? THREE.MathUtils.degToRad(64) : this.pitch;
    const ks = 1 - Math.exp(-dt * 3);
    this.curDist += (wantDist - this.curDist) * ks;
    this.curPitch += (wantPitch - this.curPitch) * ks;
    this.target.lerp(this.overview ? this.overviewCenter : carPos, this.overview ? ks : k);

    // the jolt springs back (slightly underdamped, so it settles with one small overshoot) and the rattle fades
    const K = 170, C = 16;
    const jd = Math.min(dt, 1 / 30);
    this.joltV.addScaledVector(this.jolt, -K * jd).multiplyScalar(Math.max(0, 1 - C * jd));
    this.jolt.addScaledVector(this.joltV, jd);
    this.trauma = Math.max(0, this.trauma - dt * 2.5);
    this.shakeT += dt;
    const t = this.shakeT, r = this.trauma * this.trauma * 0.004;
    this.offset.set(
      this.jolt.x + r * (Math.sin(t * 41.3) + 0.6 * Math.sin(t * 27.1 + 1.3)),
      this.jolt.y + r * 0.6 * (Math.sin(t * 36.7 + 2.1) + 0.5 * Math.sin(t * 19.9)),
      this.jolt.z + r * (Math.sin(t * 38.9 + 0.7) + 0.6 * Math.sin(t * 23.3 + 2.9)),
    ).multiplyScalar(this.overview ? 0 : this.curDist);

    const cp = Math.cos(this.curPitch), sp = Math.sin(this.curPitch);
    this.camera.position.set(
      this.target.x + Math.sin(this.yaw) * cp * this.curDist,
      this.target.y + sp * this.curDist,
      this.target.z + Math.cos(this.yaw) * cp * this.curDist,
    ).add(this.offset);
    // a low pitch puts the camera near the ground: keep it clear of a hill behind the car
    if (this.groundAt && !this.overview) {
      const g = this.groundAt(this.camera.position.x, this.camera.position.z);
      // close in the camera may sit lower, so a chase view is a chase view rather than a look down the bonnet
      const clear = this.curDist < 14 ? 0.9 : 2.5;
      if (g !== null && this.camera.position.y < g + clear) this.camera.position.y = g + clear;
    }
    this.camera.lookAt(this.look.copy(this.target).add(this.offset));
  }

  /**
   * Put the camera exactly here, for the title reel's director. The follow state is set to match,
   * so when play takes over the camera eases from this pose into the follow pose rather than cutting.
   */
  pose(yaw: number, pitch: number, dist: number, target: THREE.Vector3): void {
    this.yaw = yaw;
    this.curPitch = pitch;
    this.curDist = dist;
    this.target.copy(target);
    this.initialised = true;
    const cp = Math.cos(pitch), sp = Math.sin(pitch);
    this.camera.position.set(target.x + Math.sin(yaw) * cp * dist, target.y + sp * dist, target.z + Math.cos(yaw) * cp * dist);
    this.camera.lookAt(target);
  }

  /** Horizontal unit vector from camera toward target. */
  forwardXZ(out: THREE.Vector2): THREE.Vector2 {
    return out.set(-Math.sin(this.yaw), -Math.cos(this.yaw));
  }
}
