import * as THREE from 'three';
import { N, CHUNK, CHUNKS, STEP, World } from '../world/tiles';
import { buildChunk, buildFallChunk, buildIslandLod, buildIslandLodSteps, buildLodRails, lodShowChunks } from './mesher';
import { buildBuildings, buildChunkCrops, buildChunkProps, fencePlacement, placementMatrix, propsOn, type Placement, type PropGeometries } from './props';
import { buildFarTown } from './farTown';
import { slumps, type FenceKind } from '../world/fences';
import { buildRoadChunk } from './roadMesh';
import { buildJumpChunk } from './jumps';
import { buildInterstateSignChunk } from './interstateSigns';
import { drawing, townChunkSteps } from './townMesh';
import { buildLampChunk } from './lamps';
import { buildBridgeChunk } from './bridges';
import { buildRailChunk } from './railMesh';
import { buildRailBridgeChunk, forgetRailChunk } from './railBridges';

/**
 * Tiles from the camera's focus within which chunks are built at full detail when nothing is known
 * about the camera (the title reel's warm-up, a console `look`). With a camera the plan is its view:
 * every chunk whose box the widened frustum touches within FAR tiles of the focus, plus a small CORE
 * disc immediately round the focus (the vehicle's own few chunks) so a snap turn or a pitch change
 * never opens on a hole in the ground it stands on while the next chunk streams in. Everything else,
 * behind the camera included, is only built when the view actually reaches it — that is the point:
 * an orbit or a zoom now changes what gets drawn, not just how much.
 */
const NEAR = 112;
const CORE = 20;
const FAR_FULL = 184;
let FAR = FAR_FULL;
/**
 * The share of the full-detail distance in use (render/quality.ts: less at Low and Lowest, 11 Nov 2026 perf
 * audit). Fewer chunks drawn in detail is fewer objects for three to walk every frame; the low-detail blocks
 * stand in beyond it, as they always do past FAR.
 */
export function setChunkReach(k: number): void { FAR = Math.round(FAR_FULL * Math.max(0.5, Math.min(1, k))); }
/**
 * How far, in world units, the frustum's own six planes are pushed outward before a chunk counts as in
 * view (build) or worth keeping (don't drop yet). This is a *fixed* offset applied to each plane, not a
 * percentage: since the side planes converge toward the camera, the same offset dilates the cross-section
 * far more, relatively, near the apex than far from it — camped down small, or a tightly zoomed-in camera
 * (whose true cone is narrow close to the lens) would end up keeping almost anything nearby regardless of
 * where it is actually looking, which is exactly the waste this is meant to avoid.
 */
const VIEW_PAD = 6, KEEP_PAD = 16;
/** Extra distance a chunk keeps its detail before it is thrown away, so the edge doesn't flicker. */
const HYSTERESIS = 24;
/** Tiles from the focus within which a field's crops stand; beyond it the field's colour carries it. */
const CROP_NEAR = 64;
/**
 * Tiles from the focus within which trees, rocks and crops throw shadows. Further out they are a pixel
 * or two, in the tilt-shift's blur, yet each chunk's trees were a shadow draw of thousands of triangles.
 */
const PROP_SHADOW_NEAR = 60;
/** Chunks per side of one low-detail block: each of its chunks is left out of it while that chunk's detail is drawn. */
const BLOCK = 4;
const BLOCKS = CHUNKS / BLOCK;
/**
 * Chunks per island kept, out of the scene, after the view has left them: an orbit or a zoom swings
 * the view across the same few dozen chunks again and again, and building one again from scratch
 * (a city block's worth of buildings) can take longer than a frame. Oldest are let go first.
 */
const SPARE = 96;

/**
 * Called with every freshly built chunk and island block (main.ts compiles their shaders): a program
 * first met on screen stalls that frame while the driver builds it, a quarter to half a second on
 * Windows, and a chunk is usually built before the camera turns to it.
 */
let warmHook: ((parts: THREE.Object3D[]) => Promise<unknown> | null) | null = null;

/** Milliseconds spent building chunks, by part, since the page loaded (pr.stream.cost). */
export const CHUNK_COST = new Map<string, number>();
/**
 * The same for the frame being run, cleared by main.ts at each frame's start: a freeze in the play reports
 * names the step that made it (net/perfField.ts Hitch.steps, 7 Nov 2026), not just "chunks". A rebuild after an
 * edit is named `rebuild: <step>`, an island let go `let go`, chunks dropped from view `drop`.
 */
export const FRAME_STEPS = new Map<string, number>();
/** The longest single step of each kind since the page loaded (pr.stream.max): what a frame can't split. */
const STEP_MAX = new Map<string, number>();
function spent(name: string, ms: number, total = true, detail = name): void {
  if (total) CHUNK_COST.set(name, (CHUNK_COST.get(name) ?? 0) + ms);
  FRAME_STEPS.set(detail, (FRAME_STEPS.get(detail) ?? 0) + ms);
  if (ms > (STEP_MAX.get(detail) ?? 0)) STEP_MAX.set(detail, ms);
}

/** How many trees stand on a tile, for the coarse ground's colour and bulk (mesher.ts buildIslandLod). */
const treesOn = (w: World) => (x: number, z: number): number => propsOn(w, x, z).trees;

/**
 * Spare chunks kept across every island together, oldest first (11 Nov 2026 perf audit): SPARE is per island,
 * and with nine or more islands drawn round a spread-out fleet up to ~860 built chunks were held off the scene,
 * thousands of geometries and hundreds of MB. Past SPARE_ALL the oldest anywhere is let go.
 */
const SPARE_ALL = 160;
const spareLru = new Map<string, { v: View; k: number }>();
let viewIds = 0;

/** One island in the scene: its coarse blocks, whichever detailed chunks are near, and its POIs. */
class View {
  private readonly id = ++viewIds;
  /** Keep a spare chunk, in this island's list and the shared one, letting the oldest go past either cap. */
  private keepSpare(k: number, parts: THREE.Object3D[]): void {
    this.spare.set(k, { parts, rev: this.w.revision });
    spareLru.delete(`${this.id}:${k}`);
    spareLru.set(`${this.id}:${k}`, { v: this, k });
    for (const old of this.spare.keys()) {
      if (this.spare.size <= SPARE) break;
      this.forgetSpare(old);
    }
    for (const { v, k: ok } of spareLru.values()) {
      if (spareLru.size <= SPARE_ALL) break;
      v.forgetSpare(ok);
    }
  }
  /** A spare chunk taken back (or let go): out of both lists. */
  private takeSpare(k: number): { parts: THREE.Object3D[]; rev: number } | undefined {
    const s = this.spare.get(k);
    if (!s) return undefined;
    this.spare.delete(k);
    spareLru.delete(`${this.id}:${k}`);
    return s;
  }
  readonly group = new THREE.Group();
  readonly chunks = new Map<number, THREE.Object3D[]>();
  /** Chunks the view has left, still built, oldest first, with the island revision they were built at. */
  private spare = new Map<number, { parts: THREE.Object3D[]; rev: number }>();
  private lod: (THREE.Mesh | null)[] = [];
  /** Per block, a bit per chunk (row order within the block) whose detail is drawn, so the block leaves it out. */
  private lodIn = new Uint16Array(BLOCKS * BLOCKS);
  /** Per block, its buildings from afar as plain boxes (render/farTown.ts), left out chunk by chunk as the ground is. */
  private lodTown: (THREE.Mesh | null)[] = [];
  /** The distant railway, a chunk at a time, each hidden while its own chunk's track is drawn. */
  private lodRails: (THREE.Mesh | null)[] = [];
  private pois: THREE.Group | null = null;

  /**
   * The island's base, built a step at a time by Stream.update rather than all at once as it arrives (that was a
   * 15–25 ms task in the worker's message, a dropped frame per county): the coarse blocks, the distant railway and
   * the POIs. Null once all are in.
   */
  private base: Generator<string, void> | null;

  constructor(readonly w: World, private geos: PropGeometries) {
    this.group.position.set(w.ox, 0, w.oz);
    this.lod = new Array<THREE.Mesh | null>(BLOCKS * BLOCKS).fill(null);
    this.lodTown = new Array<THREE.Mesh | null>(BLOCKS * BLOCKS).fill(null);
    this.lodRails = new Array<THREE.Mesh | null>(CHUNKS * CHUNKS).fill(null);
    this.base = this.baseSteps();
  }

  private *baseSteps(): Generator<string, void> {
    const w = this.w, made: THREE.Object3D[] = [];
    for (let b = 0; b < BLOCKS * BLOCKS; b++) {
      const bx = b % BLOCKS, bz = (b - bx) / BLOCKS;
      const steps = buildIslandLodSteps(w, bx * BLOCK * CHUNK, bz * BLOCK * CHUNK, (bx + 1) * BLOCK * CHUNK, (bz + 1) * BLOCK * CHUNK, treesOn(w));
      let r = steps.next();
      while (!r.done) { yield 'lod'; r = steps.next(); }
      const m = r.value;
      this.lod[b] = m;
      if (m) {
        m.name ||= 'lod';
        // chunks drawn in full before their block came in: the block leaves them out
        if (this.lodIn[b]) lodShowChunks(m, (k) => !(this.lodIn[b] & (1 << k)));
        this.place(m);
        made.push(m);
      }
      yield 'lod';
    }
    for (let b = 0; b < BLOCKS * BLOCKS; b++) {
      const m = this.farTown(b);
      if (m) made.push(m);
      yield 'lod town';
    }
    for (let k = 0; k < CHUNKS * CHUNKS; k++) {
      const cx = k % CHUNKS, cz = (k - cx) / CHUNKS;
      const m = buildLodRails(w, cx * CHUNK, cz * CHUNK, (cx + 1) * CHUNK, (cz + 1) * CHUNK);
      this.lodRails[k] = m;
      if (m) {
        m.name ||= 'lod rails';
        m.visible = !this.chunks.has(k);
        this.place(m);
        made.push(m);
      }
      if (k % 16 === 15) yield 'lod rails';
    }
    this.pois = buildBuildings(w, this.geos);
    this.pois.name ||= 'buildings';
    this.place(this.pois);
    made.push(this.pois);
    yield 'pois';
    warmHook?.(made);
  }

  /** Block b's distant buildings, built (again) and in the scene; whatever stood for them before is let go. */
  private farTown(b: number): THREE.Mesh | null {
    const old = this.lodTown[b];
    if (old) { this.group.remove(old); old.geometry.dispose(); (old.userData.lights as THREE.Mesh | undefined)?.geometry.dispose(); }
    const bx = b % BLOCKS, bz = (b - bx) / BLOCKS;
    const m = buildFarTown(this.w, bx * BLOCK * CHUNK, bz * BLOCK * CHUNK, (bx + 1) * BLOCK * CHUNK, (bz + 1) * BLOCK * CHUNK);
    this.lodTown[b] = m;
    if (m) {
      m.name ||= 'lod town';
      lodShowChunks(m, (k) => !(this.lodIn[b] & (1 << k)));
      this.place(m);
    }
    return m;
  }

  /**
   * Into the island's group with its matrices worked out once, as a chunk's are (attach, freezeStatic): the coarse
   * blocks, the distant railway and the POIs never move, and left live they were recomposed every frame (nine
   * islands of them, a good share of the frame's matrix walk).
   */
  private place(o: THREE.Object3D): void {
    this.group.add(o);
    o.updateWorldMatrix(true, true);
    freezeStatic(o);
  }

  /** Whether the island's base (coarse blocks, distant railway, POIs) is all in. */
  get based(): boolean { return !this.base; }

  /** Build the base until `until` (at least one step): true once it is all in. */
  baseSome(until: number): boolean {
    if (!this.base) return true;
    let t = performance.now();
    for (;;) {
      const r = this.base.next();
      const n = performance.now();
      if (!r.done) spent(r.value, n - t);
      t = n;
      if (r.done) { this.base = null; return true; }
      if (n >= until) return false;
    }
  }

  /**
   * Chunks built whose new shaders the driver is still compiling: kept out of the scene until they
   * are ready, so their first frame doesn't stall waiting for them. `crops` is what showCrops last said.
   */
  private pending = new Map<number, { parts: THREE.Object3D[]; crops: boolean; shadows: boolean }>();

  hasChunk(k: number): boolean { return this.chunks.has(k) || this.pending.has(k); }

  /**
   * Each chunk's ground in island tiles (x0, z0, x1, z1), grown to take in every building it draws: a
   * building belongs to the chunk its middle is in, so a big lot (a circuit, a wonder) seen only in part
   * must still load that chunk. Worked out again when the island changes.
   */
  private reachRev = -1;
  private reach = new Float32Array(0);
  extent(k: number): Float32Array {
    const w = this.w;
    if (this.reachRev !== w.revision) {
      this.reachRev = w.revision;
      const r = new Float32Array(CHUNKS * CHUNKS * 4);
      for (let c = 0; c < CHUNKS * CHUNKS; c++) {
        const cx = c % CHUNKS, cz = (c - cx) / CHUNKS;
        r.set([cx * CHUNK, cz * CHUNK, (cx + 1) * CHUNK, (cz + 1) * CHUNK], c * 4);
      }
      for (const b of w.allBuildings) {
        if (b.gone || (b.w <= 4 && b.d <= 4)) continue;
        const cx = Math.min(CHUNKS - 1, Math.max(0, Math.floor((b.x + b.w / 2) / CHUNK))), cz = Math.min(CHUNKS - 1, Math.max(0, Math.floor((b.z + b.d / 2) / CHUNK)));
        const i = (cz * CHUNKS + cx) * 4;
        r[i] = Math.min(r[i], b.x); r[i + 1] = Math.min(r[i + 1], b.z);
        r[i + 2] = Math.max(r[i + 2], b.x + b.w); r[i + 3] = Math.max(r[i + 3], b.z + b.d);
      }
      this.reach = r;
    }
    return this.reach.subarray(k * 4, k * 4 + 4);
  }

  /** Show or hide a loaded chunk's crops. */
  /** Trees, rocks and crops of a loaded chunk throwing shadows or not (PROP_SHADOW_NEAR). */
  propShadows(k: number, on: boolean): void {
    const wait = this.pending.get(k);
    if (wait) { wait.shadows = on; return; }
    for (const p of this.chunks.get(k) ?? []) {
      if (p.name !== 'props' && p.name !== 'crops') continue;
      // the kinds that never cast keep it that way (props.ts NO_SHADOW): remember who did
      for (const c of p.children) {
        if (c.userData.casts === undefined) c.userData.casts = c.castShadow;
        c.castShadow = on && c.userData.casts;
      }
    }
  }

  showCrops(k: number, on: boolean): void {
    const wait = this.pending.get(k);
    if (wait) { wait.crops = on; return; }
    const crops = this.chunks.get(k)?.find((p) => p.name === 'crops');
    if (crops) crops.visible = on;
  }

  /**
   * The chunk being built a step at a time (buildSome), and its meshes so far. One at a time per island; the
   * streamer keeps it at the front of its queue so a replan doesn't throw the work away.
   */
  private making: { k: number; steps: Generator<string, void>; parts: THREE.Object3D[] } | null = null;

  /** The chunk this island is part way through building, if any. */
  get makingChunk(): number { return this.making?.k ?? -1; }

  /** A chunk's meshes, a part at a time and its town a building at a time, each step named for pr.stream.cost. */
  private *steps(k: number, parts: THREE.Object3D[]): Generator<string, void> {
    const w = this.w, cx = k % CHUNKS, cz = (k - cx) / CHUNKS;
    // each part named after its step, so a frame's draws can be told apart (pr.stream, profiling)
    const add = (m: THREE.Object3D | null, name: string) => { if (m) { m.name ||= name; parts.push(m); } };
    const { terrain, water } = buildChunk(w, cx, cz);
    terrain.name ||= 'terrain';
    parts.push(terrain);
    if (water) { water.name ||= 'water'; parts.push(water); }
    yield 'ground';
    add(buildChunkProps(w, this.geos, cx, cz), 'props');
    yield 'props';
    add(buildChunkCrops(w, this.geos, cx, cz), 'crops');
    yield 'crops';
    add(buildRoadChunk(w, cx, cz), 'roads');
    yield 'roads';
    const town = townChunkSteps(w, cx, cz);
    for (let r = town.next(); ; r = town.next()) {
      if (r.done) { add(r.value, 'town'); break; }
      yield 'town';
    }
    yield 'town';
    add(buildLampChunk(w, cx, cz), 'lamps');
    yield 'lamps';
    add(buildBridgeChunk(w, cx, cz), 'bridges');
    yield 'bridges';
    add(buildRailChunk(w, cx, cz), 'rail');
    yield 'rail';
    add(buildRailBridgeChunk(w, cx, cz), 'railBridges');
    yield 'railBridges';
    add(buildFallChunk(w, cx, cz), 'falls');
    yield 'falls';
    add(buildJumpChunk(w, cx, cz), 'jumps');
    yield 'jumps';
    add(buildInterstateSignChunk(w, cx, cz), 'signs');
    yield 'signs';
  }

  /** A chunk kept from before (SPARE) put back, if it is still current: true if it was. */
  private reuse(k: number): boolean {
    const kept = this.takeSpare(k);
    if (!kept) return false;
    const cx = k % CHUNKS, cz = (k - cx) / CHUNKS;
    if (kept.rev === this.w.revision) { this.attach(k, cx, cz, kept.parts); return true; }
    for (const p of kept.parts) disposeTree(p);
    return false;
  }

  /** The chunk part way through building, thrown away (it is no longer wanted, or its ground changed). */
  abandon(): void {
    const m = this.making;
    if (!m) return;
    this.making = null;
    m.steps.return(undefined);
    for (const p of m.parts) disposeTree(p);
  }

  /**
   * Build chunk k until `until` (always at least one step): true once it is built, or was already. A chunk that
   * doesn't fit in a frame's budget carries on next frame from where it stopped, so no single frame pays for a
   * whole dense chunk (30–85 ms in a city).
   */
  buildSome(k: number, until: number): boolean {
    if (this.chunks.has(k) || this.pending.has(k)) return true;
    let m = this.making;
    if (m && m.k !== k) { this.abandon(); m = null; }
    if (!m) {
      if (this.reuse(k)) return true;
      const parts: THREE.Object3D[] = [];
      m = this.making = { k, steps: this.steps(k, parts), parts };
    }
    let t = performance.now();
    for (;;) {
      const r = m.steps.next();
      const n = performance.now();
      // a town step named for what it drew (a fairground, the merge), for the reports' freezes and pr.stream.max
      if (!r.done) spent(r.value, n - t, true, r.value === 'town' ? `town: ${drawing}` : r.value);
      t = n;
      if (r.done) { this.making = null; this.finish(k, m.parts); return true; }
      if (n >= until) return false;
    }
  }

  /** Build chunk k now, all of it (a refresh after an edit, the title reel's warm). */
  build(k: number): void {
    if (this.making?.k === k) this.abandon();
    if (this.chunks.has(k) || this.pending.has(k) || this.reuse(k)) return;
    const parts: THREE.Object3D[] = [];
    const steps = this.steps(k, parts);
    let t = performance.now();
    for (let r = steps.next(); !r.done; r = steps.next()) {
      const n = performance.now();
      CHUNK_COST.set(r.value, (CHUNK_COST.get(r.value) ?? 0) + n - t);
      spent(`rebuild: ${r.value}`, n - t, false, `rebuild: ${r.value === 'town' ? `town: ${drawing}` : r.value}`);
      t = n;
    }
    this.finish(k, parts);
  }

  /** A chunk's meshes are all made: into the scene, or held while their shaders compile. */
  private finish(k: number, parts: THREE.Object3D[]): void {
    const cx = k % CHUNKS, cz = (k - cx) / CHUNKS;
    CHUNK_COST.set('chunks', (CHUNK_COST.get('chunks') ?? 0) + 1);
    const ready = warmHook?.(parts);
    if (!ready) { this.attach(k, cx, cz, parts); return; }
    const wait = { parts, crops: true, shadows: true };
    this.pending.set(k, wait);
    void ready.then(() => {
      // dropped, rebuilt or the island let go while it compiled: that path has disposed of it
      if (this.pending.get(k) !== wait) return;
      this.pending.delete(k);
      this.attach(k, cx, cz, parts);
      this.showCrops(k, wait.crops);
      this.propShadows(k, wait.shadows);
    });
  }

  /** A chunk still compiling, thrown away. */
  private dropPending(k: number): boolean {
    const wait = this.pending.get(k);
    if (!wait) return false;
    this.pending.delete(k);
    for (const p of wait.parts) disposeTree(p);
    return true;
  }

  /** Put a chunk's meshes in the scene, and hide the coarse stand-ins it replaces. */
  private attach(k: number, cx: number, cz: number, parts: THREE.Object3D[]): void {
    for (const p of parts) {
      this.group.add(p);
      // world matrices worked out once, here: the island's group never moves (see freezeStatic)
      if (!p.userData.frozen) { p.updateWorldMatrix(true, true); freezeStatic(p); p.userData.frozen = true; }
    }
    this.chunks.set(k, parts);
    const ribbon = this.lodRails[k];
    if (ribbon) ribbon.visible = false;
    this.lodMark(cx, cz, true);
  }

  /** A chunk's detail came in (or went): the coarse block under it leaves its patch out (or draws it again). */
  private lodMark(cx: number, cz: number, on: boolean): void {
    const b = Math.floor(cz / BLOCK) * BLOCKS + Math.floor(cx / BLOCK);
    const bit = 1 << ((cz % BLOCK) * BLOCK + (cx % BLOCK));
    this.lodIn[b] = on ? this.lodIn[b] | bit : this.lodIn[b] & ~bit;
    const m = this.lod[b];
    if (m) lodShowChunks(m, (k) => !(this.lodIn[b] & (1 << k)));
    const t = this.lodTown[b];
    if (t) lodShowChunks(t, (k) => !(this.lodIn[b] & (1 << k)));
  }

  /**
   * Take a chunk out of the scene. `keep` holds on to its meshes for the view coming back (see SPARE);
   * otherwise, or once the spares are full, the oldest is thrown away.
   */
  drop(k: number, keep = false): void {
    if (this.making?.k === k) { this.abandon(); return; }
    if (this.dropPending(k)) return;
    const parts = this.chunks.get(k);
    if (!parts) return;
    this.chunks.delete(k);
    for (const p of parts) this.group.remove(p);
    if (keep) this.keepSpare(k, parts);
    else for (const p of parts) disposeTree(p);
    const ribbon = this.lodRails[k];
    if (ribbon) ribbon.visible = true;
    const cx = k % CHUNKS, cz = (k - cx) / CHUNKS;
    this.lodMark(cx, cz, false);
  }

  /**
   * Rebuild whichever loaded chunks cover these tiles (a road was laid, something came down). `pois`
   * false leaves the cabins and lighthouses alone: the earthworks drag redraws many times a second.
   */
  refresh(tiles: number[], pois = true): void {
    const keys = new Set<number>();
    for (const t of tiles) {
      const x = t % N, z = (t - x) / N;
      keys.add(Math.floor(z / CHUNK) * CHUNKS + Math.floor(x / CHUNK));
    }
    for (const k of keys) {
      this.forgetSpare(k);
      if (this.making?.k === k) { this.abandon(); continue; } // queued still: started again from the ground as it is
      if (this.dropPending(k)) { this.build(k); continue; }
      if (!this.chunks.has(k)) continue;
      this.drop(k);
      this.build(k);
    }
    if (!pois) return;
    this.baseSome(Infinity);
    const t = performance.now();
    if (this.pois) { this.group.remove(this.pois); disposeTree(this.pois); }
    this.pois = buildBuildings(this.w, this.geos);
    this.pois.name ||= 'buildings';
    this.place(this.pois);
    // and the distant town over them: a building went up or came down
    const blocks = new Set<number>();
    for (const i of tiles) {
      const x = i % N, z = (i - x) / N;
      blocks.add(Math.floor(z / (BLOCK * CHUNK)) * BLOCKS + Math.floor(x / (BLOCK * CHUNK)));
    }
    for (const b of blocks) this.farTown(b);
    spent('rebuild: pois', performance.now() - t, false);
  }

  forgetSpare(k: number): void {
    const s = this.takeSpare(k);
    if (!s) return;
    for (const p of s.parts) disposeTree(p);
  }

  /** Rebuild the coarse blocks over these tiles: the ground itself has moved (docs/terrain.html). */
  rebuildLod(tiles: number[]): void {
    this.baseSome(Infinity);
    const blocks = new Set<number>();
    for (const t of tiles) {
      const x = t % N, z = (t - x) / N;
      blocks.add(Math.floor(z / (BLOCK * CHUNK)) * BLOCKS + Math.floor(x / (BLOCK * CHUNK)));
    }
    for (const b of blocks) {
      const old = this.lod[b];
      if (old) { this.group.remove(old); old.geometry.dispose(); }
      const bx = b % BLOCKS, bz = (b - bx) / BLOCKS;
      const m = buildIslandLod(this.w, bx * BLOCK * CHUNK, bz * BLOCK * CHUNK, (bx + 1) * BLOCK * CHUNK, (bz + 1) * BLOCK * CHUNK, treesOn(this.w));
      this.lod[b] = m;
      if (m) { lodShowChunks(m, (k) => !(this.lodIn[b] & (1 << k))); this.place(m); }
    }
  }

  /** The instance of a fence drawn in this island's loaded chunk, if the chunk is loaded. */
  fenceInstance(kind: FenceKind, i: number, px: number, pz: number): { mesh: THREE.InstancedMesh; index: number } | null {
    const x = i % N, z = (i - x) / N;
    const parts = this.chunks.get(Math.floor(z / CHUNK) * CHUNKS + Math.floor(x / CHUNK));
    const props = parts?.find((p) => p.name === 'props');
    const mesh = props?.children.find((c) => c.name === kind) as THREE.InstancedMesh | undefined;
    if (!mesh) return null;
    for (let k = 0; k < mesh.count; k++) {
      mesh.getMatrixAt(k, _mat);
      _v.setFromMatrixPosition(_mat);
      if (Math.abs(_v.x - px) < 0.01 && Math.abs(_v.z - pz) < 0.01) return { mesh, index: k };
    }
    return null;
  }

  dispose(): void {
    this.abandon();
    this.base?.return(undefined);
    this.base = null;
    for (const k of [...this.pending.keys()]) this.dropPending(k);
    for (const k of [...this.chunks.keys()]) this.drop(k);
    for (const k of [...this.spare.keys()]) this.forgetSpare(k);
    for (const m of this.lod) if (m) { this.group.remove(m); m.geometry.dispose(); }
    this.lod = [];
    // with their window skins (render/farLights.ts), which were left behind on every unload (11 Nov 2026 perf audit)
    for (const m of this.lodTown) if (m) { this.group.remove(m); m.geometry.dispose(); (m.userData.lights as THREE.Mesh | undefined)?.geometry.dispose(); }
    this.lodTown = [];
    for (const m of this.lodRails) if (m) { this.group.remove(m); m.geometry.dispose(); }
    this.lodRails = [];
    if (this.pois) disposeTree(this.pois);
    this.group.removeFromParent();
  }
}

const _mat = new THREE.Matrix4();
const _v = new THREE.Vector3();

/** A fence on its way down: its instance, where it stood, which way it falls, and how far it has got. */
interface Falling { mesh: THREE.InstancedMesh; index: number; p: Placement; fell: number; stone: boolean; t: number }

function disposeTree(o: THREE.Object3D): void {
  forgetRailChunk(o); // crossings and signals leave the simulation's registries with their chunk
  o.traverse((c) => {
    const m = c as THREE.Mesh & { isInstancedMesh?: boolean; dispose?: () => void };
    if (m.isInstancedMesh) m.dispose?.();
    else if ((m as THREE.Mesh).isMesh) (m as THREE.Mesh).geometry.dispose();
  });
}

/**
 * Everything on screen that is made of world.
 *
 * Every island has its own group, parked at its place on the lattice, so all the meshes inside it
 * are built in the island's own tile coordinates exactly as they always were. Near the camera the
 * chunks are drawn in full; everywhere else a coarse block stands in, so the horizon is full of
 * land without the memory of a dozen islands' worth of detail. Chunks are built a few milliseconds
 * at a time, nearest first, so arriving somewhere new never costs a frame.
 */
/**
 * A chunk's meshes never move once built, and nor does the island's group they hang from, so their
 * matrices are worked out once (by attach) rather than every frame: the local ones composed, and a
 * subtree with nothing moving in it left out of the frame's matrix walk altogether (updateMatrixWorld
 * and its compose were a sixth of the slow frames' time in the Oct 2026 playtest). A kit's spinners and
 * rides (userData.moves) keep theirs live, with all under them. Returns whether the subtree is still.
 */
function freezeStatic(o: THREE.Object3D): boolean {
  if (o.userData.moves) return false;
  o.matrixAutoUpdate = false;
  let still = true;
  for (const c of o.children) if (!freezeStatic(c)) still = false;
  if (still) {
    o.matrixWorldAutoUpdate = false;
    // and the walk itself stops here (11 Nov 2026 perf audit): three still visited every node under a still
    // subtree each frame, though nothing in it does anything, and every loaded chunk's nodes were most of the
    // ~5 ms floor under the render lap. Walked as before if anything has been hung on it since.
    o.userData.stillN = o.children.length;
    o.updateMatrixWorld = stillWalk;
  }
  return still;
}
const walk = THREE.Object3D.prototype.updateMatrixWorld;
function stillWalk(this: THREE.Object3D, force?: boolean): void {
  if (this.children.length !== this.userData.stillN) walk.call(this, force);
}

export class Stream {
  /** Set the hook every new chunk and island is handed to once built (see warmHook). */
  static warm(f: typeof warmHook): void { warmHook = f; }
  /** Chunk build time by part (debug). */
  get cost(): Record<string, number> { return Object.fromEntries([...CHUNK_COST].map(([k, v]) => [k, +v.toFixed(1)])); }
  /** The longest single step of each kind (debug): `pr.stream.max`. */
  get max(): Record<string, number> { return Object.fromEntries([...STEP_MAX].sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, +v.toFixed(1)])); }
  /** Forget the maxima (debug: `pr.stream.resetMax()` once the loading screen is down, to see play's own). */
  resetMax(): void { STEP_MAX.clear(); }
  readonly root = new THREE.Group();
  private views = new Map<World, View>();
  private queue: { view: View; k: number; d: number }[] = [];
  private lastX = NaN;
  private lastZ = NaN;
  /** An island being drawn in full, whatever the distance. */
  private whole: World | null = null;
  built = 0;

  constructor(private geos: PropGeometries) {}

  /** Detailed chunks built and shown across every island in the scene (the play reports' frame windows). */
  /** Counties with a view (drawn), and chunks kept off the scene for a view coming back (SPARE), for the play reports' census. */
  get viewCount(): number { return this.views.size; }
  get spareChunks(): number { let n = 0; for (const v of this.views.values()) n += (v as unknown as { spare: Map<number, unknown> }).spare.size; return n; }
  get loadedChunks(): number { let n = 0; for (const v of this.views.values()) n += v.chunks.size; return n; }

  add(w: World): void {
    if (this.views.has(w)) return;
    const v = new View(w, this.geos);
    this.views.set(w, v);
    this.root.add(v.group);
    this.lastX = NaN; // the queue is stale now
  }

  remove(w: World): void {
    const v = this.views.get(w);
    if (!v) return;
    const t = performance.now();
    v.dispose();
    spent('let go', performance.now() - t, false);
    this.views.delete(w);
    this.queue = this.queue.filter((q) => q.view !== v);
  }

  /** The group an island's meshes live under, parked at its place on the lattice. */
  groupOf(w: World): THREE.Group | null { return this.views.get(w)?.group ?? null; }

  refresh(w: World, tiles: number[]): void {
    this.views.get(w)?.refresh(tiles);
  }

  /** Redraw the chunks over these tiles and nothing else: the ground moving under the earthworks drag. */
  refreshGround(w: World, tiles: number[]): void {
    this.views.get(w)?.refresh(tiles, false);
  }

  /** The middle-distance blocks over these tiles, drawn again from the ground as it now is. */
  rebuildLod(w: World, tiles: number[]): void {
    this.views.get(w)?.rebuildLod(tiles);
  }

  private falling: Falling[] = [];

  /**
   * A car knocked a fence down on island w (it is already in w.knocked, so a chunk built from now on
   * draws it lying flat): topple the one on screen. `px, pz` is where it stood.
   */
  knock(w: World, f: { kind: FenceKind; i: number; d: number; fell: number }, px: number, pz: number): void {
    const found = this.views.get(w)?.fenceInstance(f.kind, f.i, px, pz);
    if (!found) return;
    const x = f.i % N, z = (f.i - x) / N;
    const p = fencePlacement(w, x, z, { kind: f.kind, d: f.d, px, pz });
    this.falling.push({ ...found, p, fell: f.fell, stone: slumps(f.kind), t: 0 });
  }

  /** Fences toppling: they fall with a quick ease-in, the way a tipped thing speeds up, and land. */
  animate(dt: number): void {
    if (!this.falling.length || dt <= 0) return;
    this.falling = this.falling.filter((a) => {
      a.t = Math.min(1, a.t + dt / (a.stone ? 0.2 : 0.32));
      const e = a.stone ? 1 - (1 - a.t) * (1 - a.t) : a.t * a.t;
      a.mesh.setMatrixAt(a.index, placementMatrix(a.p, a.fell * e, _mat, a.stone));
      a.mesh.instanceMatrix.needsUpdate = true;
      return a.t < 1;
    });
  }

  /**
   * Work out what should be detailed around (gx, gz) in world tiles, then build for a few ms.
   * `whole` is an island to draw in full however far away it is, which is what the overview asks
   * for: at that height the ring would leave the rim of the island coarse.
   */
  update(gx: number, gz: number, budgetMs: number, whole: World | null = null, camera: THREE.PerspectiveCamera | null = null): void {
    // the view is planned again when the focus has moved a half-chunk, or the camera has turned, tilted or zoomed enough to show new ground
    const sig = camera ? this.cameraSig(camera, gx, gz) : '';
    if (whole !== this.whole || sig !== this.camSig || Math.abs(gx - this.lastX) > CHUNK / 2 || Math.abs(gz - this.lastZ) > CHUNK / 2 || Number.isNaN(this.lastX)) {
      this.lastX = gx;
      this.lastZ = gz;
      this.whole = whole;
      this.camSig = sig;
      const t = performance.now(), dropped = FRAME_STEPS.get('drop') ?? 0;
      this.replan(gx, gz, camera);
      // the plan's own time, the drops inside it counted as theirs
      spent('plan', performance.now() - t - ((FRAME_STEPS.get('drop') ?? 0) - dropped), false);
    }
    // a step always (a part of a chunk, a building of a town, a coarse block), then more while the budget lasts:
    // a chunk that doesn't fit carries on next frame. The ground right round the focus comes first, then the bases
    // of newly arrived islands (their horizon), then the rest nearest first.
    const until = performance.now() + budgetMs;
    let ran = false;
    const near = this.queue.length && this.queue[this.queue.length - 1].d <= CORE;
    if (!near) {
      for (const v of this.views.values()) {
        if (v.based) continue;
        if (ran && performance.now() >= until) return;
        ran = true;
        if (!v.baseSome(until)) return;
      }
    }
    while (this.queue.length) {
      if (ran && performance.now() >= until) return;
      const job = this.queue[this.queue.length - 1];
      if (!this.views.has(job.view.w)) { this.queue.pop(); continue; }
      ran = true;
      if (!job.view.buildSome(job.k, until)) return;
      this.queue.pop();
      job.view.showCrops(job.k, job.d <= CROP_NEAR);
      job.view.propShadows(job.k, job.d <= PROP_SHADOW_NEAR);
      this.built++;
    }
    for (const v of this.views.values()) {
      if (v.based) continue;
      if (ran && performance.now() >= until) return;
      ran = true;
      if (!v.baseSome(until)) return;
    }
  }

  /**
   * Build toward a second focus without dropping anything: the chunks round the title reel's next
   * shot, drawn before the cut. Returns how many within reach of it are still missing.
   */
  warm(gx: number, gz: number, budgetMs: number, reach = NEAR * 0.6): number {
    const want: { view: View; k: number; d: number }[] = [];
    for (const v of this.views.values()) {
      const w = v.w;
      if (gx < w.ox - reach || gz < w.oz - reach || gx > w.ox + N + reach || gz > w.oz + N + reach) continue;
      for (let cz = 0; cz < CHUNKS; cz++) {
        for (let cx = 0; cx < CHUNKS; cx++) {
          const k = cz * CHUNKS + cx;
          if (v.hasChunk(k)) continue;
          const x0 = w.ox + cx * CHUNK, z0 = w.oz + cz * CHUNK;
          const d = Math.hypot(Math.max(0, x0 - gx, gx - (x0 + CHUNK)), Math.max(0, z0 - gz, gz - (z0 + CHUNK)));
          if (d <= reach) want.push({ view: v, k, d });
        }
      }
    }
    want.sort((a, b) => a.d - b.d);
    const until = performance.now() + budgetMs;
    let left = want.length;
    for (const job of want) {
      if (performance.now() >= until) break;
      job.view.build(job.k);
      this.built++;
      left--;
    }
    return left;
  }

  /** Forget the plan, so the next update replans round its focus (after a cut to somewhere else). */
  replanSoon(): void { this.lastX = NaN; }

  private camSig = '';
  private frustum = new THREE.Frustum();
  private keepFrustum = new THREE.Frustum();
  private proj = new THREE.Matrix4();
  private box = new THREE.Box3();

  /** The camera's pose, coarsely: a new value means the view has changed enough to plan again. */
  private cameraSig(c: THREE.PerspectiveCamera, gx: number, gz: number): string {
    const dx = c.position.x - gx, dz = c.position.z - gz;
    const yaw = Math.round(Math.atan2(dx, dz) / (Math.PI / 18));
    const dist = Math.round(Math.log(Math.max(1, Math.hypot(dx, c.position.y, dz))) * 6);
    const pitch = Math.round(Math.atan2(c.position.y, Math.hypot(dx, dz)) / (Math.PI / 24));
    return `${yaw}|${dist}|${pitch}`;
  }

  /**
   * Two frustums from the camera: the view widened a little (what is built) and widened a lot (what is
   * kept). A frustum is widened by pulling its planes outward, which for a perspective camera is the
   * same as a slightly wider lens.
   */
  private setFrustums(c: THREE.PerspectiveCamera): void {
    const wider = (pad: number, out: THREE.Frustum) => {
      this.proj.multiplyMatrices(c.projectionMatrix, c.matrixWorldInverse);
      out.setFromProjectionMatrix(this.proj);
      for (const pl of out.planes) pl.constant += pad;
    };
    wider(VIEW_PAD, this.frustum);
    wider(KEEP_PAD, this.keepFrustum);
  }

  /** How many chunks are still waiting to be drawn in full. */
  get pending(): number {
    let n = this.queue.length;
    for (const v of this.views.values()) if (!v.based) n++;
    return n;
  }

  /**
   * The same, for the ground round the focus only: chunks planned within r tiles of it, and the island under it
   * while its coarse blocks aren't made (game/travelLoading.ts: the camera sent far waits on what it looks at,
   * not on neighbours coming in behind).
   */
  pendingNear(gx: number, gz: number, r: number): number {
    let n = 0;
    for (const q of this.queue) if (q.d <= r) n++;
    for (const v of this.views.values()) if (!v.based && gx >= v.w.ox && gx < v.w.ox + N && gz >= v.w.oz && gz < v.w.oz + N) n++;
    return n;
  }

  private replan(gx: number, gz: number, camera: THREE.PerspectiveCamera | null): void {
    this.queue = [];
    if (camera) this.setFrustums(camera);
    for (const v of this.views.values()) {
      const w = v.w;
      const top = (w.peak + 12) * STEP;
      for (let cz = 0; cz < CHUNKS; cz++) {
        for (let cx = 0; cx < CHUNKS; cx++) {
          const k = cz * CHUNKS + cx;
          // distance from the focus to the nearest point of the chunk, and of what it draws
          const e = v.extent(k);
          const x0 = w.ox + e[0], z0 = w.oz + e[1], x1 = w.ox + e[2], z1 = w.oz + e[3];
          const dx = Math.max(0, x0 - gx, gx - x1);
          const dz = Math.max(0, z0 - gz, gz - z1);
          const d = Math.hypot(dx, dz);
          let want: boolean, keep: boolean;
          if (w === this.whole) want = keep = true;
          else if (!camera) { want = d <= NEAR; keep = d <= NEAR + HYSTERESIS; }
          else if (d <= CORE) want = keep = true;
          else if (d > FAR) { want = false; keep = d <= FAR + HYSTERESIS && this.inView(this.keepFrustum, x0, z0, top, x1, z1); }
          else {
            // the chunk's box, tall enough to hold whatever stands on it. Hysteresis is the wider
            // keepFrustum, not a distance carve-out — a carve-out wide enough to matter would just
            // as well keep everything near the focus loaded regardless of which way the camera looks,
            // which is the opposite of the point.
            want = this.inView(this.frustum, x0, z0, top, x1, z1);
            keep = want || this.inView(this.keepFrustum, x0, z0, top, x1, z1);
          }
          if (v.hasChunk(k)) {
            if (!keep) { const t = performance.now(); v.drop(k, true); spent('drop', performance.now() - t, false); }
            else { v.showCrops(k, d <= CROP_NEAR); v.propShadows(k, d <= PROP_SHADOW_NEAR); }
          } else if (want) {
            this.queue.push({ view: v, k, d });
          }
        }
      }
    }
    // nearest last: the queue is popped from the end
    this.queue.sort((a, b) => b.d - a.d);
    // a chunk part way through building is finished first if it is still wanted, so a replan never wastes it
    for (const v of this.views.values()) {
      const k = v.makingChunk;
      if (k < 0) continue;
      const i = this.queue.findIndex((q) => q.view === v && q.k === k);
      if (i < 0) { v.abandon(); continue; }
      const [job] = this.queue.splice(i, 1);
      this.queue.push(job);
    }
  }

  private inView(f: THREE.Frustum, x0: number, z0: number, top: number, x1 = x0 + CHUNK, z1 = z0 + CHUNK): boolean {
    this.box.min.set(x0, -1.5, z0);
    this.box.max.set(x1, top, z1);
    return f.intersectsBox(this.box);
  }
}
