import { N, type World } from '../../world/tiles';
import { strongholdsIn, toPlan, fromPlan, dirFromPlan, type Stronghold } from '../../world/strongholds';
import { insidePlan, gateOut, type SGate } from '../../world/strongholdPlans';
import { FACTIONS, RUNG, RUNGS, type FactionId } from './factions';
import { reputation } from './reputation';
import { deeds } from '../deeds';

/**
 * The factions' strongholds' gates (docs/strongholds.html): a player the faction does not count Honoured is stopped at
 * the gate ("papers, please"), told why, and turned round and set back outside; Hostile and worse are searched and
 * fined first. A player found inside without the standing by any other way (a jump, a tow, a garage, a spawn, a
 * helicopter that somehow set down) is put out at the gate the same way. And over a stronghold that does not honour
 * them, the sky is closed (game/air.ts setAirClosed): nothing they fly can come down there, the Army's airfield included.
 */

export interface GateHost {
  /** The player's vehicle in its county's own tiles, and what it is; null when not driving one. */
  player(): { w: World; x: number; z: number; heading: number; v: number; kind: 'land' | 'air' | 'water' } | null;
  /** Put the player's vehicle at county tile (x, z) facing `heading` (x = sin, z = cos), stopped. */
  place(x: number, z: number, heading: number): void;
  worlds(): World[];
  hold(seconds: number): void;
  fine(n: number, why: string): void;
  announce(title: string, body: string): void;
  float(text: string, x: number, z: number, kind: 'info' | 'bad'): void;
}

/** How near a gate (tiles) a refused car is stopped. */
const STOP_R = 2.2;
/** How far outside the gate it is set down, facing away. */
const OUT = 3.0;
/** Closed airspace reaches this far past a stronghold's lot (tiles), and past the Army's airfield. */
const SKY_MARGIN = 3;
/** About how far an airfield reaches from its middle (a major runway's half length and its apron). */
const AIRFIELD_R = 20;

const allowed = (f: FactionId) => reputation.rung(f) >= RUNG.honoured;

export class StrongholdGates {
  /** When each gate last stopped the player (so one approach is one stop). */
  private stopped = new Map<string, number>();
  private clock = 0;
  /** Strongholds the player has been inside, this session (the first time each is announced). */
  private inside = new Set<string>();
  private skyWarned = new Map<string, number>();

  constructor(private host: GateHost) {}

  /** Is the sky closed over world tile (gx, gz) for the player? */
  closed = (gx: number, gz: number): boolean => {
    for (const w of this.host.worlds()) {
      const lx = gx - w.ox, lz = gz - w.oz;
      if (lx < -SKY_MARGIN || lz < -SKY_MARGIN || lx >= N + SKY_MARGIN || lz >= N + SKY_MARGIN) continue;
      for (const s of strongholdsIn(w)) {
        if (allowed(s.f)) continue;
        const b = s.b;
        if (lx >= b.x - SKY_MARGIN && lz >= b.z - SKY_MARGIN && lx < b.x + b.w + SKY_MARGIN && lz < b.z + b.d + SKY_MARGIN) { this.warnSky(s); return true; }
        // the Army's: its airfield too
        if (s.f === 'army') {
          for (const g of w.works) {
            if (!g.military) continue;
            if (Math.hypot(lx - g.x, lz - g.z) <= AIRFIELD_R + SKY_MARGIN) { this.warnSky(s); return true; }
          }
        }
      }
    }
    return false;
  };

  private warnSky(s: Stronghold): void {
    const key = `${s.w.cx},${s.w.cz}`;
    const hour = Math.floor(this.clock / 60);
    if (this.skyWarned.get(key) === hour) return;
    this.skyWarned.set(key, hour);
    this.host.announce('⛔ Restricted airspace', `${s.name} is closed to you from the air. ${FACTIONS[s.f].name} must count you Honoured before anything you fly may come down there.`);
  }

  update(dt: number): void {
    this.clock += dt;
    const p = this.host.player();
    if (!p || p.kind === 'air') return;
    for (const s of strongholdsIn(p.w)) {
      const b = s.b;
      if (p.x < b.x - 4 || p.z < b.z - 4 || p.x > b.x + b.w + 4 || p.z > b.z + b.d + 4) continue;
      const [px, pz] = toPlan(b, p.x, p.z);
      const inside = insidePlan(s.plan, px, pz);
      const key = `${p.w.cx},${p.w.cz}#${b.uid}`;
      if (allowed(s.f)) {
        if (inside && !this.inside.has(key)) {
          this.inside.add(key);
          deeds.mark('gates', s.f);
          this.host.announce(`${FACTIONS[s.f].glyph} ${s.name}`, `${FACTIONS[s.f].name} open their gates to you. Their stronghold’s own loads wait at its headquarters door.`);
        }
        continue;
      }
      if (inside) { this.turnBack(s, nearestGate(s, px, pz), p, true); return; }
      // coming up to a gate from outside, and moving: stopped there
      // the way the car is going, in the stronghold's frame
      const [hx, hz] = toPlan(b, b.x + b.w / 2 + Math.sin(p.heading) * Math.sign(p.v || 1), b.z + b.d / 2 + Math.cos(p.heading) * Math.sign(p.v || 1));
      for (const g of s.plan.gates) {
        if (Math.hypot(px - g.x, pz - g.z) > STOP_R || Math.abs(p.v) < 0.05) continue;
        // only a car heading in through it: driving past the end of its road is no approach
        const [ox, oz] = gateOut(s.plan, g);
        if (hx * ox + hz * oz > -0.3) continue;
        const gk = `${key}:${g.x},${g.z}`;
        if (this.clock - (this.stopped.get(gk) ?? -99) < 4) continue;
        this.stopped.set(gk, this.clock);
        this.turnBack(s, g, p, false);
        return;
      }
    }
  }

  private turnBack(s: Stronghold, g: SGate, p: NonNullable<ReturnType<GateHost['player']>>, found: boolean): void {
    const [ox, oz] = gateOut(s.plan, g);
    const [lx, lz] = fromPlan(s.b, g.x + ox * OUT, g.z + oz * OUT);
    const [dx, dz] = dirFromPlan(s.b, ox, oz);
    this.host.place(lx, lz, Math.atan2(dx, dz));
    const f = s.f, d = FACTIONS[f], r = reputation.rung(f);
    const togo = Math.max(0, Math.ceil(RUNGS[RUNG.honoured].at - reputation.points(f)));
    const bar = `${d.short} ${Math.round(reputation.points(f)).toLocaleString('en-GB')} / ${RUNGS[RUNG.honoured].at.toLocaleString('en-GB')}: ${togo.toLocaleString('en-GB')} to Honoured`;
    if (r <= RUNG.hostile) {
      this.host.hold(6);
      this.host.fine(30, 'Searched');
      this.host.announce(`⛔ ${s.name}`, `Papers, please… The guard has your name on a list: a search, $30 for the trouble, and “don’t come back.” ${bar}.`);
    } else {
      this.host.hold(3);
      const why = r >= RUNG.friend
        ? `“You’re not on the list. ${d.name} open their gates to those they honour.”`
        : '“No one here knows you. Turn it round.”';
      this.host.announce(`⛔ ${s.name}`, `${found ? 'You are shown back out to the gate. ' : 'Papers, please… '}${why} ${bar}.`);
    }
    this.host.float('Papers, please', lx + s.w.ox, lz + s.w.oz, 'bad');
    void p;
  }
}

/** The gate nearest a point inside (the way back out). */
function nearestGate(s: Stronghold, px: number, pz: number): SGate {
  let best = s.plan.gates[0], d = Infinity;
  for (const g of s.plan.gates) {
    if (g.ring !== 0) continue;
    const e = Math.hypot(px - g.x, pz - g.z);
    if (e < d) { d = e; best = g; }
  }
  return best;
}
