import { activePad } from './gamepad';

/** A key let go within this many ms of going down is a tap; held longer, it is a hold. */
const TAP_MS = 250;

/** Keys that edit or move the caret in a field, besides the printable ones. */
const EDIT_KEYS = new Set(['Backspace', 'Delete', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown']);
const NOT_TEXT = new Set(['checkbox', 'radio', 'range', 'button', 'submit', 'reset', 'color', 'file', 'image']);

/** A text box, text area, drop-down or editable element that the key is typed into. */
export function editable(t: EventTarget | null): boolean {
  if (!(t instanceof HTMLElement)) return false;
  if (t instanceof HTMLInputElement) return !NOT_TEXT.has(t.type);
  return t instanceof HTMLTextAreaElement || t instanceof HTMLSelectElement || t.isContentEditable;
}

export class Input {
  private keys = new Set<string>();
  private pressed = new Set<string>();
  /** When each held key went down (ms), and the keys let go within a tap of going down. */
  private downAt = new Map<string, number>();
  private tapped = new Set<string>();
  dragDX = 0;
  /** Vertical mouse travel while the left button is held: the earthworks drag (docs/terrain.html). */
  leftDY = 0;
  wheel = 0;
  /** Last pointer position over the canvas, in client pixels. */
  mouseX = 0;
  mouseY = 0;
  hasMouse = false;
  private dragging = false;
  private leftDown: { x: number; y: number } | null = null;
  private clicks: { x: number; y: number }[] = [];

  constructor(private el: HTMLElement) {
    window.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      // typing in a text field: the letters, Space, arrows and editing keys are the field's, not the game's (no W driving,
      // no B builder); Escape, Enter and Tab still reach the game so windows can close and forms move on
      if (editable(e.target) && (e.key.length === 1 || EDIT_KEYS.has(e.code))) return;
      this.keys.add(e.code);
      this.pressed.add(e.code);
      this.downAt.set(e.code, performance.now());
      if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
      // Tab is a game key (take the wheel): it mustn't move the page's focus, except between a form's fields
      if (e.code === 'Tab') { const t = e.target as HTMLElement | null; if (!t || !['INPUT', 'TEXTAREA', 'SELECT', 'BUTTON'].includes(t.tagName)) e.preventDefault(); }
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      const t = this.downAt.get(e.code);
      if (t !== undefined && performance.now() - t < TAP_MS) this.tapped.add(e.code);
      this.downAt.delete(e.code);
    });
    window.addEventListener('blur', () => { this.keys.clear(); this.downAt.clear(); });
    document.addEventListener('visibilitychange', () => { if (document.hidden) { this.keys.clear(); this.downAt.clear(); } });
    el.addEventListener('contextmenu', (e) => e.preventDefault());
    el.addEventListener('mousedown', (e) => {
      if (e.button === 2 || e.button === 1) this.dragging = true;
      if (e.button === 0) this.leftDown = { x: e.clientX, y: e.clientY };
    });
    window.addEventListener('mouseup', (e) => {
      this.dragging = false;
      // a left press that barely moved counts as a click on the canvas
      if (e.button === 0 && this.leftDown && Math.hypot(e.clientX - this.leftDown.x, e.clientY - this.leftDown.y) < 6) {
        this.clicks.push({ x: e.clientX, y: e.clientY });
      }
      if (e.button === 0) this.leftDown = null;
    });
    window.addEventListener('mousemove', (e) => {
      if (this.dragging) this.dragDX += e.movementX;
      if (this.leftDown) this.leftDY += e.movementY;
    });
    el.addEventListener('mousemove', (e) => { this.mouseX = e.clientX; this.mouseY = e.clientY; this.hasMouse = true; });
    el.addEventListener('mouseleave', () => { this.hasMouse = false; });
    el.addEventListener('wheel', (e) => { this.wheel += e.deltaY; e.preventDefault(); }, { passive: false });
  }

  down(code: string): boolean { return this.keys.has(code); }
  /** True once per key press. */
  justPressed(code: string): boolean {
    if (this.pressed.has(code)) { this.pressed.delete(code); return true; }
    return false;
  }
  /** True once per tap: a key let go within TAP_MS of going down. A longer press is a hold, never a tap. */
  justTapped(code: string): boolean {
    if (this.tapped.has(code)) { this.tapped.delete(code); return true; }
    return false;
  }
  /** How long a key has been held, in seconds; 0 when it is up. */
  heldFor(code: string): number {
    const t = this.downAt.get(code);
    return t === undefined ? 0 : (performance.now() - t) / 1000;
  }

  /**
   * The pad (gamepad.ts: the DualSense first): right trigger drives, left trigger brakes and
   * reverses, the left stick steers, the right stick turns the camera. The keyboard wins when both are held.
   */
  private pad(): Gamepad | null { return activePad(); }

  get throttle(): number {
    const keys = (this.down('KeyW') || this.down('ArrowUp') ? 1 : 0) - (this.down('KeyS') || this.down('ArrowDown') ? 1 : 0);
    if (keys) return keys;
    const p = this.pad();
    if (!p) return 0;
    const t = (p.buttons[7]?.value ?? 0) - (p.buttons[6]?.value ?? 0);
    return Math.abs(t) > 0.12 ? t : 0;
  }
  get steer(): number {
    const keys = (this.down('KeyA') || this.down('ArrowLeft') ? 1 : 0) - (this.down('KeyD') || this.down('ArrowRight') ? 1 : 0);
    if (keys) return keys;
    const p = this.pad();
    if (!p) return 0;
    // stick right is steer right, which is negative here
    return -stick(p.axes[0]);
  }
  /** Climb (+) / descend (-) for flying vehicles. */
  get lift(): number {
    return (this.down('Space') ? 1 : 0) - (this.down('ShiftLeft') || this.down('ShiftRight') ? 1 : 0);
  }
  /** The handbrake: Space held, under the thumb (the pad's ✕ sends it too); a tap of the same key loads cargo. */
  get handbrake(): boolean { return this.down('Space'); }
  get orbit(): number {
    const keys = (this.down('KeyQ') ? 1 : 0) - (this.down('KeyE') ? 1 : 0);
    if (keys) return keys;
    const p = this.pad();
    // right stick right turns the camera the way E does
    return p ? -stick(p.axes[2]) : 0;
  }
  /** The left button is down on the canvas. */
  get leftHeld(): boolean { return this.leftDown !== null; }
  /** Where the left button went down, in client pixels. */
  get leftFrom(): { x: number; y: number } | null { return this.leftDown; }
  /** Consume the vertical travel of a left drag. */
  takeLeftDY(): number { const d = this.leftDY; this.leftDY = 0; return d; }
  /** Consume accumulated mouse deltas. */
  takeDrag(): number { const d = this.dragDX; this.dragDX = 0; return d; }
  takeWheel(): number { const d = this.wheel; this.wheel = 0; return d; }
  /** Next unconsumed left click on the canvas this frame. */
  takeClick(): { x: number; y: number } | null { return this.clicks.shift() ?? null; }
  /** The pad's cursor: the middle of the screen, where a tool's focus sits. */
  aimAtCentre(): void {
    const r = this.el.getBoundingClientRect();
    this.mouseX = r.left + r.width / 2;
    this.mouseY = r.top + r.height / 2;
    this.hasMouse = true;
  }
  /** A click at the middle of the screen, from the pad. */
  clickCentre(): void {
    this.aimAtCentre();
    this.clicks.push({ x: this.mouseX, y: this.mouseY });
  }
  /** Clear one-shot presses and clicks that nobody consumed this frame. */
  endFrame(): void { this.pressed.clear(); this.tapped.clear(); this.clicks.length = 0; }
}

/** A stick axis with a dead zone, the rest rescaled to -1..1. */
function stick(v: number | undefined): number {
  const a = Math.abs(v ?? 0);
  return a < 0.15 ? 0 : Math.sign(v!) * Math.min(1, (a - 0.15) / 0.85);
}
