/**
 * The Shared Fleet tab of the social window (docs/social.html, docs/sharedfleets.html): who runs this
 * fleet with you, and the ways in. On the left the members, each with their role and what they have brought
 * into the purse this week (the founder may make officers, hand founding over, or boot; anyone else may leave);
 * on the right the asks to join waiting for an answer, the invite to send (a link and a code, or a player by
 * name), how the fleet is joined and who may hand out invites, and a box to join somebody else's fleet. It was
 * the pause card's Fleet players screen (title/menu.ts) until 3 November 2026; the pause card's two buttons
 * open this tab.
 */
import { esc, money } from '../game/cargoHud';
import type { SocialTabBody } from '../game/socialWindow';
import type { CrewCard, OnlineMenu } from '../title/api';
import type { ClientMsg } from '../../shared/protocol';
import type { CrewPolicy, InboxItem, Inviters, Joining } from '../../shared/social';

type CrewApi = Pick<OnlineMenu, 'crew' | 'invite' | 'boot' | 'leaveCrew' | 'joinWith'>;

/** Phase 3 (docs/social.html): what the tab needs beyond the pause card's calls. */
export interface CrewExtra {
  post(m: ClientMsg): void;
  /** The fleet's officers, policy and each member's week; whether I may invite. */
  state(): { officers: string[]; policy: CrewPolicy; week: Record<string, number>; mayInvite: boolean };
  /** Asks to join my fleet still waiting (net/inbox.ts). */
  asks(): InboxItem[];
  /** A player by name (case aside), as the game has heard of them. */
  findPlayer(name: string): { id: string; name: string } | null;
  /** How a fleet of one is joined (my profile). */
  joining(): Joining;
}

const JOIN_LABEL: Record<Joining, string> = { open: 'Open to anyone', ask: 'By asking', invite: 'Invite only' };
const INVITERS_LABEL: Record<Inviters, string> = { founder: 'Founder only', officers: 'Founder and officers', anyone: 'Anyone in the fleet' };

export class CrewTab implements SocialTabBody {
  onlineOnly = true;
  private code: string | null = null;
  private link: string | null = null;
  private error = '';
  private note = '';
  private busy = false;
  private join = '';
  private who = '';
  /** A boot, a leave or a hand-over pressed once: "boot:<id>", "founder:<id>", or 'leave'. */
  private sure: string | null = null;
  /** The window redraws when an invite comes back. */
  onChange: () => void = () => {};

  constructor(private api: CrewApi, private say: (text: string) => void, private signedIn: () => boolean, private extra: CrewExtra | null = null) {}

  opened(): void {
    const c = this.api.crew();
    this.code = c?.code ?? null;
    this.link = c?.link ?? null;
    this.error = '';
    this.sure = null;
  }

  /** The text boxes as typed (the window's body is redrawn around them). */
  typed(name: string, value: string): void { if (name === 'join') this.join = value; if (name === 'who') this.who = value; }

  /** The asks waiting: the tab's badge. */
  badge(): number { return this.extra?.asks().length ?? 0; }

  private async makeInvite(): Promise<void> {
    this.busy = true; this.error = '';
    this.onChange();
    const r = await this.api.invite();
    this.busy = false;
    if ('why' in r) this.error = r.why; else { this.code = r.code; this.link = r.link; this.note = ''; }
    this.onChange();
  }

  private async copy(text: string, said: string): Promise<void> {
    let ok = false;
    try { await navigator.clipboard.writeText(text); ok = true; } catch { ok = false; }
    this.note = ok ? said : 'Select it and copy it (Ctrl+C).';
    this.error = '';
    this.say(this.note);
    this.onChange();
  }

  press(target: HTMLElement): boolean {
    const b = target.closest('[data-cract]') as HTMLElement | null;
    if (!b) return false;
    const act = b.dataset.cract!, id = b.dataset.id ?? '';
    const c = this.api.crew();
    const x = this.extra;
    if (act === 'make') { if (!this.busy) void this.makeInvite(); }
    else if (act === 'copy' && this.link) void this.copy(this.link, 'Link copied: send it to whoever you want in the fleet.');
    else if (act === 'copycode' && this.code) void this.copy(this.code, 'Code copied: they paste it under Join another fleet, or open the link.');
    else if (act === 'boot' && c) {
      if (this.sure !== `boot:${id}`) { this.sure = `boot:${id}`; return true; }
      this.api.boot(id);
      const m = c.members.find((q) => q.id === id);
      this.sure = null;
      this.note = `${m?.name ?? 'They'} ${m ? 'is' : 'are'} out of the fleet: their own fleet is theirs again next time they sign in.`;
    } else if (act === 'leave') {
      if (this.sure !== 'leave') { this.sure = 'leave'; return true; }
      this.api.leaveCrew();
    } else if (act === 'join') {
      const input = b.closest('.cr-join')?.querySelector<HTMLInputElement>('input');
      const why = this.api.joinWith(input?.value ?? this.join);
      if (why) this.error = why;
    } else if (act === 'unsure') this.sure = null;
    else if (act === 'role' && x) {
      const role = b.dataset.role as 'officer' | 'member' | 'founder';
      if (role === 'founder' && this.sure !== `founder:${id}`) { this.sure = `founder:${id}`; return true; }
      this.sure = null;
      x.post({ t: 'crewRole', id, role });
    } else if (act === 'answer' && x) x.post({ t: 'crewAnswer', id, ok: b.dataset.ok === '1' });
    else if (act === 'byname' && x) {
      const input = b.closest('.cr-byname')?.querySelector<HTMLInputElement>('input');
      const name = (input?.value ?? this.who).trim();
      const p = name ? x.findPlayer(name) : null;
      if (!p) { this.error = name ? `Nobody called ${name} has been seen yet: try their card in Fleets.` : 'Type a player’s name.'; return true; }
      this.error = '';
      x.post({ t: 'crewInvite', id: p.id });
      this.who = '';
      if (input) input.value = '';
    } else if (act === 'joining' && x) {
      const v = b.dataset.v as Joining;
      if (c?.shared) x.post({ t: 'crewPolicy', joining: v }); else x.post({ t: 'profile', set: { joining: v } });
    } else if (act === 'inviters' && x) x.post({ t: 'crewPolicy', invites: b.dataset.v as Inviters });
    return true;
  }

  html(): { left: string; right: string } {
    if (!this.signedIn()) return { left: '<p class="none">Sign in to play online first.</p>', right: '' };
    const c: CrewCard | null = this.api.crew();
    if (!c) return { left: '<p class="none">A fleet made in one click from a postcard can’t be shared yet: keep it first (pause → Keep this fleet).</p>', right: '' };
    const st = this.extra?.state() ?? { officers: [], policy: {}, week: {}, mayInvite: c.founder };
    const iAmOfficer = c.members.some((m) => m.you && st.officers.includes(m.id));
    const lead = c.shared
      ? `<b>${esc(c.name)}</b> is run by ${c.members.length} player${c.members.length === 1 ? '' : 's'}: one purse, one garage, the same vehicles, drivers, HQ, slots and buildings. Diamonds, tech, Passport and achievements stay each player’s own.`
      : `Invite other players to run <b>${esc(c.name)}</b> with you: one purse, one garage, the same vehicles, drivers, HQ, slots and buildings. Diamonds, tech, Passport and achievements stay each player’s own.`;
    const pips = Array.from({ length: 8 }, (_, i) => `<i class="${i < (c.shared ? c.members.length : 1) ? 'on' : ''}"></i>`).join('');
    const top = Math.max(1, ...Object.values(st.week));
    const members = (c.shared ? c.members : [{ id: '', name: 'You', online: true, founder: true, you: true }]).map((m) => {
      const officer = st.officers.includes(m.id);
      const role = m.founder ? 'founder' : officer ? 'officer' : 'member';
      const brought = st.week[m.id] ?? 0;
      const btn = (act: string, label: string, extra = '', warn = false) => `<button type="button" class="link${warn ? ' warn' : ''}" data-cract="${act}" data-id="${esc(m.id)}"${extra}>${label}</button>`;
      let acts = '';
      if (c.founder && !m.you && m.id) {
        const sureBoot = this.sure === `boot:${m.id}`, sureHand = this.sure === `founder:${m.id}`;
        acts = `<span class="acts">${btn('role', officer ? 'Not an officer' : 'Make officer', ` data-role="${officer ? 'member' : 'officer'}"`)}`
          + `${btn('role', sureHand ? 'Sure? Hand over founding' : 'Hand over', ' data-role="founder"', sureHand)}`
          + `${btn('boot', sureBoot ? 'Sure? Remove' : 'Boot', '', sureBoot)}${sureBoot || sureHand ? btn('unsure', 'Keep') : ''}</span>`;
      }
      return `<li class="${m.online ? '' : 'quiet'}"><span class="what"><b${m.id && !m.you ? ` data-pid="${esc(m.id)}"` : ''}>${esc(m.name)}</b><small>${[role, m.you ? 'you' : '', m.online ? '<i class="on"></i> online' : 'away'].filter(Boolean).join(' · ')}</small>`
        + (c.shared ? `<small>${brought ? `${money(brought)} into the purse this week` : 'nothing into the purse this week'}</small><span class="nbar"><i style="width:${((brought / top) * 100).toFixed(1)}%;background:#1e9e4a"></i></span>` : '')
        + `</span>${acts}</li>`;
    }).join('');
    const leave = c.shared && !c.founder
      ? `<p class="foot"><button type="button" class="link${this.sure === 'leave' ? ' warn' : ''}" data-cract="leave">${this.sure === 'leave' ? 'Sure? Leave and sign out' : 'Leave this fleet'}</button>${this.sure === 'leave' ? ' <button type="button" class="link" data-cract="unsure">Stay</button>' : ''} · your own fleet is kept for you.</p>`
      : c.shared && c.founder ? '<p class="foot">You founded this fleet: it stays yours. Hand founding over to a member to be free to leave it, or remove the others to run it alone.</p>' : '';
    const left = `<p class="lead">${lead}</p><div class="cr-pips" title="${c.shared ? c.members.length : 1} of 8 places">${pips}<small>${c.shared ? c.members.length : 1} of 8</small></div>
      <ul class="people crew">${members}</ul>${leave}`;

    // asks waiting for an answer: the founder's and officers' to give (alone, yours)
    const answer = !c.shared || c.founder || iAmOfficer;
    const asks = answer ? this.extra?.asks() ?? [] : [];
    const requests = asks.length ? `<div class="cr-block"><h4>Asks to join <small>${asks.length}</small></h4><ul class="people asks">${asks.map((a) => `<li><span class="what"><b data-pid="${esc(a.from ?? '')}">${esc(a.name ?? 'a player')}</b><small>${esc(a.fleet ?? '')}${a.text ? ` · “${esc(a.text)}”` : ''}</small></span>`
      + `<span class="acts"><button type="button" class="fc-btn on" data-cract="answer" data-ok="1" data-id="${esc(a.from ?? '')}">Let in</button><button type="button" class="fc-btn" data-cract="answer" data-ok="0" data-id="${esc(a.from ?? '')}">Not now</button></span></li>`).join('')}</ul>
      <p class="foot">Let in sends them an invite good for a week, for them alone. Not now tells them, and they can ask again tomorrow.</p></div>` : '';
    const mayInvite = st.mayInvite;
    const invite = !mayInvite ? '<p>Only the founder and officers hand out invites in this fleet.</p>' : this.code && this.link
      ? `<label>Invite link<input type="text" readonly value="${esc(this.link)}" onfocus="this.select()" spellcheck="false"></label>
         <label>Invite code<input type="text" readonly class="code" value="${esc(this.code)}" onfocus="this.select()" spellcheck="false"></label>
         <div class="fc-acts"><button type="button" class="fc-btn on" data-cract="copy">Copy link</button><button type="button" class="fc-btn" data-cract="copycode">Copy code</button></div>
         <p class="foot">Anyone with the link or the code can join, up to eight of you. The founder can remove anyone.</p>`
      : `<p>An invite is a link to send, or an eight-letter code to type in.</p><div class="fc-acts"><button type="button" class="fc-btn on" data-cract="make"${this.busy ? ' disabled' : ''}>${this.busy ? 'Making…' : 'Make an invite'}</button></div>`;
    const byName = mayInvite && this.extra ? `<div class="cr-byname"><label>Or invite a player by name<input type="text" name="who" maxlength="40" value="${esc(this.who)}" placeholder="their player name" spellcheck="false" autocomplete="off"></label>
      <div class="fc-acts"><button type="button" class="fc-btn" data-cract="byname">Send invite</button></div><p class="foot">It waits in their inbox for a week, good for them alone. Or use Invite to my fleet on their card.</p></div>` : '';
    // how the fleet is joined: the founder's (or yours, alone); who may invite: the founder's
    const joining = (c.shared ? st.policy.joining : this.extra?.joining()) ?? 'ask';
    const inviters = st.policy.invites ?? 'officers';
    const chip = (act: string, v: string, label: string, on: boolean) => `<button type="button" data-cract="${act}" data-v="${v}" class="${on ? 'on' : ''}">${label}</button>`;
    const settings = (!c.shared || c.founder) && this.extra ? `<div class="cr-block"><h4>How players join</h4>
        <div class="scope">${(Object.keys(JOIN_LABEL) as Joining[]).map((j) => chip('joining', j, JOIN_LABEL[j], joining === j)).join('')}</div>
        <p class="foot">${joining === 'open' ? 'Ask to join on your card lets anyone in at once (they still confirm).' : joining === 'ask' ? 'Ask to join on your card sends you their ask; you answer it here or in your inbox.' : 'Nobody can ask: only an invite from you lets a player in.'}</p>
        ${c.shared ? `<h4>Who may invite</h4><div class="scope">${(Object.keys(INVITERS_LABEL) as Inviters[]).map((v) => chip('inviters', v, INVITERS_LABEL[v], inviters === v)).join('')}</div>` : ''}</div>` : '';
    const right = `${requests}<div class="cr-block"><h4>Invite to the fleet</h4>${invite}${byName}${this.error ? `<p class="err">${esc(this.error)}</p>` : this.note ? `<p class="foot ok">${esc(this.note)}</p>` : ''}</div>
      ${settings}
      <div class="cr-block cr-join"><h4>Join another fleet</h4><p>Paste an invite code or link from another player, or use Ask to join on their card.</p>
        <label>Their invite<input type="text" name="join" maxlength="200" value="${esc(this.join)}" placeholder="an invite code or link" spellcheck="false" autocomplete="off"></label>
        <div class="fc-acts"><button type="button" class="fc-btn" data-cract="join">Join</button></div>
        <p class="foot">Joining signs you out and back in: you are asked to confirm, and your own fleet is kept for you if you ever leave.</p></div>`;
    return { left, right };
  }
}
