import { hex, scale, type RGB } from '../../../world/biomes';
import type { Building, BuildingKind } from '../../../world/tiles';
import { Vis } from '../../nightLights';
import {
  BRICK, DARK, GLASS, METAL, TAU, TRUNK, WARM_GLOW, WHITE, WOOD, RED_LIGHT, cur, pick, styleRoof, styleWall, win, windowSched, windowGlow,
  roofOver, veranda, porch, engawa, corners, doorcase, type Draw, type Kit, type P3 } from '../kit';
import { nameModels } from '../kit';

/** A plain lit pane with the building's own schedule and glow, for stall and shed windows that take no shutters or sashes. */
function lit(k: Kit, b: Building, r: () => number, x: number, y: number, z: number, w: number, h: number, face: number): void {
  k.pane(x, y, z, w, h, face, GLASS, windowSched(b.kind, r), windowGlow(b.kind, r));
}

/**
 * Alternative models for the farm kinds: the farmhouse, the barn and the silo that stand in rural towns
 * and out in the country (drawn there with no town, in the classic style), the wind turbine, the
 * windmill and the orchard. Same lots, same local frame and the same style branches as the originals.
 */

/** The farmhouse's own palette where the style has no roof form of its own. */
const FARM_WALLS = [0xf4f1e8, 0xefe6d2, 0xe8e0cc];
const FARM_ROOFS = [0x8a3a34, 0x4a5560, 0x6b4a3a];

// ---- farmhouse ------------------------------------------------------------------------------

/**
 * An I-house: a two-storey front only a room deep and the width of the lot, a tall brick chimney up
 * each gable end and a one-storey kitchen ell out the back, the door in the middle under a little hood.
 */
const iHouse: Draw = (k, _W, _D, b, r) => {
  const styled = !!cur.form;
  const wall = styled ? styleWall(r) : pick(r, FARM_WALLS), roof = styled ? styleRoof(r) : pick(r, FARM_ROOFS);
  const mw = 0.72, md = 0.3, mz = 0.04, h = 0.5, front = mz + md / 2;
  k.box(0, 0, mz, mw, h, md, wall);
  if (styled && cur.massing === 'ribbed') corners(k, 0, mz, mw, md, h);
  // the kitchen ell behind one end, one storey
  const ex = r() < 0.5 ? -0.17 : 0.17, ew = 0.32, ed = 0.38, ez = mz - md / 2 - ed / 2 + 0.02, eh = 0.28;
  let top: number;
  if (styled) {
    top = roofOver(k, r, 0, h, mz, mw, md, wall, roof);
    if (cur.form === 'flat') k.box(ex, 0, ez, ew, eh, ed, wall, scale(roof, 0.96));
    else {
      k.box(ex, 0, ez, ew, eh, ed, wall);
      if (cur.form === 'hip') k.hip(ex, eh, ez, ew + 0.06, 0.14, ed + 0.04, roof);
      else k.gable(ex, eh, ez, ew + 0.06, 0.14, ed + 0.04, roof, wall, true);
    }
    if (cur.massing === 'veranda') veranda(k, r, 0, 0, mz, mw, md, 0.24);
    if (cur.massing === 'porch') porch(k, r, 0, 0, mz, mw, md, 0.24);
    if (cur.engawa !== undefined) engawa(k, 0, mz, mw, md, true, roof);
  } else {
    const ov = cur.eaves;
    k.gable(0, h, mz, mw + ov, 0.22, md + ov + 0.04, roof, wall);
    top = h + 0.22;
    k.box(ex, 0, ez, ew, eh, ed, wall);
    k.gable(ex, eh, ez, ew + 0.06, 0.14, ed + 0.04, roof, wall, true);
    // the hood over the door
    k.box(0, 0.23, front + 0.05, 0.2, 0.02, 0.1, roof);
  }
  // the chimneys up the gable ends, or the style's own one
  if (!styled) for (const sx of [-1, 1]) k.box(sx * (mw / 2 + 0.03), 0, mz, 0.07, top + 0.08, 0.1, pick(r, BRICK));
  else if (cur.chimney && cur.form !== 'flat') k.box(-(mw / 2 - 0.06), h, mz, 0.07, Math.max(cur.chimney[0], top - h + 0.06), 0.07, hex(cur.chimney[1]));
  // the door in the middle, a window either side and three over them
  k.box(0, 0, front + 0.01, 0.1, 0.2, 0.02, pick(r, cur.doors ?? [0x5a3a28, 0x2f4d7a]));
  if (cur.doorcase !== undefined) doorcase(k, 0, front + 0.02, 0.1, 0.2, hex(cur.doorcase));
  for (const sx of [-1, 1]) for (const y of [0.1, 0.33]) win(k, b, r, sx * 0.2, y, front, 0.12, 0.1, 1);
  lit(k, b, r, ex + (ex < 0 ? -ew / 2 : ew / 2), 0.09, ez, 0.1, 0.08, ex < 0 ? 2 : 0);
  if (!styled) k.glowBox(0.1, 0.17, front + 0.02, 0.03, 0.04, 0.03, WHITE, [17.5 + r(), 22 + r(), 2], hex(cur.glow ?? 0xffc978));
};

/**
 * A longhouse: the house and the byre end to end under one long low roof across the lot, the byre in
 * boards with wide doors and a hay-loft dormer, the chimney standing where the two meet.
 */
const longhouse: Draw = (k, _W, _D, b, r) => {
  const styled = !!cur.form;
  const wall = styled ? styleWall(r) : pick(r, FARM_WALLS), roof = styled ? styleRoof(r) : pick(r, [...FARM_ROOFS, 0x9a7a4a]);
  const flat = cur.form === 'flat';
  const byre = flat ? scale(wall, 0.9) : pick(r, [0x8a5a3a, 0x6e4a32, 0x9a3a30, 0x5a4a3e]);
  const s = r() < 0.5 ? 1 : -1, hw = cur.form === 'curved' ? 0.36 : 0.4, hx = s * hw / 2, bx = -s * hw / 2, z = -0.06, d = 0.5, H = flat ? 0.4 : 0.32, front = z + d / 2;
  k.box(hx, 0, z, hw, H, d, wall);
  k.box(bx, 0, z, hw, H, d, byre);
  if (styled && cur.massing === 'ribbed') corners(k, hx, z, hw, d, H);
  let top: number;
  if (styled) top = roofOver(k, r, 0, H, z, hw * 2, d, wall, roof);
  else {
    // one roof, its two gable ends each in its own end's boards
    for (const [x, end] of [[hx, wall], [bx, byre]] as [number, RGB][]) k.gable(x + (x > 0 ? 0.02 : -0.02), H, z, hw + 0.04, 0.36, d + 0.12, roof, end);
    top = H + 0.36;
  }
  // a hay-loft dormer out of the byre's front slope, where the roof is steep enough to carry it
  if ((!cur.form || cur.form === 'gable') && top - H >= 0.26) {
    k.box(bx, 0.3, front - 0.05, 0.16, 0.18, 0.12, byre);
    k.gable(bx, 0.48, front - 0.05, 0.2, 0.08, 0.14, roof, byre, true);
    k.box(bx, 0.38, front + 0.012, 0.09, 0.09, 0.01, hex(0x3a2a20));
  }
  // the byre's wide doors, the house's door and windows
  k.box(bx, 0, front + 0.01, 0.24, 0.24, 0.02, scale(byre, 0.7));
  k.box(hx + s * 0.1, 0, front + 0.01, 0.1, 0.19, 0.02, pick(r, cur.doors ?? [0x5a3a28, 0x3f5a3f]));
  win(k, b, r, hx - s * 0.07, 0.1, front, 0.12, 0.1, 1);
  win(k, b, r, hx + s * hw / 2, 0.1, z, 0.12, 0.1, s > 0 ? 0 : 2);
  lit(k, b, r, hx, 0.1, z - d / 2, 0.1, 0.08, 3);
  if (cur.engawa !== undefined) engawa(k, hx, z, hw, d, false, roof);
  if (cur.massing === 'veranda') veranda(k, r, hx, 0, z, hw, d, 0.24);
  if (cur.massing === 'porch') porch(k, r, hx, 0, z, hw, d, 0.24);
  if (!flat && (!styled || cur.chimney)) k.box(s * 0.02, H, z, 0.08, top - H + 0.1, 0.1, cur.chimney ? hex(cur.chimney[1]) : pick(r, BRICK));
  if (!styled) k.glowBox(hx + s * 0.18, 0.17, front + 0.02, 0.03, 0.04, 0.03, WHITE, [17.5 + r(), 22 + r(), 2], hex(cur.glow ?? 0xffc978));
};

// ---- barn -----------------------------------------------------------------------------------

/**
 * A dairy barn under a gambrel roof, end-on to the front: steep lower slopes to a knee and shallow
 * ones to the ridge, a hay hood over the loft door, a row of small stall windows and a cupola.
 */
const dairyBarn: Draw = (k, _W, _D, b, r) => {
  const white = r() < 0.25;
  const body = white ? hex(0xe8e4da) : pick(r, [0xc9463d, 0xb73e36, 0x8f3b2e]), trim = white ? hex(0x8f3b2e) : hex(0xf1e9dc);
  const roof = pick(r, [0x5a4a44, 0x6b7076, 0x4f5f52]);
  const W = 1.3, D = 1.24, H = 0.46, e = 0.05;
  k.box(0, 0, 0, W, H, D, body);
  // the gambrel, ridge running front to back
  const x0 = W / 2 + e, xk = 0.42, yk = H + 0.3, yr = H + 0.52, z0 = -D / 2 - e, z1 = D / 2 + e, I: P3 = [0, H + 0.15, 0];
  for (const sx of [-1, 1]) {
    k.quad([sx * x0, H, z0], [sx * x0, H, z1], [sx * xk, yk, z1], [sx * xk, yk, z0], roof, I);
    k.quad([sx * xk, yk, z0], [sx * xk, yk, z1], [0, yr, z1], [0, yr, z0], roof, I);
  }
  for (const sz of [-1, 1]) {
    const zz = sz * D / 2, A: P3 = [-W / 2, H, zz], B: P3 = [W / 2, H, zz], C: P3 = [xk - 0.01, yk, zz], P: P3 = [0, yr - 0.01, zz], E: P3 = [-xk + 0.01, yk, zz];
    k.tri(A, B, C, body, I);
    k.tri(A, C, P, body, I);
    k.tri(A, P, E, body, I);
  }
  // the hay hood over the loft door, the loft door and the big doors below
  k.gable(0, yr - 0.1, D / 2 + 0.08, 0.16, 0.08, 0.2, roof, body, true);
  k.box(0, H + 0.06, D / 2 + 0.01, 0.2, 0.24, 0.02, trim);
  k.box(0, 0, D / 2 + 0.01, 0.6, 0.42, 0.02, trim);
  k.box(0, 0.03, D / 2 + 0.02, 0.52, 0.36, 0.02, scale(body, 0.8));
  // stall windows down both sides
  for (const sx of [-1, 1]) for (const wz of [-0.34, 0, 0.34]) lit(k, b, r, sx * W / 2, 0.22, wz, 0.12, 0.06, sx > 0 ? 0 : 2);
  // the cupola on the ridge
  k.box(0, yr - 0.05, 0, 0.14, 0.15, 0.14, trim);
  k.hip(0, yr + 0.1, 0, 0.2, 0.12, 0.2, roof);
  k.glowBox(0, 0.46, D / 2 + 0.04, 0.05, 0.04, 0.04, hex(0xc9b27a), [18 + r(), 21 + r(), 1.6], WARM_GLOW);
};

/**
 * A threshing barn in tarred boards: a long low body under a hipped roof that sweeps nearly to the
 * ground, a tall gabled wagon porch standing out of the front slope and a lean-to shed down one end.
 */
const threshingBarn: Draw = (k, _W, _D, b, r) => {
  const board = pick(r, [0x3a3430, 0x4a3a30, 0x8f3b2e]), roof = pick(r, [0x9a5a3a, 0x6b6258, 0xb08a4a]);
  const s = r() < 0.5 ? 1 : -1, D = 1.24, H = 0.36, bw = 1.04, bx = -s * 0.16, lx = s * 0.52;
  k.box(bx, 0, 0, bw, H, D, board);
  // the hipped roof, ridge along x
  const e = 0.05, x0 = bx - bw / 2 - e, x1 = bx + bw / 2 + e, z1 = D / 2 + e, yr = H + 0.46, hi = 0.34, I: P3 = [bx, H + 0.1, 0];
  for (const sz of [-1, 1]) k.quad([x0, H, sz * z1], [x1, H, sz * z1], [x1 - hi, yr, 0], [x0 + hi, yr, 0], roof, I);
  k.tri([x0, H, -z1], [x0, H, z1], [x0 + hi, yr, 0], roof, I);
  k.tri([x1, H, -z1], [x1, H, z1], [x1 - hi, yr, 0], roof, I);
  // the lean-to down one end, open on the front
  k.box(lx, 0, 0, 0.32, 0.28, D - 0.04, scale(board, 1.15));
  const li = s * 0.36, lo = s * 0.7;
  k.quad([li, 0.52, -D / 2], [li, 0.52, D / 2], [lo, 0.3, D / 2], [lo, 0.3, -D / 2], roof, [lx, 0.1, 0]);
  k.box(lx, 0, D / 2 - 0.01, 0.24, 0.22, 0.01, hex(0x2a2420));
  // the wagon porch and its tall doors
  const px = bx - s * 0.08;
  k.box(px, 0, 0.44, 0.44, 0.62, 0.36, board);
  k.gable(px, 0.62, 0.44, 0.5, 0.24, 0.42, roof, board, true);
  k.box(px, 0, 0.63, 0.3, 0.5, 0.02, scale(board, 1.35));
  for (const wx of [-0.25, 0.25]) lit(k, b, r, bx + wx, 0.14, -D / 2, 0.1, 0.08, 3);
  k.glowBox(px, 0.54, 0.66, 0.05, 0.04, 0.04, hex(0xc9b27a), [18 + r(), 21 + r(), 1.6], WARM_GLOW);
  // straw bales stacked out front, under bumper height
  k.box(-s * 0.3, 0.004, 0.84, 0.36, 0.12, 0.16, hex(0xd9c07a));
};

// ---- silo -----------------------------------------------------------------------------------

/** Three corrugated grain bins under cone roofs, a dryer and a tall bucket leg spouting into each, a catwalk to the big one. */
const grainBins: Draw = (k, _W, _D, _b, r) => {
  const tin = pick(r, [0xc9ced1, 0xd8dcd6, 0xb9c0c4]), cap = scale(tin, 0.88);
  const bins: [number, number, number, number][] = [[-0.26, -0.25, 0.2, 0.62], [0.24, -0.26, 0.18, 0.5], [-0.27, 0.24, 0.18, 0.5]];
  for (const [x, z, rr, h] of bins) {
    k.cyl(x, 0, z, rr, h, tin, 8);
    k.cone(x, h, z, rr + 0.02, rr * 0.7, cap, 8);
  }
  // the dryer, the leg on it and its head
  const lx = 0.24, lz = 0.22, top = 1.4;
  k.box(lx, 0, lz + 0.02, 0.26, 0.3, 0.26, hex(0x6f7a80));
  k.box(lx, 0.3, lz, 0.07, top - 0.3, 0.07, METAL);
  k.box(lx, top, lz, 0.12, 0.08, 0.12, tin);
  for (const [x, z, rr, h] of bins) k.bar([lx, top, lz], [x, h + rr * 0.7, z], 0.014, METAL);
  k.bar([lx, 0.78, lz], [-0.26, 0.64, -0.25], 0.02, DARK);
};

/** A glass-lined tower silo in dark blue with a white band and a domed cap, its unloader chute, and a feed shed beside it. */
const towerSilo: Draw = (k, _W, _D, b, r) => {
  const blue = pick(r, [0x1f3f6a, 0x2a4a7a, 0x243a5a]);
  const sx = -0.2, sz = -0.18, R = 0.22, H = 1.5;
  k.cyl(sx, 0, sz, R, H, blue, 10);
  k.cyl(sx, 1.12, sz, R + 0.006, 0.07, WHITE, 10);
  k.dome(sx, H, sz, R, scale(blue, 1.25), 10, 2);
  k.box(sx + 0.155, 0, sz + 0.155, 0.05, H - 0.04, 0.05, WHITE);
  // the feed shed, in the town's colours
  const wall = styleWall(r), roof = styleRoof(r);
  k.box(0.22, 0, 0.1, 0.46, 0.32, 0.66, wall, cur.form === 'flat' ? scale(roof, 0.96) : wall);
  if (cur.form !== 'flat') k.gable(0.22, 0.32, 0.1, 0.52, 0.16, 0.72, roof, wall, true);
  k.box(0.22, 0, 0.435, 0.18, 0.22, 0.02, hex(0x5a3a28));
  lit(k, b, r, 0.45, 0.13, 0.1, 0.12, 0.08, 0);
  k.bar([sx + 0.12, 0.52, sz + 0.14], [0.04, 0.4, 0.02], 0.02, METAL);
  k.glowBox(0.22, 0.25, 0.46, 0.04, 0.03, 0.04, WHITE, [17.5 + r(), 22 + r(), 2], WARM_GLOW);
};

// ---- wind turbine ---------------------------------------------------------------------------

/** A flat strip from a to b, `u` its half-width, seen from both sides of the plane whose normal is n. */
function strip(k: Kit, a: P3, b: P3, u: P3, n: P3, col: RGB): void {
  const at = (p: P3, s: number): P3 => [p[0] + u[0] * s, p[1] + u[1] * s, p[2] + u[2] * s];
  const m: P3 = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2];
  for (const s of [-1, 1]) k.quad(at(a, -1), at(b, -1), at(b, 1), at(a, 1), col, [m[0] - n[0] * s * 0.05, m[1] - n[1] * s * 0.05, m[2] - n[2] * s * 0.05]);
}

/** An older turbine on a tapering steel lattice tower, a small three-blade rotor that spins faster, and a tail vane. */
const latticeTurbine: Draw = (k, _W, _D, b) => {
  const H = 2.1, lo = 0.2, hi = 0.05, mid = (lo + hi) / 2, steel = hex(0x9aa0a6), t = 0.012;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([sx * lo, 0, sz * lo], [sx * hi, H, sz * hi], 0.014, steel);
  // a zigzag of braces up each face and a girt round the middle
  for (let f = 0; f < 4; f++) {
    const c = Math.cos((f / 4) * TAU), sn = Math.sin((f / 4) * TAU);
    // on face f the wall runs along (-sn, c) at distance w out along (c, sn)
    const P = (w: number, along: number, y: number): P3 => [c * w - sn * along, y, sn * w + c * along];
    const n: P3 = [c, 0, sn], u: P3 = [-sn * t, t, c * t];
    strip(k, P(lo, -lo, 0), P(mid, mid, H / 2), u, n, steel);
    strip(k, P(mid, mid, H / 2), P(hi, -hi, H), u, n, steel);
    strip(k, P(mid, -mid, H / 2), P(mid, mid, H / 2), [0, t, 0], n, steel);
  }
  k.box(0, H, 0, 0.16, 0.02, 0.16, steel);
  k.box(0, H + 0.02, -0.04, 0.08, 0.08, 0.26, hex(0xe8e4dc));
  k.box(0, H + 0.02, -0.3, 0.012, 0.16, 0.18, WHITE);
  k.spin(0, H + 0.06, 0.1, 'z', 1.8 + (b.seed % 7) * 0.1, (s) => {
    s.dome(0, 0, 0, 0.04, WHITE, 6, 1);
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU + b.seed;
      s.bar([0, 0, 0], [Math.cos(a) * 0.8, Math.sin(a) * 0.8, 0], 0.022, WHITE);
    }
  });
};

/** A two-blade turbine on a tapering concrete tower with a door at its foot, a long nacelle and red-tipped blades. */
const concreteTurbine: Draw = (k, _W, _D, b) => {
  const H = 2.7, conc = hex(0xd8d4cc), seg = 8, r0 = 0.15, r1 = 0.07;
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    k.quad([Math.cos(a0) * r0, 0, Math.sin(a0) * r0], [Math.cos(a1) * r0, 0, Math.sin(a1) * r0], [Math.cos(a1) * r1, H, Math.sin(a1) * r1], [Math.cos(a0) * r1, H, Math.sin(a0) * r1], conc, [0, H / 2, 0]);
  }
  k.cyl(0, 0, 0, 0.19, 0.08, hex(0xb9b4aa), 8);
  k.box(0, 0.08, 0.14, 0.06, 0.14, 0.02, DARK);
  k.box(0, H - 0.02, -0.06, 0.13, 0.13, 0.4, WHITE);
  k.spin(0, H + 0.045, 0.16, 'z', 1.1 + (b.seed % 7) * 0.06, (s) => {
    s.box(0, -0.045, 0, 0.09, 0.09, 0.08, WHITE);
    const a = b.seed, c = Math.cos(a), sn = Math.sin(a), red = hex(0xd8453a);
    s.bar([c * 1.04, sn * 1.04, 0], [-c * 1.04, -sn * 1.04, 0], 0.035, WHITE);
    for (const d of [-1, 1]) s.bar([d * c * 0.88, d * sn * 0.88, 0], [d * c * 1.05, d * sn * 1.05, 0], 0.037, red);
  });
  k.glowBox(0, H + 0.11, -0.2, 0.04, 0.04, 0.04, hex(0x882222), [17, 30, 2.4], RED_LIGHT);
  k.box(0.26, 0, 0.22, 0.16, 0.18, 0.12, hex(0xb9bdc2));
};

// ---- windmill -------------------------------------------------------------------------------

/**
 * A post mill: the whole timber body (the buck) stands on a post over a squat brick roundhouse and
 * turns into the wind by the ladder-and-tail-pole out of its back, its four sails spread with canvas.
 */
const postMill: Draw = (k, _W, _D, b, r) => {
  const tar = r() < 0.4, body = tar ? hex(0x4a3a2e) : pick(r, [0xf4f1e8, 0xe8dcc0]), roof = tar ? hex(0xe8e4da) : hex(0x6b6f76);
  k.cyl(0, 0, 0, 0.3, 0.34, pick(r, BRICK), 8);
  k.cone(0, 0.34, 0, 0.34, 0.14, hex(0x5a4a44), 8);
  k.box(0, 0.4, 0, 0.08, 0.16, 0.08, WOOD);
  // the buck, its roof ridged front to back
  k.box(0, 0.54, 0.02, 0.42, 0.5, 0.5, body);
  k.gable(0, 1.04, 0.02, 0.46, 0.16, 0.54, roof, body, true);
  k.box(0, 0.56, -0.24, 0.12, 0.2, 0.02, DARK);
  win(k, b, r, 0.21, 0.8, 0.02, 0.1, 0.09, 0);
  win(k, b, r, -0.21, 0.8, 0.02, 0.1, 0.09, 2);
  // the ladder and tail pole down to the ground behind
  k.bar([0, 0.55, -0.24], [0, 0.02, -0.46], 0.03, WOOD);
  k.bar([0.06, 0.62, -0.24], [0.08, 0.04, -0.48], 0.015, TRUNK);
  const cloth = hex(0xe8dcc0);
  k.spin(0, 0.86, 0.3, 'z', 0.5, (s) => {
    s.cyl(0, -0.03, 0, 0.04, 0.06, DARK, 6);
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + 0.3, c = Math.cos(a), sn = Math.sin(a);
      s.bar([0, 0, 0.03], [c * 0.74, sn * 0.74, 0.03], 0.014, WOOD);
      // the canvas, seen from both faces
      const q0: P3 = [c * 0.2, sn * 0.2, 0.035], q1: P3 = [c * 0.74, sn * 0.74, 0.035];
      const q2: P3 = [c * 0.74 - sn * 0.11, sn * 0.74 + c * 0.11, 0.035], q3: P3 = [c * 0.2 - sn * 0.11, sn * 0.2 + c * 0.11, 0.035];
      for (const f of [-1, 1]) s.quad(q0, q1, q2, q3, cloth, [c * 0.45, sn * 0.45, 0.035 + f * 0.05]);
    }
  });
};

// ---- orchard --------------------------------------------------------------------------------

/**
 * An espalier orchard: fruit trees trained flat along wires in long hedge-like rows, blossom along
 * their tops out of summer and fruit on them in it, an open packing shed in one back corner, ladders
 * and crates of picked fruit.
 */
const espalier: Draw = (k, W, D, _b, r) => {
  const leaf = hex(0x4f8f40), blossom = hex(0xf2c4d8), fruit = pick(r, [0xe2412f, 0xf2a93b, 0xd8c83a]);
  const shx = -W / 2 + 0.5, shz = -D / 2 + 0.38;
  for (let z = -D / 2 + 0.35; z < D / 2 - 0.2; z += 0.42) {
    const x0 = z < shz + 0.4 ? shx + 0.55 : -W / 2 + 0.25, x1 = W / 2 - 0.25;
    const n = Math.max(1, Math.round((x1 - x0) / 0.5)), L = (x1 - x0) / n;
    const g0 = k.ground(x0, z), g1 = k.ground(x1, z);
    for (const [x, g] of [[x0, g0], [x1, g1]]) k.box(x, g - 0.02, z, 0.03, 0.28, 0.03, WOOD);
    k.bar([x0, g0 + 0.24, z], [x1, g1 + 0.24, z], 0.005, METAL);
    for (let i = 0; i < n; i++) {
      const x = x0 + L * (i + 0.5), y = k.ground(x, z) - 0.02;
      k.box(x, y, z, L * 0.94, 0.22, 0.09, i % 2 ? leaf : scale(leaf, 1.08));
      k.tagged(Vis.NotSummer, () => k.box(x, y + 0.22, z, L * 0.86, 0.03, 0.1, blossom));
      k.tagged(Vis.Summer, () => { for (const sz of [-1, 1]) k.box(x + sz * L * 0.2, y + 0.12, z + sz * 0.05, 0.04, 0.04, 0.02, fruit); });
    }
  }
  // the packing shed: a back wall, two posts and a roof, crates inside and a lamp
  const sy = k.ground(shx, shz) - 0.02;
  k.box(shx, sy, shz - 0.22, 0.76, 0.38, 0.05, WOOD);
  for (const sx of [-1, 1]) k.box(shx + sx * 0.35, sy, shz + 0.22, 0.04, 0.38, 0.04, WOOD);
  k.gable(shx, sy + 0.38, shz, 0.86, 0.14, 0.56, styleRoof(r), WOOD);
  for (let i = 0; i < 3; i++) k.box(shx - 0.2 + i * 0.15, sy, shz - 0.05, 0.12, 0.08 + (i % 2) * 0.08, 0.1, scale(WOOD, 1.15));
  k.glowBox(shx, sy + 0.3, shz - 0.18, 0.04, 0.04, 0.03, WHITE, [17.5 + r(), 21 + r(), 1.6], WARM_GLOW);
  // ladders against the rows, and crates of fruit at the row ends
  for (const [x, z] of [[W / 2 - 0.6, -D / 2 + 0.35 + 0.42], [0.1, D / 2 - 0.5]]) {
    const g = k.ground(x, z);
    for (const o of [-0.04, 0.04]) k.bar([x + o, g, z + 0.2], [x + o, g + 0.3, z + 0.07], 0.008, WOOD);
  }
  for (let i = 0; i < 3; i++) {
    const x = W / 2 - 0.2, z = -D / 2 + 0.5 + i * 0.16, g = k.ground(x, z);
    k.box(x, g, z, 0.12, 0.08, 0.12, WOOD, fruit);
  }
};

