import { CARRIAGE, RUNG } from './carriage';

/**
 * What a town gives the player at each rung of its carriage ladder (docs/standing.html), in words: the
 * town card lists what they have and what the next rung adds, and the fleet ticker names what they've just
 * won. The numbers live where they act: outlets.ts STANDING_OFF (3% a rung), the ferry fare (wire.ts
 * fareMul), the lot price (firms.ts discount), the levy (Carriage.levyMul), first refusal (firms.ts).
 */

/** Everything the player has in a town at this rung (and, at Territory, whether strong or contested). */
export function perksAt(rung: number, strong = false, contested = false): string[] {
  const out: string[] = [];
  if (rung >= RUNG.known) out.push(`${rung * 3}% off at its vehicle shops and dealers`);
  if (rung >= RUNG.regular) out.push('10% off ferries from its harbours');
  if (rung >= RUNG.trusted) out.push('10% off buying its buildings');
  if (rung >= RUNG.territory) {
    out.push(strong ? 'no levy on your loads here' : 'half the levy on your loads here');
    out.push(`first refusal on its new loads (${CARRIAGE.refusal} s before anyone else)`);
    out.push('your colours on its town hall and the maps');
    out.push(contested ? 'its ◆ diamonds (none while it is contested)' : `its ◆ diamonds every day${strong ? ', at the strong rate' : ''}`);
  }
  return out;
}

/** What reaching this rung adds, in a line. */
export function gainsAt(rung: number): string {
  switch (rung) {
    case RUNG.known: return '3% off at its shops and dealers';
    case RUNG.regular: return '10% off its ferries · 6% off at its shops';
    case RUNG.trusted: return '10% off its buildings · 9% off at its shops';
    case RUNG.territory: return 'half the levy · first refusal on its loads · 12% off at its shops · ◆ every day';
    default: return '';
  }
}
