/**
 * Marks, the game's side (docs/marks.html): what a player leaves in the shared world for others to come
 * across, and what comes back to them.
 *
 * - **Signs** (U): a two-part message on a post made from set words. Driving past one offers L for a heart,
 *   as on a work; its card takes one too, or takes it back. Loved signs are carved in stone.
 * - **Drift records**: the longest slide in each chunk of a county, painted on the ground in the holder's
 *   colours under a flag. Slide further there and it is repainted in yours.
 * - **Lap records**: a circuit's best hot lap, and its ghost, driven round with you on every lap you start.
 * - **Guestbooks**: stop by another player's HQ and your fleet signs its book; your own HQ's card shows who came.
 * - **Town holders**: a banner over each town a player holds, the town card's list of who has held it, and a
 *   GG to the fleet that took one from you.
 * - **Patrons**: rent at your doors, named by who paid it.
 * - **Picks**: the week's best, on the World tab (and the title screen, from online.json).
 */

interface MarksHost {
  islands(): Islands | null;
  home(): World | null;
  veh(): VehicleState | null;
  def(): VehicleDef;
  /** The model being driven, for a lap record's ghost. */
  model(): string;
  groupOf(w: World): THREE.Group | null;
  announce(title: string, body: string, ms?: number): void;
  /** Game hours, the server's clock. */
  hours(): number;
  /** In play, with nothing (a menu, a tool, a card) over it. */
  playing(): boolean;
  townName(key: string): string;
  circuitName(key: string): string;
  /** Where a circuit stands, world tiles, while it is in memory. */
  circuitSpot(key: string): { x: number; z: number } | null;
  /** The circuit's lot, for the server to check a lap's ghost against (game/circuits.ts lot). */
  circuitLot(key: string): number[] | null;
  /** The hot lap in hand (game/circuits.ts lapNow). */
  lap(): { key: string; name: string; w: World; t: number; running: boolean; valid: boolean; n: number } | null;
  /** Send the camera somewhere: a work, a lot, or just a point (world tiles). */
  fly(to: { work?: string; key?: string; name: string; x: number; z: number }): void;
  /** Another card is about to open: this one steps aside, and the other way about. */
  opened(): void;
}

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
const hex = (c: number): string => `#${(c & 0xffffff).toString(16).padStart(6, '0')}`;
const fmtLap = (t: number): string => `${Math.floor(t / 60)}:${(t % 60).toFixed(1).padStart(4, '0')}`;
/** A name tag's height on screen, pixels, at any distance. */
const TAG_PX = 34;
/** Tiles from the camera's focus within which signs' and drifts' tags show. */
const TAG_NEAR = 44;
/** Seconds a prompt stays up. */
const PROMPT_LIFE = 6;

type Card =
  | { kind: 'sign'; cell: string; id: string }
  | { kind: 'compose' }
  | { kind: 'drift'; cell: string; k: string }
  | { kind: 'gg'; town: string; by: Pid };

interface Drawn {
  group: THREE.Group; sig: string;
  /** Things a click picks: where they stand (world units) and what they are. */
  hits: { x: number; y: number; z: number; card: Card; tag?: number }[];
}

export class Marks {
  private signs = new Map<string, Record<string, SignRow>>();
  private drifts = new Map<string, Record<string, DriftRow>>();
  private laps = new Map<string, Record<string, LapRow>>();
  private guests = new Map<string, Record<string, GuestRow>>();
  private holders = new Map<string, Record<string, HolderRow>>();
  /** A version per cell, bumped when anything drawn from it changes. */
  private ver = new Map<string, number>();
  private drawn = new Map<World, Drawn>();
  /** Record ghosts, by circuit key, as the server last sent them. */
  private ghosts = new Map<string, { pts: GhostPt[]; by: Pid; s: number }>();
  private asked = new Set<string>();
  picks: Picks | null = null;
  onPicks: () => void = () => {};
  /** News about a postcard of mine came in (docs/postcards.html): the list is worth asking for again. */
  onPostcard: () => void = () => {};
  /** My best patrons in this world, as the server last said and as rent has come in since. */
  private patrons = new Map<Pid, number>();
  private away: { news: MarkNews[]; payers: [string, number][] } | null = null;

  private card = document.createElement('div');
  private open: Card | null = null;
  private compose: { p: number; w: number; two: boolean; j: number; p2: number; w2: number } = { p: 0, w: 0, two: false, j: 0, p2: 2, w2: 14 };
  private prompt = document.createElement('div');
  private promptT = 0;
  /** What L does while the prompt is up: a sign to leave a heart on. */
  private promptSign: { cell: string; id: string } | null = null;
  private prompted = new Set<string>();
  private lapChip = document.createElement('div');
  private tagUnit = 0.01;
  private inOverview = false;
  private focus = { x: 0, z: 0 };
  private ray = new THREE.Vector3();

  // driving
  private slide: { cell: string; w: World; pts: number[]; max: number; t: number } | null = null;
  private rec: { key: string; n: number; w: World; pts: GhostPt[] } | null = null;
  private ghost: { key: string; mesh: VehicleMesh; mats: THREE.Material[]; w: World; tag: THREE.Sprite } | null = null;
  private stay = { key: '', t: 0 };
  private signed = new Set<string>();
  private sampleT = 0;
  // rent, gathered into one line now and then
  private rentIn = new Map<Pid, { amt: number; at: Set<string> }>();
  private rentT = 0;
  private paidTold = new Map<string, number>();
  private guestTold: { who: string[]; stamp: number; t: number } | null = null;

  private mats = new Map<number, THREE.MeshLambertMaterial>();
  private postGeo = new THREE.BoxGeometry(0.06, 0.5, 0.06).translate(0, 0.25, 0);
  private boardGeo = new THREE.BoxGeometry(0.44, 0.24, 0.04);
  private slabGeo = new THREE.BoxGeometry(0.42, 0.5, 0.12).translate(0, 0.25, 0);
  private poleGeo = new THREE.CylinderGeometry(0.025, 0.025, 1.1, 6).translate(0, 0.55, 0);
  private flagGeo: THREE.BufferGeometry;
  private sprites = new Map<string, THREE.SpriteMaterial>();

  /**
   * The town banners' cards ("Your territory · held since day 2"), in the page over the game rather than drawn into
   * it: a sprite in the scene took the quality setting's resolution and the tilt-shift's blur, and buildings in front
   * cut through it (the user, 11 Nov 2026). Placed every frame in `view`.
   */
  private townTags = document.createElement('div');
  private tagPos = new THREE.Vector3();

  constructor(private online: Online, private host: MarksHost) {
    this.townTags.id = 'mark-towntags';
    document.body.append(this.townTags);
    this.card.id = 'mark-card';
    this.card.className = 'hud chip';
    this.card.hidden = true;
    this.card.addEventListener('pointerdown', (e) => {
      const t = e.target as HTMLElement;
      if (t instanceof HTMLSelectElement || t instanceof HTMLInputElement || t instanceof HTMLOptionElement) return;
      const b = t.closest('[data-act]') as HTMLElement | null;
      if (!b) return;
      e.preventDefault();
      this.act(b.dataset.act!, b.dataset);
    });
    this.card.addEventListener('change', (e) => this.composeChanged(e.target as HTMLElement));
    // the composer's lists keep their own keys
    for (const ev of ['keydown', 'keyup'] as const) this.card.addEventListener(ev, (e) => {
      const t = e.target as HTMLElement;
      if (!(t instanceof HTMLSelectElement || t instanceof HTMLInputElement)) return;
      e.stopPropagation();
      if (ev === 'keydown' && (e as KeyboardEvent).key === 'Escape') this.close();
    });
    this.prompt.id = 'mark-prompt';
    this.prompt.className = 'hud chip';
    this.prompt.hidden = true;
    this.prompt.addEventListener('pointerdown', (e) => {
      const b = (e.target as HTMLElement).closest('[data-stamp]') as HTMLElement | null;
      if (!b) return;
      e.preventDefault();
      this.online.post({ t: 'guest', k: b.dataset.k!, stamp: Number(b.dataset.stamp) });
      this.prompt.innerHTML = `📖 Signed with ${STAMPS[Number(b.dataset.stamp)]} <em>· thank you</em>`;
      this.promptT = Math.min(this.promptT, 1.6);
    });
    this.lapChip.id = 'lap-chip';
    this.lapChip.className = 'hud chip';
    this.lapChip.hidden = true;
    document.body.append(this.card, this.prompt, this.lapChip);
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute([0, 1.1, 0, 0, 0.82, 0, 0.42, 0.96, 0], 3));
    g.computeVertexNormals();
    this.flagGeo = g;
  }

  private get on(): boolean { return this.online.active && !!this.online.me; }
  private get me(): Pid { return this.online.me?.id ?? ''; }
  get cardOpen(): boolean { return !!this.open; }
  private name(pid: Pid): string { return pid === this.me ? 'You' : this.online.fleetName(pid); }
  private colour(pid: Pid): number { return (pid === this.me ? this.online.me : this.online.people.get(pid))?.brand?.primary ?? 0x7d8a92; }
  private accent(pid: Pid): number { return (pid === this.me ? this.online.me : this.online.people.get(pid))?.brand?.accent ?? 0xffffff; }
  private day(at: number): number { return Math.floor(at / 24) + 1; }
  private bump(k: string): void { this.ver.set(k, (this.ver.get(k) ?? 0) + 1); }

  /** The lap records held at once, at the circuits in memory: the Hot Lap deed. */
  private countHeld(): void {
    let n = 0;
    for (const rows of this.laps.values()) for (const r of Object.values(rows)) if (r.by === this.me) n++;
    deeds.best('lapsHeld', n);
  }

  // ---- what the server says ----------------------------------------------------------------------------

  welcome(w: Welcome): void {
    this.reset();
    const m = w.marks;
    if (!m) return;
    this.patrons = new Map(m.patrons);
    this.away = m.news.length || m.payers.length ? { news: m.news, payers: m.payers } : null;
  }

  reset(): void {
    for (const map of [this.signs, this.drifts, this.laps, this.guests, this.holders]) map.clear();
    this.ver.clear();
    this.ghosts.clear();
    this.asked.clear();
    this.prompted.clear();
    this.signed.clear();
    this.rentIn.clear();
    this.slide = null;
    this.rec = null;
    this.dropGhost();
    this.close();
    for (const d of this.drawn.values()) this.undraw(d);
    this.drawn.clear();
    this.lapChip.hidden = true;
    this.prompt.hidden = true;
  }

  /** The world is up: what happened to my marks while I was away, a card or two of it. */
  ready(): void {
    const a = this.away;
    this.away = null;
    if (!a) return;
    const cards: [string, string][] = [];
    if (a.payers.length) {
      const total = a.payers.reduce((s, [, v]) => s + v, 0);
      cards.push([`💵 ${money(total)} paid at your doors`, `While you were away: ${a.payers.slice(0, 4).map(([p, v]) => `${this.name(p)} ${money(v)}`).join(' · ')}`]);
    }
    // and the paper hears all of it (docs/newspaper.html)
    for (const n of a.news) this.toPress(n, true);
    const count = (what: MarkNews['what']) => a.news.filter((n) => n.what === what);
    const lost = [...count('lapLost'), ...count('driftLost')];
    if (lost.length) cards.push(['Records taken while you were away', lost.slice(0, 3).map((n) => this.newsLine(n)[1]).join(' · ')]);
    const guests = count('guest');
    if (guests.length) {
      const who = [...new Set(guests.map((n) => n.what === 'guest' ? this.name(n.by) : ''))];
      cards.push([`📖 ${guests.length} visitor${guests.length === 1 ? '' : 's'} to your HQ`, `${who.slice(0, 4).join(', ')}${who.length > 4 ? ` and ${who.length - 4} more` : ''} signed your guestbook`]);
    }
    const ups = count('signUp');
    if (ups.length) cards.push([`🪧 ♥ ${ups.length} heart${ups.length === 1 ? '' : 's'} on your signs`, ups.some((n) => n.what === 'signUp' && n.carved) ? 'One of them is carved in stone now: it stays.' : 'Other players liked what you wrote.']);
    for (const n of [...count('signFell'), ...count('townLost'), ...count('townWon'), ...count('gg'), ...count('named')].slice(0, 4)) cards.push(this.newsLine(n));
    const me = this.me;
    cards.forEach(([title, body], k) => setTimeout(() => { if (this.on && this.me === me) this.host.announce(title, body, 9000); }, 26000 + k * 9500));
    // a town lost while away still gets its GG card
    const tl = count('townLost').find((n) => n.what === 'townLost' && isPid(n.by));
    if (tl && tl.what === 'townLost') setTimeout(() => { if (this.on && this.me === me) this.show({ kind: 'gg', town: tl.town, by: tl.by }); }, 26000 + cards.length * 9500);
  }

  cell(k: string, doc: CellDoc): void {
    this.signs.set(k, { ...(doc.signs ?? {}) });
    this.drifts.set(k, { ...(doc.drifts ?? {}) });
    this.laps.set(k, { ...(doc.laps ?? {}) });
    this.countHeld();
    this.guests.set(k, { ...(doc.guests ?? {}) });
    this.holders.set(k, { ...(doc.holders ?? {}) });
    this.bump(k);
  }

  forget(k: string): void {
    for (const map of [this.signs, this.drifts, this.laps, this.guests, this.holders]) map.delete(k);
    this.ver.delete(k);
  }

  got(m: ServerMsg): boolean {
    switch (m.t) {
      case 'signRow': {
        const s = this.signs.get(m.c);
        if (s) { if (m.row) s[m.id] = m.row; else delete s[m.id]; this.bump(m.c); }
        if (this.open?.kind === 'sign' && this.open.id === m.id && this.open.cell === m.c) { if (m.row) this.render(); else this.close(); }
        return true;
      }
      case 'driftRow': { const d = this.drifts.get(m.c); if (d) { d[m.k] = m.row; this.bump(m.c); } return true; }
      case 'lapRow': {
        const l = this.laps.get(m.c);
        const key = `${m.c}#${m.k}`;
        // taken away (its ghost cut the track): no record there now, and no ghost to race
        if (!m.row) {
          if (l) delete l[m.k];
          this.ghosts.delete(key);
          if (this.ghost?.key === key) this.dropGhost();
          return true;
        }
        if (l) l[m.k] = m.row;
        this.countHeld();
        const g = this.ghosts.get(key);
        // a new record: its ghost is asked for again next time round
        if (g && (g.by !== m.row.by || Math.abs(g.s - m.row.s) > 0.01)) { this.ghosts.delete(key); this.asked.delete(key); }
        return true;
      }
      case 'ghost': this.ghosts.set(`${m.c}#${m.k}`, { pts: decodeGhost(m.g), by: m.by, s: m.s }); return true;
      case 'guestRow': { const g = this.guests.get(m.c); if (g) g[m.k] = m.row; return true; }
      case 'holderRow': { const h = this.holders.get(m.c); if (h) { h[m.town] = m.row; this.bump(m.c); } return true; }
      case 'mark': this.news(m.n, m.who); return true;
      case 'picks': this.picks = m.picks; this.onPicks(); this.picksToPress(m.picks); return true;
      default: return false;
    }
  }

  // ---- news ------------------------------------------------------------------------------------------

  /** A line of news about a mark of mine: its title and body. */
  private newsLine(n: MarkNews): [string, string] {
    switch (n.what) {
      case 'lapLost': return ['⏱ Your lap record fell', `${this.name(n.by)} went round ${this.host.circuitName(`${n.c}#${n.k}`)} in ${fmtLap(n.s)}, beating your ${fmtLap(n.was)}: their ghost is waiting`];
      case 'driftLost': return ['↯ Your drift record fell', `${this.name(n.by)} slid ${driftPoints(n.s)} points where your ${driftPoints(n.was)} stood: the ground is in their colours now`];
      case 'guest': return [`📖 ${this.name(n.by)} signed your guestbook ${STAMPS[n.stamp] ?? ''}`, 'They stopped by your HQ'];
      case 'signUp': return n.carved ? ['🪧 Your sign is carved in stone', `“${this.signTextOf(n.c, n.k)}” has ${MARKS.carveUp} hearts: it stays for good`] : [`♥ ${this.name(n.by)} left a heart`, `On your sign “${this.signTextOf(n.c, n.k)}”`];
      case 'signFell': return ['🪧 One of your signs came down', 'It is gone from the map'];
      case 'townLost': return [`🏴 ${this.name(n.by) === 'You' ? 'You' : this.name(n.by)} took ${this.host.townName(n.town)}`, isPid(n.by) ? 'It was your territory: they carry more of its trade now' : 'It was your territory'];
      case 'townWon': return [`🏴 ${this.host.townName(n.town)} is yours`, isPid(n.from) ? `You took it from ${this.name(n.from)}, and they’ve been told` : 'Its trade is mostly yours now'];
      case 'gg': return [`🤝 ${this.name(n.by)} ${n.back ? 'says they’ll be back' : 'says GG'}`, `For ${this.host.townName(n.town)}, which you took from them`];
      case 'named': return n.by === this.me
        ? ['🛣️ Your name stuck', `“${n.name}” is the name on the map now, as you suggested`]
        : ['🛣️ A work of yours has a name', `“${n.name}”, as ${this.name(n.by)} suggested`];
      case 'postcard': return n.ride
        ? ['📮 Your postcard brought someone in', `${n.ride} took a car from “${n.title}” · +5 likes`]
        : [`📮 “${n.title}” has been opened ${n.opens} times`, 'Every link you post brings people to the world'];
    }
  }

  /**
   * A line of news for the paper (docs/newspaper.html), told as it happens or from the away news. A town won or
   * lost in play is territory's to tell (game/territory.ts); from the away news it is told here.
   */
  private toPress(n: MarkNews, away: boolean): void {
    const by = (pid: string) => (isPid(pid) ? this.name(pid) : '');
    // names the game can't find come back as stand-ins ("A town", "the circuit", "your sign"): left out of print
    const town = (key: string) => { const s = this.host.townName(key); return s === 'A town' ? '' : s; };
    const circuit = (key: string) => { const s = this.host.circuitName(key); return s === 'the circuit' ? '' : s; };
    const sign = (c: string, k: string) => { const s = this.signTextOf(c, k); return s === 'your sign' ? '' : s; };
    switch (n.what) {
      case 'lapLost': press.write({ k: 'record', v: 'lap', who: 'you', f: { by: by(n.by), circuit: circuit(`${n.c}#${n.k}`), time: fmtLap(n.s), was: fmtLap(n.was) } }); break;
      case 'driftLost': press.write({ k: 'record', v: 'drift', who: 'you', f: { by: by(n.by), points: driftPoints(n.s), was: driftPoints(n.was) } }); break;
      case 'guest': press.write({ k: 'guest', who: 'you', f: { by: by(n.by) } }); break;
      case 'signUp': if (n.carved) press.write({ k: 'sign', v: 'carved', who: 'you', f: { text: sign(n.c, n.k) } }); else press.write({ k: 'hearts', who: 'you', f: { by: by(n.by) } }); break;
      case 'signFell': press.write({ k: 'sign', v: 'fell', who: 'you', f: {} }); break;
      case 'townLost': if (away && town(n.town)) press.write({ k: 'territoryLost', who: 'you', town: n.town, f: { town: town(n.town), to: by(n.by) } }); break;
      case 'townWon': if (away && town(n.town)) press.write({ k: 'territoryWon', who: 'you', town: n.town, f: { town: town(n.town), from: by(n.from) } }); break;
      case 'gg': press.write({ k: 'gg', ...(n.back ? { v: 'back' } : {}), who: 'you', f: { by: by(n.by), town: town(n.town) } }); break;
      case 'named': press.write({ k: 'named', ...(n.by === this.me ? { v: 'self' } : {}), who: 'you', f: { name: n.name, by: by(n.by) } }); break;
      case 'postcard': press.write(n.ride ? { k: 'postcard', v: 'ride', who: 'you', w: 3, f: { title: n.title, ride: n.ride } } : { k: 'postcard', v: 'opens', who: 'you', f: { title: n.title, opens: n.opens ?? 0 } }); break;
    }
  }

  /** The week's picks, once each: the player's own as their news, anyone else's near the player as the town's. */
  private picksToPress(p: Picks): void {
    for (const it of p.items) {
      const mine = it.by === this.me;
      const f = { label: PICK_LABEL[it.kind].toLowerCase(), detail: it.detail, by: it.who, title: it.title };
      const key = `pick|${p.from}|${it.kind}|${it.by}`;
      if (mine) press.once(key, { k: 'pick', v: 'you', who: 'you', w: 4, f });
      else if (it.x !== undefined && it.z !== undefined) press.once(key, { k: 'pick', who: it.who, at: { x: it.x, z: it.z }, f });
    }
  }

  private signTextOf(cell: string, key: string): string {
    const id = key.split('#')[1] ?? key;
    const s = this.signs.get(cell)?.[id];
    return s ? signText(s.m) : 'your sign';
  }

  private news(n: MarkNews, who?: Who): void {
    if (who) this.online.people.set(who.id, who);
    if (n.what === 'townLost' && isPid(n.by)) { this.show({ kind: 'gg', town: n.town, by: n.by }); return; }
    if (n.what === 'guest') {
      this.toPress(n, false);
      // visitors in quick succession are one line
      const g = this.guestTold && performance.now() - this.guestTold.t < 20000 ? this.guestTold : (this.guestTold = { who: [], stamp: n.stamp, t: performance.now() });
      const nm = this.name(n.by);
      if (!g.who.includes(nm)) g.who.push(nm);
      g.stamp = n.stamp;
      this.host.announce(g.who.length > 1 ? `📖 ${g.who.length} visitors signed your guestbook` : `📖 ${nm} signed your guestbook ${STAMPS[n.stamp] ?? ''}`, g.who.length > 1 ? g.who.join(', ') : 'They stopped by your HQ', 5000);
      return;
    }
    if (n.what === 'postcard') this.onPostcard();
    this.toPress(n, false);
    const [title, body] = this.newsLine(n);
    this.host.announce(title, body, n.what === 'signUp' && !n.carved ? 3500 : 7000);
  }

  // ---- rent, named -----------------------------------------------------------------------------------------

  /** Rent at one of my doors: gathered, and said every half a minute as who paid it. */
  rentFrom(key: string, amt: number, from: Pid | undefined): void {
    if (!from) return;
    const r = this.rentIn.get(from) ?? { amt: 0, at: new Set<string>() };
    r.amt += amt;
    const d = this.online.deeds.get(key);
    if (d?.name) r.at.add(d.name);
    this.rentIn.set(from, r);
    this.patrons.set(from, (this.patrons.get(from) ?? 0) + amt);
  }

  /** My trade paid rent at someone else's door: once in a while, a word that it did. */
  paid(key: string, _gross: number, owner: Pid): void {
    const t = performance.now();
    if (t - (this.paidTold.get(owner) ?? -1e9) < 240e3) return;
    this.paidTold.set(owner, t);
    const d = this.online.deeds.get(key);
    this.host.announce(`🏢 ${this.online.fleetName(owner)}’s door`, `${d?.name ? `${d.name} is theirs: they` : 'They'} take a share of the trade here, and see that it was yours`, 3200);
  }

  private flushRent(dt: number): void {
    this.rentT -= dt;
    if (this.rentT > 0 || !this.rentIn.size) return;
    this.rentT = 30;
    const rows = [...this.rentIn].sort((a, b) => b[1].amt - a[1].amt);
    this.rentIn.clear();
    const total = rows.reduce((s, [, r]) => s + r.amt, 0);
    const places = [...new Set(rows.flatMap(([, r]) => [...r.at]))];
    this.host.announce(`💵 ${money(total)} rent from ${rows.length === 1 ? this.name(rows[0][0]) : `${rows.length} fleets`}`,
      `${rows.slice(0, 3).map(([p, r]) => `${this.name(p)} ${money(r.amt)}`).join(' · ')}${places.length ? ` · at ${places.slice(0, 2).join(', ')}` : ''}`, 4200);
  }

  // ---- the HQ's card, and the town card ------------------------------------------------------------------

  /** The inspector's card for an HQ: its guestbook, and for my own, my patrons. */
  hqHtml(lotKey: string): string {
    if (!this.on) return '';
    const d = this.online.deeds.get(lotKey);
    if (!d || d.hq === undefined) return '';
    const [cell, id] = lotKey.split('#');
    const g = this.guests.get(cell)?.[id];
    let out = '<div class="markbook">';
    if (g?.n) {
      const last = [...g.list].reverse().slice(0, 6).map(([p, s, at]) => `<span>${STAMPS[s] ?? '👋'} <b data-pid="${esc(p)}">${esc(this.name(p))}</b> <small>day ${this.day(at)}</small></span>`).join('');
      out += `<p class="note">📖 <b>Guestbook</b> · ${g.n} visit${g.n === 1 ? '' : 's'} by ${g.by.length} fleet${g.by.length === 1 ? '' : 's'}</p><div class="stamps">${last}</div>`;
    } else out += `<p class="note">📖 Guestbook · ${d.by === this.me ? 'nobody has stopped by yet' : 'stop here a moment to sign it'}</p>`;
    if (d.by === this.me && this.patrons.size) {
      const top = [...this.patrons].sort((a, b) => b[1] - a[1]).slice(0, 5);
      out += `<p class="note">💵 <b>Patrons</b> · ${top.map(([p, v]) => `<span data-pid="${esc(p)}">${esc(this.name(p))}</span> ${money(v)}`).join(' · ')}</p>`;
    }
    return out + '</div>';
  }

  /** A town's holders as territory, newest first, as the town card names carriers (me as YOU). */
  holdersOf(townKey: string): { who: string; day: number }[] {
    const row = this.holders.get(townKey.split('#')[0])?.[townKey];
    if (!row?.length) return [];
    return [...row].reverse().map(([who, at]) => ({ who: who === this.me ? YOU : who, day: this.day(at) }));
  }

  // ---- every frame -----------------------------------------------------------------------------------

  frame(dt: number): void {
    if (!this.on) return;
    for (const w of this.worlds()) this.draw(w);
    for (const [w, d] of this.drawn) if (this.host.islands()?.at(w.cx, w.cz) !== w) { this.undraw(d); this.drawn.delete(w); }
    if (!this.prompt.hidden) { this.promptT -= dt; if (this.promptT <= 0) { this.prompt.hidden = true; this.promptSign = null; } }
    this.flushRent(dt);
    this.slideStep(dt);
    this.lapStep();
    this.sampleT -= dt;
    if (this.sampleT <= 0) { this.sampleT = 0.2; this.sample(); }
  }

  /** Every frame, the camera: the tags' size on screen, and whether the overview is up. */
  view(camera: THREE.Camera, overview: boolean, focus: { x: number; z: number }, play = true): void {
    // not playing (the title after signing out): nothing of the marks shows, the page's town cards included
    if (!play) overview = true;
    const lens = camera.projectionMatrix.elements[5] || 1;
    this.tagUnit = (2 * TAG_PX) / (window.innerHeight * lens);
    this.inOverview = overview;
    this.focus = focus;
    for (const d of this.drawn.values()) for (const o of d.group.children) {
      if (!(o instanceof THREE.Sprite)) continue;
      const near = Math.hypot(o.userData.gx - focus.x, o.userData.gz - focus.z) < (o.userData.far ?? TAG_NEAR);
      // a town banner's card is the page's (townTags): the sprite stays hidden and only says where it is
      const el = o.userData.el as HTMLElement | undefined;
      if (el) {
        o.visible = false;
        let show = !overview && near;
        if (show) {
          o.getWorldPosition(this.tagPos).project(camera);
          show = this.tagPos.z < 1 && Math.abs(this.tagPos.x) < 1.1 && Math.abs(this.tagPos.y) < 1.1;
          if (show) el.style.transform = `translate(${(((this.tagPos.x + 1) / 2) * window.innerWidth).toFixed(1)}px, ${(((1 - this.tagPos.y) / 2) * window.innerHeight).toFixed(1)}px) translate(-50%, -100%)`;
        }
        el.hidden = !show;
        continue;
      }
      o.visible = !overview && near;
      if (o.visible && o.scale.y !== this.tagUnit) o.scale.set(this.tagUnit * (o.userData.aspect as number), this.tagUnit, 1);
    }
  }

  private worlds(): World[] {
    const isles = this.host.islands();
    return isles ? [...isles.live.values()] : [];
  }

  /** Five times a second: a sign within reach, and an HQ being visited. */
  private sample(): void {
    const w = this.host.home(), v = this.host.veh();
    if (!w || !v || !this.host.playing()) return;
    const k = cellKey(w.cx, w.cz);
    // a sign within a couple of tiles: L leaves it a heart
    if (this.prompt.hidden) {
      for (const [id, s] of Object.entries(this.signs.get(k) ?? {})) {
        const key = `${k}#${id}`;
        if (s.by === this.me || this.prompted.has(key) || s.up.includes(this.me)) continue;
        if (Math.hypot((s.t % N) + 0.5 - v.x, Math.floor(s.t / N) + 0.5 - v.z) > 2.6) continue;
        this.prompted.add(key);
        this.promptSign = { cell: k, id };
        this.promptT = PROMPT_LIFE;
        this.prompt.innerHTML = `${s.carved ? '🪨' : '🪧'} <b>“${esc(signText(s.m))}”</b> <span class="by"><i class="dot" style="background:${hex(this.colour(s.by))}"></i>${esc(this.name(s.by))}</span> <kbd>L</kbd> <span class="hrt">♥</span> leave a heart`;
        this.prompt.hidden = false;
        break;
      }
    }
    // stopped by another player's HQ: their guestbook, signed
    const day = Math.floor(this.host.hours() / 24);
    let at = '';
    for (const [key, d] of this.online.deeds) {
      if (d.hq === undefined || d.by === this.me || !key.startsWith(`${k}#`) || this.signed.has(`${key}|${day}`)) continue;
      const near = (d.rects ?? []).some(([rx, rz, rw, rd]) => Math.max(rx - v.x, v.x - (rx + rw), rz - v.z, v.z - (rz + rd)) <= MARKS.guestReach);
      if (near) { at = key; break; }
    }
    if (!at || Math.abs(v.v) > 0.3) { this.stay = { key: at, t: 0 }; return; }
    if (this.stay.key !== at) this.stay = { key: at, t: 0 };
    this.stay.t += 0.2;
    if (this.stay.t < MARKS.guestStay) return;
    this.signed.add(`${at}|${day}`);
    this.online.post({ t: 'guest', k: at, stamp: 0 });
    const owner = this.online.deeds.get(at)!.by;
    this.promptSign = null;
    this.promptT = 8;
    this.prompt.innerHTML = `📖 You signed <b>${esc(this.online.fleetName(owner))}</b>’s guestbook 👋 <em>· or</em> ${STAMPS.slice(1).map((s, n) => `<button type="button" data-k="${esc(at)}" data-stamp="${n + 1}">${s}</button>`).join('')}`;
    this.prompt.hidden = false;
  }

  /** L: a heart for the sign the prompt names. */
  likeKey(): boolean {
    if (!this.on || this.prompt.hidden || !this.promptSign) return false;
    const { cell, id } = this.promptSign;
    this.online.post({ t: 'rate', c: cell, id, v: 1 });
    this.prompt.innerHTML = '<b class="hrt">♥</b> <em>thank you</em>';
    this.promptT = Math.min(this.promptT, 1.4);
    this.promptSign = null;
    return true;
  }

  // ---- drifts ----------------------------------------------------------------------------------------

  /** A slide under way: its line kept, and once the car is straight again, measured against the record here. */
  private slideStep(dt: number): void {
    const w = this.host.home(), v = this.host.veh();
    const slid = v instanceof CarState ? v.slide : 0;
    if (!w || !v || slid <= 0) {
      if (this.slide) this.slideDone();
      return;
    }
    const k = cellKey(w.cx, w.cz);
    if (this.slide && this.slide.w !== w) this.slide = null;
    if (!this.slide) this.slide = { cell: k, w, pts: [], max: 0, t: 0 };
    const s = this.slide;
    s.max = Math.max(s.max, slid);
    s.t -= dt;
    if (s.t <= 0 && s.pts.length < 800) {
      s.t = 0.08;
      s.pts.push(Math.max(0, Math.min(N * 4, Math.round(v.x * 4))), Math.max(0, Math.min(N * 4, Math.round(v.z * 4))));
    }
  }

  private slideDone(): void {
    const s = this.slide!;
    this.slide = null;
    if (s.max < MARKS.driftMin || s.pts.length < 4) return;
    // the line, cut down to the points the server keeps
    const n = s.pts.length / 2, keep = Math.min(MARKS.driftPts, n);
    const p: number[] = [];
    for (let j = 0; j < keep; j++) { const i = Math.round((j * (n - 1)) / Math.max(1, keep - 1)); p.push(s.pts[i * 2], s.pts[i * 2 + 1]); }
    const mid = Math.floor(p.length / 4) * 2;
    const ch = String(chunkOfTile(Math.min(N - 1, Math.floor(p[mid + 1] / 4)) * N + Math.min(N - 1, Math.floor(p[mid] / 4))));
    const rec = this.drifts.get(s.cell)?.[ch];
    const score = Math.round(s.max * 10) / 10;
    if (!rec || score > rec.s) {
      this.online.post({ t: 'drift', c: s.cell, s: score, p, m: this.host.model() });
      this.host.announce(`↯ Drift record · ${driftPoints(score)} points`, rec ? `${rec.by === this.me ? 'Your own' : `${this.name(rec.by)}’s`} ${driftPoints(rec.s)} beaten: the ground here is painted in your colours` : 'The first here: your line is painted on the ground under your flag', 5000);
    } else if (rec.by !== this.me) {
      this.host.announce(`↯ ${driftPoints(score)} points`, `The record here is ${driftPoints(rec.s)}, ${this.name(rec.by)}’s: follow their painted line`, 3000);
    }
  }

  // ---- laps and ghosts -------------------------------------------------------------------------------

  private lapStep(): void {
    const lap = this.host.lap();
    if (!lap) { this.lapChip.hidden = true; this.rec = null; this.dropGhost(); return; }
    const [cell, uid] = lap.key.split('#');
    const row = this.laps.get(cell)?.[uid];
    // the record's ghost, asked for as soon as the circuit is underfoot
    if (row && !this.ghosts.has(lap.key) && !this.asked.has(lap.key)) {
      this.asked.add(lap.key);
      // with the circuit's lot, so the server can check the record's ghost keeps to the track
      const lot = this.host.circuitLot(lap.key);
      this.online.post({ t: 'ghost', c: cell, k: uid, ...(lot ? { lot } : {}) });
    }
    // the lap's own line, kept for a record
    const w = this.host.home(), v = this.host.veh();
    if (lap.running && (!this.rec || this.rec.n !== lap.n || this.rec.key !== lap.key)) this.rec = { key: lap.key, n: lap.n, w: lap.w, pts: [] };
    if (!lap.running) this.rec = null;
    if (this.rec && w && v) {
      const x = w.ox + v.x - lap.w.ox, z = w.oz + v.z - lap.w.oz;
      while (this.rec.pts.length <= lap.t * MARKS.ghostHz && this.rec.pts.length < MARKS.ghostMax) this.rec.pts.push([x, z, v.heading]);
    }
    // the ghost goes round with you
    const g = this.ghosts.get(lap.key);
    if (lap.running && g?.pts.length) {
      if (!this.ghost || this.ghost.key !== lap.key) this.makeGhost(lap.key, lap.w, row?.m ?? 'tomato', g.by, g.s);
      const at = ghostAt(g.pts, lap.t);
      if (this.ghost && at) {
        const [x, z, h] = at;
        const y = heightAt(lap.w, Math.max(0, Math.min(N - 1, x)), Math.max(0, Math.min(N - 1, z)));
        this.ghost.mesh.holder.visible = this.ghost.tag.visible = true;
        this.ghost.mesh.root.position.set(x, y, z);
        this.ghost.mesh.root.rotation.set(0, h, 0);
        // its name over it, the same size on screen at any distance: a car is only a few pixels long
        this.ghost.tag.position.set(x, y + 0.7, z);
        this.ghost.tag.scale.set(this.tagUnit * 0.8 * (this.ghost.tag.userData.aspect as number), this.tagUnit * 0.8, 1);
      }
    } else if (this.ghost) this.ghost.mesh.holder.visible = this.ghost.tag.visible = false;
    // the chip: the clock and the record to beat
    const rec = row ? `Record <b>${fmtLap(row.s)}</b> <span class="by"><i class="dot" style="background:${hex(this.colour(row.by))}"></i>${esc(this.name(row.by))}</span>${g?.pts.length && lap.running ? ' · 👻 ghost' : ''}` : 'No record yet: <b>set one</b>';
    const html = `🏁 <span>${esc(lap.name)}</span> <span class="clock">${lap.running ? fmtLap(lap.t) : 'cross the line'}</span>${lap.running && !lap.valid ? '<em>cut</em>' : ''} · ${rec}`;
    if (this.lapChip.innerHTML !== html) this.lapChip.innerHTML = html;
    this.lapChip.hidden = !this.host.playing();
  }

  /** A clean lap of a circuit (from circuits.ts): a record, if it beats the one there, with its ghost. */
  lapDone(key: string, secs: number): void {
    if (!this.on) return;
    const [cell, uid] = key.split('#');
    const row = this.laps.get(cell)?.[uid];
    const rec = this.rec && this.rec.key === key ? this.rec : null;
    if (!row || secs < row.s - 0.005) {
      if (!rec || rec.pts.length < secs * MARKS.ghostHz * 0.6) return;
      const [cx, cz] = cellOfKey(cell);
      const spotAt = this.host.circuitSpot(key);
      const at = spotAt ? Math.max(0, Math.min(N - 1, Math.floor(spotAt.z - cz * N))) * N + Math.max(0, Math.min(N - 1, Math.floor(spotAt.x - cx * N))) : undefined;
      const lot = this.host.circuitLot(key);
      this.online.post({ t: 'lap', c: cell, k: uid, s: Math.round(secs * 100) / 100, m: this.host.model(), g: encodeGhost(rec.pts), ...(at !== undefined ? { at } : {}), ...(lot ? { lot } : {}) });
      // the next lap races this one
      this.ghosts.set(key, { pts: rec.pts.slice(), by: this.me, s: secs });
      this.dropGhost();
      setTimeout(() => this.host.announce(`🏁 Lap record · ${fmtLap(secs)}`, row ? `${row.by === this.me ? 'Your own' : `${this.name(row.by)}’s`} ${fmtLap(row.s)} beaten by ${(row.s - secs).toFixed(1)} s: your ghost is the one to beat now` : `The first record at ${this.host.circuitName(key)}: anyone who drives it races your ghost`, 6000), 1200);
    } else if (row.by !== this.me) {
      setTimeout(() => this.host.announce(`⏱ ${(secs - row.s).toFixed(1)} s off the record`, `${this.name(row.by)}’s ${fmtLap(row.s)} stands: their ghost is the faint car`, 3500), 1200);
    }
  }

  private makeGhost(key: string, w: World, model: string, by: Pid, secs: number): void {
    this.dropGhost();
    const g = this.host.groupOf(w);
    if (!g) return;
    let mesh: VehicleMesh;
    try { mesh = buildVehicleMesh(defOf(model)); } catch { return; }
    // see-through and unlit, washed toward its holder's colour, so it reads by day and by night alike
    const mats: THREE.Material[] = [];
    const tint = new THREE.Color(this.colour(by)).lerp(new THREE.Color(0xffffff), 0.35);
    mesh.holder.traverse((o) => {
      if (!(o instanceof THREE.Mesh)) return;
      const src = Array.isArray(o.material) ? o.material : [o.material];
      const out = src.map((m: THREE.Material) => {
        const base = 'color' in m && (m as THREE.MeshLambertMaterial).color ? (m as THREE.MeshLambertMaterial).color.clone() : new THREE.Color(0xffffff);
        const c = new THREE.MeshBasicMaterial({ color: base.lerp(tint, 0.6), transparent: true, opacity: 0.55, depthWrite: false, toneMapped: false, fog: false });
        mats.push(c);
        return c;
      });
      o.material = Array.isArray(o.material) ? out : out[0];
      o.castShadow = false;
      o.renderOrder = 5;
    });
    g.add(mesh.holder);
    const tag = this.tag([`👻 ${this.name(by)} · ${fmtLap(secs)}`], this.colour(by), 'drift');
    g.add(tag);
    this.ghost = { key, mesh, mats, w, tag };
  }

  private dropGhost(): void {
    if (!this.ghost) return;
    this.ghost.mesh.holder.removeFromParent();
    this.ghost.tag.removeFromParent();
    for (const m of this.ghost.mats) m.dispose();
    disposeVehicleMesh(this.ghost.mesh);
    this.ghost = null;
  }

  // ---- drawing ---------------------------------------------------------------------------------------

  private mat(c: number): THREE.MeshLambertMaterial {
    let m = this.mats.get(c);
    if (!m) this.mats.set(c, (m = new THREE.MeshLambertMaterial({ color: c, side: THREE.DoubleSide })));
    return m;
  }

  /** A tag over a mark: a line or two of text on a rounded card, its colour dot, the same size on screen at any distance. */
  private tag(lines: string[], dot: number | null, style: 'sign' | 'stone' | 'drift' | 'town'): THREE.Sprite {
    const text = `${style}|${dot}|${lines.join('|')}`;
    let m = lruGet(this.sprites, text);
    if (!m) {
      const c = document.createElement('canvas');
      const g = c.getContext('2d')!;
      const fonts = ['700 40px "IBM Plex Sans", "Segoe UI", sans-serif', '500 32px "IBM Plex Sans", "Segoe UI", sans-serif'];
      const widths = lines.map((l, n) => { g.font = fonts[Math.min(n, 1)]; return g.measureText(l).width; });
      const dotW = dot === null ? 0 : 36;
      c.width = Math.ceil(Math.max(...widths) + 48 + dotW);
      c.height = 30 + lines.length * 46;
      const bg = style === 'sign' ? '#f6ecd6' : style === 'stone' ? '#d9d8d2' : style === 'drift' ? 'rgba(31,43,51,.9)' : 'rgba(255,255,255,.94)';
      const ink = style === 'drift' ? '#ffffff' : '#1f2b33';
      g.fillStyle = bg;
      g.beginPath(); g.roundRect(3, 3, c.width - 6, c.height - 6, style === 'stone' ? 10 : 26); g.fill();
      if (style === 'sign' || style === 'stone') { g.strokeStyle = style === 'sign' ? '#8a6a45' : '#8c8b84'; g.lineWidth = 4; g.stroke(); }
      g.textBaseline = 'middle';
      if (dot !== null) { g.fillStyle = hex(dot); g.beginPath(); g.arc(30, 15 + 23, 11, 0, Math.PI * 2); g.fill(); }
      lines.forEach((l, n) => {
        g.font = fonts[Math.min(n, 1)];
        g.fillStyle = n ? (style === 'drift' ? '#c9d3d8' : '#5b676e') : ink;
        g.textAlign = 'left';
        g.fillText(l, 24 + dotW, 15 + 23 + n * 46);
      });
      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      m = new THREE.SpriteMaterial({ map: tex, depthWrite: false, sizeAttenuation: false, toneMapped: false, fog: false });
      m.userData.aspect = c.width / c.height;
      lruPut(this.sprites, text, m, 64, (old) => { old.map?.dispose(); old.dispose(); });
    }
    const s = new THREE.Sprite(m);
    s.center.set(0.5, 0);
    s.userData.aspect = m.userData.aspect;
    s.scale.set(this.tagUnit * (m.userData.aspect as number), this.tagUnit, 1);
    s.renderOrder = 6;
    return s;
  }

  private undraw(d: Drawn): void {
    d.group.removeFromParent();
    for (const o of d.group.children) (o.userData.el as HTMLElement | undefined)?.remove();
    d.group.traverse((o) => { if (o instanceof THREE.Mesh && o.userData.own) { o.geometry.dispose(); (o.material as THREE.Material).dispose(); } });
  }

  /** Signs, drift paint and flags, and town banners over an island, drawn again when any of them changes. */
  private draw(w: World): void {
    const parent = this.host.groupOf(w);
    if (!parent) return;
    const k = cellKey(w.cx, w.cz);
    let d = this.drawn.get(w);
    if (!d) { d = { group: new THREE.Group(), sig: '', hits: [] }; this.drawn.set(w, d); }
    if (d.group.parent !== parent) parent.add(d.group);
    const sig = `${this.ver.get(k) ?? 0}|${this.online.people.size}|${w.roadStamp}`;
    if (sig === d.sig) return;
    d.sig = sig;
    this.undraw(d);
    d.group = new THREE.Group();
    parent.add(d.group);
    d.hits = [];
    const put = (o: THREE.Object3D) => d!.group.add(o);
    const tagAt = (s: THREE.Sprite, x: number, y: number, z: number, far = TAG_NEAR) => {
      s.position.set(x, y, z);
      s.userData.gx = w.ox + x; s.userData.gz = w.oz + z; s.userData.far = far;
      s.visible = false;
      put(s);
    };
    // signs: a post with a board, or a stone slab once carved
    for (const [id, s] of Object.entries(this.signs.get(k) ?? {})) {
      const x = (s.t % N) + 0.72, z = Math.floor(s.t / N) + 0.72;
      if (!inB(Math.floor(x), Math.floor(z))) continue;
      const y = heightAt(w, x, z);
      const g = new THREE.Group();
      g.position.set(x, y, z);
      g.rotation.y = (s.t * 0.37) % Math.PI;
      if (s.carved) g.add(new THREE.Mesh(this.slabGeo, this.mat(0xb9b7ae)));
      else {
        const board = new THREE.Mesh(this.boardGeo, this.mat(0xc9a36a));
        board.position.y = 0.5;
        const band = new THREE.Mesh(this.boardGeo, this.mat(this.colour(s.by)));
        band.scale.set(1, 0.18, 1.2); band.position.y = 0.64;
        g.add(new THREE.Mesh(this.postGeo, this.mat(0x6b5a48)), board, band);
      }
      put(g);
      const card: Card = { kind: 'sign', cell: k, id };
      d.hits.push({ x: w.ox + x, y: y + 0.45, z: w.oz + z, card });
      const t = this.tag([signText(s.m), `${this.name(s.by)} · ♥ ${s.up.length}`], null, s.carved ? 'stone' : 'sign');
      tagAt(t, x, y + 0.85, z);
      d.hits.push({ x: w.ox + x, y: y + 0.85, z: w.oz + z, card, tag: t.userData.aspect as number });
    }
    // drift records: the line painted on the ground in the holder's colours, and a flag over its middle
    const pos: number[] = [], col: number[] = [];
    const c = new THREE.Color();
    for (const [ch, r] of Object.entries(this.drifts.get(k) ?? {})) {
      c.setHex(this.colour(r.by));
      const pts: [number, number][] = [];
      for (let j = 0; j + 1 < r.p.length; j += 2) pts.push([r.p[j] / 4, r.p[j + 1] / 4]);
      for (let j = 0; j + 1 < pts.length; j++) {
        const [ax, az] = pts[j], [bx, bz] = pts[j + 1];
        const dx = bx - ax, dz = bz - az, l = Math.hypot(dx, dz);
        if (l < 0.01 || l > 6) continue;
        const nx = -dz / l, nz = dx / l;
        for (const off of [-0.17, 0.17]) {
          const q = (px: number, pz: number, side: number): number[] => {
            const ex = px + nx * (off + side * 0.05), ez = pz + nz * (off + side * 0.05);
            return [ex, heightAt(w, Math.max(0, Math.min(N - 1, ex)), Math.max(0, Math.min(N - 1, ez))) + 0.035, ez];
          };
          const p0 = q(ax, az, -1), p1 = q(ax, az, 1), p2 = q(bx, bz, 1), p3 = q(bx, bz, -1);
          for (const p of [p0, p1, p2, p0, p2, p3]) { pos.push(...p); col.push(c.r, c.g, c.b); }
        }
      }
      const [mx, mz] = pts[Math.floor(pts.length / 2)] ?? [0, 0];
      if (!inB(Math.floor(mx), Math.floor(mz))) continue;
      const fx = mx + 0.5, fz = mz + 0.5, y = heightAt(w, Math.min(N - 1, fx), Math.min(N - 1, fz));
      const flag = new THREE.Group();
      flag.position.set(fx, y, fz);
      flag.add(new THREE.Mesh(this.poleGeo, this.mat(0xe9e6dd)), new THREE.Mesh(this.flagGeo, this.mat(this.colour(r.by))));
      put(flag);
      const card: Card = { kind: 'drift', cell: k, k: ch };
      d.hits.push({ x: w.ox + fx, y: y + 0.9, z: w.oz + fz, card });
      const t = this.tag([`↯ ${driftPoints(r.s)}`, this.name(r.by)], this.colour(r.by), 'drift');
      tagAt(t, fx, y + 1.2, fz, TAG_NEAR + 10);
      d.hits.push({ x: w.ox + fx, y: y + 1.2, z: w.oz + fz, card, tag: t.userData.aspect as number });
    }
    if (pos.length) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
      geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
      geo.computeVertexNormals();
      const m = new THREE.Mesh(geo, new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true, opacity: 0.8, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3, side: THREE.DoubleSide }));
      m.renderOrder = 3;
      m.userData.own = true;
      put(m);
    }
    // towns a player holds: a banner by the road nearest the middle of town
    for (const [town, row] of Object.entries(this.holders.get(k) ?? {})) {
      const who = row[row.length - 1]?.[0];
      if (!who || !isPid(who)) continue;
      const id = Number(town.split('#')[1]);
      const t = w.towns.find((x) => x.id === id);
      if (!t) continue;
      const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
      let best = -1, bd = Infinity;
      for (let dz = -10; dz <= 10; dz++) for (let dx = -10; dx <= 10; dx++) {
        const x = Math.floor(cx) + dx, z = Math.floor(cz) + dz;
        if (!inB(x, z) || !w.road[idx(x, z)]) continue;
        const dd = dx * dx + dz * dz;
        if (dd < bd) { bd = dd; best = idx(x, z); }
      }
      const bx = best >= 0 ? (best % N) + 1.1 : cx, bz = best >= 0 ? Math.floor(best / N) + 1.1 : cz;
      const y = heightAt(w, Math.min(N - 1, bx), Math.min(N - 1, bz));
      const banner = new THREE.Group();
      banner.position.set(bx, y, bz);
      banner.scale.setScalar(1.6);
      const flag = new THREE.Mesh(this.flagGeo, this.mat(this.colour(who)));
      const stripe = new THREE.Mesh(this.flagGeo, this.mat(this.accent(who)));
      stripe.scale.set(0.55, 0.45, 1); stripe.position.set(0, 0.5, 0.005);
      banner.add(new THREE.Mesh(this.poleGeo, this.mat(0xe9e6dd)), flag, stripe);
      put(banner);
      const since = row[row.length - 1][1];
      const tg = this.tag([who === this.me ? 'Your territory' : `${this.name(who)}’s territory`, `held since day ${this.day(since)}`], this.colour(who), 'town');
      tagAt(tg, bx, y + 2, bz, 110);
      // its card in the page (townTags, placed in view): crisp at any quality, never cut by a building
      const el = document.createElement('div');
      el.className = 'mk-tt';
      el.hidden = true;
      const mine = who === this.me;
      el.innerHTML = `<i style="background:${hex(this.colour(who))}"></i><span><b>${esc(mine ? 'Your territory' : `${this.name(who)}’s territory`)}</b><small>held since day ${this.day(since)}</small></span>`;
      tg.userData.el = el;
      this.townTags.append(el);
    }
  }

  // ---- clicks and the card ----------------------------------------------------------------------------

  /** A click on the world: a sign, a flag or their tags. True if it was one of these. */
  click(mx: number, my: number, camera: THREE.Camera): boolean {
    if (!this.on || this.inOverview) return false;
    let best: Card | null = null, bd = Infinity;
    for (const d of this.drawn.values()) for (const h of d.hits) {
      if (Math.hypot(h.x - this.focus.x, h.z - this.focus.z) > TAG_NEAR + 10) continue;
      this.ray.set(h.x, h.y, h.z).project(camera);
      if (this.ray.z > 1) continue;
      const px = ((this.ray.x + 1) / 2) * window.innerWidth, py = ((1 - this.ray.y) / 2) * window.innerHeight;
      let dd: number;
      if (h.tag) {
        const half = (TAG_PX * 1.2 * h.tag) / 2;
        dd = Math.abs(mx - px) <= half && my <= py && my >= py - TAG_PX * 2.4 ? 0 : Infinity;
      } else dd = Math.hypot(px - mx, py - my) < 20 ? Math.hypot(px - mx, py - my) : Infinity;
      if (dd < bd) { bd = dd; best = h.card; }
    }
    if (!best) return false;
    this.show(best);
    return true;
  }

  private show(c: Card): void {
    this.host.opened();
    this.open = c;
    this.card.hidden = false;
    this.render();
  }

  close(): void {
    this.open = null;
    this.card.hidden = true;
  }

  /** U: the sign composer, for the tile the car is on. */
  composeKey(): boolean {
    if (!this.on || !this.host.home() || !this.host.veh()) return false;
    if (this.open?.kind === 'compose') { this.close(); return true; }
    this.show({ kind: 'compose' });
    return true;
  }

  private render(): void {
    const c = this.open;
    if (!c) return;
    const x = '<button class="x" type="button" data-act="close" title="Close">×</button>';
    let html = '';
    if (c.kind === 'sign') {
      const s = this.signs.get(c.cell)?.[c.id];
      if (!s) { this.close(); return; }
      const mine = s.by === this.me, up = s.up.includes(this.me);
      html = `<header><span class="ic">${s.carved ? '🪨' : '🪧'}</span><b>“${esc(signText(s.m))}”</b><small>${s.carved ? 'Carved in stone' : 'A sign'} · day ${this.day(s.at)}</small></header>`
        + `<dl><dt>Put up by</dt><dd><i class="dot" style="background:${hex(this.colour(s.by))}"></i><b${mine ? '' : ` data-pid="${esc(s.by)}"`}>${esc(this.name(s.by))}</b></dd>`
        + `<dt>Hearts</dt><dd><b class="hrt">♥ ${s.up.length}</b></dd></dl>`
        + '<div class="acts">'
        + (mine ? '<button type="button" data-act="unsign">Take it down</button>'
          : `<button type="button" data-act="up" class="heart${up ? ' on' : ''}">${up ? '♥ Hearted · take it back' : '♥ Leave a heart'}</button>`)
        + '</div>'
        + `<p class="note">${s.carved ? 'Carved: it stays for good.' : `${MARKS.carveUp} hearts carve a sign in stone. Hearts are free, and <kbd>L</kbd> leaves one as you drive past.`}</p>`;
    } else if (c.kind === 'drift') {
      const r = this.drifts.get(c.cell)?.[c.k];
      if (!r) { this.close(); return; }
      html = `<header><span class="ic">↯</span><b>${driftPoints(r.s)}-point drift</b><small>The record for this patch · day ${this.day(r.at)}</small></header>`
        + `<dl><dt>Held by</dt><dd><i class="dot" style="background:${hex(this.colour(r.by))}"></i><b${r.by === this.me ? '' : ` data-pid="${esc(r.by)}"`}>${esc(this.name(r.by))}</b></dd>`
        + `<dt>Slid</dt><dd>${r.s.toFixed(1)} tiles sideways</dd></dl>`
        + `<p class="note">${r.by === this.me ? 'Yours: the painted line is your colours until somebody slides further here.' : 'Slide further anywhere on this patch (handbrake, <kbd>Space</kbd>) and the ground is painted in your colours.'}</p>`;
    } else if (c.kind === 'gg') {
      html = `<header><span class="ic">🏴</span><b>${esc(this.name(c.by))} took ${esc(this.host.townName(c.town))}</b><small>It was your territory</small></header>`
        + `<p class="note">They carry more of its trade than you now. Send them a word?</p>`
        + '<div class="acts"><button type="button" data-act="gg">🤝 GG</button><button type="button" data-act="back">💪 I’ll be back</button><button type="button" data-act="close">Say nothing</button></div>';
    } else {
      const s = this.compose;
      const phrase = (sel: number, act: string) => `<select data-c="${act}">${SIGN_PHRASES.map((p, n) => `<option value="${n}"${n === sel ? ' selected' : ''}>${esc(p.replace('{}', '___'))}</option>`).join('')}</select>`;
      let n = 0;
      const word = (sel: number, act: string) => `<select data-c="${act}">${SIGN_WORDS.map(([g, ws]) => `<optgroup label="${g}">${ws.map((w) => { const i = n++; return `<option value="${i}"${i === sel ? ' selected' : ''}>${esc(w)}</option>`; }).join('')}</optgroup>`).join('')}</select>`;
      const msg: SignMsg = s.two ? [s.p, s.w, s.j, s.p2, s.w2] : [s.p, s.w];
      const firstWord = word(s.w, 'w');
      n = 0;
      const secondWord = word(s.w2, 'w2');
      html = `<header><span class="ic">🪧</span><b>Put up a sign</b><small>Here, for every player who passes</small></header>`
        + `<div class="compose">${phrase(s.p, 'p')}${firstWord}`
        + `<label class="two"><input type="checkbox" data-c="two"${s.two ? ' checked' : ''}> and more</label>`
        + (s.two ? `<select data-c="j">${SIGN_JOINS.map((j, i) => `<option value="${i}"${i === s.j ? ' selected' : ''}>${j}</option>`).join('')}</select>${phrase(s.p2, 'p2')}${secondWord}` : '')
        + `</div><p class="preview">“${esc(signText(msg))}”</p>`
        + `<div class="acts"><button type="button" data-act="put" class="heart on">Put it up</button><button type="button" data-act="close">Cancel</button></div>`
        + `<p class="note">You may have ${MARKS.signsMax} up at once: a new one past that takes your oldest down. Others leave hearts on it; loved signs are carved in stone.</p>`;
    }
    this.card.innerHTML = x + html;
  }

  private composeChanged(t: HTMLElement): void {
    const k = (t as HTMLElement).dataset.c as keyof Marks['compose'] | undefined;
    if (!k || this.open?.kind !== 'compose') return;
    if (k === 'two') this.compose.two = (t as HTMLInputElement).checked;
    else this.compose[k] = Number((t as HTMLSelectElement).value);
    this.render();
  }

  private act(a: string, _data: DOMStringMap): void {
    const c = this.open;
    if (a === 'close') { this.close(); return; }
    if (c?.kind === 'sign') {
      const s = this.signs.get(c.cell)?.[c.id];
      if (!s) return;
      if (a === 'unsign') { this.online.post({ t: 'unsign', c: c.cell, id: c.id }); this.close(); return; }
      if (a !== 'up') return;
      const v = s.up.includes(this.me) ? 0 : 1;
      this.online.post({ t: 'rate', c: c.cell, id: c.id, v });
    } else if (c?.kind === 'gg' && (a === 'gg' || a === 'back')) {
      this.online.post({ t: 'gg', to: c.by, town: c.town, ...(a === 'back' ? { back: true } : {}) });
      this.host.announce(a === 'gg' ? '🤝 GG sent' : '💪 Message sent', `${this.name(c.by)} has been told`, 3000);
      this.close();
    } else if (c?.kind === 'compose' && a === 'put') {
      const w = this.host.home(), v = this.host.veh();
      if (!w || !v) return;
      const s = this.compose;
      this.online.post({ t: 'sign', c: cellKey(w.cx, w.cz), tile: idx(Math.floor(v.x), Math.floor(v.z)), m: s.two ? [s.p, s.w, s.j, s.p2, s.w2] : [s.p, s.w] });
      this.host.announce('🪧 Sign up', `“${signText(s.two ? [s.p, s.w, s.j, s.p2, s.w2] : [s.p, s.w])}”: you’ll hear when players like it`, 3500);
      this.close();
    }
  }

  // ---- picks -----------------------------------------------------------------------------------------

  askPicks(): void { this.online.post({ t: 'picks' }); }

  /** The World tab's head: the week's picks, each with Fly there. */
  picksHtml(): string {
    const p = this.picks ?? this.online.picks;
    if (!p?.items.length) return '';
    const when = new Date(p.from).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
    return `<div class="picks"><h4>${p.live ? 'This week' : 'Last week'} <small>from ${when}</small></h4><ul>${p.items.map((it, n) => pickLine(it, n)).join('')}</ul></div>`;
  }

  /** A press in the World tab that was a pick's. */
  press(t: HTMLElement): boolean {
    const b = t.closest('[data-pick]') as HTMLElement | null;
    if (!b) return false;
    const p = (this.picks ?? this.online.picks)?.items[Number(b.dataset.pick)];
    if (p) flyToPick(p, this.host.fly);
    return true;
  }
}

/** One pick as a line with Fly there; shared with the title screen. */
export function pickLine(it: Pick, n: number): string {
  // what the card is about: the vehicle for a lap or a drift (the title turns its model here), the fleet's own
  // shield for a fleet, the kind's mark otherwise; and the fleet's shield beside its name on every card
  const shield = it.brand ? badgeUrl({ logo: it.brand.logo, primary: it.brand.primary, accent: it.brand.accent }, 'shield') : '';
  const fleet = it.kind === 'growth' || it.kind === 'guests';
  const icon = it.model ? `<span class="pk pk-car" data-model="${esc(it.model)}">${iconOf(it)}</span>`
    : fleet && shield ? `<span class="pk"><img class="pk-shield" src="${shield}" alt=""></span>`
      : `<span class="pk">${iconOf(it)}</span>`;
  const mark = shield ? `<img class="pk-mini" src="${shield}" alt="">` : `<i class="dot" style="background:${hex(it.colour)}"></i>`;
  return `<li>${icon}<span class="what"><small>${esc(deskOf(it))}</small><b>${esc(it.title)}</b>`
    + `<small>${mark}${esc(it.who)} · ${esc(it.detail)}</small></span>`
    + (it.x !== undefined ? `<button type="button" class="link" data-pick="${n}">Fly there</button>` : '') + '</li>';
}

/**
 * A pick as a story on the centred title's newspaper (title/menu.ts picksCarousel): its kind as the kicker, its
 * title as the headline, the fleet as the byline, the vehicle (turning), the fleet's shield or the kind's mark
 * as the photo, and Fly there.
 */
export function pickStory(it: Pick, n: number): string {
  const shield = it.brand ? badgeUrl({ logo: it.brand.logo, primary: it.brand.primary, accent: it.brand.accent }, 'shield') : '';
  const fleet = it.kind === 'growth' || it.kind === 'guests';
  const photo = it.model ? `<div class="gz-photo pk-car" data-model="${esc(it.model)}">${iconOf(it)}</div>`
    : fleet && shield ? `<div class="gz-photo"><img class="gz-shield" src="${shield}" alt=""></div>`
      : `<div class="gz-photo">${iconOf(it)}</div>`;
  const mark = shield ? `<img class="pk-mini" src="${shield}" alt="">` : `<i class="dot" style="background:${hex(it.colour)}"></i>`;
  return `<article class="gz-story">${photo}<div class="gz-text"><div class="gz-kicker">${esc(kickerOf(it))}</div>`
    + `<h4 class="gz-head">${esc(it.title)}</h4><div class="gz-by">${mark}By ${esc(it.who)} · ${esc(it.detail)}</div>`
    + (it.x !== undefined ? `<button type="button" class="gz-fly" data-pick="${n}">Fly there →</button>` : '') + '</div></article>';
}

/** Send the camera to a pick: its work, its HQ, or the spot. */
export function flyToPick(p: Pick, fly: MarksHost['fly']): void {
  if (p.x === undefined || p.z === undefined) return;
  const isLot = !!p.k && /#b\d+$/.test(p.k);
  fly({ ...(p.k && !isLot && p.kind !== 'sign' ? { work: p.k } : {}), ...(isLot ? { key: p.k } : {}), name: p.title, x: p.x, z: p.z });
}

