import type { CargoType } from '../cargoTypes';

/**
 * Supply chains (docs/supplychains.html): the goods only a plant makes. None of these ever turns up on its own:
 * they are not in CARGO (so no timer, no demand, no mission, no town request, no passport line ever offers one),
 * only `cargoById` finds them, and only a plant the player owns puts one at its kerb (game/chains/plants.ts).
 * `from` names the kinds that make it, for the card; `to` the places that buy it besides the player's own plants
 * that take it in (those are found from the recipe book, not listed here). Values are `valueOf`'s: a finished
 * good is freight of 6–10 units wherever it can be, so heavy pay applies, and none tops $5,000 at face.
 * No made good goes to an airport or an international (the user, 7 Nov 2026: the jets take no part in chains).
 */
const M = (t: Omit<CargoType, 'ttl' | 'every' | 'max' | 'madeOnly'> & { ttl?: [number, number] }): CargoType => ({
  ttl: [160, 240], every: [99999, 99999], max: 0, madeOnly: true, ...t,
});

