import * as THREE from 'three';
import type { RailPath, World } from '../world/tiles';

/** Tiles a second the cog car climbs at: a slow, steady grind. */
const SPEED = 1.1;
/** Seconds it waits at each end before setting off again. */
const DWELL = 7;

interface Car { w: World; p: RailPath; s: number; dir: 1 | -1; wait: number; mesh: THREE.Group }

/**
 * The rack railways' cog cars (docs/geology.html): one little red railcar to each line, climbing from
 * the valley to the village and back all day, a pause at each end. A line of its own, so the car simply
 * shuttles; it keeps no timetable and nothing waits for it.
 */
export class RackShuttles {
  readonly root = new THREE.Group();
  private cars = new Map<RailPath, Car>();
  private body = new THREE.MeshStandardMaterial({ color: 0xc23a2c, roughness: 0.6 });
  private cream = new THREE.MeshStandardMaterial({ color: 0xf2e6c8, roughness: 0.7 });
  private glass = new THREE.MeshStandardMaterial({ color: 0x3a4a58, roughness: 0.2, emissive: 0x000000 });
  private dark = new THREE.MeshStandardMaterial({ color: 0x2a2a2e, roughness: 0.8 });
  private tmp = new THREE.Vector3();

  constructor() { this.root.name = 'rack shuttles'; }

  private build(): THREE.Group {
    const g = new THREE.Group();
    // a stepped body: the cog car's floor is level and its cabins climb in steps, like the real ones
    const add = (geo: THREE.BufferGeometry, m: THREE.Material, x: number, y: number, z: number) => {
      const mesh = new THREE.Mesh(geo, m);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      g.add(mesh);
    };
    add(new THREE.BoxGeometry(0.46, 0.08, 1.2), this.dark, 0, 0.1, 0);
    for (const [z, h] of [[-0.38, 0.36], [0, 0.42], [0.38, 0.48]] as const) {
      add(new THREE.BoxGeometry(0.44, h, 0.38), this.body, 0, 0.14 + h / 2, z);
      add(new THREE.BoxGeometry(0.45, 0.1, 0.36), this.glass, 0, 0.14 + h - 0.12, z);
      add(new THREE.BoxGeometry(0.45, 0.04, 0.39), this.cream, 0, 0.14 + h * 0.45, z);
    }
    add(new THREE.BoxGeometry(0.5, 0.04, 1.24), this.cream, 0, 0.66, 0.04);
    return g;
  }

  /**
   * Keep a car on every rack line in memory, drive them along, and drop the ones whose county has gone. A line the
   * player's own cog engine is on (`busy`, 0.7.0) is left to it: its shuttle stands down until the player has gone.
   */
  update(dt: number, worlds: World[], busy?: Set<RailPath>): void {
    const seen = new Set<RailPath>();
    for (const w of worlds) {
      for (const p of w.rails) {
        if (!p.key.startsWith('rack:') || p.length < 4 || busy?.has(p)) continue;
        seen.add(p);
        let c = this.cars.get(p);
        if (!c) {
          c = { w, p, s: 0.5, dir: 1, wait: DWELL * 0.5, mesh: this.build() };
          this.root.add(c.mesh);
          this.cars.set(p, c);
        }
        this.drive(c, dt);
      }
    }
    for (const [p, c] of this.cars) if (!seen.has(p)) { this.root.remove(c.mesh); this.cars.delete(p); }
  }

  private drive(c: Car, dt: number): void {
    if (c.wait > 0) c.wait -= dt;
    else {
      c.s += c.dir * SPEED * dt;
      const end = c.p.length - 0.6;
      if (c.s >= end) { c.s = end; c.dir = -1; c.wait = DWELL; }
      else if (c.s <= 0.6) { c.s = 0.6; c.dir = 1; c.wait = DWELL; }
    }
    const a = this.at(c, c.s - 0.4), b = this.at(c, c.s + 0.4);
    c.mesh.position.set((a.x + b.x) / 2, (a.y + b.y) / 2 + 0.02, (a.z + b.z) / 2);
    c.mesh.rotation.set(0, 0, 0);
    c.mesh.lookAt(this.tmp.set(b.x, b.y + 0.02, b.z));
  }

  private at(c: Car, s: number): { x: number; y: number; z: number } {
    const p = c.p, S = p.s, n = S.length;
    const v = Math.min(p.length, Math.max(0, s));
    let i = Math.min(n - 2, Math.max(0, Math.floor((v / (p.length || 1)) * (n - 1))));
    while (i > 0 && S[i] > v) i--;
    while (i < n - 2 && S[i + 1] < v) i++;
    const f = Math.min(1, Math.max(0, (v - S[i]) / (S[i + 1] - S[i] || 1)));
    return {
      x: c.w.ox + p.xz[i * 2] + (p.xz[i * 2 + 2] - p.xz[i * 2]) * f,
      y: p.y[i] + (p.y[i + 1] - p.y[i]) * f,
      z: c.w.oz + p.xz[i * 2 + 1] + (p.xz[i * 2 + 3] - p.xz[i * 2 + 1]) * f,
    };
  }
}
