import { N, type RailPath, type RailStation, type World } from '../world/tiles';
import { isBuiltRail } from '../world/railBuild';
import { townKey } from './ledger';

/** How near (tiles) a station's ground must come to a town's for it to count as that town's. */
const TOWN_NEAR = 6;

/** The town a station stands in: its own, else the town nearest its building's lot or its platform (-1 for none). */
function townOf(w: World, st: RailStation, p: RailPath): number {
  if (st.town >= 0) return st.town;
  const b = st.building;
  const mid = Math.floor(p.s.length / 2);
  const [cx, cz] = b ? [b.x + b.w / 2, b.z + b.d / 2] : [p.xz[mid * 2], p.xz[mid * 2 + 1]];
  let best = -1, bd = Infinity;
  for (let dz = -TOWN_NEAR; dz <= TOWN_NEAR; dz++) for (let dx = -TOWN_NEAR; dx <= TOWN_NEAR; dx++) {
    const tx = Math.floor(cx) + dx, tz = Math.floor(cz) + dz;
    if (tx < 0 || tz < 0 || tx >= N || tz >= N) continue;
    const t = w.townId[tz * N + tx], d = Math.hypot(dx, dz);
    if (t >= 0 && d < bd) { bd = d; best = t; }
  }
  return best;
}

/**
 * The towns the player has put on the railway (the On the Line deed, the user 2 Nov 2026): a station the player
 * built in a town the world gave none, joined by track the player laid to the lines the world was made with.
 * Joined means a walk from the station's platform along joins (a junction, a carried-on line, a parallel track
 * joined at its buffers) and over county lines (a laid track's two halves share a border key) reaches a path the
 * generator laid. Counted in the counties in memory; returns each such town's key (ledger.ts townKey).
 */
export function linkedTowns(worlds: World[]): string[] {
  // every path in memory by a key of its own; the joins between them both ways, and the halves met at a border
  const id = (w: World, k: number) => `${w.cx},${w.cz}:${k}`;
  const paths = new Map<string, { w: World; p: RailPath }>();
  const next = new Map<string, Set<string>>();
  const link = (a: string, b: string) => {
    (next.get(a) ?? next.set(a, new Set()).get(a)!).add(b);
    (next.get(b) ?? next.set(b, new Set()).get(b)!).add(a);
  };
  const borders = new Map<string, string[]>();
  for (const w of worlds) {
    w.rails.forEach((p, k) => {
      const me = id(w, k);
      paths.set(me, { w, p });
      for (const e of [p.start, p.end]) if (e.kind === 'join' && e.path !== undefined && w.rails[e.path]) link(me, id(w, e.path));
      if (p.key.startsWith('pb:')) (borders.get(p.key) ?? borders.set(p.key, []).get(p.key)!).push(me);
    });
  }
  for (const list of borders.values()) for (let i = 1; i < list.length; i++) link(list[0], list[i]);
  const out = new Set<string>();
  for (const w of worlds) {
    for (const st of w.stations) {
      const own = w.rails[st.path];
      const town = own && isBuiltRail(own) ? townOf(w, st, own) : -1;
      if (town < 0 || !w.towns[town]) continue;
      // a town the world gave a station of its own already has the railway
      if (w.stations.some((o) => o.town === town && w.rails[o.path] && !isBuiltRail(w.rails[o.path]))) continue;
      const key = townKey(w, w.towns[town]);
      if (out.has(key)) continue;
      const seen = new Set([id(w, st.path)]), queue = [id(w, st.path)];
      while (queue.length) {
        const at = queue.shift()!;
        const here = paths.get(at);
        if (here && !isBuiltRail(here.p)) { out.add(key); break; }
        for (const b of next.get(at) ?? []) if (!seen.has(b)) { seen.add(b); queue.push(b); }
      }
    }
  }
  return [...out];
}
