/**
 * The Passport (docs/passport.html): every achievement as a stamp in one book, drawn as a real passport since
 * 7 Oct 2026 (the user): a leather cover in the fleet's colours that swings open, a contents page inside it,
 * the holder's page, then pages of stamps pressed on at a slant (Sights: a style, a biome, a size of town, a
 * wonder, a landform, a building; then the signature buildings by style), the visa pages (the deeds, a page a
 * group), Imports (the home town's culture) and Bookmarks. Pages turn one leaf at a time about the spine;
 * ribbons down the fore-edge jump to a chapter. Built into the title menu's panel, so it shares its keys:
 * left and right turn the pages, up and down move between stamps, 1–9 open a visa page, Enter opens a stamp.
 */

type Button = (text: string, cls: string, key: string, run: () => void, group?: string) => HTMLButtonElement;
type Section = 'sights' | 'visas' | 'imports' | 'marks';

export interface DeedsView {
  group: number;
  /** The deed whose row is open. */
  open: string | null;
  section?: Section;
  page?: SightPage;
  /** The stamp whose details are open, as "page:key". */
  stamp?: string | null;
  /** The spread the book lies open at (a page at a time on a narrow screen); unset: the holder's page, or the section's first. */
  spread?: number;
  /** The book lies shut, its cover showing: it opens of itself a moment after. */
  closed?: boolean;
  /** Open at this achievement's visa page, its row picked out (from a notification of it: docs/passport.html). */
  deed?: string | null;
}

/** What the book asks of a game in play; null from the title, where there is no world to look at. */
interface BookHost {
  /**
   * The fleet's culture books (docs/culturegate.html): every town with a book or a hall, the HQ's town first, then
   * the towns held, then towns once held; or why there is none.
   */
  imports(): { towns: ImportTown[]; why: string; waiting: Crate[]; aboard: Crate[]; room: string } | null;
  /** Where the player is: the cell, and the spot in it. */
  here(): { cx: number; cz: number; x: number; z: number } | null;
  /** Close the book and open the map on a place. */
  showOnMap(at: { cx: number; cz: number; x: number; z: number; label: string }): void;
}
export const book: { host: BookHost | null } = { host: null };


/** Five pips, filled in their tier's colour up to the tier reached, the next one hollow. */
function pips(tier: number): HTMLElement {
  const row = el('span', 'dd-pips');
  for (let k = 0; k < 5; k++) {
    const p = el('i', k < tier ? 'on' : k === tier ? 'next' : '');
    p.style.setProperty('--c', TIER_COLOURS[k]);
    row.append(p);
  }
  return row;
}

const date = (t: number): string => (t ? new Date(t).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : 'before records began');
const N = 256;
const tilesBetween = (a: { cx: number; cz: number; x: number; z: number }, b: { cx: number; cz: number; x: number; z: number }): number =>
  Math.round(Math.hypot((b.cx - a.cx) * N + b.x - a.x, (b.cz - a.cz) * N + b.z - a.z));
const farText = (b: { cx: number; cz: number; x: number; z: number }): string => {
  const me = book.host?.here();
  if (!me) return `cell ${b.cx}, ${b.cz}`;
  const d = tilesBetween(me, b);
  return d < 2 * N ? `${d} tiles away` : `${Math.round(d / N)} cells away`;
};

/** The line under a deed's bar: 2,480 / 10,000 tiles · Gold, 12 of 29 · Platinum at 22, or Diamond · 14 Sep 2026. */
function deedLine(d: Deed): string {
  const t = deeds.tier(d), v = deeds.value(d);
  if (t >= 5) return `Diamond · ${date(deeds.dates(d)[4] ?? 0)}`;
  const next = TIERS[t];
  if (d.kind === 'set') return `${v.toLocaleString('en-US')}${d.of ? ` of ${d.of}` : ''} · ${next} at ${d.ladder[t].toLocaleString('en-US')}`;
  if (d.kind === 'best') return `best ${amount(d, v)} · ${next} at ${amount(d, d.ladder[t])}`;
  const unit = d.unit === '$' ? '' : ` ${d.unit}`;
  const money = d.unit === '$' ? '$' : '';
  return `${money}${v.toLocaleString('en-US')} / ${money}${d.ladder[t].toLocaleString('en-US')}${unit} · ${next}`;
}

/** How a sight's stamp was come by, before the place's name. */
const HOW: Record<SightPage, string> = {
  arch: 'driving into', size: 'driving into', biome: 'standing in it near', wonder: 'reaching it at', landform: 'driving into it at', kind: 'passing one in', event: 'being there for it in',
};
/** How rare a stamp is: a style's own building, a wonder, or an ordinary sight (nothing said). */
function rarity(p: SightPage, key: string): string {
  if (p === 'kind') {
    const style = SIGNATURE_STYLE.get(key as BuildingKind);
    return style ? `a ${ARCH_LABEL[style]} signature building · only ${ARCH_LABEL[style]} towns build it` : '';
  }
  if (p === 'wonder') return 'a wonder · one to a county, at most';
  if (p === 'size' && (key === 'mega' || key === 'metro')) return key === 'mega' ? 'the biggest a town gets' : 'a big city';
  return '';
}


/** The stamp a sight is shown by in the Passport (game/passportStamps.ts). */
const stampArt = (p: SightPage, key: string): string => sightStamp(p, key, stampLabel(p, key), p === 'kind' ? SIGNATURE_STYLE.get(key as BuildingKind) : undefined);

const STAMP_KIND: Record<SightPage, MarkKind> = { arch: 'town', biome: 'biome', size: 'town', wonder: 'wonder', landform: 'landform', kind: 'building', event: 'place' };

// ---- the book: a cover that swings open, pages that turn, stamps pressed onto the pages ----

/** A chapter of the book: the holder's page, a page of sights, the signature buildings, the visas, imports, bookmarks. */
type Chapter = 'contents' | 'data' | SightPage | 'sig' | 'visas' | 'imports' | 'marks' | 'notes';
interface Page {
  ch: Chapter;
  title: string;
  /** Right of the title: how many of the chapter are stamped. */
  count?: string;
  /** A small line under the title. */
  sub?: string;
  /** The body scrolls (imports, bookmarks): what is on it can run longer than a page. */
  scroll?: boolean;
  /** The achievements on a visa page, by id. */
  deeds?: string[];
  /** The seal the page's chapter earns when every stamp in it is in (game/passportRewards.ts). */
  seal?: SealId;
  draw(body: HTMLElement): void;
}
/** The chapters with a ribbon down the book's edge, in order, with the section each belongs to. */
const CHAPTERS: { ch: Chapter; icon: string; label: string; section: Section }[] = [
  { ch: 'data', icon: '🪪', label: 'Holder', section: 'sights' },
  ...SIGHT_PAGES.map((p) => ({ ch: p as Chapter, icon: PAGE_ICON[p], label: PAGE_LABEL[p], section: 'sights' as Section })),
  { ch: 'sig', icon: '🏛️', label: 'Signatures', section: 'sights' },
  { ch: 'visas', icon: '🛂', label: 'Visas', section: 'visas' },
  { ch: 'imports', icon: '🎎', label: 'Imports', section: 'imports' },
  { ch: 'marks', icon: '⭐', label: 'Bookmarks', section: 'marks' },
];
const SECTION_START: Record<Section, Chapter> = { sights: 'arch', visas: 'visas', imports: 'imports', marks: 'marks' };
const SIGHT_DEED: Record<SightPage, string> = { arch: 'styles', biome: 'biomes', size: 'sizes', wonder: 'wonders', landform: 'landforms', kind: 'kinds', event: 'events' };

/** What the menu asks of the open book: turn a page (false when there is no book, or it is busy turning). */
export const passportNav: { flip(dir: 1 | -1): boolean; digit(n: number): boolean } = { flip: () => false, digit: () => false };

/** A steady number from a string, for where a stamp lands and how it is turned. */
function hashOf(s: string): number {
  let h = 2166136261;
  for (let k = 0; k < s.length; k++) h = Math.imul(h ^ s.charCodeAt(k), 16777619);
  return h >>> 0;
}

/** The size of a page, and how many stamps one holds, for this window. */
function bookSize(): { w: number; h: number; two: boolean; cols: number; rows: number; cell: number } {
  let h = Math.round(Math.max(380, Math.min(600, window.innerHeight - 190)));
  let w = Math.round(h * 0.7);
  // two pages side by side when there is room for them and a ribbon open beside them (its label reads to the right)
  const room = Math.floor((window.innerWidth - 420) / 2);
  const two = room >= 270;
  if (two && room < w) { w = room; h = Math.min(h, Math.round(w / 0.66)); }
  if (!two) {
    // one page at a time, on a narrow screen: a page as wide as there is room for, and no taller than a page that wide
    // (on a phone the ribbons are icons only; anything wider keeps their names beside the page)
    w = Math.max(240, Math.min(w, window.innerWidth - (window.innerWidth > 600 ? 180 : 84)));
    h = Math.max(340, Math.min(h, Math.round(w * 1.42)));
  }
  const cols = w >= 330 ? 3 : 2;
  const cell = w >= 330 ? 122 : 108;
  const rows = Math.max(1, Math.floor((h - 104) / cell));
  return { w, h, two, cols, rows, cell };
}

const hexCol = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;
/** A colour darkened toward black by f (0..1): the leather of the cover. */
function darker(c: number, f: number): string {
  const r = (c >> 16) & 255, g = (c >> 8) & 255, b = c & 255;
  return `rgb(${Math.round(r * (1 - f))}, ${Math.round(g * (1 - f))}, ${Math.round(b * (1 - f))})`;
}

/** Who the book belongs to: the player, and their fleet's name, colours and logo when there is one. */
interface BookOwner { id?: string; name: string; colour: number; fleet?: { name: string; primary: number; accent: number; logo: string } | null }

export function buildDeeds(panel: HTMLElement, view: DeedsView, who: BookOwner, button: Button, rerender: (key?: string) => void): void {
  const size = bookSize();
  // the fleet's brand as the menu has it, else as the game in play has it
  if (!who.fleet && playerBrand.current) who = { ...who, fleet: playerBrand.current };
  const pages = bookPages(view, who, button, rerender, size);
  const at = (ch: Chapter): number => Math.max(0, pages.findIndex((p) => p.ch === ch));
  const spreadOf = (i: number): number => (size.two ? i >> 1 : i);
  const last = spreadOf(pages.length - 1);
  // asked for an achievement: the visa page it is on; else the section's first page, or the holder's
  const deedPage = view.deed ? pages.findIndex((p) => !!p.deeds?.includes(view.deed!)) : -1;
  if (view.spread === undefined) view.spread = spreadOf(deedPage >= 0 ? deedPage : view.section ? at(SECTION_START[view.section]) : at('data'));
  view.spread = Math.max(0, Math.min(last, view.spread));
  /** The pages a spread shows: left and right side by side, or the one page. */
  const shown = (s: number): [number, number] => (size.two ? [s * 2, s * 2 + 1] : [-1, s]);

  const wrap = el('div', 'pb-wrap');
  wrap.style.setProperty('--pw', `${size.w}px`);
  wrap.style.setProperty('--ph', `${size.h}px`);
  wrap.style.setProperty('--cell', `${size.cell}px`);
  const leather = who.fleet ? darker(who.fleet.primary, 0.45) : '#5b1f2c';
  wrap.style.setProperty('--leather', leather);
  wrap.style.setProperty('--fleet', who.fleet ? hexCol(who.fleet.primary) : '#7a2a3a');
  wrap.style.setProperty('--fleet2', who.fleet ? hexCol(who.fleet.accent) : '#e3c27a');
  const stage = el('div', 'pb-stage');
  const bookEl = el('div', `pb-book ${size.two ? 'two' : 'one'}`);
  const boards = el('div', 'pb-boards');
  const slotL = el('div', 'pb-slot l'), slotR = el('div', 'pb-slot r');
  bookEl.append(boards, slotL, slotR);
  stage.append(bookEl);

  // a page, drawn fresh: its header, its body and its number
  const pageEl = (i: number): HTMLElement => {
    const pg = el('div', 'pb-page');
    if (i < 0 || i >= pages.length) { pg.classList.add('blank'); return pg; }
    const p = pages[i];
    pg.classList.add(`ch-${p.ch}`);
    if (p.ch !== 'contents' && p.ch !== 'data' && p.ch !== 'notes') {
      const head = el('div', 'pb-head');
      const t = el('b', '', p.title);
      head.append(t);
      if (p.count) head.append(el('em', '', p.count));
      if (p.seal) head.append(sealMark(p.seal));
      pg.append(head);
      if (p.sub) pg.append(el('div', 'pb-sub', p.sub));
    }
    const body = el('div', `pb-body${p.scroll ? ' scroll' : ''}`);
    p.draw(body);
    pg.append(body);
    if (i > 0) pg.append(el('div', 'pb-num', String(i)));
    return pg;
  };
  const fill = (slot: HTMLElement, i: number): void => { slot.replaceChildren(pageEl(i)); };
  const paint = (s: number): void => {
    const [l, r] = shown(s);
    if (size.two) fill(slotL, l);
    fill(slotR, r);
  };

  // the ribbons down the fore-edge: one a chapter, the one open standing out
  const ribbons = el('div', 'pb-ribbons');
  const ribbonFor = new Map<Chapter, HTMLButtonElement>();
  for (const c of CHAPTERS) {
    if (!pages.some((p) => p.ch === c.ch)) continue;
    const b = button('', 'pb-ribbon', `rib-${c.ch}`, () => turnTo(spreadOf(at(c.ch))), 'ribbons');
    b.append(el('i', '', c.icon), el('span', '', c.label));
    b.setAttribute('aria-label', c.label);
    ribbons.append(b);
    ribbonFor.set(c.ch, b);
  }
  // on the book itself, at its fore-edge: they stick out past the pages, wherever the book stands
  bookEl.append(ribbons);

  // under the book: back a page, where we are, on a page
  const nav = el('div', 'pb-nav');
  const prev = button('‹ Back a page', 'link pb-turn', 'pb-prev', () => turnTo((busy ? goal : view.spread ?? 0) - 1), 'turns');
  const next = button('On a page ›', 'link pb-turn', 'pb-next', () => turnTo((busy ? goal : view.spread ?? 0) + 1), 'turns');
  const where = el('span', 'pb-where');
  nav.append(prev, where, next);

  const settle = (): void => {
    const s = view.spread ?? 0;
    const [l, r] = shown(s);
    // the chapter open is the right page's, unless that is the ruled page facing the last
    const page = pages[r] && pages[r].ch !== 'notes' ? pages[r] : pages[l];
    const ch = page?.ch ?? 'data';
    const sect = CHAPTERS.find((c) => c.ch === ch)?.section;
    if (sect && ch !== 'data') view.section = sect;
    for (const [c, b] of ribbonFor) b.classList.toggle('on', c === ch);
    const nums = [l, r].filter((i) => i > 0 && i < pages.length);
    where.textContent = view.closed ? 'Closed' : nums.length ? `page${nums.length > 1 ? 's' : ''} ${nums.join('–')} of ${pages.length - 1}` : 'Inside cover';
    prev.disabled = s <= 0 || !!view.closed;
    next.disabled = s >= last || !!view.closed;
  };

  // ---- the cover ----
  const cover = (): HTMLElement => {
    const c = el('div', 'pb-cover');
    c.append(el('div', 'pb-cv-top', 'PASSPORT'), el('div', 'pb-cv-sub', 'TINYFLEET · FREE ROADS'));
    // the fleet's own badge, in its own colours, set in a gold ring: the logo on the disc of the accent
    const seal = el('div', 'pb-cv-seal');
    if (who.fleet) {
      const p = badgePaint(who.fleet.primary, who.fleet.accent);
      const badge = el('div', 'pb-cv-badge fleet-badge', who.fleet.logo);
      badge.style.background = p.disc;
      badge.style.color = p.glyph;
      badge.style.boxShadow = `inset 0 0 0 calc(var(--pw) * .018) ${p.ring}, inset 0 -6px 14px rgba(0,0,0,.18), 0 2px 6px rgba(0,0,0,.45)`;
      seal.classList.add('branded');
      seal.append(badge);
    } else seal.append(el('span', '', '★'));
    c.append(seal, el('div', 'pb-cv-name', (who.fleet?.name ?? who.name).toUpperCase()));
    const chip = el('div', 'pb-cv-chip');
    chip.append(el('i'));
    c.append(chip);
    return c;
  };
  const reduced = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
  const TURN = reduced ? 1 : 620;
  let busy = false;
  /**
   * Where the turning is headed, and the turn under way. A press while a leaf is turning moves the goal on
   * and the leaf snaps over, so a quick tap-tap-tap turns once, three spreads on (the user, 7 Oct 2026),
   * instead of three turns played out one after another.
   */
  let goal = view.spread ?? 0;
  let cur: Animation | null = null;

  /**
   * Draw the stamps of the spreads either side ahead of time: a building's stamp is drawn from its model a
   * few a frame and kept (passportStamps.ts), so a page drawn once off-screen turns in with every stamp ready.
   */
  const warmed = new Set<number>();
  let warmT = 0;
  const preload = (s: number): void => {
    clearTimeout(warmT);
    warmT = window.setTimeout(() => {
      if (!wrap.isConnected) return;
      for (const t of [s + 1, s - 1, s + 2]) {
        if (t < 0 || t > last) continue;
        for (const i of shown(t)) {
          if (i < 0 || i >= pages.length || warmed.has(i)) continue;
          const ch = pages[i].ch;
          if (ch !== 'sig' && !(SIGHT_PAGES as string[]).includes(ch)) continue;
          warmed.add(i);
          pageEl(i);
        }
      }
    }, 80);
  };

  /** A leaf over a slot, its two faces drawn, turning about the spine. */
  const leafOver = (side: 'l' | 'r', front: HTMLElement, back: HTMLElement): HTMLElement => {
    const leaf = el('div', `pb-leaf ${side}`);
    const f = el('div', 'pb-face front'), b = el('div', 'pb-face back');
    f.append(front, el('i', 'pb-shade'));
    b.append(back, el('i', 'pb-shade'));
    leaf.append(f, b);
    bookEl.append(leaf);
    return leaf;
  };
  // a turn ends when its animation does, or a little after it should have: a hidden tab stops the clock
  const done = (a: Animation): Promise<void> => new Promise((ok) => {
    // (its finish event waits for a frame as well, so the turn is settled here outright)
    const stop = window.setTimeout(() => { try { a.finish(); } catch { /* gone */ } ok(); }, (Number(a.effect?.getTiming().duration) || TURN) + 400);
    a.onfinish = () => { window.clearTimeout(stop); ok(); };
    a.oncancel = () => { window.clearTimeout(stop); ok(); };
  });

  /** Open the closed book: the cover swings over to the left, and the book slides to the middle. */
  const openCover = async (): Promise<void> => {
    if (!view.closed || busy) return;
    busy = true;
    view.closed = false;
    const s = view.spread ?? 0;
    const [l, r] = shown(s);
    // the pages under the cover are the ones asked for; the cover's inside is the left page as it lands
    bookEl.querySelector('.pb-leaf.cover')?.remove();
    if (size.two) slotL.replaceChildren();
    fill(slotR, r);
    const inner = size.two ? pageEl(l) : el('div', 'pb-page endboard');
    const leaf = leafOver('r', cover(), inner);
    leaf.classList.add('cover');
    // the left board stays hidden until the cover has swung over to be it
    bookEl.classList.replace('closed', 'opening');
    const ease = 'cubic-bezier(.45,.05,.3,1)';
    const slide = size.two ? bookEl.animate([{ transform: `translateX(${-size.w / 2}px)` }, { transform: 'translateX(0)' }], { duration: TURN * 1.15, easing: ease }) : null;
    const a = leaf.animate([{ transform: 'rotateY(0deg)' }, { transform: 'rotateY(-180deg)', offset: 1 }], { duration: TURN * 1.15, easing: ease, fill: 'forwards' });
    cur = a;
    preload(s);
    await done(a);
    cur = null;
    // the slide ends with the cover's turn, even where the clock stood still
    try { slide?.finish(); } catch { /* gone */ }
    bookEl.classList.remove('opening');
    leaf.remove();
    paint(s);
    busy = false;
    settle();
    if (goal !== s) void turnTo(goal);
  };

  /** Turn to a spread: one leaf turns over, whatever the distance. */
  const turnTo = async (t: number): Promise<void> => {
    t = Math.max(0, Math.min(last, t));
    const s = view.spread ?? 0;
    if (view.closed) { view.spread = t; goal = t; await openCover(); return; }
    // a leaf already turning: the goal moves on, and that leaf snaps over so the next turn goes straight there
    if (busy) { goal = t; try { cur?.finish(); } catch { /* gone */ } return; }
    goal = t;
    if (t === s) return;
    busy = true;
    const hadFocus = wrap.contains(document.activeElement) && !nav.contains(document.activeElement) && !ribbons.contains(document.activeElement);
    const fwd = t > s;
    const [sl, sr] = shown(s), [tl, tr] = shown(t);
    const ease = 'cubic-bezier(.4,.1,.3,1)';
    let leaf: HTMLElement, a: Animation;
    if (size.two && fwd) {
      // the right page lifts and turns over onto the left, showing the next left page on its back
      leaf = leafOver('r', pageEl(sr), pageEl(tl));
      fill(slotR, tr);
      a = leaf.animate([{ transform: 'rotateY(0deg)' }, { transform: 'rotateY(-180deg)' }], { duration: TURN, easing: ease, fill: 'forwards' });
      cur = a;
      await done(a);
      fill(slotL, tl);
    } else if (size.two) {
      leaf = leafOver('l', pageEl(sl), pageEl(tr));
      fill(slotL, tl);
      a = leaf.animate([{ transform: 'rotateY(0deg)' }, { transform: 'rotateY(180deg)' }], { duration: TURN, easing: ease, fill: 'forwards' });
      cur = a;
      await done(a);
      fill(slotR, tr);
    } else if (fwd) {
      leaf = leafOver('r', pageEl(sr), el('div', 'pb-page blank'));
      fill(slotR, tr);
      a = leaf.animate([{ transform: 'rotateY(0deg)', opacity: 1 }, { transform: 'rotateY(-180deg)', opacity: 0.6 }], { duration: TURN, easing: ease, fill: 'forwards' });
      cur = a;
      await done(a);
    } else {
      leaf = leafOver('r', pageEl(tr), el('div', 'pb-page blank'));
      a = leaf.animate([{ transform: 'rotateY(-180deg)', opacity: 0.6 }, { transform: 'rotateY(0deg)', opacity: 1 }], { duration: TURN, easing: ease, fill: 'forwards' });
      cur = a;
      await done(a);
      fill(slotR, tr);
    }
    cur = null;
    leaf.remove();
    view.spread = t;
    busy = false;
    settle();
    if (hadFocus) (fwd ? next : prev).focus();
    // pressed again while it turned: one more turn, straight to where the presses add up to
    if (goal !== t) { void turnTo(goal); return; }
    preload(t);
  };

  passportNav.flip = (dir) => {
    if (!wrap.isConnected || view.stamp || view.open) return false;
    if (view.closed) { void openCover(); return true; }
    // from where the turning is headed, so each press counts while a leaf is still over
    void turnTo((busy ? goal : view.spread ?? 0) + dir);
    return true;
  };
  passportNav.digit = (n) => {
    if (!wrap.isConnected) return false;
    const g = DEED_GROUPS[n - 1];
    if (!g) return false;
    const i = pages.findIndex((p) => p.ch === 'visas' && p.title.startsWith(g));
    if (i < 0) return false;
    void turnTo(spreadOf(i));
    return true;
  };

  if (view.closed) {
    bookEl.classList.add('closed');
    const leaf = el('div', 'pb-leaf r cover');
    const f = el('div', 'pb-face front');
    f.append(cover());
    leaf.append(f);
    leaf.addEventListener('click', () => void openCover());
    bookEl.append(leaf);
    // the book lies shut a moment, then opens of itself
    window.setTimeout(() => { if (wrap.isConnected) void openCover(); }, reduced ? 0 : 520);
  } else { paint(view.spread); preload(view.spread); }
  settle();

  wrap.append(stage, nav);
  panel.append(wrap);
  // a stamp or a visa opened: its card over the book
  const card = view.stamp ? stampCard(view, button, rerender) : view.open ? visaCard(view, button, rerender) : null;
  if (card) (panel.closest('#title-menu') ?? panel).append(card);
}

/**
 * A page's seal in its header (game/passportRewards.ts): gold and pressed when every stamp is in, open when a page
 * that was sealed has grown (its treat kept), and a faint outline of what filling it gives otherwise.
 */
function sealMark(id: SealId): HTMLElement {
  const t = treatOf(id), full = pageFull(id), had = rewards.has(id);
  const [got, all] = pageTally(id);
  const s = el('span', `pb-seal${full ? ' on' : had ? ' open' : ''}`, full || had ? '🔏' : '○');
  s.title = full ? `Sealed · ${t.icon} ${t.name}: ${t.blurb}`
    : had ? `Sealed once, and the page has grown: ${all - got} new to stamp · ${t.icon} ${t.name} is still yours`
      : `Fill the page (${all - got} to go) for ${t.icon} ${t.name}: ${t.blurb}`;
  return s;
}

/** The book's pages, in order, cut to fit pages of this size. */
function bookPages(view: DeedsView, who: BookOwner, button: Button, rerender: (key?: string) => void, size: ReturnType<typeof bookSize>): Page[] {
  const pages: Page[] = [];
  const per = size.cols * size.rows;
  const chunks = <T,>(list: T[], n: number): T[][] => {
    const out: T[][] = [];
    for (let k = 0; k < list.length; k += n) out.push(list.slice(k, k + n));
    return out.length ? out : [[]];
  };
  // the inside of the front cover: what is in the book, and where
  pages.push({ ch: 'contents', title: 'Contents', draw: (b) => contentsPage(b, pages, button, size) });
  pages.push({ ch: 'data', title: 'Holder', draw: (b) => dataPage(b, who) });

  for (const p of SIGHT_PAGES) {
    const deed = DEEDS.find((x) => x.stat === SIGHT_DEED[p]);
    const sub = deed ? `${deed.icon} ${deed.name}: ${deedLine(deed)}` : undefined;
    const all = pageKeys(p).length;
    let keys: string[];
    if (p === 'kind') {
      const signature = new Set<string>();
      for (const kinds of SIGNATURES.values()) for (const k of kinds) signature.add(k);
      keys = sights.keys('kind').filter((k) => !signature.has(k) && !WONDER_KINDS.has(k)).sort((a, b) => stampLabel('kind', a).localeCompare(stampLabel('kind', b)));
    } else {
      const listed = pageKeys(p);
      keys = [...listed, ...sights.keys(p).filter((q) => !listed.includes(q))];
    }
    const parts = chunks(keys, per);
    parts.forEach((part, k) => pages.push({
      ch: p, title: `${PAGE_LABEL[p]}${parts.length > 1 ? ` · ${k + 1} of ${parts.length}` : ''}`, count: `${sights.count(p)}/${all}`, sub: k === 0 ? sub : undefined, seal: p,
      draw: (b) => {
        if (!part.length) b.append(el('p', 'pb-empty', p === 'kind' ? 'No buildings stamped yet. Drive within five tiles of one for its stamp.' : 'Nothing stamped here yet.'));
        else stampGrid(b, part.map((key) => [p, key] as [SightPage, string]), view, button, rerender, size);
        if (p === 'kind' && k === parts.length - 1) {
          const blanks = pageKeys('kind').length - sights.count('kind');
          const key = el('div', 'pp-inks');
          for (const c of Object.keys(INK) as InkClass[]) { const s = el('span'); const dot = el('i'); dot.style.background = INK[c].ink; s.append(dot, INK[c].label); key.append(s); }
          { const s = el('span', 'gold'); s.append(el('i'), 'gold foil: a landmark or a wonder'); key.append(s); }
          b.append(key);
          if (blanks > 0) b.append(el('p', 'pb-empty', `${blanks} more kinds of building are out there.`));
        }
      },
    }));
  }

  // the signature buildings, a style at a time, as many styles to a page as fit
  {
    const bodyH = size.h - 104;
    const rowH = size.cell, labelH = 22;
    let cur: { style: Arch; kinds: string[] }[] = [], used = 0;
    const flush = () => {
      if (!cur.length) return;
      const blocks = cur;
      pages.push({ ch: 'sig', title: 'Signature buildings', seal: 'sig', count: `${[...SIGNATURES.values()].flat().filter((k) => sights.has('kind', k)).length}/${[...SIGNATURES.values()].flat().length}`, draw: (b) => {
        for (const blk of blocks) {
          const got = blk.kinds.filter((k) => sights.has('kind', k)).length;
          const line = el('div', 'pb-sig');
          line.append(el('b', '', ARCH_LABEL[blk.style]), el('em', '', `${got} of ${SIGNATURES.get(blk.style)?.length ?? blk.kinds.length}`));
          b.append(line);
          stampGrid(b, blk.kinds.map((k) => ['kind', k] as [SightPage, string]), view, button, rerender, size);
        }
      } });
      cur = [];
      used = 0;
    };
    for (const style of ARCHES) {
      const kinds = SIGNATURES.get(style);
      if (!kinds?.length) continue;
      for (const part of chunks(kinds, per)) {
        const need = labelH + Math.ceil(part.length / size.cols) * rowH;
        if (used + need > bodyH) flush();
        cur.push({ style, kinds: part });
        used += need;
      }
    }
    flush();
  }

  // the visas: a page a group of deeds, more if it runs over
  const visaH = 60;
  const perVisa = Math.max(2, Math.floor((size.h - 104) / visaH));
  DEED_GROUPS.forEach((g) => {
    const list = DEEDS.filter((d) => d.group === g && (chainsShown() || !CHAIN_DEEDS.has(d.id) || deeds.tier(d) > 0));
    if (!list.length) return;
    const got = list.reduce((s, d) => s + deeds.tier(d), 0);
    const parts = chunks(list, perVisa);
    parts.forEach((part, k) => pages.push({
      ch: 'visas', title: `${g}${parts.length > 1 ? ` · ${k + 1} of ${parts.length}` : ''}`, count: `${got}/${list.length * 5}`, deeds: part.map((d) => d.id), seal: `visa:${g}`,
      draw: (b) => { for (const d of part) b.append(visaEntry(d, view, button, rerender)); },
    }));
  });

  pages.push({ ch: 'imports', title: 'Imports', scroll: true, draw: (b) => buildImports(b) });
  pages.push({ ch: 'marks', title: 'Bookmarks', count: `${bookmarks.all().length}/${MAX_BOOKMARKS}`, scroll: true, draw: (b) => buildMarks(b, button, rerender) });
  // two to a spread: the last page has a facing page, a ruled one for notes
  if (size.two && pages.length % 2 === 1) pages.push({ ch: 'notes', title: 'Notes', draw: (b) => { b.classList.add('ruled'); b.append(el('div', 'pb-notes', 'Notes · Observations')); } });
  return pages;
}

/** The inside of the front cover: the chapters, each with the page it starts on. */
function contentsPage(b: HTMLElement, pages: Page[], button: Button, size: ReturnType<typeof bookSize>): void {
  b.append(el('div', 'pb-ctitle', 'Contents'));
  const list = el('div', 'pb-contents');
  for (const c of CHAPTERS) {
    const i = pages.findIndex((p) => p.ch === c.ch);
    if (i < 0) continue;
    const row = button('', 'pb-crow', `toc-${c.ch}`, () => {
      // the ribbon for the chapter does the turning
      (document.querySelector(`[data-k="rib-${c.ch}"]`) as HTMLButtonElement | null)?.click();
    }, 'toc');
    row.append(el('i', '', c.icon), el('span', '', c.label), el('u'), el('em', '', String(i)));
    list.append(row);
  }
  b.append(list, el('p', 'pb-hint', size.two ? '← → turn the pages · the ribbons jump to a chapter' : '← → turn the pages'));
}

/** The holder's page: who the book is for, their fleet's badge for a photo, and the lines a passport has. */
function dataPage(b: HTMLElement, who: BookOwner): void {
  const { tiers, points } = deeds.totals();
  b.append(el('div', 'pb-dhead', 'PASSPORT · PASSEPORT · PASAPORTE'));
  const grid = el('div', 'pb-dgrid');
  const photo = el('div', 'pb-photo');
  if (who.fleet) {
    const p = badgePaint(who.fleet.primary, who.fleet.accent);
    photo.style.background = p.disc;
    photo.style.color = p.glyph;
    photo.style.boxShadow = `inset 0 0 0 6px ${p.ring}`;
    photo.textContent = who.fleet.logo;
  } else {
    photo.style.background = hexCol(who.colour);
    photo.textContent = (who.name[0] ?? '?').toUpperCase();
  }
  // the date it was issued: the first stamp in it
  let first = Infinity;
  for (const p of SIGHT_PAGES) for (const k of sights.keys(p)) { const t = sights.where(p, k)?.t; if (t && t < first) first = t; }
  const no = (hashOf(who.id ?? who.name) % 1e9).toString(36).toUpperCase().padStart(7, '0').slice(0, 7);
  const fields: [string, string][] = [
    ['Type / Code', 'P · TFL'],
    ['Passport no.', `TF${no}`],
    ['Name', who.name],
    ['Fleet', who.fleet?.name ?? '—'],
    ['Issued', Number.isFinite(first) ? date(first) : 'not yet stamped'],
    ['Stamps', `${sights.total()}`],
    ['Visa tiers', `${tiers} of ${DEEDS.length * 5}`],
    ['From stamps', `◆ ${points}`],
  ];
  const dl = el('dl', 'pb-fields');
  for (const [k, v] of fields) dl.append(el('dt', '', k), el('dd', '', v));
  grid.append(photo, dl);
  b.append(grid, el('div', 'pb-sign', who.name));
  // the machine-readable lines at the foot
  const clean = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]+/g, '<');
  const pad = (s: string) => (s + '<'.repeat(30)).slice(0, 30);
  const mrz = el('div', 'pb-mrz');
  mrz.append(el('div', '', pad(`P<TFL${clean(who.name)}<<${clean(who.fleet?.name ?? '')}`)), el('div', '', pad(`TF${no}<${sights.total()}<${tiers}<${points}`)));
  b.append(mrz);
}

/** Stamps pressed onto a page: each in its cell, turned and nudged as a hand would press it, the same each time. */
function stampGrid(b: HTMLElement, list: [SightPage, string][], view: DeedsView, button: Button, rerender: (key?: string) => void, size: ReturnType<typeof bookSize>): void {
  const grid = el('div', 'pb-grid');
  grid.style.gridTemplateColumns = `repeat(${size.cols}, 1fr)`;
  for (const [p, key] of list) {
    const s = stampEl(p, key, view, button, rerender);
    const h = hashOf(`${p}:${key}`);
    const turn = ((h % 23) - 11) * (sights.has(p, key) ? 1 : 0);
    const dx = (((h >> 5) % 13) - 6), dy = (((h >> 9) % 11) - 5);
    s.style.setProperty('--tilt', `${turn}deg`);
    s.style.setProperty('--dx', `${dx}px`);
    s.style.setProperty('--dy', `${dy}px`);
    grid.append(s);
  }
  b.append(grid);
}

/** One stamp: its own art, or a faint space for one not yet come by. */
function stampEl(p: SightPage, key: string, view: DeedsView, button: Button, rerender: (key?: string) => void): HTMLElement {
  const id = `${p}:${key}`;
  if (!sights.has(p, key)) { const s = el('span', 'pp-stamp blank'); s.append(el('i', '', '?'), el('small', '', stampLabel(p, key))); return s; }
  const rareOne = p === 'wonder' || (p === 'kind' && SIGNATURE_STYLE.has(key as BuildingKind));
  const b = button('', `pp-stamp ${p}${rareOne ? ' foil' : ''}${view.stamp === id ? ' open' : ''}`, `stamp-${id}`, () => { view.stamp = view.stamp === id ? null : id; rerender(`stamp-${id}`); }, 'stamps');
  const seen = sights.where(p, key);
  const art = el('img', 'pp-art');
  if (p === 'kind' || p === 'wonder') {
    const style = p === 'kind' ? SIGNATURE_STYLE.get(key as BuildingKind) : undefined;
    buildingStampInto(art, key as BuildingKind, style ?? 'classic', stampLabel(p, key), p === 'wonder' || !!style);
  } else art.src = stampArt(p, key);
  art.alt = stampLabel(p, key);
  b.append(art);
  b.title = seen ? `${stampLabel(p, key)} · first seen at ${seen.name}, ${date(seen.t)}` : `${stampLabel(p, key)} · seen before places were kept`;
  return b;
}

/** A stamp opened: a card over the book, the stamp large and how it was come by. */
function stampCard(view: DeedsView, button: Button, rerender: (key?: string) => void): HTMLElement | null {
  if (!view.stamp) return null;
  const cut = view.stamp.indexOf(':');
  const p = view.stamp.slice(0, cut) as SightPage, key = view.stamp.slice(cut + 1);
  if (!sights.has(p, key)) return null;
  const seen = sights.where(p, key);
  const close = () => { view.stamp = null; rerender(`stamp-${p}:${key}`); };
  const modal = el('div', 'pp-modal');
  modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
  const card = el('div', 'pp-mcard');
  const big = el('img', `pp-big ${p}`);
  big.alt = stampLabel(p, key);
  if (p === 'kind' || p === 'wonder') {
    const style = p === 'kind' ? SIGNATURE_STYLE.get(key as BuildingKind) : undefined;
    buildingStampInto(big, key as BuildingKind, style ?? 'classic', stampLabel(p, key), p === 'wonder' || !!style);
  } else big.src = stampArt(p, key);
  const info = el('div', 'pp-minfo');
  info.append(el('small', '', `${PAGE_ICON[p]} ${PAGE_LABEL[p]} · ${sights.count(p)} of ${pageKeys(p).length} collected`), el('h3', '', stampLabel(p, key)));
  const lines: [string, string][] = [];
  const rare = rarity(p, key);
  if (rare) lines.push(['Rarity', rare]);
  if (seen) {
    lines.push(['Stamped', `${HOW[p]} ${seen.name}`]);
    lines.push(['On', new Date(seen.t).toLocaleString(undefined, { weekday: 'short', day: 'numeric', month: 'long', year: 'numeric', hour: 'numeric', minute: '2-digit' })]);
    lines.push(['Where', `cell ${seen.cx}, ${seen.cz} · ${farText(seen)}`]);
  } else lines.push(['Stamped', 'before the Passport kept places: pass one again and it will remember where']);
  const dl = el('dl', 'pp-mlines');
  for (const [k, v] of lines) dl.append(el('dt', '', k), el('dd', '', v));
  info.append(dl);
  const row = el('div', 'pp-acts');
  if (seen) {
    const id = `s:${p}:${key}`;
    row.append(button(bookmarks.has(id) ? '★ Bookmarked' : '☆ Bookmark', 'link', `mark-${id}`, () => {
      if (!bookmarks.toggle({ id, kind: STAMP_KIND[p], label: `${stampLabel(p, key)} · ${seen.name}`, sub: PAGE_LABEL[p], cx: seen.cx, cz: seen.cz, x: seen.x, z: seen.z }) && !bookmarks.has(id)) info.append(el('span', 'pp-full', `The list is full (${MAX_BOOKMARKS}).`));
      rerender(`mark-${id}`);
    }));
    if (book.host) row.append(button('Show on map', 'link', `map-${id}`, () => book.host?.showOnMap({ ...seen, label: stampLabel(p, key) })));
  }
  row.append(button('Close', 'link', 'stamp-close', close));
  info.append(row);
  card.append(big, info);
  modal.append(card);
  return modal;
}

/** What hovering an achievement says, in the Passport and on its notifications alike. */
export function deedTip(d: Deed): string { return d.blurb; }

/** A deed on a visa page: its seal pressed beside its name, its pips and how far along it is. */
function visaEntry(d: Deed, view: DeedsView, button: Button, rerender: (key?: string) => void): HTMLElement {
  const t = deeds.tier(d);
  const row = button('', `pb-visa${t >= 5 ? ' done' : ''}${t === 0 ? ' none' : ''}${view.deed === d.id ? ' picked' : ''}`, `deed-${d.id}`, () => { view.open = d.id; rerender(`deed-${d.id}`); }, 'stamps');
  row.title = deedTip(d);
  const seal = el('img', 'pb-vseal');
  seal.src = sealOf(d, t);
  seal.alt = d.icon;
  seal.style.setProperty('--tilt', `${(hashOf(d.id) % 17) - 8}deg`);
  const text = el('div', 'pb-vtext');
  const top = el('div', 'pb-vtop');
  top.append(el('b', '', d.name), pips(t));
  const bar = el('div', 'dd-bar');
  const fillBar = el('i');
  fillBar.style.width = `${Math.round(deeds.progress(d) * 100)}%`;
  fillBar.style.background = TIER_COLOURS[Math.min(4, t)];
  bar.append(fillBar);
  text.append(top, bar, el('div', 'dd-line', deedLine(d)));
  row.append(seal, text);
  return row;
}

/** A visa opened: the deed's seal large, what it is for and its ladder of tiers with the dates they came. */
function visaCard(view: DeedsView, button: Button, rerender: (key?: string) => void): HTMLElement | null {
  const d = DEEDS.find((x) => x.id === view.open);
  if (!d) return null;
  const t = deeds.tier(d);
  const close = () => { view.open = null; rerender(`deed-${d.id}`); };
  const modal = el('div', 'pp-modal');
  modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
  const card = el('div', 'pp-mcard');
  const big = el('img', 'pp-big visa');
  big.src = sealOf(d, t);
  big.alt = d.icon;
  const info = el('div', 'pp-minfo');
  info.append(el('small', '', `🛂 Visa · ${d.group}`), el('h3', '', d.name), el('div', 'pp-note', d.blurb), pips(t), el('div', 'dd-line', deedLine(d)));
  const ladder = el('div', 'dd-ladder');
  d.ladder.forEach((v, k) => {
    const at = deeds.dates(d)[k];
    const step = el('span', k < t ? 'on' : '');
    step.style.setProperty('--c', TIER_COLOURS[k]);
    step.append(el('i'), `${TIERS[k]} ${d.kind === 'set' ? v.toLocaleString('en-US') : amount(d, v)}`, k < t ? el('em', '', ` · ${date(at ?? 0)}`) : '');
    ladder.append(step);
  });
  info.append(ladder);
  const row = el('div', 'pp-acts');
  row.append(button('Close', 'link', 'visa-close', close));
  info.append(row);
  card.append(big, info);
  modal.append(card);
  return modal;
}

// ---- imports: the fleet's culture books, a town at a time (docs/culturegate.html) ----

/** One town on the Culture page: its book, and whether its hall is open to the fleet. */
export interface ImportTown { key: string; name: string; sub: string; role: 'hq' | 'held' | 'once'; strands: Strand[]; festival: number; received: string[] }

function buildImports(panel: HTMLElement): void {
  const v = book.host?.imports();
  if (!v) { panel.append(el('p', 'pp-note', 'Your towns’ culture is kept with the game: open the Passport while you play to see it.')); return; }
  if (!v.towns.length) {
    panel.append(el('p', 'pp-note', v.why), el('p', 'pp-note', `A town’s culture rises only by what you carry to it: go somewhere it has never received anything from, load the cultural goods waiting there (its food, its art, its cloth), and hand them in at your HQ or at the hall of a town you hold. A vehicle carries ${CULTURE.per} units of cultural goods; more needs your fleet in formation behind you.`));
    return;
  }
  const ROLE = { hq: 'your HQ takes cultural goods', held: 'held · its hall takes cultural goods', once: 'once yours · its book is kept' };
  for (const t of v.towns) {
    const head = el('div', 'pp-home');
    head.append(el('b', '', t.name), el('span', '', `${t.sub} · ${ROLE[t.role]}${t.festival > 0 ? ` · festival for ${Math.ceil(t.festival)} h more` : ''}`));
    panel.append(head);
    if (!t.strands.length) panel.append(el('p', 'pp-note', t.role === 'hq' ? 'Nothing imported yet. Drive into a town of another style, to a wonder or a landform in another county, and its goods will wait there for you, like any other cargo.' : 'No goods yet: hand some in at its hall.'));
    for (const s of t.strands) {
      const row = el('div', 'pp-strand');
      const top = el('div', 'dd-top');
      top.append(el('b', '', s.label), el('span', `pp-rung r${s.rung}`, s.rung ? RUNG_NAME[s.rung] : 'Stirring'));
      const bar = el('div', 'dd-bar');
      const fill = el('i');
      const goal = s.next ?? CULTURE.rungs[2];
      fill.style.width = `${Math.min(100, Math.round((s.pts / goal) * 100))}%`;
      fill.style.background = TIER_COLOURS[Math.min(4, s.rung + 1)];
      bar.append(fill);
      const line = s.next ? `${s.pts} / ${s.next} to ${RUNG_NAME[CULTURE.rungs.indexOf(s.next as 50 | 150 | 400) + 1]}` : `${s.pts} points`;
      row.append(top, bar, el('div', 'dd-line', s.needs ? `${line} · needs ${s.needs}` : line));
      panel.append(row);
    }
  }
  const crates = (title: string, list: Crate[], empty: string) => {
    panel.append(el('h4', 'pp-h', title));
    if (!list.length) { panel.append(el('p', 'pp-note', empty)); return; }
    const ul = el('div', 'dd-rows');
    for (const c of list) {
      const r = el('div', 'pp-crate');
      r.append(el('b', '', `${c.good.icon} ${c.good.name}`), el('span', '', `${styleLabel(c.style)} · ${c.weight} unit${c.weight === 1 ? '' : 's'} · ${c.from} · cell ${c.cx}, ${c.cz}`));
      if (book.host && list === v.waiting) {
        const b = el('button', 'tm-btn link', 'map');
        b.type = 'button';
        b.addEventListener('click', (e) => { e.stopPropagation(); book.host?.showOnMap({ cx: c.cx, cz: c.cz, x: c.x - c.cx * N, z: c.z - c.cz * N, label: c.good.name }); });
        r.append(b);
      }
      ul.append(r);
    }
    panel.append(ul);
  };
  crates(`Aboard · ${v.room}`, v.aboard, 'No cultural goods aboard.');
  crates('Waiting to be fetched', v.waiting, 'Nothing waiting. New goods appear where you find something the town has never received.');
  const first = v.towns[0];
  const never = ARCHES.filter((a) => !first.received.includes(`arch:${a}`) && !first.strands.some((s) => s.style === a));
  if (never.length) panel.append(el('p', 'pp-note', `${first.name} has never received from: ${never.slice(0, 6).map((a: Arch) => ARCH_LABEL[a]).join(', ')}${never.length > 6 ? `, ${never.length - 6} more` : ''}.`));
}

// ---- bookmarks ----

function buildMarks(panel: HTMLElement, button: Button, rerender: (key?: string) => void): void {
  const list = bookmarks.all();
  if (!list.length) { panel.append(el('p', 'pp-note', 'Nothing bookmarked yet. Click a building, a wonder or a town and press ☆ on its card, or open a stamp in Sights and bookmark where you first saw it.')); return; }
  const me = book.host?.here() ?? null;
  const sorted = me ? [...list].sort((a, b) => tilesBetween(me, a) - tilesBetween(me, b)) : list;
  const top = el('div', 'pp-acts');
  const all = list.every((b) => b.lit);
  top.append(el('span', '', `${list.length} of ${MAX_BOOKMARKS} · ${list.filter((b) => b.lit).length} lit on the map`),
    button(all ? 'Dim all' : 'Light all', 'link', 'mk-all', () => { bookmarks.lightAll(!all); rerender('mk-all'); }));
  panel.append(top);
  const rows = el('div', 'dd-rows');
  for (const b of sorted) rows.append(markRow(b, button, rerender));
  panel.append(rows);
}

function markRow(b: Bookmark, button: Button, rerender: (key?: string) => void): HTMLElement {
  const row = el('div', `pp-mark${b.lit ? ' lit' : ''}`);
  const text = el('div', 'pp-marktext');
  text.append(el('b', '', `${MARK_ICON[b.kind]} ${b.label}`), el('span', '', `${b.sub ? `${b.sub} · ` : ''}${farText(b)}`));
  row.append(text,
    button(b.lit ? '💡 Lit' : '💡 Light', `link${b.lit ? ' on' : ''}`, `mk-lit-${b.id}`, () => { bookmarks.setLit(b.id, !b.lit); rerender(`mk-lit-${b.id}`); }));
  if (book.host) row.append(button('Map', 'link', `mk-map-${b.id}`, () => { bookmarks.setLit(b.id, true); book.host?.showOnMap(b); }));
  row.append(button('Rename', 'link', `mk-name-${b.id}`, () => {
    const name = prompt('Name this bookmark', b.label);
    if (name) { bookmarks.rename(b.id, name); rerender(`mk-name-${b.id}`); }
  }), button('✕', 'link', `mk-del-${b.id}`, () => { bookmarks.remove(b.id); rerender(); }));
  return row;
}

/** The line a player's chip on Saved games gains: their best tier's pip in each group and their tier count. */
export function playerMedals(player: string): HTMLElement {
  const g = groupTiers(player);
  const line = el('div', 'dd-medals');
  const total = g.reduce((s, x) => s + x.tiers, 0);
  for (const x of g) {
    const p = el('i', x.best ? 'on' : '');
    p.style.setProperty('--c', x.best ? TIER_COLOURS[x.best - 1] : '#d5dde2');
    p.title = `${x.group}: ${x.tiers} tier${x.tiers === 1 ? '' : 's'}`;
    line.append(p);
  }
  line.append(el('span', '', `${total} of ${DEEDS.length * 5} tiers`));
  return line;
}
