import { N, SEA, DIRS, World, idx, inB, waterDepth, steepness, isFlat, edgeMismatch } from '../world/tiles';
import { railBlocks } from '../world/graph';
import type { VehicleDef, VehicleState } from './vehicles';
import { CarState } from './car';
import { BoatState, boatFits, boatTileOk } from './boat';
import { AirState, groundY } from './air';

/** Closest tile (by rings outward from x, z) that passes ok, or null. */
export function findNear(x: number, z: number, ok: (tx: number, tz: number) => boolean): [number, number] | null {
  const cx = Math.floor(x), cz = Math.floor(z);
  for (let r = 0; r < N; r++) {
    let best: [number, number] | null = null;
    let bestD = Infinity;
    for (let dz = -r; dz <= r; dz++) {
      const edge = Math.abs(dz) === r;
      for (let dx = -r; dx <= r; dx += edge ? 1 : 2 * r) {
        const tx = cx + dx, tz = cz + dz;
        if (!inB(tx, tz) || !ok(tx, tz)) continue;
        const d = dx * dx + dz * dz;
        if (d < bestD) { bestD = d; best = [tx, tz]; }
      }
    }
    if (best) return best;
  }
  return null;
}

/**
 * The tile a car can drive to from i across side d, or -1: along the drivable edges (w.edges bits, which
 * already refuse blocked tiles), or over at-grade track, which the edges leave out but a car bumps across.
 */
function stepFrom(w: World, i: number, d: number): number {
  const x = i % N, z = (i - x) / N;
  const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
  if (!inB(nx, nz)) return -1;
  const j = idx(nx, nz);
  if (w.edges[i] & (1 << d)) return j;
  if (!railBlocks(w, i) && !railBlocks(w, j)) return -1;
  if (w.blocked[i] || w.blocked[j] || waterDepth(w, i) > 1 || waterDepth(w, j) > 1) return -1;
  return edgeMismatch(w, i, d) === 0 ? j : -1;
}

/**
 * Every tile a car can reach from some road: a flood outward from all road tiles at once. A pitch sealed
 * inside a stadium's stands, a courtyard walled by lots, a meadow cut off by cliffs — none of those are
 * marked. On an island with no road at all nothing is.
 */
export function roadReach(w: World): Uint8Array {
  const seen = new Uint8Array(N * N);
  const queue = new Int32Array(N * N);
  let head = 0, tail = 0;
  for (let i = 0; i < N * N; i++) {
    if (w.road[i] > 0 && !w.blocked[i]) { seen[i] = 1; queue[tail++] = i; }
  }
  while (head < tail) {
    const i = queue[head++];
    for (let d = 0; d < 4; d++) {
      const j = stepFrom(w, i, d);
      if (j >= 0 && !seen[j]) { seen[j] = 1; queue[tail++] = j; }
    }
  }
  return seen;
}

/** Past this many tiles a pocket is big enough to drive about in, road or not: stop looking. */
const POCKET_CAP = 2048;

/**
 * Whether a car at tile i can drive out to a road — or at least has a stretch of country big enough not
 * to be trapped in. A flood from i alone, so it is cheap where it matters: on or beside a road it stops
 * at once, and a sealed pocket (a stadium pitch) runs out after a few tiles. True on a roadless island.
 */
function reachesRoad(w: World, i: number): boolean {
  if (w.road[i] > 0) return true;
  const seen = new Set<number>([i]);
  const queue = [i];
  for (let head = 0; head < queue.length; head++) {
    const k = queue[head];
    for (let d = 0; d < 4; d++) {
      const j = stepFrom(w, k, d);
      if (j < 0 || seen.has(j)) continue;
      if (w.road[j] > 0 || seen.size >= POCKET_CAP) return true;
      seen.add(j);
      queue.push(j);
    }
  }
  return !w.road.some((r) => r > 0);
}

/** Build a state for def near (x, z), moved to the closest place it can actually exist. */
export function spawnState(def: VehicleDef, w: World, x: number, z: number, heading: number, y: number): VehicleState {
  const cx = Math.min(N - 0.5, Math.max(0.5, x));
  const cz = Math.min(N - 0.5, Math.max(0.5, z));

  if (def.kind === 'rail') throw new Error('a train is put on the track by the trains system, not placed');
  if (def.kind === 'air') return new AirState(def, x, z, heading, Math.max(y, groundY(w, x, z)), w);

  if (def.kind === 'water') {
    const level = w.water[idx(Math.floor(cx), Math.floor(cz))];
    if (level >= 0 && boatFits(w, def, cx, cz, heading, level)) return new BoatState(def, cx, cz, heading, w);
    // launch into open sea rather than a pond or a narrow creek
    const t = findNear(cx, cz, (tx, tz) => w.water[idx(tx, tz)] === SEA && boatTileOk(w, def, tx, tz, 2))
      ?? findNear(cx, cz, (tx, tz) => boatTileOk(w, def, tx, tz, 2))
      ?? findNear(cx, cz, (tx, tz) => boatTileOk(w, def, tx, tz));
    return t ? new BoatState(def, t[0] + 0.5, t[1] + 0.5, heading, w) : new BoatState(def, cx, cz, heading, w);
  }

  const i = idx(Math.floor(cx), Math.floor(cz));
  // a bridge's tile: on its deck, where the road is, never on the ground or the water under it
  if (w.deckAxis[i]) {
    const st = new CarState(def, cx, cz, heading, w);
    st.standOnDeck(w);
    return st;
  }
  const depth = waterDepth(w, i);
  const swims = !!def.swimSpeed;
  const okHere = swims && depth > 0
    ? true
    : depth <= def.wade && steepness(w, i) <= def.maxGrade && w.edges[i] !== 0 && reachesRoad(w, i);
  if (okHere) return new CarState(def, cx, cz, heading, w);
  // never into a pocket with no way out (a stadium pitch): only tiles joined to a road, unless there is none
  const reach = roadReach(w);
  const roadless = !reach.includes(1);
  const t = findNear(cx, cz, (tx, tz) => {
    const j = idx(tx, tz);
    return waterDepth(w, j) === 0 && isFlat(w, j) && w.edges[j] === 15 && (roadless || reach[j] === 1);
  });
  return t ? new CarState(def, t[0] + 0.5, t[1] + 0.5, heading, w) : new CarState(def, cx, cz, heading, w);
}
