/**
 * Fleet work (the user, 11 Nov 2026): missions the fleet does while the player does something else. Each counts
 * what the company already does in the background, from when the step comes up (missions/model.ts `fleet`):
 *
 *   fleet:hands    Many Hands     deliveries made by hired drivers, two for each driver out, in a game day
 *   fleet:payroll  Payroll        dollars the drivers' deliveries pay the player, three quarters of a measured day
 *   fleet:rent     Landlord       loads through doors the player owns, by anybody, in a game day
 *
 * Side jobs on the fleet thread, offered by the director like any other. What they pay is set by missions/pay.ts.
 */
import type { MissionCtx } from './missions';
import type { Obj } from './model';
import { squareOf, townRef, townsNear, type Draft, type Template } from './templates';
import { tidy } from './pay';

/** Vehicles out with a hired driver at the wheel, working or following. */
const crewOut = (c: MissionCtx): number => c.units.filter((u) => u.crew).length;

/** Old Bram, who has run a fleet himself, at the nearest town's hall. */
function bram(c: MissionCtx): Draft['giver'] | null {
  const t = townsNear(c, 260)[0];
  return t ? { who: 'haulier', name: 'Old Bram', at: squareOf(t.w, t.t, 'the town hall'), town: townRef(t.w, t.t) } : null;
}

const hands: Template = {
  id: 'fleet:hands', thread: 'fleet', kind: 'job', side: true, cooldown: 36,
  gate(c) { return crewOut(c) >= 1 ? null : 'a driver out first'; },
  bind(c) {
    const g = bram(c);
    if (!g) return null;
    const n = Math.max(4, Math.min(20, 2 + 2 * crewOut(c)));
    const o: Obj = { t: 'fleet', what: 'loads', label: `Run ${n} crew deliveries`, icon: '🚚', n };
    return {
      title: 'Many Hands', why: `A fleet is judged by what it does without you. Have your drivers make ${n} deliveries inside a day, and Bram will spread the word.`,
      details: 'Every delivery a hired driver makes counts, wherever they are. Keep them in Work mode and do whatever you like meanwhile.',
      giver: g, hero: { kind: 'vehicle', model: 'mule' }, caption: 'Your crew at work',
      objs: [o], reward: [{ r: 'cash', n: 100 }, { r: 'gems', n: 1 }], hours: 24,
    };
  },
};

const payroll: Template = {
  id: 'fleet:payroll', thread: 'fleet', kind: 'job', side: true, cooldown: 48,
  gate(c) { return crewOut(c) >= 1 ? null : 'a driver out first'; },
  bind(c) {
    const g = bram(c);
    if (!g) return null;
    // three quarters of what the drivers at work were measured paying in a game day; a guess with nothing measured
    const day = c.fleetDay && c.fleetDay > 0 ? c.fleetDay : crewOut(c) * 600;
    const n = tidy(Math.max(300, day * 0.75));
    const label = `Collect $${n.toLocaleString('en-US')} from drivers`;
    return {
      title: 'Payroll', why: `Bram bets your drivers can't bring in $${n.toLocaleString('en-US')} for you in a single day. Keep them working and prove him wrong.`,
      details: 'Your cut of every delivery your hired drivers make counts toward it. Pick their bases and cargo well (H → Fleet) and it comes in faster.',
      giver: g, hero: { kind: 'crate', colour: 0x3f8fd0 }, caption: 'A day’s takings',
      objs: [{ t: 'fleet', what: 'cash', label: label.length <= 28 ? label : 'Collect the day’s takings', icon: '💵', n }],
      reward: [{ r: 'cash', n: 100 }], hours: 24,
    };
  },
};

const landlord: Template = {
  id: 'fleet:rent', thread: 'hold', also: 'fleet', kind: 'job', side: true, cooldown: 48,
  gate(c) { return c.buildings >= 1 ? null : 'own a building first'; },
  bind(c) {
    const g = bram(c);
    if (!g) return null;
    const n = Math.max(4, Math.min(16, 2 + 2 * c.buildings));
    return {
      title: 'Landlord', why: `Doors you own earn on every load through them. Take rent on ${n} loads inside a day: route your drivers there, or let the trade come.`,
      details: 'Any load that starts or ends at a building you own pays you rent, whoever carries it: you, your drivers, rival firms or other players.',
      giver: g, hero: { kind: 'building', b: 'shop', arch: 'classic', w: 1, d: 1, floors: 2 }, caption: 'Rent day',
      objs: [{ t: 'fleet', what: 'rent', label: `Take rent on ${n} loads`, icon: '🏠', n }],
      reward: [{ r: 'cash', n: 100 }], hours: 24,
    };
  },
};

export const FLEET_TEMPLATES: Template[] = [hands, payroll, landlord];
