import { N, Biome, Flag, World, heightAt, idx, inB, waterDepth } from './tiles';
import { hashCell } from './rng';
import { cellKind } from './macro';

/**
 * Transmission lines (0.8.0, NEXT_080, docs/phonelist.html item 4b): lattice pylons marching in straight runs across
 * the country, a swath cut through any wood they pass, the wires slung between them high over roads, fields and rivers.
 *
 * Each county's lines meet at a hub: its power station if it has one (a coal or nuclear plant's cooling towers, a solar
 * farm, a pumped-storage scheme, a tidal barrage), else just outside its biggest town, where the line comes down to the
 * town's supply. Lines run in from the county's edges, county to county across the continent: whether an edge carries
 * one, and where along it, is hashed from the edge itself, so the two counties either side agree without either seeing
 * the other, and each draws its half of the span that crosses the seam to the same point over it (render/powerLines.ts).
 *
 * Placed last of all on the county (generate.ts), with no rng draws, so nothing else moves; a pylon's foot takes its tile
 * (blocked, like any solid building's), the swath clears the trees along the line.
 */

/** The tiles between pylons, at most (a long crossing may stretch to SPAN_MAX). */
const SPAN = 7, SPAN_MAX = 18;
/** How tall a pylon stands, in world units: well over a house or a wood. */
export const PYLON_H = 2.3;
/** The chance a continental edge between two counties carries a line. */
const EDGE_CHANCE = 0.4;
const SALT = 0x9071;
/** How far in from the seam a line's last pylon stands. */
const SEAM_IN = 3;
/** The kinds of building a line starts at. */
const PLANTS = new Set<string>(['powerPlant', 'coolingTowers', 'solarFarm', 'pumpedHydro', 'tidalBarrage', 'geothermalPlant', 'dam']);

export interface Pylon { x: number; z: number; foot: number }
/** One line: its pylons in order, and where it leaves the county over the seam (null where it ends at its hub or start). */
export interface PowerLine { pylons: Pylon[]; seamA: { x: number; z: number; y: number } | null; seamB: { x: number; z: number; y: number } | null }

/** Where an edge's line crosses the seam, as a tile along it, or -1 where the edge carries none. */
function edgeLine(seedHash: number, ax: number, az: number, horizontal: boolean): number {
  // the edge between (ax, az) and its neighbour east (horizontal: false) or south (true), keyed alike from either side
  const kx = ax * 2 + (horizontal ? 0 : 1), kz = az * 2 + (horizontal ? 1 : 0);
  const h = hashCell(seedHash, kx, kz, SALT);
  if (h / 4294967296 >= EDGE_CHANCE) return -1;
  const bx = horizontal ? ax : ax + 1, bz = horizontal ? az + 1 : az;
  if (cellKind(seedHash, ax, az) !== 'continent' || cellKind(seedHash, bx, bz) !== 'continent') return -1;
  return 48 + ((h >>> 8) % (N - 96));
}

/** The height the wires cross a seam at, from the ground on the seam itself (which both counties read alike). */
function seamHeight(w: World, x: number, z: number): number {
  return heightAt(w, Math.min(N - 0.01, Math.max(0, x)), Math.min(N - 0.01, Math.max(0, z))) + PYLON_H - 0.25;
}

/** Ground a pylon's foot may stand on. */
function footOk(w: World, x: number, z: number): boolean {
  if (x < 1 || z < 1 || x >= N - 1 || z >= N - 1) return false;
  const i = idx(x, z);
  if (w.road[i] || w.rail[i] || w.blocked[i] || w.deckAxis[i] || w.townId[i] >= 0 || w.portId[i] >= 0 || w.lot[i]) return false;
  if (w.water[i] >= 0 || waterDepth(w, i) > 0 || w.biome[i] === Biome.Ocean || w.biome[i] === Biome.Town) return false;
  if (w.flags[i] & (Flag.Poi | Flag.Track | Flag.Ramp | Flag.River | Flag.Stream | Flag.Corridor)) return false;
  let lo = 127, hi = -128;
  for (let q = 0; q < 4; q++) { lo = Math.min(lo, w.corners[i * 4 + q]); hi = Math.max(hi, w.corners[i * 4 + q]); }
  return hi - lo <= 2;
}

/** A pylon at or near (x, z), across the line's way: the nearest good foot within two tiles, or null. */
function footNear(w: World, x: number, z: number, dx: number, dz: number): Pylon | null {
  const px = -dz, pz = dx;
  for (const off of [0, 1, -1, 2, -2]) {
    const tx = Math.round(x + px * off), tz = Math.round(z + pz * off);
    if (footOk(w, tx, tz)) return { x: tx, z: tz, foot: heightAt(w, tx + 0.5, tz + 0.5) };
  }
  return null;
}

/**
 * Pylons along the straight run from a to b, every SPAN tiles or as near as the ground allows. `whole` false when the
 * ground ran out (a lake too wide, a town in the way): then the pylons as far as it got.
 */
function run(w: World, ax: number, az: number, bx: number, bz: number): { pylons: Pylon[]; whole: boolean } | null {
  const len = Math.hypot(bx - ax, bz - az);
  if (len < 4) return null;
  const dx = (bx - ax) / len, dz = (bz - az) / len;
  const out: Pylon[] = [];
  let last = 0;
  for (let s = 0; s <= len + 0.01;) {
    const want = Math.min(s, len);
    let got: Pylon | null = null;
    // the next pylon: as near SPAN on as a foot can be had, stepping on a tile at a time up to SPAN_MAX (the first,
    // by the seam, no more than a few tiles in)
    for (let t = want; t <= Math.min(len, out.length ? last + SPAN_MAX : 4); t += 1) {
      got = footNear(w, ax + dx * t, az + dz * t, dx, dz);
      if (got) { s = t; break; }
    }
    if (!got) return out.length >= 2 ? { pylons: out, whole: false } : null;
    out.push(got);
    last = s;
    if (s >= len - 0.01) break;
    s = Math.min(len, s + SPAN);
  }
  return out.length >= 2 ? { pylons: out, whole: true } : null;
}

/**
 * The way from a to b: straight if it can be, else through a waypoint either side of the straight way, else as far as
 * the straight way goes (the line ends at a terminal pylon short of its hub).
 */
function route(w: World, ax: number, az: number, bx: number, bz: number): Pylon[] | null {
  const direct = run(w, ax, az, bx, bz);
  if (direct?.whole) return direct.pylons;
  const len = Math.hypot(bx - ax, bz - az) || 1;
  const px = -(bz - az) / len, pz = (bx - ax) / len, mx = (ax + bx) / 2, mz = (az + bz) / 2;
  for (const off of [24, -24, 48, -48]) {
    const wx = Math.min(N - 6, Math.max(6, mx + px * off)), wz = Math.min(N - 6, Math.max(6, mz + pz * off));
    const a = run(w, ax, az, wx, wz);
    if (!a?.whole) continue;
    const b = run(w, a.pylons[a.pylons.length - 1].x, a.pylons[a.pylons.length - 1].z, bx, bz);
    if (b?.whole) return [...a.pylons, ...b.pylons.slice(1)];
  }
  return direct?.pylons ?? null;
}

/** Lay the county's lines (generate.ts, last of all). Returns how many pylons stand. */
export function placePowerLines(w: World, seedHash: number): number {
  // the hub: a power station's switchyard, or the ground just outside the biggest town
  const plant = w.allBuildings.find((b) => !b.gone && PLANTS.has(b.kind));
  let hub: { x: number; z: number } | null = null;
  if (plant) hub = { x: plant.x + plant.w / 2, z: plant.z + plant.d / 2 };
  const town = [...w.towns].sort((a, b) => b.size - a.size)[0];
  const townEdge = (from: { x: number; z: number }) => {
    if (!town) return null;
    const cx = town.x0 + town.size / 2, cz = town.z0 + town.size / 2;
    const d = Math.hypot(from.x - cx, from.z - cz) || 1;
    const r = town.size / 2 + 4;
    return { x: cx + ((from.x - cx) / d) * r, z: cz + ((from.z - cz) / d) * r };
  };
  // where lines come in over the seams
  const ins: { x: number; z: number; seam: { x: number; z: number } }[] = [];
  const west = edgeLine(seedHash, w.cx - 1, w.cz, false), east = edgeLine(seedHash, w.cx, w.cz, false);
  const north = edgeLine(seedHash, w.cx, w.cz - 1, true), south = edgeLine(seedHash, w.cx, w.cz, true);
  if (west >= 0) ins.push({ x: SEAM_IN, z: west, seam: { x: 0, z: west + 0.5 } });
  if (east >= 0) ins.push({ x: N - 1 - SEAM_IN, z: east, seam: { x: N, z: east + 0.5 } });
  if (north >= 0) ins.push({ x: north, z: SEAM_IN, seam: { x: north + 0.5, z: 0 } });
  if (south >= 0) ins.push({ x: south, z: N - 1 - SEAM_IN, seam: { x: south + 0.5, z: N } });
  if (!hub && ins.length) hub = townEdge({ x: N / 2, z: N / 2 }) ?? { x: N / 2, z: N / 2 };
  const lines: PowerLine[] = [];
  for (const e of ins) {
    const pyl = route(w, e.x, e.z, hub!.x, hub!.z);
    if (!pyl) continue;
    // the line's end at the seam: its first pylon must be the one by the seam, or the seam span would wander
    if (Math.hypot(pyl[0].x - e.x, pyl[0].z - e.z) > 4.5) continue;
    lines.push({ pylons: pyl, seamA: { x: e.seam.x, z: e.seam.z, y: seamHeight(w, e.seam.x, e.seam.z) }, seamB: null });
  }
  // a station with no line in over the seams still sends one to its town
  if (plant && !lines.length && town) {
    const to = townEdge(hub!);
    const pyl = to ? route(w, hub!.x, hub!.z, to.x, to.z) : null;
    if (pyl) lines.push({ pylons: pyl, seamA: null, seamB: null });
  }
  let n = 0;
  for (const l of lines) {
    for (const p of l.pylons) {
      const i = idx(p.x, p.z);
      if (w.blocked[i]) continue;
      w.blocked[i] = 1;
      w.flags[i] |= Flag.Poi;
      w.roof[i] = Math.max(w.roof[i], p.foot + PYLON_H);
      n++;
    }
    // the swath: no tree within a tile of the wires (the tiles under them are cleared, as the bulldozer clears them)
    for (let k = 0; k + 1 < l.pylons.length; k++) {
      const a = l.pylons[k], b = l.pylons[k + 1];
      const len = Math.hypot(b.x - a.x, b.z - a.z);
      for (let t = 0; t <= len; t += 0.5) {
        const x = Math.round(a.x + ((b.x - a.x) * t) / len), z = Math.round(a.z + ((b.z - a.z) * t) / len);
        for (let d = -1; d <= 1; d++) for (let e = -1; e <= 1; e++) {
          if (!inB(x + d, z + e)) continue;
          const j = idx(x + d, z + e);
          if (w.biome[j] === Biome.Forest && !w.road[j] && w.townId[j] < 0) w.cleared[j] = 1;
        }
      }
    }
  }
  w.powerLines = lines;
  return n;
}

