import { colourName } from './parts';
import { LOGOS, MORE_LOGOS, badgePaint } from './logos';

/**
 * The player's fleet: its name, its two livery colours and its logo, chosen when a game starts
 * (the title's "Your fleet" panel) and kept on the save. Every unit that hasn't been resprayed in
 * the workshop wears the livery, as a rival firm's vehicles wear theirs.
 */

export interface FleetBrand {
  /** 1–24 characters. */
  name: string;
  /** Body colour: one of BRAND_COLOURS, or any colour mixed in the custom picker. */
  primary: number;
  /** Roof and trim, likewise. */
  accent: number;
  /** One of FLEET_LOGOS. */
  logo: string;
}

export const BRAND_NAME_MAX = 24;

/** The logos a fleet can wear: every firm's, and a row only the player picks from. */
export const FLEET_LOGOS: string[] = [...LOGOS, ...MORE_LOGOS];

/** Swatches per row on the "Your fleet" panel; the palette fills two rows, the last slot the custom picker. */
const BRAND_COLUMNS = 14;

/**
 * The livery palette, as the panel lays it out: row one the bright hues swept pink to violet, then
 * the light greys; row two the deeper companion of the colour above it, then the dark greys. Most
 * are the workshop's respray colours (parts.ts PALETTE, left alone); Ocean, Duckling and Denim sat
 * too close to Navy, Canary and Cornflower to earn a swatch, so a fleet saved in one shows it on the
 * custom slot.
 */
const BRAND_PALETTE: { c: number; name: string }[] = [
  { c: 0xf7c5d4, name: 'Candy' }, { c: 0xe2412f, name: 'Tomato' }, { c: 0xef6a4c, name: 'Coral' }, { c: 0xf28c38, name: 'Tangerine' },
  { c: 0xf2a93b, name: 'Marigold' }, { c: 0xf5cf3a, name: 'Canary' }, { c: 0x86c36c, name: 'Lime' }, { c: 0xa7dcc8, name: 'Mint' },
  { c: 0x2bb3a3, name: 'Teal' }, { c: 0x3f78c0, name: 'Cornflower' }, { c: 0x8e5cc7, name: 'Grape' }, { c: 0xf4f2ec, name: 'Chalk' },
  { c: 0xc9ced4, name: 'Silver' }, { c: 0x8a8f96, name: 'Gunmetal' },

  { c: 0xb23a6c, name: 'Raspberry' }, { c: 0x9e2b3a, name: 'Claret' }, { c: 0xa9482a, name: 'Rust' }, { c: 0xb07a4a, name: 'Walnut' },
  { c: 0xd9b34a, name: 'Gold' }, { c: 0x948a2c, name: 'Olive' }, { c: 0x3f9b4a, name: 'Tractor' }, { c: 0x6f9e6b, name: 'Bramble' },
  { c: 0x1f6d66, name: 'Pine' }, { c: 0x2f4d7a, name: 'Navy' }, { c: 0x5c3a84, name: 'Plum' }, { c: 0x5a6169, name: 'Slate' },
  { c: 0x2a2a2e, name: 'Black' },
];

/** The palette the livery is picked from. */
export const BRAND_COLOURS: number[] = BRAND_PALETTE.map((p) => p.c);

/** A livery colour's name: the palette's, the workshop's, or "Custom" and its hex for one mixed in the picker. */
export function brandColourName(c: number): string {
  const n = BRAND_PALETTE.find((p) => p.c === c)?.name ?? colourName(c);
  return n.startsWith('#') ? `Custom ${n}` : n;
}

const FIRST = ['Tiny', 'Little', 'Pocket', 'Plucky', 'Busy', 'Sunny', 'Swift', 'Jolly', 'Happy', 'Bright'];
const LAST = ['Haulage', 'Freight', 'Movers', 'Express', 'Carriers', 'Logistics', 'Transport', 'Couriers'];

const pick = <T>(a: T[]): T => a[Math.floor(Math.random() * a.length)];

/** A fresh random fleet: a name, two colours far enough apart to read, and a logo. */
export function randomBrand(): FleetBrand {
  const primary = pick(BRAND_COLOURS);
  const far = BRAND_COLOURS.filter((c) => Math.abs(lightness(c) - lightness(primary)) > 0.28);
  return { name: `${pick(FIRST)} ${pick(LAST)}`, primary, accent: pick(far.length ? far : BRAND_COLOURS), logo: pick(FLEET_LOGOS) };
}

export const cleanBrandName = (name: string): string => name.trim().replace(/\s+/g, ' ').slice(0, BRAND_NAME_MAX).trim();

/** A brand read back from a save, or null when it isn't one. */
export function readBrand(b: unknown): FleetBrand | null {
  const o = b as Partial<FleetBrand> | null;
  if (!o || typeof o !== 'object' || typeof o.name !== 'string' || typeof o.primary !== 'number' || typeof o.accent !== 'number') return null;
  const rgb = (c: number): number => Math.max(0, Math.min(0xffffff, Math.round(c))) || 0;
  return { name: cleanBrandName(o.name) || 'My Fleet', primary: rgb(o.primary), accent: rgb(o.accent), logo: FLEET_LOGOS.includes(o.logo as string) ? o.logo! : LOGOS[0] };
}

function lightness(c: number): number {
  return (0.299 * ((c >> 16) & 255) + 0.587 * ((c >> 8) & 255) + 0.114 * (c & 255)) / 255;
}

/** The player's fleet in the game being played, for the windows that name carriers; set by Fleet.setBrand. */
export const playerBrand: { current: FleetBrand | null } = { current: null };

const esc = (t: string): string => t.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

/** How the player is named wherever a carrier is: the fleet's badge and name, or plain "You". */
export function youHtml(size = 14): string {
  const b = playerBrand.current;
  return b ? `${badgeHtml(b, size)} ${esc(b.name)}` : 'You';
}

/** The logo in the body colour on the accent, ringed in the body colour: the badge shown wherever the fleet's name is. */
export function badgeHtml(b: FleetBrand, size = 22): string {
  const p = badgePaint(b.primary, b.accent);
  return `<span class="fleet-badge" style="vertical-align:middle;width:${size}px;height:${size}px;font-size:${Math.round(size * 0.58)}px;background:${p.disc};color:${p.glyph};box-shadow:inset 0 0 0 ${Math.max(2, Math.round(size / 9))}px ${p.ring}">${b.logo}</span>`;
}
