/** The symbols a fleet's logo is picked from, the player's and every rival firm's. */
export const LOGOS: string[] = [
  '★', '⚓', '⚡', '♛', '♞', '✦', '❖', '☀', '☾', '♥', '♣', '♠',
  '✿', '❄', '▲', '●', '◆', '✚', '➤', '∞', '☘', '⚑', '✈', '⛵',
];

/**
 * A third row only the player picks from: rival firms hash their logo into LOGOS by its length, so
 * growing that list would hand every firm in an old save a new badge. All text-style symbols that
 * Segoe UI Symbol draws, none of them colour emoji.
 */
export const MORE_LOGOS: string[] = ['⚙', '⚜', '♜', '♫', '✪', '❀', '⬢', '☂', '♦', '⚒', '☯', '✉'];

const lin = (v: number): number => { const s = v / 255; return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
/** Relative luminance, for contrast between two colours. */
const rel = (c: number): number => 0.2126 * lin((c >> 16) & 255) + 0.7152 * lin((c >> 8) & 255) + 0.0722 * lin(c & 255);
const contrast = (a: number, b: number): number => { const x = rel(a), y = rel(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };

const INK = 0x1f2b33, WHITE = 0xffffff;
const css = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;

const mix = (a: number, b: number, t: number): number => {
  const ch = (sh: number): number => Math.round(((a >> sh) & 255) * (1 - t) + ((b >> sh) & 255) * t) << sh;
  return ch(16) | ch(8) | ch(0);
};
/** Contrast a badge's glyph must reach against its disc to read. */
const BADGE_CONTRAST = 2.2;

/**
 * How a badge is painted: the glyph in the body colour on a disc of the accent, ringed in the body
 * colour. The disc always wears the accent the player picked; when the body colour is too close to it
 * to read, the glyph is the body colour shaded toward white or ink (whichever parts it from the accent
 * sooner) just far enough to stand out, so both colours still show.
 */
export function badgePaint(body: number, accent: number): { disc: string; glyph: string; ring: string } {
  let glyph = body;
  if (contrast(body, accent) < BADGE_CONTRAST) {
    const to = contrast(accent, WHITE) >= contrast(accent, INK) ? WHITE : INK;
    for (let t = 0.05; t <= 1.0001; t += 0.05) {
      glyph = mix(body, to, Math.min(1, t));
      if (contrast(glyph, accent) >= BADGE_CONTRAST) break;
    }
  }
  return { disc: css(accent), glyph: css(glyph), ring: css(body) };
}
