/**
 * The named woods' own trees and floor (world/woods.ts, 0.8.0), in the style of the ordinary trees: merged low-poly
 * parts, each coloured and marked for the year by `aLeaf` (regionProps.ts paint), drawn instanced by render/props.ts.
 *
 *   aspen        a slim white trunk, a narrow crown of small leaves that goes gold in autumn (as a birch's does)
 *   maple        a stout trunk under a broad round crown that burns scarlet in autumn
 *   fir          an old-growth giant: a tall dark spire of tiers, bare for its lower third
 *   larch        a conifer that turns gold and drops its needles: sparse pale tiers
 *   baldCypress  a flared, buttressed foot standing in the water, a flat feathery top, Spanish moss hanging
 *   mangrove     a short trunk held up on arching stilt roots, a dense dark crown
 *   eucalyptus   a tall pale trunk forking high, wisps of grey-blue leaves
 *   snag         a dead tree: a broken trunk and a few bare stubs (a burn scar's, darker; a drowned wood's, paler)
 *   log          a fallen trunk lying on the floor of an old wood, moss along its top
 */
import * as THREE from 'three';
import { boughs, limb, merge, paint } from './regionProps';

function aspenGeometry(): THREE.BufferGeometry {
  return merge([
    paint(limb([0, 0, 0], [0.02, 1.05, 0], 0.034, 0.02, 5), 0xf1eee6),
    paint(new THREE.CylinderGeometry(0.035, 0.036, 0.04, 5, 1, true).translate(0.004, 0.24, 0), 0x2f2b28),
    paint(new THREE.CylinderGeometry(0.03, 0.031, 0.03, 5, 1, true).translate(0.01, 0.52, 0), 0x2f2b28),
    ...boughs([0.02, 0.6, 0], 1.2, 0.12, 0.6, 0xddd8cf, 3),
    paint(new THREE.IcosahedronGeometry(0.15, 0).scale(1, 1.6, 1).translate(0.02, 1.02, 0), 0x86c25e, 4),
    paint(new THREE.IcosahedronGeometry(0.12, 0).scale(1, 1.4, 1).translate(-0.07, 0.8, 0.05), 0x92c868, 4),
    paint(new THREE.IcosahedronGeometry(0.1, 0).scale(1, 1.3, 1).translate(0.08, 0.72, -0.04), 0x7cb856, 4),
  ]);
}

function mapleGeometry(): THREE.BufferGeometry {
  return merge([
    paint(limb([0, 0, 0], [0.02, 0.42, 0], 0.075, 0.055, 6), 0x6b5440),
    ...boughs([0.02, 0.4, 0], 0.92, 0.36, 0.2, 0x6b5440, 5),
    paint(new THREE.IcosahedronGeometry(0.4, 0).scale(1.2, 0.85, 1.2).translate(0, 0.78, 0), 0x4f9e48, 2),
    paint(new THREE.IcosahedronGeometry(0.26, 0).scale(1.2, 0.9, 1.1).translate(0.28, 0.66, 0.12), 0x5aaa50, 2),
    paint(new THREE.IcosahedronGeometry(0.24, 0).scale(1.2, 0.9, 1.1).translate(-0.26, 0.68, -0.14), 0x48923f, 2),
    paint(new THREE.IcosahedronGeometry(0.2, 0).translate(0.02, 1.06, 0.04), 0x5fae53, 2),
  ]);
}

function firGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(limb([0, 0, 0], [0, 0.7, 0], 0.075, 0.055, 6), 0x5a3e2a),
    paint(limb([0, 0.7, 0], [0, 1.55, 0], 0.055, 0.02, 5), 0x4e3624),
    paint(new THREE.ConeGeometry(0.12, 0.16, 6, 1, true).translate(0, 0.08, 0), 0x4e3624),
  ];
  const tiers: [number, number, number][] = [[0.52, 0.32, 0.36], [0.76, 0.28, 0.34], [0.98, 0.23, 0.32], [1.18, 0.17, 0.3], [1.36, 0.11, 0.28]];
  tiers.forEach(([y, r, h], k) => parts.push(paint(new THREE.ConeGeometry(r, h, 7).rotateY(k * 0.6).translate(0, y + h / 2, 0), k % 2 ? 0x24503a : 0x1f4632, 1)));
  return merge(parts);
}

function larchGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [paint(limb([0, 0, 0], [0, 1.1, 0], 0.045, 0.012, 5), 0x7a5a40)];
  const tiers: [number, number, number][] = [[0.3, 0.27, 0.3], [0.52, 0.22, 0.28], [0.72, 0.16, 0.26], [0.9, 0.1, 0.24]];
  tiers.forEach(([y, r, h], k) => parts.push(paint(new THREE.ConeGeometry(r, h, 6, 1, true).rotateY(k * 0.7).translate(0, y + h / 2, 0), k % 2 ? 0x8cbf62 : 0x7fb35a, 2)));
  return merge(parts);
}

function baldCypressGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    // the flared foot, wide where it stands in the water, and the knees round it
    paint(new THREE.CylinderGeometry(0.06, 0.17, 0.26, 7, 1, true).translate(0, 0.13, 0), 0x7a6a58),
    paint(limb([0, 0.25, 0], [0.02, 0.95, 0], 0.06, 0.035, 6), 0x7a6a58),
  ];
  for (let k = 0; k < 4; k++) {
    const a = k * 1.7 + 0.4;
    parts.push(paint(new THREE.ConeGeometry(0.03, 0.12, 4).translate(Math.cos(a) * 0.26, 0.06, Math.sin(a) * 0.26), 0x6e5e4c));
  }
  // the flat feathery top
  parts.push(paint(new THREE.IcosahedronGeometry(0.34, 0).scale(1.35, 0.4, 1.25).translate(0.02, 1.02, 0), 0x6d8f4a, 2));
  parts.push(paint(new THREE.IcosahedronGeometry(0.24, 0).scale(1.3, 0.45, 1.2).translate(0.2, 0.86, 0.1), 0x799b52, 2));
  parts.push(paint(new THREE.IcosahedronGeometry(0.22, 0).scale(1.3, 0.45, 1.2).translate(-0.2, 0.9, -0.12), 0x648444, 2));
  // Spanish moss hanging from the crown
  for (let k = 0; k < 6; k++) {
    const a = (k / 6) * Math.PI * 2 + 0.3, h = 0.22 + (k % 3) * 0.06;
    parts.push(paint(new THREE.ConeGeometry(0.05, h, 3, 1, true).rotateX(Math.PI).translate(Math.cos(a) * 0.3, 0.88 - h / 2, Math.sin(a) * 0.28), 0xa3a88e));
  }
  return merge(parts);
}

function mangroveGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [paint(limb([0, 0.28, 0], [0.02, 0.6, 0], 0.05, 0.04, 5), 0x6a5444)];
  // the stilt roots, arching out from the trunk down into the mud
  for (let k = 0; k < 6; k++) {
    const a = (k / 6) * Math.PI * 2;
    const mx = Math.cos(a) * 0.16, mz = Math.sin(a) * 0.16;
    parts.push(paint(limb([0, 0.32, 0], [mx, 0.24, mz], 0.025, 0.02, 3), 0x6a5444));
    parts.push(paint(limb([mx, 0.24, mz], [mx * 1.9, 0, mz * 1.9], 0.02, 0.016, 3), 0x5e4a3c));
  }
  parts.push(paint(new THREE.IcosahedronGeometry(0.34, 0).scale(1.25, 0.75, 1.2).translate(0, 0.74, 0), 0x2f6f3a, 1));
  parts.push(paint(new THREE.IcosahedronGeometry(0.22, 0).scale(1.2, 0.8, 1.1).translate(0.24, 0.66, 0.1), 0x377a42, 1));
  parts.push(paint(new THREE.IcosahedronGeometry(0.2, 0).scale(1.2, 0.8, 1.1).translate(-0.22, 0.68, -0.12), 0x2a6534, 1));
  return merge(parts);
}

function eucalyptusGeometry(): THREE.BufferGeometry {
  return merge([
    paint(limb([0, 0, 0], [0.03, 0.85, 0], 0.05, 0.035, 5), 0xe6dccb),
    paint(limb([0.03, 0.85, 0], [0.2, 1.35, 0.06], 0.033, 0.016, 4), 0xddd2bf),
    paint(limb([0.03, 0.85, 0], [-0.16, 1.3, -0.08], 0.03, 0.014, 4), 0xddd2bf),
    // a strip of bark peeling off low down
    paint(new THREE.BoxGeometry(0.02, 0.22, 0.045).rotateZ(0.12).translate(0.05, 0.3, 0.02), 0x9a7a5a),
    paint(new THREE.IcosahedronGeometry(0.2, 0).scale(1.3, 0.8, 1.1).translate(0.22, 1.4, 0.06), 0x8aa898, 1),
    paint(new THREE.IcosahedronGeometry(0.18, 0).scale(1.3, 0.8, 1.1).translate(-0.17, 1.34, -0.08), 0x7f9e8e, 1),
    paint(new THREE.IcosahedronGeometry(0.13, 0).scale(1.2, 0.8, 1).translate(0.06, 1.12, 0.12), 0x93b0a0, 1),
  ]);
}

function snagGeometry(): THREE.BufferGeometry {
  return merge([
    paint(limb([0, 0, 0], [0.04, 0.95, 0.02], 0.055, 0.025, 5), 0x857a6e),
    // the snapped top
    paint(new THREE.ConeGeometry(0.03, 0.12, 4).rotateZ(0.5).translate(0.06, 1.0, 0.02), 0x766b60),
    paint(limb([0.02, 0.48, 0], [0.24, 0.66, 0.05], 0.022, 0.01, 3), 0x7a6f64),
    paint(limb([0.03, 0.66, 0.01], [-0.18, 0.84, -0.04], 0.018, 0.008, 3), 0x7a6f64),
    paint(limb([0.03, 0.3, 0], [0.04, 0.38, 0.17], 0.018, 0.008, 3), 0x7a6f64),
  ]);
}

function logGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.CylinderGeometry(0.07, 0.08, 0.8, 6).rotateZ(Math.PI / 2).translate(0, 0.07, 0), 0x6e5a46),
    paint(new THREE.BoxGeometry(0.62, 0.025, 0.07).translate(-0.04, 0.145, 0), 0x5f8a44),
    // the root plate at one end, standing on edge
    paint(new THREE.CylinderGeometry(0.16, 0.16, 0.05, 7).rotateZ(Math.PI / 2).translate(0.42, 0.1, 0), 0x5e4b3a),
  ]);
}

export interface WoodTreeGeometries {
  aspen: THREE.BufferGeometry; maple: THREE.BufferGeometry; fir: THREE.BufferGeometry; larch: THREE.BufferGeometry;
  baldCypress: THREE.BufferGeometry; mangrove: THREE.BufferGeometry; eucalyptus: THREE.BufferGeometry; snag: THREE.BufferGeometry;
  log: THREE.BufferGeometry;
}
export function createWoodTreeGeometries(): WoodTreeGeometries {
  return {
    aspen: aspenGeometry(), maple: mapleGeometry(), fir: firGeometry(), larch: larchGeometry(), baldCypress: baldCypressGeometry(),
    mangrove: mangroveGeometry(), eucalyptus: eucalyptusGeometry(), snag: snagGeometry(), log: logGeometry(),
  };
}
