import { World, RoadType, type Bridge } from './tiles';
import { layRoad } from './roads';
import { buildEdges } from './graph';
import { demolish, targetAt } from '../game/demolish';
import { applyBuild, applyClaim, applyLift, applyRing, applyTownRoad, applyWear, type GrowthEdit } from './growth';
import { applyLand, type LandBlock } from './landCodec';
import { applyPaths, type PathBlock } from './paths';
import { applyProp } from './scenery';
import { layRail, layStation, mendJoins, type RailSpec, type StationSpec } from './railBuild';
import { applyErect, type ErectSpec } from './erect';

/**
 * One thing that changed an island after it was generated: a road the player built or a tile they
 * bulldozed, or something a town did as its fortunes changed (see `growth.ts`). A road the town grew
 * carries `tw`, the town's id, and `g`.
 */
export type Edit =
  // a bridge is [from, to, h0, h1] and, since the long spans, tolls and flyovers, an optional fifth
  // number of flags — 1 a suspension span, 2 a toll bridge, 4 a flyover (whose crest height is the
  // sixth number), 8 a tunnel; 32 raised over broad water for boats, 64 an elevated stretch (both carry
  // the crest too); 128 a raised road's level platform (from === to, h0 its height). A save from before
  // them has four numbers and so has none of them.
  | { k: 'road'; t: RoadType; n: number[]; b?: number[][]; tw?: number; g?: 1 }
  | { k: 'raze'; x: number; z: number }
  // a boost pad the player laid on a road tile (the builder's Boost pad mode): `i` the tile, `d` the way it
  // shoves (DIRS), 4 or 5 a two-way pad along DIRS[0] or DIRS[1] (world/jumps.ts TWO_WAY), or -1 for one taken up.
  // Pads the worldgen laid are in the island already (world/jumpsGen.ts).
  | { k: 'pad'; i: number; d: number }
  // a piece of scenery placed from the builder (world/scenery.ts): where in the cell's tiles, which, and
  // turned how many eighths; `p` empty takes up the piece nearest the point
  | { k: 'prop'; x: number; z: number; p: string; r?: number; by?: string }
  // a track the player laid from the builder's Rails side (world/railBuild.ts): its points x, z, y (tiles and steps),
  // the line's period, and how each end meets the world (buffers when missing, a join onto another path, or the
  // cell border); `nm` names the line
  | ({ k: 'rail'; by?: string } & RailSpec)
  // a station the player put up (world/railBuild.ts): its kind, its lot's origin tile and facing, the period and name
  | ({ k: 'station'; by?: string } & StationSpec)
  // a building a fleet put up from its blueprints (world/erect.ts, docs/blueprints.html): the copy's kind, lot, facing,
  // storeys, seed and style, the hours its site runs; online the server stamps who and when (`at`, the hour work began)
  | ({ k: 'erect'; by?: string; at?: number } & ErectSpec)
  | Exclude<GrowthEdit, { k: 'road' }>;

/**
 * Everything that has changed on one island, in the order it happened. The island itself is never
 * stored: it is generated again from the seed and these few edits replayed over it, which is what
 * keeps a saved game to a few kilobytes however far you have driven.
 */
export interface CellDelta {
  edits: Edit[];
  /**
   * Earthworks (docs/terrain.html): how far the player has moved this island's ground and water from
   * the generator's, by 16×16 chunk (see landCodec.ts). A result, not a history. From save 15.
   */
  land?: LandBlock;
  /**
   * Online only: the paths other players' tyres have worn into open ground here (docs/community.html,
   * world/paths.ts), as the server counts them. Never saved: it comes with the cell each time.
   */
  paths?: PathBlock;
}

export const emptyDelta = (): CellDelta => ({ edits: [] });
export const isEmptyDelta = (d: CellDelta | undefined): boolean => !d || (d.edits.length === 0 && !d.land && !d.paths);

/** Record a road the player has just built. */
export function noteRoad(d: CellDelta, type: RoadType, nodes: number[], bridges: Bridge[] | undefined): void {
  const e: Edit = { k: 'road', t: type, n: nodes.slice() };
  if (bridges?.length) {
    e.b = bridges.map((b) => {
      const flags = (b.suspension ? 1 : 0) | (b.toll ? 2 : 0) | (b.peak !== undefined ? 4 : 0) | (b.tunnel ? 8 : 0) | (b.ramp ? 16 : 0)
        | (b.raised === 1 ? 32 : b.raised === 2 ? 64 : 0) | (b.level ? 128 : 0);
      if (b.ramp) return [b.from, b.to, b.h0, b.h1, flags, b.peak!, b.ramp];
      if (b.peak !== undefined) return [b.from, b.to, b.h0, b.h1, flags, b.peak];
      return flags ? [b.from, b.to, b.h0, b.h1, flags] : [b.from, b.to, b.h0, b.h1];
    });
  }
  d.edits.push(e);
}

/** Record a bulldozed tile. */
export function noteRaze(d: CellDelta, x: number, z: number): void {
  d.edits.push({ k: 'raze', x, z });
}

/** Record a boost pad laid, turned round (`d` its new way) or taken up (`d` -1). */
export function notePad(d: CellDelta, i: number, dir: number): void {
  d.edits.push({ k: 'pad', i, d: dir });
}

/** Record a piece of scenery placed (`p` its id) or taken up (`p` empty: the one nearest the point). */
export function noteProp(d: CellDelta, x: number, z: number, p: string, r = 0): void {
  d.edits.push(p ? { k: 'prop', x, z, p, r } : { k: 'prop', x, z, p: '' });
}

/** Record a track laid from the builder. */
export function noteRail(d: CellDelta, spec: RailSpec): void {
  const e: Edit = { k: 'rail', p: spec.p.map((v) => Math.round(v * 100) / 100), era: spec.era };
  if (spec.a) e.a = spec.a;
  if (spec.b) e.b = spec.b;
  if (spec.nm) e.nm = spec.nm;
  d.edits.push(e);
}

/** Record a station put up from the builder. */
export function noteStation(d: CellDelta, spec: StationSpec): void {
  d.edits.push({ k: 'station', ...spec });
}

/** Record a building a fleet broke ground on (world/erect.ts), `at` the game hour it did. */
export function noteErect(d: CellDelta, spec: ErectSpec, at: number): Extract<Edit, { k: 'erect' }> {
  const e: Extract<Edit, { k: 'erect' }> = { k: 'erect', ...spec, at: Math.round(at * 10) / 10 };
  d.edits.push(e);
  return e;
}

/** Forget the most recent track or station the player laid: they have just undone it. */
export function forgetLastRail(d: CellDelta): void {
  for (let k = d.edits.length - 1; k >= 0; k--) {
    const e = d.edits[k];
    if (e.k === 'rail' || e.k === 'station') { d.edits.splice(k, 1); return; }
  }
}

/** Forget the most recent road the player built: they have just undone it. Roads a town grew are not theirs to undo. */
export function forgetLastRoad(d: CellDelta): void {
  for (let k = d.edits.length - 1; k >= 0; k--) {
    const e = d.edits[k];
    if (e.k === 'road' && !e.g) { d.edits.splice(k, 1); return; }
  }
}

/**
 * Apply one edit to an island. Returns the tiles it changed. Shared by the replay below and by the
 * economy when a town grows or wears in play, so the two can never disagree.
 */
export function applyEdit(w: World, e: Edit): number[] {
  switch (e.k) {
    case 'road': {
      if (e.g && e.tw !== undefined) {
        const t = w.towns[e.tw];
        if (!t) return [];
        t.roads++;
        return applyTownRoad(w, t, { k: 'road', t: e.t, n: e.n, tw: e.tw, g: 1 }, layRoad);
      }
      const bridges: Bridge[] = (e.b ?? []).map(([from, to, h0, h1, flags = 0, peak, ramp]) => ({
        from, to, h0, h1,
        suspension: !!(flags & 1) || undefined, toll: !!(flags & 2) || undefined,
        peak: flags & 4 ? peak : undefined, tunnel: !!(flags & 8) || undefined,
        ramp: flags & 16 ? ramp : undefined,
        raised: flags & 32 ? 1 as const : flags & 64 ? 2 as const : undefined,
        level: flags & 128 ? true as const : undefined,
      }));
      return layRoad(w, e.t, e.n, undefined, bridges).tiles;
    }
    case 'raze':
      return demolish(w, targetAt(w, e.x, e.z));
    case 'prop':
      return applyProp(w, e);
    case 'rail':
      // its joins found by where they stand, should the county's list of paths have moved under them (mendJoins)
      return layRail(w, mendJoins(w, e)).tiles;
    case 'station':
      return layStation(w, e).tiles;
    case 'erect':
      return applyErect(w, e);

    case 'pad': {
      if (!(e.i >= 0 && e.i < w.boost.length)) return [];
      // only on a road: a pad replayed onto a tile since bulldozed has nothing to sit on
      if (e.d < 0) w.boost[e.i] = 0;
      else if (w.road[e.i] && e.d < 6) w.boost[e.i] = e.d + 1;
      else return [];
      return [e.i];
    }
    case 'build': {
      const t = w.towns[e.t];
      return t ? applyBuild(w, t, e.b) : [];
    }
    case 'lift': {
      const b = w.allBuildings[e.u];
      return b && !b.gone ? applyLift(w, b, e.floors, e.kind) : [];
    }
    case 'wear': {
      const b = w.allBuildings[e.u];
      return b && !b.gone ? applyWear(w, b, e.on === 1) : [];
    }
    case 'ring': {
      const t = w.towns[e.t];
      if (t) applyRing(t);
      return [];
    }
    case 'claim': {
      const t = w.towns[e.t];
      return t ? applyClaim(w, t, e.n) : [];
    }
    // an edit this build doesn't know (online, from a newer game): left alone rather than thrown
    default:
      return [];
  }
}

/**
 * Replay the edits over a freshly generated island. Generation is a pure function of the seed and
 * the cell, so the same edits land on exactly the tiles they were made on.
 *
 * The earthworks overlay goes down first, before any edit, because it is kept as a result rather than
 * in order. That is only right while nothing that replays reads the ground under a tile the player
 * could still dig afterwards. Today exactly one edit reads corners — 'build', which averages the
 * ground under a new building to cut its pad — and a built tile is a building's footprint for good,
 * standing or bulldozed, which the land tool refuses even in a town the player holds (land.ts, Fix.Pad).
 * Any new edit that reads the ground must
 * keep that true, or `npm run land`'s round trip fails; it is there to fail.
 */
export function applyDelta(w: World, d: CellDelta | undefined): void {
  if (isEmptyDelta(d)) return;
  applyLand(w, d!.land);
  for (const e of d!.edits) applyEdit(w, e);
  // worn paths after the edits: a road laid since over a worn tile is a road (paths.ts pathBarred)
  applyPaths(w, d!.paths);
  buildEdges(w);
}
