import type { Building, BuildingKind } from '../../../world/tiles';
import { padLocal } from '../../../world/helipads';
import { hex, scale } from '../../../world/biomes';
import { COOL_GLOW, DARK, METAL, WARM_GLOW, type Draw, type Kit, type P3 } from '../kit';

/**
 * Alternatives for the airport terminal (the user, 25 Oct 2026: "5 more variants of airport terminal buildings
 * based on architecturally significant airport terminals"), each after one famous building:
 *
 * - **TWA Flight Center**, JFK (Eero Saarinen, 1962): the white concrete bird, its shell wings lifting at the ends
 *   over sloping glass, a beak over the kerb, and the red-carpeted flight tubes out to the gates;
 * - **Washington Dulles** (Saarinen, 1962): the roof hung like a hammock between two rows of outward-leaning
 *   pylons, the front row taller, and a mobile lounge on its scissor legs at the airside;
 * - **Denver International** (Fentress Bradburn, 1995): the white fabric roof's row of peaks after the Rockies,
 *   each tent on its mast;
 * - **Kansai International** (Renzo Piano, 1994): the long glider of a roof, rising from the landside and sweeping
 *   down to the gates, tapering to both ends, in stainless panels;
 * - **Madrid-Barajas T4** (Richard Rogers and Estudio Lamela, 2006): the rolling wave roof on its Y-shaped trees,
 *   painted down the building's length from blue through green and yellow to red.
 *
 * Drawn as the terminal is (game frame: the long side along x, the landside kerb at +z, the gates at −z, jetways
 * reaching out to the stands as the original's do), in the works' own colours whatever the town, and keeping every
 * wall a car meets inside the lot, and the terminal's helipad (world/helipads.ts) on a deck at its own height.
 * Render only: picked from the building's seed (./index.ts).
 */

const CONCRETE = hex(0xf1efe8), SHELL_SHADE = hex(0xdedbd2), GLASS_DARK = hex(0x5d87a6), GLASS_PALE = hex(0x9cc6d9);
const TUBE_RED = hex(0xc8352b), FABRIC = hex(0xf7f7f3), FABRIC_SHADE = hex(0xe4e4de), STEEL = hex(0xc9cfd4), STEEL_DARK = hex(0xb4bcc3);
const GLOW_HOURS: [number, number, number] = [15, 30, 1.2];

/** The glazed hall under a roof: glass all round, lit at night, a little inside the lot. */
function hall(k: Kit, W: number, D: number, h: number, glass = GLASS_DARK): void {
  k.box(0, 0, 0, W, 0.12, D, hex(0xd8d6d0));
  k.glowBox(0, 0.12, 0, W - 0.05, h - 0.12, D - 0.05, glass, GLOW_HOURS, COOL_GLOW);
}

/** The jetways out to the stands: raised arms off the airside face, each on a leg inside the lot. */
function jetways(k: Kit, W: number, D: number, y: number, arms: number, col = hex(0xd3cec3)): void {
  for (let i = 0; i < arms; i++) {
    const o = arms === 1 ? 0 : -(W - 2) / 2 + ((W - 2) / (arms - 1)) * i;
    // (reaching as far past the lot as the original's do)
    k.box(o, y, -D / 2 - 0.2, 0.3, 0.3, 1.0, col);
    k.box(o, 0, -D / 2 + 0.12, 0.09, y, 0.09, METAL);
  }
}

/**
 * The helipad (world/helipads.ts padLocal: every terminal has one, where the helicopter work lands): a deck at its
 * height on four slim legs, so the pad's paint and the landing agree whatever roof is under it. Returns its x span.
 */
function padDeck(k: Kit, b: Building, W: number, D: number): [number, number] {
  const p = padLocal(b, W, D);
  if (!p) return [Infinity, -Infinity];
  const half = p.s * 0.62;
  k.box(p.x, p.y - 0.06, p.z, half * 2, 0.06, half * 2, hex(0x8c8f93), hex(0x6f7377));
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(p.x + sx * (half - 0.08), 0.45, p.z + sz * (half - 0.08), 0.06, p.y - 0.51, 0.06, METAL);
  return [p.x - half, p.x + half];
}

/** A surface over the lot from a height field: nx × nz quads, coloured per strip along x (and its underside). */
function sheet(k: Kit, x0: number, x1: number, z0: number, z1: number, nx: number, nz: number, y: (u: number, v: number) => number, col: (i: number) => ReturnType<typeof hex>, under?: ReturnType<typeof hex>): void {
  const P = (i: number, j: number): P3 => { const u = i / nx, v = j / nz; return [x0 + (x1 - x0) * u, y(u, v), z0 + (z1 - z0) * v]; };
  for (let i = 0; i < nx; i++) {
    for (let j = 0; j < nz; j++) {
      const a = P(i, j), b = P(i + 1, j), c = P(i + 1, j + 1), d = P(i, j + 1);
      const m: P3 = [(a[0] + c[0]) / 2, (a[1] + c[1]) / 2, (a[2] + c[2]) / 2];
      k.quad(a, b, c, d, col(i), [m[0], m[1] - 1, m[2]]);
      if (under) k.quad(a, b, c, d, under, [m[0], m[1] + 1, m[2]]);
    }
  }
}

/** TWA Flight Center: the concrete bird. */
const twa: Draw = (k, W, D, b) => {
  const h = 0.6 + b.floors * 0.2;
  const hw = W / 2 - 0.4, front = D / 2 - 0.25, back = -D / 2 + 0.55;
  // glass under the shell, sloping out toward the kerb as Saarinen's does
  k.box(0, 0, 0, W - 0.3, 0.12, D - 0.3, hex(0xd8d6d0));
  k.glowBox(0, 0.12, -0.05, W - 0.7, h - 0.15, D - 0.7, GLASS_DARK, GLOW_HOURS, COOL_GLOW);
  // the four shells: low where they meet in the middle, lifting to the wingtips at either end, and down to four piers
  // (the wingtips stay under the helipad's deck at the east end)
  const mid = h + 0.1, tip = Math.min(h + 0.72, (padLocal(b, W, D)?.y ?? 9) - 0.08);
  const C: P3 = [0, mid, 0.1];
  for (const sx of [-1, 1]) {
    const tipF: P3 = [sx * hw, tip, front - 0.4], tipB: P3 = [sx * hw, tip - 0.25, back + 0.3];
    const midF: P3 = [sx * 0.2, mid + 0.05, front], midB: P3 = [sx * 0.2, mid - 0.05, back];
    const pierF: P3 = [sx * (hw - 0.5), 0, front - 0.7], pierB: P3 = [sx * (hw - 0.5), 0, back + 0.5];
    const inside: P3 = [sx * hw * 0.5, mid - 0.4, 0];
    // the shell's top, in two sweeps out from the middle to the wingtip
    k.tri(C, midF, tipF, CONCRETE, inside);
    k.tri(C, tipF, tipB, CONCRETE, inside);
    k.tri(C, tipB, midB, SHELL_SHADE, inside);
    // the underside, seen from below the wing
    k.tri(C, tipF, midF, SHELL_SHADE, [sx * hw * 0.5, mid + 0.6, 0]);
    k.tri(C, tipB, tipF, SHELL_SHADE, [sx * hw * 0.5, mid + 0.6, 0]);
    // the Y-piers carrying each wing down to the ground
    k.bar(pierF, tipF, 0.09, CONCRETE);
    k.bar(pierB, tipB, 0.09, CONCRETE);
    k.box(pierF[0], 0, pierF[2], 0.28, 0.12, 0.28, CONCRETE);
    k.box(pierB[0], 0, pierB[2], 0.28, 0.12, 0.28, CONCRETE);
  }
  // the beak over the kerb, and the red glow of the lounge inside
  k.tri([-0.9, mid + 0.05, front], [0.9, mid + 0.05, front], [0, mid - 0.15, front + 0.22], CONCRETE, [0, mid - 0.5, front - 0.3]);
  k.glowBox(0, 0.14, 0.3, W - 2.4, 0.12, D - 2.2, TUBE_RED, GLOW_HOURS, WARM_GLOW);
  // the flight tubes: two raised tubes out to round gate pods at the airside edge
  for (const sx of [-1, 1]) {
    const x = sx * (W / 2 - 2.2);
    k.bar([x * 0.4, h * 0.55, back], [x, h * 0.55, -D / 2 + 0.35], 0.13, CONCRETE);
    k.glowBox(x * 0.7, h * 0.55 - 0.05, (back - D / 2 + 0.35) / 2, 0.06, 0.1, 0.5, TUBE_RED, GLOW_HOURS, WARM_GLOW);
    k.cyl(x, 0, -D / 2 + 0.35, 0.32, h * 0.8, CONCRETE, 10, SHELL_SHADE);
  }
  jetways(k, W, D, h * 0.45, b.floors > 1 ? 2 : 1);
  padDeck(k, b, W, D);
};

/** Washington Dulles: the hammock roof between leaning pylons. */
const dulles: Draw = (k, W, D, b) => {
  const front = D / 2 - 0.35, back = -D / 2 + 0.45;
  const hiF = 1.35 + b.floors * 0.3, hiB = hiF * 0.72;
  hall(k, W - 0.8, D - 1.3, hiB - 0.2, GLASS_PALE);
  const n = Math.max(6, Math.round(W / 1.2));
  const xs: number[] = [];
  for (let i = 0; i < n; i++) xs.push(-W / 2 + 0.4 + ((W - 0.8) * i) / (n - 1));
  // the pylons: tapering, leaning out, the front ones taller
  for (const x of xs) {
    k.bar([x, 0, front - 0.25], [x, hiF, front], 0.07, CONCRETE);
    k.bar([x, 0, back + 0.25], [x, hiB, back], 0.06, CONCRETE);
    k.box(x, 0, front - 0.25, 0.24, 0.1, 0.24, SHELL_SHADE);
    k.box(x, 0, back + 0.25, 0.22, 0.1, 0.22, SHELL_SHADE);
  }
  // the roof hung between them: a catenary sag front to back, the same the whole length
  const sag = 0.55;
  sheet(k, xs[0], xs[xs.length - 1], back, front, n - 1, 5, (_u, v) => hiB + (hiF - hiB) * v - sag * 4 * v * (1 - v), (i) => (i % 2 ? CONCRETE : SHELL_SHADE), hex(0xc9c6bd));
  // the mobile lounge (the "people mover"), up on its scissor legs at the airside
  const mx = W / 2 - 1.6;
  k.box(mx, 0.55, -D / 2 + 0.55, 1.1, 0.4, 0.55, hex(0xf4f2ec));
  k.glowBox(mx, 0.68, -D / 2 + 0.55, 1.12, 0.14, 0.57, GLASS_DARK, GLOW_HOURS, COOL_GLOW);
  for (const sx of [-1, 1]) {
    k.bar([mx + sx * 0.4, 0, -D / 2 + 0.4], [mx - sx * 0.4, 0.55, -D / 2 + 0.4], 0.025, DARK);
    k.bar([mx + sx * 0.4, 0, -D / 2 + 0.7], [mx - sx * 0.4, 0.55, -D / 2 + 0.7], 0.025, DARK);
  }
  jetways(k, W - 2.4, D, 0.5, b.floors > 1 ? 2 : 1);
  padDeck(k, b, W, D);
};

/** Denver International: the white tents of the Rockies. */
const denver: Draw = (k, W, D, b) => {
  const h = 0.55 + b.floors * 0.2;
  hall(k, W - 0.4, D - 0.8, h);
  const [p0, p1] = padDeck(k, b, W, D);
  const peaks = Math.max(3, Math.round(W / 1.7));
  const pw = (W - 0.4) / peaks, z0 = -(D - 0.8) / 2, z1 = (D - 0.8) / 2;
  for (let i = 0; i < peaks; i++) {
    const cx = -(W - 0.4) / 2 + pw * (i + 0.5);
    const top = h + 1.0 + (i % 2 ? 0 : 0.35) + (i === Math.floor(peaks / 2) ? 0.2 : 0);
    const x0 = cx - pw / 2, x1 = cx + pw / 2;
    // the bay under the helipad keeps a flat roof
    if (x1 > p0 + 0.25 && x0 < p1 - 0.25) { k.box(cx, h, 0, pw, 0.08, D - 0.8, FABRIC_SHADE); continue; }
    // each tent: its peak on the mast, the fabric drooping to the eaves between the corners
    const P: P3 = [cx, top, 0];
    const eave = (x: number, z: number, low = 0): P3 => [x, h + 0.05 - low, z];
    const sides: [P3, P3, P3][] = [
      [eave(x0, z1), eave(cx, z1, -0.18), eave(x1, z1)], [eave(x1, z1), eave(x1, 0, -0.18), eave(x1, z0)],
      [eave(x1, z0), eave(cx, z0, -0.18), eave(x0, z0)], [eave(x0, z0), eave(x0, 0, -0.18), eave(x0, z1)],
    ];
    const I: P3 = [cx, h + 0.2, 0];
    sides.forEach(([a, m, c], s) => {
      k.tri(P, a, m, s % 2 ? FABRIC_SHADE : FABRIC, I);
      k.tri(P, m, c, s % 2 ? FABRIC : FABRIC_SHADE, I);
    });
    // the mast through the peak, and its stay
    k.cyl(cx, top - 0.1, 0, 0.03, 0.35, METAL, 5);
  }

  jetways(k, W, D - 0.4, h * 0.8, b.floors > 1 ? 3 : 1);
};

/** Kansai International: the glider. */
const kansai: Draw = (k, W, D, b) => {
  const base = 0.65 + b.floors * 0.2, lift = 0.75;
  const z0 = -D / 2 + 0.15, z1 = D / 2 - 0.15;
  hall(k, W - 0.8, D - 1.0, base * 0.9);
  // landside high, sweeping down to the gates; both ends tapering, as the 1.7 km wing does
  const profile = (v: number) => (v < 0.7 ? Math.sin((v / 0.7) * Math.PI / 2) : Math.cos(((v - 0.7) / 0.3) * Math.PI / 2) * 0.6 + 0.4);
  const taper = (u: number) => 0.45 + 0.55 * Math.sin(u * Math.PI);
  const y = (u: number, v: number) => base + lift * profile(1 - v) * taper(u) * (1 - 0.35 * (1 - v));
  sheet(k, -W / 2 + 0.1, W / 2 - 0.1, z0, z1, 10, 5, y, (i) => (i % 2 ? STEEL : STEEL_DARK), hex(0xa9b3bb));
  // the landside glass wall rising to meet the roof's leading edge
  k.glowBox(0, 0.12, z1 - 0.35, W - 1.4, base + lift * 0.3, 0.06, GLASS_PALE, GLOW_HOURS, COOL_GLOW);
  // the gates' edge: a long glazed pier under the trailing edge
  k.glowBox(0, 0.12, z0 + 0.35, W - 0.8, base * 0.75, 0.3, GLASS_DARK, GLOW_HOURS, COOL_GLOW);
  jetways(k, W, D, base * 0.45, b.floors > 1 ? 3 : 1, hex(0xcfd3d6));
  padDeck(k, b, W, D);
};

/** The rainbow of Barajas T4's trees, end to end of the building. */
const T4 = [0x2f6fb5, 0x2f9fb0, 0x3f9b4a, 0x9cc23a, 0xf2c14e, 0xf28c38, 0xe2412f, 0xb8326a].map(hex);
/** Madrid-Barajas T4: the wave roof on its rainbow trees. */
const barajas: Draw = (k, W, D, b) => {
  const h = 0.95 + b.floors * 0.25;
  hall(k, W - 1.0, D - 1.3, h - 0.35);
  // the roof: waves rolling across it front to back, bamboo underneath, pale on top, overhanging the kerb
  const y = (_u: number, v: number) => h + 0.16 * Math.sin(v * Math.PI * 3);
  sheet(k, -W / 2 + 0.15, W / 2 - 0.15, -D / 2 + 0.2, D / 2 - 0.1, 8, 6, y, () => hex(0xe9e6df), hex(0xd9b27a));
  // the trees: a trunk splitting in a Y up into the roof, a row along each long side, coloured by where they stand
  const n = Math.max(5, Math.round(W / 1.4));
  for (let i = 0; i < n; i++) {
    const u = i / (n - 1), x = -W / 2 + 0.6 + (W - 1.2) * u;
    const col = T4[Math.min(T4.length - 1, Math.floor(u * T4.length))];
    for (const z of [D / 2 - 0.45, -D / 2 + 0.55]) {
      const fork = h * 0.55, roofAt = (zz: number) => y(0, (zz + D / 2 - 0.2) / (D - 0.3)) - 0.09;
      k.cyl(x, 0, z, 0.07, fork, col, 6);
      k.bar([x, fork, z], [x - 0.35, roofAt(z), z + 0.25], 0.045, col);
      k.bar([x, fork, z], [x + 0.35, roofAt(z), z - 0.25], 0.045, col);
    }
  }
  jetways(k, W, D, 0.55, b.floors > 1 ? 3 : 1, scale(hex(0xd3cec3), 1));
  padDeck(k, b, W, D);
};

export const TERMINAL_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = { terminal: [twa, dulles, denver, kansai, barajas] };
