/**
 * The cargo and culture boards (docs/social.html, phase 4, at the user's ask): who has delivered the most of each
 * cargo kind, and who has brought home the most of each culture. Two World-tab bodies over one online extra: every
 * kind at a glance (its icon and name, its leader and their count, how many fleets have any, your count and place),
 * and a kind opened up in full (its top twenty, under the World tab's scope: everyone, friends or neighbours). The
 * game's own tallies (game/metrics.ts) go up with every save; the server adds up shared fleets (server/goodsBoards.ts).
 */
import { esc } from '../game/cargoHud';
import { chip, css } from '../game/firmSpec';
import { CARGO } from '../game/cargoTypes';
import { styleLabel, VISITOR, type CultureStyle } from '../game/culture';
import { GOODS } from '../game/cultureGoods';
import { ALL_VEHICLES } from '../game/vehicles';
import type { OnlineExtra } from './online';
import type { BoardBody } from './worldTab';
import { inScope, scopeMode } from './boardScope';
import type { CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import type { GoodsBoardKind, GoodsRow, GoodsSummary } from '../../shared/social';

/** Seconds between asks for the same thing. */
const ASK_S = 8;

export interface GoodsHost { online(): boolean; me(): string | null; post(m: ClientMsg): void }

interface Side { summary: GoodsSummary[] | null; askedSum: number; pick: string | null; board: { kind: string; rows: GoodsRow[]; you: { n: number; place: number } | null; fleets: number } | null; askedBoard: number }

/** A kind's icon and name: a cargo kind's own, or a culture's (its first good's icon, the style's name). */
const KIND_ICON = { land: '🚗', water: '⛵', air: '🚁', rail: '🚂' } as const;
function label(k: GoodsBoardKind, kind: string): { icon: string; name: string } {
  if (k === 'g') { const t = CARGO.find((c) => c.name === kind); return { icon: t?.icon ?? '📦', name: kind }; }
  if (k === 'v' || k === 'e') { const d = ALL_VEHICLES.find((q) => q.id === kind); return { icon: d ? KIND_ICON[d.kind] : '🚗', name: d?.name ?? kind }; }
  const style = kind as CultureStyle;
  const icon = style === VISITOR ? '☄️' : (GOODS as Record<string, [string, string][]>)[style]?.[0]?.[1] ?? '🎁';
  return { icon, name: styleLabel(style) };
}

/** Each board's words: its count's verb and unit, the empty line, what a board is of, and the foot. */
const WORDS: Record<GoodsBoardKind, { verb: string; unit: string; none: string; every: string; many: string; col: string; foot: string }> = {
  g: { verb: 'delivered', unit: 'loads', none: 'No deliveries counted yet: every load delivered from here on counts, yours and your drivers’.', every: 'cargo', many: 'cargo kinds', col: 'Cargo', foot: 'Every load delivered by you and your drivers counts, by its cargo kind. A shared fleet is one line, its players added up.' },
  c: { verb: 'brought home', unit: 'units', none: 'No culture brought home yet: cultural goods carried to your HQ count here, by the style they come from.', every: 'culture', many: 'cultures', col: 'Culture', foot: 'Units of cultural goods brought home to your HQ, by the style they come from. A shared fleet is one line.' },
  v: { verb: 'delivered in it', unit: 'loads', none: 'No loads counted by vehicle yet: every load delivered from here on counts, in the vehicle it went in.', every: 'vehicle', many: 'vehicles', col: 'Vehicle', foot: 'Every load delivered by you and your drivers counts, in the vehicle it went in. A shared fleet is one line, its players added up.' },
  e: { verb: 'earned in it', unit: 'dollars', none: 'No earnings counted by vehicle yet: what every load pays from here on counts, in the vehicle it went in.', every: 'vehicle', many: 'vehicles', col: 'Vehicle', foot: 'What every load paid you, yours at the wheel and your drivers’ cut to you, in the vehicle it went in. A shared fleet is one line.' },
};
/** A board's count as shown: dollars with a sign, the rest as they are. */
const count = (k: GoodsBoardKind, n: number): string => (k === 'e' ? `$${n.toLocaleString('en-US')}` : n.toLocaleString('en-US'));

export class GoodsTab implements OnlineExtra {
  private sides: Record<GoodsBoardKind, Side> = { g: this.blank(), c: this.blank(), v: this.blank(), e: this.blank() };
  onData: () => void = () => {};

  constructor(private host: GoodsHost) {}

  private blank(): Side { return { summary: null, askedSum: -1e9, pick: null, board: null, askedBoard: -1e9 }; }

  // ---- the online session ----
  welcome(_w: Welcome): void { this.reset(); }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t === 'goodsBoards') { this.sides[m.k].summary = m.rows; this.onData(); return true; }
    if (m.t === 'goodsBoard') { this.sides[m.k].board = { kind: m.kind, rows: m.rows, you: m.you, fleets: m.fleets }; this.onData(); return true; }
    return false;
  }
  ready(): void { /* asked for when shown */ }
  frame(): void { /* nothing per frame */ }
  forget(): void { /* nothing per cell */ }
  reset(): void { this.sides = { g: this.blank(), c: this.blank(), v: this.blank(), e: this.blank() }; }

  private ask(k: GoodsBoardKind, force = false): void {
    const s = this.sides[k], now = performance.now();
    if (!this.host.online()) return;
    if (s.pick) {
      if (force || now - s.askedBoard > ASK_S * 1000) { s.askedBoard = now; this.host.post({ t: 'goodsBoard', k, kind: s.pick }); }
    } else if (force || now - s.askedSum > ASK_S * 1000) { s.askedSum = now; this.host.post({ t: 'goodsBoards', k }); }
  }

  private body(k: GoodsBoardKind): BoardBody {
    return {
      opened: () => this.ask(k, true),
      tick: () => this.ask(k),
      press: (t: HTMLElement) => {
        const b = t.closest('[data-gkind]') as HTMLElement | null;
        if (!b) return false;
        const s = this.sides[k];
        s.pick = b.dataset.gkind || null;
        s.board = null;
        this.ask(k, true);
        return true;
      },
      html: () => this.html(k),
    };
  }

  /** The two World-tab bodies. */
  readonly cargo: BoardBody = this.body('g');
  readonly culture: BoardBody = this.body('c');
  /** The vehicle boards (the user, 5 Nov 2026): loads delivered, and dollars earned, in each model. */
  readonly vehicles: BoardBody = this.body('v');
  readonly earnings: BoardBody = this.body('e');

  private html(k: GoodsBoardKind): string {
    if (!this.host.online()) return '<p class="none">The cargo and culture boards are online: every fleet’s deliveries, side by side.</p>';
    const s = this.sides[k];
    const what = WORDS[k];
    if (s.pick) {
      const b = s.board;
      const l = label(k, s.pick);
      if (!b || b.kind !== s.pick) return `<p><button type="button" class="link" data-gkind="">← every ${what.every}</button></p><p class="none">Asking the server…</p>`;
      const me = this.host.me();
      const scoped = scopeMode() !== 'everyone';
      const rows = b.rows.filter((r) => (!!me && r.ids.includes(me)) || r.ids.some((id) => inScope(id)));
      const top = Math.max(1, ...rows.map((r) => r.n));
      const list = rows.map((r, i) => {
        const you = !!me && r.ids.includes(me);
        const place = b.rows.indexOf(r) + 1;
        return `<li class="${you ? 'you' : ''}"><span class="nm"><i>${scoped ? i + 1 : place}</i>${chip([r.brand?.primary ?? 0x7d8a92, r.brand?.accent ?? 0xffffff], r.brand?.logo || undefined)}<b${you ? '' : ` data-pid="${esc(r.id)}"`}>${esc(r.name)}</b>${you ? ' <small>you</small>' : ''}${scoped ? `<span class="sub">#${place} overall</span>` : ''}</span>`
          + `<em>${count(k, r.n)}</em><span class="bar"><i style="width:${Math.max(1.5, (r.n / top) * 100).toFixed(1)}%;background:${css(r.brand?.primary ?? 0x7d8a92)}"></i></span></li>`;
      }).join('');
      const you = b.you ? `Yours: <b>${count(k, b.you.n)}</b>${k === 'e' ? '' : ` ${what.unit}`} · <b>#${b.you.place} of ${b.fleets}</b>` : `Nothing of yours yet · ${b.fleets} fleet${b.fleets === 1 ? '' : 's'} on this board`;
      return `<p><button type="button" class="link" data-gkind="">← every ${what.every}</button></p><h3 class="gk-h">${l.icon} ${esc(l.name)} <small>${what.unit} ${what.verb}</small></h3>
        <div class="lead">${you}</div><ul class="ranking">${list || `<li><span class="nm">${scoped ? 'Nobody in this scope on the top twenty.' : 'Nobody yet.'}</span></li>`}</ul>`;
    }
    const sum = s.summary;
    if (!sum) return '<p class="none">Asking the server…</p>';
    if (!sum.length) return `<p class="none">${what.none}</p>`;
    const me = this.host.me();
    const leads = sum.filter((r) => !!me && !!r.top?.ids.includes(me)).length;
    const rows = sum.map((r) => {
      const l = label(k, r.kind);
      const t = r.top;
      const mine = !!me && !!t?.ids.includes(me);
      return `<li class="gk-row${mine ? ' you' : ''}"><button type="button" class="pick" data-gkind="${esc(r.kind)}"><span class="ti">${l.icon}</span><span class="what"><b>${esc(l.name)}</b><small>${r.fleets} fleet${r.fleets === 1 ? '' : 's'}</small></span>`
        + `<span class="lead-by">${t ? `${chip([t.brand?.primary ?? 0x7d8a92, t.brand?.accent ?? 0xffffff], t.brand?.logo || undefined)}<b>${esc(mine ? 'You' : t.name)}</b> <small>${count(k, t.n)}</small>` : ''}</span>`
        + `<span class="yours">${r.you ? `<b>${count(k, r.you)}</b> <small>#${r.place}</small>` : '<small class="mute">—</small>'}</span></button></li>`;
    }).join('');
    return `<div class="lead">${sum.length} ${what.many} · you lead <b>${leads}</b> · open one for its top twenty</div>
      <div class="gk-head"><span></span><span>${what.col}</span><span>Leader</span><span>Yours</span></div><ul class="fleets goods">${rows}</ul>
      <p class="foot">${what.foot} Counted from each game’s saves.</p>`;
  }
}
