/** The mayor of a town: always the same person, whoever asks. */
export function mayorOf(town: string): { name: string; short: string } {
  const h = hashString(`mayor|${town}`);
  const given = GIVEN[h % GIVEN.length], family = SURNAME[(h >>> 9) % SURNAME.length];
  return { name: `${given} ${family}`, short: `${given[0]}. ${family}` };
}

/** The inks a town's seal is struck in: civic colours, one per town for good. */
const INKS = ['#2b4a7a', '#7a2b2b', '#2f5f3a', '#5a3570', '#7a4a1f', '#1f5c66'];
let sealNo = 0;

/**
 * A town's official seal, as a small SVG: a double ring with OFFICE OF THE MAYOR run round it and the
 * town's initials struck in the middle, always in the same ink for the same town.
 */
function townSeal(town: string): SVGSVGElement {
  const h = hashString(`seal|${town}`);
  const ink = INKS[h % INKS.length];
  const initials = town.split(/[\s-]+/).filter((w) => /^[A-Za-z]/.test(w) && !/^(of|the|on|by|upon|and|de|la|le|du|del)$/i.test(w)).map((w) => w[0].toUpperCase()).slice(0, 3).join('');
  const id = `seal-arc-${sealNo++}`;
  const el = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  el.setAttribute('viewBox', '0 0 64 64');
  el.setAttribute('class', 'seal');
  el.setAttribute('aria-hidden', 'true');
  el.style.color = ink;
  el.innerHTML = `<defs><path id="${id}" d="M32,32 m-21.5,0 a21.5,21.5 0 1,1 43,0 a21.5,21.5 0 1,1 -43,0"/></defs>`
    + `<circle cx="32" cy="32" r="30.5" fill="none" stroke="currentColor" stroke-width="2.2"/>`
    + `<circle cx="32" cy="32" r="27.5" fill="none" stroke="currentColor" stroke-width=".8" stroke-dasharray="1.4 1.6"/>`
    + `<circle cx="32" cy="32" r="15.5" fill="none" stroke="currentColor" stroke-width=".9"/>`
    + `<text font-family="IBM Plex Mono, monospace" font-size="5.6" font-weight="700" letter-spacing=".55" fill="currentColor"><textPath href="#${id}" startOffset="50%" text-anchor="middle">★ OFFICE OF THE MAYOR ★</textPath></text>`
    + `<text x="32" y="${initials.length > 2 ? 36 : 37}" font-family="Georgia, serif" font-size="${initials.length > 2 ? 11 : initials.length > 1 ? 14 : 17}" font-weight="700" text-anchor="middle" fill="currentColor">${initials.replace(/&/g, '&amp;').replace(/</g, '&lt;')}</text>`;
  return el;
}

/** The letterhead every notice goes out on: the seal beside the town's name, the office under it. */
function letterhead(town: string): HTMLElement {
  const head = document.createElement('header');
  head.className = 'town';
  const seal = townSeal(town);
  const name = document.createElement('div');
  name.className = 'name';
  const of = document.createElement('small');
  of.textContent = 'Town of';
  const big = document.createElement('b');
  big.textContent = town;
  const office = document.createElement('small');
  office.textContent = 'Office of the Mayor';
  name.append(of, big, office);
  head.append(seal, name);
  return head;
}

/** Anyone else with a name from the same book, salted so a driver never shares a mayor's hash. */
export function personName(salt: string): string {
  const h = hashString(`person|${salt}`);
  return `${GIVEN[h % GIVEN.length]} ${SURNAME[(h >>> 9) % SURNAME.length]}`;
}

/**
 * Is this given name (or full name: its first word) a woman's, by the book's alternation (hers are the even entries)?
 * Null for a name not in the book (a player's own, say).
 */
export function isWomanName(name: string): boolean | null {
  const k = GIVEN.indexOf(name.trim().split(/\s+/)[0] ?? '');
  return k < 0 ? null : k % 2 === 0;
}

/** A woman's name from the same book (its given names alternate: hers are the even entries), salted the same way. */
export function womanName(salt: string): string {
  const h = hashString(`person|${salt}`);
  const given = GIVEN.filter((_, k) => k % 2 === 0);
  return `${given[h % given.length]} ${SURNAME[(h >>> 9) % SURNAME.length]}`;
}

/** One letter waiting to be read. `by` names the company driver whose delivery tipped the town over. */
export interface Levy { town: string; rate: number; earned: number; by?: string }
/** A plain letter from the mayor: news about something of the player's in the town (docs/property.html). */
export interface Note { town: string; note: string[]; tag: string }

/**
 * The other kind of letter: a town asking for something (game/requests.ts). It is the only
 * interruption a request ever makes; everything else about it waits on the board.
 */
export interface Ask {
  town: string;
  title: string;
  line: string;
  /** One line per step, in the order they are to be done. */
  steps: string[];
  reward: number;
  effectLine: string;
  /** Why the vehicle being driven cannot do it, if it cannot: the card then only offers the board. */
  whyNot: string | null;
  accept(): void;
}

/** The letter, colder as the rate climbs. */
function letter(l: Levy): string[] {
  const t = l.town, r = `${l.rate}%`, e = money(l.earned);
  const by = l.by ? `Your driver ${l.by} has been busy on our streets, and it counts as yours.` : '';
  const lines = letterFor(l, t, r, e);
  return by ? [by, ...lines] : lines;
}

function letterFor(l: Levy, t: string, r: string, e: string): string[] {
  if (l.rate <= 4) {
    return [
      `You've done well out of us lately: ${e} in the last few days, by the town clerk's count.`,
      `Council has voted a haulage levy of ${r} on deliveries into ${t}, effective immediately.`,
      'Thank you for your custom.',
    ];
  }
  if (l.rate <= 16) {
    return [
      `The clerk puts your takings here at ${e}. The council has taken note.`,
      `The haulage levy on deliveries into ${t} now stands at ${r}.`,
    ];
  }
  if (l.rate < 40) return [`${e}, by our count. The levy into ${t} is now ${r}.`];
  return [`${t} levy: ${r}. That is final.`];
}

export class MayorCard {
  isOpen = false;
  private el = document.getElementById('mayor')!;
  private queue: (Levy | Ask | Note)[] = [];

  constructor() {
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    window.addEventListener('keydown', (e) => {
      if (!this.isOpen) return;
      if (e.code === 'Escape' || e.code === 'Enter' || e.code === 'Space') { this.close(); e.preventDefault(); }
    });
  }

  /** A town has raised its rate: the letter goes on the mat, and opens now unless one is being read. */
  post(l: Levy): void {
    this.queue.push(l);
    if (!this.isOpen) this.next();
  }

  /** News for the player, on the same letterhead. */
  note(n: Note): void {
    this.queue.push(n);
    if (!this.isOpen) this.next();
  }

  /** A town is asking for something: the same letterhead, with Take it on and Not now. */
  ask(a: Ask): void {
    this.queue.push(a);
    if (!this.isOpen) this.next();
  }

  private next(): void {
    const l = this.queue.shift();
    if (!l) return;
    if ('title' in l) { this.askCard(l); return; }
    const note = 'note' in l ? l : null;
    const m = mayorOf(l.town);
    const panel = document.createElement('div');
    panel.className = 'panel';
    const head = letterhead(l.town);
    const who = document.createElement('p');
    who.className = 'who';
    who.textContent = `Mayor ${m.name}`;
    const body = document.createElement('div');
    body.className = 'letter';
    for (const line of note ? note.note : letter(l as Levy)) {
      const p = document.createElement('p');
      p.textContent = line;
      body.append(p);
    }
    const sign = document.createElement('p');
    sign.className = 'sign';
    sign.textContent = `— ${m.name}`;
    body.append(sign);
    const rate = document.createElement('div');
    rate.className = 'rate';
    rate.textContent = note ? note.tag : `Levy ${(l as Levy).rate}%`;
    const ok = document.createElement('button');
    ok.type = 'button';
    ok.textContent = 'Understood';
    ok.addEventListener('click', () => this.close());
    panel.append(head, rate, who, body, ok);
    this.el.replaceChildren(panel);
    this.el.hidden = false;
    this.isOpen = true;
  }

  /** The ask, on the mayor's own letterhead: what they want, what it pays, and what it does to the town. */
  private askCard(a: Ask): void {
    const m = mayorOf(a.town);
    const panel = document.createElement('div');
    panel.className = 'panel ask';
    const head = letterhead(a.town);
    const who = document.createElement('p');
    who.className = 'who';
    who.textContent = `Mayor ${m.name} writes`;
    const title = document.createElement('h3');
    title.className = 'ask-title';
    title.textContent = a.title;
    const body = document.createElement('div');
    body.className = 'letter';
    const said = document.createElement('p');
    said.textContent = `\u201c${a.line}\u201d`;
    body.append(said);
    const list = document.createElement('ol');
    list.className = 'steps';
    for (const s of a.steps) {
      const li = document.createElement('li');
      li.textContent = s;
      list.append(li);
    }
    body.append(list);
    const terms = document.createElement('p');
    terms.className = 'terms';
    terms.textContent = `${money(a.reward)} on the last drop, on top of what each load pays. When it is done: ${a.effectLine}.`;
    body.append(terms);
    if (a.whyNot) {
      const no = document.createElement('p');
      no.className = 'whynot';
      no.textContent = `Not in what you are driving: ${a.whyNot}.`;
      body.append(no);
    }
    const sign = document.createElement('p');
    sign.className = 'sign';
    sign.textContent = `\u2014 ${m.name}`;
    body.append(sign);
    const acts = document.createElement('div');
    acts.className = 'acts';
    const yes = document.createElement('button');
    yes.type = 'button';
    yes.textContent = a.whyNot ? 'Open the board' : 'Take it on';
    yes.addEventListener('click', () => { this.close(); a.accept(); });
    const later = document.createElement('button');
    later.type = 'button';
    later.className = 'later';
    later.textContent = 'Not now';
    later.addEventListener('click', () => this.close());
    acts.append(yes, later);
    panel.append(head, who, title, body, acts);
    this.el.replaceChildren(panel);
    this.el.hidden = false;
    this.isOpen = true;
  }

  close(): void {
    this.isOpen = false;
    this.el.hidden = true;
    (document.activeElement as HTMLElement | null)?.blur?.();
    // anything else that arrived while this was open comes up next
    if (this.queue.length) setTimeout(() => this.next(), 250);
  }
}
