import * as THREE from 'three';

/**
 * A blimp between the camera and what it follows goes see-through, as buildings (xray.ts) and scenery already
 * do. A blimp is drawn four times the size of a car and hangs at a building's height, so it covers the car far
 * more often than anything else that moves. Vehicles share their materials, so a fading blimp is given its own
 * copies while it fades and the shared ones back once it is clear: no other vehicle changes.
 */

/** How much of a blimp is left while it covers the car. */
const FADED = 0.28;
/** How quickly it fades and comes back, per second (an exponential ease). */
const SPEED = 5;
/** Its bounds are grown by this much, in world units, so it fades a moment before it covers the car. */
const PAD = 0.4;

interface Faded { alpha: number; swaps: { mesh: THREE.Mesh; was: THREE.Material | THREE.Material[] }[]; copies: { m: THREE.Material; opacity: number }[] }

export class BlimpFade {
  private faded = new Map<THREE.Object3D, Faded>();
  private box = new THREE.Box3();
  private ray = new THREE.Ray();
  private dir = new THREE.Vector3();
  private at = new THREE.Vector3();

  /**
   * Once a frame. `eye` is the camera, `target` what it follows (null: nothing to keep in view), `blimps` the
   * blimps in the scene this frame.
   */
  update(dt: number, eye: THREE.Vector3, target: THREE.Vector3 | null, blimps: Iterable<THREE.Object3D>, followed: THREE.Object3D | null = null): void {
    const here = new Set<THREE.Object3D>();
    const k = 1 - Math.exp(-Math.max(0, dt) * SPEED);
    for (const o of blimps) {
      here.add(o);
      let covers = false;
      if (target && o !== followed) {
        this.box.setFromObject(o).expandByScalar(PAD);
        // a blimp the camera is following is not in its own way
        if (!this.box.containsPoint(target)) {
          const len = eye.distanceTo(target);
          this.ray.set(eye, this.dir.subVectors(target, eye).normalize());
          covers = !!this.ray.intersectBox(this.box, this.at) && eye.distanceTo(this.at) < len;
        }
      }
      let f = this.faded.get(o);
      if (!f) {
        if (!covers) continue;
        f = this.begin(o);
      }
      f.alpha += ((covers ? FADED : 1) - f.alpha) * k;
      if (!covers && f.alpha > 0.98) { this.end(o, f); continue; }
      for (const c of f.copies) c.m.opacity = c.opacity * f.alpha;
    }
    for (const [o, f] of this.faded) if (!here.has(o)) this.end(o, f);
  }

  /** Everything back as it was: a new world, or the game leaving play. */
  clear(): void {
    for (const [o, f] of this.faded) this.end(o, f);
  }

  private begin(o: THREE.Object3D): Faded {
    const f: Faded = { alpha: 1, swaps: [], copies: [] };
    const mine = new Map<THREE.Material, THREE.Material>();
    const copy = (m: THREE.Material): THREE.Material => {
      let c = mine.get(m);
      if (!c) {
        c = m.clone();
        c.transparent = true;
        c.depthWrite = false;
        mine.set(m, c);
        f.copies.push({ m: c, opacity: m.opacity });
      }
      return c;
    };
    o.traverse((x) => {
      const mesh = x as THREE.Mesh;
      if (!mesh.isMesh || !mesh.material) return;
      f.swaps.push({ mesh, was: mesh.material });
      mesh.material = Array.isArray(mesh.material) ? mesh.material.map(copy) : copy(mesh.material);
    });
    this.faded.set(o, f);
    return f;
  }

  private end(o: THREE.Object3D, f: Faded): void {
    for (const s of f.swaps) s.mesh.material = s.was;
    for (const c of f.copies) c.m.dispose();
    this.faded.delete(o);
  }
}
