import { hex, scale, type RGB } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, GLASS_LIGHT, NEON_HOURS, TAU, WHITE, bladeSign, neonColour, row, type Draw, type Kit } from './kit';

/**
 * Tokyo's own buildings, the Shibuya and Shinjuku ones, swapped in by the `tokyo` style (STYLE_SWAPS in
 * world/towns.ts). Each stands on its lot centred on the origin, its front to +z:
 *
 * - **Shibuya 109** (for a department store): the silver cylinder on the corner of its block, ribbed with
 *   glass, under a drum that carries "109" in red, lit white after dark.
 * - **The scramble crossing** (for a fountain square): zebra stripes on every side and both diagonals,
 *   Hachiko on his plinth, and the big video screens looking down on it from their masts.
 * - **The Metropolitan Government Building** (for a city hall): a granite-grey block that splits into two
 *   towers, each turned a little at the top, over a wing and a colonnaded plaza.
 * - **The Cocoon Tower** (for a skyscraper): a tapering elliptical glass tower in a white lattice web.
 * - **The Godzilla tower** (for a cinema): the cinema's podium with Godzilla's head looking over its
 *   terrace, eyes lit at night, and a hotel tower rising behind.
 * - **The yokocho** (for a terrace row): a lane of tiny two-storey bars under tin roofs, paper lanterns
 *   strung along the front, noren over the doors and a lit sign on every one.
 * - **Kabukicho's gate** (for a memorial or plaza steps): a red steel arch over the street with its sign
 *   lit in a thousand bulbs.
 */

const SILVER = hex(0xc8ccd0), SILVER_DARK = hex(0x9aa0a6), GRANITE = hex(0xb0aca4), GRANITE_DARK = hex(0x8a8680);
const ASPHALT = hex(0x4a4c50), STRIPE = hex(0xf2f2ee), BRONZE = hex(0x6a5236), PLINTH = hex(0x9a968e);
const COCOON_GLASS = hex(0x3e5a74), LATTICE = hex(0xeef2f4), GODZILLA = hex(0x3e4640), GODZILLA_DARK = hex(0x2a302c);
const TEETH = hex(0xf0ece0), BAR_WOOD = hex(0x4a3428), TIN = hex(0x7a7e80), LANTERN = hex(0xe8402a), GATE_RED = hex(0xc8282a);
const SCREEN_OFF = hex(0x1e2226), TOHO = hex(0xd8d2c6), HOTEL = hex(0xc4c8cc);
/** Screens and eyes are lit through the day as well; the gate's bulbs and the lanterns from dusk. */
const SCREEN_HOURS: Sched = [7, 30.5, 1.3], ALL_NIGHT: Sched = [0, 36, 1.6];

/**
 * A digit in seven segments on a plate facing +z, its middle at (x, y0 + h/2, z): the only lettering the
 * kit can draw, and enough for 109.
 */
function digit(k: Kit, ch: string, x: number, y0: number, z: number, h: number, col: RGB, s: Sched, g: RGB): void {
  const SEGS: Record<string, string> = { '0': 'abcdef', '1': 'bc', '9': 'abcdfg' };
  const on = SEGS[ch] ?? '';
  const w = h * 0.55, t = h * 0.14, half = h / 2;
  const seg = (sx: number, sy: number, sw: number, sh: number) => k.glowBox(x + sx, y0 + sy, z, sw, sh, 0.02, col, s, g);
  if (on.includes('a')) seg(0, h - t, w, t);
  if (on.includes('g')) seg(0, half - t / 2, w, t);
  if (on.includes('d')) seg(0, 0, w, t);
  if (on.includes('f')) seg(-w / 2 + t / 2, half, t, half);
  if (on.includes('b')) seg(w / 2 - t / 2, half, t, half);
  if (on.includes('e')) seg(-w / 2 + t / 2, 0, t, half);
  if (on.includes('c')) seg(w / 2 - t / 2, 0, t, half);
}

/** A video screen facing +z: a dark frame and a mosaic of lit colours, so it reads as a picture. */
function screen(k: Kit, r: Rng, x: number, y: number, z: number, w: number, h: number): void {
  k.box(x, y - 0.03, z - 0.02, w + 0.06, h + 0.06, 0.03, SCREEN_OFF);
  const nx = 4, ny = 3;
  for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) {
    const c = neonColour(r);
    k.glowBox(x - w / 2 + (w / nx) * (i + 0.5), y + (h / ny) * j, z, w / nx, h / ny, 0.012, scale(c, 0.6), SCREEN_HOURS, c);
  }
}

/** Rows of windows up all four faces of a block, every storey, in the kit's own panes. */
function glazed(k: Kit, b: Parameters<Draw>[3], r: Rng, x: number, y: number, z: number, w: number, d: number, floors: number, glass: RGB, every = 1): void {
  const nx = Math.max(1, Math.round(w / 0.24)), nz = Math.max(1, Math.round(d / 0.24));
  for (let f = 0; f < floors; f += every) {
    const fy = y + f * FLOOR + 0.07;
    row(k, b, r, x, fy, z + d / 2, w - 0.04, 0.12, nx, 1, glass);
    row(k, b, r, x, fy, z - d / 2, w - 0.04, 0.12, nx, 3, glass);
    row(k, b, r, x + w / 2, fy, z, d - 0.04, 0.12, nz, 0, glass);
    row(k, b, r, x - w / 2, fy, z, d - 0.04, 0.12, nz, 2, glass);
  }
}

// ---- Shibuya 109 ----

const shibuyaTower: Draw = (k, W, D, b, r) => {
  const floors = Math.max(8, b.floors + 3), H = floors * FLOOR;
  // the block behind, stepping down from the cylinder
  const bw = W - 0.2, bd = D - 0.2;
  k.box(-0.15, 0, -0.15, bw - 0.3, H * 0.6, bd - 0.3, SILVER_DARK, SILVER);
  glazed(k, b, r, -0.15, 0, -0.15, bw - 0.3, bd - 0.3, Math.floor(floors * 0.6), GLASS_LIGHT, 2);
  // the cylinder on the corner, ribbed floor by floor with a band of glass
  const cx = W / 2 - 0.62, cz = D / 2 - 0.62, R = 0.56;
  for (let f = 0; f < floors; f++) {
    k.cyl(cx, f * FLOOR, cz, R, FLOOR * 0.62, SILVER, 16);
    k.cyl(cx, f * FLOOR + FLOOR * 0.62, cz, R * 0.97, FLOOR * 0.38, scale(GLASS_LIGHT, 0.8), 16);
  }
  // the drum on top, white and lit, carrying 109 in red to the street
  k.glowBox(cx, H, cz, R * 1.7, 0.5, R * 1.7, WHITE, ALL_NIGHT, hex(0xfafaff));
  k.cyl(cx, H + 0.5, cz, R * 0.95, 0.06, SILVER, 16);
  const red = hex(0xd8202a);
  const dz = cz + R * 0.86 + 0.02, dh = 0.34;
  ['1', '0', '9'].forEach((ch, i) => digit(k, ch, cx + (i - 1) * 0.26, H + 0.08, dz, dh, red, ALL_NIGHT, hex(0xff3040)));
  // shop signs down the street fronts
  bladeSign(k, r, -W / 2 + 0.18, FLOOR, H * 0.7, bd / 2 - 0.15);
  k.glowBox(-0.15, FLOOR * 0.74, (bd - 0.3) / 2 - 0.13, bw - 0.4, 0.07, 0.03, scale(hex(0xff2e7a), 0.8), NEON_HOURS, hex(0xff2e7a));
};

// ---- the scramble crossing ----

const scrambleCrossing: Draw = (k, W, D, _b, r) => {
  // the junction itself, laid a hair over the plaza
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, ASPHALT);
  const bars = (len: number, lay: (o: number) => void) => { for (let o = -len / 2 + 0.06; o < len / 2 - 0.04; o += 0.14) lay(o); };
  // a zebra across each side
  const edge = W / 2 - 0.35;
  bars(W - 0.9, (o) => { k.box(o, 0.02, edge, 0.08, 0.004, 0.42, STRIPE); k.box(o, 0.02, -edge, 0.08, 0.004, 0.42, STRIPE); });
  bars(D - 0.9, (o) => { k.box(edge, 0.02, o, 0.42, 0.004, 0.08, STRIPE); k.box(-edge, 0.02, o, 0.42, 0.004, 0.08, STRIPE); });
  // and the two diagonals that make it a scramble
  for (const yaw of [Math.PI / 4, -Math.PI / 4]) {
    k.turned(yaw, () => bars(Math.hypot(W, D) * 0.62, (o) => k.box(o, 0.021, 0, 0.08, 0.004, 0.42, STRIPE)));
  }
  // Hachiko on his plinth at the corner, looking along the crossing
  const hx = -W / 2 + 0.25, hz = D / 2 - 0.25;
  k.box(hx, 0, hz, 0.24, 0.16, 0.18, PLINTH);
  k.box(hx, 0.16, hz, 0.16, 0.06, 0.07, BRONZE);            // body
  k.box(hx + 0.06, 0.16, hz, 0.03, 0.08, 0.05, BRONZE);     // front legs, sitting
  k.box(hx + 0.08, 0.21, hz, 0.05, 0.08, 0.05, BRONZE);     // chest and neck
  k.box(hx + 0.11, 0.28, hz, 0.06, 0.05, 0.045, BRONZE);    // head
  for (const s of [-1, 1]) k.box(hx + 0.1, 0.33, hz + s * 0.014, 0.012, 0.025, 0.012, BRONZE);
  // the screens, high on masts at the back corners, looking out over the crossing
  for (const s of [-1, 1]) {
    const mx = s * (W / 2 - 0.12), mz = -D / 2 + 0.12;
    k.box(mx, 0, mz, 0.06, 2.1, 0.06, DARK);
    screen(k, r, mx - s * 0.3, 1.4, mz + 0.05, 0.9, 0.55);
  }
  // and a lamp on the corner Hachiko doesn't keep
  const lx = W / 2 - 0.12, lz = D / 2 - 0.12;
  k.box(lx, 0, lz, 0.03, 0.6, 0.03, DARK);
  k.glowBox(lx, 0.6, lz, 0.08, 0.05, 0.08, WHITE, NEON_HOURS, hex(0xfff6e0));
};

// ---- the Metropolitan Government Building ----

const metroGovTower: Draw = (k, W, D, b, r) => {
  // the plaza's colonnade across the front, and the low wing behind it
  for (let x = -W / 2 + 0.2; x <= W / 2 - 0.2; x += 0.3) k.box(x, 0, D / 2 - 0.2, 0.06, 0.5, 0.06, GRANITE);
  k.box(0, 0.5, D / 2 - 0.2, W - 0.3, 0.06, 0.14, GRANITE_DARK);
  const wx = -W / 2 + 0.85;
  k.box(wx, 0, -0.2, 1.4, 1.4, D - 1.0, GRANITE, GRANITE_DARK);
  glazed(k, b, r, wx, 0, -0.2, 1.4, D - 1.0, 5, hex(0x6a7a86));
  // the main block: its lower half one slab, its upper half split into the two towers
  const tx = 0.45, tw = Math.min(W - 1.6, 2.2), td = Math.min(D - 0.9, 1.3);
  const lower = 28, upper = 20;
  k.box(tx, 0, -0.15, tw, lower * FLOOR, td, GRANITE, GRANITE_DARK);
  glazed(k, b, r, tx, 0, -0.15, tw, td, lower, hex(0x6a7a86), 2);
  // the split between the towers, recessed, from the lower roof up
  const y0 = lower * FLOOR, half = tw * 0.36;
  for (const s of [-1, 1]) {
    const x = tx + s * (tw / 2 - half / 2);
    k.box(x, y0, -0.15, half, upper * FLOOR, td * 0.9, GRANITE, GRANITE_DARK);
    glazed(k, b, r, x, y0, -0.15, half, td * 0.9, upper, hex(0x6a7a86), 2);
    // the crown: each tower's top turned a little, a lantern of darker glass under a flat cap
    const top = y0 + upper * FLOOR;
    // (turned a quarter about the building's middle, so the crown's own middle is counter-turned into place)
    const lx = (x + 0.15) * Math.SQRT1_2, lz = (x - 0.15) * Math.SQRT1_2;
    k.turned(Math.PI / 4, () => {
      k.box(lx, top, lz, half * 0.72, 0.6, half * 0.72, hex(0x5a6068));
      k.box(lx, top + 0.6, lz, half * 0.6, 0.05, half * 0.6, GRANITE);
    });
    k.glowBox(x, top + 0.55, -0.15, 0.05, 0.05, 0.05, hex(0xe2412f), [0, 36, 2.8], hex(0xff4a3a));
  }
  // the dark vertical grille down the middle of the front, where the halves meet
  k.box(tx, 0.3, -0.15 + td / 2 + 0.01, 0.14, y0 - 0.3, 0.02, GRANITE_DARK);
};

// ---- the Cocoon Tower ----

const cocoonTower: Draw = (k, W, D, b, r) => {
  const floors = Math.max(30, b.floors), H = floors * FLOOR * 0.62;
  const Rx = (Math.min(W, D) - 0.3) * 0.34, Rz = Rx * 0.72;
  // the girth at height t (0 at the foot, 1 at the tip): swelling a little above the foot, tapering to the top
  const girth = (t: number) => (t < 0.18 ? 0.86 + t * 0.9 : 1.02 - Math.pow((t - 0.18) / 0.82, 1.6) * 0.9);
  const rings = 10, seg = 12;
  for (let i = 0; i < rings; i++) {
    const t0 = i / rings, t1 = (i + 1) / rings, g = girth((t0 + t1) / 2);
    k.cyl(0, t0 * H, 0, Rx * g * 0.95, (t1 - t0) * H, COCOON_GLASS, seg, COCOON_GLASS, Rz * g * 0.95);
  }
  // the web: bars crossing between rings, each running a step round the tower one way or the other
  const at = (t: number, a: number): [number, number, number] => [Math.cos(a) * Rx * girth(t), t * H, Math.sin(a) * Rz * girth(t)];
  for (let i = 0; i < rings; i++) {
    const t0 = i / rings, t1 = (i + 1) / rings;
    for (let j = 0; j < seg; j++) {
      const a = (j / seg) * TAU, step = TAU / seg;
      k.bar(at(t0, a), at(t1, a + step), 0.018, LATTICE);
      k.bar(at(t0, a + step), at(t1, a), 0.018, LATTICE);
    }
  }
  // the entrance at its foot, and the aircraft light at the tip
  k.box(0, 0, Rz * 0.9, Rx * 1.2, 0.24, 0.2, LATTICE);
  k.glowBox(0, H, 0, 0.06, 0.06, 0.06, hex(0xe2412f), [0, 36, 2.8], hex(0xff4a3a));
  void r;
};

// ---- the Godzilla tower ----

const godzillaTower: Draw = (k, W, D, b, r) => {
  // the cinema's podium, eight storeys, its screens' names lit down the front
  const pw = W - 0.16, pd = D - 0.16, ph = 8 * FLOOR;
  k.box(0, 0, 0, pw, ph, pd, TOHO, hex(0xb8b2a6));
  glazed(k, b, r, 0, 0, 0, pw, pd, 8, GLASS_LIGHT, 2);
  bladeSign(k, r, pw / 2 - 0.08, FLOOR, ph - 0.1, pd / 2);
  bladeSign(k, r, -pw / 2 + 0.08, FLOOR, ph * 0.7, pd / 2);
  // the hotel rising from the back half
  const hd = pd * 0.5, hz = -pd / 2 + hd / 2, hh = 22 * FLOOR;
  k.box(0, ph, hz, pw * 0.8, hh, hd, HOTEL, hex(0xa8acb0));
  glazed(k, b, r, 0, ph, hz, pw * 0.8, hd, 22, hex(0x7a8a96), 2);
  k.glowBox(0, ph + hh, hz, 0.05, 0.05, 0.05, hex(0xe2412f), [0, 36, 2.8], hex(0xff4a3a));
  // Godzilla, looking over the terrace at the street: skull, brow, snout, an open jaw full of teeth,
  // spines. Drawn at a head's size and scaled up about its own neck, big enough to read from the road.
  const G = 2.1, gz0 = pd / 2 - 0.86, gy = ph;
  const kk = { box: (x: number, y: number, z: number, w: number, h: number, d: number, c: RGB) => k.box(x * G, gy + (y - gy) * G, gz0 + (z - gz0) * G, w * G, h * G, d * G, c),
    glowBox: (x: number, y: number, z: number, w: number, h: number, d: number, c: RGB, s: Sched, g: RGB) => k.glowBox(x * G, gy + (y - gy) * G, gz0 + (z - gz0) * G, w * G, h * G, d * G, c, s, g) };
  const gz = gz0;
  kk.box(0, gy, gz - 0.1, 0.34, 0.22, 0.3, GODZILLA_DARK);               // neck, on the terrace
  kk.box(0, gy + 0.18, gz, 0.4, 0.28, 0.36, GODZILLA);                   // skull
  kk.box(0, gy + 0.4, gz + 0.02, 0.36, 0.06, 0.3, GODZILLA_DARK);        // brow
  kk.box(0, gy + 0.22, gz + 0.3, 0.3, 0.14, 0.3, GODZILLA);              // snout
  kk.box(0, gy + 0.08, gz + 0.26, 0.26, 0.07, 0.28, GODZILLA_DARK);      // jaw, hanging open
  for (let i = -2; i <= 2; i++) {
    kk.box(i * 0.05, gy + 0.18, gz + 0.43, 0.02, 0.04, 0.02, TEETH);
    kk.box(i * 0.045, gy + 0.15, gz + 0.38, 0.02, 0.03, 0.02, TEETH);
  }
  for (const s of [-1, 1]) kk.glowBox(s * 0.12, gy + 0.33, gz + 0.19, 0.06, 0.035, 0.02, hex(0xe8c040), ALL_NIGHT, hex(0xffd040));
  // the spines down its back, in three rows of jagged plates
  for (let i = 0; i < 4; i++) for (const s of [-0.08, 0, 0.08]) {
    const tall = s === 0 ? 0.2 - i * 0.03 : 0.12 - i * 0.02;
    kk.box(s, gy + 0.3 - i * 0.05, gz - 0.12 - i * 0.1, 0.03, tall, 0.07, GODZILLA_DARK);
  }
};

// ---- the yokocho ----

const yokocho: Draw = (k, W, D, _b, r) => {
  const n = Math.max(4, Math.round(W / 0.5)), cell = W / n, depth = D - 0.2;
  for (let i = 0; i < n; i++) {
    const x = -W / 2 + cell * (i + 0.5), h = FLOOR * (1.7 + (i % 3) * 0.18);
    const wall = i % 2 ? BAR_WOOD : scale(BAR_WOOD, 1.25);
    k.box(x, 0, -0.05, cell - 0.02, h, depth, wall);
    // a lean-to tin roof out over the front
    k.box(x, h, -0.05, cell, 0.03, depth + 0.1, TIN);
    k.box(x, FLOOR * 0.95, depth / 2 + 0.02, cell - 0.02, 0.025, 0.2, TIN);
    // a lit shopfront and noren over the door
    k.glowBox(x, 0.04, depth / 2 - 0.04, cell * 0.6, FLOOR * 0.62, 0.02, hex(0x8a6a4a), NEON_HOURS, hex(0xffc878));
    k.box(x, FLOOR * 0.6, depth / 2 - 0.02, cell * 0.64, 0.08, 0.01, pick3(r));
    // and a little lit sign on every one
    const c = neonColour(r);
    k.glowBox(x, h - 0.12, depth / 2 - 0.03, cell * 0.7, 0.08, 0.02, scale(c, 0.8), NEON_HOURS, c);
  }
  // the lanterns, strung the length of the lane under the eaves
  for (let x = -W / 2 + 0.12; x < W / 2 - 0.05; x += 0.2) {
    k.box(x, FLOOR * 1.02, depth / 2 + 0.1, 0.008, 0.03, 0.008, DARK);
    k.glowBox(x, FLOOR * 0.86, depth / 2 + 0.1, 0.07, 0.11, 0.07, LANTERN, NEON_HOURS, hex(0xff5a30));
  }
};

/** Noren colours: indigo, deep red, black and undyed. */
function pick3(r: Rng): RGB {
  const c = [0x2f4a7a, 0x8a2a2a, 0x2e2e34, 0xe8e2d4];
  return hex(c[Math.floor(r() * c.length)]);
}

// ---- Kabukicho's gate ----

const kabukichoGate: Draw = (k, W, D, _b, r) => {
  const span = W - 0.3, H = 1.3, z = 0;
  // two red columns and the beam across them
  for (const s of [-1, 1]) {
    k.box(s * span / 2, 0, z, 0.12, H, 0.12, GATE_RED);
    k.box(s * span / 2, 0, z, 0.2, 0.08, 0.2, DARK);
  }
  k.box(0, H, z, span + 0.2, 0.12, 0.14, GATE_RED);
  // the sign board over it, a frame of bulbs round a lit panel, and a smaller board under the beam
  k.box(0, H + 0.12, z, span * 0.86, 0.34, 0.08, GATE_RED);
  k.glowBox(0, H + 0.15, z + 0.045, span * 0.8, 0.28, 0.02, hex(0xe8e0d0), NEON_HOURS, hex(0xfff0c8));
  for (let x = -span * 0.4; x <= span * 0.4 + 1e-6; x += span * 0.8 / 12) {
    for (const y of [H + 0.13, H + 0.44]) k.glowBox(x, y, z + 0.05, 0.02, 0.02, 0.02, hex(0xffe8a0), NEON_HOURS, hex(0xfff4c0));
  }
  // the lettering, as bars of red on the lit board
  for (let i = 0; i < 6; i++) {
    const x = -span * 0.32 + i * span * 0.128;
    k.glowBox(x, H + 0.2, z + 0.058, 0.08, 0.16, 0.01, hex(0xc8202a), NEON_HOURS, hex(0xff3a40));
  }
  k.glowBox(0, H - 0.2, z + 0.075, span * 0.5, 0.12, 0.02, scale(neonColour(r), 0.8), NEON_HOURS, hex(0x2ee0ff));
  void D;
};

export const TOKYO_DRAW = {
  shibuyaTower, scrambleCrossing, metroGovTower, cocoonTower, godzillaTower, yokocho, kabukichoGate,
} satisfies Record<string, Draw>;
