/**
 * Track and stations the player lays from the builder's Rails side (game/railBuilder.ts; docs/trains.html,
 * "Laying your own track").
 *
 * A built track is kept as an edit (world/delta.ts 'rail'): a coarse polyline of points with heights, in steps,
 * about a tile apart, and how each end meets the world (buffers, a join onto another path, or the cell border).
 * This file shapes that polyline into a RailPath exactly as the generator's lines are kept — staircases pulled
 * into straight diagonals, corners rounded, resampled a quarter tile apart, the vertical line held to the
 * ruling grade and never below the ground, every sample classed as bank, trestle, viaduct, truss or tunnel —
 * and writes the tile bits every reader of the railway expects (world/railPlan.ts cutAndMark), so trains,
 * cars, the chunk meshes, the fit layer and the land tool all take a built line for a line.
 *
 * Built track never cuts the ground: where the ground is too high for the grade the line rises onto a bank or
 * a trestle rather than into a cutting, so replaying the edit over a fresh cell is a pure function of the
 * points it carries. A station does level its pad, as a town's building does (growth.ts applyBuild), and for
 * the same reason it is safe: a built tile is a building's for good.
 */
import {
  N, STEP, Biome, Flag, Lot, RailBit, Under, World, idx, inB, heightAt, waterDepth, maxCorner, minCorner,
  type Building, type RailEnd, type RailEra, type RailPath, type RailStation, type StationKind,
} from './tiles';
import { RAIL_LIFT, SAMPLE, STATION_LOT, TRACK_GAP } from './railPlan';
import { solidMask } from './footprint';
import { buildingHeight } from './towns';

/** The ruling grade of built track, steps per tile: steeper than the generator's 1 in 6, so a line can follow the roads' country. */
export const BUILT_GRADE = 1 / 3;
/** Tiles a joining track shares with the line it joins before (or after) leaving it, and how far along the line from the junction foot it departs. */
export const LEAD = 2, DEPART = 3;
/** The smallest gap between a parallel track and the line it follows, in tiles (a passing loop's offset). */
export const MIN_GAP = 1.1;
/** The most points one built track may carry: about that many tiles. */
export const MAX_POINTS = 400;
/** The largest radius a corner is rounded to, in tiles. */
const FILLET = 3;
/** How far a station's pad may be from level before it is placed, in steps (the pad is levelled to the mean). */
const PAD_ROUGH = 3;

const BUILT_PREFIX = 'p:';
/** Whether a path is the player's (laid here) rather than the generator's. */
export const isBuiltRail = (p: RailPath): boolean => p.key.startsWith(BUILT_PREFIX) || p.key.startsWith('pb:');

/** One built track as the edit keeps it: points x, z, y (tile coordinates and steps) and how its ends meet the world. */
export interface RailSpec {
  p: number[];
  era: RailEra;
  a?: RailEnd;
  b?: RailEnd;
  /** The line's name; a track joining another takes that line's, else it is a private line. */
  nm?: string;
  /** Online: the player who laid it (the server stamps every edit), so only they and their fleet may take it up. */
  by?: string;
}

/** A built station as the edit keeps it: its kind, the lot's origin tile and facing, the line's period and its name. */
export interface StationSpec { kind: StationKind; x: number; z: number; f: number; era: RailEra; nm: string; sd: number; by?: string }

// ---------------------------------------------------------------------------------------------
// the tile bits as the generator left them, so a built track can be taken up again

interface Marks { rail: Uint8Array; axis: Uint8Array }
const RAIL0 = new WeakMap<World, Marks>();
/** A path end this file turned from buffers into a join when a track was carried on from it, and what it was. */
const CONVERTED = new WeakMap<RailPath, { path: RailPath; which: 'start' | 'end'; was: RailEnd }[]>();

function keep0(w: World): void {
  if (!RAIL0.has(w)) RAIL0.set(w, { rail: w.rail.slice(), axis: w.railAxis.slice() });
}

// ---------------------------------------------------------------------------------------------
// shaping a polyline into a path

/** Douglas–Peucker over (x, z, y): a staircase of tile steps becomes one straight diagonal, a deck's crest is kept. */
/**
 * For each sample of the smoothed line, the height the route's own points ask for there: the route's polyline (its tile
 * centres, a staircase on a diagonal) is found nearest the sample in plan, walking along with it, and its height read
 * off between its two points. -Infinity where nothing is near (never in practice: the line is drawn through them).
 */
function askedHeights(raw: number[][], dense: number[][]): Float64Array {
  const out = new Float64Array(dense.length).fill(-Infinity);
  let seg = 0;
  for (let i = 0; i < dense.length; i++) {
    const [px, pz] = dense[i];
    let best = Infinity, bestY = -Infinity, bestK = seg;
    // the nearest stretch, looking a few on from the last one found (the two lines run along together)
    for (let k = Math.max(0, seg - 2); k < Math.min(raw.length - 1, seg + 8); k++) {
      const [ax, az, ay] = raw[k], [bx, bz, by] = raw[k + 1];
      const dx = bx - ax, dz = bz - az, L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.min(1, Math.max(0, ((px - ax) * dx + (pz - az) * dz) / L2));
      const d = Math.hypot(px - ax - dx * t, pz - az - dz * t);
      if (d < best) { best = d; bestY = ay + (by - ay) * t; bestK = k; }
    }
    seg = bestK;
    // only where the smoothed line is really passing that stretch (a corner's fillet cuts inside it by up to a tile)
    if (best <= 1.25) out[i] = bestY;
  }
  return out;
}

function simplify(pts: number[][], tol: number): number[][] {
  if (pts.length <= 2) return pts;
  const keep = new Uint8Array(pts.length);
  keep[0] = keep[pts.length - 1] = 1;
  const stack: [number, number][] = [[0, pts.length - 1]];
  while (stack.length) {
    const [a, b] = stack.pop()!;
    const [ax, az, ay] = pts[a], [bx, bz, by] = pts[b];
    const dx = bx - ax, dz = bz - az, dy = by - ay, L2 = dx * dx + dz * dz + dy * dy || 1e-9;
    let worst = -1, worstD = tol;
    for (let i = a + 1; i < b; i++) {
      const [px, pz, py] = pts[i];
      const t = Math.min(1, Math.max(0, ((px - ax) * dx + (pz - az) * dz + (py - ay) * dy) / L2));
      const d = Math.hypot(px - ax - dx * t, pz - az - dz * t, py - ay - dy * t);
      if (d > worstD) { worstD = d; worst = i; }
    }
    if (worst < 0) continue;
    keep[worst] = 1;
    stack.push([a, worst], [worst, b]);
  }
  return pts.filter((_, i) => keep[i]);
}

/** Round every corner: the two legs meet through a short curve, as long as the legs and the radius cap allow. */
function fillet(pts: number[][]): number[][] {
  if (pts.length < 3) return pts;
  const out: number[][] = [pts[0]];
  for (let i = 1; i + 1 < pts.length; i++) {
    const P = pts[i], A = out[out.length - 1], B = pts[i + 1];
    const ux = P[0] - A[0], uz = P[1] - A[1], la = Math.hypot(ux, uz) || 1e-9;
    const vx = B[0] - P[0], vz = B[1] - P[1], lb = Math.hypot(vx, vz) || 1e-9;
    const cos = (ux * vx + uz * vz) / (la * lb);
    const th = Math.acos(Math.max(-1, Math.min(1, cos)));
    if (th < 0.03) { out.push(P); continue; }
    // the tangent length: half a leg at most (the next corner wants the other half), and the radius cap
    const t = Math.min(FILLET * Math.tan(th / 2), la * 0.5, lb * 0.5);
    if (t < 0.05) { out.push(P); continue; }
    const fa = 1 - t / la, fb = t / lb;
    const a = [A[0] + ux * fa, A[1] + uz * fa, A[2] + (P[2] - A[2]) * fa];
    const b = [P[0] + vx * fb, P[1] + vz * fb, P[2] + (B[2] - P[2]) * fb];
    const segs = Math.max(4, Math.ceil((th * 2 * t) / SAMPLE / 1.5));
    for (let k = 0; k <= segs; k++) {
      const s = k / segs, m = 1 - s;
      out.push([m * m * a[0] + 2 * m * s * P[0] + s * s * b[0], m * m * a[1] + 2 * m * s * P[1] + s * s * b[1], a[2] + (b[2] - a[2]) * s]);
    }
  }
  out.push(pts[pts.length - 1]);
  return out;
}

/** Resample at the generator's spacing, keeping both ends exactly, heights carried along. */
function resample3(pts: number[][]): number[][] {
  const out: number[][] = [pts[0].slice()];
  let carry = 0;
  for (let k = 1; k < pts.length; k++) {
    const [ax, az, ay] = pts[k - 1], [bx, bz, by] = pts[k];
    const seg = Math.hypot(bx - ax, bz - az);
    if (seg < 1e-6) continue;
    let t = SAMPLE - carry;
    while (t <= seg) {
      const f = t / seg;
      out.push([ax + (bx - ax) * f, az + (bz - az) * f, ay + (by - ay) * f]);
      t += SAMPLE;
    }
    carry = seg - (t - SAMPLE);
  }
  const last = pts[pts.length - 1];
  const l = out[out.length - 1];
  if (Math.hypot(last[0] - l[0], last[1] - l[1]) > SAMPLE * 0.4) out.push(last.slice());
  else out[out.length - 1] = last.slice();
  return out;
}

/** The ground under a sample, in steps: the highest of the centre and a little either side, so the bank never buries a rail. */
function groundUnder(w: World, x: number, z: number, nx: number, nz: number): number {
  let g = heightAt(w, x, z);
  for (const o of [-0.3, 0.3]) g = Math.max(g, heightAt(w, x + nx * o, z + nz * o));
  return g / STEP;
}

const wetTile = (w: World, t: number): boolean => waterDepth(w, t) > 0;
const seaTile = (w: World, t: number): boolean => w.biome[t] === Biome.Ocean;
const atGrade = (c: number): boolean => c === Under.Ground || c === Under.Embank;

/**
 * What carries the track at every sample, the generator's rules read off the finished ground (railPlan.ts
 * classify): over water a truss, over the sea a sea viaduct; on land by how far the rail stands over the
 * ground — nothing is ever a cutting, since built track cuts nothing. A tunnel is where the track was asked for
 * under the hill (`bore`, shapeWith's bores) and lies under the ground there.
 */
function classify(w: World, xz: Float32Array, y: Float32Array, n: number, bore: Uint8Array): Uint8Array {
  const cls = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const x = xz[i * 2], z = xz[i * 2 + 1];
    const tx = Math.min(N - 1, Math.max(0, Math.floor(x))), tz = Math.min(N - 1, Math.max(0, Math.floor(z)));
    const t = tz * N + tx;
    if (wetTile(w, t)) { cls[i] = seaTile(w, t) ? Under.Sea : Under.Truss; continue; }
    const diff = y[i] / STEP - heightAt(w, x, z) / STEP;
    cls[i] = bore[i] && diff < -BORE_SKIN ? Under.Tunnel : diff < 0.7 ? Under.Ground : diff < 1.6 ? Under.Embank : diff < 4.5 ? Under.Trestle : Under.Viaduct;
  }
  const runs = (fn: (c: number, i0: number, i1: number) => void) => {
    let i0 = 0;
    for (let i = 1; i <= n; i++) if (i === n || cls[i] !== cls[i0]) { fn(cls[i0], i0, i - 1); i0 = i; }
  };
  const tiles = (i0: number, i1: number) => (i1 - i0 + 1) * SAMPLE;
  runs((c, i0, i1) => { if (c === Under.Sea && tiles(i0, i1) < 16) cls.fill(Under.Truss, i0, i1 + 1); });
  const wetRuns: [number, number][] = [];
  runs((c, i0, i1) => { if (c === Under.Truss && tiles(i0, i1) < 3) wetRuns.push([i0, i1]); });
  for (const [i0, i1] of wetRuns) {
    const grow = Math.ceil((3 - tiles(i0, i1)) / SAMPLE / 2);
    for (let i = Math.max(0, i0 - grow); i <= Math.min(n - 1, i1 + grow); i++) if (cls[i] !== Under.Sea && cls[i] !== Under.Tunnel) cls[i] = Under.Truss;
  }
  for (let pass = 0; pass < 3; pass++) {
    const list: [number, number, number][] = [];
    runs((c, i0, i1) => list.push([c, i0, i1]));
    list.forEach(([c, i0, i1], k) => {
      if (tiles(i0, i1) >= 2 || c === Under.Sea || c === Under.Truss || c === Under.Tunnel) return;
      const before = list[k - 1], after = list[k + 1];
      const lenOf = (r?: [number, number, number]) => (r ? tiles(r[1], r[2]) : -1);
      const take = lenOf(before) >= lenOf(after) ? before : after;
      if (!take || take[0] === Under.Tunnel) return;
      const cls2 = take[0] === Under.Truss || take[0] === Under.Sea ? Under.Trestle : take[0];
      cls.fill(cls2, i0, i1 + 1);
    });
  }
  runs((c, i0, i1) => {
    if (c !== Under.Trestle) return;
    let tall = false;
    for (let i = i0; i <= i1; i++) if (y[i] / STEP - heightAt(w, xz[i * 2], xz[i * 2 + 1]) / STEP > 3) tall = true;
    if (tiles(i0, i1) > 10 || tall) cls.fill(Under.Viaduct, i0, i1 + 1);
  });
  return cls;
}

/** A bore is asked for where a track's height is this far under the ground (steps), for BORE_MIN tiles or more… */
const BORE_DEEP = 1.0, BORE_MIN = 3;
/** …it is a tunnel from where it is this far under (nearer the surface it is still open track running in at the mouth)… */
const BORE_SKIN = 0.3;
/** …and its mouths, where the hillside is still rising over it, reach at most this many tiles out from the deep of it. */
const BORE_MOUTH = 4;

/**
 * The samples of a track that keep the height they were asked for though it is under the ground: its tunnels. The
 * planner's bore (world/roads.ts tunnelBetween, through railRoute.ts heightsOf) is a straight line from one foot of
 * the hill to the other, and all of it is kept: the deep of it, and the mouth at each end where the hill has not yet
 * risen over the track. Until 11 Nov 2026 only samples a step and a half under were kept, each on its own, and the
 * rest lifted onto the hillside, so the track climbed the slope it was meant to enter and the ruling grade then held
 * it up out of most of its own tunnel; what was left was a tunnel only from six tiles, two steps deep.
 */
function bores(g: Float64Array, want: Float64Array, s: Float32Array, n: number): Uint8Array {
  const keep = new Uint8Array(n);
  let i = 0;
  while (i < n) {
    if (want[i] >= g[i] - BORE_DEEP) { i++; continue; }
    // the deep of it: on while the track stays under the skin, to the last sample properly deep
    let i1 = i, deep = 0;
    for (let k = i; k < n && want[k] < g[k] - BORE_SKIN; k++) if (want[k] < g[k] - BORE_DEEP) { i1 = k; deep++; }
    if (deep * SAMPLE >= BORE_MIN) {
      let a = i, b = i1;
      while (a > 0 && s[i] - s[a - 1] <= BORE_MOUTH && want[a - 1] < g[a - 1] + RAIL_LIFT) a--;
      while (b < n - 1 && s[b + 1] - s[i1] <= BORE_MOUTH && want[b + 1] < g[b + 1] + RAIL_LIFT) b++;
      keep.fill(1, a, b + 1);
    }
    i = i1 + 1;
  }
  return keep;
}

/** The key two halves of one track share where it crosses a border, so the network stitches them (game/trains.ts next). */
function borderKey(w: World, e: RailEnd): string {
  const side = e.side ?? 0, at = e.at ?? 0;
  return side % 2 === 0 ? `pb:x${w.ox + (side === 0 ? N : 0)}:${w.oz + at}` : `pb:z${w.oz + (side === 1 ? N : 0)}:${w.ox + at}`;
}

/**
 * The path a spec shapes into, with the problem that stops it (null for none). `id` is the index it will
 * have in w.rails. Nothing is written.
 */
export function shapeRail(w: World, spec: RailSpec, id: number): { path: RailPath | null; why: string | null } {
  const raw: number[][] = [];
  // to two decimals, as the edit keeps them (delta.ts noteRail): what is laid here is exactly what a replay lays
  const r2 = (v: number) => Math.round(v * 100) / 100;
  for (let k = 0; k + 2 < spec.p.length; k += 3) raw.push([r2(spec.p[k]), r2(spec.p[k + 1]), r2(spec.p[k + 2])]);
  if (raw.length < 2) return { path: null, why: 'Too short to lay' };
  if (raw.length > MAX_POINTS) return { path: null, why: `Too long for one track: lay it in two (${MAX_POINTS} tiles at most)` };
  for (const q of raw) if (!Number.isFinite(q[0]) || !Number.isFinite(q[1]) || !Number.isFinite(q[2])) return { path: null, why: 'Bad points' };
  // a route is a staircase of tile centres: drawn through every step, a diagonal (a long bridge over the sea most of
  // all) waved from side to side (the user, 2 Nov 2026). Straightened past STRAIGHTEN first, so it runs as one line
  // or one long sweep; where that would touch something, as tight as before (which every track laid till now passes)
  const loose = shapeWith(w, spec, id, raw, STRAIGHTEN);
  return loose.path ? loose : shapeWith(w, spec, id, raw, 0.36);
}

/** How far (tiles) a route's points may stand off the straightened line: a staircase's steps, not its turns. */
const STRAIGHTEN = 1;

function shapeWith(w: World, spec: RailSpec, id: number, raw: number[][], tol: number): { path: RailPath | null; why: string | null } {
  const dense = resample3(fillet(simplify(raw, tol)));
  const n = dense.length;
  if (n < 3) return { path: null, why: 'Too short to lay' };
  const xz = new Float32Array(n * 2), y = new Float32Array(n), s = new Float32Array(n);
  const h = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    xz[i * 2] = dense[i][0]; xz[i * 2 + 1] = dense[i][1];
    if (i) s[i] = s[i - 1] + Math.hypot(dense[i][0] - dense[i - 1][0], dense[i][1] - dense[i - 1][1]);
  }
  // the vertical line: the heights asked for, never below the ground (a tunnel's deep run excepted), then held
  // to the ruling grade by raising only, so what is cleared stays cleared
  // the heights the route asked for, where the straightened line passes: straightening keeps a point only where it is
  // a tile off the line in all three, so a platform standing a little higher (a viaduct held over the sea for the boats,
  // a deck over a road) was dropped and the line sagged past it (3 Nov 2026). Read off the route itself, raising only.
  const asked = askedHeights(raw, dense);
  const g = new Float64Array(n), want = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const ip = Math.min(n - 1, i + 1), im = Math.max(0, i - 1);
    const dx = xz[ip * 2] - xz[im * 2], dz = xz[ip * 2 + 1] - xz[im * 2 + 1], len = Math.hypot(dx, dz) || 1;
    g[i] = groundUnder(w, xz[i * 2], xz[i * 2 + 1], -dz / len, dx / len);
    want[i] = Math.max(dense[i][2], asked[i]);
  }
  const bore = bores(g, want, s, n);
  for (let i = 0; i < n; i++) h[i] = bore[i] ? want[i] : Math.max(want[i], g[i] + RAIL_LIFT);
  // (by the distance between samples, not their count: the last one can stand short of a full spacing)
  for (let i = 1; i < n; i++) h[i] = Math.max(h[i], h[i - 1] - BUILT_GRADE * (s[i] - s[i - 1]));
  for (let i = n - 2; i >= 0; i--) h[i] = Math.max(h[i], h[i + 1] - BUILT_GRADE * (s[i + 1] - s[i]));

  for (let i = 0; i < n; i++) y[i] = h[i] * STEP;
  const under = classify(w, xz, y, n, bore);
  // what it runs over
  for (let i = 0; i < n; i++) {
    const tx = Math.floor(xz[i * 2]), tz = Math.floor(xz[i * 2 + 1]);
    if (!inB(tx, tz)) {
      // only a border end may touch the line itself
      const onLine = (i === 0 && spec.a?.kind === 'border') || (i === n - 1 && spec.b?.kind === 'border');
      if (!onLine) return { path: null, why: 'Runs off the edge of the county' };
      continue;
    }
    const t = tz * N + tx;
    if (under[i] !== Under.Tunnel && w.blocked[t]) return { path: null, why: 'A building is in the way' };
    if (wetTile(w, t) && y[i] < (w.water[t] + 0.4) * STEP) return { path: null, why: 'It would run into the water: raise it (+) or bridge it' };
  }
  const start: RailEnd = spec.a ? { ...spec.a } : { kind: 'stop' };
  const end: RailEnd = spec.b ? { ...spec.b } : { kind: 'stop' };
  const key = start.kind === 'border' ? borderKey(w, start) : end.kind === 'border' ? borderKey(w, end) : `${BUILT_PREFIX}${w.cx},${w.cz}:${id}`;
  const joined = start.kind === 'join' ? w.rails[start.path ?? -1] : end.kind === 'join' ? w.rails[end.path ?? -1] : null;
  const name = spec.nm ?? joined?.name ?? 'Private Line';
  const kind = start.kind === 'join' || end.kind === 'join' ? 'stub' : 'main';
  return { path: { id, key, kind, era: spec.era, name, xz, y, s, under, length: s[n - 1], start, end, ...(spec.by ? { by: spec.by } : {}) }, why: null };
}

// ---------------------------------------------------------------------------------------------
// the tile bits

/** Set every tile's bits for a path (railPlan.ts cutAndMark, without the cutting); the tiles touched go into `touched`. */
function mark(w: World, p: RailPath, touched: Set<number>): void {
  const n = p.s.length;
  const axisVotes = new Map<number, number>();
  for (let i = 0; i < n; i++) {
    const x = p.xz[i * 2], z = p.xz[i * 2 + 1];
    const c = p.under[i];
    const ip = Math.min(n - 1, i + 1), im = Math.max(0, i - 1);
    const dx = p.xz[ip * 2] - p.xz[im * 2], dz = p.xz[ip * 2 + 1] - p.xz[im * 2 + 1];
    const len = Math.hypot(dx, dz) || 1;
    const nx = -dz / len, nz = dx / len;
    for (const o of [-0.45, 0, 0.45]) {
      const tx = Math.floor(x + nx * o), tz = Math.floor(z + nz * o);
      if (!inB(tx, tz)) continue;
      const t = tz * N + tx;
      touched.add(t);
      if (w.blocked[t]) continue;
      if (c === Under.Tunnel) { w.rail[t] |= RailBit.Tunnel; continue; }
      if (atGrade(c)) {
        w.rail[t] |= RailBit.Track;
        w.flags[t] &= ~Flag.Stream;
        w.cleared[t] = 1;
      } else {
        w.rail[t] |= RailBit.Deck;
      }
    }
    if (c === Under.Sea && Math.round(p.s[i] / SAMPLE) % Math.round(3 / SAMPLE) === 0 && Math.abs(p.s[i] - p.length / 2) > 6) {
      const tx = Math.floor(x), tz = Math.floor(z);
      if (inB(tx, tz)) w.rail[tz * N + tx] |= RailBit.Pier;
    }
    // (a building standing in the margin keeps the bit too: it is only ever read by what grows, and the bits must
    // come out the same whether the building went up before the track or after, for undo and for replay)
    if (c !== Under.Tunnel) {
      for (const o of [-1.5, -1, 1, 1.5]) {
        const tx = Math.floor(x + nx * o), tz = Math.floor(z + nz * o);
        if (!inB(tx, tz)) continue;
        const t = tz * N + tx;
        w.rail[t] |= RailBit.Reserved;
        w.cleared[t] = 1;
        touched.add(t);
      }
    }

    // crossings: straight at-grade track square to the grid, where a road may cross on the level
    const ip4 = Math.min(n - 1, i + 4), im4 = Math.max(0, i - 4);
    const dx4 = p.xz[ip4 * 2] - p.xz[im4 * 2], dz4 = p.xz[ip4 * 2 + 1] - p.xz[im4 * 2 + 1];
    const l4 = Math.hypot(dx4, dz4) || 1;
    let axis = 0;
    if (Math.abs(dz4) / l4 < 0.03) axis = 1;
    else if (Math.abs(dx4) / l4 < 0.03) axis = 2;
    const deckAbove = p.y[i] / STEP - heightAt(w, x, z) / STEP;
    if (c !== Under.Ground || deckAbove > 0.6) axis = 0;
    for (const o of [-0.45, 0, 0.45]) {
      const tx = Math.floor(x - (dz / len) * o), tz = Math.floor(z + (dx / len) * o);
      if (!inB(tx, tz)) continue;
      const t = tz * N + tx;
      const prev = axisVotes.get(t);
      axisVotes.set(t, prev === undefined ? axis : prev === axis ? axis : 0);
    }
  }
  for (const [t, axis] of axisVotes) {
    if (w.rail[t] & (RailBit.Pad | RailBit.Loop | RailBit.Deck | RailBit.Tunnel)) { w.railAxis[t] = 0; continue; }
    // a tile two lines share keeps a crossing only where both run the same way
    const had = w.railAxis[t];
    w.railAxis[t] = axis && (!had || had === axis) ? axis : 0;
  }
}

/** The tiles of a built station's pad: its lot and the platform strip beside the track. */
function padTiles(w: World, st: RailStation): number[] {
  const out = new Set<number>();
  const b = st.building, p = w.rails[st.path];
  if (b) for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) out.add(idx(x, z));
  if (p) {
    const n = p.s.length;
    for (let i = 0; i < n; i++) {
      const ip = Math.min(n - 1, i + 1), im = Math.max(0, i - 1);
      const dx = p.xz[ip * 2] - p.xz[im * 2], dz = p.xz[ip * 2 + 1] - p.xz[im * 2 + 1], len = Math.hypot(dx, dz) || 1;
      for (const o of [-0.5, 0, 0.5]) {
        const x = Math.floor(p.xz[i * 2] - (dz / len) * o), z = Math.floor(p.xz[i * 2 + 1] + (dx / len) * o);
        if (inB(x, z)) out.add(idx(x, z));
      }
    }
  }
  return [...out];
}

/** Every built path's and built station's bits laid again over the generator's own (after one is taken up). */
function remark(w: World): Set<number> {
  const touched = new Set<number>();
  const m0 = RAIL0.get(w);
  if (!m0) return touched;
  w.rail.set(m0.rail);
  w.railAxis.set(m0.axis);
  const builtStations = w.stations.filter((st) => w.rails[st.path] && isBuiltRail(w.rails[st.path]));
  for (const st of builtStations) for (const t of padTiles(w, st)) { w.rail[t] |= RailBit.Pad; w.railAxis[t] = 0; touched.add(t); }
  for (const p of w.rails) if (isBuiltRail(p)) mark(w, p, touched);
  for (const t of touched) if (w.rail[t] & RailBit.Pad) w.railAxis[t] = 0;
  return touched;
}

/** Where a path end joins another at the very end of it (carrying a dead end on), that path's buffers become the join. */
function continueFrom(w: World, p: RailPath, which: 'start' | 'end'): void {
  const e = which === 'start' ? p.start : p.end;
  if (e.kind !== 'join' || e.path === undefined) return;
  const q = w.rails[e.path];
  if (!q || q === p) return;
  const mine = which === 'start' ? 0 : p.length;
  const myDir: 1 | -1 = which === 'start' ? 1 : -1;
  let convert: 'start' | 'end' | null = null;
  if ((e.s ?? 0) <= 0.02 && q.start.kind === 'stop') convert = 'start';
  else if ((e.s ?? 0) >= q.length - 0.02 && q.end.kind === 'stop') convert = 'end';
  if (!convert) return;
  const was = convert === 'start' ? q.start : q.end;
  const now: RailEnd = { kind: 'join', path: p.id, s: mine, dir: myDir };
  if (convert === 'start') q.start = now; else q.end = now;
  e.s = convert === 'start' ? 0 : q.length;
  e.dir = convert === 'start' ? 1 : -1;
  const list = CONVERTED.get(p) ?? [];
  list.push({ path: q, which: convert, was });
  CONVERTED.set(p, list);
}

/** The snapped-to ends of a join, read back from the path it joins: a bad index or a loop refuses the track. */
function joinProblem(w: World, e: RailEnd | undefined): string | null {
  if (!e || e.kind !== 'join') return null;
  const q = e.path === undefined ? undefined : w.rails[e.path];
  if (!q) return 'The line it joins is not here';
  if (q.kind === 'loop') return 'A track can’t join a passing loop: join the main line beside it';
  if (!(e.s !== undefined && e.s >= -0.01 && e.s <= q.length + 0.01)) return 'The join is off the end of that line';
  return null;
}

/**
 * A track's joins as they stand in this county, for one replayed from a log (world/delta.ts applyEdit). A join names
 * the line it meets by its place in the county's list of paths; a log the server kept with an undone track still in
 * it (the user, 6 Nov 2026: a player's whole network gone after a reload) has every later track one place out, so its
 * joins named the wrong line, were refused off its end, and took every track joined after them down too. A join's end
 * stands exactly on the line it meets, `s` along it: when the named line isn't there at that point, the line that is
 * takes its place. With none there, the join is left as it was (and refused as before).
 */
export function mendJoins(w: World, spec: RailSpec): RailSpec {
  const n = Math.floor(spec.p.length / 3);
  if (n < 2) return spec;
  const end = (k: number) => ({ x: spec.p[k * 3], z: spec.p[k * 3 + 1] });
  const fits = (q: RailPath | undefined, s: number, pt: { x: number; z: number }) => {
    if (!q || q.kind === 'loop' || !(s >= -0.01 && s <= q.length + 0.01)) return false;
    const m = railAt(q, Math.max(0, Math.min(q.length, s)));
    return Math.hypot(m.x - pt.x, m.z - pt.z) < MEND_NEAR;
  };
  const mend = (e: RailEnd | undefined, pt: { x: number; z: number }): RailEnd | undefined => {
    if (!e || e.kind !== 'join' || e.path === undefined || e.s === undefined) return e;
    if (fits(w.rails[e.path], e.s, pt)) return e;
    const k = w.rails.findIndex((r) => fits(r, e.s!, pt));
    return k >= 0 ? { ...e, path: k } : e;
  };
  const a = mend(spec.a, end(0)), b = mend(spec.b, end(n - 1));
  return a === spec.a && b === spec.b ? spec : { ...spec, a, b };
}

/** How near (tiles) a join's end must stand to the line at its `s` to be on it: the points are kept to 2 dp. */
const MEND_NEAR = 0.06;

/**
 * Lay a built track: the path shaped, its bits set, its ends tied in. Returns the path and every tile that
 * changed, or null (with why) when it can't be laid. w.rails is replaced, not added to, so caches keyed on
 * the list (the network, the ballast index, the distant ribbons) notice.
 */
export function layRail(w: World, spec: RailSpec): { path: RailPath; tiles: number[]; why?: undefined } | { path: null; tiles: []; why: string } {
  const jp = joinProblem(w, spec.a) ?? joinProblem(w, spec.b);
  if (jp) return { path: null, tiles: [], why: jp };
  const id = w.rails.length;
  const { path, why } = shapeRail(w, spec, id);
  if (!path) return { path: null, tiles: [], why: why ?? 'Can’t lay it there' };
  keep0(w);
  const touched = new Set<number>();
  mark(w, path, touched);
  w.rails = [...w.rails, path];
  continueFrom(w, path, 'start');
  continueFrom(w, path, 'end');
  w.revision++;
  return { path, tiles: [...touched] };
}

/** Take up the newest built track (not a station's platform). Returns the tiles to redraw, or null when there is none. */
export function unlayLastRail(w: World): { path: RailPath; tiles: number[] } | null {
  const last = w.rails[w.rails.length - 1];
  if (!last || !isBuiltRail(last) || w.stations.some((st) => st.path === last.id)) return null;
  return { path: last, tiles: removeRail(w, last) };
}

/**
 * Take a built path up from anywhere in the list (the bulldozer): every later path moves down one, and every
 * join, station and loop index with it; a track that joined it now ends at buffers there, and a dead end it was
 * carried on from has its buffers back. Returns the tiles to redraw. Nothing is done to a generated path.
 */
export function removeRail(w: World, p: RailPath): number[] {
  const k = w.rails.indexOf(p);
  if (k < 0 || !isBuiltRail(p)) return [];
  const touched = new Set<number>();
  mark(w, p, touched);   // the tiles it covered, for the redraw (the bits are laid again below)
  for (const c of CONVERTED.get(p) ?? []) { if (c.which === 'start') c.path.start = c.was; else c.path.end = c.was; }
  CONVERTED.delete(p);
  const rest = w.rails.filter((q) => q !== p);
  for (const q of rest) {
    for (const which of ['start', 'end'] as const) {
      const e = q[which];
      if (e.kind !== 'join' || e.path === undefined) continue;
      if (e.path === k) q[which] = { kind: 'stop' };
      else if (e.path > k) q[which] = { ...e, path: e.path - 1 };
    }
    const conv = CONVERTED.get(q);
    if (conv) CONVERTED.set(q, conv.filter((c) => c.path !== p));
  }
  rest.forEach((q, i) => {
    q.id = i;
    // a built line's own key names its place in the list (a border half keeps the key its neighbour shares)
    if (q.key.startsWith(BUILT_PREFIX)) q.key = `${BUILT_PREFIX}${w.cx},${w.cz}:${i}`;
  });
  for (const st of w.stations) {
    if (st.path > k) st.path--;
    if (st.loop === k) st.loop = -1;
    else if (st.loop > k) st.loop--;
    if (st.twin && st.twin.path > k) st.twin.path--;
  }
  w.rails = rest;
  for (const t of remark(w)) touched.add(t);
  w.revision++;
  return [...touched];
}

// ---------------------------------------------------------------------------------------------
// finding the line

/** The nearest sample of any path (loops left out, and `skip`) to a point, within `range` tiles, or null. */
export function nearestRail(w: World, x: number, z: number, range: number, loops = false, skip: RailPath | null = null): { k: number; i: number; d: number; p: RailPath } | null {
  let best: { k: number; i: number; d: number; p: RailPath } | null = null;
  w.rails.forEach((p, k) => {
    if ((p.kind === 'loop' && !loops) || p === skip) return;
    const n = p.s.length;
    for (let i = 0; i < n; i++) {
      if (p.under[i] === Under.Tunnel) continue;
      const d = Math.hypot(p.xz[i * 2] - x, p.xz[i * 2 + 1] - z);
      if (d < range && (!best || d < best.d)) best = { k, i, d, p };
    }
  });
  return best;
}

/** The point and unit tangent of a path at arc length s (clamped). */
export function railAt(p: RailPath, s: number): { x: number; z: number; y: number; tx: number; tz: number } {
  const n = p.s.length;
  const c = Math.min(p.length, Math.max(0, s));
  let i = Math.min(n - 2, Math.max(0, Math.floor((c / (p.length || 1)) * (n - 1))));
  while (i > 0 && p.s[i] > c) i--;
  while (i < n - 2 && p.s[i + 1] < c) i++;
  const span = p.s[i + 1] - p.s[i] || 1;
  const f = Math.min(1, Math.max(0, (c - p.s[i]) / span));
  const dx = p.xz[i * 2 + 2] - p.xz[i * 2], dz = p.xz[i * 2 + 3] - p.xz[i * 2 + 1], l = Math.hypot(dx, dz) || 1;
  return { x: p.xz[i * 2] + dx * f, z: p.xz[i * 2 + 1] + dz * f, y: p.y[i] + (p.y[i + 1] - p.y[i]) * f, tx: dx / l, tz: dz / l };
}

/**
 * Points along `q` from s0 to s1 (either way), offset `gap` tiles to the left of increasing s (negative for
 * the right), about a tile apart, at the line's own heights: a parallel track. In the x, z, y(steps) form a spec takes.
 */
export function offsetPoints(q: RailPath, gap: number, s0: number, s1: number): number[] {
  const out: number[] = [];
  const dir = s1 >= s0 ? 1 : -1;
  const L = Math.abs(s1 - s0);
  const steps = Math.max(1, Math.round(L));
  for (let k = 0; k <= steps; k++) {
    const s = s0 + dir * (L * k) / steps;
    const a = railAt(q, s);
    out.push(a.x - a.tz * gap, a.z + a.tx * gap, a.y / STEP);
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// stations

/** A kind's lot, platform line and building side for a lot at (x, z) facing f (DIRS index the forecourt looks away from the track). */
export function stationLot(kind: StationKind, x: number, z: number, f: number): {
  lot: { x: number; z: number; w: number; d: number; facing: number }; a: { x: number; z: number }; b: { x: number; z: number }; side: 1 | -1; gate: [number, number][];
} {
  const [W, D] = STATION_LOT[kind];
  const alongX = f === 1 || f === 3;
  const lot = alongX ? { x, z, w: W, d: D, facing: f } : { x, z, w: D, d: W, facing: f };
  // the track beyond the front edge (the way the lot faces); the forecourt gate on the back edge
  let a: { x: number; z: number }, b: { x: number; z: number };
  const gate: [number, number][] = [];
  if (f === 1) { const tz = lot.z + lot.d + TRACK_GAP; a = { x: lot.x, z: tz }; b = { x: lot.x + W, z: tz }; for (let k = 0; k < W; k++) gate.push([lot.x + k, lot.z - 1]); }
  else if (f === 3) { const tz = lot.z - TRACK_GAP; a = { x: lot.x, z: tz }; b = { x: lot.x + W, z: tz }; for (let k = 0; k < W; k++) gate.push([lot.x + k, lot.z + lot.d]); }
  else if (f === 0) { const tx = lot.x + lot.w + TRACK_GAP; a = { x: tx, z: lot.z }; b = { x: tx, z: lot.z + W }; for (let k = 0; k < W; k++) gate.push([lot.x - 1, lot.z + k]); }
  else { const tx = lot.x - TRACK_GAP; a = { x: tx, z: lot.z }; b = { x: tx, z: lot.z + W }; for (let k = 0; k < W; k++) gate.push([lot.x + lot.w, lot.z + k]); }
  const ang = Math.atan2(b.z - a.z, b.x - a.x);
  const nx = -Math.sin(ang), nz = Math.cos(ang);
  const cx = lot.x + lot.w / 2, cz = lot.z + lot.d / 2;
  const side: 1 | -1 = nx * (cx - a.x) + nz * (cz - a.z) > 0 ? 1 : -1;
  return { lot, a, b, side, gate };
}

/** The tiles a station's pad would level: its lot and the strip under and beside the platform track. */
export function stationPad(kind: StationKind, x: number, z: number, f: number): number[] | null {
  const { lot, a, b } = stationLot(kind, x, z, f);
  const out = new Set<number>();
  for (let zz = lot.z; zz < lot.z + lot.d; zz++) for (let xx = lot.x; xx < lot.x + lot.w; xx++) { if (!inB(xx, zz)) return null; out.add(idx(xx, zz)); }
  const L = Math.hypot(b.x - a.x, b.z - a.z), n = Math.round(L / SAMPLE);
  const nx = -(b.z - a.z) / L, nz = (b.x - a.x) / L;
  for (let i = 0; i <= n; i++) {
    const px = a.x + ((b.x - a.x) * i) / n, pz = a.z + ((b.z - a.z) * i) / n;
    for (const o of [-0.5, 0, 0.5]) {
      const tx = Math.floor(px + nx * o), tz = Math.floor(pz + nz * o);
      if (!inB(tx, tz)) return null;
      out.add(idx(tx, tz));
    }
  }
  return [...out];
}

/** Why a station of this kind can't stand here, or null when it can. */
export function stationProblem(w: World, kind: StationKind, x: number, z: number, f: number): string | null {
  const pad = stationPad(kind, x, z, f);
  if (!pad) return 'Too close to the edge of the county';
  let lo = Infinity, hi = -Infinity;
  for (const t of pad) {
    const tx = t % N, tz = (t - tx) / N;
    if (tx < 2 || tz < 2 || tx >= N - 2 || tz >= N - 2) return 'Too close to the edge of the county';
    if (w.biome[t] === Biome.Ocean || waterDepth(w, t) > 0) return 'A station stands on dry ground';
    if (w.blocked[t] || (w.flags[t] & Flag.Poi)) return 'A building is in the way';
    if (w.road[t]) return 'A road is in the way';
    if (w.rail[t] & (RailBit.Track | RailBit.Pad | RailBit.Loop | RailBit.Deck | RailBit.Pier)) return 'The railway is in the way';
    lo = Math.min(lo, minCorner(w, t)); hi = Math.max(hi, maxCorner(w, t));
  }
  if (hi - lo > PAD_ROUGH) return 'Too uneven for a station: U to level it';
  const { gate } = stationLot(kind, x, z, f);
  if (!gate.some(([gx, gz]) => inB(gx, gz) && w.road[idx(gx, gz)] && !w.deckAxis[idx(gx, gz)])) return 'A station stands beside a road: its forecourt needs a street along the back of the lot (R turns it)';
  return null;
}

const SUFFIX: Record<StationKind, string> = { terminus: 'Terminus', cityStation: 'Central', townStation: 'Station', halt: 'Halt', goodsYard: 'Goods', harbourDepot: 'Depot' };

/** A name for a station here: after the nearest town (else the county), one not already taken. */
export function stationName(w: World, kind: StationKind, x: number, z: number): string {
  let base = w.name, bestD = Infinity;
  for (const t of w.towns) {
    const d = Math.hypot(t.x0 + t.size / 2 - x, t.z0 + t.size / 2 - z) - t.size / 2;
    if (d < 70 && d < bestD) { bestD = d; base = t.name; }
  }
  const taken = new Set(w.stations.map((s) => s.name));
  const first = `${base} ${SUFFIX[kind]}`;
  if (!taken.has(first)) return first;
  for (const sfx of ['North', 'South', 'East', 'West', 'Road', 'Bridge', 'Park']) if (!taken.has(`${base} ${sfx} ${SUFFIX[kind]}`)) return `${base} ${sfx} ${SUFFIX[kind]}`;
  return `${first} ${w.stations.length + 1}`;
}

/**
 * Put a station up: its pad levelled, its building on the lot, a straight platform track along the front
 * with buffers at both ends (a track laid from either end carries it on). Returns what was made and the
 * tiles that changed, or null with why.
 */
export function layStation(w: World, spec: StationSpec): { st: RailStation; path: RailPath; tiles: number[]; why?: undefined } | { st: null; path: null; tiles: []; why: string } {
  const why = stationProblem(w, spec.kind, spec.x, spec.z, spec.f);
  if (why) return { st: null, path: null, tiles: [], why };
  keep0(w);
  const { lot, a, b, side } = stationLot(spec.kind, spec.x, spec.z, spec.f);
  const pad = stationPad(spec.kind, spec.x, spec.z, spec.f)!;
  let sum = 0;
  for (const t of pad) for (let q = 0; q < 4; q++) sum += w.corners[t * 4 + q];
  const level = Math.round(sum / (pad.length * 4));
  for (const t of pad) {
    w.corners[t * 4] = w.corners[t * 4 + 1] = w.corners[t * 4 + 2] = w.corners[t * 4 + 3] = level;
    w.rail[t] |= RailBit.Pad;
    w.railAxis[t] = 0;
    w.cleared[t] = 1;
    if (w.water[t] >= 0 && w.water[t] <= level) w.water[t] = -1;
  }
  // the platform track: dead straight, on the pad's level
  const L = Math.hypot(b.x - a.x, b.z - a.z), n = Math.round(L / SAMPLE) + 1;
  const xz = new Float32Array(n * 2), y = new Float32Array(n), s = new Float32Array(n), under = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const f = i / (n - 1);
    xz[i * 2] = a.x + (b.x - a.x) * f; xz[i * 2 + 1] = a.z + (b.z - a.z) * f;
    y[i] = (level + RAIL_LIFT) * STEP;
    s[i] = L * f;
    under[i] = Under.Ground;
  }
  const id = w.rails.length;
  const path: RailPath = {
    id, key: `${BUILT_PREFIX}${w.cx},${w.cz}:${id}`, kind: 'main', era: spec.era, name: `${spec.nm} Line`,
    xz, y, s, under, length: L, start: { kind: 'stop' }, end: { kind: 'stop' },
  };
  const touched = new Set<number>(pad);
  mark(w, path, touched);
  for (const t of pad) { w.rail[t] |= RailBit.Pad; w.railAxis[t] = 0; }
  w.rails = [...w.rails, path];
  const era = spec.era === 'steam' ? 1 : spec.era === 'streamline' ? 2 : 3;
  const bld: Building = {
    kind: spec.kind, x: lot.x, z: lot.z, w: lot.w, d: lot.d, facing: lot.facing, floors: era,
    seed: spec.sd >>> 0, solid: true, level, uid: w.allBuildings.length,
  };
  w.allBuildings.push(bld);
  const top = level * STEP + buildingHeight(bld);
  const mask = solidMask(bld);
  for (let zz = lot.z; zz < lot.z + lot.d; zz++) for (let xx = lot.x; xx < lot.x + lot.w; xx++) {
    const i = idx(xx, zz);
    w.lot[i] = Lot.Plaza;
    if (mask[(zz - lot.z) * lot.w + xx - lot.x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  const town = w.townId[idx(lot.x, lot.z)];
  const st: RailStation = { kind: spec.kind, name: spec.nm, path: id, s0: 0, s1: L, loop: -1, side, era: spec.era, town: town >= 0 ? town : -1, building: bld };
  if (spec.by) path.by = st.by = spec.by;

  w.stations = [...w.stations, st];
  w.revision++;
  return { st, path, tiles: [...touched] };
}

/** Take the newest built station down again: its building, its platform track, its pad bits. Null when the newest path is not one. */
export function unlayLastStation(w: World): { st: RailStation; tiles: number[] } | null {
  const last = w.rails[w.rails.length - 1];
  const st = last && isBuiltRail(last) ? w.stations.find((q) => q.path === last.id) : undefined;
  if (!last || !st) return null;
  return { st, tiles: removeStation(w, st) };
}

/**
 * Take a built station down (the bulldozer): its building comes down where it stood (its slot in allBuildings
 * kept, marked gone, so every uid stays put), its platform track goes, and a track laid from either end of the
 * platform now ends at buffers there. The pad stays level. Returns the tiles to redraw; nothing for a generated station.
 */
export function removeStation(w: World, st: RailStation): number[] {
  const p = w.rails[st.path];
  if (!p || !isBuiltRail(p) || !w.stations.includes(st)) return [];
  const touched = new Set<number>(padTiles(w, st));
  const b = st.building;
  if (b) {
    b.gone = true;
    for (let zz = b.z; zz < b.z + b.d; zz++) for (let xx = b.x; xx < b.x + b.w; xx++) {
      const i = idx(xx, zz);
      w.blocked[i] = 0; w.roof[i] = 0; w.lot[i] = Lot.None; w.cleared[i] = 1;
      touched.add(i);
    }
  }
  w.stations = w.stations.filter((q) => q !== st);
  for (const t of removeRail(w, p)) touched.add(t);
  return [...touched];
}

/**
 * The built line under point (x, z) of the cell, for the bulldozer: the built path with a sample nearest the point
 * (within 0.75 of a tile), and the station whose platform it is, if any. Null over generated track or none.
 */
export function builtRailAt(w: World, x: number, z: number): { path: RailPath; station: RailStation | null } | null {
  let best: RailPath | null = null, bestD = 0.75;
  for (const p of w.rails) {
    if (!isBuiltRail(p)) continue;
    for (let i = 0; i < p.s.length; i++) {
      if (Math.abs(p.xz[i * 2] - x) > bestD || Math.abs(p.xz[i * 2 + 1] - z) > bestD) continue;
      const d = Math.hypot(p.xz[i * 2] - x, p.xz[i * 2 + 1] - z);
      if (d < bestD) { bestD = d; best = p; }
    }
  }
  if (!best) return null;
  const path = best;
  return { path, station: w.stations.find((st) => st.path === path.id) ?? null };
}
