import type { TownKind } from '../world/tiles';
import { CLASS_LABEL, URGENCY, type CargoType, type Urgency } from './cargoTypes';
import type { CargoItem, Site } from './cargo';
import { MODES, modeOf, rankIndex, type Driver } from './drivers';
import { canLoad, type CargoClass, type VehicleDef } from './vehicles';
import { affinity } from './affinity';
import type { RouteOrder } from './chains/routes';

/**
 * Orders: what kind of work a unit's driver looks for, and where. An order belongs to the unit, not
 * the driver, so the car keeps its job when the driver changes. It is a filter and a range; the
 * driver chooses the load, by the picker at the bottom of this file.
 */

export type PresetId = 'anything' | 'passengers' | 'portWork' | 'longHaul';
export type Range = 'island' | 'near' | 'anywhere';
export type Cross = 'yes' | 'no' | 'ports' | 'prefer';
/** How many loads a driver packs into one run: one at a time, as many as they have learned to, or one more than that. */
export type Pack = 'one' | 'some' | 'full';

/** Where a unit waits and goes back to when work dries up: a town or a harbour on its island. */
export interface Base {
  cx: number; cz: number;
  kind: 'town' | 'port';
  id: number;
  name: string;
  /** A stopping place there, in the cell's own tiles. */
  x: number; z: number;
  /** The town's kind (a harbour takes its town's, or rural), for the books' cap. */
  tkind: TownKind;
}

export interface Order {
  preset: PresetId | 'custom';
  /** Classes it may take; empty means every class the unit holds. */
  takes: CargoClass[];
  /** The lowest urgency it takes: 'none' takes everything. */
  floor: Urgency;
  /** Up to four cargo type ids, weighted up in the picker. */
  prefers: string[];
  range: Range;
  cross: Cross;
  base: Base | null;
  /**
   * The player picked this base (the vehicle's card or a town's Base here): the convoy leaves it be and the
   * vehicle works from it, wherever the HQ is. Without it the base is the one nearest the HQ (or where the
   * vehicle is), moved as the fleet moves (a player's report, 4 Nov 2026: a base set by hand kept changing).
   */
  chosen?: boolean;
  /** Stay at base, crewed, and take nothing. */
  wait: boolean;
  /** How full a hold the driver packs (docs/manifests.html). Missing in a save from before version 10, which reads as 'some'. */
  pack: Pack;
  /** A crewed train's beat (game/railBeat.ts, docs/crewtrains.html): where it works from, and two ends of the player's. */
  beat?: BeatOrder;
  /** A route (docs/supplychains.html, game/chains/routes.ts): a line or loop of doors it runs instead of looking for work. */
  route?: RouteOrder;
  /**
   * Fetching for a plant (docs/supplychains.html, "Fetching"): loads of these kinds weigh 2.5 times, and one it claims
   * is re-pointed to the plant's door. It does ordinary work in between.
   */
  fetch?: { key: string; ids: string[]; name: string };
}

/** How much more a fetcher wants a load of the kinds it is fetching. */
export const FETCH_WEIGHT = 2.5;

/** A station named the way a beat keeps it: its county and its name. */
export interface BeatEnd { cx: number; cz: number; name: string }
/** A crewed train's beat: the county it works from (the line within reach of it), and Custom's two ends. */
export interface BeatOrder { home: [number, number]; custom?: { a: BeatEnd; b: BeatEnd }; long?: boolean }

export const PRESET_LABEL: Record<PresetId, string> = { anything: 'Anything', passengers: 'Passengers', portWork: 'Port work', longHaul: 'Long haul' };
export const RANGE_LABEL: Record<Range, string> = { island: 'this island', near: 'this island and the next', anywhere: 'anywhere it can drive' };
export const CROSS_LABEL: Record<Cross, string> = { yes: 'may cross borders', no: 'stays in its cell', ports: 'port to port only', prefer: 'prefers crossings' };
export const PACK_LABEL: Record<Pack, string> = { one: 'one load', some: 'pack the hold', full: 'fill it' };

/** Loads a run carries at most in an ordinary hold, whoever is driving; a big hold adds holdLoads. */
const MOST_LOADS = 4;
/** Loads any run carries at most: MAX_STOPS / 2 in game/manifest.ts. */
const RUN_LOADS = 6;

/**
 * Loads a big hold packs on top of the rank's (Oct 2026): a rookie in a Tipper took one five-unit load at a
 * time and drove the other nine units empty. Twelve units or more is two more, twenty or more three more, past
 * MOST_LOADS too, up to RUN_LOADS.
 */
export const holdLoads = (capacity: number): number => (capacity >= 20 ? 3 : capacity >= 12 ? 2 : 0);

/**
 * How many loads this driver will juggle in one run. Rank is the ceiling — a rookie one, a regular two,
 * a veteran three, an ace four — and the cut's mode nudges it: Hustle packs one more, Coasting one fewer
 * (a coasting rookie still manages one). A big hold (`capacity`, its units) packs holdLoads more. The
 * order's dial caps it at one, leaves it, or asks for one more than the rank would; the hold does the rest.
 */
export function packOf(d: Driver, o: Order, capacity = 0): number {
  if (o.pack === 'one') return 1;
  const mode = modeOf(d.cut), big = holdLoads(capacity);
  let n = rankIndex(d) + 1 + (mode === 'hustle' ? 1 : mode === 'coasting' ? -1 : 0) + big;
  if (o.pack === 'full') n++;
  return Math.max(1, Math.min(MOST_LOADS + big, RUN_LOADS, n));
}

/** Urgencies from the most relaxed up: a floor takes its own step and everything above it. */
export const LADDER: Urgency[] = ['none', 'relaxed', 'standard', 'timely', 'urgent'];

/**
 * How many cells from home an order reaches. It decides which loads a driver may take, and — since
 * the fleet musters where the player is (game/convoy.ts) — how far the player may wander before this
 * unit packs up and follows: 'this island' comes when you cross one border, 'anywhere' tolerates two.
 */
export const reachOf = (r: Range): number => (r === 'island' ? 0 : r === 'near' ? 1 : 2);

export function preset(id: PresetId, base: Base | null): Order {
  switch (id) {
    case 'passengers': return { preset: id, takes: ['people'], floor: 'relaxed', prefers: ['commuters', 'patients'], range: 'island', cross: 'no', base, wait: false, pack: 'some' };
    case 'portWork': return { preset: id, takes: ['freight', 'bulk', 'container'], floor: 'none', prefers: ['container', 'fuel'], range: 'island', cross: 'ports', base, wait: false, pack: 'some' };
    case 'longHaul': return { preset: id, takes: [], floor: 'standard', prefers: [], range: 'anywhere', cross: 'prefer', base, wait: false, pack: 'some' };
    default: return { preset: 'anything', takes: [], floor: 'none', prefers: [], range: 'near', cross: 'yes', base, wait: false, pack: 'some' };
  }
}

/**
 * Which preset an order is, as the pane lights its pill: the one whose filter it matches (what it takes for this
 * vehicle, its floor, preferred types, range and borders), the preset it came from first; 'custom' when it has
 * been edited away from all of them. Its base, packing and Wait are not what a preset is about.
 */
export function presetOf(o: Order, def: VehicleDef): PresetId | 'custom' {
  const takes = (x: CargoClass[]) => def.holds.filter((c) => !x.length || x.includes(c)).join();
  const types = (x: string[]) => [...x].sort().join();
  const same = (id: PresetId) => {
    const p = preset(id, null);
    return takes(p.takes) === takes(o.takes) && p.floor === o.floor && p.range === o.range && p.cross === o.cross && types(p.prefers) === types(o.prefers);
  };
  if (o.preset !== 'custom' && same(o.preset)) return o.preset;
  return (Object.keys(PRESET_LABEL) as PresetId[]).find(same) ?? 'custom';
}

/** A short line for the pane: "Takes: people ✓ parcels ✓ · at least Relaxed · prefers commuters". */
export function orderLine(o: Order, def: VehicleDef): string {
  const takes = def.holds.map((c) => `${CLASS_LABEL[c]} ${o.takes.length === 0 || o.takes.includes(c) ? '✓' : '✗'}`).join(' ');
  const floor = o.floor === 'none' ? 'any limit' : `at least ${URGENCY[o.floor].label}`;
  const pack = o.pack && o.pack !== 'some' ? ` · ${PACK_LABEL[o.pack]}` : '';
  return `Takes: ${takes} · ${floor}${o.prefers.length ? ` · prefers ${o.prefers.join(', ')}` : ''}${pack}`;
}

/** Counties apart, a diagonal neighbour one away: the same measure the convoy keeps a unit's reach by (game/convoy.ts). */
const cheb = (a: { cx: number; cz: number }, b: { cx: number; cz: number }): number => Math.max(Math.abs(a.cx - b.cx), Math.abs(a.cz - b.cz));

/** Does the order allow this load at all (ignoring whether the unit can reach it)? */
export function allows(o: Order, driver: Driver, def: VehicleDef, it: CargoItem, home: { cx: number; cz: number }): boolean {
  if (o.wait) return false;
  if (o.takes.length && !o.takes.includes(it.type.cls)) return false;
  if (LADDER.indexOf(it.urgency) < LADDER.indexOf(o.floor)) return false;
  const mode = MODES[modeOf(driver.cut)];
  if (mode.takes && !mode.takes.includes(it.urgency)) return false;
  const reach = reachOf(o.range);
  if (cheb(it.w, home) > reach || cheb(it.to.w, home) > reach) return false;
  const crossing = it.to.w !== it.w;
  if (crossing && o.cross === 'no') return false;
  if (crossing && o.cross === 'ports' && !(it.to.port >= 0 && it.from && it.from.port >= 0)) return false;
  // the Barnstormer never stops, so it can never load; a jet flies the air service, never a driver's run (game/jetPilots.ts)
  if (!canLoad(def)) return false;
  return true;
}

/**
 * What a hired jet's order lets it fly (game/cargo.ts jetReserve; the user, 4 Nov 2026: a cargo plane's pilot on
 * Long haul flew whatever came, as every jet did, its order never read). The road order read for the air service:
 * Wait takes nothing; Takes, the floor and the cut's mode as on the road; Range counts counties between the two
 * airports (Anywhere is as far as a jet's work goes); Stays in its cell keeps it to its own county (port to port
 * is any airport); preferred types weigh half again and, for an order that prefers crossings, another county twice,
 * in choosing where it flies. Long haul (`far`) also takes gold long-haul work, five counties or more off.
 */
export interface JetWant {
  /** Wait: no work at all. */
  none: boolean;
  /** Long haul: gold long-haul work first (game/cargo.ts jetFar). */
  far: boolean;
  /** Does it carry this kind at all (Takes)? */
  kind(t: CargoType): boolean;
  /** May it fly this, at this urgency, between these two places? */
  ok(t: CargoType, urgency: Urgency, from: Site, to: Site): boolean;
  /** How much the order wants it, times its value, in choosing which place's loads it flies. */
  weight(t: CargoType, from: Site, to: Site): number;
}

export function jetWant(o: Order, driver: Driver, def: VehicleDef): JetWant {
  const mode = MODES[modeOf(driver.cut)];
  const reach = o.range === 'anywhere' ? Infinity : reachOf(o.range);
  const kind = (t: CargoType) => !o.takes.length || o.takes.includes(t.cls);
  return {
    none: o.wait,
    far: presetOf(o, def) === 'longHaul',
    kind,
    ok: (t, urgency, from, to) => {
      if (!kind(t)) return false;
      if (LADDER.indexOf(urgency) < LADDER.indexOf(o.floor)) return false;
      if (mode.takes && !mode.takes.includes(urgency)) return false;
      const apart = cheb(from.w, to.w);
      return apart <= reach && !(apart > 0 && o.cross === 'no');
    },
    weight: (t, from, to) => (o.prefers.includes(t.id) ? 1.5 : 1) * (o.cross === 'prefer' && to.w !== from.w ? 2 : 1) * affinity(def, t),
  };
}

/** Tiles of drive to the goods cost this much of the score, so a near load beats a slightly richer far one. */
const DRIVE_COST = 0.8;
/** Loads the picker looks over, before rank adds a quarter more per step. */
const CONSIDER = 8;
/**
 * Loads it looks over besides, past the nearest, that the order asks for by name (a preferred type, or a
 * crossing for an order that prefers them): the nearest-first cut used to leave them out before the
 * preference could count, so Prefers did next to nothing (a player's report, 4 Nov 2026).
 */
const CONSIDER_WANTED = 6;

/**
 * Score every open job this unit may haul and return them best first. The score is the expected net
 * to you after tax, times the urgency fit for the cut's mode, 1.5 for a preferred type, 1.1 for the
 * driver's nose and 2 for a crossing a Long haul prefers, less a cost for the drive to the goods.
 */
export function pickJobs(
  o: Order, driver: Driver, def: VehicleDef, jobs: CargoItem[], at: { x: number; z: number },
  home: { cx: number; cz: number }, taxOf: (it: CargoItem) => number, canHaul: (d: VehicleDef, it: CargoItem) => boolean,
): CargoItem[] {
  const mode = MODES[modeOf(driver.cut)];
  const near = jobs.filter((it) => canHaul(def, it) && allows(o, driver, def, it, home))
    .sort((a, b) => Math.hypot(a.x - at.x, a.z - at.z) - Math.hypot(b.x - at.x, b.z - at.z));
  const n = Math.round(CONSIDER * (1 + 0.25 * rankIndex(driver)));
  const wanted = (it: CargoItem) => o.prefers.includes(it.type.id) || (o.cross === 'prefer' && it.to.w !== it.w) || !!o.fetch?.ids.includes(it.type.id);
  const pool = [...near.slice(0, n), ...(o.prefers.length || o.cross === 'prefer' || o.fetch ? near.slice(n).filter(wanted).slice(0, CONSIDER_WANTED) : [])];
  const score = (it: CargoItem) => {
    const gross = it.value * (driver.nose === it.type.cls ? 1.1 : 1);
    let s = (gross - gross * taxOf(it)) * driver.cut;
    if (it.urgency === 'urgent' || it.urgency === 'timely') s *= mode.urgentFit;
    // what this vehicle is for (game/affinity.ts): a limousine goes for the wedding and a coach for the
    // school trip, whoever is driving and whether or not anybody is watching
    s *= affinity(def, it.type);
    if (o.prefers.includes(it.type.id)) s *= 1.5;
    // fetching for one of the fleet's plants (docs/supplychains.html): its inputs first
    if (o.fetch?.ids.includes(it.type.id)) s *= FETCH_WEIGHT;
    if (driver.nose === it.type.cls) s *= 1.1;
    if (o.cross === 'prefer' && it.to.w !== it.w) s *= 2;
    return s - DRIVE_COST * Math.hypot(it.x - at.x, it.z - at.z) * driver.cut;
  };
  return pool.map((it) => ({ it, s: score(it) })).sort((a, b) => b.s - a.s).map((e) => e.it);
}
