/**
 * The loading screen: one of the game's showpieces turning on a lit platform, zapped off to the left every
 * few seconds as the next zaps in from the right, over a real percentage of the world being made.
 *
 * Its own small renderer on its own canvas, made the first time a world loads and kept for the next; the
 * models come from the hero stage's builder (render/heroStage.ts), so a vehicle is the game's own mesh and a
 * landmark is drawn by the town mesher in its home style. Each is built while the one before it is still
 * turning, so the build's few milliseconds never land on a zap.
 */
import * as THREE from 'three';
import { hero } from './heroStage';
import { KIND_SPEC } from '../world/townKinds';
import type { HeroSpec } from '../game/missions/model';
import type { Arch, BuildingKind } from '../world/tiles';
import { badgeHtml, type FleetBrand } from '../game/brand';
import { FirstRoad, type RoadLessons } from './firstRoad';
import type { Input } from '../game/input';

interface Pick { spec: HeroSpec; name: string; tag: string }

const top = (v: number | [number, number] | undefined, d: number): number => (v === undefined ? d : typeof v === 'number' ? v : v[1]);
const ride = (model: string, name: string, tag: string): Pick => ({ spec: { kind: 'vehicle', model }, name, tag });
/** A landmark at the biggest size its town would give it, or the size given (the wonders stand outside towns). */
const sight = (b: BuildingKind, arch: Arch, name: string, tag: string, size?: [number, number, number]): Pick => {
  const k = KIND_SPEC[b] as { w?: number | [number, number]; d?: number | [number, number]; floors?: number | [number, number] } | undefined;
  const [w, d, floors] = size ?? [top(k?.w, 3), top(k?.d, 3), top(k?.floors, 3)];
  return { spec: { kind: 'building', b, arch, w, d, floors }, name, tag };
};

/** The showpieces: the biggest, oddest and shiniest things in the game (each checked to read well at this size). */
const PICKS: Pick[] = [
  ride('jumbo', 'Jumbo', 'Jet airliner'),
  ride('carrier', 'Bastion', 'Aircraft carrier'),
  ride('submarine', 'Leviathan', 'Submarine'),
  ride('galleon', 'Sea Lion', 'Galleon'),
  ride('tank', 'Tortoise', 'Tank'),
  ride('chinook', 'Bumblebee', 'Twin-rotor helicopter'),
  ride('riverboat', 'Delta Belle', 'Paddle steamer'),
  ride('wasabi', 'Wasabi', 'Sports car'),
  ride('fighter', 'Stinger', 'Fighter jet'),
  ride('kettle', 'The Kettle', 'Steam locomotive'),
  ride('workhorse', 'The Workhorse', 'Diesel locomotive'),
  ride('yacht', 'Serenade', 'Superyacht'),
  ride('hover', 'Skimmer', 'Hovercraft'),
  ride('wrecker', 'Hooky', 'Tow truck'),
  ride('sunny', 'Sunny', 'Convertible'),
  ride('airboat', 'Gator', 'Airboat'),
  ride('humvee', 'Badger', 'Off-roader'),
  sight('eiffelTower', 'paris', 'Eiffel Tower', 'Paris landmark'),
  sight('sphereTheatre', 'vegas', 'The Sphere', 'Las Vegas landmark'),
  sight('tajMahal', 'mughal', 'Taj Mahal', 'Mughal landmark'),
  sight('statueLiberty', 'newyork', 'Statue of Liberty', 'New York landmark'),
  sight('colosseum', 'roman', 'Colosseum', 'Roman landmark'),
  sight('bigBen', 'london', 'Big Ben', 'London landmark'),
  sight('whiteCitadel', 'whitecity', 'White Citadel', 'White City landmark'),
  sight('sailHotel', 'dubai', 'Sail Hotel', 'Dubai landmark'),
  sight('osakaCastle', 'osaka', 'Osaka Castle', 'Osaka landmark'),
  sight('skyDock', 'steampunk', 'Sky Dock', 'Steampunk landmark'),
  sight('stPeters', 'roman', "St Peter's", 'Roman landmark'),
  sight('machuPicchu', 'andean', 'Machu Picchu', 'Andean landmark'),
  sight('fairground', 'classic', 'Fairground', 'Theme park'),
];

/** A percentage held this long (ms) is nudged up by one, never past NUDGE_MAX (LoadingShow.tickPercent). */
const NUDGE_MS = 5000, NUDGE_MAX = 99;
/** Seconds each showpiece turns before the next zaps it away. */
const HOLD = 4.2;
const OUT = 0.34, IN = 0.55, IN_AT = 0.12;
/** How wide (across its turning circle) and how tall a showpiece is made, in scene units. */
const FIT_W = 3.3, FIT_H = 3.5;
/** The platform's radius, and the height the camera looks at (the platform sits below the middle, the showpiece over it). */
const DECK_R = 1.95, LOOK_Y = 0.95;
const FOV = 30;
/** The game's red: the title's full stop, the rings, the bar. */
const RED = 0xe2412f;

interface Shown { pick: Pick; zap: THREE.Group; spin: THREE.Group; dispose(): void }

class LoadingShow {
  private el = document.getElementById('loading')!;
  private canvas = this.el.querySelector<HTMLCanvasElement>('.ld-canvas')!;
  private seedEl = document.getElementById('loading-seed')!;
  private pctEl = this.el.querySelector<HTMLElement>('.ld-pct')!;
  private labelEl = this.el.querySelector<HTMLElement>('.ld-label')!;
  private barEl = this.el.querySelector<HTMLElement>('.ld-bar i')!;
  private capEl = this.el.querySelector<HTMLElement>('.ld-cap')!;
  private tagEl = this.el.querySelector<HTMLElement>('.ld-tag')!;
  private nameEl = this.el.querySelector<HTMLElement>('.ld-name')!;
  private skipEl = this.el.querySelector<HTMLButtonElement>('.ld-skip')!;
  /**
   * What stands over the bar: the turntable of showpieces, or for a brand-new player the first road (render/firstRoad.ts,
   * docs/firstroad.html), one lit road in a black void that teaches the keys while the world is made.
   */
  private mode: 'show' | 'road' = 'show';
  private road: FirstRoad | null = null;
  /** What the last first road taught, kept after it is put away (the handover and the play reports read it). */
  private lastLessons: RoadLessons | null = null;
  /** The game's keys, for the first road's car (main.ts sets it). */
  keys: Input | null = null;
  /**
   * The world is made but the first road is still up (the user, 8 Nov 2026): the bar gives way to a Skip controls
   * tutorial button, and the screen stays until that is pressed or the car drives over the road's finish line.
   */
  private waitingRoad = false;
  /** Told what the first road taught as it is put away (main.ts: the camera card is skipped if the camera was learned). */
  onRoadEnd: ((l: RoadLessons) => void) | null = null;
  private renderer: THREE.WebGLRenderer | null = null;
  private scene = new THREE.Scene();
  private cam = new THREE.PerspectiveCamera(FOV, 1, 0.1, 200);
  private deck = new THREE.Group();
  private rings: THREE.Mesh[] = [];
  private wave: THREE.Mesh;
  private glow: THREE.Mesh;
  private sky = new THREE.HemisphereLight(0xffffff, 0x8a8f94, 1.3);
  private key = new THREE.DirectionalLight(0xfff3dc, 2.4);
  private fill = new THREE.DirectionalLight(0xffffff, 0.8);
  private drumMat = new THREE.MeshStandardMaterial({ metalness: 0.3, roughness: 0.45 });
  private faceMat = new THREE.MeshBasicMaterial({ transparent: true });
  /** Which UI theme the platform is painted for (game/theme.ts's body.dark-ui), or null before the first paint. */
  private dark: boolean | null = null;
  private raf = 0;
  private last = 0;
  private calm = typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;
  /** The order the showpieces come in this time, and where in it we are. */
  private order: number[] = [];
  private at = 0;
  private cur: Shown | null = null;
  private next: Shown | null = null;
  private leaving: Shown | null = null;
  /** Seconds since the current one landed; and since the zap began (or -1 when none is under way). */
  private held = 0;
  private zapT = -1;
  private flash = 0;
  private shake = 0;
  private t = 0;
  // the percentage: a floor the work has reached, a ceiling it is working toward, and the number shown
  private base = 0;
  private ceil = 0;
  private sinceStep = 0;
  private shown = 0;
  /** The whole number last shown, and when it last went up (performance.now ms): the nudge's clock. */
  private lastPct = -1;
  private pctAt = 0;
  private closing = false;
  private hideTimer = 0;
  private failsafe = 0;

  constructor() {
    this.scene.add(this.sky);
    this.key.position.set(4, 7, 6);
    this.fill.position.set(-7, 3, -2);
    this.scene.add(this.key, this.fill);
    // the platform: a drum with a dial on its face, red rings round its rim and a pool of light (or shade) on the floor
    const drum = new THREE.Mesh(new THREE.CylinderGeometry(DECK_R * 0.98, DECK_R * 1.06, 0.36, 72), this.drumMat);
    drum.position.y = -0.18;
    const face = new THREE.Mesh(new THREE.CircleGeometry(DECK_R * 0.96, 72), this.faceMat);
    face.rotation.x = -Math.PI / 2;
    face.position.y = 0.005;
    this.deck.add(drum, face);
    for (const [r, y, tube] of [[DECK_R, 0, 0.03], [DECK_R * 1.07, -0.34, 0.022]] as const) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(r, tube, 8, 96), new THREE.MeshBasicMaterial({ color: RED, toneMapped: false }));
      ring.rotation.x = Math.PI / 2;
      ring.position.y = y;
      this.rings.push(ring);
      this.deck.add(ring);
    }
    this.glow = new THREE.Mesh(new THREE.PlaneGeometry(DECK_R * 3.8, DECK_R * 3.8), new THREE.MeshBasicMaterial({ transparent: true, depthWrite: false, toneMapped: false }));
    this.glow.rotation.x = -Math.PI / 2;
    this.glow.position.y = -0.37;
    this.wave = new THREE.Mesh(new THREE.RingGeometry(0.92, 1, 96), new THREE.MeshBasicMaterial({ color: RED, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide, toneMapped: false }));
    this.wave.rotation.x = -Math.PI / 2;
    this.wave.position.y = 0.02;
    this.paint(document.body.classList.contains('dark-ui'));
    this.scene.add(this.deck, this.glow, this.wave);
    this.skipEl.addEventListener('click', () => this.close());
    // the page comes up with the screen already showing (index.html), before the game has asked for it
    if (!this.el.hidden) this.start();
  }

  get open(): boolean { return !this.el.hidden && !this.closing; }
  /** The world is in and waiting on the first road's player (Skip or the finish line): main.ts draws nothing under it. */
  get waiting(): boolean { return this.waitingRoad && !this.closing && !this.el.hidden; }
  /** The first road is up: its keys are the road's, not the game's (main.ts holds the car and the camera keys). */
  get roadUp(): boolean { return this.mode === 'road' && !this.el.hidden; }
  /** What the first road taught this load (or the last one), or null when there was none. */
  lessons(): RoadLessons | null { return this.road ? this.road.lessons() : this.lastLessons; }
  /** For the console: pr.firstRoad. */
  get roadState(): object | null { return this.road ? this.road.state : null; }

  /** Up over everything, naming the fleet whose world it is (never the seed); nothing when there is none yet. */
  show(brand: FleetBrand | null, mode: 'show' | 'road' = 'show'): void {
    this.seedEl.textContent = '';
    this.seedEl.classList.toggle('fleet', !!brand);
    if (brand) { this.seedEl.innerHTML = badgeHtml(brand, 22); this.seedEl.append(brand.name); }
    clearTimeout(this.hideTimer);
    clearTimeout(this.failsafe);
    this.hideTimer = 0;
    this.el.classList.remove('ld-out');
    if (this.el.hidden || this.closing) {
      // a fresh screen counts from nothing; one already up (a world asked for again) carries on from where it was
      if (this.el.hidden) { this.base = this.ceil = this.shown = 0; this.sinceStep = 0; this.lastPct = -1; this.label('Unpacking the toy box'); }
      this.closing = false;
      this.el.hidden = false;
      this.start();
    }
    this.setWaiting(false);
    this.setMode(mode);
  }

  /** The turntable or the first road over the bar; a road already up (a world asked for again) carries on. */
  private setMode(mode: 'show' | 'road'): void {
    if (mode === 'road' && !this.road) {
      this.road = new FirstRoad(this.capEl, this.el);
      // the sign-up card's PIN field may still have the focus: the keys are the car's now
      (document.activeElement as HTMLElement | null)?.blur?.();
    } else if (mode === 'show') this.endRoad();
    this.mode = mode;
    this.el.classList.toggle('road', mode === 'road');
  }

  /** The first road put away: what it taught is kept, and the caption is the turntable's again. */
  private endRoad(): void {
    if (!this.road) return;
    this.lastLessons = this.road.lessons();
    this.setWaiting(false);
    this.onRoadEnd?.(this.lastLessons);
    this.road.dispose();
    this.road = null;
    this.capEl.classList.remove('in', 'out');
    this.capEl.innerHTML = '<span class="ld-tag"></span><span class="ld-name"></span>';
    this.tagEl = this.capEl.querySelector<HTMLElement>('.ld-tag')!;
    this.nameEl = this.capEl.querySelector<HTMLElement>('.ld-name')!;
    this.el.classList.remove('road');
    this.mode = 'show';
  }

  /**
   * The work has reached `p` percent and is on its way to `toward` (the next step's start): the number shown
   * eases up to `p` and then creeps on toward `toward`, so a long step never looks stuck. Never goes back.
   */
  progress(p: number, label?: string, toward = p): void {
    if (p > this.base) { this.base = Math.min(100, p); this.sinceStep = 0; }
    this.ceil = Math.max(this.base, Math.min(100, toward));
    if (label) this.label(label);
  }

  /**
   * All done: the bar runs to 100 and the screen fades away. Over the first road it waits instead, the bar swapped for
   * the Skip button, until that or the finish line closes it.
   */
  finish(): void {
    if (this.el.hidden) return;
    this.progress(100, 'Ready!');
    if (this.road && !this.closing) {
      this.setWaiting(true);
      this.road.ready = true;
      return;
    }
    this.close();
  }

  /** The Skip button in place of the bar, or the bar back. */
  private setWaiting(on: boolean): void {
    this.waitingRoad = on;
    this.el.classList.toggle('ld-ready', on);
    this.skipEl.hidden = !on;
  }

  /** The screen fades away (after the bar has run to the end). */
  private close(): void {
    if (this.el.hidden || this.closing) return;
    this.setWaiting(false);
    this.progress(100, 'Ready!');
    this.closing = true;
    // the fade waits on the bar, which is drawn in frames: a page drawing none (a hidden tab) is let go anyway
    clearTimeout(this.failsafe);
    this.failsafe = window.setTimeout(() => { if (this.closing) this.hide(); }, 2500);
  }

  /** Gone at once, nothing finished (a guest view that couldn't connect). */
  hide(): void {
    clearTimeout(this.failsafe);
    this.el.classList.remove('ld-out');
    this.closing = false;
    this.el.hidden = true;
    this.endRoad();
    this.stop();
  }

  /** The platform in the UI's colours: pale with a soft shadow under it in light, charcoal over a faint glow in dark. */
  private paint(dark: boolean): void {
    if (this.dark === dark) return;
    this.dark = dark;
    this.drumMat.color.setHex(dark ? 0x2b2f35 : 0xf2f3f1);
    this.faceMat.map?.dispose();
    this.faceMat.map = dialTexture(dark);
    this.faceMat.needsUpdate = true;
    this.sky.groundColor.setHex(dark ? 0x30343a : 0x9aa0a4);
    this.fill.intensity = dark ? 0.6 : 0.9;
    const g = this.glow.material as THREE.MeshBasicMaterial;
    g.map?.dispose();
    g.map = floorTexture(dark);
    g.blending = dark ? THREE.AdditiveBlending : THREE.NormalBlending;
    g.needsUpdate = true;
  }

  private label(s: string): void { if (this.labelEl.textContent !== s) this.labelEl.textContent = s; }

  private start(): void {
    if (this.raf) return;
    if (!this.order.length) this.order = shuffled(PICKS.length);
    this.last = performance.now();
    const tick = (now: number) => {
      this.raf = requestAnimationFrame(tick);
      const raw = (now - this.last) / 1000;
      this.last = now;
      this.frame(Math.min(0.1, raw), raw);
    };
    this.raf = requestAnimationFrame(tick);
  }

  private stop(): void {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
  }

  private ensure(): THREE.WebGLRenderer | null {
    if (this.renderer) return this.renderer;
    try {
      this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true, powerPreference: 'high-performance' });
    } catch { return null; } // no WebGL to spare: the screen is the bar alone
    this.renderer.setPixelRatio(Math.min(1.5, window.devicePixelRatio || 1));
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.toneMapping = THREE.NeutralToneMapping;
    this.renderer.toneMappingExposure = 1.1;
    return this.renderer;
  }

  /** `raw` is the whole of the time since the last frame: the road's car drives through a stall rather than pausing in it. */
  private frame(dt: number, raw = dt): void {
    this.t += dt;
    this.paint(document.body.classList.contains('dark-ui'));
    this.tickPercent(dt);
    const r = this.ensure();
    if (r) {
      const W = this.canvas.clientWidth, H = this.canvas.clientHeight;
      if (this.road) {
        this.road.frame(Math.min(1, raw), this.keys, W && H ? W / H : 1);
        // over the finish line, the world made: the screen goes
        if (this.road.crossed && this.waitingRoad) this.close();
        if (W && H) {
          const size = r.getSize(new THREE.Vector2());
          if (size.x !== W || size.y !== H) r.setSize(W, H, false);
          r.render(this.road.scene, this.road.cam);
        }
      } else {
        this.stage(dt);
        if (W && H) {
          const size = r.getSize(new THREE.Vector2());
          if (size.x !== W || size.y !== H) r.setSize(W, H, false);
          this.aim(W / H);
          r.render(this.scene, this.cam);
        }
      }
    }
    // the bar has reached the end: fade out, then stop drawing
    if (this.closing && this.shown >= 99.5 && !this.hideTimer) {
      this.el.classList.add('ld-out');
      this.hideTimer = window.setTimeout(() => {
        this.hideTimer = 0;
        if (!this.closing) return;
        this.closing = false;
        this.el.hidden = true;
        this.el.classList.remove('ld-out');
        this.endRoad();
        this.stop();
      }, 420);
    }
  }

  private tickPercent(dt: number): void {
    this.sinceStep += dt;
    // creep toward the ceiling, quick at first and slower the nearer it gets; the number shown never goes back
    const target = this.base + (this.ceil - this.base) * (1 - Math.exp(-this.sinceStep / 5));
    this.shown = Math.max(this.shown, this.shown + (target - this.shown) * Math.min(1, dt * (this.closing ? 9 : 4)));
    if (target - this.shown < 0.05 && target > this.shown) this.shown = target;
    // never stuck: a whole number held NUDGE_MS (a long step creeping up on its ceiling, 51% for half a minute on a
    // slow machine) goes up by one, every NUDGE_MS on the clock, up to 99; the work's own figure wins once it's
    // higher, and only finishing shows 100 (the user, 6 Nov 2026)
    const now = performance.now();
    if (Math.floor(this.shown + 0.001) !== this.lastPct) { this.lastPct = Math.floor(this.shown + 0.001); this.pctAt = now; }
    else if (!this.closing && now - this.pctAt >= NUDGE_MS && this.lastPct < NUDGE_MAX) {
      const steps = Math.min(NUDGE_MAX - this.lastPct, Math.floor((now - this.pctAt) / NUDGE_MS));
      this.shown = this.lastPct + steps;
      this.lastPct = Math.floor(this.shown + 0.001);
      this.pctAt += steps * NUDGE_MS;
    }
    const n = Math.min(100, Math.floor(this.shown + 0.001));
    const s = `${n}%`;
    if (this.pctEl.textContent !== s) this.pctEl.textContent = s;
    this.barEl.style.transform = `scaleX(${(this.shown / 100).toFixed(4)})`;
  }

  /** The camera back far enough that the platform and a zap's run-up fit however narrow the screen. */
  private aim(aspect: number): void {
    const tan = Math.tan(THREE.MathUtils.degToRad(FOV / 2));
    const dist = Math.max(13.5, 2.7 / (tan * aspect));
    const sh = this.calm ? 0 : this.shake;
    this.cam.aspect = aspect;
    this.cam.position.set(Math.sin(this.t * 61) * sh * 0.12, LOOK_Y + dist * 0.2 + Math.cos(this.t * 53) * sh * 0.08, dist);
    this.cam.lookAt(0, LOOK_Y, 0);
    this.cam.updateProjectionMatrix();
  }

  /** How far off to the side a zapped showpiece goes: well clear of the edge of the picture. */
  private offX(): number {
    const tan = Math.tan(THREE.MathUtils.degToRad(FOV / 2));
    return this.cam.position.z * tan * this.cam.aspect + FIT_W;
  }

  private stage(dt: number): void {
    // the first showpiece lands as the screen comes up
    if (!this.cur && !this.leaving && this.zapT < 0) {
      this.next ??= this.make();
      if (this.next) this.beginZap();
    }
    if (this.cur && this.zapT < 0) {
      this.held += dt;
      // the next one is built a moment after this one landed, while it turns
      if (!this.next && this.held > 0.8) this.next = this.make();
      if (this.held >= HOLD && this.next) this.beginZap();
    }
    if (this.zapT >= 0) this.zapping(dt);
    // everything on the platform turns; the platform's dial and rings turn with it
    const spin = dt * (this.calm ? 0.25 : 0.55);
    if (this.cur) this.cur.spin.rotation.y += spin;
    if (this.leaving) this.leaving.spin.rotation.y += spin * 3;
    this.deck.rotation.y += spin;
    if (this.cur && this.zapT < 0) this.cur.zap.position.y = Math.sin(this.t * 1.6) * 0.04;
    // the landing's flash: the rings flare, the shockwave runs out over the floor, the camera shudders
    this.flash = Math.max(0, this.flash - dt * 2.2);
    this.shake = Math.max(0, this.shake - dt * 4);
    const pulse = 0.5 + 0.5 * Math.sin(this.t * 3);
    for (const ring of this.rings) (ring.material as THREE.MeshBasicMaterial).color.setHex(RED).multiplyScalar(0.85 + 0.25 * pulse + this.flash * 0.9);
    (this.glow.material as THREE.MeshBasicMaterial).opacity = this.dark ? 0.6 + 0.2 * pulse + this.flash * 0.5 : 0.85;
    const w = 1 - this.flash;
    this.wave.scale.setScalar(DECK_R + w * DECK_R * 1.9);
    (this.wave.material as THREE.MeshBasicMaterial).opacity = this.flash * 0.7;
  }

  private beginZap(): void {
    this.leaving = this.cur;
    this.cur = this.next;
    this.next = null;
    this.zapT = 0;
    this.held = 0;
    if (this.cur) { this.cur.zap.position.set(this.offX(), 0, 0); this.cur.zap.visible = true; this.scene.add(this.cur.zap); }
    // the caption goes out with the old one and comes back with the new
    if (this.leaving) {
      this.capEl.classList.remove('in');
      this.capEl.classList.add('out');
      this.el.classList.remove('zap');
      void this.el.offsetWidth; // restart the streaks' animation
      this.el.classList.add('zap');
    }
    window.setTimeout(() => {
      if (!this.cur) return;
      this.tagEl.textContent = this.cur.pick.tag;
      this.nameEl.textContent = this.cur.pick.name;
      this.capEl.classList.remove('out');
      this.capEl.classList.add('in');
    }, this.leaving ? 260 : 0);
  }

  private zapping(dt: number): void {
    this.zapT += dt;
    const t = this.zapT, off = this.offX();
    const old = this.leaving;
    if (old) {
      const k = Math.min(1, t / OUT), e = k * k * k;
      old.zap.position.x = -off * e;
      // stretched along the way it is going, a cartoon's speed lines in the model itself
      old.zap.scale.set(1 + e * 1.6, 1 - e * 0.3, 1);
      if (k >= 1) { this.scene.remove(old.zap); old.dispose(); this.leaving = null; }
    }
    const cur = this.cur;
    if (cur) {
      const k = Math.min(1, Math.max(0, (t - (old ? IN_AT : 0)) / IN));
      const e = backOut(k);
      cur.zap.position.x = off * (1 - e);
      const s = Math.max(0, 1 - k * 1.6);
      cur.zap.scale.set(1 + s * 1.3, 1 - s * 0.25, 1);
      cur.zap.position.y = 0;
      if (k >= 1 && !this.leaving) { this.zapT = -1; this.flash = 1; this.shake = 1; cur.zap.scale.set(1, 1, 1); cur.zap.position.x = 0; }
    } else if (!this.leaving) this.zapT = -1;
  }

  /** Build the next showpiece in the order, skipping any that won't build or build to nothing. */
  private make(): Shown | null {
    for (let tries = 0; tries < PICKS.length; tries++) {
      const pick = PICKS[this.order[this.at % this.order.length]];
      this.at++;
      if (this.at % this.order.length === 0) this.order = shuffled(PICKS.length, this.order[this.order.length - 1]);
      try {
        const built = hero.build(pick.spec);
        const obj = built.obj;
        obj.updateMatrixWorld(true);
        const all = new THREE.Box3().setFromObject(obj);
        // a landmark comes on its own patch of ground: framed by its footprint, as tall as it really stands
        const box = built.frame ? built.frame.clone() : all.clone();
        if (built.frame) box.max.y = Math.max(box.min.y + 0.2, all.max.y);
        const size = box.getSize(new THREE.Vector3()), centre = box.getCenter(new THREE.Vector3());
        if (box.isEmpty() || !(size.x > 0.01) || !(size.y > 0.01)) { built.dispose(); continue; }
        const s = Math.min(FIT_W / Math.hypot(size.x, size.z), FIT_H / size.y);
        const fit = new THREE.Group();
        fit.add(obj);
        obj.position.set(-centre.x, -box.min.y, -centre.z);
        fit.scale.setScalar(s);
        const spin = new THREE.Group();
        spin.add(fit);
        spin.rotation.y = -0.6;
        const zap = new THREE.Group();
        zap.add(spin);
        zap.visible = false;
        return { pick, zap, spin, dispose: () => built.dispose() };
      } catch { /* a showpiece that can't be built here is skipped */ }
    }
    return null;
  }
}

/** Every showpiece once in a random order, rides and landmarks taking turns, not starting with `not` (the last one shown). */
function shuffled(n: number, not = -1): number[] {
  const mix = (a: number[]) => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const all = [...Array(n).keys()];
  const rides = mix(all.filter((i) => PICKS[i].spec.kind === 'vehicle')), sights = mix(all.filter((i) => PICKS[i].spec.kind !== 'vehicle'));
  const first = Math.random() < 0.5 ? rides : sights, second = first === rides ? sights : rides;
  const out: number[] = [];
  for (let i = 0; i < Math.max(rides.length, sights.length); i++) {
    if (i < first.length) out.push(first[i]);
    if (i < second.length) out.push(second[i]);
  }
  if (out[0] === not && n > 1) [out[0], out[1]] = [out[1], out[0]];
  return out;
}

/** Ease out with a little overshoot: the showpiece skids past its mark and settles back. */
function backOut(k: number): number {
  const c = 1.9;
  return 1 + (c + 1) * Math.pow(k - 1, 3) + c * Math.pow(k - 1, 2);
}

/** The platform's face: rings and tick marks, so its turning reads. */
function dialTexture(dark: boolean): THREE.Texture {
  const c = document.createElement('canvas');
  c.width = c.height = 512;
  const g = c.getContext('2d')!;
  const R = 256;
  const bg = g.createRadialGradient(R, R, 0, R, R, R);
  bg.addColorStop(0, dark ? '#3a3f46' : '#ffffff');
  bg.addColorStop(1, dark ? '#25292e' : '#e4e8e6');
  g.fillStyle = bg;
  g.beginPath(); g.arc(R, R, R, 0, Math.PI * 2); g.fill();
  const line = dark ? 'rgba(255,255,255,.22)' : 'rgba(31,43,51,.18)';
  g.strokeStyle = line;
  g.lineWidth = 3;
  for (const r of [0.94, 0.62]) { g.beginPath(); g.arc(R, R, R * r, 0, Math.PI * 2); g.stroke(); }
  g.lineWidth = 6;
  for (let i = 0; i < 48; i++) {
    const a = (i / 48) * Math.PI * 2, long = i % 4 === 0;
    g.strokeStyle = long ? 'rgba(226,65,47,.85)' : line;
    g.beginPath();
    g.moveTo(R + Math.cos(a) * R * (long ? 0.8 : 0.85), R + Math.sin(a) * R * (long ? 0.8 : 0.85));
    g.lineTo(R + Math.cos(a) * R * 0.92, R + Math.sin(a) * R * 0.92);
    g.stroke();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** Under the platform: a soft shadow on a light screen, a faint warm glow on a dark one. */
function floorTexture(dark: boolean): THREE.Texture {
  const c = document.createElement('canvas');
  c.width = c.height = 256;
  const g = c.getContext('2d')!;
  const grad = g.createRadialGradient(128, 128, 0, 128, 128, 128);
  if (dark) {
    grad.addColorStop(0, 'rgba(255,140,120,.35)');
    grad.addColorStop(0.45, 'rgba(226,65,47,.12)');
  } else {
    grad.addColorStop(0, 'rgba(31,43,51,.28)');
    grad.addColorStop(0.45, 'rgba(31,43,51,.12)');
  }
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 256, 256);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** The one loading screen. */
export const loadingShow = new LoadingShow();
