/**
 * Where to go (docs/missions.html, The journal): the tracker chip under the cash — the mission, the one
 * thing to do now, how far and which way — and, in the world, a beam over where that is and a pin over
 * everyone with work on offer.
 */
import * as THREE from 'three';
import { type World } from '../../world/tiles';
import { SEEN_THROUGH, drapedBand as laidBand, groundOf } from '../../render/drape';
import { THREAD_COLOUR, type Mission } from './model';
import { MISSION_YELLOW } from '../cargoLook';
import { clockText, type Missions } from './missions';
import { MEDAL_ICON } from './medals';
import { esc } from './card';

/** The chip's pointer: a broad head on a stubby fat tail, pointing up before it is turned. */
const ARROW = '<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M8 1.2 14.6 8.4H10.6V14.4H5.4V8.4H1.4Z" fill="currentColor" stroke="currentColor" stroke-width="0.8" stroke-linejoin="round"/></svg>';

/** Missions shown at once in the tracker; past this a "more…" link opens the journal. */
const TRACK_SHOWN = 3;

export class Tracker {
  /** The MISSIONS section at the top of the column under the top bar (#tr-stack): a grey header over the chips. */
  private sec = document.createElement('div');
  private chip = document.createElement('div');
  private text = '';
  /** Opens the journal (the "more…" link). */
  onMore: (() => void) | null = null;
  private group = new THREE.Group();
  /** What it draws in the world, for the camera's clean shot to leave out. */
  get root(): THREE.Group { return this.group; }
  private beam: THREE.Mesh;
  private pins: THREE.Group[] = [];
  private pinGeo = new THREE.OctahedronGeometry(0.28, 0);
  private t = 0;
  /**
   * How far a mission's target is along a guide's arrows, when something is laying them (the first
   * drive, game/tutorial.ts): null for the crow's distance.
   */
  pathFar: ((m: Mission) => number | null) | null = null;

  constructor(scene: THREE.Scene, private ms: Missions) {
    this.sec.className = 'trk-sec';
    this.sec.hidden = true;
    const h = document.createElement('div');
    h.className = 'trk-h link';
    h.textContent = 'Missions';
    // the header opens the journal, as J does (the user, 4 Nov 2026)
    h.title = 'Open the journal (J)';
    h.setAttribute('role', 'button');
    h.addEventListener('click', (e) => { e.stopPropagation(); this.onMore?.(); });
    this.chip.id = 'mission-tracker';
    this.chip.className = 'trk-list';
    this.sec.append(h, this.chip);
    // a click on a mission tracks it; the link under them opens the journal
    this.chip.addEventListener('click', (e) => {
      const el = (e.target as HTMLElement).closest('[data-m],[data-more]') as HTMLElement | null;
      if (!el) return;
      if (el.dataset.more) { this.onMore?.(); return; }
      const m = this.ms.active.find((q) => String(q.id) === el.dataset.m);
      if (m) this.ms.track(m);
    });
    document.getElementById('tr-stack')!.prepend(this.sec);
    this.beam = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, 40, 12, 1, true), new THREE.MeshBasicMaterial({ color: MISSION_YELLOW, transparent: true, opacity: 0.25, depthWrite: false }));
    this.beam.visible = false;
    this.group.add(this.beam);
    scene.add(this.group);
  }

  /** One mission's chip: which way and how far to its step now, its title and the step. */
  private chipHtml(m: Mission, tg: { x: number; z: number } | null, me: { x: number; y: number; z: number }, camera: THREE.Camera): string {
    const o = m.objs[m.step];
    const secret = o?.t === 'reach' && !!o.hidden && !tg;
    const crow = tg ? Math.hypot(tg.x - me.x, tg.z - me.z) : null;
    const far = crow !== null ? this.pathFar?.(m) ?? crow : null;
    let arrow = '';
    if (tg && crow !== null && crow > 3) {
      const a = new THREE.Vector3(me.x, me.y, me.z).project(camera), b = new THREE.Vector3(tg.x, me.y, tg.z).project(camera);
      let ang = Math.atan2(b.x - a.x, b.y - a.y);
      if (b.z > 1) ang += Math.PI;
      arrow = `<span class="mt-arrow" style="transform:rotate(${ang.toFixed(2)}rad)">${ARROW}</span>`;
    } else arrow = `<span class="mt-arrow here">${secret ? '?' : '●'}</span>`;
    const count = o && (o.t === 'deliver' || o.t === 'loads' || o.t === 'fleet') && o.n > 1 ? (o.t === 'fleet' && o.what === 'cash' ? ` $${Math.floor(m.count)}/$${o.n}` : ` ${m.count}/${o.n}`) : '';
    const colour = `#${THREAD_COLOUR[m.thread].toString(16).padStart(6, '0')}`;
    // a dash's clock (missions/workTemplates.ts), red for its last ten seconds
    const left = this.ms.clockOf(m);
    // or a delivery's medal clock: the next medal still to win (missions/medals.ts)
    const md = left === null ? this.ms.medalOf(m)?.next ?? null : null;
    const clock = left !== null ? `<span class="mt-clock${left < 10 ? ' hot' : ''}">⏱ ${clockText(left)}</span>`
      : md && this.ms.aboard(m) ? `<span class="mt-clock${md.left < 10 ? ' hot' : ''}">${MEDAL_ICON[md.medal]} ${clockText(md.left)}</span>` : '';
    return `<div class="chip trk${m.tracked ? ' on' : ''}" data-m="${m.id}" style="--c:${colour}" title="${m.tracked ? 'Tracked · click again to follow your cargo instead' : 'Click to track'}">${arrow}<span class="mt-txt"><b>${esc(m.title)}</b>${esc(o?.label ?? '')}${count}</span>${clock}${far !== null ? `<span class="mt-d">${Math.round(far)} t</span>` : ''}</div>`;
  }

  /** The rings on the ground at each running mission's arrival step, by mission id. */
  private rings = new Map<number, Ring>();

  /**
   * A ring on the ground where each running mission's arrival step counts — `r` across, the very circle the
   * player must stop inside — with a sign over it saying what to do there ("Stop here · 8 s", "Open 21:00
   * to 04:00") and an arc round its inside that fills while a hold is kept. Before, nothing on the ground
   * said where to stop or for how long (the user, 18 Oct 2026).
   */
  private syncRings(ground: (x: number, z: number) => number | null): void {
    const live = new Set<number>();
    for (const m of this.ms.active) {
      const r = this.ms.ringOf(m);
      if (!r) continue;
      const gy = ground(r.x, r.z);
      if (gy === null) continue;
      live.add(m.id);
      let ring = this.rings.get(m.id);
      const key = `${r.x.toFixed(2)},${r.z.toFixed(2)},${r.r}`;
      if (!ring || ring.key !== key) {
        if (ring) this.dropRing(m.id);
        ring = newRing(r.x, r.z, r.r, ground, key);
        this.group.add(ring.group);
        this.rings.set(m.id, ring);
      }
      // every mission's ring is mission yellow (docs/cargolook.html); the thread shows on its card
      const colour = r.ok ? MISSION_YELLOW : 0x8a8f98;
      (ring.band.material as THREE.MeshBasicMaterial).color.setHex(colour);
      (ring.band.material as THREE.MeshBasicMaterial).opacity = 0.55 + Math.sin(this.t * 3) * 0.2;
      (ring.fill.material as THREE.MeshBasicMaterial).color.setHex(colour);
      (ring.xray.material as THREE.MeshBasicMaterial).color.setHex(colour);
      if (Math.abs(ring.p - r.p) > 0.001) {
        ring.p = r.p;
        ring.arc.geometry.dispose();
        ring.arc.geometry = drapedBand(r.x, r.z, r.r - 0.75, r.r - 0.35, r.p * Math.PI * 2, ground);
      }
      ring.arc.visible = r.p > 0;
      if (ring.text !== r.text) { ring.text = r.text; paintSign(ring.sign, r.text); }
      ring.sign.position.set(r.x, gy + 3.2 + Math.sin(this.t * 2) * 0.1, r.z);
    }
    for (const id of [...this.rings.keys()]) if (!live.has(id)) this.dropRing(id);
  }

  private dropRing(id: number): void {
    const ring = this.rings.get(id);
    if (!ring) return;
    ring.group.removeFromParent();
    for (const o of [ring.band, ring.fill, ring.arc]) o.geometry.dispose();
    for (const o of [ring.band, ring.fill, ring.arc, ring.xray]) (o.material as THREE.Material).dispose();
    const sm = ring.sign.material as THREE.SpriteMaterial;
    sm.map?.dispose();
    sm.dispose();
    this.rings.delete(id);
  }

  hide(): void {
    this.sec.hidden = true;
    this.text = '';
    this.group.visible = false;
  }

  update(dt: number, camera: THREE.Camera, me: { x: number; y: number; z: number } | null, worldAt: (cx: number, cz: number) => World | null, covered: boolean): void {
    this.t += dt;
    this.group.visible = true;
    // what the ring lies on: the ground, a road's top or the water (render/drape.ts)
    const ground = groundOf(worldAt);
    // the chips: the tracked mission first, then the rest under way, up to TRACK_SHOWN of them
    const m = this.ms.tracked;
    const tg = m ? this.ms.target(m) : null;
    let html = '';
    if (m && me) {
      const rest = this.ms.active.filter((q) => q !== m).sort((a, b) => b.step / b.objs.length - a.step / a.objs.length);
      const list = [m, ...rest];
      html = list.slice(0, TRACK_SHOWN).map((q) => this.chipHtml(q, q === m ? tg : this.ms.target(q), me, camera)).join('');
      if (list.length > TRACK_SHOWN) html += `<button type="button" class="trk-more" data-more="1">${list.length - TRACK_SHOWN} more…</button>`;
    }
    if (covered) html = '';
    if (html !== this.text) {
      this.text = html;
      this.chip.innerHTML = html;
      this.sec.hidden = !html;
    }
    // the beam over the (tracked) target: there however close the player comes, so the place is never lost
    // just as it is reached (it used to go out inside 4 tiles, the user, 18 Oct 2026)
    const gy = tg ? ground(tg.x, tg.z) : null;
    this.beam.visible = !!tg && gy !== null && !!me;
    if (this.beam.visible && tg && gy !== null && m) {
      this.beam.position.set(tg.x, gy + 20, tg.z);
      (this.beam.material as THREE.MeshBasicMaterial).color.setHex(MISSION_YELLOW);
      this.beam.scale.x = this.beam.scale.z = 1 + Math.sin(this.t * 2.4) * 0.15;
    }
    this.syncRings(ground);
    // a pin over everyone with work on offer, as many as there are diamonds (Missions.onMap)
    const offers = this.ms.onMap();
    while (this.pins.length < offers.length) {
      const g = new THREE.Group();
      const gem = new THREE.Mesh(this.pinGeo, new THREE.MeshStandardMaterial({ color: MISSION_YELLOW, emissive: 0x3a2a00, roughness: 0.4, metalness: 0.3, flatShading: true }));
      gem.scale.y = 1.5;
      g.add(gem);
      this.group.add(g);
      this.pins.push(g);
    }
    this.pins.forEach((g, k) => {
      const q: Mission | undefined = offers[k];
      const y = q ? ground(q.giver.at.x, q.giver.at.z) : null;
      g.visible = !!q && y !== null;
      if (!q || y === null) return;
      g.position.set(q.giver.at.x, y + 1.3 + Math.sin(this.t * 2 + k) * 0.12, q.giver.at.z);
      g.rotation.y = this.t * 1.5 + k;
      const mat = (g.children[0] as THREE.Mesh).material as THREE.MeshStandardMaterial;
      mat.color.setHex(MISSION_YELLOW);
    });
  }
}

interface Ring {
  key: string; group: THREE.Group; band: THREE.Mesh; fill: THREE.Mesh; arc: THREE.Mesh; xray: THREE.Mesh; sign: THREE.Sprite; text: string; p: number;
}

/** How far over the ground the ring is laid: clear of the road paint, under a car's wheels. */
const RING_LIFT = 0.08;

/**
 * A band between radii r0 and r1 round (x, z), from angle 0 through `sweep`, laid over the ground finely enough
 * (render/drape.ts) that it follows slopes and banks rather than floating over a hollow or sinking into a rise.
 */
function drapedBand(x: number, z: number, r0: number, r1: number, sweep: number, ground: (x: number, z: number) => number | null): THREE.BufferGeometry {
  return laidBand(x, z, r0, r1, ground, RING_LIFT, Math.max(0.001, sweep));
}

/** A disc laid over the ground, in rings out to r: the soft floor of the stopping circle. */
function drapedDisc(x: number, z: number, r: number, ground: (x: number, z: number) => number | null): THREE.BufferGeometry {
  const geos: THREE.BufferGeometry[] = [];
  const steps = Math.max(2, Math.ceil(r / 1.2));
  for (let k = 0; k < steps; k++) geos.push(drapedBand(x, z, (r * k) / steps, (r * (k + 1)) / steps, Math.PI * 2, ground));
  // one geometry: the bands' positions and indices end to end
  const pos: number[] = [], index: number[] = [];
  for (const g of geos) {
    const base = pos.length / 3;
    pos.push(...(g.getAttribute('position').array as Float32Array));
    for (const i of g.getIndex()!.array) index.push(base + i);
    g.dispose();
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setIndex(index);
  return geo;
}

function ringMat(opacity: number): THREE.MeshBasicMaterial {
  return new THREE.MeshBasicMaterial({ transparent: true, opacity, depthWrite: false, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
}

function newRing(x: number, z: number, r: number, ground: (x: number, z: number) => number | null, key: string): Ring {
  const group = new THREE.Group();
  const band = new THREE.Mesh(drapedBand(x, z, r - 0.3, r, Math.PI * 2, ground), ringMat(0.6));
  const fill = new THREE.Mesh(drapedDisc(x, z, r - 0.3, ground), ringMat(0.12));
  const arcMat = ringMat(0.9);
  arcMat.color.setHex(0xffffff);
  const arc = new THREE.Mesh(drapedBand(x, z, r - 0.75, r - 0.35, 0.001, ground), arcMat);
  arc.visible = false;
  // and the band again, faintly, through whatever stands in the circle (the building the meeting is at), so
  // the whole ring always reads
  const xrayMat = ringMat(0.22);
  xrayMat.depthTest = false;
  const xray = new THREE.Mesh(band.geometry, xrayMat);
  // the ring itself before the buildings, so a faded one lets it show at its full colour (render/drape.ts SEEN_THROUGH)
  for (const o of [band, fill, arc]) o.renderOrder = SEEN_THROUGH + 2;
  xray.renderOrder = 2;
  const canvas = document.createElement('canvas');
  canvas.width = 512; canvas.height = 96;
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sign = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false, depthWrite: false }));
  sign.scale.set(5.2, 0.975, 1);
  sign.renderOrder = 3;
  group.add(fill, band, xray, arc, sign);
  return { key, group, band, fill, arc, xray, sign, text: '', p: 0 };
}

/** The sign over a ring: its words in a dark pill. */
function paintSign(sign: THREE.Sprite, text: string): void {
  const tex = (sign.material as THREE.SpriteMaterial).map as THREE.CanvasTexture;
  const canvas = tex.image as HTMLCanvasElement;
  const g = canvas.getContext('2d')!;
  g.clearRect(0, 0, canvas.width, canvas.height);
  g.font = '600 44px system-ui, sans-serif';
  const w = Math.min(canvas.width - 8, g.measureText(text).width + 56);
  const x0 = (canvas.width - w) / 2;
  g.fillStyle = 'rgba(20, 24, 30, 0.82)';
  g.beginPath();
  g.roundRect(x0, 8, w, 80, 40);
  g.fill();
  g.fillStyle = '#ffffff';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(text, canvas.width / 2, 50, canvas.width - 40);
  tex.needsUpdate = true;
}
