/** Small number helpers shared across the game (they were copied file to file). */

/** v held to [lo, hi]. */
export const clamp = (v: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, v));

/** v held to [0, 1]. */
export const clamp01 = (v: number): number => Math.max(0, Math.min(1, v));

/**
 * A random number in [a, b), from Math.random: for what may differ from game to game (traffic, people, weather
 * of the moment). Anything that must come out the same for everybody uses world/rng.ts's seeded hashes instead.
 */
export const rand = (a: number, b: number): number => a + Math.random() * (b - a);
