// ---- little people ---------------------------------------------------------------------------------

const BODY = new THREE.BoxGeometry(0.05, 0.08, 0.036).translate(0, 0.04, 0);
const HEAD = new THREE.SphereGeometry(0.02, 8, 6).translate(0, 0.1, 0);
const SEATED = new THREE.BoxGeometry(0.06, 0.1, 0.055).translate(0, 0.05, 0);

/** A batch of little people: bodies in their shirts, heads in skin tones, posed from Actors. */
class Figures {
  readonly body: THREE.InstancedMesh;
  readonly head: THREE.InstancedMesh;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private e = new THREE.Euler();
  private v = new THREE.Vector3();
  private s = new THREE.Vector3();
  constructor(readonly n: number, parent: THREE.Object3D) {
    this.body = new THREE.InstancedMesh(BODY, new THREE.MeshStandardMaterial({ roughness: 0.85 }), n);
    this.head = new THREE.InstancedMesh(HEAD, new THREE.MeshStandardMaterial({ roughness: 0.8 }), n);
    const c = new THREE.Color();
    for (let i = 0; i < n; i++) { this.body.setColorAt(i, c.setHex(0xffffff)); this.head.setColorAt(i, c.setHex(SKIN[i % SKIN.length])); }
    this.body.frustumCulled = this.head.frustumCulled = false;
    this.body.count = this.head.count = 0;
    parent.add(this.body, this.head);
  }
  private c = new THREE.Color();
  colour(i: number, hex: number): void { this.body.setColorAt(i, this.c.setHex(hex)); this.body.instanceColor!.needsUpdate = true; }
  pose(i: number, x: number, y: number, z: number, yaw: number, scale: number): void {
    this.e.set(0, yaw, 0);
    this.q.setFromEuler(this.e);
    this.m.compose(this.v.set(x, y, z), this.q, this.s.set(scale, scale, scale));
    this.body.setMatrixAt(i, this.m);
    this.head.setMatrixAt(i, this.m);
  }
  show(n: number): void {
    this.body.count = this.head.count = n;
    this.body.instanceMatrix.needsUpdate = this.head.instanceMatrix.needsUpdate = true;
  }
  dispose(): void {
    this.body.removeFromParent(); this.head.removeFromParent();
    this.body.dispose(); this.head.dispose();
    (this.body.material as THREE.Material).dispose(); (this.head.material as THREE.Material).dispose();
  }
}

// ---- the big screen ---------------------------------------------------------------------------------

class Board {
  private canvas = document.createElement('canvas');
  private g: CanvasRenderingContext2D;
  readonly tex: THREE.CanvasTexture;
  readonly meshes: THREE.Mesh[] = [];
  private last = '';
  constructor(p: StadiumPlan, private team: Team, parent: THREE.Object3D) {
    this.canvas.width = 256; this.canvas.height = 112;
    this.g = this.canvas.getContext('2d')!;
    this.tex = new THREE.CanvasTexture(this.canvas);
    this.tex.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.MeshBasicMaterial({ map: this.tex, toneMapped: false, polygonOffset: true, polygonOffsetFactor: -2 });
    const B = p.board, geo = new THREE.PlaneGeometry(B.w * 0.96, B.h * 0.92);
    // the gridiron's board is a cube hung over the field: a face each way along the field
    const out = B.two ? B.w * 0.55 / 2 + 0.012 : 0.03;
    for (const turn of B.two ? [0, Math.PI] : [0]) {
      const m = new THREE.Mesh(geo, mat);
      const yaw = B.yaw + turn;
      m.position.set(B.x + Math.sin(yaw) * out, B.y, B.z + Math.cos(yaw) * out);
      m.rotation.y = yaw;
      parent.add(m);
      this.meshes.push(m);
    }
    this.draw(this.team.nick.toUpperCase(), this.team.town.toUpperCase());
  }
  draw(big: string, small: string): void {
    const key = `${big}|${small}`;
    if (key === this.last) return;
    this.last = key;
    const g = this.g, W = 256, H = 112;
    g.fillStyle = '#0d1014'; g.fillRect(0, 0, W, H);
    g.fillStyle = `#${this.team.colour.toString(16).padStart(6, '0')}`; g.fillRect(0, 0, W, 8); g.fillRect(0, H - 8, W, 8);
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillStyle = '#ffffff';
    let size = 46;
    g.font = `700 ${size}px Impact, "Arial Narrow", sans-serif`;
    while (g.measureText(big).width > W - 16 && size > 16) { size -= 2; g.font = `700 ${size}px Impact, "Arial Narrow", sans-serif`; }
    g.fillText(big, W / 2, 44);
    g.fillStyle = '#ffc83d';
    size = 26;
    g.font = `600 ${size}px "IBM Plex Mono", monospace`;
    while (g.measureText(small).width > W - 16 && size > 12) { size -= 2; g.font = `600 ${size}px "IBM Plex Mono", monospace`; }
    g.fillText(small, W / 2, 86);
    this.tex.needsUpdate = true;
  }
  dispose(): void {
    for (const m of this.meshes) { m.removeFromParent(); m.geometry.dispose(); (m.material as THREE.Material).dispose(); }
    this.tex.dispose();
  }
}

// ---- the stage --------------------------------------------------------------------------------------

/** A gig's stage: the deck, the truss, the screen, the stacks, the lasers, the fog and the spot. */
interface Rig {
  group: THREE.Group;
  screen: THREE.MeshBasicMaterial;
  screenTex: THREE.CanvasTexture;
  lamps: THREE.MeshBasicMaterial[];
  lasers: THREE.Mesh[];
  laserMat: THREE.MeshBasicMaterial;
  fog: { s: THREE.Sprite; age: number; life: number; vx: number; vz: number }[];
  spot: THREE.Mesh;
  next: number;
  hue: number;
  song: number;
}

let fogTexture: THREE.CanvasTexture | null = null;
function fogTex(): THREE.CanvasTexture {
  if (fogTexture) return fogTexture;
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d')!, r = g.createRadialGradient(32, 32, 2, 32, 32, 32);
  r.addColorStop(0, 'rgba(255,255,255,0.9)'); r.addColorStop(0.5, 'rgba(255,255,255,0.35)'); r.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = r; g.fillRect(0, 0, 64, 64);
  return (fogTexture = new THREE.CanvasTexture(c));
}

function buildRig(p: StadiumPlan, act: Act, parent: THREE.Object3D): Rig {
  const s = p.stage, group = new THREE.Group();
  group.position.set(s.x, 0, s.z);
  group.rotation.y = s.yaw;
  parent.add(group);
  const dark = new THREE.MeshStandardMaterial({ color: 0x24272c, roughness: 0.7 });
  const steel = new THREE.MeshStandardMaterial({ color: 0x8c9198, roughness: 0.5, metalness: 0.4 });
  const box = (w: number, h: number, d: number, x: number, y: number, z: number, m: THREE.Material) => {
    const q = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
    q.position.set(x, y + h / 2, z);
    q.castShadow = true;
    group.add(q);
    return q;
  };
  // the deck and the drum riser
  box(s.w, 0.12, s.d, 0, 0, 0, dark);
  box(0.36, 0.06, 0.24, 0, 0.12, -s.d * 0.28, dark);
  // the truss: two towers and an open frame over the deck, so the band is seen from above
  const H = 0.95;
  for (const sx of [-1, 1]) box(0.05, H, 0.05, sx * s.w / 2, 0, -s.d / 2 + 0.04, steel);
  box(s.w + 0.05, 0.05, 0.05, 0, H, -s.d / 2 + 0.04, steel);
  box(s.w + 0.05, 0.05, 0.05, 0, H, s.d / 2 - 0.04, steel);
  for (const sx of [-1, 1]) box(0.05, 0.05, s.d, sx * s.w / 2, H, 0, steel);
  // the stacks either side, the wedges along the front
  for (const sx of [-1, 1]) {
    box(0.16, 0.42, 0.13, sx * (s.w / 2 + 0.12), 0, s.d * 0.2, dark);
    box(0.14, 0.32, 0.11, sx * (s.w / 2 + 0.12), H - 0.34, s.d * 0.3, dark);
  }
  // the drum kit and the mic stand
  const drum = new THREE.MeshStandardMaterial({ color: 0xc23b3b, roughness: 0.4 });
  for (const [x, z, r] of [[0, -s.d * 0.22, 0.05], [-0.07, -s.d * 0.3, 0.035], [0.07, -s.d * 0.3, 0.035]] as const) {
    const q = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 0.05, 10), drum);
    q.position.set(x, 0.18 + 0.025, z);
    group.add(q);
  }
  // the screen at the back, with the act's name on it
  const c = document.createElement('canvas');
  c.width = 256; c.height = 96;
  const screenTex = new THREE.CanvasTexture(c);
  screenTex.colorSpace = THREE.SRGBColorSpace;
  const g = c.getContext('2d')!;
  const grad = g.createLinearGradient(0, 0, 256, 96);
  grad.addColorStop(0, '#ff3fa4'); grad.addColorStop(0.5, '#6a3bff'); grad.addColorStop(1, '#19d3ff');
  g.fillStyle = grad; g.fillRect(0, 0, 256, 96);
  g.fillStyle = '#fff'; g.textAlign = 'center'; g.textBaseline = 'middle';
  let size = 40;
  g.font = `700 ${size}px Impact, "Arial Narrow", sans-serif`;
  const name = act.name.toUpperCase();
  while (g.measureText(name).width > 236 && size > 14) { size -= 2; g.font = `700 ${size}px Impact, "Arial Narrow", sans-serif`; }
  g.fillText(name, 128, 48);
  const screen = new THREE.MeshBasicMaterial({ map: screenTex, toneMapped: false });
  const sc = new THREE.Mesh(new THREE.PlaneGeometry(s.w * 0.86, 0.5), screen);
  sc.position.set(0, 0.14 + 0.27, -s.d / 2 + 0.07);
  group.add(sc);
  // lamps on the front beam
  const lamps: THREE.MeshBasicMaterial[] = [];
  for (let i = 0; i < 6; i++) {
    const m = new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false });
    const q = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.05, 0.06), m);
    q.position.set(-s.w * 0.42 + i * (s.w * 0.84 / 5), H - 0.05, s.d / 2 - 0.04);
    group.add(q);
    lamps.push(m);
  }
  // the lasers: thin beams from the top beam, out over the crowd
  const laserMat = new THREE.MeshBasicMaterial({ color: 0x3dff6a, transparent: true, opacity: 0.6, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
  const beam = new THREE.CylinderGeometry(0.006, 0.006, 4.6, 4, 1, true).translate(0, 2.3, 0).rotateX(Math.PI / 2);
  const lasers: THREE.Mesh[] = [];
  for (let i = 0; i < 8; i++) {
    const q = new THREE.Mesh(beam, laserMat);
    q.position.set(-s.w * 0.4 + i * (s.w * 0.8 / 7), H, s.d / 2 - 0.05);
    q.renderOrder = 3;
    group.add(q);
    lasers.push(q);
  }
  // a spot on the singer
  const spot = new THREE.Mesh(
    new THREE.ConeGeometry(0.22, H - 0.12, 16, 1, true).translate(0, -(H - 0.12) / 2, 0),
    new THREE.MeshBasicMaterial({ color: 0xfff2c8, transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false }),
  );
  spot.position.set(0, H, s.d * 0.3);
  spot.renderOrder = 3;
  group.add(spot);
  // the fog: soft sprites puffed out over the front of the stage
  const fog: Rig['fog'] = [];
  for (let i = 0; i < 28; i++) {
    const m = new THREE.SpriteMaterial({ map: fogTex(), color: 0xdfe6ff, transparent: true, opacity: 0, depthWrite: false });
    const sp = new THREE.Sprite(m);
    sp.visible = false;
    group.add(sp);
    fog.push({ s: sp, age: 0, life: 0, vx: 0, vz: 0 });
  }
  return { group, screen, screenTex, lamps, lasers, laserMat, fog, spot, next: 0, hue: Math.random(), song: -1 };
}

function disposeGroup(g: THREE.Object3D): void {
  g.removeFromParent();
  g.traverse((o) => {
    const m = o as THREE.Mesh;
    if (m.geometry) m.geometry.dispose();
    const mat = m.material as THREE.Material | THREE.Material[] | undefined;
    if (Array.isArray(mat)) mat.forEach((q) => q.dispose()); else mat?.dispose();
  });
}

// ---- the stadiums -----------------------------------------------------------------------------------

/** What a stadium is called on its gates: the town's Stadium, Park or Arena, or a ballpark's "Comets Field". */
export function venueName(design: StadiumPlan['design'], team: Team): string {
  if (design === 'ballpark') return `${team.nick} Field`;
  return `${team.town} ${['Stadium', 'Park', 'Field', 'Arena'][['bowl', 'ballpark', 'gridiron', 'pillow'].indexOf(design)]}`;
}

/** The key a stadium is known by: its cell and its building's uid. */
export const stadiumKey = (w: World, b: Building): string => `${w.cx},${w.cz}#${b.uid}`;

let current: Stadiums | null = null;
/** What is on at a stadium, for the inspector: null when it is quiet or out of sight. */
export function stadiumNow(w: World, b: Building): string | null { return current?.now(stadiumKey(w, b)) ?? null; }
/** The stadiums runtime, for the inspector's season and tour sections (game/stadiumCard.ts). */
export function stadiumsNow(): Stadiums | null { return current; }

/**
 * When a county's club of this sport was founded, if it was during play: a county that had no stadium of the
 * sport until one was built gets a brand new team as that stadium opens, with no games or seasons before it.
 * Undefined while any stadium of the sport there was standing from the start (that club was always there).
 */
function foundedAt(w: World, sport: Sport): number | undefined {
  let first: number | undefined;
  for (const b of w.allBuildings) {
    if (b.kind !== 'stadium' || b.gone || stadiumPlanOf(b).sport !== sport) continue;
    if (b.grownAt === undefined) return undefined;
    const open = b.grownAt + BUILD_HOURS;
    if (first === undefined || open < first) first = open;
  }
  return first;
}

/** The team a stadium's town fields. */
export function homeTeam(w: World, b: Building): Team {
  const town = w.towns.find((t) => t.buildings.includes(b));
  return teamOf(town?.name ?? w.name, undefined, town?.accent);
}

export class Stadiums {
  private venues = new Map<string, Venue>();
  /** The last fixture's result at each stadium, for the inspector. */
  private results = new Map<string, string>();
  /** Scores of the league games the player watched, by fixture key: they replace the played-out ones. */
  readonly overrides: Overrides = new Map();
  /** League games being played live right now (kept out of the tables until they end), and every one started live. */
  readonly liveKeys = new Set<string>();
  private started = new Set<string>();
  /** Clubs whose real stadium team has been met, by `league id|slot`: the town, and its colour. */
  private named = new Map<string, [string, number?]>();
  /** The last gig at each stadium: the act's id and the day. */
  readonly gigs = new Map<string, [number, number]>();
  /** The touring acts and their convoys. */
  readonly tours: Tours;
  /** Online: what this game tells the world's league book (net/leagueNet.ts); null offline. */
  share: ((m: LeagueShare) => void) | null = null;
  /** Scores the world gave (the first game to finish each): never replaced by this game's own. */
  private worldDone = new Set<string>();
  /** Clubs as the world has them, and fixtures other games are playing live. */
  private worldClubs = new Map<string, string>();
  private worldLive = new Set<string>();

  constructor(private host: StadiumHost) {
    current = this;
    this.tours = new Tours({
      worlds: () => host.worlds(),
      focus: () => host.focus(),
      hours: () => host.hours(),
      seed: () => host.seed?.() ?? '',
      trafficOf: (w) => host.trafficOf?.(w) ?? null,
      say: (title, body, group) => host.say(title, body, group),
      venueName: (w, b) => venueName(stadiumPlanOf(b).design, homeTeam(w, b)),
      begin: (key, act, tour) => this.begin(key, act, tour),
    });
  }

  hours(): number { return this.host.hours(); }
  private sh(): number { return hashString(this.host.seed?.() ?? ''); }

  /** The league a stadium's club plays in, and its place in it. */
  leagueOf(w: World, b: Building): { L: League; slot: number; team: Team } {
    const sport = stadiumPlanOf(b).sport, team = homeTeam(w, b);
    const L = leagueFor(this.sh(), sport, w.cx, w.cz);
    const slot = slotOf(L, w.cx, w.cz);
    if (slot >= 0) {
      const since = foundedAt(w, sport), accent = w.towns.find((t) => t.buildings.includes(b))?.accent;
      setFounded(L, slot, since);
      const key = `${L.id}|${slot}`;
      this.named.set(key, [team.town, accent]);
      // online: a club the world doesn't know as this game sees it is told to it
      const club: LeagueClub = [key, w.cx, w.cz, team.town, accent ?? null, since ?? null];
      if (this.share && this.worldClubs.get(key) !== JSON.stringify(club.slice(3))) {
        this.worldClubs.set(key, JSON.stringify(club.slice(3)));
        this.share({ clubs: [club] });
      }
    }
    return { L, slot, team };
  }

  /** A club as it is known: its real stadium team once met, else the county's club. */
  clubTeam(L: League, slot: number, avoid?: Team): Team {
    const n = this.named.get(`${L.id}|${slot}`);
    if (n) return teamOf(n[0], avoid, avoid ? undefined : n[1]);
    return avoid ? teamOf(L.clubs[slot].place, avoid) : L.clubs[slot].team;
  }

  /** The tours' cells to keep in memory (main.ts pins them with the fleet's). */
  needed(): [number, number][] { return this.tours.needed(); }

  update(dt: number): void {
    const focus = this.host.focus();
    this.sync(focus);
    this.tours.update(dt);
    // nothing is written along the bottom of the screen: a game's goals, scores and result come as cards
    for (const v of this.venues.values()) {
      const c = stadiumToIsland(v.b, 0, 0);
      const d = Math.hypot(v.w.ox + c.x - focus.x, v.w.oz + c.z - focus.z);
      v.d = d;
      v.root.visible = d < ACTIVE_R + 20;
      this.schedule(v, d, dt);
      v.floods.update(dt, !!v.ev);
      if (v.ev) this.run(v, v.ev, dt, d);
      if (v.root.visible) this.dress(v, dt);
    }
  }

  // ---- venues ------------------------------------------------------------------------------------

  private sync(focus: { x: number; z: number }): void {
    const seen = new Set<string>();
    for (const w of this.host.worlds()) {
      for (const b of w.allBuildings) {
        if (b.kind !== 'stadium' || b.gone || builtShare(b) < 1) continue;
        // a stadium built during play founds its county's club as it opens, wherever the camera is
        if (b.grownAt !== undefined) this.leagueOf(w, b);
        const c = stadiumToIsland(b, 0, 0);
        if (Math.hypot(w.ox + c.x - focus.x, w.oz + c.z - focus.z) > KEEP_R) continue;
        const key = stadiumKey(w, b);
        seen.add(key);
        if (!this.venues.has(key)) this.venues.set(key, this.makeVenue(key, w, b));
      }
    }
    for (const [key, v] of this.venues) if (!seen.has(key)) { this.endEvent(v); this.disposeVenue(v); this.venues.delete(key); }
  }

  private makeVenue(key: string, w: World, b: Building): Venue {
    const plan = stadiumPlanOf(b);
    const { L, slot, team } = this.leagueOf(w, b);
    const f = stadiumFrame(b);
    const root = new THREE.Group();
    root.position.set(w.ox + f.ox, f.oy, w.oz + f.oz);
    root.rotation.y = f.yaw;
    this.host.scene.add(root);
    const r = mulberry32(hashString(key));
    const seats = new Float32Array(seatsOf(plan, 0.15, r));
    // shuffle the seats, so the stands fill evenly rather than row by row
    const n = seats.length / 3;
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(r() * (i + 1));
      for (let k = 0; k < 3; k++) { const t = seats[i * 3 + k]; seats[i * 3 + k] = seats[j * 3 + k]; seats[j * 3 + k] = t; }
    }
    const crowd = new THREE.InstancedMesh(SEATED, new THREE.MeshStandardMaterial({ roughness: 0.9 }), n);
    const m = new THREE.Matrix4(), c = new THREE.Color();
    for (let i = 0; i < n; i++) {
      m.makeTranslation(seats[i * 3], seats[i * 3 + 1], seats[i * 3 + 2]);
      crowd.setMatrixAt(i, m);
      crowd.setColorAt(i, c.setHex(SHIRTS[Math.floor(r() * SHIRTS.length)]));
    }
    crowd.count = 0;
    crowd.frustumCulled = false;
    root.add(crowd);
    const walkers = new Figures(44, root);
    // the floodlights over the field, from masts at the bowl's corners (render/buildings/stadiums.ts)
    const fr = plan.field;
    const floods = new Floodlights({
      masts: [-1, 1].flatMap((sx) => [-1, 1].map((sz) => ({ x: sx * (plan.W / 2 - 0.2), y: 2.2, z: sz * (plan.D / 2 - 0.2) }))),
      pool: { x: fr.cx, z: fr.cz, w: fr.axis === 'x' ? fr.len : fr.wid, d: fr.axis === 'x' ? fr.wid : fr.len, y: 0 },
    });
    root.add(floods.group);
    const off = hashString(key) % PERIOD;
    const v: Venue = {
      key, w, b, plan, team, name: venueName(plan.design, team),
      root, seats, crowd, walkers, walk: [], board: new Board(plan, team, root), fill: 0, ev: null,
      lastSlot: Math.floor((this.host.hours() + off) / PERIOD), lastEnd: -99, soonAt: null, wasFar: true, last: '', floods,
      league: L, slot, d: Infinity,
    };
    return v;
  }

  private disposeVenue(v: Venue): void {
    v.board.dispose();
    v.walkers.dispose();
    v.crowd.removeFromParent();
    v.crowd.dispose();
    (v.crowd.material as THREE.Material).dispose();
    v.floods.dispose();
    this.host.scene.remove(v.root);
  }

  // ---- the fixture list --------------------------------------------------------------------------

  private schedule(v: Venue, d: number, dt: number): void {
    const hours = this.host.hours();
    const off = hashString(v.key) % PERIOD;
    const slot = Math.floor((hours + off) / PERIOD);
    const hour = ((hours % 24) + 24) % 24;
    if (d > ACTIVE_R + 30 && v.ev) this.endEvent(v);
    if (d > ACTIVE_R) { v.wasFar = true; v.lastSlot = slot; return; }
    if (v.ev || dt <= 0) return;
    // the league: a home fixture kicking off now is played here, live
    const fx = this.dueFixture(v, hours);
    if (fx) { this.started.add(fx.key); this.startEvent(v, v.plan.sport, { fixture: fx }); return; }
    if (v.wasFar && d < VISIT_R) {
      v.wasFar = false;
      if (hours - v.lastEnd > 3) v.soonAt = hours + 0.3;
    }
    const due = slot !== v.lastSlot && hour >= 18 && hour < 23;
    const soon = v.soonAt !== null && hours >= v.soonAt;
    if (due || soon) {
      v.lastSlot = slot;
      v.soonAt = null;
      // a fixture or a tour's show is on soon anyway: wait for it
      if (this.nextHere(v, hours) - hours < 4) return;
      const r = mulberry32(hashString(`${v.key}|${slot}`));
      const inSeason = SEASONS[v.plan.sport].includes(this.host.season());
      // come by after a while away: a friendly in season, a one-night gig out of it; off-season evenings, now and then a gig
      if (soon && inSeason) this.startEvent(v, v.plan.sport, { friendly: true });
      else if (soon || (!inSeason && r() < 0.5)) {
        const free = this.tours.acts().filter((a) => !this.tours.touring(a.id));
        if (free.length) this.startEvent(v, 'concert', { gig: free[Math.floor(r() * free.length)].id });
      }
    }
  }

  /** A home fixture of this stadium's club that has just kicked off and has not been started here. */
  private dueFixture(v: Venue, hours: number): FixRef | null {
    if (v.slot < 0) return null;
    const s = seasonAt(v.plan.sport, hours);
    if (!s.inSeason) return null;
    for (const f of fixtures(v.league, s.k)) {
      if (f.home !== v.slot || hours < f.at || hours > f.at + KICK_WINDOW) continue;
      const key = fixtureKey(v.league, s.k, f);
      if (this.started.has(key) || this.overrides.has(key)) continue;
      return { L: v.league, k: s.k, f, key };
    }
    return null;
  }

  /** When the next thing booked here is: a home fixture or a tour's show. */
  private nextHere(v: Venue, hours: number): number {
    let at = Infinity;
    const t = this.tours.at(v.key);
    if (t) at = t.at.key === v.key ? t.at.show : t.next!.show;
    if (v.slot >= 0) {
      const s = seasonAt(v.plan.sport, hours);
      for (const k of [s.k, s.k + 1]) for (const f of fixtures(v.league, k)) if (f.home === v.slot && f.at >= hours - KICK_WINDOW) at = Math.min(at, f.at);
    }
    return at;
  }

  /** A tour's show is due here (game/tours.ts): on now if anyone is near and the stadium is free. */
  private begin(key: string, act: Act, tour: Tour): 'live' | 'busy' | 'away' {
    const v = this.venues.get(key);
    if (!v || v.d > ACTIVE_R) return 'away';
    if (v.ev) {
      // a friendly or a one-night gig makes way for the show; a league game is played out first
      if (v.ev.fixture || v.ev.tour) return 'busy';
      this.endEvent(v);
    }
    this.startEvent(v, 'concert', { act, tour });
    return 'live';
  }

  /** Who comes to play a friendly: another club of the league. */
  private visitor(v: Venue, seed: number): Team {
    const others = v.league.clubs.filter((c) => c.slot !== v.slot);
    if (!others.length) return teamOf(FAR_TOWNS[seed % FAR_TOWNS.length], v.team);
    return this.clubTeam(v.league, others[seed % others.length].slot, v.team);
  }

  startEvent(v: Venue, kind: Kind, opt: { fixture?: FixRef; tour?: Tour; act?: Act; friendly?: boolean; gig?: number } = {}): void {
    if (v.ev) return;
    // a league game's own seed: everyone who watches it sees the same game
    const seed = opt.fixture ? hashString(opt.fixture.key) : hashString(`${v.key}|${Math.floor(this.host.hours())}|${kind}`);
    let sim: Sim, away: Team | null = null, act: Act | null = null, title: string;
    if (kind === 'concert') {
      // a touring act's show, or a one-night gig by one of the world's acts (from the console, whoever is free)
      let a = opt.act ?? null;
      if (!a) {
        const pool = this.tours.acts();
        const one: TourAct = pool[opt.gig ?? seed % pool.length];
        if (opt.gig === undefined) opt.gig = one.id;
        a = { name: one.name, songs: one.songs, tour: 'One Night Only' };
      }
      act = a;
      sim = new ConcertSim(v.plan, act, seed);
      title = `${act.name} · ${act.tour}`;
    } else {
      away = opt.fixture ? this.clubTeam(opt.fixture.L, opt.fixture.f.away, v.team) : this.visitor(v, seed);
      sim = kind === 'soccer' ? new SoccerSim(v.plan, v.team, away, seed) : kind === 'football' ? new FootballSim(v.plan, v.team, away, seed) : new BaseballSim(v.plan, v.team, away, seed);
      title = kind === 'baseball' ? `${away.name} at ${v.team.name}` : `${v.team.name} v ${away.name}`;
      if (!opt.fixture) title += ' · friendly';
      else { this.liveKeys.add(opt.fixture.key); this.shareLive(); }
    }
    const props = new THREE.Group();
    v.root.add(props);
    const people = new Figures(sim.actors.length, props);
    sim.actors.forEach((a, i) => people.colour(i, a.col));
    let ball: THREE.Mesh | null = null;
    if (sim.ball) {
      const geo = kind === 'football' ? new THREE.SphereGeometry(0.022, 8, 6).scale(1, 0.7, 1.5) : new THREE.SphereGeometry(kind === 'baseball' ? 0.016 : 0.022, 8, 6);
      ball = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: kind === 'football' ? 0x7a4a2a : 0xffffff, roughness: 0.5 }));
      ball.visible = false;
      props.add(ball);
    }
    if (kind === 'soccer') this.goals(v.plan, props);
    const rig = act ? buildRig(v.plan, act, props) : null;
    // the stands in the colours: home shirts, a corner of away ones, and for a gig whatever people wear
    const c = new THREE.Color(), r = mulberry32(seed);
    for (let i = 0; i < v.crowd.instanceMatrix.count; i++) {
      const roll = r();
      const hex = away ? (roll < 0.45 ? v.team.colour : roll < 0.6 ? away.colour : roll < 0.68 ? v.team.alt : SHIRTS[Math.floor(r() * SHIRTS.length)]) : SHIRTS[Math.floor(r() * SHIRTS.length)];
      v.crowd.setColorAt(i, c.setHex(hex));
    }
    if (v.crowd.instanceColor) v.crowd.instanceColor.needsUpdate = true;
    v.ev = { kind, sim, stage: 'arrive', t: 0, title, away, act, people, ball, props, rig, announced: false, result: '', fixture: opt.fixture, tour: opt.tour, friendly: opt.friendly, gig: opt.gig };
    v.walk = [];
    // now and then the day opens with a flypast: three to seven jets or helicopters low over the ground as it goes live
    if (this.host.flyover && mulberry32(seed ^ 0x5a17)() < FLYPAST_SHARE) {
      this.host.flyover(v.w.ox + v.b.x + v.b.w / 2, v.w.oz + v.b.z + v.b.d / 2, ARRIVE, seed, v.name);
    }
  }

  /** Soccer goals at each end of the pitch: posts, a bar, a net. */
  private goals(p: StadiumPlan, parent: THREE.Object3D): void {
    const f = p.field, gw = Math.min(0.32, f.wid * 0.12), white = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 });
    const net = new THREE.MeshStandardMaterial({ color: 0xffffff, transparent: true, opacity: 0.55, roughness: 1, depthWrite: false });
    for (const e of [-1, 1]) {
      const g = new THREE.Group();
      const a = e * (f.len / 2);
      if (f.axis === 'x') { g.position.set(f.cx + a, 0, f.cz); g.rotation.y = e > 0 ? Math.PI / 2 : -Math.PI / 2; }
      else { g.position.set(f.cx, 0, f.cz + a); g.rotation.y = e > 0 ? 0 : Math.PI; }
      for (const s of [-1, 1]) { const post = new THREE.Mesh(new THREE.BoxGeometry(0.024, 0.14, 0.024), white); post.position.set(s * gw, 0.07, 0); g.add(post); }
      const bar = new THREE.Mesh(new THREE.BoxGeometry(gw * 2 + 0.024, 0.024, 0.024), white);
      bar.position.set(0, 0.14, 0);
      g.add(bar);
      const back = new THREE.Mesh(new THREE.BoxGeometry(gw * 2, 0.13, 0.12), net);
      back.position.set(0, 0.065, 0.065);
      g.add(back);
      parent.add(g);
    }
  }

  private endEvent(v: Venue): void {
    const e = v.ev;
    if (!e) return;
    if (e.result) this.results.set(v.key, e.result);
    // over before the end (the camera went away): the league plays the game out, and a show still counts
    if (e.fixture) { this.liveKeys.delete(e.fixture.key); if (this.worldLive.has(e.fixture.key)) this.liveKeys.add(e.fixture.key); }
    if (!e.result && e.stage !== 'arrive') this.finished(v, e);
    else if (!e.result && e.tour) this.tours.showDone(e.tour, false);
    e.people.dispose();
    disposeGroup(e.props);
    v.ev = null;
    v.lastEnd = this.host.hours();
    v.board.draw(v.team.nick.toUpperCase(), v.team.town.toUpperCase());
  }

  /** A game or a show is over: the score goes in the league's books, the show on its act's. */
  private finished(v: Venue, e: Event): void {
    if (e.fixture && e.result) {
      const sc = (e.sim as unknown as { score?: number[] }).score;
      // online, a score the world already has (another game finished it first) stands
      if (sc && !this.worldDone.has(e.fixture.key)) {
        this.overrides.set(e.fixture.key, [sc[0], sc[1]]);
        while (this.overrides.size > MAX_RESULTS) this.overrides.delete(this.overrides.keys().next().value!);
        forgetSeason(e.fixture.L, e.fixture.k);
        this.share?.({ done: [[e.fixture.key, sc[0], sc[1]]] });
      }
      this.liveKeys.delete(e.fixture.key);
      if (this.worldLive.has(e.fixture.key) && !this.worldDone.has(e.fixture.key)) this.liveKeys.add(e.fixture.key);
      this.shareLive();
    }
    const day = Math.floor(this.host.hours() / 24) + 1;
    if (e.tour) {
      this.gigs.set(v.key, [e.tour.act, day]);
      this.tours.showDone(e.tour, true);
      e.tour = undefined;
    } else if (e.gig !== undefined) {
      this.gigs.set(v.key, [e.gig, day]);
      this.tours.oneNight(e.gig, v.team.town, v.seats.length / 3, hashString(`${v.key}|${day}|${e.gig}`));
      e.gig = undefined;
    }
  }

  // ---- the day itself ----------------------------------------------------------------------------

  private run(v: Venue, e: Event, dt: number, d: number): void {
    e.t += dt;
    const hear = d < HEAR_R;
    if (e.stage === 'arrive') {
      if (!e.announced && d < 120) {
        e.announced = true;
        const what = e.act ? `${e.act.name} live at ${v.name} · the gates are open` : `${SPORT_NAME[e.kind as Sport]} at ${v.name} · the fans are on their way`;
        this.host.say(`🏟️ ${e.title}`, what, v.name);
      }
      if (e.fixture) {
        // a league game warms up in a fixed number of fixed steps, and goes live after them
        e.acc = (e.acc ?? 0) + dt;
        for (let n = 0; n < MAX_STEPS && e.acc >= FIXED_DT && e.stage === 'arrive'; n++) {
          e.sim.warm(FIXED_DT); e.acc -= FIXED_DT;
          if ((e.warmN = (e.warmN ?? 0) + 1) >= Math.round(ARRIVE / FIXED_DT)) { e.stage = 'live'; e.t = 0; }
        }
      } else {
        e.sim.warm(dt);
        if (e.t >= ARRIVE) { e.stage = 'live'; e.t = 0; }
      }
    } else if (e.stage === 'live') {
      if (e.fixture) {
        e.acc = (e.acc ?? 0) + dt;
        for (let n = 0; n < MAX_STEPS && e.acc >= FIXED_DT && !e.sim.done; n++) { e.sim.step(FIXED_DT); e.acc -= FIXED_DT; }
      } else e.sim.step(dt);
      // the play-by-play only for a player watching from close by; the crowd and the whistle as before
      const x0 = v.w.ox + v.b.x, z0 = v.w.oz + v.b.z;
      const watching = this.host.watching ? this.host.watching(x0, z0, x0 + v.b.w, z0 + v.b.d, v.b.level * 0.5 + 4) : hear;
      for (const c of e.sim.cues) {
        if (!hear) continue;
        if (c.t === 'cheer') this.host.cheer();
        else if (c.t === 'whistle') this.host.whistle(c.final);
        else if (watching) { this.host.say(c.title, c.body, v.name); if (c.end) e.toldEnd = true; }
      }
      e.sim.cues.length = 0;
      if (e.sim.done) {
        e.stage = 'leave'; e.t = 0; e.result = e.sim.line(); this.finished(v, e);
        // the paper (docs/newspaper.html): a game or a show the player was there for
        if (e.announced) {
          if (e.act) press.write({ k: 'concert', at: buildingAt(v.w, v.b), f: { act: e.act.name, venue: v.name } });
          else press.write({ k: 'bigGame', at: buildingAt(v.w, v.b), f: { title: e.title, result: stripTags(e.result), venue: v.name } });
        }
        // the final score, said once whoever is watching, unless the full-time line just said it
        if (!e.toldEnd && e.announced) {
          if (e.act) this.host.say(`🏟️ ${e.act.name}`, `That's the show at ${v.name}`, v.name);
          else this.host.say(`🏁 ${e.title}`, `Final · ${stripTags(e.result)}`, v.name);
        }
      }
    } else if (e.t >= LEAVE) {
      this.endEvent(v);
      return;
    }
    if (!v.root.visible) return;
    this.pose(v, e, dt);
    const [big, small] = e.stage === 'arrive'
      ? (e.act ? [e.act.name.toUpperCase(), 'TONIGHT'] : [`${v.team.abbr} v ${e.away!.abbr}`, 'KICK-OFF SOON'.replace('KICK-OFF', e.kind === 'baseball' ? 'FIRST PITCH' : 'KICK-OFF')])
      : e.stage === 'leave' ? (e.act ? ['THANK YOU', v.team.town.toUpperCase()] : e.sim.board()) : e.sim.board();
    v.board.draw(big, small);
  }

  /** Put the sim's people, its ball and its stage where they are this frame. */
  private pose(v: Venue, e: Event, dt: number): void {
    const sim = e.sim, fig = e.people;
    // on the field only once the gates are open; off it once the crowd is going
    const onField = e.stage !== 'leave' || e.t < LEAVE * 0.35;
    sim.actors.forEach((a: Actor, i) => {
      const run = a.moving ? Math.abs(Math.sin(performance.now() / 70 + i)) * 0.012 : 0;
      const sc = a.hidden || !onField ? 0 : a.big ? 1.25 : 1;
      fig.pose(i, a.x, a.y + a.hop + run, a.z, a.yaw, sc);
    });
    fig.show(sim.actors.length);
    if (e.ball && sim.ball) {
      e.ball.visible = sim.ball.shown && onField && e.stage === 'live';
      e.ball.position.set(sim.ball.x, sim.ball.y, sim.ball.z);
    }
    if (e.rig && sim instanceof ConcertSim) this.light(v, e.rig, sim, dt, onField);
  }

  /** The lights, the lasers, the fog and the screen, all on the beat. */
  private light(v: Venue, rig: Rig, sim: ConcertSim, dt: number, on: boolean): void {
    const now = performance.now() / 1000;
    if (sim.song !== rig.song) { rig.song = sim.song; rig.hue = (rig.hue + 0.27) % 1; }
    const beat = Math.pow(1 - sim.beat, 3), live = on && sim.song >= 0;
    const E = live ? sim.energy : 0.05;
    const hue = rig.hue;
    rig.screen.color.setHSL(0, 0, 0.45 + 0.55 * (live ? 0.5 + beat * 0.5 * E : 0.3));
    rig.lamps.forEach((m, i) => m.color.setHSL((hue + i * 0.08) % 1, 0.9, live ? 0.25 + 0.55 * (i % 2 === Math.floor(now * sim.bps) % 2 ? 1 : 0.3) * E : 0.15));
    // the lasers fan out and sweep in the chorus
    rig.laserMat.color.setHSL((hue + 0.33) % 1, 1, 0.55);
    rig.laserMat.opacity = live && sim.gap <= 0 ? Math.min(0.85, Math.max(0, E - 0.35) * 1.8) : 0;
    rig.lasers.forEach((l, i) => {
      l.visible = rig.laserMat.opacity > 0.02;
      l.rotation.set(-0.08 - 0.12 * (0.5 + 0.5 * Math.sin(now * 0.9 + i)), Math.sin(now * (0.6 + E) + i * 0.7) * 0.75, 0);
    });
    // the spot follows the singer
    const singer = sim.actors[0], s = v.plan.stage;
    const dx = singer.x - s.x, dz = singer.z - s.z, c = Math.cos(s.yaw), sn = Math.sin(s.yaw);
    rig.spot.position.x = dx * c - dz * sn;
    rig.spot.position.z = dx * sn + dz * c;
    rig.spot.visible = live;
    // fog puffs from the front of the stage, more when the song lifts
    rig.next -= dt * (live ? 2 + E * 7 : 0.4);
    while (rig.next <= 0) {
      rig.next += 1;
      const f = rig.fog.reduce((a, b) => (a.life - a.age < b.life - b.age ? a : b));
      f.age = 0; f.life = 4 + Math.random() * 3;
      f.s.position.set((Math.random() - 0.5) * s.w * 0.9, 0.16, s.d / 2 - 0.05);
      f.vx = (Math.random() - 0.5) * 0.08; f.vz = 0.06 + Math.random() * 0.1;
      f.s.visible = true;
    }
    for (const f of rig.fog) {
      if (!f.s.visible) continue;
      f.age += dt;
      if (f.age >= f.life) { f.s.visible = false; continue; }
      const u = f.age / f.life;
      f.s.position.x += f.vx * dt; f.s.position.z += f.vz * dt; f.s.position.y = 0.16 + u * 0.12;
      const k = 0.35 + u * 0.9;
      f.s.scale.set(k, k * 0.6, k);
      const m = f.s.material as THREE.SpriteMaterial;
      m.opacity = Math.min(1, u * 5) * (1 - u) * 0.55;
      m.color.setHSL((hue + 0.6) % 1, 0.35, 0.8);
    }
  }

  /** The stands fill and empty; the fans walk in from the street and back out to it; the stands bounce. */
  private dress(v: Venue, dt: number): void {
    const e = v.ev;
    const want = !e ? 0 : e.stage === 'arrive' ? Math.min(1, e.t / ARRIVE) : e.stage === 'leave' ? Math.max(0, 1 - e.t / (LEAVE * 0.8)) : 1;
    v.fill += Math.max(-dt * 0.5, Math.min(dt * 0.5, want - v.fill));
    const total = v.crowd.instanceMatrix.count;
    const people = Math.floor(v.fill * total * (e?.kind === 'concert' ? 0.97 : 0.9));
    if (v.crowd.count !== people) v.crowd.count = people;
    // the stands on their feet when it matters
    const buzz = e && e.stage === 'live' ? e.sim.buzz : 0;
    if (buzz > 0.45 || v.last === 'bouncing') {
      const m = new THREE.Matrix4(), now = performance.now() / 1000, k = Math.max(0, buzz - 0.45) * 0.07;
      for (let i = 0; i < people; i++) m.makeTranslation(v.seats[i * 3], v.seats[i * 3 + 1] + Math.max(0, Math.sin(now * 9 + i * 1.7)) * k, v.seats[i * 3 + 2]), v.crowd.setMatrixAt(i, m);
      v.crowd.instanceMatrix.needsUpdate = true;
      v.last = buzz > 0.45 ? 'bouncing' : '';
    }
    this.walkers(v, e, dt);
  }

  /** Fans on foot: from the street to the gates while the crowd comes in, and back out after. */
  private walkers(v: Venue, e: Event | null, dt: number): void {
    const n = v.walkers.n;
    const coming = e?.stage === 'arrive', going = e?.stage === 'leave' && e.t < LEAVE * 0.9;
    if (!coming && !going) {
      if (v.walk.length) { v.walk = []; v.walkers.show(0); }
      return;
    }
    const gateZ = v.plan.D / 2 - 0.15, spread = v.plan.W * 0.4;
    const ground = (x: number, z: number) => { const q = stadiumToIsland(v.b, x, z); return heightAt(v.w, q.x, q.z) - stadiumFrame(v.b).oy; };
    const spawn = (k: number) => {
      const gx = (Math.random() - 0.5) * spread * 0.6, sx = (Math.random() - 0.5) * spread * 2.2, sz = gateZ + 1.4 + Math.random() * 2.2;
      const [x, z, tx, tz] = coming ? [sx, sz, gx, gateZ] : [gx, gateZ, sx, sz];
      v.walk[k] = { x, z, tx, tz, y0: ground(x, z), y1: ground(tx, tz), k: 0, sp: 0.22 + Math.random() * 0.14 };
    };
    if (!v.walk.length) {
      // a third in the visitors' colours, a third in the home side's, the rest in whatever they own
      for (let k = 0; k < n; k++) {
        spawn(k); v.walk[k].k = Math.random();
        v.walkers.colour(k, e?.away && k % 3 === 0 ? e.away.colour : e?.away && k % 3 === 1 ? v.team.colour : SHIRTS[k % SHIRTS.length]);
      }
    }
    const shown = Math.min(n, Math.floor(n * (coming ? Math.min(1, e!.t / 4) * (1 - Math.max(0, e!.t - ARRIVE + 4) / 4) : Math.min(1, e!.t / 3) * (1 - e!.t / (LEAVE * 0.9)))));
    for (let k = 0; k < n; k++) {
      const p = v.walk[k];
      const len = Math.hypot(p.tx - p.x, p.tz - p.z) || 1;
      p.k += (p.sp * dt) / len;
      if (p.k >= 1) spawn(k);
      const q = v.walk[k], u = Math.min(1, q.k);
      const x = q.x + (q.tx - q.x) * u, z = q.z + (q.tz - q.z) * u, y = q.y0 + (q.y1 - q.y0) * u;
      v.walkers.pose(k, x, y + Math.abs(Math.sin(u * len * 30)) * 0.01, z, Math.atan2(q.tx - q.x, q.tz - q.z), 1);
    }
    v.walkers.show(shown);
  }

  // ---- for the inspector and the console ---------------------------------------------------------

  now(key: string): string | null {
    const v = this.venues.get(key);
    const e = v?.ev;
    if (e) return e.stage === 'arrive' ? `${e.title} · the crowd is arriving` : e.stage === 'leave' ? `${e.result} · over, the crowd is leaving` : `${e.sim.line()}${e.kind === 'concert' ? '' : ' · live'}`;
    const last = this.results.get(key);
    return last ? `Last time: ${last}` : null;
  }

  list(): { key: string; name: string; design: string; team: string; x: number; z: number; on: string }[] {
    return [...this.venues.values()].map((v) => {
      const c = stadiumToIsland(v.b, 0, 0);
      return { key: v.key, name: v.name, design: stadiumDesignOf(v.b), team: homeOf(v.team), x: Math.round(v.w.ox + c.x), z: Math.round(v.w.oz + c.z), on: v.ev ? `${v.ev.title}: ${v.ev.stage}` : 'quiet' };
    });
  }

  /** Start something now at the stadium nearest the camera: its sport, or a gig. */
  go(kind?: Kind): string {
    const f = this.host.focus();
    const dist = (v: Venue) => { const c = stadiumToIsland(v.b, 0, 0); return Math.hypot(v.w.ox + c.x - f.x, v.w.oz + c.z - f.z); };
    const v = [...this.venues.values()].sort((a, b) => dist(a) - dist(b))[0];
    if (!v) return 'no stadium near';
    if (v.ev) this.endEvent(v);
    this.startEvent(v, kind ?? v.plan.sport);
    v.ev!.t = ARRIVE - 4;
    return `${v.name} (${v.plan.design}): ${v.ev!.title}`;
  }

  clear(): void {
    for (const v of this.venues.values()) { this.endEvent(v); this.disposeVenue(v); }
    this.venues.clear();
    this.results.clear();
    this.tours.clear();
  }

  // ---- the save ----------------------------------------------------------------------------------

  toSave(): SportsSave {
    return {
      results: Object.fromEntries(this.overrides),
      named: Object.fromEntries(this.named),
      tours: this.tours.toSave(),
      gigs: Object.fromEntries(this.gigs),
    };
  }

  // ---- the world's league book (online) ---------------------------------------------------------

  /** Tell the world which fixtures this game is playing live now. */
  private shareLive(): void {
    if (!this.share) return;
    const mine: string[] = [];
    for (const v of this.venues.values()) if (v.ev?.fixture && !v.ev.result) mine.push(v.ev.fixture.key);
    this.share({ live: mine });
  }

  /**
   * What the world's league book says (net/leagueNet.ts). The whole book (`full`, on signing in) replaces what this
   * game had learned by itself, so its tables are everyone's; then scores, clubs and live games as they come.
   */
  fromWorld(m: LeagueShare): void {
    if (m.full) {
      for (const k of this.overrides.keys()) forgetFixture(k);
      this.overrides.clear();
      this.named.clear();
      this.worldDone.clear();
      this.worldClubs.clear();
      clearShared();
    }
    for (const [key, h, a] of m.done ?? []) {
      this.worldDone.add(key);
      this.overrides.set(key, [h, a]);
      forgetFixture(key);
    }
    while (this.overrides.size > MAX_RESULTS * 4) this.overrides.delete(this.overrides.keys().next().value!);
    for (const [key, , , town, accent, since] of m.clubs ?? []) {
      this.worldClubs.set(key, JSON.stringify([town, accent, since]));
      this.named.set(key, [town, accent ?? undefined]);
      shareSince(key, since ?? undefined);
    }
    if (m.live) {
      const own = new Set<string>();
      for (const v of this.venues.values()) if (v.ev?.fixture && !v.ev.result) own.add(v.ev.fixture.key);
      for (const k of this.worldLive) if (!own.has(k)) this.liveKeys.delete(k);
      this.worldLive = new Set(m.live);
      for (const k of this.worldLive) if (!this.worldDone.has(k)) this.liveKeys.add(k);
    }
    // a game being played live somewhere is over once its score is in
    for (const [key] of m.done ?? []) if (this.worldLive.delete(key)) this.liveKeys.delete(key);
    if (m.full) {
      // and the clubs this game can see now are told to the world again (the book may not have them)
      for (const v of this.venues.values()) this.leagueOf(v.w, v.b);
    }
  }

  /** Signed out, or a world left: the shared book goes, and this game learns for itself again. */
  leaveWorld(): void {
    this.share = null;
    this.worldDone.clear();
    this.worldClubs.clear();
    for (const k of this.worldLive) this.liveKeys.delete(k);
    this.worldLive.clear();
    clearShared();
  }

  /** A load (or a new game, with nothing): watched results, clubs met, and the tours where they had got to. */
  fromSave(s: SportsSave | undefined): void {
    this.overrides.clear();
    this.liveKeys.clear();
    this.started.clear();
    this.named.clear();
    this.gigs.clear();
    for (const [k, v] of Object.entries(s?.results ?? {})) if (Array.isArray(v)) this.overrides.set(k, [v[0], v[1]]);
    for (const [k, v] of Object.entries(s?.named ?? {})) if (Array.isArray(v)) this.named.set(k, [v[0], typeof v[1] === 'number' ? v[1] : undefined]);
    for (const [k, v] of Object.entries(s?.gigs ?? {})) if (Array.isArray(v)) this.gigs.set(k, [v[0], v[1]]);
    this.tours.fromSave(s?.tours);
  }
}

/** A sim's result line as plain text (it carries markup for the inspector). */
function stripTags(html: string): string {
  return html.replace(/<[^>]*>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim();
}
