import * as THREE from 'three';
import type { KnownAirport } from '../world/surveyor';
import { airCodeHtml } from './regionView';

/**
 * Airport codes over the world while the player flies: a little three-letter code over every
 * airport in the view (green, or blue for an international), with a chevron pointing down at its strip. They are laid over the picture
 * rather than drawn in it, so an airport five counties off — far past where the ground is drawn, or
 * lost in the haze on the horizon pitch — still shows where it is. The airports come from the
 * surveys (world/surveyor.ts), which reach well beyond the islands in memory.
 */
export class AirBeacons {
  private root = document.createElement('div');
  private els = new Map<string, HTMLElement>();
  private v = new THREE.Vector3();
  private rel = new THREE.Vector3();
  private fwd = new THREE.Vector3();

  constructor() {
    this.root.id = 'air-codes';
    this.root.hidden = true;
    document.body.append(this.root);
  }

  /** Place a code over each airport in view; `list` null (not flying, or a panel up) hides them all. */
  update(camera: THREE.Camera, list: KnownAirport[] | null, known: (a: KnownAirport) => boolean): void {
    this.root.hidden = !list;
    if (!list) return;
    const W = window.innerWidth, H = window.innerHeight;
    camera.getWorldDirection(this.fwd);
    const live = new Set<string>();
    for (const a of list) {
      const k = `${a.cx},${a.cz}:${a.name}`;
      this.v.set(a.gx, a.y + 1, a.gz);
      this.rel.copy(this.v).sub(camera.position);
      if (this.rel.dot(this.fwd) <= 1) continue;
      this.v.project(camera);
      const x = ((this.v.x + 1) / 2) * W, y = ((1 - this.v.y) / 2) * H;
      if (x < 12 || x > W - 12 || y < 24 || y > H - 4) continue;
      let el = this.els.get(k);
      if (!el) {
        el = document.createElement('div');
        el.className = a.major ? 'acode intl' : 'acode';
        el.innerHTML = airCodeHtml(a.code);
        this.root.append(el);
        this.els.set(k, el);
      }
      el.title = known(a) ? a.name : `${a.code} · airport`;
      live.add(k);
      el.hidden = false;
      // nearer airports a touch bolder, far ones fainter, so the one ahead reads first
      const d = this.rel.length();
      el.style.opacity = d < 600 ? '1' : d < 1400 ? '0.85' : '0.7';
      el.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px) translate(-50%, -100%)`;
    }
    for (const [k, el] of this.els) {
      if (live.has(k)) continue;
      if (!list.some((a) => `${a.cx},${a.cz}:${a.name}` === k)) { el.remove(); this.els.delete(k); } else el.hidden = true;
    }
  }

  clear(): void {
    for (const el of this.els.values()) el.remove();
    this.els.clear();
    this.root.hidden = true;
  }
}
