/**
 * What a mission pays in cash (the user, 11 Nov 2026): the time it should take, how hard it is, and how far into
 * the game the player is. One scale for every card, so a short hop never out-pays a long haul and a mission is
 * worth taking at any net worth:
 *
 *   cash = rate (how deep the player is, $ a minute) × minutes (the trip it asks for) × hard (what kind of work)
 *          − what the mission's own loads pay on delivery (so the two together are what the time is worth)
 *
 * - `rateAt`: a new player's minute is worth BASE_RATE (experts haul $100–180 a minute in the first hour: the
 *   fleet-size study, Oct 2026). It grows with the stage, and with net worth: WORTH_SHARE of it a minute, so an
 *   hour of missions is worth about 6% of what the company is. A player who has spent everything is still paid
 *   for the hours they have put in: net worth never counts for less than half of `expectedWorth` at that hour.
 * - `effort`: the drive from the giver through every objective at 60% of top speed with the roads' wander, the
 *   stops, the holds and the waits; and a factor for what is asked (a race can be lost, a tow needs a crew, a
 *   convoy needs the fleet in line, a clock is tight).
 * - `scalePay` sets a bound mission's cash by it (Missions.make). A chain's step never pays less than its author
 *   wrote (the stories' pay climbs act by act); a mission that pays in a vehicle or a building keeps its cash as
 *   written, times depth; one that pays in a part pays PART_SHARE of the fair figure beside it. The first drive's
 *   missions, and ones that set their own pay from this scale (`notes.paid`), are left alone.
 */
import type { Mission, Obj, PlaceRef } from './model';

/** A new player's minute, in dollars. */
export const BASE_RATE = 120;
/** What each stage (game/fit.ts stageOf, 0–4) adds to the rate, as a share of BASE_RATE. */
const STAGE_STEP = 0.25;
/** The share of net worth a minute of mission work is worth. */
const WORTH_SHARE = 0.001;
/** The most a minute is ever worth. */
const RATE_CAP = 5000;
/** The cash beside a part, as a share of the fair figure. */
const PART_SHARE = 0.6;
/** A mission's cash never falls under this share of what its time is worth, whatever its loads pay. */
const FLOOR = 0.25;
/** Cash that is not a prize: Needs More Go refunds a share of the engine's price. */
const EXEMPT = new Set(['fast:go']);
/** The roads' wander over the straight line, the share of top speed a trip is reckoned at, and its limits (tiles/s). */
const WANDER = 1.3, PACE = 0.6, TOP_MIN = 2.2, TOP_MAX = 7;
/** Seconds to pull in and load or unload; to take a card, find the way and turn round. */
const STOP_SECS = 6, OVERHEAD_SECS = 30;

/** How far into the game a player is: the stage, what the company is worth, and seconds played. */
export interface Depth { stage: number; worth?: number; played?: number }

/** What an average player's company is worth after this many hours of play: $25k at one, $100k at two, $900k at six. */
export const expectedWorth = (hours: number): number => 25000 * Math.min(10, Math.max(0, hours)) ** 2;

/** Dollars a minute of the player's own time is worth, this deep into the game. */
export function rateAt(d: Depth): number {
  const hours = (d.played ?? 0) / 3600;
  const worth = Math.max(d.worth ?? 0, 0.5 * expectedWorth(hours));
  const stage = Math.max(0, Math.min(4, d.stage));
  return Math.min(RATE_CAP, BASE_RATE * (1 + STAGE_STEP * stage) + WORTH_SHARE * worth);
}

const far = (a: { x: number; z: number }, b: { x: number; z: number }): number => Math.hypot(a.x - b.x, a.z - b.z);

/** The minutes a mission should take in a vehicle of this top speed (tiles/s), and how hard its work is (1: a plain drive). */
export function effort(m: Pick<Mission, 'objs' | 'giver'>, top: number): { minutes: number; hard: number } {
  let tiles = 0, secs = OVERHEAD_SECS, hard = 1;
  let p: { x: number; z: number } = m.giver.at;
  const go = (to: PlaceRef | { x: number; z: number }) => { tiles += far(p, to); p = to; };
  const harder = (k: number) => { hard = Math.max(hard, k); };
  for (const o of m.objs as Obj[]) {
    switch (o.t) {
      case 'deliver': {
        const n = Math.max(1, o.n);
        go(o.from);
        tiles += far(o.from, o.to) * (2 * n - 1);
        p = o.to;
        secs += STOP_SECS * 2 * n;
        harder((o.clock ? 1.25 : o.ride ? 1.1 : 1) * (1 + 0.35 * (o.with ?? 0)));
        break;
      }
      case 'reach': {
        go(o.at);
        secs += (o.hold ?? 0) + (o.after !== undefined ? 60 : 0) + (o.hidden ? 90 : 0);
        harder((o.hidden ? 1.3 : o.dived ? 1.2 : o.ride || o.low ? 1.1 : 1) * (1 + 0.35 * (o.with ?? 0)));
        break;
      }
      case 'race': go(o.from); go(o.to); harder(1.2 + 0.15 * o.tier); break;
      // a load is dragged at a third of the pace, with a crew on the ropes
      case 'tow': go(o.from); tiles += far(o.from, o.to) * 3; p = o.to; secs += 30; harder(1.3 + 0.25 * o.min); break;
      case 'op': go(o.at); tiles += o.r * 4; if (o.to) go(o.to); secs += 90; harder(1.3); break;
      case 'lap': go(o.at); secs += o.secs * 3; harder(1.3); break;
      case 'grid': go(o.at); secs += 240; harder(1.4); break;
      case 'tail': {
        go(o.at);
        let q: { x: number; z: number } = o.at, run = 0;
        for (const l of o.legs) { run += far(q, l); q = l; }
        tiles += (run + far(q, o.to)) * 1.5;
        p = o.to;
        harder(1.3);
        break;
      }
      case 'ram': go(o.at); secs += 20; harder(1.1); break;
      case 'visit': if (o.at) go(o.at); break;
      case 'ferry': if (o.at) go(o.at); secs += 120; break;
      // out and not back: the way home is the player's own business
      case 'range': tiles += o.tiles * 0.7; break;
      case 'discover': tiles += o.n * 320; break;
      case 'loads': secs += o.n * 180; break;
      // the fleet's work goes on while the player does something else: a little of their time, not all of it
      case 'fleet': secs += 120; break;
      case 'own': case 'hq': case 'driving': case 'fit': case 'make': case 'crew': case 'speed': case 'drift': secs += 60; break;
    }
  }
  const speed = Math.max(TOP_MIN, Math.min(TOP_MAX, top || TOP_MIN)) * PACE;
  return { minutes: (tiles * WANDER) / speed / 60 + secs / 60, hard };
}

/** A figure a card can show: to the nearest $10, or $50 past two thousand. */
export const tidy = (n: number): number => (n >= 2000 ? Math.round(n / 50) * 50 : Math.max(10, Math.round(n / 10) * 10));

/** The fair cash for a job of this many tiles and seconds, this hard, for a player this deep (a tavern's job, say). */
export function fairCash(d: Depth, top: number, tiles: number, secs: number, hard: number): number {
  const speed = Math.max(TOP_MIN, Math.min(TOP_MAX, top || TOP_MIN)) * PACE;
  return tidy(rateAt(d) * ((tiles * WANDER) / speed / 60 + (secs + OVERHEAD_SECS) / 60) * hard);
}

/** Set a bound mission's cash by the scale. Returns the mission. */
export function scalePay<M extends Pick<Mission, 'objs' | 'giver' | 'reward' | 'tpl' | 'arc' | 'notes'>>(m: M, d: Depth, top: number): M {
  if (m.tpl.startsWith('first:') || m.notes?.paid) return m;
  const k = m.reward.findIndex((r) => r.r === 'cash');
  if (k < 0) return m;
  const cash = m.reward[k];
  if (cash.r !== 'cash') return m;
  if (EXEMPT.has(m.tpl)) return m;
  const rate = rateAt(d), depth = rate / BASE_RATE;
  const e = effort(m, top);
  // the loads pay their own value on delivery: the mission's cash is the rest of what the time is worth, never under FLOOR of it
  const loads = (m.objs as Obj[]).reduce((s, o) => s + (o.t === 'deliver' ? o.value * Math.max(1, o.n) + (o.also?.value ?? 0) : 0), 0);
  const worth = rate * e.minutes * e.hard;
  const fair = Math.max(worth - loads, worth * FLOOR);
  const thing = m.reward.some((r) => r.r === 'vehicle' || r.r === 'building');
  const part = m.reward.some((r) => r.r === 'part');
  const n = tidy(thing ? cash.n * depth : m.arc ? Math.max(cash.n * depth, fair * (part ? PART_SHARE : 1)) : fair * (part ? PART_SHARE : 1));
  m.reward = m.reward.map((r, i) => (i === k ? { r: 'cash', n } : r));
  // a card that names its prize ("the prize is $900") says the new one
  if (n !== cash.n) {
    const was = [`$${cash.n.toLocaleString('en-US')}`, `$${cash.n}`], now = `$${n.toLocaleString('en-US')}`;
    const say = (t: string | undefined): string | undefined => (t ? was.reduce((q, w) => q.split(w).join(now), t) : t);
    const card = m as unknown as { why?: string; details?: string };
    card.why = say(card.why);
    card.details = say(card.details);
  }
  return m;
}
