import { N, SEA, STEP, Biome, DIRS, Feature, Flag, Lot, World, idx, inB, type Building, type BuildingKind } from './tiles';
import type { Rng } from './rng';
import type { TownPlan } from './towns';
import type { WorkSite } from './industry';
import { landformName } from './landforms';
import { buildingHeight } from './towns';
import { solidMask } from './footprint';
import { KIND_SPEC } from './townKinds';
import { INFO_080, type Kind080 } from './kinds080';

/**
 * The beachfront (0.8.0, NEXT_080, docs/phonelist.html item 15): a warm coastal town's pier, built out from its beach
 * over the sea: a fishing pier off a village, a pleasure pier (the wheel, the helter-skelter, kiosks, a pavilion at the
 * end) off a city, a grand pier with a rollercoaster too off a big city. Lifeguard towers and volleyball courts stand
 * on the sand either side of it.
 *
 * The pier is laid as the wonder's pier is (world/wonders.ts `pier`): its seaward run raised out of the sea as a deck
 * level with the beach, its sides walls into the water, at the same stage, before the corners, on a stream of its own.
 * It stands as a work of its own (kind 'resort', with its lot), so a paved road comes to its gate on the shore.
 */

export const PIER_SALT = 0x91e7;
/** Out of every hundred warm coastal towns of each kind, how many build a pier. */
const CHANCE: Record<string, number> = { rural: 0.3, suburb: 0.35, city: 0.6, metro: 0.7, mega: 0.75 };
/** Warm enough for a beach town (w.temp, which runs warm: most land sits about 0.9). */
const WARM = 0.72;
const MAX_PIERS = 2;
/** Tiles of the lot on the land, behind the beach. */
const INLAND = 3;
/** How far from a town's square its pier's root may be. */
const REACH = 16;
/** Tiles a pier's root keeps from a harbour's. */
const PORT_CLEAR = 13;

const SIZE: Record<string, Kind080> = { rural: 'fishingPier', suburb: 'fishingPier', city: 'pleasurePier080', metro: 'grandPier', mega: 'grandPier' };
export const PIER_KINDS = new Set<string>(['fishingPier', 'pleasurePier080', 'grandPier']);

/** Plan the county's piers, carving their decks out of the sea. Returns their work sites (with lots). */
export function planPiers(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, plans: TownPlan[], ports: readonly { x: number; z: number }[], band: number, rng: Rng): WorkSite[] {
  const out: WorkSite[] = [];
  const lo = band + 6;
  for (const p of plans) {
    if (out.length >= MAX_PIERS) break;
    const kind = SIZE[p.kind];
    if (!kind || rng() >= (CHANCE[p.kind] ?? 0)) continue;
    // warm, and on the coast
    let temp = 0, n = 0;
    for (let z = p.z0; z < p.z0 + p.size; z += 3) for (let x = p.x0; x < p.x0 + p.size; x += 3) if (inB(x, z)) { temp += w.temp[idx(x, z)]; n++; }
    if (!n || temp / n < WARM) continue;
    const [W, D] = INFO_080[kind].size;
    const outward = D - INLAND;
    let best: { x: number; z: number; d: number; score: number } | null = null;
    for (let z = p.z0 - REACH; z < p.z0 + p.size + REACH; z++) {
      for (let x = p.x0 - REACH; x < p.x0 + p.size + REACH; x++) {
        if (!inB(x, z)) continue;
        const i = idx(x, z);
        if (!land[i] || w.coastDist[i] !== 1 || river[i] || w.biome[i] === Biome.Town) continue;
        // well clear of a harbour's quays and cranes
        if (ports.some((q) => Math.hypot(q.x - x, q.z - z) < PORT_CLEAR)) continue;
        for (let d = 0; d < 4; d++) {
          const [dx, dz] = DIRS[d];
          const px = -dz, pz = dx;
          let ok = true;
          for (let k = -INLAND + 1; k <= outward && ok; k++) {
            for (let o = -(W >> 1); o <= ((W - 1) >> 1) && ok; o++) {
              const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
              if (tx < lo || tz < lo || tx >= N - lo || tz >= N - lo) { ok = false; break; }
              const j = idx(tx, tz);
              if (k <= 0) ok = !!land[j] && w.biome[j] !== Biome.Town && Math.abs(E[j] - SEA - 1) < 2.5 && !river[j] && !w.feature[j];
              else ok = !land[j] && E[j] < SEA;
            }
          }
          // open water either side of the seaward run
          for (let k = 2; k <= outward && ok; k += 2) {
            for (const o of [-(W >> 1) - 2, ((W - 1) >> 1) + 2]) {
              const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
              if (!inB(tx, tz) || land[idx(tx, tz)]) ok = false;
            }
          }
          if (!ok) continue;
          // nearest the town's middle, on a sandy beach for choice
          const cx = p.x0 + p.size / 2, cz = p.z0 + p.size / 2;
          const score = Math.hypot(x - cx, z - cz) - (w.biome[i] === Biome.Beach ? 6 : 0) + rng() * 2;
          if (!best || score < best.score) best = { x, z, d, score };
        }
      }
    }
    if (!best) continue;
    const [dx, dz] = DIRS[best.d];
    const px = -dz, pz = dx;
    let x0 = N, z0 = N, x1 = -1, z1 = -1;
    for (let k = -INLAND + 1; k <= outward; k++) {
      for (let o = -(W >> 1); o <= ((W - 1) >> 1); o++) {
        const tx = best.x + dx * k + px * o, tz = best.z + dz * k + pz * o;
        const j = idx(tx, tz);
        land[j] = 1;
        E[j] = SEA + 1;
        if (k > 0) w.flags[j] |= Flag.Corridor;
        w.biome[j] = Biome.Town;
        w.lot[j] = Lot.Deck;
        w.cleared[j] = 1;
        river[j] = 0;
        x0 = Math.min(x0, tx); z0 = Math.min(z0, tz); x1 = Math.max(x1, tx); z1 = Math.max(z1, tz);
      }
    }
    const wx = x1 - x0 + 1, wz = z1 - z0 + 1;
    const gx = best.x - dx * INLAND, gz = best.z - dz * INLAND;
    const word = landformName('crossing', Math.floor(rng() * 2 ** 31), w.ox + best.x, w.oz + best.z);
    out.push({
      kind: 'resort', name: `${word} ${kind === 'fishingPier' ? 'Fishing Pier' : 'Pier'}`, x: Math.floor(x0 + wx / 2), z: Math.floor(z0 + wz / 2),
      level: SEA + 1, facing: best.d, major: kind !== 'fishingPier', len: Math.max(wx, wz), half: Math.min(wx, wz) / 2, cable: [],
      gate: idx(Math.max(0, Math.min(N - 1, gx)), Math.max(0, Math.min(N - 1, gz))),
      lot: { kind, x: x0, z: z0, w: wx, d: wz },
    });
  }
  return out;
}

/**
 * The sand either side of each pier, once the towns are built (generate.ts, in the 0.8.0 block): lifeguard towers every
 * few tiles back from the water, a volleyball court. Returns how many went up.
 */
export function dressBeaches(w: World, rng: Rng): number {
  let n = 0;
  const piers = w.works.filter((g) => g.kind === 'resort' && g.buildings.some((b) => PIER_KINDS.has(b.kind)));
  const sand = (x: number, z: number) => {
    if (!inB(x, z)) return false;
    const i = idx(x, z);
    return (w.biome[i] === Biome.Beach || w.feature[i] === Feature.Beach) && w.water[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && !w.lot[i]
      && !(w.flags[i] & (Flag.Poi | Flag.Field | Flag.Track | Flag.Corridor)) && w.coastDist[i] >= 1 && w.coastDist[i] <= 4;
  };
  for (const g of piers) {
    const b = g.buildings.find((q) => PIER_KINDS.has(q.kind))!;
    const [dx, dz] = DIRS[g.facing];
    const px = -dz, pz = dx;
    // the pier's root on the shore: the landward end of its lot
    const long = Math.max(b.w, b.d);
    const cx = b.x + (b.w - 1) / 2, cz = b.z + (b.d - 1) / 2;
    const root = { x: Math.round(cx - dx * (long / 2 - INLAND)), z: Math.round(cz - dz * (long / 2 - INLAND)) };
    for (const side of [-1, 1]) {
      let towers = 0, courts = 0;
      for (let along = Math.ceil(Math.min(b.w, b.d) / 2) + 3; along <= 34 && (towers < 3 || courts < 1); along++) {
        for (const back of [2, 1, 3]) {
          const x = root.x + px * side * along - dx * back, z = root.z + pz * side * along - dz * back;
          if (towers < 3 && along % 9 === 5 && sand(x, z)) {
            if (put(w, rng, 'lifeguardTower', x, z, 1, 1, g.facing)) { towers++; n++; }
            break;
          }
          if (courts < 1 && along % 9 === 1 && sand(x, z) && sand(x + px, z + pz)) {
            const bx = Math.min(x, x + px), bz = Math.min(z, z + pz);
            if (put(w, rng, 'volleyCourt', bx, bz, Math.abs(px) + 1, Math.abs(pz) + 1, g.facing)) { courts++; n++; }
            break;
          }
        }
      }
    }
  }
  return n;
}

/** A building out in the country (on the sand, a headland), as world/countryside.ts puts one. */
export function put(w: World, r: Rng, kind: BuildingKind, x: number, z: number, wx: number, wz: number, facing: number): Building | null {
  const solid = KIND_SPEC[kind]?.solid !== false;
  let sum = 0;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
  const level = Math.round(sum / (wx * wz * 4));
  const b: Building = { kind, x, z, w: wx, d: wz, facing, floors: 1, seed: Math.floor(r() * 2 ** 31), solid, level, uid: w.allBuildings.length };
  w.allBuildings.push(b);
  w.countryside.push(b);
  const top = level * STEP + buildingHeight(b);
  const mask = solid ? solidMask(b) : null;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  return b;
}
