import { N, STEP, World, heightAt, heightOnTile, idx, inB, waterDepth } from './tiles';
import { railBedAt, railDeckAt } from './railSurface';
import { ROAD_INFO, deckSurfaceAt } from './roads';
import { circuitLift } from './circuits';

/**
 * What something stands on at a point: a bridge deck, a railway's ballast or deck, a road's painted
 * surface, or the bare ground. `CarState.surf` answers the same question for the car itself, but it
 * leans on the flags the car keeps as it drives (whether it stepped onto a deck); this one is for
 * anything that only knows where it is — a trailer swinging behind a semi, above all.
 *
 * Where a tile carries both a deck and ground (a bridge over a valley, a flyover over a road), the one
 * nearest `near` wins, so a trailer on a bridge rides the deck and one that has just come off it rides
 * the ground, without either being dragged down through the other.
 */
function surfaceUnder(w: World, x: number, z: number, near: number): number {
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return heightAt(w, x, z);
  const i = idx(tx, tz);
  // a circuit's banking lifts the track, as it lifts the car (CarState.surf)
  const ground = railBedAt(w, tx, tz, x, z, heightOnTile(w, tx, tz, x, z)) + circuitLift(w, x, z);
  const road = w.road[i];
  let best = road ? ground + ROAD_INFO[road].lift : ground;
  // afloat: a boat's trailer, and anything sitting on the water rather than under it
  if (!road && waterDepth(w, i) > 0) best = Math.max(best, w.water[i] * STEP - 0.035);
  let gap = Math.abs(best - near);
  const decks: number[] = [];
  if (w.deckAxis[i]) decks.push(deckSurfaceAt(w, i, x, z));
  const rail = railDeckAt(w, tx, tz, x, z);
  if (rail !== null) decks.push(rail);
  for (const d of decks) {
    const g = Math.abs(d - near);
    if (g < gap) { gap = g; best = d; }
  }
  return best;
}

/** The same, clamped to the island: a point off the edge keeps the height of the nearest tile. */
export function surfaceNear(w: World, x: number, z: number, near: number): number {
  return surfaceUnder(w, Math.min(N - 0.001, Math.max(0, x)), Math.min(N - 0.001, Math.max(0, z)), near);
}
