import { cellKind, cellName } from '../world/macro';
import { hashString, mulberry32, type Rng } from '../world/rng';
import { DAYS_PER_YEAR } from '../render/season';
import { SPORT_NAME, actFor, teamOf, type Act, type Sport, type Team } from '../world/stadiums';

/**
 * Leagues, seasons and the touring acts (docs/stadiums.html covers the stadiums themselves).
 *
 * Everything here is pure and deterministic from the world seed, so it answers for counties nobody has
 * been to and costs nothing to keep: a league is the counties of a BLOCK × BLOCK block of the cell
 * lattice, one club a county (named for the county until its real stadium team has been met), playing a
 * single round robin in the sport's season. A fixture's score is played out of the two clubs' form for
 * that season and a hash of the match; a game the player watches live replaces it (game/stadiums.ts keeps
 * those, and the save does). History goes back to the league's founding, before the world began.
 *
 * Online, every game shows the same leagues: the fixtures and the played-out scores are the seed's and the clock is
 * the server's, and the three things a game learns as it goes are the world's (server/leagues.ts, net/leagueNet.ts):
 * a watched game's score (the first game to finish it says it for everyone), a club's real team once anyone has met
 * it, and a club founded during play (`shareSince`, for leagues whose county nobody here has loaded).
 *
 * The acts are a pool of a dozen per world, each with a name, a genre, a draw and a career before day 0;
 * game/tours.ts sends them round the stadiums and adds what they do to that.
 */

/** Cells a side in a league's block. */
export const BLOCK = 3;
/** When each sport's season runs: the day of the year it starts (0 spring … 3 winter) and how many days it lasts. */
export const SPAN: Record<Sport, { off: number; len: number }> = {
  soccer: { off: 2, len: 3 }, football: { off: 2, len: 2 }, baseball: { off: 0, len: 2 },
};
/** Game hours after kick-off before an unwatched fixture's result is in. */
export const RESULT_LAG = 2.5;
/** The fewest clubs a league runs with: open ocean lends it clubs from further off. */
const MIN_CLUBS = 4;
const FAR_PLACES = ['Port Ellis', 'Hollow Creek', 'Marrowby', 'Easton Vale', 'Kingsferry', 'Redwater', 'Ashby Cross', 'Fairhaven'];

const u01 = (h: number): number => (h >>> 0) / 4294967296;
const sgn = (s: string): number => u01(hashString(s)) * 2 - 1;

/** A county's name as a club would carry it: "Bramblereach Island" plays as Bramblereach. */
function trimPlace(name: string): string {
  return name.replace(/^the /i, '').replace(/ (Island|Isle|Land|Key|Rock|Skerry|Reef|Cay|Atoll|Caldera|Deep)$/, '');
}

// ---- seasons ------------------------------------------------------------------------------------

interface SeasonSpan { k: number; start: number; end: number; inSeason: boolean }

/** The season of a sport that is on now (or, out of season, the last one), in game hours. */
export function seasonAt(sport: Sport, hours: number): SeasonSpan {
  const { off, len } = SPAN[sport];
  const k = Math.floor((hours / 24 - off) / DAYS_PER_YEAR);
  const start = (k * DAYS_PER_YEAR + off) * 24, end = start + len * 24;
  return { k, start, end, inSeason: hours < end };
}
export const seasonStart = (sport: Sport, k: number): number => (k * DAYS_PER_YEAR + SPAN[sport].off) * 24;
export const seasonEnd = (sport: Sport, k: number): number => seasonStart(sport, k) + SPAN[sport].len * 24;

// ---- leagues ------------------------------------------------------------------------------------

export interface Club {
  slot: number; cx: number; cz: number; place: string; team: Team;
  /**
   * A club founded during play (a stadium of its sport built in a county that had none, game/stadiums.ts): the
   * game hour it was founded. It plays no fixture before then and is in no season that ended before it, so its
   * record and its history start from nothing. Missing for the clubs that were always there.
   */
  since?: number;
}
export interface League {
  id: string; sport: Sport; name: string; clubs: Club[];
  /** The season index of its first season (before day 0, so a new world has history). */
  founded: number;
}

const LEAGUES = new Map<string, League>();
/** Clubs founded during play that the world knows of (online, server/leagues.ts), by `league id|slot`: put on a league as it is made. */
const SINCE = new Map<string, number>();

/** The league of a sport that the county (cx, cz) plays in. */
export function leagueFor(sh: number, sport: Sport, cx: number, cz: number): League {
  const L = blockLeague(sh, sport, Math.floor(cx / BLOCK), Math.floor(cz / BLOCK));
  if (!L.clubs.some((c) => c.cx === cx && c.cz === cz)) addClub(sh, L, cx, cz);
  return L;
}

/** A league from its id (`seed hash:sport:bx,bz`), as the server checks a reported result against it; null for no such league. */
export function leagueById(id: string): League | null {
  const m = /^(-?\d+):(soccer|football|baseball):(-?\d+),(-?\d+)$/.exec(id);
  return m ? blockLeague(Number(m[1]), m[2] as Sport, Number(m[3]), Number(m[4])) : null;
}

function blockLeague(sh: number, sport: Sport, bx: number, bz: number): League {
  const id = `${sh}:${sport}:${bx},${bz}`;
  let L = LEAGUES.get(id);
  if (L) return L;
  const cells: [number, number][] = [];
  for (let dz = 0; dz < BLOCK; dz++) for (let dx = 0; dx < BLOCK; dx++) {
    const x = bx * BLOCK + dx, z = bz * BLOCK + dz;
    if (cellKind(sh, x, z) !== 'sea') cells.push([x, z]);
  }
  if (cells.length < MIN_CLUBS) {
    // a block that is mostly sea borrows the nearest counties round it
    const ring: [number, number][] = [];
    for (let z = bz * BLOCK - 1; z <= bz * BLOCK + BLOCK; z++) for (let x = bx * BLOCK - 1; x <= bx * BLOCK + BLOCK; x++) {
      const inside = x >= bx * BLOCK && x < bx * BLOCK + BLOCK && z >= bz * BLOCK && z < bz * BLOCK + BLOCK;
      if (!inside && cellKind(sh, x, z) !== 'sea') ring.push([x, z]);
    }
    ring.sort((p, q) => hashString(`${id}|${p}`) - hashString(`${id}|${q}`));
    while (cells.length < MIN_CLUBS && ring.length) cells.push(ring.shift()!);
  }
  const centre = [bx * BLOCK + 1, bz * BLOCK + 1] as const;
  const region = trimPlace(cellName(sh, centre[0], centre[1], cellKind(sh, centre[0], centre[1])));
  L = { id, sport, name: `${region} ${SPORT_NAME[sport]} League`, clubs: [], founded: -(12 + (hashString(`${id}|founded`) % 48)) };
  for (const [x, z] of cells) addClub(sh, L, x, z);
  // open ocean all round: clubs from far away make up the numbers
  for (let k = 0; L.clubs.length < MIN_CLUBS; k++) {
    const place = FAR_PLACES[(hashString(id) + k) % FAR_PLACES.length];
    L.clubs.push({ slot: L.clubs.length, cx: 1e6 + k, cz: 1e6, place, team: teamOf(place) });
  }
  for (const c of L.clubs) { const s = SINCE.get(`${id}|${c.slot}`); if (s !== undefined) c.since = s; }
  LEAGUES.set(id, L);
  return L;
}

/**
 * The world says a club was founded during play at this hour (or never was, undefined): kept for a league not made
 * yet, put on one that is.
 */
export function shareSince(clubKey: string, hour: number | undefined): void {
  const i = clubKey.lastIndexOf('|');
  if (i < 0) return;
  if (hour === undefined) SINCE.delete(clubKey); else SINCE.set(clubKey, hour);
  const L = LEAGUES.get(clubKey.slice(0, i));
  if (L) setFounded(L, Number(clubKey.slice(i + 1)), hour);
}
/** A new world (or the shared book read again): no club known founded but by what this game sees. */
export function clearShared(): void { SINCE.clear(); }

function addClub(sh: number, L: League, cx: number, cz: number): void {
  let place = trimPlace(cellName(sh, cx, cz, cellKind(sh, cx, cz)));
  // two counties of one name in a block: the second is told apart by which side of the first it lies
  const twin = L.clubs.find((c) => c.place === place);
  if (twin) place += Math.abs(cx - twin.cx) >= Math.abs(cz - twin.cz) ? (cx > twin.cx ? ' East' : ' West') : (cz > twin.cz ? ' South' : ' North');
  L.clubs.push({ slot: L.clubs.length, cx, cz, place, team: teamOf(place) });
}

/** Is the club in the league in season k: always, for one that was always there; for a new one, from the season it was founded in. */
const playsIn = (L: League, slot: number, k: number): boolean => {
  const s = L.clubs[slot]?.since;
  return s === undefined || s < seasonEnd(L.sport, k);
};

/**
 * Found a club during play, from this game hour (or undo it with undefined): its old played-out record is gone
 * and the league's kept final tables are worked out again.
 */
export function setFounded(L: League, slot: number, hour: number | undefined): void {
  const c = L.clubs[slot];
  if (!c || c.since === hour) return;
  c.since = hour;
  for (const k of [...FINALS.keys()]) if (k.startsWith(`${L.id}|`)) FINALS.delete(k);
}

/** The club of a county in its league, or -1. */
export const slotOf = (L: League, cx: number, cz: number): number => L.clubs.findIndex((c) => c.cx === cx && c.cz === cz);

// ---- fixtures and results -----------------------------------------------------------------------

export interface Fixture { round: number; at: number; home: number; away: number }
export interface Played extends Fixture { hs: number; as: number; live: boolean }

/** The season's fixtures: a single round robin (the circle method), kick-offs spread over its days between 11:00 and 21:00. */
const FIXTURES = new Map<string, Fixture[]>();
export function fixtures(L: League, k: number): Fixture[] {
  const key = `${L.id}|${k}|${L.clubs.length}`;
  let list = FIXTURES.get(key);
  if (!list) {
    if (FIXTURES.size > 400) FIXTURES.clear();
    FIXTURES.set(key, (list = drawFixtures(L, k)));
  }
  return list;
}
function drawFixtures(L: League, k: number): Fixture[] {
  const n = L.clubs.length, m = n % 2 ? n + 1 : n;
  const rounds = m - 1, { len } = SPAN[L.sport];
  const perDay = Math.ceil(rounds / len);
  const hours = perDay === 1 ? [16] : Array.from({ length: perDay }, (_, j) => 11 + (j * 10) / (perDay - 1));
  const start = seasonStart(L.sport, k);
  // the order the clubs are drawn in changes every season
  const order = Array.from({ length: m }, (_, i) => i);
  const r = mulberry32(hashString(`${L.id}|draw|${k}`));
  for (let i = m - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const out: Fixture[] = [];
  for (let round = 0; round < rounds; round++) {
    const rot = [order[0], ...order.slice(1).map((_, i) => order[1 + ((i + round) % (m - 1))])];
    const at = start + Math.floor(round / perDay) * 24 + hours[round % perDay];
    for (let i = 0; i < m / 2; i++) {
      let a = rot[i], b = rot[m - 1 - i];
      if (a >= n || b >= n) continue; // the bye
      if ((round + i + k) % 2) [a, b] = [b, a];
      out.push({ round, at, home: a, away: b });
    }
  }
  return out;
}

/** The key a fixture's live result is kept under. */
export const fixtureKey = (L: League, k: number, f: Fixture): string => `${L.id}|${k}|${f.round}|${f.home}`;

/** A fixture from its key, as the server checks a reported score: its league, season and the fixture itself, or null. */
export function fixtureOf(key: string): { L: League; k: number; f: Fixture } | null {
  const m = /^([^|]+)\|(-?\d+)\|(\d+)\|(\d+)$/.exec(key);
  const L = m ? leagueById(m[1]) : null;
  if (!m || !L) return null;
  const k = Number(m[2]), round = Number(m[3]), home = Number(m[4]);
  const f = fixtures(L, k).find((x) => x.round === round && x.home === home);
  return f ? { L, k, f } : null;
}

/** The most a side scores in a game of each sport that a report may claim (the sims never come near). */
export const MAX_SCORE: Record<Sport, number> = { soccer: 20, football: 120, baseball: 40 };

/** A club's form in a season, about -1.2 to 1.2: a lasting standing, an era, and the year itself. */
export function strength(L: League, slot: number, k: number): number {
  return 0.6 * sgn(`${L.id}|base|${slot}`) + 0.3 * sgn(`${L.id}|era|${slot}|${Math.floor(k / 6)}`) + 0.3 * sgn(`${L.id}|yr|${slot}|${k}`);
}

function poisson(r: Rng, mean: number): number {
  const lim = Math.exp(-Math.max(0.05, mean));
  let p = 1, n = -1;
  do { n++; p *= r(); } while (p > lim && n < 30);
  return n;
}

/** An unwatched fixture played out of the two clubs' form: goals, points or runs, home first. */
function playOut(sport: Sport, sh: number, sa: number, seed: number): [number, number] {
  const r = mulberry32(seed >>> 0);
  const d = sh - sa;
  if (sport === 'soccer') return [poisson(r, 1.4 + 0.45 * d + 0.15), poisson(r, 1.25 - 0.45 * d)];
  if (sport === 'football') {
    const side = (edge: number) => {
      let pts = 0;
      for (let k = 0; k < 11; k++) {
        const x = r();
        if (x < 0.19 + 0.08 * edge) pts += r() < 0.94 ? 7 : 6;
        else if (x < 0.31 + 0.08 * edge) pts += 3;
      }
      return pts;
    };
    return [side(d + 0.15), side(-d)];
  }
  let h = poisson(r, 4.3 + 1.1 * d + 0.2), a = poisson(r, 4.3 - 1.1 * d);
  // baseball plays on until somebody wins
  if (h === a) { if (r() < 0.5 + 0.15 * d) h++; else a++; }
  return [h, a];
}

/** Live results the player watched, by fixtureKey: what replaces the played-out score. */
export type Overrides = Map<string, [number, number]>;

/** A season's results in by `upTo` (game hours): a watched game's own score, else the played-out one; `skip` leaves out games still being played. */
export function results(L: League, k: number, upTo: number, live: Overrides, skip?: Set<string>): Played[] {
  const out: Played[] = [];
  const since = (slot: number) => L.clubs[slot]?.since ?? -Infinity;
  for (const f of fixtures(L, k)) {
    const key = fixtureKey(L, k, f);
    if (skip?.has(key)) continue;
    // a club founded during play has no games from before it was founded: its opponent has a bye
    if (since(f.home) > f.at || since(f.away) > f.at) continue;
    const o = live.get(key);
    if (o) { out.push({ ...f, hs: o[0], as: o[1], live: true }); continue; }
    if (f.at + RESULT_LAG > upTo) continue;
    const [hs, as] = playOut(L.sport, strength(L, f.home, k), strength(L, f.away, k), hashString(key));
    out.push({ ...f, hs, as, live: false });
  }
  return out;
}

export interface Row { club: number; p: number; w: number; d: number; l: number; pf: number; pa: number; pts: number }

/** Soccer counts three for a win and one for a draw; the others go by wins (a tie half a win). */
export function table(L: League, played: Played[], k?: number): Row[] {
  // season k's clubs: a club founded later than the season ended is not in it
  const rows: Row[] = L.clubs.filter((c) => k === undefined || playsIn(L, c.slot, k)).map((c) => ({ club: c.slot, p: 0, w: 0, d: 0, l: 0, pf: 0, pa: 0, pts: 0 }));
  const of = new Map(rows.map((r) => [r.club, r]));
  for (const g of played) {
    const h = of.get(g.home), a = of.get(g.away);
    if (!h || !a) continue;
    h.p++; a.p++; h.pf += g.hs; h.pa += g.as; a.pf += g.as; a.pa += g.hs;
    if (g.hs > g.as) { h.w++; a.l++; } else if (g.hs < g.as) { a.w++; h.l++; } else { h.d++; a.d++; }
  }
  for (const r of rows) r.pts = L.sport === 'soccer' ? r.w * 3 + r.d : r.w + r.d * 0.5;
  const pct = (r: Row) => (L.sport === 'soccer' ? r.pts : r.p ? r.pts / r.p : 0);
  return rows.sort((a, b) => pct(b) - pct(a) || (b.pf - b.pa) - (a.pf - a.pa) || b.pf - a.pf || a.club - b.club);
}

/** "3–2–1" for soccer (won, drawn, lost), "4–2" for the others (a tie on the end when there was one). */
export function recordText(sport: Sport, r: { w: number; d: number; l: number }): string {
  return sport === 'soccer' ? `${r.w}–${r.d}–${r.l}` : `${r.w}–${r.l}${r.d ? `–${r.d}` : ''}`;
}
export const ordinal = (n: number): string => `${n}${n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] ?? 'th'}`;
/** A season as people number it: the league's first was Season 1. */
export const seasonLabel = (L: League, k: number): number => k - L.founded + 1;

// ---- history ------------------------------------------------------------------------------------

/** A finished season's final table, kept: history is asked for every refresh of the card. */
const FINALS = new Map<string, Row[]>();

export function finalTable(L: League, k: number, live: Overrides): Row[] {
  const key = `${L.id}|${k}|${L.clubs.length}`;
  let t = FINALS.get(key);
  if (!t) FINALS.set(key, (t = table(L, results(L, k, Infinity, live), k)));
  return t;
}
/** A live result has come in for season k: its kept final table is out of date. */
export function forgetSeason(L: League, k: number): void { FINALS.delete(`${L.id}|${k}|${L.clubs.length}`); }
/** The same from a fixture's key alone (a result the world sent): every kept table of that league's season. */
export function forgetFixture(key: string): void {
  const [id, k] = key.split('|');
  for (const f of [...FINALS.keys()]) if (f.startsWith(`${id}|${k}|`)) FINALS.delete(f);
}

interface SeasonLine { k: number; label: number; pos: number; of: number; row: Row; champion: number }
export interface History {
  seasons: number; titles: number; best: SeasonLine | null;
  /** The label of the first season counted (1 for a club that was always there), 0 for none. */
  first: number;
  w: number; d: number; l: number; pf: number; pa: number;
  /** The last few finished seasons, newest first. */
  recent: SeasonLine[];
  /** Seasons won, newest first. */
  won: number[];
}

/** A club's whole history: every finished season since the league was founded, up to (not including) season `before`. */
export function history(L: League, slot: number, before: number, live: Overrides, keep = 6): History {
  const h: History = { seasons: 0, titles: 0, best: null, first: 0, w: 0, d: 0, l: 0, pf: 0, pa: 0, recent: [], won: [] };
  for (let k = L.founded; k < before; k++) {
    const t = finalTable(L, k, live);
    const pos = t.findIndex((r) => r.club === slot);
    if (pos < 0) continue;
    const row = t[pos];
    h.seasons++;
    if (!h.first) h.first = seasonLabel(L, k);
    h.w += row.w; h.d += row.d; h.l += row.l; h.pf += row.pf; h.pa += row.pa;
    const line: SeasonLine = { k, label: seasonLabel(L, k), pos: pos + 1, of: t.length, row, champion: t[0].club };
    if (pos === 0) { h.titles++; h.won.unshift(line.label); }
    if (!h.best || line.pos < h.best.pos || (line.pos === h.best.pos && row.w > h.best.row.w)) h.best = line;
    h.recent.unshift(line);
    if (h.recent.length > keep) h.recent.pop();
  }
  return h;
}

// ---- the touring acts ---------------------------------------------------------------------------

const GENRES = ['indie rock', 'synth-pop', 'country', 'hip hop', 'folk', 'heavy metal', 'soul', 'dance', 'jazz fusion', 'punk', 'R&B', 'pop'];
const ACT_COLOURS: [number, number][] = [
  [0xe2412f, 0xffd166], [0x6a3bff, 0x19d3ff], [0x1f2329, 0xff3fa4], [0x2f8f4a, 0xf4f2ec], [0xf28c1e, 0x1f2a5a],
  [0xc4246b, 0xf2c14e], [0x0f7c8c, 0xffffff], [0x8a1c2b, 0xd9a441], [0x2aa6de, 0xf4f2ec], [0x5b2d8e, 0x3dff6a],
];
const WORDS_A = ['Neon', 'Paper', 'Summer', 'Highway', 'Satellite', 'Golden', 'Midnight', 'Harbour', 'Electric', 'Last', 'Velvet', 'Silver', 'Ocean', 'Radio', 'City', 'Wildfire'];
const WORDS_B = ['Hearts', 'Lights', 'Static', 'Skyline', 'Dreams', 'Rain', 'Avenue', 'Fever', 'Sunset', 'Echoes', 'Signals', 'Days', 'Waves', 'Ghosts', 'Roads', 'Gold'];
/** Acts in a world's pool. */
export const ACTS = 12;

export interface TourAct extends Act {
  id: number;
  genre: string;
  colour: number; alt: number;
  /** How many people want to see them, 0.45–1: the share of a stadium they sell. */
  draw: number;
  /** Their career before day 0: tours, shows, tickets and takings. */
  pastTours: number; pastShows: number; pastCrowd: number; pastGross: number;
  /** The town they come from. */
  from: string;
}

const POOL = new Map<string, TourAct[]>();

/** The world's acts: the same dozen every time this seed is played. */
export function actsOf(seed: string): TourAct[] {
  let pool = POOL.get(seed);
  if (pool) return pool;
  pool = [];
  const names = new Set<string>();
  for (let i = 0; pool.length < ACTS && i < ACTS * 4; i++) {
    const h = hashString(`${seed}|act|${i}`);
    const a = actFor(h);
    if (names.has(a.name)) continue;
    names.add(a.name);
    const r = mulberry32(h ^ 0x7a11);
    const id = pool.length;
    const draw = 0.45 + r() * 0.55;
    const pastTours = 1 + Math.floor(r() * 9);
    let pastShows = 0;
    for (let t = 0; t < pastTours; t++) pastShows += 6 + Math.floor(r() * 14);
    const pastCrowd = Math.round(pastShows * (6000 + 16000 * draw) * (0.8 + r() * 0.3));
    const [colour, alt] = ACT_COLOURS[Math.floor(r() * ACT_COLOURS.length)];
    pool.push({
      ...a, id, genre: GENRES[Math.floor(r() * GENRES.length)], colour, alt, draw,
      pastTours, pastShows, pastCrowd, pastGross: Math.round(pastCrowd * ticketPrice(draw)),
      from: FAR_PLACES[Math.floor(r() * FAR_PLACES.length)],
    });
  }
  POOL.set(seed, pool);
  return pool;
}

/** A ticket, by how much people want one. */
export const ticketPrice = (draw: number): number => Math.round(35 + 60 * draw);

/** The name of an act's n-th tour (counting its career before day 0). */
export function tourName(act: TourAct, n: number): string {
  const r = mulberry32(hashString(`${act.name}|tour|${n}`));
  return `${WORDS_A[Math.floor(r() * WORDS_A.length)]} ${WORDS_B[Math.floor(r() * WORDS_B.length)]} Tour`;
}

/** How many people a show sells to, in a stadium with this many seats drawn (each drawn seat stands for twenty). */
export function crowdFor(act: TourAct, seats: number, seed: number): number {
  const cap = Math.max(4000, seats * 20);
  const r = mulberry32(seed >>> 0);
  return Math.round(cap * Math.min(1, act.draw * (0.78 + r() * 0.32)));
}
