import { hashString, mulberry32 } from '../world/rng';
import { cellKind } from '../world/macro';
import { personName } from './mayor';
import type { CargoClass } from './vehicles';
import { LOGOS, badgePaint } from './logos';

/**
 * The rival firms' lattice (docs/rivals.html, docs/localrivals.html): how many firms a county holds, and
 * everything about one that comes from the seed alone — its trade (taxis, freight, or anything), its
 * bent, the stage it is found at, its livery and its name. Pure, so the gate runs it headless.
 *
 * Since the local rivals every county with more than one municipality has a firm, and a rich one two
 * (`slotsFor`, from the generated county's towns); `specFor` is the firm in one of its slots. The old
 * one-a-block lattice (`legacySpec`) is kept only to rebuild the firms saves made before it.
 */

/** Transit (0.7.0, NEXT_WORLD): a big city's bus authority (Omnibuses on fares) or its commuter railway (the county's passenger trains). */
export type Trade = 'taxi' | 'freight' | 'general' | 'bus' | 'rail';
export type Bent = 'haulier' | 'landlord' | 'courtier';

/** Cells to a side of the old lattice's blocks (legacySpec): at most one firm a block. */
export const BLOCK = 5;
/** The chance an old block had a firm, by keenness: none, quiet, keen, cut-throat. */
export const CHANCE = [0, 0.25, 0.45, 0.7];

/** Which counties hold firms, and how many (docs/localrivals.html, "The rule"). */
export const LOCAL = {
  /** Quiet worlds: the chance a county that could hold a firm does. */
  quiet: 0.6,
  /** A second firm: two towns of suburb size or more, this many standing buildings, this much usual trade ($/h); by keenness. */
  twoBuildings: [Infinity, Infinity, 400, 300], twoNorm: [Infinity, Infinity, 60, 45],
  /** The county the game starts in has one start-up, which waits for the first drive to be over. */
  start: [0, 0] as [number, number],
};

/** What the lattice needs to know about a generated county: its towns' kinds and their standing buildings, and its usual trade. */
export interface CountySummary {
  towns: { kind: string; buildings: number }[];
  /** Σ ECONOMY.norm over its towns: dollars an hour the anonymous haulers usually carry for them. */
  norm: number;
  /** Its passenger stations (not halts, not goods yards): where a commuter railway could run. */
  stations?: number;
}

/** How many firms a county holds (0, 1 or 2), and whether its one firm is a village start-up. */
export function slotsFor(seedHash: number, cx: number, cz: number, c: CountySummary, keen: number): { n: number; village: boolean } {
  const none = { n: 0, village: false };
  if (keen <= 0 || !c.towns.length) return none;
  const start = cx === LOCAL.start[0] && cz === LOCAL.start[1];
  const big = c.towns.filter((t) => t.kind !== 'rural');
  // one town is not a local market: nobody sets up against it (the start's county excepted)
  if (c.towns.length < 2 && !start) return none;
  const village = !big.length;
  if (keen === 1 && !start && mulberry32(hashString(`firmq|${seedHash}|${cx}|${cz}`))() >= LOCAL.quiet) return none;
  if (start || village || keen === 1) return { n: 1, village };
  const buildings = c.towns.reduce((s, t) => s + t.buildings, 0);
  const two = big.length >= 2 && buildings >= LOCAL.twoBuildings[keen] && c.norm >= LOCAL.twoNorm[keen];
  return { n: two ? 2 : 1, village: false };
}

/** The vehicles each trade runs, cheapest first. A railway buys none: it runs the county's passenger trains (TRANSIT). */
export const MODELS: Record<Trade, string[]> = {
  taxi: ['cab'],
  freight: ['mule', 'bramble', 'clod', 'dump', 'bertha'],
  general: ['tomato', 'mule', 'pip', 'atv', 'bramble', 'zippy'],
  bus: ['bus'],
  rail: [],
};
/** What each trade's drivers take: a taxi only fares, a freight firm never passengers. Empty is anything. */
export const TAKES: Record<Trade, CargoClass[]> = {
  taxi: ['people'],
  freight: ['parcel', 'freight', 'bulk', 'container'],
  general: [],
  bus: ['people'],
  rail: ['people'],
};
export const TRADE_LABEL: Record<Trade, string> = { taxi: 'taxis', freight: 'freight', general: 'carriers', bus: 'city buses', rail: 'commuter rail' };

/**
 * Transit operators (0.7.0, behind NEXT_WORLD; docs/rivals.html "Transit"): rare, and only in a county
 * with a big city (metro) or a megalopolis, at most one a county. They take county slots of their own
 * (`busSlot`, `railSlot`), past the ordinary firms' 0 and 1, so the rosters 0.6.x rolled are untouched. A
 * county gets a railway rather than a bus authority only where it has passenger stations enough to run one.
 */
export const TRANSIT = {
  /** The chance a county with a metro or a megalopolis has one. */
  chance: 0.3,
  /** The kinds of town that make a county big enough. */
  kinds: ['metro', 'mega'],
  /** Passenger stations a railway needs in its county (a line runs on through the next counties); with them, the chance it is a railway. */
  stations: 1, rail: 0.6,
  /** Their slots: the id `cx,cz/8` is a bus authority, `cx,cz/9` a railway. */
  busSlot: 8, railSlot: 9,
  /** Trains a railway runs (its units), by the stage it is met at. */
  trains: [2, 3, 4],
  /** What a railway takes at each call of one of its trains: its share of the fares. */
  fare: 14,
};

/** A county's transit operator, if it has one: its slot (TRANSIT.busSlot or railSlot), or null. Pure. */
export function transitSlot(seedHash: number, cx: number, cz: number, c: CountySummary, keen: number): number | null {
  if (keen <= 0 || !c.towns.some((t) => TRANSIT.kinds.includes(t.kind))) return null;
  // the gate's switch: every county that could have one has one, a railway wherever one could run
  if (TRANSIT_TEST.all) return (c.stations ?? 0) >= TRANSIT.stations ? TRANSIT.railSlot : TRANSIT.busSlot;
  const rng = mulberry32(hashString(`transit|${seedHash}|${cx}|${cz}`));
  if (rng() >= TRANSIT.chance) return null;
  return (c.stations ?? 0) >= TRANSIT.stations && rng() < TRANSIT.rail ? TRANSIT.railSlot : TRANSIT.busSlot;
}
/** For the gate (scripts/transit.ts): an operator in every big-city county. */
export const TRANSIT_TEST = { all: false };
/** Is this county slot a transit operator's? */
export const isTransitSlot = (slot: number): boolean => slot === TRANSIT.busSlot || slot === TRANSIT.railSlot;
export const BENT_LABEL: Record<Bent, string> = { haulier: 'hauliers', landlord: 'landlords', courtier: 'courting the towns' };
export const STAGE_LABEL = ['start-up', 'local', 'regional', 'major'];

/**
 * Liveries: a body and an accent, both well apart in lightness so the two bands read from the camera.
 * The player's red and its neighbours are never a firm's body. Taxi firms keep to the taxi colours.
 */
export const BODIES: Record<Trade, number[]> = {
  taxi: [0xf5cf3a, 0xf6d04d, 0xf2a93b, 0xd9b34a, 0x2a2a2e, 0xf4f2ec, 0x2bb3a3, 0x86c36c],
  // the authorities' colours: white or silver, a city's blue, red or green, and the odd all-over orange
  bus: [0xf4f2ec, 0x2f5fb0, 0xc23a2c, 0x2e8a57, 0xf28c38, 0xc9ced4, 0x1f6f8b],
  rail: [0xc9ced4, 0xf4f2ec, 0x2f4d7a, 0x7a2a5a, 0x2e8a57, 0xd8a020, 0x1f6f8b],
  freight: [0x2f4d7a, 0x3f78c0, 0x3f9b4a, 0x6f9e6b, 0x8a8f96, 0xb07a4a, 0x8e5cc7, 0x2a2a2e, 0xc9ced4, 0x2bb3a3, 0x4a6fa5, 0xf28c38],
  general: [0x8e5cc7, 0x2bb3a3, 0x3f78c0, 0x86c36c, 0xf28c38, 0x4a6fa5, 0xa7dcc8, 0xf7c5d4, 0x2f4d7a, 0xd9b34a, 0x3f9b4a, 0xc9ced4],
};
export const ACCENTS = [0xf4f2ec, 0x2a2a2e, 0xd9b34a, 0xf5cf3a, 0x2f4d7a, 0xa7dcc8, 0xc9ced4];
export const lum = (c: number): number => (0.299 * ((c >> 16) & 255) + 0.587 * ((c >> 8) & 255) + 0.114 * (c & 255)) / 255;
/** The lightness gap a livery's two colours need. */
export const LIVERY_GAP = 0.3;

/** What the lattice says about a block: everything about a firm that comes from the seed. */
export interface Spec {
  id: string;
  epoch: number;
  home: [number, number];
  trade: Trade;
  bent: Bent;
  /** The stage it is found at, the first time the player has its home in memory. */
  start: number;
  livery: [number, number];
  /** Its logo, one of LOGOS: on its badge wherever its name is. */
  logo: string;
  /** Salt for its name and its starting drivers. */
  salt: string;
  /** A one-van start-up out of a county of villages. */
  village?: boolean;
}


// ---- the lattice ----------------------------------------------------------------------------------

/** The block's first-choice body colour, which its neighbours step round. */
function firstBody(seedHash: number, bx: number, bz: number, epoch: number): number {
  const rng = mulberry32(hashString(`firm|${seedHash}|${bx}|${bz}|${epoch}`));
  rng(); rng(); rng();
  const trade = tradeOf(rng());
  const list = BODIES[trade];
  return list[Math.floor(rng() * list.length)];
}

const tradeOf = (r: number): Trade => (r < 0.36 ? 'taxi' : r < 0.72 ? 'freight' : 'general');

/**
 * The firm a block of the old lattice held, if any: a pure function of the seed, the block, the epoch
 * and how keen the world is. Only saves made before the local rivals have these (ids "bx,bz").
 */
export function legacySpec(seedHash: number, bx: number, bz: number, epoch: number, keen: number): Spec | null {
  if (keen <= 0 || (bx === 0 && bz === 0)) return null;
  const rng = mulberry32(hashString(`firm|${seedHash}|${bx}|${bz}|${epoch}`));
  if (rng() >= CHANCE[keen]) return null;
  // the home cell: a land cell somewhere in the block
  let home: [number, number] | null = null;
  const roll = rng(); void roll;
  const r2 = rng();
  const trade = tradeOf(rng());
  const bodies = BODIES[trade];
  let pick = Math.floor(rng() * bodies.length);
  for (let k = 0; k < 16 && !home; k++) {
    const cx = bx * BLOCK + Math.floor(mulberry32(hashString(`firmcell|${seedHash}|${bx}|${bz}|${epoch}|${k}`))() * BLOCK);
    const cz = bz * BLOCK + Math.floor(mulberry32(hashString(`firmcell|${seedHash}|${bz}|${bx}|${epoch}|${k}`))() * BLOCK);
    if (cellKind(seedHash, cx, cz) !== 'sea') home = [cx, cz];
  }
  if (!home) return null;
  // never the same body as a neighbouring block's first choice
  const near = new Set<number>();
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (dx || dz) near.add(firstBody(seedHash, bx + dx, bz + dz, 0));
  for (let k = 0; k < bodies.length && near.has(bodies[pick]); k++) pick = (pick + 1) % bodies.length;
  const body = bodies[pick];
  const accents = ACCENTS.filter((a) => Math.abs(lum(a) - lum(body)) >= LIVERY_GAP);
  const accent = accents[Math.floor(rng() * accents.length)] ?? 0xf4f2ec;
  const bents: Bent[] = ['haulier', 'landlord', 'courtier'];
  const bent = bents[Math.floor(rng() * 3)];
  const s = rng();
  const start = s < 0.6 ? 0 : s < 0.9 ? 1 : 2;
  const salt = `${seedHash}|${bx}|${bz}|${epoch}|${r2}`;
  // hashed from the salt rather than drawn from the stream, so nothing else about the firm moves
  const logo = LOGOS[hashString(`firmlogo|${salt}`) % LOGOS.length];
  return { id: `${bx},${bz}`, epoch, home, trade, bent, start, livery: [body, accent], logo, salt };
}

/** A firm id of the local lattice: its county and its slot. */
export const slotId = (cx: number, cz: number, slot: number): string => `${cx},${cz}/${slot}`;
/** The county and slot of a local firm id, or null for an old block id. */
export function parseSlotId(id: string): { cx: number; cz: number; slot: number } | null {
  const m = /^(-?\d+),(-?\d+)\/(\d+)$/.exec(id);
  return m ? { cx: Number(m[1]), cz: Number(m[2]), slot: Number(m[3]) } : null;
}

const slotRng = (seedHash: number, cx: number, cz: number, slot: number, epoch: number) =>
  mulberry32(hashString(`firm2|${seedHash}|${cx}|${cz}|${slot}|${epoch}`));

/** A county slot's trade: slot 1 never takes slot 0's first trade, so two firms in a county split it. */
function slotTrade(seedHash: number, cx: number, cz: number, slot: number, epoch: number, village: boolean): Trade {
  if (village) return 'general';
  const r = slotRng(seedHash, cx, cz, slot, epoch)();
  if (slot === 0) return tradeOf(r);
  const first = slotTrade(seedHash, cx, cz, 0, 0, false);
  const rest = (['taxi', 'freight', 'general'] as Trade[]).filter((t) => t !== first);
  return rest[r < 0.5 ? 0 : 1];
}

/** A county slot's first-choice body colour, which its neighbours and its sibling step round. */
function slotBody(seedHash: number, cx: number, cz: number, slot: number): number {
  const rng = slotRng(seedHash, cx, cz, slot, 0);
  rng(); rng();
  const list = BODIES[slotTrade(seedHash, cx, cz, slot, 0, false)];
  return list[Math.floor(rng() * list.length)];
}

/**
 * The firm in one slot of a county: a pure function of the seed, the county, the slot, the epoch (a fold
 * starts a new one) and whether it is a village start-up. Whether the slot is open at all is slotsFor's
 * business, from the generated county. The start's county only ever has a start-up.
 */
export function specFor(seedHash: number, cx: number, cz: number, slot: number, epoch: number, village: boolean): Spec {
  if (isTransitSlot(slot)) return transitSpec(seedHash, cx, cz, slot, epoch);
  const rng = slotRng(seedHash, cx, cz, slot, epoch);
  rng();
  const r2 = rng();
  const trade = slotTrade(seedHash, cx, cz, slot, epoch, village);
  const bodies = BODIES[trade];
  let pick = Math.floor(rng() * bodies.length);
  // never the same body as a neighbouring county's firms or its own sibling
  const near = new Set<number>();
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) for (let k = 0; k < 2; k++) {
    if (!dx && !dz && k === slot) continue;
    near.add(slotBody(seedHash, cx + dx, cz + dz, k));
  }
  // and the second firm steps round the colour its sibling actually wears, not only its first choice
  if (slot > 0) near.add(specFor(seedHash, cx, cz, 0, 0, false).livery[0]);
  for (let k = 0; k < bodies.length && near.has(bodies[pick]); k++) pick = (pick + 1) % bodies.length;
  const body = bodies[pick];
  const accents = ACCENTS.filter((a) => Math.abs(lum(a) - lum(body)) >= LIVERY_GAP);
  const accent = accents[Math.floor(rng() * accents.length)] ?? 0xf4f2ec;
  const bents: Bent[] = ['haulier', 'landlord', 'courtier'];
  const bent = bents[Math.floor(rng() * 3)];
  const s = rng();
  const startCounty = cx === LOCAL.start[0] && cz === LOCAL.start[1];
  const start = village || startCounty ? 0 : s < 0.6 ? 0 : s < 0.9 ? 1 : 2;
  const salt = `${seedHash}|${cx}|${cz}|${slot}|${epoch}|${r2}`;
  const logo = LOGOS[hashString(`firmlogo|${salt}`) % LOGOS.length];
  return { id: slotId(cx, cz, slot), epoch, home: [cx, cz], trade, bent, start, livery: [body, accent], logo, salt, village };
}

/** A transit operator in its slot: a bus authority or a railway, in a transit colour with an accent well apart from it. */
function transitSpec(seedHash: number, cx: number, cz: number, slot: number, epoch: number): Spec {
  const rng = mulberry32(hashString(`transit2|${seedHash}|${cx}|${cz}|${slot}|${epoch}`));
  const trade: Trade = slot === TRANSIT.railSlot ? 'rail' : 'bus';
  const r2 = rng();
  const body = BODIES[trade][Math.floor(rng() * BODIES[trade].length)];
  const accents = ACCENTS.filter((a) => Math.abs(lum(a) - lum(body)) >= LIVERY_GAP);
  const accent = accents[Math.floor(rng() * accents.length)] ?? 0x2f4d7a;
  // an authority is no start-up: the city already rides it
  const start = rng() < 0.5 ? 1 : 2;
  const salt = `${seedHash}|${cx}|${cz}|${slot}|${epoch}|${r2}`;
  const logo = LOGOS[hashString(`firmlogo|${salt}`) % LOGOS.length];
  return { id: slotId(cx, cz, slot), epoch, home: [cx, cz], trade, bent: 'courtier', start, livery: [body, accent], logo, salt };
}

/** A firm's name, from its trade, its salt and its home town (and, for a transit operator, its county). */
export function firmName(spec: Spec, town: string, county = ''): string {
  const rng = mulberry32(hashString(`firmname|${spec.salt}`));
  const sur = personName(`firmname|${spec.salt}`).split(' ').pop()!;
  const pick = <T>(xs: T[]): T => xs[Math.floor(rng() * xs.length)];
  const place = town.replace(/ City$/, '');
  switch (spec.trade) {
    case 'taxi': return pick([`${place} Cabs`, `${sur} Taxis`, `${place} Radio Cars`, `Checker ${place}`, `${sur}’s Cabs`, `${place} Hackney Co.`]);
    case 'freight': return pick([`${place} Freight`, `${sur} Haulage`, `${sur} & Sons`, `${place} Carriers`, `${sur} Road Services`, `${place} Goods Co.`]);
    // named for their city, as real ones are; an area authority for its county
    case 'bus': return pick([`${place} Transit Authority`, `${place} Metropolitan Transit`, `${place} Rapid Transit District`, `${place} Area Transit`,
      ...(county ? [`${county} Regional Transit`] : [])]);
    case 'rail': return pick([`${place} Regional Rail`, `${place} Metro Rail`, `${place} Commuter Rail`, `${county || place} Area Rapid Transit`]);
    default: return pick([`${sur} & Daughters`, `${place} Couriers`, `${sur} Brothers`, `${place} Transport`, `${sur} & Co.`, `${place} Express`]);
  }
}

/** The CSS colour of a number. */
export const css = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;
/** The badge a firm is shown with wherever its name is: its logo in its body colour on its accent, ringed in the body colour. */
export const chip = (l: [number, number], logo?: string, p = badgePaint(l[0], l[1])): string => logo
  ? `<span class="fleet-badge firm" style="width:15px;height:15px;font-size:9px;margin-right:5px;vertical-align:-2px;background:${p.disc};color:${p.glyph};box-shadow:inset 0 0 0 2px ${p.ring}">${logo}</span>`
  : `<span class="livery"><i style="background:${css(l[0])}"></i><i style="background:${css(l[1])}"></i></span>`;

/** The stage a firm of this many vehicles is at. */
export function stageFor(n: number): number { return n >= 15 ? 3 : n >= 8 ? 2 : n >= 4 ? 1 : 0; }
