import type { Building, World } from '../../world/tiles';
import type { Site } from '../cargo';
import { ROUTE, type RouteOrder, type RouteStop } from './routes';

/**
 * Setting a route (docs/supplychains.html, "Making one"): the vehicle card's Route button opens this. Right-click
 * the stops in order (a press and release that doesn't drag the camera); right-click the first again to close a loop;
 * Esc or Done leaves it a line, out and back. A stop the vehicle can't use says why and isn't added.
 */
export interface RouteToolHost {
  /** The building under the pointer. */
  pick(mx: number, my: number): { w: World; b: Building } | null;
  /** That building's cargo site (its kerb), if it trades. */
  site(w: World, b: Building): Site | null;
  /** Its deed key. */
  keyOf(w: World, b: Building): string;
  /** Why this vehicle can't call here, or null when it can. */
  why(uid: number, s: Site): string | null;
  /** Give the vehicle the route. Returns why not, or null. */
  set(uid: number, r: RouteOrder): string | null;
  /** The vehicle's name, for the strip. */
  name(uid: number): string;
  say(title: string, body: string): void;
}

/** A press and release closer than this (pixels) is a click, not a camera drag. */
const CLICK = 5;

export class RouteTool {
  uid = 0;
  stops: RouteStop[] = [];
  private strip = document.createElement('div');
  private down: { x: number; y: number } | null = null;

  constructor(private host: RouteToolHost, canvas: HTMLElement) {
    this.strip.id = 'route-strip';
    this.strip.hidden = true;
    document.body.append(this.strip);
    this.strip.addEventListener('pointerdown', (e) => {
      const b = (e.target as HTMLElement).closest('button[data-rt]') as HTMLElement | null;
      if (!b) return;
      e.preventDefault();
      e.stopPropagation();
      if (b.dataset.rt === 'done') this.finish(false);
      else if (b.dataset.rt === 'loop') this.finish(true);
      else if (b.dataset.rt === 'undo') { this.stops.pop(); this.draw(); }
      else this.cancel();
    });
    canvas.addEventListener('pointerdown', (e) => { if (this.active && e.button === 2) this.down = { x: e.clientX, y: e.clientY }; });
    canvas.addEventListener('pointerup', (e) => {
      if (!this.active || e.button !== 2 || !this.down) return;
      const moved = Math.hypot(e.clientX - this.down.x, e.clientY - this.down.y);
      this.down = null;
      if (moved <= CLICK) this.click(e.clientX, e.clientY);
    });
    // Esc finishes (as a line) before anything else hears it
    window.addEventListener('keydown', (e) => {
      if (!this.active || e.key !== 'Escape') return;
      e.preventDefault();
      e.stopImmediatePropagation();
      this.finish(false);
    }, true);
  }

  get active(): boolean { return this.uid !== 0; }

  start(uid: number): void {
    this.uid = uid;
    this.stops = [];
    this.draw();
  }

  cancel(): void {
    this.uid = 0;
    this.stops = [];
    this.draw();
  }

  private click(mx: number, my: number): void {
    const hit = this.host.pick(mx, my);
    if (!hit) return;
    const key = this.host.keyOf(hit.w, hit.b);
    // the first again closes the loop
    if (this.stops.length >= 2 && this.stops[0].key === key) { this.finish(true); return; }
    if (this.stops.length && this.stops[this.stops.length - 1].key === key) return;
    if (this.stops.length >= ROUTE.most) { this.host.say('That’s enough stops', `A route takes ${ROUTE.most} at most`); return; }
    const s = this.host.site(hit.w, hit.b);
    if (!s) { this.host.say('No stop here', 'Nothing is loaded or set down at this building'); return; }
    const why = this.host.why(this.uid, s);
    if (why) { this.host.say('Can’t stop here', why); return; }
    if (this.stops.some((p) => Math.hypot(p.x - s.x, p.z - s.z) > ROUTE.span)) { this.host.say('Too far apart', `Keep a route’s stops within ${ROUTE.span} tiles of each other`); return; }
    this.stops.push({ key, name: s.name, x: s.x, z: s.z, y: s.y, cx: s.w.cx, cz: s.w.cz });
    this.draw();
  }

  finish(loop: boolean): void {
    const uid = this.uid;
    if (!uid) return;
    if (this.stops.length >= 2) {
      const why = this.host.set(uid, { stops: this.stops, loop: loop && this.stops.length > 2, i: 0, dir: 1, hold: true, laps: 0 });
      if (why) this.host.say('No route', why);
      else this.host.say(`${this.host.name(uid)} has a route`, `${loop && this.stops.length > 2 ? 'A loop' : 'A line'} of ${this.stops.length} stops`);
    }
    this.cancel();
  }

  private draw(): void {
    this.strip.hidden = !this.active;
    if (!this.active) return;
    const list = this.stops.map((s, k) => `<span class="rs">${k + 1} ${esc(s.name.split(' · ')[0])}</span>`).join('<i>›</i>');
    this.strip.innerHTML = `<b>🔁 Route for ${esc(this.host.name(this.uid))}</b>`
      + `<small>Right-click the stops in order · right-click the first again to close a loop · <kbd>Esc</kbd> to finish</small>`
      + `<div class="rl">${list || '<em>no stops yet</em>'}</div>`
      + `<div class="rb">${this.stops.length ? '<button type="button" data-rt="undo">Undo</button>' : ''}`
      + `${this.stops.length > 2 ? '<button type="button" data-rt="loop">Loop</button>' : ''}`
      + `${this.stops.length >= 2 ? '<button type="button" data-rt="done" class="main">Done</button>' : ''}`
      + `<button type="button" data-rt="cancel">Cancel</button></div>`;
  }
}

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
