import { N, World, idx, waterDepth, type Bridge, type GreatDesign, type Landmark, type Road } from './tiles';
import { deckTiles, dirBetween, shapeOf } from './roads';
import { siteOf } from './bridgeDesigns';
import { hash2 } from './rng';
import { landformName } from './landforms';

/**
 * Great crossings (0.8.0, NEXT_080, docs/phonelist.html item 14): out in the country, far from any town, the county's
 * most dramatic crossing is built as a famous kind of bridge and named. A deep gorge is spanned by a steel deck arch
 * springing from its walls (New River Gorge), an open-spandrel concrete arch (Bixby Creek, by the coast) or, when it is
 * long, a high viaduct on slender piers; a wide river by a steel through-truss, its deck down at the banks.
 *
 * Nothing is moved or rerouted: the crossing is one the county's roads already make, picked once every road is laid
 * (generate.ts, after the roads are mended), so a county that has none is exactly what it was. The bridge carries its
 * design (Bridge.great, which world/bridgeDesigns.ts designOf returns) and a 'crossing' landmark names it, so it is on
 * the map labels, announced as the car drives onto it, and a place sightseers go.
 */

/** A gorge span: at least this much air under the deck (world units) and this many tiles of deck. */
const GORGE_AIR = 3.5, GORGE_LEN = 8;
/** A river span: this many tiles of deck over water at least. */
const RIVER_LEN = 12;
/** No town's edge within this many tiles of the deck. */
const TOWN_CLEAR = 8;
/** A gorge span this long is a viaduct; one within this many tiles of the sea a concrete arch. */
const VIADUCT_LEN = 30, COAST = 14;

export const GREAT_NAME: Record<GreatDesign, string> = {
  deckArch: 'Steel arch bridge', spandrelArch: 'Concrete arch bridge', highViaduct: 'Viaduct', throughTruss: 'Truss bridge',
};

/** Pick and name the county's great crossing, if it has one. Returns its design, or null. */
export function markGreatCrossing(w: World, seedHash: number): GreatDesign | null {
  let best: { r: Road; br: Bridge; score: number; design: GreatDesign; mid: number; len: number } | null = null;
  for (const r of w.roads) {
    if (r.town !== undefined && r.town >= 0) continue;
    if (r.limited) continue;
    for (const br of r.bridges ?? []) {
      if (br.tunnel || br.level || br.ramp || br.peak !== undefined || br.raised || br.from === br.to) continue;
      const site = siteOf(w, r, br);
      const a = r.nodes[br.from], b = r.nodes[br.to];
      const tiles = deckTiles(a, b, dirBetween(a, r.nodes[br.from + 1]), shapeOf(r.type));
      if (!tiles.length) continue;
      if (tiles.some(({ tile }) => nearTown(w, tile))) continue;
      let wet = 0, coast = 99;
      for (const { tile } of tiles) { if (waterDepth(w, tile) > 0) wet++; coast = Math.min(coast, w.coastDist[tile]); }
      let design: GreatDesign | null = null, score = 0;
      if (site.height >= GORGE_AIR && site.len >= GORGE_LEN && wet <= tiles.length * 0.5) {
        const roll = hash2(a, b, 7401);
        design = site.len >= VIADUCT_LEN ? 'highViaduct' : coast <= COAST || roll < 0.45 ? 'spandrelArch' : 'deckArch';
        score = 100 + site.height * 4 + site.len;
      } else if (site.len >= RIVER_LEN && wet >= site.len * 0.6) {
        design = 'throughTruss';
        score = site.len;
      }
      if (design && (!best || score > best.score)) best = { r, br, score, design, mid: tiles[tiles.length >> 1].tile, len: site.len };
    }
  }
  if (!best) return null;
  best.br.great = best.design;
  const x = (best.mid % N) + 0.5, z = Math.floor(best.mid / N) + 0.5;
  // (hashed off the deck's middle and the road's own ends, so neighbouring counties' crossings are not all one name)
  const word = landformName('crossing', seedHash ^ Math.imul(best.r.nodes[0] + 1, 2654435761), w.ox * 3 + x, w.oz * 5 + z);
  const name = best.design === 'throughTruss' ? `the ${word} River Bridge` : best.design === 'highViaduct' ? `the ${word} Viaduct` : `the ${word} Gorge Bridge`;
  const l: Landmark = { kind: 'crossing', name, x, z, r: Math.max(4, Math.ceil(best.len / 2) + 1), data: [GREAT_DESIGNS.indexOf(best.design)] };
  w.landmarks.push(l);
  return best.design;
}

export const GREAT_DESIGNS: GreatDesign[] = ['deckArch', 'spandrelArch', 'highViaduct', 'throughTruss'];

function nearTown(w: World, tile: number): boolean {
  const x = tile % N, z = (tile - x) / N;
  for (const t of w.towns) {
    const dx = Math.max(t.x0 - x, 0, x - (t.x0 + t.size)), dz = Math.max(t.z0 - z, 0, z - (t.z0 + t.size));
    if (Math.max(dx, dz) < TOWN_CLEAR) return true;
  }
  return w.townId[idx(x, z)] >= 0;
}

/** The great crossing's label under its name, by its design. */
export function crossingLabel(l: Landmark): string {
  return GREAT_NAME[GREAT_DESIGNS[l.data?.[0] ?? 0] ?? 'deckArch'];
}

