/**
 * The 0.8.0 world's new buildings (world/kinds080.ts), gathered into one draw table for render/townMesh.ts and the
 * gallery (gallery.html?group=k080). A kind not drawn yet stands as a plain block.
 *
 * The beachfront (world/beachfront.ts):
 * - **Fishing pier**: a plank deck on piles out over the sea, rails, a bait shack at the end, anglers at the rail
 * - **Pleasure pier**: the Shallows wonder's pier (its wheel, helter-skelter, kiosks and pavilion), off a beach town
 * - **Grand pier**: the pleasure pier with a wooden rollercoaster and a carousel on its landward half
 * - **Lifeguard tower**: a hut on stilts with a ramp, a red cross and a flag
 * - **Beach volleyball**: a sanded court, its net between two posts
 *
 * The headland park (world/headland.ts): the officers' row round its parade lawn, the gun battery, the lookout.
 */
import { hex } from '../../world/biomes';
import { INFO_080, KINDS_080, type Kind080 } from '../../world/kinds080';
import { GLASS, METAL, TAU, WHITE, windowGlow, windowSched, type Draw, type Kit, type P3 } from './kit';
import { pleasurePier } from './regions/shallows';
import { COMPLEX_DRAW } from './k080complex';
import { STRONGHOLD_DRAW_A } from './strongholdsA';
import { STRONGHOLD_DRAW_B } from './strongholdsB';
import { STRONGHOLD_KINDS } from '../../world/strongholdPlans';
import type { Building } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import type { RGB } from '../../world/biomes';

const PLANK = hex(0xa98a64), PLANK2 = hex(0x8f7454), PILE = hex(0x5a4a3a), RED = hex(0xd8342a), YELLOW = hex(0xf2c14e);
const SAND = hex(0xe6d29a), BLUE = hex(0x2f7fb5);

const fishingPier: Draw = (k, W, D, _b, r) => {
  const E = W / 2 - 0.08, L = -D / 2, S = D / 2;
  // the deck and its piles
  k.box(0, -0.06, 0, W - 0.1, 0.08, D, PLANK, PLANK);
  for (let z = L + 0.5; z < S; z += 0.5) k.box(0, 0.0, z, W - 0.1, 0.012, 0.03, PLANK2);
  for (let z = 1.2; z < S; z += 1.4) for (const x of [-E + 0.06, E - 0.06]) k.cyl(x, -1.3, z, 0.05, 1.25, PILE, 6);
  // rails
  for (const sx of [-1, 1]) {
    for (let z = L + 0.3; z < S - 0.2; z += 0.6) k.box(sx * E, 0, z, 0.035, 0.22, 0.035, WHITE);
    k.box(sx * E, 0.22, 0, 0.05, 0.03, D - 0.6, WHITE);
  }
  // the bait shack at the end, and a bench
  k.box(0, 0, S - 0.7, W - 0.6, 0.38, 0.7, hex(0x6fa8c8));
  k.gable(0, 0.38, S - 0.7, W - 0.5, 0.16, 0.8, hex(0x9a3a2a), hex(0x6fa8c8));
  k.box(0, 0.12, S - 1.06, 0.4, 0.14, 0.01, YELLOW);
  // anglers at the rail, rods out over the water
  for (let i = 0; i < 4; i++) {
    const sx = i % 2 ? 1 : -1, z = L + 3 + i * 2.2 + r() * 0.6;
    const x = sx * (E - 0.18);
    k.box(x, 0, z, 0.1, 0.18, 0.08, [hex(0x3f9b4a), hex(0xe2412f), hex(0x2f7fb5), hex(0xf28c38)][i]);
    k.box(x, 0.18, z, 0.08, 0.08, 0.08, hex(0xe0b08a));
    k.bar([x, 0.2, z], [x + sx * 0.7, 0.55, z + 0.1], 0.008, PILE);
  }
};

/** The pleasure pier, with a wooden coaster looping along one side and a carousel turning on the other. */
const grandPier: Draw = (k, W, D, b, r, t) => {
  pleasurePier(k, W, D, b, r, t);
  const E = W / 2 - 0.06, L = -D / 2;
  // the coaster: a lifted loop of track on timber trestles, its train parked at the top
  const cx = E - 0.85, cz = L + 7.6, R = 0.6, len = 3.2;
  const at = (u: number): P3 => {
    // a racetrack loop: two straights joined by half circles, climbing to a lift hill and swooping down twice
    const per = 2 * len + TAU * R, s = (((u % 1) + 1) % 1) * per;
    let x: number, z: number;
    if (s < len) { x = cx + R; z = cz - len / 2 + s; }
    else if (s < len + Math.PI * R) { const a = (s - len) / R; x = cx + R * Math.cos(a); z = cz + len / 2 + R * Math.sin(a); }
    else if (s < 2 * len + Math.PI * R) { x = cx - R; z = cz + len / 2 - (s - len - Math.PI * R); }
    else { const a = Math.PI + (s - 2 * len - Math.PI * R) / R; x = cx + R * Math.cos(a); z = cz - len / 2 + R * Math.sin(a); }
    const t = ((u % 1) + 1) % 1;
    const y = 0.35 + 1.05 * Math.max(0, Math.sin(t * TAU)) ** 1.5 + 0.35 * Math.max(0, Math.sin(t * TAU * 3 + 1.2));
    return [x, y, z];
  };
  const n = 64, RED_RAIL = hex(0xc23a30), TIMBER = hex(0xd8c8a8);
  for (let i = 0; i < n; i++) {
    const a = at(i / n), c = at((i + 1) / n);
    // the two rails either side of the track's line, and a tie across them now and then
    const tx = c[0] - a[0], tz = c[2] - a[2], tl = Math.hypot(tx, tz) || 1, ox = (-tz / tl) * 0.06, oz = (tx / tl) * 0.06;
    for (const sgn of [-1, 1]) k.bar([a[0] + ox * sgn, a[1], a[2] + oz * sgn], [c[0] + ox * sgn, c[1], c[2] + oz * sgn], 0.03, RED_RAIL);
    if (i % 2 === 0) k.bar([a[0] - ox, a[1] - 0.02, a[2] - oz], [a[0] + ox, a[1] - 0.02, a[2] + oz], 0.025, TIMBER);
    // the timber trestle under it
    if (i % 4 === 0) {
      k.bar([a[0] - ox * 1.5, 0.02, a[2] - oz * 1.5], [a[0], a[1] - 0.04, a[2]], 0.03, TIMBER);
      k.bar([a[0] + ox * 1.5, 0.02, a[2] + oz * 1.5], [a[0], a[1] - 0.04, a[2]], 0.03, TIMBER);
    }
  }
  // the train, waiting at the top of the lift hill
  for (let i = 0; i < 4; i++) { const p = at(0.24 + i * 0.01); k.box(p[0], p[1] + 0.05, p[2], 0.13, 0.08, 0.15, i % 2 ? YELLOW : RED); }
  // the carousel, turning under its striped canopy
  const ox = -E + 0.75, oz = L + 9.2;
  k.cyl(ox, 0.02, oz, 0.62, 0.06, WHITE, 14);
  k.cyl(ox, 0.08, oz, 0.04, 0.7, hex(0xd9a441), 6);
  k.spin(ox, 0.08, oz, 'y', 0.5, (s) => {
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU, x = Math.cos(a) * 0.45, z = Math.sin(a) * 0.45;
      s.cyl(x, 0, z, 0.012, 0.6, hex(0xd9a441), 4);
      s.box(x, 0.18 + (i % 2) * 0.06, z, 0.07, 0.1, 0.16, i % 2 ? WHITE : hex(0xb9865a));
    }
  });
  for (let i = 0; i < 12; i++) {
    const a0 = (i / 12) * TAU, a1 = ((i + 1) / 12) * TAU;
    k.bar([ox + Math.cos(a0) * 0.66, 0.78, oz + Math.sin(a0) * 0.66], [ox, 1.0, oz], 0.02, i % 2 ? RED : WHITE);
    k.bar([ox + Math.cos(a0) * 0.66, 0.78, oz + Math.sin(a0) * 0.66], [ox + Math.cos(a1) * 0.66, 0.78, oz + Math.sin(a1) * 0.66], 0.03, i % 2 ? RED : WHITE);
  }
  k.cone(ox, 0.78, oz, 0.7, 0.3, RED, 12);
};

const lifeguardTower: Draw = (k, _W, _D, _b, _r) => {
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.cyl(sx * 0.18, 0, sz * 0.15, 0.025, 0.32, WHITE, 5);
  k.box(0, 0.32, 0, 0.5, 0.04, 0.42, PLANK);
  k.box(0, 0.36, -0.03, 0.42, 0.24, 0.32, YELLOW);
  k.gable(0, 0.6, -0.03, 0.5, 0.1, 0.4, BLUE, YELLOW);
  // the window to the sea, the red cross on the side, the ramp down to the sand and the flag
  k.box(0, 0.44, 0.13, 0.3, 0.1, 0.01, hex(0x36505e));
  k.box(0.211, 0.46, -0.03, 0.01, 0.1, 0.03, RED);
  k.box(0.211, 0.46, -0.03, 0.01, 0.03, 0.1, RED);
  k.bar([0, 0.33, 0.21], [0, 0.0, 0.48], 0.05, PLANK2);
  k.cyl(-0.22, 0.36, 0.17, 0.008, 0.45, METAL, 4);
  k.box(-0.17, 0.72, 0.17, 0.1, 0.07, 0.006, RED);
};

const volleyCourt: Draw = (k, W, D) => {
  k.box(0, 0, 0, W - 0.15, 0.02, D - 0.15, SAND);
  // the lines, and the net across the middle on its two posts
  for (const s of [-1, 1]) k.box(s * (W / 2 - 0.12), 0.021, 0, 0.02, 0.003, D - 0.25, WHITE);
  for (const s of [-1, 1]) k.box(0, 0.021, s * (D / 2 - 0.12), W - 0.25, 0.003, 0.02, WHITE);
  for (const s of [-1, 1]) k.cyl(0, 0, s * (D / 2 - 0.05), 0.015, 0.32, METAL, 5);
  k.box(0, 0.22, 0, 0.01, 0.1, D - 0.12, hex(0xf4f2ec));
  k.box(0.3, 0.05, 0.2, 0.05, 0.05, 0.05, hex(0xf6e06a));
};

/** A row of old officers' houses round a parade lawn: white clapboard, red tile roofs, porches, a flagpole. */
const officersRow: Draw = (k, W, D, _b, r) => {
  const ROOF = hex(0xb4553a), CLAP = hex(0xf2efe6), TRIM = hex(0x5a6e5a);
  k.box(0, 0, 0, W - 0.1, 0.015, D - 0.1, hex(0x7fae5c));
  const n = 3, span = (W - 0.4) / n;
  for (let i = 0; i < n; i++) {
    const x = -W / 2 + 0.2 + span * (i + 0.5), z = -D / 2 + 0.75;
    k.box(x, 0, z, span - 0.18, 0.62, 0.8, CLAP);
    k.gable(x, 0.62, z, span - 0.08, 0.3, 0.9, ROOF, CLAP);
    // the porch along the front, on posts, and the windows over it
    k.box(x, 0.24, z + 0.5, span - 0.2, 0.03, 0.22, ROOF);
    for (const px of [-1, 0, 1]) k.box(x + px * (span - 0.3) / 2, 0, z + 0.6, 0.03, 0.24, 0.03, CLAP);
    for (const wx of [-0.18, 0.18]) k.box(x + wx, 0.38, z + 0.41, 0.12, 0.14, 0.01, TRIM);
    k.box(x, 0.06, z + 0.41, 0.12, 0.17, 0.01, TRIM);
    k.box(x + (span - 0.18) / 2 - 0.08, 0.62, z - 0.2, 0.08, 0.32, 0.08, hex(0x8a6a58));
  }
  // the flagpole on the parade lawn
  k.cyl(0, 0, D / 2 - 0.35, 0.015, 1.25, WHITE, 5);
  k.box(0.12, 1.08, D / 2 - 0.35, 0.22, 0.13, 0.006, [hex(0x2f4d7a), hex(0xc8342a), hex(0xf2efe6)][Math.floor(r() * 3)]);
};

/** An old coastal gun battery: concrete emplacements dug into the cliff top, grass over them, rusting barrels to sea. */
const gunBattery: Draw = (k, W, D) => {
  const CON = hex(0xb8b2a6), CON2 = hex(0x9c968a), GRASS = hex(0x7aa058);
  k.box(0, -0.1, -0.2, W - 0.2, 0.32, D - 0.6, GRASS);
  k.box(0, -0.1, D / 2 - 0.45, W - 0.2, 0.3, 0.3, CON);
  for (const sx of [-1, 1]) {
    const x = sx * (W / 4);
    k.cyl(x, 0.1, 0.15, 0.36, 0.1, CON2, 12);
    k.cyl(x, 0.2, 0.15, 0.12, 0.08, hex(0x5a4f45), 8);
    k.bar([x, 0.26, 0.15], [x, 0.34, 0.95], 0.05, hex(0x6a5a4a));
  }
  // the magazine doors in the back wall
  for (const sx of [-1, 1]) k.box(sx * 0.3, -0.05, -D / 2 + 0.12, 0.2, 0.2, 0.02, hex(0x4a4640));
};

/** A lookout: a low stone wall round a viewing place, a coin telescope and a bench. */
const lookoutPoint: Draw = (k) => {
  const STONE = hex(0xb3a58f);
  for (let i = 0; i < 7; i++) {
    const a0 = Math.PI * (i / 7), a1 = Math.PI * ((i + 1) / 7);
    k.bar([Math.cos(a0) * 0.36, 0.06, Math.sin(a0) * 0.36], [Math.cos(a1) * 0.36, 0.06, Math.sin(a1) * 0.36], 0.08, STONE);
  }
  k.cyl(0.1, 0, 0.1, 0.02, 0.24, METAL, 5);
  k.bar([0.1, 0.25, 0.1], [0.1, 0.29, 0.22], 0.04, hex(0x3f6a5a));
  k.box(-0.15, 0.06, -0.05, 0.3, 0.03, 0.09, PLANK);
};

// ---- rich enclaves (world/enclaves.ts) ------------------------------------------------------------------------------

const HEDGE = hex(0x3f7a3c), LAWN = hex(0x7fb35e), GRAVEL = hex(0xd6cdb8), POOL = hex(0x58b8d8);
export const ESTATE_STYLES = ['Georgian', 'Tudor revival', 'Mediterranean villa', 'Spanish colonial', 'Mid-century', 'Glass house', 'Château',
  'Shingle style', 'Columned mansion', 'Mega-mansion'] as const;

/** A row of lit windows along one face of a box: face 1 the front (+z), 3 the back, 0 the east (+x), 2 the west. */
function windows(k: Kit, b: Building, r: Rng, x: number, z: number, along: number, ys: number[], n: number, face: number, ww = 0.1, wh = 0.13): void {
  const sched = windowSched(b.kind, r), glow = windowGlow(b.kind, r);
  for (const y of ys) for (let i = 0; i < n; i++) {
    const t = n === 1 ? 0 : (i / (n - 1) - 0.5) * along;
    if (face === 1 || face === 3) k.pane(x + t, y, z, ww, wh, face, GLASS, sched, glow);
    else k.pane(x, y, z + t, ww, wh, face, GLASS, sched, glow);
  }
}

/** The grounds every estate stands in: lawn, a hedge round it with a gate at the front, the drive in, a car on it. */
function grounds(k: Kit, W: number, D: number, r: Rng, drive: RGB = GRAVEL): void {
  k.box(0, 0, 0, W - 0.04, 0.012, D - 0.04, LAWN);
  const e = W / 2 - 0.08, f = D / 2 - 0.08;
  k.box(0, 0, -f, W - 0.16, 0.14, 0.1, HEDGE);
  for (const sx of [-1, 1]) k.box(sx * e, 0, 0, 0.1, 0.14, D - 0.16, HEDGE);
  for (const sx of [-1, 1]) k.box(sx * ((e + 0.28) / 2), 0, f, e - 0.28, 0.14, 0.1, HEDGE);
  for (const sx of [-1, 1]) k.box(sx * 0.22, 0, f, 0.07, 0.2, 0.07, hex(0xd8d0c0));
  k.box(0, 0.013, f - 0.45, 0.3, 0.006, 0.8, drive);
  k.box(0, 0.013, 0.32, 0.9, 0.006, 0.3, drive);
  // the car out front, in one of the colours money buys
  const col = [hex(0x15161a), hex(0xc8102e), hex(0xf4f2ec), hex(0x2f4d7a), hex(0xb0b6bb)][Math.floor(r() * 5)];
  k.box(0.28, 0.02, 0.36, 0.2, 0.07, 0.11, col);
  k.box(0.27, 0.09, 0.36, 0.11, 0.05, 0.1, hex(0x36505e));
}

function pool(k: Kit, x: number, z: number, w: number, d: number): void {
  k.box(x, 0.013, z, w + 0.06, 0.012, d + 0.06, hex(0xe8e2d4));
  k.box(x, 0.02, z, w, 0.008, d, POOL);
}

function tennis(k: Kit, x: number, z: number): void {
  k.box(x, 0.013, z, 0.62, 0.008, 1.0, hex(0x4f8a5a));
  k.box(x, 0.021, z, 0.5, 0.003, 0.012, WHITE);
  k.box(x, 0.021, z, 0.012, 0.003, 0.86, WHITE);
  k.box(x, 0.02, z, 0.6, 0.06, 0.01, hex(0x2f3a3a));
}

function roundTree(k: Kit, x: number, z: number, s = 1): void {
  k.cyl(x, 0, z, 0.03 * s, 0.2 * s, hex(0x6a5038), 5);
  k.dome(x, 0.16 * s, z, 0.17 * s, hex(0x4e9a44), 7, 3);
}
function cypressTree(k: Kit, x: number, z: number): void {
  k.cyl(x, 0, z, 0.02, 0.06, hex(0x6a5038), 5);
  k.cone(x, 0.05, z, 0.07, 0.55, hex(0x2f5f3a), 6);
}

const estateHouse: Draw = (k, W, D, b, r) => {
  const style = b.seed % ESTATE_STYLES.length;
  const hz = -0.42;
  switch (style) {
    case 0: { // Georgian: red brick, a white portico, a hipped slate roof, chimneys at the ends
      grounds(k, W, D, r);
      const BRICK = hex(0xa4553e), w = 1.7, d = 1.0, h = 0.72;
      k.box(0, 0, hz, w, h, d, BRICK);
      k.box(0, h, hz, w + 0.04, 0.04, d + 0.04, WHITE);
      k.hip(0, h + 0.04, hz, w + 0.04, 0.32, d + 0.04, hex(0x4d5862));
      for (const sx of [-1, 1]) k.box(sx * (w / 2 - 0.12), h, hz, 0.14, 0.42, 0.22, BRICK);
      for (let i = 0; i < 4; i++) k.cyl(-0.27 + i * 0.18, 0, hz + d / 2 + 0.16, 0.025, 0.58, WHITE, 6);
      k.box(0, 0.58, hz + d / 2 + 0.16, 0.66, 0.05, 0.3, WHITE);
      k.gable(0, 0.63, hz + d / 2 + 0.16, 0.66, 0.16, 0.3, WHITE, WHITE);
      windows(k, b, r, 0, hz + d / 2, w - 0.3, [0.14, 0.44], 5, 1);
      pool(k, -0.8, 0.7, 0.5, 0.7);
      break;
    }
    case 1: { // Tudor revival: cream render over dark timbers, two steep front gables, a tall brick chimney
      grounds(k, W, D, r);
      const CREAM = hex(0xece2c6), BEAM = hex(0x3e2c20), w = 1.8, d = 0.95, h = 0.6;
      k.box(0, 0, hz, w, h, d, CREAM);
      k.gable(0, h, hz, w + 0.06, 0.42, d + 0.1, hex(0x6b4a3a), CREAM);
      for (const sx of [-0.45, 0.45]) {
        k.box(sx, 0, hz + d / 2 + 0.12, 0.6, h, 0.25, CREAM);
        k.gable(sx, h, hz + d / 2 + 0.12, 0.66, 0.5, 0.3, hex(0x6b4a3a), CREAM, true);
        for (let i = 0; i < 4; i++) k.box(sx - 0.24 + i * 0.16, 0.05, hz + d / 2 + 0.25, 0.025, h - 0.1, 0.01, BEAM);
        k.box(sx, 0.32, hz + d / 2 + 0.25, 0.58, 0.025, 0.01, BEAM);
      }
      k.box(0.7, 0, hz - 0.2, 0.18, 1.35, 0.18, hex(0x8a4a38));
      windows(k, b, r, 0, hz + d / 2 + 0.26, 0.9, [0.16, 0.42], 2, 1, 0.12, 0.1);
      tennis(k, -0.95, 0.55);
      break;
    }
    case 2: { // Mediterranean villa: ochre stucco, a low red tile roof, an arcade along the front, cypresses
      grounds(k, W, D, r, hex(0xd8c0a0));
      const STUCCO = hex(0xe3b77d), TILE = hex(0xb4553a), w = 1.9, d = 1.0, h = 0.66;
      k.box(0, 0, hz, w, h, d, STUCCO);
      k.hip(0, h, hz, w + 0.12, 0.22, d + 0.12, TILE);
      k.box(0.5, h, hz - 0.1, 0.5, 0.28, 0.5, STUCCO);
      k.hip(0.5, h + 0.28, hz - 0.1, 0.58, 0.14, 0.58, TILE);
      for (let i = 0; i < 5; i++) {
        const x = -0.72 + i * 0.36;
        k.box(x, 0, hz + d / 2 + 0.01, 0.2, 0.3, 0.012, hex(0x5a3a2a));
      }
      windows(k, b, r, 0, hz + d / 2, 1.4, [0.46], 5, 1);
      pool(k, 0, 0.62, 1.0, 0.45);
      for (const [x, z] of [[-1.2, 0.4], [-1.2, -0.2], [1.2, 0.4], [1.2, -0.2]]) cypressTree(k, x, z);
      break;
    }
    case 3: { // Spanish colonial: white walls round a courtyard with a fountain, red tile roofs
      grounds(k, W, D, r, hex(0xd8c0a0));
      const WALL = hex(0xf2ede2), TILE = hex(0xb85a3a);
      for (const [x, z, w, d] of [[0, -0.85, 1.9, 0.5], [-0.75, -0.25, 0.45, 0.8], [0.75, -0.25, 0.45, 0.8]] as [number, number, number, number][]) {
        k.box(x, 0, z, w, 0.52, d, WALL);
        k.hip(x, 0.52, z, w + 0.08, 0.16, d + 0.08, TILE);
      }
      k.box(0, 0.01, -0.3, 1.0, 0.012, 0.7, hex(0xd9c49a));
      k.cyl(0, 0.02, -0.3, 0.14, 0.06, hex(0xe0d8c8), 10);
      k.cyl(0, 0.08, -0.3, 0.03, 0.12, hex(0xe0d8c8), 6);
      k.box(0, 0, 0.18, 1.05, 0.28, 0.06, WALL);
      k.box(0, 0.3, 0.18, 0.3, 0.12, 0.07, TILE);
      windows(k, b, r, 0, -0.6, 1.4, [0.24], 4, 1);
      break;
    }
    case 4: { // Mid-century: long and low, a butterfly roof, the front all glass, a breeze-block screen
      grounds(k, W, D, r, hex(0x9a9a92));
      const w = 2.1, d = 0.9, h = 0.42, ROOF = hex(0x5a6066), IN: P3 = [0, 0, hz];
      k.box(0, 0, hz, w, h, d, hex(0xefe9dc));
      k.box(-0.55, 0, hz, 0.9, h, d + 0.02, hex(0x9a6a44));
      k.quad([-w / 2 - 0.1, h + 0.12, hz - d / 2 - 0.1], [0, h + 0.02, hz - d / 2 - 0.1], [0, h + 0.02, hz + d / 2 + 0.15], [-w / 2 - 0.1, h + 0.12, hz + d / 2 + 0.15], ROOF, IN);
      k.quad([0, h + 0.02, hz - d / 2 - 0.1], [w / 2 + 0.1, h + 0.12, hz - d / 2 - 0.1], [w / 2 + 0.1, h + 0.12, hz + d / 2 + 0.15], [0, h + 0.02, hz + d / 2 + 0.15], ROOF, IN);
      windows(k, b, r, 0.45, hz + d / 2, 0.8, [0.18], 3, 1, 0.24, 0.3);
      pool(k, 0.45, 0.62, 0.9, 0.42);
      k.box(-1.0, 0, 0.3, 0.06, 0.32, 0.5, hex(0xd8cfbf));
      break;
    }
    case 5: { // Glass house: white boxes stacked and cantilevered, bands of glass, an infinity pool on its edge
      grounds(k, W, D, r, hex(0xb8b8b0));
      k.box(0, 0, hz, 1.6, 0.36, 0.9, hex(0xf6f6f2));
      k.box(0.35, 0.36, hz + 0.12, 1.4, 0.34, 0.75, hex(0xf6f6f2));
      k.box(0.35, 0.7, hz + 0.12, 1.46, 0.03, 0.8, hex(0x2f3438));
      windows(k, b, r, 0, hz + 0.45, 1.3, [0.12], 3, 1, 0.38, 0.22);
      windows(k, b, r, 0.35, hz + 0.5, 1.1, [0.46], 3, 1, 0.36, 0.22);
      pool(k, 0, 0.7, 2.0, 0.32);
      for (const x of [-1.15, 1.15]) roundTree(k, x, -0.2, 0.9);
      break;
    }
    case 6: { // Château: pale stone, a steep slate mansard, round turrets with cones, a gravel court
      grounds(k, W, D, r);
      const STONE = hex(0xe2d8c2), SLATE = hex(0x4a5560), w = 1.6, d = 0.95, h = 0.62;
      k.box(0, 0, hz, w, h, d, STONE);
      k.box(0, h, hz, w - 0.1, 0.32, d - 0.1, SLATE);
      k.hip(0, h + 0.32, hz, w - 0.1, 0.24, d - 0.1, SLATE);
      for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
        const x = sx * (w / 2), z = hz + sz * (d / 2);
        k.cyl(x, 0, z, 0.17, h + 0.25, STONE, 10);
        k.cone(x, h + 0.25, z, 0.21, 0.5, SLATE, 10);
      }
      for (let i = 0; i < 3; i++) k.box(-0.4 + i * 0.4, h + 0.1, hz + d / 2 - 0.04, 0.12, 0.16, 0.08, STONE);
      windows(k, b, r, 0, hz + d / 2, 1.2, [0.14, 0.4], 4, 1);
      k.box(0, 0.014, 0.42, 1.3, 0.006, 0.55, GRAVEL);
      k.cyl(0, 0.02, 0.42, 0.12, 0.05, STONE, 10);
      break;
    }
    case 7: { // Shingle style: grey shingles rambling under several gables, a wide porch, a round tower
      grounds(k, W, D, r);
      const SHINGLE = hex(0x8f9396), ROOF = hex(0x5e5650), TRIM = hex(0xf4f2ec);
      k.box(-0.15, 0, hz, 1.5, 0.6, 0.95, SHINGLE);
      k.gable(-0.15, 0.6, hz, 1.56, 0.4, 1.0, ROOF, SHINGLE);
      k.box(-0.55, 0.3, hz + 0.45, 0.5, 0.3, 0.2, SHINGLE);
      k.gable(-0.55, 0.6, hz + 0.45, 0.54, 0.26, 0.24, ROOF, SHINGLE, true);
      k.cyl(0.72, 0, hz + 0.2, 0.22, 0.86, SHINGLE, 10);
      k.cone(0.72, 0.86, hz + 0.2, 0.27, 0.42, ROOF, 10);
      k.box(-0.1, 0.22, hz + 0.62, 1.5, 0.03, 0.32, ROOF);
      for (let i = 0; i < 6; i++) k.box(-0.82 + i * 0.29, 0, hz + 0.76, 0.03, 0.22, 0.03, TRIM);
      windows(k, b, r, -0.15, hz + 0.48, 1.0, [0.38], 3, 1);
      roundTree(k, 1.1, 0.6);
      break;
    }
    case 8: { // Columned mansion: white, a two-storey colonnade the full width, a hipped roof, an avenue of oaks
      grounds(k, W, D, r);
      const w = 1.8, d = 1.0, h = 0.74;
      k.box(0, 0, hz, w, h, d, hex(0xf6f3ea));
      k.hip(0, h, hz, w + 0.3, 0.3, d + 0.36, hex(0x3e4a52));
      for (let i = 0; i < 6; i++) k.cyl(-0.8 + i * 0.32, 0, hz + d / 2 + 0.14, 0.032, h, WHITE, 8);
      k.box(0, 0.36, hz + d / 2 + 0.1, w - 0.1, 0.03, 0.2, hex(0xe8e2d4));
      windows(k, b, r, 0, hz + d / 2, w - 0.4, [0.14, 0.48], 5, 1);
      for (const z of [0.25, 0.65, 1.05]) for (const sx of [-1, 1]) roundTree(k, sx * 0.5, z, 0.75);
      break;
    }
    default: { // Mega-mansion: wings of pale stone round a motor court, an entrance tower, a helipad on the lawn
      grounds(k, W, D, r, hex(0xd9d2c4));
      const STONE = hex(0xe6dcc6), ROOF = hex(0x6b5a4a);
      k.box(0, 0, -0.8, 2.3, 0.7, 0.7, STONE);
      k.hip(0, 0.7, -0.8, 2.38, 0.3, 0.78, ROOF);
      for (const sx of [-1, 1]) { k.box(sx * 0.95, 0, -0.15, 0.55, 0.6, 0.85, STONE); k.hip(sx * 0.95, 0.6, -0.15, 0.62, 0.26, 0.92, ROOF); }
      k.box(0, 0, -0.38, 0.5, 0.95, 0.3, STONE);
      k.hip(0, 0.95, -0.38, 0.56, 0.3, 0.36, ROOF);
      windows(k, b, r, 0, -0.45, 1.8, [0.14, 0.44], 6, 1);
      k.cyl(0, 0.014, 0.1, 0.18, 0.04, hex(0xd8d0c0), 12);
      k.cyl(0, 0.05, 0.1, 0.03, 0.12, hex(0xd8d0c0), 6);
      k.disc(-0.9, 0.016, 0.85, 0.26, hex(0x5a6066), 14);
      k.box(-0.9, 0.02, 0.85, 0.04, 0.003, 0.2, WHITE);
      k.box(-0.82, 0.02, 0.85, 0.04, 0.003, 0.2, WHITE);
      k.box(-0.86, 0.02, 0.85, 0.1, 0.003, 0.04, WHITE);
      pool(k, 0.85, 0.7, 0.6, 0.5);
      break;
    }
  }
};

