import * as THREE from 'three';
import { Biome, Feature, Flag, RoadType, Surface, World, heightOnTile, idx, inB } from '../world/tiles';
import { SEASON, PERMANENT_SNOW } from './season';
import { DRIVE_WEATHER } from '../game/car';
import type { LandDef, VehicleState } from '../game/vehicles';

/**
 * Tyre tracks: soft ground remembers a vehicle for a few seconds after it has gone. Dirt roads and
 * tracks, farm soil, sand, mud and lying snow take them; paved roads, grass, rock and ice don't.
 *
 * Every land vehicle nearby leaves its own: two lines as wide apart as its wheels (one for the
 * motorbike), as wide as its tyres, and a second pair from a trailer's axle. Each line is a strip
 * of quads laid a short step at a time, darker on mud than on sand, and each fades on the ground's
 * own clock: dirt soonest, snow last.
 *
 * The quads multiply the ground beneath them rather than being painted over it, so a track is the
 * same shade of darker by noon, at dusk and under a streetlight. They live in a ring buffer that is
 * written a few quads a frame and uploaded only where written.
 */

type Ground = 'dirt' | 'sand' | 'mud' | 'snow' | 'skid';

/** What each ground does with a track: the shade it darkens to, how strongly, and for how long. */
const GROUNDS: Record<Ground, { tint: [number, number, number]; strength: number; life: number }> = {
  dirt: { tint: [0.58, 0.47, 0.37], strength: 0.62, life: 6 },
  sand: { tint: [0.66, 0.53, 0.4], strength: 0.72, life: 9 },
  mud: { tint: [0.45, 0.36, 0.28], strength: 0.75, life: 12 },
  snow: { tint: [0.72, 0.78, 0.9], strength: 0.7, life: 15 },
  // rubber: a drift, a burnout or a hard stop marks any ground, tarmac and grass included
  skid: { tint: [0.34, 0.34, 0.36], strength: 0.5, life: 10 },
};

/** The ground a track would print on at tile i of w, if it takes one at all. */
function trackGround(w: World, i: number, groundY: number): Ground | null {
  if (w.water[i] >= 0) return null;
  const road = w.road[i] as RoadType;
  if (road && road !== RoadType.Dirt) return null;
  const surf = w.surface[i] as Surface;
  if (surf === Surface.Ice || surf === Surface.Rock || surf === Surface.Lava || surf === Surface.Basalt || surf === Surface.Cave || surf === Surface.Salt) return null;
  // snow lying on it wins over whatever is underneath
  const lying = SEASON.uSnow.value * smoothstep(SEASON.uSnowLine.value, SEASON.uSnowLine.value + 1.6, groundY);
  const always = smoothstep(PERMANENT_SNOW, PERMANENT_SNOW + 2.2, groundY);
  if (Math.max(lying, always) > 0.5 || w.biome[i] === Biome.Snow) return 'snow';
  if (surf === Surface.Marsh || w.biome[i] === Biome.Marsh) return 'mud';
  const b = w.biome[i];
  if (surf === Surface.Sand || b === Biome.Beach || b === Biome.Desert || b === Biome.Canyon || w.feature[i] === Feature.Beach) return 'sand';
  const soil = road === RoadType.Dirt || (w.flags[i] & (Flag.Track | Flag.Field)) !== 0 || b === Biome.Farm;
  // after the rain the Green's unpaved ground is mud for a while (see DRIVE_WEATHER)
  if (DRIVE_WEATHER.mud > 0.3 && !road) return 'mud';
  return soil ? 'dirt' : null;
}

function smoothstep(a: number, b: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

const VERT = /* glsl */ `
attribute float aBirth;
attribute float aLife;
attribute vec4 aTint;
attribute vec2 aTread;
uniform float uTime;
varying vec4 vTint;
varying vec2 vTread;
varying float vFade;
void main() {
  float f = (uTime - aBirth) / aLife;
  vTint = aTint;
  vTread = aTread;
  // hold, then fade out over the back half of its life
  vFade = 1.0 - smoothstep(0.45, 1.0, f);
  if (f >= 1.0 || f < 0.0) { gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return; }
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;
const FRAG = /* glsl */ `
varying vec4 vTint;
varying vec2 vTread;
varying float vFade;
void main() {
  // soft edges across the tyre, and a tread pattern along it
  float edge = 1.0 - smoothstep(0.55, 1.0, abs(vTread.x));
  float tread = 0.78 + 0.22 * step(0.45, fract(vTread.y));
  float a = vTint.a * vFade * edge * tread;
  gl_FragColor = vec4(mix(vec3(1.0), vTint.rgb, a), 1.0);
}`;

/** Quads the buffer holds; the oldest are overwritten first, and by then have long faded. */
const MAX = 6000;
/** Distance (tiles) a wheel travels between quads. */
const STEP_LEN = 0.07;
/** Tread blocks per tile along a track. */
const TREAD = 22;

/** One wheel line's last laid point: where it was, the edge offsets there, how far along the track. */
interface Line { x: number; z: number; y: number; lx: number; lz: number; along: number; ground: Ground | null; heading: number }

/** One vehicle's wheels at a time (drive): x, z and heading, a trailer's too. */
const WX = new Float64Array(4), WZ = new Float64Array(4), WH = new Float64Array(4);

export class TyreTracks {
  readonly mesh: THREE.Mesh;
  private pos = new Float32Array(MAX * 4 * 3);
  private birth = new Float32Array(MAX * 4);
  private life = new Float32Array(MAX * 4);
  private tint = new Float32Array(MAX * 4 * 4);
  private tread = new Float32Array(MAX * 4 * 2);
  private next = 0;
  private time = 0;
  private lines = new WeakMap<object, Line[]>();
  /** The home island's origin the positions are relative to. */
  private ox = NaN;
  private oz = NaN;
  private lo = Infinity;
  private hi = -1;
  /** Every position moved (home changed), so the whole buffer goes up this frame. */
  private shifted = false;
  private material: THREE.ShaderMaterial;

  constructor() {
    const g = new THREE.BufferGeometry();
    const index = new Uint32Array(MAX * 6);
    for (let q = 0; q < MAX; q++) {
      const v = q * 4, k = q * 6;
      index.set([v, v + 1, v + 2, v + 2, v + 1, v + 3], k);
    }
    g.setIndex(new THREE.BufferAttribute(index, 1));
    g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aBirth', new THREE.BufferAttribute(this.birth, 1).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aLife', new THREE.BufferAttribute(this.life, 1).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aTint', new THREE.BufferAttribute(this.tint, 4).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aTread', new THREE.BufferAttribute(this.tread, 2).setUsage(THREE.DynamicDrawUsage));
    this.life.fill(1);
    this.birth.fill(-1e6);
    this.material = new THREE.ShaderMaterial({
      vertexShader: VERT, fragmentShader: FRAG,
      uniforms: { uTime: { value: 0 } },
      transparent: true, depthWrite: false, side: THREE.DoubleSide,
      // multiply what is already drawn: dst * src
      blending: THREE.CustomBlending, blendEquation: THREE.AddEquation, blendSrc: THREE.ZeroFactor, blendDst: THREE.SrcColorFactor,
      polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2,
    });
    this.mesh = new THREE.Mesh(g, this.material);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 2;
  }

  /**
   * Start a frame. `dt` is the world's time (0 while paused); `home` is the island the positions are
   * kept relative to, and when that changes every track is shifted so it stays where it was laid.
   */
  begin(dt: number, home: World): void {
    this.time += dt;
    this.material.uniforms.uTime.value = this.time;
    if (Number.isNaN(this.ox)) { this.ox = home.ox; this.oz = home.oz; }
    if (home.ox !== this.ox || home.oz !== this.oz) {
      const dx = this.ox - home.ox, dz = this.oz - home.oz;
      for (let k = 0; k < this.pos.length; k += 3) { this.pos[k] += dx; this.pos[k + 2] += dz; }
      this.shifted = true;
      this.ox = home.ox;
      this.oz = home.oz;
      this.lines = new WeakMap();
    }
  }

  /**
   * A land vehicle `s` of `def` on island `w` (its own frame; `w` may be a neighbour of home) lays
   * track where it has gone since last frame.
   */
  drive(s: VehicleState, def: LandDef, w: World, dt: number): void {
    if (dt <= 0) return;
    const car = s as VehicleState & { onDeck?: boolean; onRailDeck?: boolean; inWater?: boolean; swimming?: boolean };
    const offX = w.ox - this.ox, offZ = w.oz - this.oz;
    const hw = def.halfWid ?? 0.3, hl = def.halfLen ?? 0.45;
    const single = def.tyres?.single === true;
    const width = hw * (def.tyres?.width ?? 0.38);
    const fx = Math.sin(s.heading), fz = Math.cos(s.heading);
    // the rear axle, and a trailer's: their wheels into the scratch buffers (no arrays or objects a car a frame:
    // every land vehicle near the camera is tracked, and they were a good share of the garbage, 7 Nov 2026)
    let nw = 0;
    const axle = (x: number, z: number, h: number) => {
      if (single) { WX[nw] = x; WZ[nw] = z; WH[nw++] = h; return; }
      const ax = Math.cos(h) * hw * 0.78, az = -Math.sin(h) * hw * 0.78;
      WX[nw] = x - ax; WZ[nw] = z - az; WH[nw++] = h;
      WX[nw] = x + ax; WZ[nw] = z + az; WH[nw++] = h;
    };
    axle(s.x - fx * hl * 0.55, s.z - fz * hl * 0.55, s.heading);
    if (def.trailer) {
      const hx = s.x - fx * def.trailer.hitch, hz = s.z - fz * def.trailer.hitch;
      const tx = Math.sin(s.trailerHeading), tz = Math.cos(s.trailerHeading);
      axle(hx - tx * def.trailer.length, hz - tz * def.trailer.length, s.trailerHeading);
    }
    let lines = this.lines.get(s);
    if (!lines || lines.length !== nw) {
      lines = [];
      for (let k = 0; k < nw; k++) lines.push({ x: NaN, z: NaN, y: 0, lx: 0, lz: 0, along: 0, ground: null, heading: 0 });
      this.lines.set(s, lines);
    }
    const lifted = car.onDeck || car.onRailDeck || car.swimming || car.inWater;
    // hard cornering and braking dig in a little deeper
    const dig = 0.8 + 0.2 * Math.min(1, Math.abs(s.steerVis) / 0.45 * Math.min(1, Math.abs(s.v) / 2));
    for (let k = 0; k < nw; k++) {
      const wx = WX[k], wz = WZ[k], wHead = WH[k], line = lines[k];
      const tx = Math.floor(wx), tz = Math.floor(wz);
      if (lifted || !inB(tx, tz)) { line.x = NaN; continue; }
      const i = idx(tx, tz);
      const y = heightOnTile(w, tx, tz, wx, wz);
      const skid = s.skid ?? 0;
      const soft = trackGround(w, i, y);
      const ground = soft ?? (skid > 0.25 && w.water[i] < 0 ? 'skid' : null);
      // edge offsets at this point, square to the wheel's heading
      const ex = Math.cos(wHead) * width, ez = -Math.sin(wHead) * width;
      const moved = Math.hypot(wx - line.x, wz - line.z);
      if (!ground || Number.isNaN(line.x) || moved > 1 || line.ground !== ground) {
        // start a fresh line here (off soft ground, just arrived, teleported or crossed onto other ground)
        line.x = wx; line.z = wz; line.y = y; line.lx = ex; line.lz = ez; line.ground = ground; line.heading = wHead;
        continue;
      }
      if (moved < STEP_LEN) continue;
      const g = GROUNDS[ground];
      const along = line.along + moved;
      this.quad(
        line.x + offX, line.y, line.z + offZ, line.lx, line.lz, line.along,
        wx + offX, y, wz + offZ, ex, ez, along,
        g.tint, Math.min(0.95, g.strength * dig * (ground === 'skid' ? 0.4 + 0.6 * skid : 1 + 0.35 * skid)), g.life,
      );
      line.x = wx; line.z = wz; line.y = y; line.lx = ex; line.lz = ez; line.along = along; line.heading = wHead;
    }
  }

  private quad(
    x0: number, y0: number, z0: number, ex0: number, ez0: number, a0: number,
    x1: number, y1: number, z1: number, ex1: number, ez1: number, a1: number,
    tint: [number, number, number], strength: number, life: number,
  ): void {
    const q = this.next;
    this.next = (this.next + 1) % MAX;
    const v = q * 4;
    const lift = 0.012;
    this.pos.set([
      x0 - ex0, y0 + lift, z0 - ez0,
      x0 + ex0, y0 + lift, z0 + ez0,
      x1 - ex1, y1 + lift, z1 - ez1,
      x1 + ex1, y1 + lift, z1 + ez1,
    ], v * 3);
    for (let c = 0; c < 4; c++) {
      this.birth[v + c] = this.time;
      this.life[v + c] = life * (0.9 + Math.random() * 0.2);
      this.tint.set([tint[0], tint[1], tint[2], strength], (v + c) * 4);
    }
    this.tread.set([-1, a0 * TREAD, 1, a0 * TREAD, -1, a1 * TREAD, 1, a1 * TREAD], v * 2);
    this.lo = Math.min(this.lo, q);
    this.hi = Math.max(this.hi, q);
  }

  /** Upload whatever was laid this frame. */
  end(): void {
    const g = this.mesh.geometry;
    if (this.shifted) {
      const attr = g.getAttribute('position') as THREE.BufferAttribute;
      attr.clearUpdateRanges();
      attr.needsUpdate = true;
    }
    if (this.hi < 0) { this.shifted = false; return; }
    const lo = this.lo, count = this.hi - this.lo + 1;
    for (const [name, size] of [['position', 12], ['aBirth', 4], ['aLife', 4], ['aTint', 16], ['aTread', 8]] as const) {
      const attr = g.getAttribute(name) as THREE.BufferAttribute;
      if (name === 'position' && this.shifted) continue;
      attr.clearUpdateRanges();
      attr.addUpdateRange(lo * size, count * size);
      attr.needsUpdate = true;
    }
    this.shifted = false;
    this.lo = Infinity;
    this.hi = -1;
  }
}
