import * as THREE from 'three';
import { N, type World } from '../world/tiles';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { buildCar, disposeCar, type CarMesh } from '../render/trainMeshes';
import { dressTrainTreats } from '../render/treats';
import { applyParts, emptyParts, fitted, owned, unpackParts, type Parts } from '../game/parts';
import { defOf } from '../game/fleet';
import { CARS, COUPLING_GAP, SETS, fillSet } from '../game/rollingStock';
import { hashString, mulberry32 } from '../world/rng';
import type { VehicleDef, VehicleState } from '../game/vehicles';
import type { BadgeLook } from '../render/fleetBadges';
import { treatsOfLook, type TreatLook } from '../game/treats';
import type { Look, Pid, Pose, UnitLook, Who } from '../../shared/protocol';

/**
 * The other players, as this game draws them: each one's vehicle and whatever of their fleet is out on
 * the map, posed a little in the past and eased between the positions the server passes on. They are
 * ghosts to the physics (nobody can be pushed), and they are only drawn on cells this game has in
 * memory. A player who signs out takes their vehicles with them.
 */

/**
 * How the others' motion is smoothed (Oct 2026: the user saw a friend's car skip). The way most online games
 * do it — snapshot interpolation:
 *   - every position carries its sender's own clock (Pose `t`), so it is placed on the sender's timeline,
 *     not by when the beat happened to arrive; that timeline is mapped onto ours by the least delay seen
 *     (the offset creeps up a little so clocks that drift apart are followed);
 *   - a short buffer of them is kept, and the vehicle is drawn `delay` behind the newest, where there is
 *     nearly always a position either side; the delay grows with the jitter measured on the line (half a
 *     second of it at most) and shrinks back as the line settles;
 *   - between two positions it follows the curve their speeds and headings describe (Hermite), not a
 *     straight chord, so a bend is a bend;
 *   - past the newest it is carried on along its heading for COAST, and when the truth arrives somewhere
 *     else the gap is eased out over ERR_EASE rather than snapped (a teleport — a ferry, a tow — still jumps).
 */
const DELAY_MIN = 0.1, DELAY_MAX = 0.4;
/** Seconds past the newest position a vehicle is carried on along its heading before it is left standing. */
const COAST = 0.5;
/** Seconds for a correction to ease out, and the gap (tiles) past which it is a jump, not a correction. */
const ERR_EASE = 0.12, ERR_SNAP = 4;
/** Positions kept per vehicle, and how far back (seconds). */
const BUF = 24, BUF_SECS = 3;
/** Seconds without a word before a working vehicle is taken off the map. */
const STALE = 4;
/** Tiles from the camera's focus past which a name tag is not shown. */
const TAG_FAR = 110;

interface Sample { t: number; x: number; z: number; y: number; h: number; v: number; pitch: number; roll: number }

/** A point in world tiles (y in world units). */
export interface Pt3 { x: number; y: number; z: number }
/** One car of another player's train: its model, how far its centre is behind the engine's, and its bogies' half-spacing. */
interface RemoteCar { mesh: CarMesh; back: number; bogie: number }
/** Spacing (tiles) of the points kept along a train's way, and how much of it to keep past its length. */
const CRUMB = 0.25, CRUMB_SPARE = 4;

/** Where a vehicle is drawn on our clock: its buffer, the sender's clock mapped onto ours, and the smoothing's state. */
interface Line {
  buf: Sample[];
  /** Our clock minus the sender's (seconds), at the least delay seen; null until the first stamped position. */
  off: number | null;
  /** Mean extra delay over the least (seconds): the jitter, and the drawing delay it asks for. */
  jit: number;
  delay: number;
  /** The correction still being eased out (world tiles), and where it was drawn last frame. */
  ex: number; ez: number;
  lx: number; lz: number; drawn: boolean;
}

interface Body {
  def: VehicleDef;
  key: string;
  mesh: VehicleMesh | null;
  group: THREE.Group;
  a: Sample | null; b: Sample | null;
  line: Line;
  state: VehicleState;
  /**
   * A train (the user, 28 Oct 2026: a friend's train was only a name over the line): its cars, the engine at the
   * position heard and the rest along `way`, the line behind the engine newest first (world tiles), laid from the
   * track when first seen and then from where the engine has run.
   */
  cars: RemoteCar[] | null;
  way: Pt3[];
  spin: number;
  /** Parked: it stands where its owner left it, with no positions coming. */
  parked: boolean;
  seen: number;
  top: number;
  /** Where it was last drawn, in world tiles. */
  gx: number; gy: number; gz: number; shown: boolean;
}

interface Player {
  who: Who;
  look: Look | null;
  own: Body | null;
  units: Map<number, Body>;
  tag: HTMLDivElement;
  cell: string;
}

/**
 * One of another player's vehicles as the inspector sees it (game/inspect.ts): whose, which (uid null: the one
 * they drive), its model, and where it is. `shown`: drawn this frame on a cell in memory; `known`: a position
 * has been heard (else x/z are only where its owner is thought to be).
 */
export interface RemoteSeen {
  pid: Pid; uid: number | null; def: VehicleDef; parts?: Parts;
  x: number; y: number; z: number; heading: number; v: number;
  parked: boolean; shown: boolean; known: boolean;
  /** Its model, for the selection ring's shading; null when it isn't drawn. */
  root: THREE.Object3D | null;
}

const blankState = (): VehicleState => ({
  x: 0, y: 0, z: 0, heading: 0, v: 0, pitch: 0, roll: 0, bob: 0, lean: 0, wheelSpin: 0, steerVis: 0, power: 0, blocked: 0,
  trailerHeading: 0, sailAngle: 0, surfaceY: NaN, step() { /* driven from afar */ }, status: () => '',
});

const newLine = (): Line => ({ buf: [], off: null, jit: 0, delay: 0.16, ex: 0, ez: 0, lx: 0, lz: 0, drawn: false });

const lerpAngle = (a: number, b: number, k: number): number => {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  else if (d < -Math.PI) d += Math.PI * 2;
  return a + d * k;
};

export class Remotes {
  readonly root = new THREE.Group();
  private players = new Map<Pid, Player>();
  private defs = new Map<string, VehicleDef>();
  private tags = document.createElement('div');
  private v = new THREE.Vector3();
  private box = new THREE.Box3();
  private clock = 0;
  /** The line behind a train's engine at (x, z) facing h, `len` tiles of it from the engine back, newest first; null with no track there. */
  railBehind: ((x: number, z: number, h: number, len: number, rack: boolean) => Pt3[] | null) | null = null;

  constructor(scene: THREE.Scene) {
    scene.add(this.root);
    this.tags.id = 'net-tags';
    document.body.append(this.tags);
  }

  get count(): number { return this.players.size; }
  ids(): Pid[] { return [...this.players.keys()]; }
  whoOf(id: Pid): Who | null { return this.players.get(id)?.who ?? null; }
  /** Where a player's own vehicle is drawn, in world tiles, while it is on a cell in memory; else null. */
  posOf(id: Pid): { x: number; y: number; z: number } | null {
    const o = this.players.get(id)?.own;
    return o?.shown ? { x: o.gx, y: o.gy, z: o.gz } : null;
  }
  cellOf(id: Pid): string | null { return this.players.get(id)?.cell ?? null; }
  /** Where the goods aboard a player's own vehicle are going (Look.d), in world tiles; empty when nothing is aboard. */
  dropsOf(id: Pid): { x: number; y: number; z: number; value: number }[] {
    const d = this.players.get(id)?.look?.d;
    const out: { x: number; y: number; z: number; value: number }[] = [];
    if (Array.isArray(d)) for (let i = 0; i + 3 < d.length; i += 4) out.push({ x: d[i], y: d[i + 1], z: d[i + 2], value: d[i + 3] });
    return out;
  }

  /** One of a player's vehicles (uid null: the one they drive), as the inspector sees it; null once it's gone. */
  vehicle(id: Pid, uid: number | null): RemoteSeen | null {
    const p = this.players.get(id);
    const b = p ? (uid === null ? p.own : p.units.get(uid) ?? null) : null;
    return p && b ? this.seen(p, b, uid) : null;
  }

  /** Everything of a player's out on the map: the vehicle they drive first, then each of their fleet. Null when they aren't signed in. */
  fleetOf(id: Pid): RemoteSeen[] | null {
    const p = this.players.get(id);
    if (!p) return null;
    const out: RemoteSeen[] = [];
    if (p.own) out.push(this.seen(p, p.own, null));
    for (const [uid, b] of p.units) out.push(this.seen(p, b, uid));
    return out;
  }

  /** Every vehicle of the others drawn this frame, for a click to pick (game/inspect.ts pickVehicle). */
  drawn(): RemoteSeen[] {
    const out: RemoteSeen[] = [];
    for (const p of this.players.values()) {
      if (p.own?.shown) out.push(this.seen(p, p.own, null));
      for (const [uid, b] of p.units) if (b.shown) out.push(this.seen(p, b, uid));
    }
    return out;
  }

  private seen(p: Player, b: Body, uid: number | null): RemoteSeen {
    const look = uid === null ? p.look : p.look?.units.find((u) => u.uid === uid);
    const parts = look ? unpackParts(look.p as Parts | undefined) : undefined;
    const last = b.b;
    if (b.shown) {
      return { pid: p.who.id, uid, def: b.def, parts, x: b.gx, y: b.gy, z: b.gz, heading: b.state.heading, v: b.state.v, parked: b.parked, shown: true, known: true, root: b.group };
    }
    if (last) return { pid: p.who.id, uid, def: b.def, parts, x: last.x, y: last.y, z: last.z, heading: last.h, v: b.parked ? 0 : last.v, parked: b.parked, shown: false, known: true, root: null };
    // never heard of: somewhere round its owner (their own vehicle when it has been, else the middle of their cell)
    const o = p.own?.b;
    const [cx, cz] = p.cell ? p.cell.split(',').map(Number) : [NaN, NaN];
    const x = o ? o.x : Number.isFinite(cx) ? (cx + 0.5) * N : 0, z = o ? o.z : Number.isFinite(cz) ? (cz + 0.5) * N : 0;
    return { pid: p.who.id, uid, def: b.def, parts, x, y: o?.y ?? 0, z, heading: 0, v: 0, parked: b.parked, shown: false, known: false, root: null };
  }

  /** A model with a unit's parts on it, in its fleet's livery unless it has been resprayed: as game/fleet.ts defFor. */
  private defFor(model: string, packed: unknown, who: Who): { def: VehicleDef; key: string } {
    const b = who.brand;
    const key = `${model}#${JSON.stringify(packed ?? null)}#${b ? `${b.primary}/${b.accent}` : ''}`;
    let d = this.defs.get(key);
    if (!d) {
      const parts = unpackParts(packed as Parts | undefined);
      const livery = b && fitted(parts, 'paint') === 0;
      if (livery) {
        const p = parts ?? emptyParts();
        d = { ...applyParts(defOf(model), { ...p, t: { ...p.t, paint: [owned(p, 'paint'), 3] }, c: b.primary, a: b.accent }), livery: b.accent };
      } else d = applyParts(defOf(model), parts);
      this.defs.set(key, d);
    }
    return { def: d, key };
  }

  private body(model: string, packed: unknown, who: Who, was: Body | null): Body {
    const { def, key } = this.defFor(model, packed, who);
    if (was && was.key === key) return was;
    if (was) this.dispose(was);
    const group = new THREE.Group();
    let mesh: VehicleMesh | null = null, cars: RemoteCar[] | null = null;
    if (def.kind === 'rail') {
      // its set's cars, as the dealer sells it (a freight's wagons filled by a seed of its own)
      const set = SETS.find((s) => s.id === def.set);
      if (set) {
        const ids = set.freight ? fillSet(set, mulberry32(hashString(`${who.id}:${model}`))) : set.cars;
        const list: RemoteCar[] = [];
        let off = 0, eng = 0;
        ids.forEach((id, k) => {
          const spec = CARS[id];
          if (!spec) return;
          if (k) off += COUPLING_GAP;
          const m = buildCar(id, k * 7);
          if (!list.length) eng = off + spec.length / 2;
          list.push({ mesh: m, back: off + spec.length / 2 - eng, bogie: m.bogie });
          group.add(m.group);
          off += spec.length;
        });
        // their Passport treats too: the ball and the lantern on the engine, the gold on every car (render/treats.ts)
        dressTrainTreats(list.map((c) => c.mesh), def);
        cars = list;
      }
    } else {
      try { mesh = buildVehicleMesh(def); group.add(mesh.holder); } catch (e) { console.warn('remote: no mesh for', model, e); }
    }
    group.visible = false;
    this.root.add(group);
    let top = 0.6;
    const tallest = mesh?.root ?? cars?.[0]?.mesh.group;
    if (tallest) {
      this.box.setFromObject(tallest);
      if (!this.box.isEmpty()) top = Math.max(0.25, Math.min(4, this.box.max.y - tallest.position.y));
    }
    return { def, key, mesh, group, a: was?.a ?? null, b: was?.b ?? null, line: was?.line ?? newLine(), state: was?.state ?? blankState(), cars, way: [], spin: 0, parked: false, seen: this.clock, top, gx: 0, gy: 0, gz: 0, shown: false };
  }

  private dispose(b: Body): void {
    this.root.remove(b.group);
    if (b.mesh) disposeVehicleMesh(b.mesh);
    for (const c of b.cars ?? []) disposeCar(c.mesh);
  }

  /** The icons of the titles a player wears this week (net/titles.ts, docs/social.html phase 4), after their name on the tag. */
  titleIcons: (pid: Pid) => string = () => '';

  /** A tag drawn: the livery's dot, the name, and the titles worn. */
  private paintTag(p: Player): void {
    const who = p.who;
    const dot = who.brand ? `#${who.brand.primary.toString(16).padStart(6, '0')}` : '#e2412f';
    p.tag.innerHTML = `<i style="background:${dot}"></i>`;
    p.tag.append(who.name);
    const icons = this.titleIcons(who.id);
    if (icons) { const t = document.createElement('span'); t.className = 'tag-titles'; t.textContent = ` ${icons}`; p.tag.append(t); }
  }

  /** The titles have changed: every tag drawn again. */
  retitle(): void { for (const p of this.players.values()) this.paintTag(p); }

  private player(who: Who, cell?: string): Player {
    let p = this.players.get(who.id);
    if (!p) {
      const tag = document.createElement('div');
      tag.className = 'net-tag';
      // right-clicking the name adds them as a friend (net/friends.ts)
      tag.dataset.pid = who.id;
      tag.hidden = true;
      this.tags.append(tag);
      p = { who, look: null, own: null, units: new Map(), tag, cell: cell ?? '' };
      this.players.set(who.id, p);
    }
    const changed = JSON.stringify(p.who.brand) !== JSON.stringify(who.brand);
    p.who = who;
    if (cell) p.cell = cell;
    this.paintTag(p);
    // a new livery: everything of theirs is repainted
    if (changed && p.look) this.setLook(who.id, p.look);
    return p;
  }

  /** Somebody signed in, or changed their fleet's name or colours. */
  join(who: Who, cell: string, look?: Look): void {
    this.player(who, cell);
    if (look) this.setLook(who.id, look);
  }

  leave(id: Pid): void {
    const p = this.players.get(id);
    if (!p) return;
    if (p.own) this.dispose(p.own);
    for (const b of p.units.values()) this.dispose(b);
    p.tag.remove();
    this.players.delete(id);
  }

  clear(): void {
    for (const id of [...this.players.keys()]) this.leave(id);
    this.defs.clear();
  }

  setCell(id: Pid, cell: string): void {
    const p = this.players.get(id);
    if (p) p.cell = cell;
  }

  /** What somebody is driving, and which of their vehicles are out: meshes are built and thrown away to match. */
  setLook(id: Pid, look: Look): void {
    const p = this.players.get(id);
    if (!p) return;
    p.look = look;
    // the Gilded Fleet's gold name (game/treats.ts)
    p.tag.classList.toggle('gilded', !!look.g);
    p.own = this.body(look.m, look.p, p.who, p.own);
    const keep = new Set<number>();
    for (const u of look.units ?? []) {
      if (typeof u?.uid !== 'number' || typeof u.m !== 'string') continue;
      keep.add(u.uid);
      const b = this.body(u.m, u.p, p.who, p.units.get(u.uid) ?? null);
      p.units.set(u.uid, b);
      this.park(b, u);
    }
    for (const [uid, b] of p.units) if (!keep.has(uid)) { this.dispose(b); p.units.delete(uid); }
  }

  private park(b: Body, u: UnitLook): void {
    b.parked = !!u.at;
    if (!u.at) return;
    const [cx, cz, x, z, y, h] = u.at;
    const s: Sample = { t: 0, x: cx * N + x, z: cz * N + z, y, h, v: 0, pitch: 0, roll: 0 };
    b.a = b.b = s;
    b.line = newLine();
  }

  private sample(b: Body, p: number[], at: number): void {
    const L = b.line;
    // on the sender's clock where it carries one; else (a game from before the stamp) when it got here
    const sent = typeof p[9] === 'number' ? p[9] / 1000 : null;
    let t = at;
    if (sent !== null) {
      const o = at - sent;
      // the least delay seen is the line's own; the offset creeps up a little a beat, for clocks that drift
      L.off = L.off === null ? o : Math.min(o, L.off + 0.002);
      L.jit += (o - L.off - L.jit) * 0.1;
      t = sent + L.off;
    }
    const s: Sample = { t, x: p[0] * N + p[2], z: p[1] * N + p[3], y: p[4], h: p[5], v: p[6], pitch: p[7] ?? 0, roll: p[8] ?? 0 };
    const last = L.buf[L.buf.length - 1];
    // a jump (a ferry, a tow, the garage) is a jump: nothing is eased across it
    if (last && Math.hypot(s.x - last.x, s.z - last.z) > 40) { L.buf = []; L.ex = L.ez = 0; L.drawn = false; }
    // late and already passed by a newer one: of no use (the same beat twice, or out of order)
    else if (last && s.t <= last.t) return;
    L.buf.push(s);
    while (L.buf.length > BUF || (L.buf.length > 2 && s.t - L.buf[0].t > BUF_SECS)) L.buf.shift();
    b.a = L.buf[L.buf.length - 2] ?? s;
    b.b = s;
    b.seen = this.clock;
    b.parked = false;
  }

  /** A beat of positions from the server. */
  moves(a: [Pid, ...Pose][], f: [Pid, number, ...Pose][]): void {
    const at = this.clock;
    for (const [id, ...pose] of a) {
      const p = this.players.get(id);
      if (!p) continue;
      p.cell = `${pose[0]},${pose[1]}`;
      if (p.own) this.sample(p.own, pose as number[], at);
    }
    for (const [id, uid, ...pose] of f) {
      const b = this.players.get(id)?.units.get(uid);
      if (b) this.sample(b, pose as number[], at);
    }
  }

  private draw(b: Body, dt: number, worldAt: (cx: number, cz: number) => World | null): void {
    b.shown = false;
    const L = b.line;
    const s1 = b.b;
    if (!s1 || (!b.parked && this.clock - b.seen > STALE)) { b.group.visible = false; L.drawn = false; return; }
    // the delay follows the jitter: up quickly when the line gets rough, back down slowly as it settles
    const want = Math.min(DELAY_MAX, Math.max(DELAY_MIN, 0.08 + 2.5 * L.jit));
    L.delay += (want - L.delay) * Math.min(1, dt * (want > L.delay ? 4 : 0.5));
    const t = this.clock - L.delay;
    let x: number, z: number, y: number, h: number, v: number, pitch: number, roll: number;
    // the two positions either side of the moment drawn
    const buf = L.buf;
    let i = buf.length - 1;
    while (i > 0 && buf[i - 1].t > t) i--;
    const s0 = i > 0 ? buf[i - 1] : null, sb = buf[i] ?? s1;
    if (b.parked || !s0 || t >= s1.t || !buf.length) {
      // past the newest word: carried on along its heading for a moment, then left where it is
      const last = b.parked || !buf.length ? s1 : buf[buf.length - 1];
      const over = b.parked ? 0 : Math.min(COAST, Math.max(0, t - last.t));
      x = last.x + Math.sin(last.h) * last.v * over;
      z = last.z + Math.cos(last.h) * last.v * over;
      y = last.y; h = last.h; pitch = last.pitch; roll = last.roll;
      v = b.parked || t - last.t > COAST ? 0 : last.v;
    } else {
      // along the curve the two positions' speeds and headings describe (a cubic Hermite), not the chord
      const span = Math.max(1e-3, sb.t - s0.t);
      const k = Math.min(1, Math.max(0, (t - s0.t) / span));
      const k2 = k * k, k3 = k2 * k;
      const h00 = 2 * k3 - 3 * k2 + 1, h10 = k3 - 2 * k2 + k, h01 = -2 * k3 + 3 * k2, h11 = k3 - k2;
      // a tangent no longer than the chord, so a position that disagrees with its own speed can't loop
      const chord = Math.hypot(sb.x - s0.x, sb.z - s0.z);
      const tan = (q: Sample) => { const len = Math.min(Math.abs(q.v) * span, chord * 1.5) * Math.sign(q.v || 1); return [Math.sin(q.h) * len, Math.cos(q.h) * len]; };
      const [m0x, m0z] = tan(s0), [m1x, m1z] = tan(sb);
      x = h00 * s0.x + h10 * m0x + h01 * sb.x + h11 * m1x;
      z = h00 * s0.z + h10 * m0z + h01 * sb.z + h11 * m1z;
      y = s0.y + (sb.y - s0.y) * k;
      h = lerpAngle(s0.h, sb.h, k); pitch = s0.pitch + (sb.pitch - s0.pitch) * k; roll = s0.roll + (sb.roll - s0.roll) * k;
      v = s0.v + (sb.v - s0.v) * k;
    }
    // a correction (the truth arrived somewhere the guess wasn't): eased out, not snapped
    if (L.drawn) {
      const moved = Math.hypot(x - L.lx, z - L.lz), fair = Math.abs(v) * dt * 1.6 + 0.04;
      if (moved > fair && moved < ERR_SNAP) {
        const keep = 1 - fair / moved;
        L.ex += (L.lx - x) * keep; L.ez += (L.lz - z) * keep;
      } else if (moved >= ERR_SNAP) { L.ex = 0; L.ez = 0; }
    }
    const ease = Math.exp(-dt / ERR_EASE);
    L.ex *= ease; L.ez *= ease;
    x += L.ex; z += L.ez;
    L.lx = x; L.lz = z; L.drawn = true;
    // an aircraft is drawn over a county not in memory yet too (posing it reads no ground): one followed across the
    // country stays in view while the counties it flies into are built (the user, 28 Oct 2026)
    const cx = Math.floor(x / N), cz = Math.floor(z / N);
    const w = worldAt(cx, cz) ?? (b.def.kind === 'air' ? ({ ox: cx * N, oz: cz * N } as World) : null);
    if (!w) { b.group.visible = false; return; }
    b.gx = x; b.gy = y; b.gz = z; b.shown = true;
    // its heading and speed whether or not there is a model to pose: the camera following it turns with them
    const st = b.state;
    st.x = x - w.ox; st.z = z - w.oz; st.y = y; st.heading = h; st.v = v; st.pitch = pitch; st.roll = roll;
    if (b.cars) { this.poseTrain(b, x, y, z, h, v, dt); return; }
    if (!b.mesh) { b.group.visible = false; return; }
    st.wheelSpin += v * dt * 4;
    st.power = b.def.kind === 'air' ? (y > 1.5 || Math.abs(v) > 0.2 ? 1 : 0.15) : Math.min(1, Math.abs(v) / Math.max(1, b.def.topSpeed));
    // a trailer swings round behind its cab
    st.trailerHeading = lerpAngle(st.trailerHeading, h, Math.min(1, dt * (1.5 + Math.abs(v))));
    b.group.position.set(w.ox, 0, w.oz);
    b.group.visible = true;
    poseVehicleMesh(b.mesh, st, b.def, w);
    for (const sp of b.mesh.spinners) sp.obj.rotation[sp.axis] += sp.speed * st.power * dt;
  }

  /** A train: the engine where it was heard, every car behind it on the line it has come along. */
  private poseTrain(b: Body, x: number, y: number, z: number, h: number, v: number, dt: number): void {
    const cars = b.cars!, way = b.way;
    const last = cars[cars.length - 1];
    const len = last ? last.back + last.bogie + 1 : 2;
    const head = way[0];
    const gone = head ? Math.hypot(x - head.x, z - head.z) : Infinity;
    if (gone > 6) {
      // first seen, or jumped (a tow, the garage): the line behind it laid from the track, else straight back
      way.length = 0;
      way.push(...(this.railBehind?.(x, z, h, len + CRUMB_SPARE, !!(b.def as { rack?: boolean }).rack) ?? [{ x, y, z }]));
    } else {
      const fwd = Math.sin(h) * (x - head.x) + Math.cos(h) * (z - head.z);
      if (fwd > 0 && gone >= CRUMB) way.unshift({ x, y, z });
      // backing up: the points it has backed over are behind it no longer
      else if (fwd < 0) while (way.length > 1 && Math.hypot(x - way[1].x, z - way[1].z) <= Math.hypot(way[0].x - way[1].x, way[0].z - way[1].z)) way.shift();
    }
    // no more of the way than the train needs
    let run = Math.hypot(x - way[0].x, z - way[0].z), k = 1;
    for (; k < way.length && run < len + CRUMB_SPARE; k++) run += Math.hypot(way[k].x - way[k - 1].x, way[k].z - way[k - 1].z);
    way.length = Math.min(way.length, k + 1);
    b.spin += v * dt / 0.05;
    const f: Pt3 = { x: 0, y: 0, z: 0 }, r: Pt3 = { x: 0, y: 0, z: 0 };
    for (const c of cars) {
      this.along(x, y, z, h, way, c.back - c.bogie, f);
      this.along(x, y, z, h, way, c.back + c.bogie, r);
      const g = c.mesh.group;
      g.position.set((f.x + r.x) / 2, (f.y + r.y) / 2, (f.z + r.z) / 2);
      const dx = f.x - r.x, dz = f.z - r.z;
      g.rotation.set(-Math.atan2(f.y - r.y, Math.hypot(dx, dz) || 1), Math.hypot(dx, dz) < 1e-3 ? h : Math.atan2(dx, dz), 0, 'YXZ');
      for (const wh of c.mesh.wheels) wh.rotation.x = b.spin;
    }
    b.group.position.set(0, 0, 0);
    b.group.visible = true;
  }

  /** The point `d` tiles behind the engine at (x, y, z) facing h, along its way (ahead of it for d < 0; straight on past the way's end). */
  private along(x: number, y: number, z: number, h: number, way: Pt3[], d: number, out: Pt3): void {
    if (d <= 0) { out.x = x - Math.sin(h) * d; out.y = y; out.z = z - Math.cos(h) * d; return; }
    let px = x, py = y, pz = z, dx = -Math.sin(h), dz = -Math.cos(h);
    for (const q of way) {
      const seg = Math.hypot(q.x - px, q.z - pz);
      if (seg < 1e-4) continue;
      dx = (q.x - px) / seg; dz = (q.z - pz) / seg;
      if (d <= seg) { const k = d / seg; out.x = px + (q.x - px) * k; out.y = py + (q.y - py) * k; out.z = pz + (q.z - pz) * k; return; }
      d -= seg; px = q.x; py = q.y; pz = q.z;
    }
    out.x = px + dx * d; out.y = py; out.z = pz + dz * d;
  }

  /** Every frame: ease everyone to where they were a moment ago, and put the names over them. */
  update(dt: number, camera: THREE.Camera, focus: { x: number; z: number }, worldAt: (cx: number, cz: number) => World | null, showTags: boolean): void {
    this.clock += dt;
    const wW = window.innerWidth, wH = window.innerHeight;
    for (const p of this.players.values()) {
      if (p.own) this.draw(p.own, dt, worldAt);
      for (const b of p.units.values()) this.draw(b, dt, worldAt);
      const o = p.own;
      let shown = false;
      if (showTags && o?.shown && Math.hypot(o.gx - focus.x, o.gz - focus.z) < TAG_FAR) {
        this.v.set(o.gx, o.gy + o.top + 0.55, o.gz).project(camera);
        if (this.v.z < 1 && Math.abs(this.v.x) < 1.1 && Math.abs(this.v.y) < 1.1) {
          p.tag.style.transform = `translate(-50%, -100%) translate(${((this.v.x + 1) / 2 * wW).toFixed(1)}px, ${((1 - this.v.y) / 2 * wH).toFixed(1)}px)`;
          shown = true;
        }
      }
      if (p.tag.hidden === shown) p.tag.hidden = !shown;
    }
  }

  /** The Passport's treats another player shows (game/treats.ts), from their look: none when they aren't about. */
  treatsOf(id: Pid): TreatLook { return treatsOfLook(this.players.get(id)?.look); }

  /** Where every drawn vehicle is, for the fleets' badges over them. */
  badges(): { look: BadgeLook; x: number; y: number; z: number; seed: number }[] {
    const out: { look: BadgeLook; x: number; y: number; z: number; seed: number }[] = [];
    let n = 0;
    for (const p of this.players.values()) {
      const b = p.who.brand;
      if (!b) continue;
      const tr = treatsOfLook(p.look);
      const look: BadgeLook = { logo: b.logo, primary: b.primary, accent: b.accent, ...(tr.emblem ? { frame: tr.emblem } : {}), ...(tr.pass ? { pass: true } : {}) };
      for (const body of [p.own, ...p.units.values()]) {
        n++;
        if (body?.shown && body.mesh) out.push({ look, x: body.gx, y: body.gy + body.top + 0.18, z: body.gz, seed: 900000 + n });
      }
    }
    return out;
  }

  /**
   * Every vehicle of the other fleets whose whereabouts are known (the one each player drives and their hired
   * drivers' units), with its fleet's primary colour, for the region map's Fleet view (game/regionView.ts).
   */
  vehiclesForMap(): { key: string; x: number; z: number; name: string; model: string; heading: number; colour: number }[] {
    const out: { key: string; x: number; z: number; name: string; model: string; heading: number; colour: number }[] = [];
    for (const p of this.players.values()) {
      const colour = p.who.brand?.primary ?? 0x7d8a92;
      const fleet = p.who.brand?.name ?? p.who.name;
      for (const s of this.fleetOf(p.who.id) ?? []) {
        if (!s.known) continue;
        out.push({ key: `r${p.who.id}:${s.uid ?? 'own'}`, x: s.x, z: s.z, name: s.uid === null ? `${p.who.name} · ${fleet}` : fleet, model: s.def.id, heading: s.heading, colour });
      }
    }
    return out;
  }

  /** Everyone whose whereabouts are known, in world tiles, for the maps. */
  dots(): { x: number; z: number; name: string }[] {
    const out: { x: number; z: number; name: string }[] = [];
    for (const p of this.players.values()) {
      if (p.own?.b) out.push({ x: p.own.b.x, z: p.own.b.z, name: p.who.name });
      else if (p.cell) { const [cx, cz] = p.cell.split(',').map(Number); out.push({ x: (cx + 0.5) * N, z: (cz + 0.5) * N, name: p.who.name }); }
    }
    return out;
  }
}
