import { hex, scale, type RGB } from '../../world/biomes';
import type { BusinessKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import {
  BRICK, BRIGHT, CARS, COOL_GLOW, DARK, GLASS, GLASS_LIGHT, LEAF, METAL, RED_LIGHT, ROOF_GREY, SHOP_GLOW, STONE, WARM_GLOW, WATER, WHITE, WOOD, car, cur, pick, portico, row, styleGlass, styleRoof, styleTrim, styleWall, topOff,
  tower, tree, win, styledGable, type Draw, type Kit } from './kit';
import { chainFence, clock, flag } from './civic';

/** Places of business: each says what it sells from the roof and the sign. */

const GOLD = hex(0xd9a441), NEON = [0xff4fa0, 0x4fe0ff, 0xffe14f, 0x8cff4f, 0xb06bff];
const LORRY = [0xf4f2ec, 0xe2412f, 0x2f7fb5, 0x3a3f45];

/** A lorry facing +z (or along x), cab at the front. */
export function lorry(k: Kit, x: number, z: number, alongX: boolean, col: RGB): void {
  const [w, d] = alongX ? [0.62, 0.2] : [0.2, 0.62];
  const f = alongX ? 1 : 0;
  k.box(x - (alongX ? 0.08 : 0), 0.04, z - (alongX ? 0 : 0.08), alongX ? 0.46 : w, 0.24, alongX ? d : 0.46, col);
  const cx = x + (alongX ? 0.22 : 0), cz = z + (alongX ? 0 : 0.22);
  k.box(cx, 0.03, cz, alongX ? 0.14 : w, 0.18, alongX ? d : 0.14, pick(() => Math.abs(Math.sin(x * 13 + z * 7)), [0xe2412f, 0x2f7fb5, 0x3f9b4a]));
  k.box(cx + f * 0.071, 0.12, cz + (1 - f) * 0.071, alongX ? 0.004 : w * 0.8, 0.06, alongX ? d * 0.8 : 0.004, GLASS);
}

/** A sign on a pole, lit all evening. */
function poleSign(k: Kit, x: number, z: number, h: number, w: number, col: RGB, s: [number, number, number] = [16.5, 30, 1.8]): void {
  k.cyl(x, 0, z, 0.025, h, METAL, 5);
  k.glowBox(x, h, z, w, w * 0.6, 0.05, col, s, col);
}

// ---- 41. hotel ---------------------------------------------------------------------------------

const hotel: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), glass = styleGlass(r), sign = pick(r, [0xe2412f, 0xd9a441, 0x2f7fb5]);
  const bw = W - 0.2, bd = D - 0.5, bz = -0.12;
  // a wide two-storey base
  const base = tower(k, b, r, 0, 0, bz, bw, bd, 2, scale(wall, 0.92), glass, 0.14);
  const top = tower(k, b, r, 0, base, bz - 0.05, bw - 0.35, bd - 0.35, Math.max(3, b.floors - 2), wall, glass, 0.1);
  topOff(k, r, 0, top, bz - 0.05, bw - 0.35, bd - 0.35, wall);
  // the rooftop bar that glows late
  k.glowBox(0, top, bz - 0.05, bw * 0.4, 0.14, bd * 0.3, GLASS_LIGHT, [19, 26, 2], WARM_GLOW);
  // entrance canopy on posts, and a revolving door
  const fz = bz + bd / 2;
  k.box(0, 0.3, fz + 0.2, 0.7, 0.04, 0.4, sign);
  for (const sx of [-1, 1]) k.box(sx * 0.32, 0, fz + 0.38, 0.03, 0.3, 0.03, GOLD);
  k.cyl(0, 0, fz + 0.03, 0.08, 0.2, GLASS_LIGHT, 8);
  k.glowBox(0, 0.3, fz + 0.2, 0.6, 0.01, 0.34, WHITE, [16.5, 30, 1.6], WARM_GLOW);
  // the vertical sign down one corner
  k.glowBox(bw / 2 + 0.03, base + 0.1, fz - 0.05, 0.05, Math.min(1.4, (b.floors - 3) * FLOOR), 0.14, sign, [16.5, 30, 2.2], sign);
};

// ---- 42. motel ---------------------------------------------------------------------------------

const motel: Draw = (k, W, D, b, r) => {
  const wall = pick(r, [0xf4e3c4, 0xe8d3b0, 0xcfe0e8, 0xf6e7a8]), roof = pick(r, [0x2bb3a3, 0xe2412f, 0x5a5f6b]);
  // the long wing of rooms across the back, with the office at one end
  const rz = -D / 2 + 0.35, rw = W - 1.2;
  k.box(-0.3, 0, rz, rw, 0.3, 0.5, wall, roof);
  k.box(-0.3, 0.3, rz + 0.1, rw + 0.06, 0.03, 0.74, roof);
  for (let i = 0; i < 7; i++) {
    const x = -0.3 - rw / 2 + 0.2 + (i * (rw - 0.4)) / 6;
    k.box(x, 0, rz + 0.255, 0.08, 0.18, 0.01, pick(r, [0x2f7fb5, 0xe2412f, 0x3f9b4a]));
    win(k, b, r, x + 0.12, 0.1, rz + 0.25, 0.08, 0.08, 1);
    if (i % 2 === 0) k.glowBox(x + 0.06, 0.2, rz + 0.27, 0.02, 0.03, 0.02, WHITE, [17.5, 30, 2], WARM_GLOW);
  }
  for (let i = 0; i <= 6; i++) k.box(-0.3 - rw / 2 + (i * rw) / 6, 0, rz + 0.45, 0.02, 0.3, 0.02, WHITE);
  const ox = W / 2 - 0.4;
  k.box(ox, 0, rz + 0.05, 0.5, 0.34, 0.6, wall, roof);
  win(k, b, r, ox, 0.08, rz + 0.35, 0.3, 0.16, 1, GLASS_LIGHT);
  // the pool and loungers
  k.box(-0.4, 0, D / 2 - 0.25, 0.8, 0.02, 0.28, WHITE);
  k.box(-0.4, 0.012, D / 2 - 0.25, 0.7, 0.012, 0.2, WATER);
  for (const sx of [0.2, 0.36]) k.box(sx, 0.02, D / 2 - 0.25, 0.08, 0.02, 0.2, WHITE);
  // the tall pole sign with VACANCY lit
  k.cyl(W / 2 - 0.12, 0, D / 2 - 0.12, 0.025, 1.0, METAL, 5);
  k.glowBox(W / 2 - 0.12, 1.0, D / 2 - 0.12, 0.34, 0.22, 0.05, roof, [16.5, 30, 2.2], hex(0xff6f5a));
  k.glowBox(W / 2 - 0.12, 0.84, D / 2 - 0.12, 0.26, 0.08, 0.05, DARK, [17, 30, 2.4], hex(0x6fff9a));
};

// ---- 43. bank ----------------------------------------------------------------------------------

const bank: Draw = (k, W, D, b, r) => {
  const stone = pick(r, STONE), bw = W - 0.2, bd = D - 0.35, bz = -0.08, h = b.floors * FLOOR + 0.12;
  k.box(0, 0, bz, bw, h, bd, stone, ROOF_GREY);
  k.box(0, h, bz, bw + 0.08, 0.08, bd + 0.08, scale(stone, 0.9));
  const fz = bz + bd / 2;
  for (let i = 0; i < 4; i++) k.cyl(-bw * 0.3 + (i * bw * 0.6) / 3, 0.04, fz + 0.06, 0.04, h - 0.08, WHITE, 6);
  k.box(0, 0, fz + 0.06, bw * 0.75, 0.04, 0.16, stone);
  k.box(0, h - 0.1, fz + 0.06, bw * 0.75, 0.06, 0.14, stone);
  k.box(0, 0.04, fz + 0.01, 0.14, 0.26, 0.02, GOLD);
  for (const sx of [-1, 1]) win(k, b, r, sx * bw * 0.4, 0.3, fz, 0.1, 0.18, 1);
  // the ATM, lit all night
  k.glowBox(bw * 0.4, 0.08, fz + 0.01, 0.08, 0.1, 0.02, hex(0x9fd8ff), [0, 30, 1.8], hex(0x9fd8ff));
  // the vault door on the side
  k.box(bw / 2 + 0.01, 0.06, bz, 0.02, 0.24, 0.24, METAL);
  k.box(bw / 2 + 0.025, 0.16, bz, 0.02, 0.04, 0.12, GOLD);
};

// ---- 44. car dealership ------------------------------------------------------------------------

const carDealership: Draw = (k, W, D, b, r) => {
  const brand = pick(r, BRIGHT);
  const sz = -D / 2 + 0.45;
  k.box(0, 0, sz, W - 0.3, 0.46, 0.7, GLASS_LIGHT, ROOF_GREY);
  k.box(0, 0.46, sz, W - 0.26, 0.06, 0.74, WHITE);
  k.box(0, 0.4, sz + 0.36, W - 0.3, 0.06, 0.02, brand);
  k.glowBox(0, 0.02, sz, W - 0.4, 0.4, 0.6, GLASS_LIGHT, [16.5, 22.5, 1.2], SHOP_GLOW);
  for (let i = 0; i < 4; i++) car(k, -W / 2 + 0.4 + (i * (W - 0.8)) / 3, sz, false, pick(r, CARS));
  // the forecourt: eight cars under bunting
  for (let row = 0; row < 2; row++) for (let i = 0; i < 4; i++) car(k, -W / 2 + 0.35 + (i * (W - 0.7)) / 3, 0.35 + row * 0.42, false, pick(r, CARS));
  const flags = 9;
  for (let i = 0; i < flags; i++) {
    const x = -W / 2 + 0.15 + (i * (W - 0.3)) / (flags - 1);
    k.box(x, 0.3, D / 2 - 0.1, 0.04, 0.06, 0.004, pick(r, BRIGHT));
  }
  k.bar([-W / 2 + 0.15, 0.36, D / 2 - 0.1], [W / 2 - 0.15, 0.36, D / 2 - 0.1], 0.004, METAL);
  // the brand totem
  k.box(W / 2 - 0.15, 0, -0.1, 0.12, 0.9, 0.06, WHITE);
  k.glowBox(W / 2 - 0.15, 0.6, -0.07, 0.1, 0.24, 0.02, brand, [16.5, 23, 2], brand);
};

// ---- 45. big box -------------------------------------------------------------------------------

const bigBox: Draw = (k, W, D, _b, r) => {
  const body = pick(r, [0xe3e8ec, 0xefe6d6, 0xd8dcd6]), brand = pick(r, BRIGHT);
  const sd = D - 1.4, sz = -D / 2 + 0.1 + sd / 2, fz = sz + sd / 2;
  k.box(0, 0, sz, W - 0.2, 0.6, sd, body, ROOF_GREY);
  k.box(0, 0.44, fz + 0.01, W - 0.2, 0.16, 0.02, brand);
  k.glowBox(0, 0.46, fz + 0.03, W * 0.35, 0.12, 0.02, WHITE, [16.5, 22.5, 2], brand);
  k.glowBox(0, 0, fz + 0.01, 0.6, 0.26, 0.02, GLASS_LIGHT, [16.5, 22.5, 1.4], SHOP_GLOW);
  for (let i = 0; i < 4; i++) k.box(W / 2 - 0.6 - i * 0.6, 0.12, sz - sd / 2 + 0.3 + i * 0.2, 0.3, 0.1, 0.3, hex(0x9aa0a6));
  // two rows of parking
  for (const pz of [fz + 0.35, fz + 0.95]) {
    const n = Math.floor((W - 0.4) / 0.3);
    for (let i = 0; i < n; i++) {
      const x = -((n - 1) * 0.3) / 2 + i * 0.3;
      k.box(x - 0.15, 0.004, pz, 0.02, 0.008, 0.4, WHITE);
      if (r() < 0.55) car(k, x, pz, false, pick(r, CARS));
    }
  }
  // trolley bays
  for (const sx of [-1, 1]) {
    k.box(sx * W * 0.3, 0.26, fz + 0.65, 0.3, 0.02, 0.12, brand);
    for (const ox of [-0.13, 0.13]) k.box(sx * W * 0.3 + ox, 0, fz + 0.65, 0.02, 0.26, 0.02, METAL);
  }
};

// ---- 46. strip mall ----------------------------------------------------------------------------

const stripMall: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), sd = 0.62, sz = -D / 2 + 0.1 + sd / 2, fz = sz + sd / 2;
  k.box(0, 0, sz, W - 0.2, 0.42, sd, wall, ROOF_GREY);
  k.box(0, 0.42, sz + 0.1, W - 0.16, 0.05, sd + 0.3, styleTrim());
  const n = 5, cell = (W - 0.3) / n;
  for (let i = 0; i < n; i++) {
    const x = -((W - 0.3) / 2) + cell * (i + 0.5), sign = pick(r, BRIGHT);
    win(k, b, r, x, 0.04, fz, cell * 0.7, 0.24, 1, GLASS_LIGHT);
    k.glowBox(x, 0.32, fz + 0.01, cell * 0.8, 0.08, 0.02, sign, [16.5, 22, 1.8], sign);
    k.box(x - cell / 2, 0, fz + 0.26, 0.025, 0.42, 0.025, WHITE);
  }
  for (let i = 0; i < 8; i++) {
    const x = -W / 2 + 0.3 + (i * (W - 0.6)) / 7;
    if (r() < 0.5) car(k, x, D / 2 - 0.2, false, pick(r, CARS));
  }
};

// ---- 47. cafe ----------------------------------------------------------------------------------

const cafe: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), awning = pick(r, BRIGHT);
  const h = b.floors * FLOOR + 0.06;
  k.box(0, 0, -0.18, 0.86, h, 0.56, wall, ROOF_GREY);
  win(k, b, r, 0, 0.03, 0.1, 0.66, 0.2, 1, GLASS_LIGHT);
  for (let f = 1; f < b.floors; f++) row(k, { ...b, kind: 'townhouse' }, r, 0, 0.08 + f * FLOOR, 0.1, 0.5, 0.13, 2, 1);
  for (let i = 0; i < 4; i++) k.box(-0.33 + i * 0.22, 0.24, 0.18, 0.22, 0.02, 0.18, i % 2 ? WHITE : awning);
  // three parasols and their tables
  for (let i = 0; i < 3; i++) {
    const x = -0.28 + i * 0.28;
    k.cyl(x, 0, 0.36, 0.008, 0.26, METAL, 4);
    k.cone(x, 0.22, 0.36, 0.11, 0.06, i % 2 ? awning : WHITE, 8);
    k.cyl(x, 0.08, 0.36, 0.04, 0.01, WHITE, 6);
    for (const sx of [-1, 1]) k.box(x + sx * 0.06, 0, 0.36, 0.03, 0.05, 0.03, DARK);
  }
  // the chalkboard
  k.bar([0.4, 0, 0.26], [0.4, 0.1, 0.24], 0.018, DARK);
};

// ---- 48. bakery --------------------------------------------------------------------------------

const bakery: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), awning = pick(r, [0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf28c38]);
  const h = b.floors * FLOOR + 0.06;
  k.box(0, 0, -0.06, 0.86, h, 0.76, wall, ROOF_GREY);
  if (cur.pitch > 0.3 || cur.form) styledGable(k, r, 0, h, -0.06, 0.9, cur.pitch * 0.5, 0.8, styleRoof(r), wall);
  win(k, b, r, 0, 0.04, 0.32, 0.6, 0.18, 1, GLASS_LIGHT);
  for (let i = 0; i < 5; i++) k.box(-0.32 + i * 0.16, 0.24, 0.4, 0.16, 0.02, 0.16, i % 2 ? WHITE : awning);
  for (let f = 1; f < b.floors; f++) row(k, { ...b, kind: 'townhouse' }, r, 0, 0.08 + f * FLOOR, 0.32, 0.5, 0.13, 2, 1);
  // the chimney at the back, and the smoke of the early bake
  k.box(0.28, h, -0.34, 0.12, 0.3, 0.12, pick(r, BRICK));
  for (let i = 0; i < 3; i++) k.glowBox(0.28 + i * 0.03, h + 0.36 + i * 0.1, -0.34, 0.1 - i * 0.02, 0.06, 0.1 - i * 0.02, hex(0xe8e8e4), [28.5, 31, 0.6], hex(0xffe8c8));
  k.glowBox(0, 0.05, 0.33, 0.56, 0.14, 0.01, GLASS_LIGHT, [28, 38, 1.6], WARM_GLOW);
};

// ---- 49. office park ---------------------------------------------------------------------------

const officePark: Draw = (k, W, D, b, r) => {
  const glass = styleGlass(r), frame = styleWall(r);
  // two three-storey boxes at right angles
  tower(k, { ...b, kind: 'office' }, r, -W / 2 + 0.75, 0, -D / 2 + 0.5, 1.3, 0.8, 3, frame, glass, 0.18);
  k.box(-W / 2 + 0.75, 3 * FLOOR, -D / 2 + 0.5, 1.34, 0.05, 0.84, frame);
  tower(k, { ...b, kind: 'office' }, r, W / 2 - 0.45, 0, -0.1, 0.7, 1.4, 3, frame, glass, 0.18);
  k.box(W / 2 - 0.45, 3 * FLOOR, -0.1, 0.74, 0.05, 1.44, frame);
  // car park, lawn strip and four trees
  for (let i = 0; i < 5; i++) {
    const x = -W / 2 + 0.3 + i * 0.3;
    k.box(x - 0.15, 0.004, D / 2 - 0.35, 0.02, 0.008, 0.4, WHITE);
    if (r() < 0.6) car(k, x, D / 2 - 0.35, false, pick(r, CARS));
  }
  for (let i = 0; i < 4; i++) tree(k, -W / 2 + 0.25 + i * 0.4, 0, 0.0, 0.7, false);
};

// ---- 50. tech campus ---------------------------------------------------------------------------

const techCampus: Draw = (k, W, D, b, r, t) => {
  const roofCol = t?.accent !== undefined ? hex(t.accent) : hex(0x2f4d7a);
  const pw = W * 0.34, pd = D * 0.3;
  const spots: [number, number][] = [[-W / 4, -D / 4], [W / 4, -D / 4], [-W / 4, D / 4], [W / 4, D / 4]];
  for (const [x, z] of spots) {
    k.box(x, 0, z, pw, 0.42, pd, GLASS_LIGHT);
    k.glowBox(x, 0.03, z, pw - 0.06, 0.36, pd - 0.06, GLASS_LIGHT, [16.5, 24, 1.3], COOL_GLOW);
    k.box(x, 0.42, z, pw + 0.12, 0.04, pd + 0.12, WHITE);
    // solar panels on the roof
    for (let i = 0; i < 3; i++) k.box(x - pw / 3 + (i * pw) / 3, 0.46, z, pw * 0.28, 0.02, pd * 0.7, roofCol);
  }
  // the courtyard pond and the walkway
  k.cyl(0, 0.004, 0, 0.5, 0.02, WATER, 12, WATER, 0.35);
  k.box(0, 0.26, 0, W * 0.5, 0.03, 0.16, WHITE);
  for (const sx of [-1, 1]) k.box(sx * W * 0.12, 0, 0, 0.03, 0.26, 0.03, METAL);
  // bicycle shed
  k.box(0, 0.22, D / 2 - 0.2, 0.7, 0.02, 0.2, ROOF_GREY);
  for (const sx of [-1, 1]) k.box(sx * 0.33, 0, D / 2 - 0.2, 0.02, 0.22, 0.02, METAL);
  void b;
};

// ---- 51. factory -------------------------------------------------------------------------------

const factory: Draw = (k, W, D, b, r) => {
  const brick = pick(r, BRICK), roof = hex(0x5a5f6b);
  const hw = W - 0.8, hd = D - 1.1, hz = -D / 2 + 0.1 + hd / 2, h = 0.55;
  k.box(-0.3, 0, hz, hw, h, hd, brick);
  // sawtooth roof: four gables, each with one steep glazed face
  for (let i = 0; i < 4; i++) {
    const z = hz - hd / 2 + (hd / 4) * (i + 0.5);
    k.quad([-0.3 - hw / 2, h, z - hd / 8], [-0.3 + hw / 2, h, z - hd / 8], [-0.3 + hw / 2, h + 0.26, z + hd / 8], [-0.3 - hw / 2, h + 0.26, z + hd / 8], roof, [-0.3, h - 0.5, z]);
    k.quad([-0.3 - hw / 2, h, z + hd / 8], [-0.3 + hw / 2, h, z + hd / 8], [-0.3 + hw / 2, h + 0.26, z + hd / 8], [-0.3 - hw / 2, h + 0.26, z + hd / 8], GLASS_LIGHT, [-0.3, h, z - 0.5]);
    k.tri([-0.3 - hw / 2, h, z - hd / 8], [-0.3 - hw / 2, h, z + hd / 8], [-0.3 - hw / 2, h + 0.26, z + hd / 8], brick, [0, h, z]);
    k.tri([-0.3 + hw / 2, h, z - hd / 8], [-0.3 + hw / 2, h, z + hd / 8], [-0.3 + hw / 2, h + 0.26, z + hd / 8], brick, [-0.6, h, z]);
  }
  row(k, b, r, -0.3, 0.14, hz + hd / 2, hw - 0.2, 0.22, 6, 1);
  // chimney with a beacon
  const cx = W / 2 - 0.3, cz = -D / 2 + 0.35;
  k.cyl(cx, 0, cz, 0.1, 1.9, brick, 8);
  k.glowBox(cx, 1.9, cz, 0.06, 0.05, 0.06, hex(0x882222), [16.5, 30, 3], RED_LIGHT);
  // water tank on stilts
  const tx = W / 2 - 0.3, tz = 0.2;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(tx + sx * 0.1, 0, tz + sz * 0.1, 0.025, 0.6, 0.025, METAL);
  k.cyl(tx, 0.6, tz, 0.16, 0.22, WOOD, 8);
  k.cone(tx, 0.82, tz, 0.17, 0.08, DARK, 8);
  // the yard with two lorries
  lorry(k, -0.8, D / 2 - 0.35, true, pick(r, LORRY));
  lorry(k, 0.3, D / 2 - 0.35, true, pick(r, LORRY));
};

// ---- 52. brewery -------------------------------------------------------------------------------

const brewery: Draw = (k, W, D, b, r) => {
  const brick = pick(r, BRICK), copper = hex(0xc07a45);
  const bz = -0.3, bd = D - 0.9;
  k.box(0, 0, bz, W - 0.3, 0.7, bd, brick);
  k.gable(0, 0.7, bz, W - 0.24, 0.3, bd + 0.06, styleRoof(r), brick);
  // the arched window showing the copper kettles
  const fz = bz + bd / 2;
  k.box(0, 0.08, fz + 0.005, 0.8, 0.4, 0.01, GLASS_LIGHT);
  k.dome(0, 0.48, fz + 0.005, 0.4, GLASS_LIGHT, 10, 2);
  for (const sx of [-0.2, 0.2]) {
    k.cyl(sx, 0.08, fz - 0.12, 0.13, 0.26, copper, 10);
    k.dome(sx, 0.34, fz - 0.12, 0.13, copper, 10, 3);
  }
  k.glowBox(0, 0.1, fz + 0.014, 0.76, 0.36, 0.004, GLASS_LIGHT, [16.5, 23, 1.4], WARM_GLOW);
  for (const sx of [-1, 1]) win(k, b, r, sx * (W / 2 - 0.4), 0.3, fz, 0.16, 0.24, 1);
  k.cyl(-W / 2 + 0.3, 0.7, bz - bd / 2 + 0.2, 0.08, 0.6, brick, 8);
  // kegs on the yard
  for (let i = 0; i < 5; i++) k.cyl(-0.5 + (i < 3 ? i * 0.14 : 0.07 + (i - 3) * 0.14), i < 3 ? 0 : 0.12, D / 2 - 0.3, 0.06, 0.12, METAL, 8);
};

// ---- 53. logistics depot -----------------------------------------------------------------------

const logisticsDepot: Draw = (k, W, D, _b, r, t) => {
  const body = pick(r, [0xe3e8ec, 0xd8dcd6, 0xcfd6d4]), brand = t?.accent !== undefined ? hex(t.accent) : pick(r, BRIGHT);
  const sd = D - 1.4, sz = -D / 2 + 0.1 + sd / 2, fz = sz + sd / 2;
  k.box(0, 0, sz, W - 0.3, 0.62, sd, body, ROOF_GREY);
  k.box(0, 0.62, sz, W - 0.26, 0.04, sd + 0.04, brand);
  // eight dock doors, three lorries backed onto them
  for (let i = 0; i < 8; i++) {
    const x = -W / 2 + 0.45 + (i * (W - 0.9)) / 7;
    k.box(x, 0, fz + 0.01, 0.3, 0.36, 0.02, hex(0x6d7176));
    k.box(x, 0.4, fz + 0.03, 0.3, 0.04, 0.06, brand);
    if (i % 3 === 1) lorry(k, x, fz + 0.4, false, pick(r, LORRY));
    k.glowBox(x, 0.46, fz + 0.03, 0.05, 0.03, 0.03, WHITE, [16.5, 30, 1.8], COOL_GLOW);
  }
  // gatehouse and barrier
  k.box(W / 2 - 0.3, 0, D / 2 - 0.3, 0.3, 0.26, 0.3, WHITE, ROOF_GREY);
  k.box(W / 2 - 0.6, 0.14, D / 2 - 0.3, 0.5, 0.02, 0.02, hex(0xe2412f));
};

// ---- 54. pub -----------------------------------------------------------------------------------

const pub: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), paint = pick(r, [0x2f4d3a, 0x6b2a2a, 0x2a3a5a, 0x3a3f45]);
  const h = b.floors * FLOOR + 0.04;
  k.box(0, 0, -0.1, 0.8, h, 0.62, wall);
  styledGable(k, r, 0, h, -0.1, 0.86, cur.pitch * 0.7 + 0.1, 0.68, roof, wall);
  // painted ground floor and bay window
  k.box(0, 0, 0.215, 0.82, 0.26, 0.02, paint);
  k.box(-0.18, 0.04, 0.26, 0.3, 0.18, 0.08, paint);
  k.pane(-0.18, 0.07, 0.3, 0.24, 0.13, 1, GLASS_LIGHT, [15.5, 23.5, 1.8], WARM_GLOW);
  k.box(0.2, 0, 0.23, 0.12, 0.2, 0.02, DARK);
  row(k, { ...b, kind: 'townhouse' }, r, 0, 0.34, 0.21, 0.6, 0.12, 3, 1);
  // the hanging sign on its bracket
  k.box(0.35, 0.44, 0.3, 0.02, 0.02, 0.16, DARK);
  k.box(0.35, 0.3, 0.37, 0.02, 0.14, 0.12, pick(r, BRIGHT));
  // barrels and a bench outside
  for (const sx of [-0.38, 0.4]) k.cyl(sx, 0, 0.36, 0.045, 0.1, WOOD, 7);
  k.box(-0.05, 0.04, 0.4, 0.22, 0.02, 0.06, WOOD);
};

// ---- 55. fast food -----------------------------------------------------------------------------

const fastFood: Draw = (k, _W, _D, b, r) => {
  const brand = pick(r, [0xe2412f, 0xf2c14e, 0x2f7fb5, 0xef6c1a]);
  k.box(-0.1, 0, -0.1, 0.56, 0.3, 0.5, hex(0xefe6d6), ROOF_GREY);
  k.wedge(-0.1, 0.24, 0.17, 0.6, 0.1, 0.06, brand);
  k.box(-0.1, 0.3, -0.1, 0.6, 0.06, 0.54, brand);
  win(k, b, r, -0.1, 0.05, 0.15, 0.4, 0.14, 1, GLASS_LIGHT);
  // the drive-through lane round the side with its menu board and window
  k.box(0.33, 0.004, 0, 0.16, 0.008, 0.8, hex(0xdad5cb));
  k.glowBox(0.19, 0.08, -0.1, 0.01, 0.1, 0.14, GLASS_LIGHT, [0, 30, 1.4], SHOP_GLOW);
  k.glowBox(0.42, 0.06, 0.25, 0.02, 0.12, 0.14, DARK, [0, 30, 1.8], hex(0xfff0a0));
  // the very tall pole sign, lit all night
  poleSign(k, -0.38, 0.38, 1.3, 0.28, brand, [0, 30, 2.4]);
};

// ---- 56. garage --------------------------------------------------------------------------------

const garage: Draw = (k, _W, _D, b, r) => {
  const wall = pick(r, [0xdad5cb, 0xe8e2d4, 0xcfd6d4]);
  k.box(0, 0, -0.14, 0.86, 0.4, 0.56, wall, ROOF_GREY);
  k.box(0, 0.4, 0.14, 0.86, 0.06, 0.02, pick(r, BRIGHT));
  // one door down, one up with a car on the lift inside
  k.box(-0.2, 0, 0.14, 0.34, 0.32, 0.02, hex(0x9aa0a6));
  k.box(0.2, 0, 0.13, 0.34, 0.32, 0.01, DARK);
  k.box(0.2, 0.12, 0.02, 0.3, 0.02, 0.3, hex(0xf2c14e));
  car(k, 0.2, 0.0, false, pick(r, CARS));
  k.glowBox(0.2, 0.3, 0.1, 0.2, 0.02, 0.02, WHITE, [16.5, 19, 1.4], COOL_GLOW);
  // tyre stack and oil drum
  for (let i = 0; i < 4; i++) k.cyl(-0.38, i * 0.04, 0.36, 0.06, 0.035, DARK, 8);
  k.cyl(0.4, 0, 0.36, 0.04, 0.1, hex(0x2f7fb5), 8);
  void b;
};

// ---- 57. market hall ---------------------------------------------------------------------------

const marketHall: Draw = (k, W, D, b, r) => {
  const stone = pick(r, STONE), iron = hex(0x3f5a4a);
  const bw = W - 0.3, bd = D - 0.3, h = 0.36;
  // the stone base with arched openings on the long sides
  for (const sz of [-1, 1]) {
    const n = 6;
    for (let i = 0; i <= n; i++) k.box(-bw / 2 + (i * bw) / n, 0, sz * bd / 2, 0.1, h, 0.1, stone);
    k.box(0, h - 0.06, sz * bd / 2, bw, 0.06, 0.1, stone);
  }
  for (const sx of [-1, 1]) k.box(sx * bw / 2, h - 0.06, 0, 0.1, 0.06, bd, stone);
  // the barrel vault, drawn as eight glass strips on iron ribs
  const R = bd / 2, seg = 8;
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * Math.PI, a1 = ((s + 1) / seg) * Math.PI;
    const p = (a: number, x: number): [number, number, number] => [x, h + Math.sin(a) * R * 0.7, Math.cos(a) * R];
    k.quad(p(a0, -bw / 2), p(a1, -bw / 2), p(a1, bw / 2), p(a0, bw / 2), s % 2 ? GLASS_LIGHT : scale(GLASS_LIGHT, 0.9), [0, h, 0]);
  }
  for (let i = 0; i <= 6; i++) k.hoop(-bw / 2 + (i * bw) / 6, h, 0, R, 0.018, iron, 8, 'zy');
  k.glowBox(0, 0.02, 0, bw - 0.2, 0.3, bd - 0.2, GLASS_LIGHT, [16, 20, 1.2], SHOP_GLOW);
  // stalls inside, a clock at the gable
  for (let i = 0; i < 4; i++) k.box(-bw / 3 + (i * bw) / 4.5, 0, 0, 0.3, 0.12, 0.2, pick(r, [0xd8a742, 0x5f9e45, 0xe2412f]));
  clock(k, 0, h + R * 0.4, bd / 2 + 0.06, 0.1);
  void b;
};

// ---- 58. department store ----------------------------------------------------------------------

const departmentStore: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), glass = styleGlass(r);
  const bw = W - 0.2, bd = D - 0.2;
  // tall display windows under awnings on the ground floor
  k.box(0, 0, 0, bw, FLOOR * 1.4, bd, scale(wall, 0.95));
  for (const face of [1, 0]) {
    const along = face === 1 ? bw : bd;
    for (let i = 0; i < 4; i++) {
      const o = -along / 2 + 0.25 + (i * (along - 0.5)) / 3;
      if (face === 1) {
        k.pane(o, 0.04, bd / 2, 0.3, FLOOR, 1, GLASS_LIGHT, [16, 30, 1.5], SHOP_GLOW);
        k.box(o, FLOOR * 1.1, bd / 2 + 0.07, 0.34, 0.03, 0.14, pick(r, BRIGHT));
      } else {
        k.pane(bw / 2, 0.04, o, 0.3, FLOOR, 0, GLASS_LIGHT, [16, 30, 1.5], SHOP_GLOW);
        k.box(bw / 2 + 0.07, FLOOR * 1.1, o, 0.14, 0.03, 0.34, pick(r, BRIGHT));
      }
    }
  }
  const top = tower(k, b, r, 0, FLOOR * 1.4, 0, bw, bd, Math.max(3, b.floors - 1), wall, glass, 0.12);
  topOff(k, r, 0, top, 0, bw, bd, wall);
  // the corner entrance, cut diagonally
  k.box(bw / 2 - 0.1, 0, bd / 2 - 0.1, 0.24, FLOOR * 1.2, 0.24, DARK);
  // the rooftop sign in a row of glowing letters
  const sign = pick(r, [0xe2412f, 0xd9a441, 0xffffff]);
  for (let i = 0; i < 6; i++) k.glowBox(-0.5 + i * 0.2, top + 0.2, bd / 2 - 0.2, 0.14, 0.18, 0.03, sign, [16.5, 24, 2.2], sign);
  for (const sx of [-0.55, 0.55]) k.box(sx, top, bd / 2 - 0.2, 0.02, 0.22, 0.02, METAL);
  flag(k, -bw / 2 + 0.1, top, -bd / 2 + 0.1, 0.5, pick(r, BRIGHT));
};

// ---- 59. exchange ------------------------------------------------------------------------------

const exchange: Draw = (k, W, D, b, r) => {
  const stone = pick(r, STONE), body = styleWall(r);
  const bw = W - 0.3, bd = D - 0.6, bz = -0.15;
  const top = tower(k, b, r, 0, 0, bz, bw, bd, Math.max(4, b.floors), body, styleGlass(r), 0.12);
  topOff(k, r, 0, top, bz, bw, bd, body);
  // the columned front and pediment
  portico(k, bz + bd / 2 + 0.16, bw * 0.9, FLOOR * 2.2, 6, stone, stone);
  // the ticker band under the cornice: six boxes stepping through the evening
  for (let i = 0; i < 6; i++) {
    const on = 16 + i * 0.25;
    k.glowBox(-bw / 2 + 0.1 + (i * (bw - 0.2)) / 5, top - 0.14, bz + bd / 2 + 0.01, (bw - 0.2) / 6, 0.06, 0.02, DARK, [on, on + 6 + (i % 3), 2], i % 2 ? hex(0x6fff9a) : hex(0xff5a4a));
  }
  // two bronze figures at the door
  for (const sx of [-1, 1]) {
    k.box(sx * bw * 0.5, 0, bz + bd / 2 + 0.5, 0.12, 0.08, 0.12, stone);
    k.cyl(sx * bw * 0.5, 0.08, bz + bd / 2 + 0.5, 0.03, 0.14, hex(0x8a6a3a), 6);
    k.dome(sx * bw * 0.5, 0.22, bz + bd / 2 + 0.5, 0.03, hex(0x8a6a3a), 6, 2);
  }
};

// ---- 60. data centre ---------------------------------------------------------------------------

const dataCentre: Draw = (k, W, D, _b, r) => {
  const body = hex(0xa8acae);
  const bd = D - 0.8, bz = -D / 2 + 0.1 + bd / 2;
  k.box(-0.2, 0, bz, W - 0.9, 0.6, bd, body, ROOF_GREY);
  for (let i = 0; i < 5; i++) {
    const x = -0.2 - (W - 0.9) / 2 + 0.3 + (i * (W - 1.5)) / 4;
    k.box(x, 0.6, bz, 0.26, 0.1, 0.4, hex(0x8a8f94));
    k.cyl(x, 0.7, bz, 0.08, 0.02, DARK, 8);
  }
  // the lobby slot, the only light
  k.glowBox(-0.2, 0.04, bz + bd / 2 + 0.005, 0.3, 0.22, 0.01, GLASS_LIGHT, [0, 30, 1.6], COOL_GLOW);
  // the generator yard, fenced
  chainFence(k, W / 2 - 0.35, bz, 0.6, bd - 0.2, 0.2, 0);
  for (let i = 0; i < 2; i++) k.box(W / 2 - 0.35, 0, bz - 0.3 + i * 0.6, 0.4, 0.2, 0.3, hex(0x3f5a4a));
  // the security gate
  k.box(0, 0, D / 2 - 0.2, 0.2, 0.22, 0.2, WHITE, ROOF_GREY);
  k.box(-0.35, 0.12, D / 2 - 0.2, 0.5, 0.02, 0.02, hex(0xf2c14e));
  void r;
};

