/** A building's name on a cargo card: what its model makes it (a Locksmith, a Bait Shop: render/modelName.ts), else its kind's. */
function siteName(w: World, b: Building): string {
  const m = modelName(w, b);
  return m ? ('name' in m ? m.name : SITE_LABEL[m.kind as SiteKind] ?? m.kind) : SITE_LABEL[b.kind] ?? b.kind;
}

