/** One bounty over a place: green over a destination, in the goods' own colour over a load. */
/** Could this vehicle carry goods of this type at all, however empty: its hold takes the class and it fits. */
function carries(def: VehicleDef, t: CargoType): boolean {
  return def.holds.includes(t.cls) && t.units <= def.capacity;
}
