/** How much a faded load's ring and tag still show while a mission is under way. */
const DIM = 0.4;
/** A comfortable average pace (tiles/s) once stops and corners are allowed for. */
const EASY_PACE = 0.6;
/** The claim a town request's step carries: held for the player, so it neither expires nor is driven for. */
export const CHAIN_CLAIM = -777000;

/**
 * What a consignment pays. It is worth its own kind, plus what it takes to carry (its units, at
 * its class's rate), plus the length of the trip — all scaled by the time limit it came with, by
 * how hard that limit is to meet over that distance, and by heavyPay for freight and big loads.
 */
export function valueOf(t: CargoType, dist: number, u: Urgency, seconds: number): number {
  const goods = (t.base + CLASS_RATE[t.cls] * t.units + t.perTile * dist) * heavyPay(t);
  const pressure = Number.isFinite(seconds) && seconds > 0 ? Math.min(2.5, dist / seconds / EASY_PACE) : 0;
  const difficulty = 0.9 + 0.5 * pressure;
  return Math.max(5, Math.round((goods * URGENCY[u].pay * difficulty) / 5) * 5);
}

