/**
 * Can goods go from one cell to the other by road? Two counties side by side always can, since every
 * border between them has a road across it; an island and its neighbour can when a causeway joins
 * them. Anything further apart, or only reachable by water, goes harbour to harbour instead.
 */
export function joinedByLand(a: World, b: World): boolean {
  const dx = b.cx - a.cx, dz = b.cz - a.cz;
  if (Math.abs(dx) + Math.abs(dz) !== 1) return false;
  if (a.kind === 'continent' && b.kind === 'continent') return true;
  const d = dx === 1 ? 0 : dx === -1 ? 2 : dz === 1 ? 1 : 3;
  return a.straits.some((st) => st.dir === d);
}

/** How close a vehicle must be to load or deliver goods (tiles): the loading ring's radius. */
export function reachOf(d: VehicleDef): number {
  // a train's reach is along its whole consist: a ring round its middle as long as the train
  return d.kind === 'water' ? 1.8 + d.halfLen : d.kind === 'air' ? (d.jet ? 3 : 2.2) : d.kind === 'rail' ? 1.5 + d.halfLen : 1.5;
}

/** Can this vehicle get there? Boats only reach ports, and big ships only the major ones. */
function reachesSite(d: VehicleDef, s: Site | null): boolean {
  // the seabed is a submarine's, and only one that dives in water that deep (docs/underwater.html)
  if (s?.seabed) return d.kind === 'water' && !!d.dive && (s.depth ?? 0) >= d.dive.need;
  if (s?.afloat) return d.kind === 'water';
  // jets load and unload at airports alone, a long runway's jet only at an international, and fly overseas
  const air = !!s && (s.kind === 'airport' || s.kind === 'intl' || s.kind === 'overseas');
  if (isJet(d)) return !!s && air && (s.kind === 'overseas' || s.major || (d as AirDef).jet!.runway <= 22);
  if (air) return false;
  // a door only the canal comes to is a boat's (or a helicopter's, which goes anywhere)
  if (d.kind !== 'water') return !s?.waterOnly || d.kind === 'air';
  if (s?.canal) return d.halfLen <= CANAL_HULL;
  if (!s || s.port < 0 || s.quay) return false;
  return s.major || d.halfLen <= BIG_SHIP;
}

/** Does a train stop here: a station's platform, or a works loaded beside the line (world/railside.ts). */
/** A crewed train's beat as the beat stock reads it (game/railCrew.ts): its stops, its kind, its hold and its round trip in seconds. */
export interface BeatWork { stops: RailStation[]; freight: boolean; capacity: number; holds: CargoClass[]; trip: number }
/**
 * Holds of beat work a round trip of a beat is given (docs/crewtrains.html): measured, so two trains on it run about three
 * fifths full and one nearly full (a middle stop sees half of what passes through, so more than the 2.4 holds a sum says).
 */
const BEAT_FILL = 4;
/** The kinds of site a station is. */
const STATION_SITE_KINDS: SiteKind[] = ['terminus', 'cityStation', 'townStation', 'halt', 'goodsYard', 'harbourDepot'];
/** A station as the beat stock keys it: by name, which is the county's own (a station's name is its town's). */
const beatKey = (st: RailStation): string => `${st.name}`;
export const railStop = (s: Site | null): boolean => !!s && (!!s.station || RAILSIDE.has(s.kind));

/**
 * Could a train carry this load the whole way (the user, 3 Nov 2026)? Rail work always; anything else only from
 * one rail stop to another. Travellers at a station bound for a hotel, or a parcel at a house, are not a train's:
 * from a train they are neither shown nor taken.
 */
export const railBound = (it: CargoItem): boolean => !!it.type.rail || (railStop(it.from) && railStop(it.to));

/** Can a boat tie up here at all: a harbour that is not just a shed on its quay, or a door on a canal. */
export const boatable = (s: Site | null): boolean => !!s && ((s.port >= 0 && !s.quay) || !!s.canal);

/** Could this vehicle collect these goods where they are and take them where they're going? (Ignores what's already aboard.) */
export function canHaul(d: VehicleDef, it: CargoItem): boolean {
  // Ultra-Bulk work is the player's alone: no hired driver, rival or the island's own traffic takes it
  if (it.type.ultra) return false;
  return d.holds.includes(it.type.cls) && it.type.units <= d.capacity && reachesSite(d, it.from) && reachesSite(d, it.to)
    && (d.kind !== 'water' || it.from !== null) && (!(it.type.sea || it.sea) || d.kind === 'water');
}

/** The models an Ultra-Bulk load is for, by name: "Big Blue", "The Workhorse or The Longhaul". */
function ultraRideNames(t: CargoType): string {
  const names = (t.ultra?.rides ?? []).map((id) => ALL_VEHICLES.find((d) => d.id === id)?.name ?? id);
  return names.length > 1 ? `${names.slice(0, -1).join(', ')} or ${names[names.length - 1]}` : names[0] ?? '';
}

/** How near a car must stand to a place to load there: reachOf for anything on wheels. */
const LAND_REACH = 1.5;

/**
 * How big a ring is drawn round a load or a drop for the vehicle driven: a train's whole-consist reach only round
 * a train's own work (a load only a train takes, or one at a station); everything else, and every shop's door, at
 * the size it always is (the user, 2 Nov 2026: from a train every ring had gone huge).
 */
function ringOf(def: VehicleDef, reach: number, trainWork: boolean): number {
  return def.kind === 'rail' && !trainWork ? LAND_REACH : reach;
}

/** What a ranch sends out of its yard (Cattle Drive), and where Take the Waters' bathers go. */
const STOCK = new Set(['livestock', 'horses', 'cattle']);
const BATHS = new Set(['bathhouse', 'dogoHonkan', 'ashiyu', 'yubatake']);

/**
 * What a load by the player's own hand counts toward in the next world's places (docs/deeds070.html, GEN 53): an
 * elementary school's students, a school trip's places, stock out of a ranch's yard, the onsen towns' bathers and
 * the Fukuzumirō's guests, a lake town's trade, and the town plans delivered into.
 */
function nextWorldDeeds(it: CargoItem): void {
  const to = it.to.kind as string, from = it.from?.kind as string | undefined, b = it.from?.b;
  if (it.type.id === 'students' && to === 'elementarySchool') deeds.add('schoolRun');
  if (it.type.id === 'schoolTrip') deeds.mark('fieldTrips', to);
  if (STOCK.has(it.type.id) && b && it.from!.w.ranches.some(({ yard: y }) => b.x >= y.x && b.x < y.x + y.w && b.z >= y.z && b.z < y.z + y.d)) deeds.add('cattleDrive');
  if ((it.type.id === 'bathers' || it.type.id === 'spaGuests') && BATHS.has(to)) deeds.add('bathers');
  if (it.type.cls === 'people' && (to === 'fukuzumiro' || from === 'fukuzumiro')) deeds.add('fukuzumiro');
  if (isLakeKind(to) || from === 'steamerPier') deeds.add('lakeSeason');
  const w = it.to.w, tid = w.townId[idx(Math.min(N - 1, Math.max(0, Math.floor(it.to.lx))), Math.min(N - 1, Math.max(0, Math.floor(it.to.lz))))];
  const plan = tid >= 0 ? w.towns[tid]?.plan : undefined;
  if (plan && plan !== 'grid') deeds.mark('planEconomy', plan);
}

/**
 * The water's edge in front of a building that faces a canal: the middle of the canal tile its front
 * looks onto, pulled in toward the quay. Null when it faces a street (or anything but water).
 */
function canalDoor(w: World, b: Building): { x: number; z: number } | null {
  const [dx, dz] = DIRS[b.facing];
  const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
  const fx = Math.floor(cx + dx * (b.w / 2 + 0.5)), fz = Math.floor(cz + dz * (b.d / 2 + 0.5));
  if (!inB(fx, fz) || w.water[idx(fx, fz)] < 0 || w.road[idx(fx, fz)]) return null;
  return { x: fx + 0.5 - dx * 0.25, z: fz + 0.5 - dz * 0.25 };
}

/** Is there a road tile within r of this point? */
function roadWithin(w: World, x: number, z: number, r: number): boolean {
  for (let tz = Math.floor(z - r); tz <= Math.floor(z + r); tz++) {
    for (let tx = Math.floor(x - r); tx <= Math.floor(x + r); tx++) {
      if (inB(tx, tz) && w.road[idx(tx, tz)] && Math.hypot(tx + 0.5 - x, tz + 0.5 - z) <= r) return true;
    }
  }
  return false;
}

/** Is there canal water (not under a bridge deck) within r of this point? */
function canalWithin(w: World, x: number, z: number, r: number): boolean {
  for (let tz = Math.floor(z - r); tz <= Math.floor(z + r); tz++) {
    for (let tx = Math.floor(x - r); tx <= Math.floor(x + r); tx++) {
      if (inB(tx, tz) && w.water[idx(tx, tz)] >= 0 && !w.road[idx(tx, tz)] && Math.hypot(tx + 0.5 - x, tz + 0.5 - z) <= r) return true;
    }
  }
  return false;
}

/** A harbour a boat can tie up at (a quay is a working berth, not a place goods change hands). */
const harbourSite = (s: Site): boolean => s.port >= 0 && !s.quay;

/** Is this a boat's load in its own cell: harbour to harbour, both in the one cell? */
export function seaLoadIn(w: World, it: CargoItem): boolean {
  return it.w === w && it.to.w === w && !!it.from && harbourSite(it.from) && harbourSite(it.to);
}

/**
 * Boat work kept waiting in a cell (README, "Boats"): at least `base` harbour-to-harbour loads for
 * every cell where the player has a boat out, plus `perBoat` for each boat there, up to `most`. They are
 * over and above the board's usual cap, and checked every `every` seconds. Without this a boat's work was
 * a handful of types among 146 on a board that is nearly always full, and the vans got to most of it.
 */
/** Entrance rings built in one frame at most (syncDoors). */
const DOORS_A_FRAME = 2;
/**
 * A shop's, a dealer's or a faction depot's sign is shown only within this many tiles of it, fading in over the last
 * SHOP_FADE (the user, 11 Nov 2026: a town's banners all hung over the skyline from across the bay).
 */
const SHOP_NEAR = 40, SHOP_FADE = 6;
/** Seconds a boat-to-harbour sea distance is trusted for (spawnSea). */
const SEA_NEAR_KEEP = 30;

export const SEA_WORK = {
  base: 1, perBoat: 2, most: 7, every: 3, over: 16,
  /** A pick-up this far by sea from one of the boats is near; near ones are put out first. */
  near: 110,
  /** The sail from harbour to harbour: at most this many tiles, and at most `detour` × as the crow flies (plus `slack`). */
  longest: 220, detour: 2.2, slack: 40,
};

/**
 * What boats the player has out in a cell: how many, what their holds take, the biggest hold, whether
 * every one is too big for the small harbours, one of them to measure the sea by, and where each floats.
 */
interface SeaDemand {
  boats: number; holds: Set<CargoClass>; capacity: number; big: boolean;
  def: VehicleDef; at: { x: number; z: number }[];
}

export function surfaceY(w: World, x: number, z: number): number {
  const i = idx(Math.min(N - 1, Math.max(0, Math.floor(x))), Math.min(N - 1, Math.max(0, Math.floor(z))));
  const ground = heightAt(w, Math.min(N - 0.001, Math.max(0, x)), Math.min(N - 0.001, Math.max(0, z)));
  return w.water[i] >= 0 ? Math.max(ground, w.water[i] * STEP) : ground;
}

/**
 * Where goods sit for a building: at the kerb in front of its door, else the nearest road tile
 * around it; for an open lot, the lot tile beside a road nearest its middle.
 */
/** The drivable tile nearest a landform's middle, within reach of it. */
function landmarkAnchor(w: World, cx: number, cz: number, reach: number): { x: number; z: number } | null {
  let best: { x: number; z: number } | null = null, bestD = Infinity;
  const x0 = Math.floor(cx), z0 = Math.floor(cz), R = Math.ceil(reach);
  for (let z = z0 - R; z <= z0 + R; z++) {
    for (let x = x0 - R; x <= x0 + R; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (!w.edges[i] || w.blocked[i] || w.water[i] >= 0) continue;
      const d = Math.hypot(x + 0.5 - cx, z + 0.5 - cz) - (w.road[i] ? 3 : 0);
      if (d < bestD) { bestD = d; best = { x: x + 0.5, z: z + 0.5 }; }
    }
  }
  return best;
}

/** The kerb in front of a building, where its goods are picked up and put down (world/storefronts.ts). */
export const anchor = kerbOf;

/** No made load is worth a gold long-haul load (docs/supplychains.html): it wins on volume, not on one crate. */
const MADE_TOP = 4990;
/** What a building site takes at its gate while it stands (docs/supplychains.html, chain 5). */
export const SITE_GOODS = new Set(['readyMix', 'panels', 'asphalt']);
/** Fireworks bound for a show on now pay this much more: the crowd is waiting (chain 19). */
const EVENT_PAY = 1.5;

/** Goods a cold box keeps (VehicleDef.coldHold): the ice and what is made with it. */
const COLD_GOODS = new Set(['iceCream', 'iceCreamTubs', 'sundaes', 'ice', 'vaccine', 'smokedFish', 'milk', 'fish', 'cocktails']);

let chainKindsCache: SiteKind[] | null = null;
/**
 * Every kind a supply chain trades through (docs/supplychains.html): the plants in the recipe book, and the places
 * that buy what only plants make. They are cargo sites whether or not the island's own goods ever call there.
 */
function chainKinds(): SiteKind[] {
  chainKindsCache ??= [...new Set<SiteKind>([...recipeBook().keys()].map((k) => k as SiteKind).concat(MADE_CARGO.flatMap((t) => t.to)))];
  return chainKindsCache;
}

/** Every place on one island that some kind of goods comes from or goes to, appended to `sites`. */
export function buildSites(w: World, sites: Site[], label: string): void {
  // ...and the quiet places contraband is picked up at and dropped off (docs/smuggling.html)
  const wanted = new Set<SiteKind>([...CARGO.flatMap((t) => [...t.from, ...t.to]), ...CONTRABAND_SITES, ...chainKinds()]);
  const add = (kind: SiteKind, name: string, x: number, z: number, port = -1, major = false, b?: Building) =>
    sites.push({ id: sites.length, kind, name: label ? `${name} · ${label}` : name, w, lx: x, lz: z, x: x + w.ox, z: z + w.oz, y: surfaceY(w, x, z), port, major, b }) - 1;
  for (const t of w.towns) {
    for (const b of t.buildings) {
      // a boarded-up building sends nothing out and takes nothing in; one still going up (docs/blueprints.html) trades from the poof
      if (!wanted.has(b.kind) || b.derelict || builtShare(b) < 1) continue;
      // in a canal town a door on the water is served from the water (world/canals.ts)
      const wet = t.canals ? canalDoor(w, b) : null;
      const p = wet ? null : anchor(w, b);
      const at = wet ?? p;
      if (!at) continue;
      const i = add(b.kind, `${siteName(w, b)} · ${t.name}`, at.x, at.z, -1, false, b);
      sites[i].tier = t.kind;
      sites[i].style = t.style;
      if (wet) { sites[i].canal = true; sites[i].waterOnly = !roadWithin(w, wet.x, wet.z, LAND_REACH); }
      // a door on a street with a canal just beside it: a boat can come alongside too
      else if (t.canals && p && canalWithin(w, p.x, p.z, 1.2)) sites[i].canal = true;
    }
  }
  // the country and the wonders: crofts, lodges and shrines out on their own, the pyramid at the end of its road
  const loose = [...w.countryside, ...w.works.filter((g) => g.kind === 'wonder' || g.kind === 'quarry' || g.kind === 'resort' || g.kind === 'mine').flatMap((g) => g.buildings)];
  for (const b of loose) {
    if (b.gone || !wanted.has(b.kind) || builtShare(b) < 1) continue;
    // a faction's stronghold (docs/strongholds.html): its loads are fetched and taken at its headquarters' door,
    // inside its walls, where only those it honours can drive
    if (isStronghold(b.kind)) {
      const plan = strongholdPlan(b.kind);
      const [dx, dz] = fromPlan(b, plan.door.x, plan.door.z);
      add(b.kind, `${siteName(w, b)} · ${w.name}`, dx, dz, -1, false, b);
      continue;
    }
    // works out at sea (world/undersea.ts, 0.8.0): served over the middle of the lot, on the bottom by a sounded
    // submarine or alongside at the surface by any boat
    if (isUndersea(b.kind)) {
      const mx = b.x + b.w / 2, mz = b.z + b.d / 2, i = idx(Math.floor(mx), Math.floor(mz));
      const s = sites[add(b.kind, `${siteName(w, b)} · ${w.name}`, mx, mz, -1, false, b)];
      if (AFLOAT_KINDS.has(b.kind)) { s.afloat = true; s.y = w.water[i] * STEP; continue; }
      let depth = Infinity;
      for (let zz = b.z; zz < b.z + b.d; zz++) for (let xx = b.x; xx < b.x + b.w; xx++) depth = Math.min(depth, waterDepth(w, idx(xx, zz)));
      s.seabed = true; s.depth = Number.isFinite(depth) ? depth : 0; s.y = b.level * STEP;
      continue;
    }
    // works by the railway (world/railside.ts, 0.8.0): loaded beside the main line in front of it, where a train
    // stopped alongside reaches (the edge facing the line when no ground-level track is found near)
    if (RAILSIDE.has(b.kind)) {
      const [dx, dz] = DIRS[b.facing];
      let ex = b.x + b.w / 2 + dx * (b.w / 2 + 0.6), ez = b.z + b.d / 2 + dz * (b.d / 2 + 0.6);
      let best = Infinity, tx = ex, tz = ez;
      for (let zz = Math.floor(ez) - 6; zz <= Math.floor(ez) + 6; zz++) for (let xx = Math.floor(ex) - 6; xx <= Math.floor(ex) + 6; xx++) {
        if (!inB(xx, zz)) continue;
        const r = w.rail[idx(xx, zz)];
        if (!(r & RailBit.Track) || (r & (RailBit.Deck | RailBit.Tunnel))) continue;
        const d = Math.hypot(xx + 0.5 - ex, zz + 0.5 - ez);
        if (d < best) { best = d; tx = xx + 0.5; tz = zz + 0.5; }
      }
      // just off the rails on the works' side
      if (best < Infinity) { const l = Math.hypot(ex - tx, ez - tz) || 1; ex = tx + ((ex - tx) / l) * 0.9; ez = tz + ((ez - tz) / l) * 0.9; }
      add(b.kind, `${siteName(w, b)} · ${w.name}`, ex, ez, -1, false, b);
      continue;
    }
    const at = anchor(w, b) ?? landmarkAnchor(w, b.x + b.w / 2, b.z + b.d / 2, Math.max(b.w, b.d) / 2 + 4);
    if (!at) continue;
    const work = w.works.find((g) => g.buildings.includes(b));
    add(b.kind, work ? work.name : `${siteName(w, b)} · ${w.name}`, at.x, at.z, -1, false, b);
    if (work && work.kind === 'wonder') add('landmark', `${work.name} · Wonder`, at.x, at.z);
  }
  // stations: on the platform edge in front of the building, where a train alongside and a car on the forecourt both reach
  for (const st of w.stations) {
    const b = st.building;
    if (!b || !wanted.has(b.kind)) continue;
    const fx = b.facing === 0 ? b.x + b.w + 0.3 : b.facing === 2 ? b.x - 0.3 : b.x + b.w / 2;
    const fz = b.facing === 1 ? b.z + b.d + 0.3 : b.facing === 3 ? b.z - 0.3 : b.z + b.d / 2;
    sites[add(b.kind, st.name, fx, fz, -1, false, b)].station = st;
  }
  // helipads: on the roof where the pad is painted, at the pad's own height, for helicopter work (world/helipads.ts)
  for (const p of helipadsOf(w)) {
    if (!wanted.has(p.kind)) continue;
    const town = w.towns.find((t) => t.buildings.includes(p.b)) ?? w.works.find((g) => g.buildings.includes(p.b));
    const i = add(p.kind, `${SITE_LABEL[p.kind] ?? 'Helipad'}${town ? ` · ${town.name}` : ''}`, p.x, p.z, -1, false, p.b);
    sites[i].y = p.y;
  }
  // the seabed (world/seabed.ts, docs/underwater.html): a submarine's work, on the bottom under a dive buoy
  for (const s of seabedSites(w)) {
    if (!wanted.has(s.kind)) continue;
    const i = add(s.kind, s.name.charAt(0).toUpperCase() + s.name.slice(1), s.lx, s.lz);
    sites[i].y = s.floor;
    sites[i].seabed = true;
    sites[i].depth = s.depth;
  }
  // airports: jet work waits at the stand at one end of the apron; an international also sends long hauls
  // out over the horizon, to a point far along its runway's line away from the middle of the world (a two-runway
  // airport is one airport, by its first runway: world/runways.ts `second`)
  for (const r of runwaysOf(w)) {
    if (r.second) continue;
    const st = r.stands[0];
    const lx = st.x - w.ox, lz = st.z - w.oz;
    const i = add('airport', r.name, lx, lz, -1, r.major);
    if (!r.major) continue;
    add('intl', r.name, lx, lz, -1, true);
    const mx = (r.ax + r.bx) / 2, mz = (r.az + r.bz) / 2;
    const dirs: [number, number][] = [[r.ux, r.uz], [-r.ux, -r.uz]];
    const [dx, dz] = dirs.sort((a, b) => Math.hypot(mx + b[0] * OVERSEAS_OUT, mz + b[1] * OVERSEAS_OUT) - Math.hypot(mx + a[0] * OVERSEAS_OUT, mz + a[1] * OVERSEAS_OUT))[0];
    const name = OVERSEAS_NAMES[Math.abs(Math.floor(mx * 7 + mz * 13)) % OVERSEAS_NAMES.length];
    const o = add('overseas', `Overseas · ${name}`, mx - w.ox + dx * OVERSEAS_OUT, mz - w.oz + dz * OVERSEAS_OUT, -1, true);
    sites[o].y = sites[i].y + 14;
  }
  // harbours: on the pier (mid-way along a major one, at the root of a jetty), in reach of trucks on the quay and boats at the berths
  for (const p of w.ports) {
    const [dx, dz] = DIRS[p.dir];
    const rx = p.root % N, rz = (p.root - rx) / N, k = p.major ? 3 : 1;
    add(p.major ? 'majorPort' : 'minorPort', p.name, rx + 0.5 + dx * k, rz + 0.5 + dz * k, p.id, p.major);
    // …and the sheds along its quay that trade in their own right — a cannery, a dry dock — each at its
    // own door, not at the pier head. They carry their harbour's id so their trade goes on its books and
    // its deed (game/ledger.ts, siteLotKey); a boat still berths at the harbour itself and never at a
    // shed standing on the quay (see reachesSite).
    for (const b of p.buildings) {
      if (b.gone || !wanted.has(b.kind)) continue;
      // a shed on the quay often has no kerb of its own: the apron round it is what a truck pulls onto,
      // so fall back to the nearest tile a vehicle can stand on, as the country buildings do
      const at = anchor(w, b) ?? landmarkAnchor(w, b.x + b.w / 2, b.z + b.d / 2, Math.max(b.w, b.d) / 2 + 3);
      if (!at) continue;
      sites[add(b.kind, `${siteName(w, b)} · ${p.name}`, at.x, at.z, p.id, p.major, b)].quay = true;
    }
  }
  // the named landforms: sightseers go to them, and a volcano and a salt pan send goods out
  for (const l of w.landmarks) {
    if (!LANDFORM_LABEL[l.kind] || l.kind === 'skerries' || l.kind === 'fjordCoast') continue;
    const at = landmarkAnchor(w, l.x, l.z, Math.max(4, Math.min(l.r, 30)));
    if (!at) continue;
    add('landmark', `${l.name} · ${l.kind === 'wood' ? woodLabel(l) : l.kind === 'crossing' ? crossingLabel(l) : LANDFORM_LABEL[l.kind]}`, at.x, at.z);
    if (l.kind === 'volcano' || l.kind === 'saltFlat') add(l.kind, l.name, at.x, at.z);
  }
  for (const poi of w.pois) {
    if (!wanted.has(poi.type)) continue;
    for (const [dx, dz] of DIRS) {
      const x = poi.x + dx, z = poi.z + dz;
      if (!inB(x, z) || !w.edges[idx(x, z)] || w.blocked[idx(x, z)]) continue;
      add(poi.type, poi.type === 'barn' ? 'Farm barn' : SITE_LABEL[poi.type] ?? poi.type, x + 0.5, z + 0.5);
      break;
    }
  }
}

interface Verdict { kind: 'ok' | 'far' | 'bad'; text: string }

/**
 * Goods and missions. Each kind of cargo turns up now and then at a random place that produces it
 * (more often near the player), with a destination, a bounty and a time limit. The player loads
 * goods by driving into their ring and pressing Space or clicking them, and delivers by stopping
 * inside the green ring at the destination. CPU haulers claim, collect and deliver goods through
 * openJobs / claim / collect / deliverCpu.
 */
export class CargoSystem {
  readonly group = new THREE.Group();
  items: CargoItem[] = [];
  hold: CargoItem[] = [];
  /**
   * Everything aboard a vehicle that is not the player's: a hired driver's manifest, or a CPU hauler's
   * load. It decays exactly as the player's hold does, so a load in a driver's hold is worth what yours
   * would be after the same journey.
   */
  carried = new Set<CargoItem>();
  sites: Site[] = [];
  delivered = 0;
  cpuDelivered = 0;
  /** Every island whose goods are live: the one the player is on, and its near neighbours. */
  private islands: World[] = [];
  private home: World | null = null;
  private byKind = new Map<SiteKind, Site[]>();
  /** Each trading building's site, for a plant looking for its own kerb (docs/supplychains.html). */
  private byBuilding = new Map<Building, Site>();
  /** A made load has gone stale on the ground (game/chains/plants.ts counts it against its plant). */
  onMadeGone: ((it: CargoItem) => void) | null = null;
  private timers = new Map<string, number>();
  private dests = new Map<number, { marker: CargoMarker; site: Site; value: number }>();
  /**
   * The loads aboard a vehicle the camera is following (one of your drivers', a rival's): their
   * destinations get the same green rings and bounties as your own hold's, drawn at that vehicle's reach.
   * `jet`: it is one of your hired jets (game/jetPilots.ts), so the airports' jet work it loads shows, as it
   * does with the player at a jet's controls.
   */
  private watched: Watched | null = null;

  /** Ring the drops of what a followed vehicle carries, or null to stop. */
  watch(w: Watched | null): void { this.watched = w; }
  /** Entrance rings: the missions' doors, and the destinations of goods that go in through one. */
  private doors: Door[] = [];
  private doorMarks = new Map<string, DoorMarker>();
  /** Space at one of the missions' doors: which. */
  onDoor: ((key: string) => void) | null = null;
  /** The Vehicle Shops' and Dealers' doors in the cells around (game/outlets.ts). */
  private shopDoors: Door[] = [];
  /** Space at a shop's or a dealer's door: its outlet key. */
  onShop: ((key: string) => void) | null = null;
  /** Space in a tavern's ring. */
  onTavern: ((key: string) => void) | null = null;
  private nextId = 1;
  /** A new load id, for loads made outside (the hold put back from a save): every load in the hold needs its own. */
  freshId(): number { return this.nextId++; }
  private time = 0;
  /** The factions' version the loads' colours were last looked at against. */
  private lookRev = -1;
  private invTimer = 0;
  private hovered: CargoItem | null = null;
  /** Goods under the pointer this frame, if any. */
  get hoverItem(): CargoItem | null { return this.hovered; }
  private v = new THREE.Vector3();
  /** The town ledgers, told about every delivery and every load left to expire. */
  books: TownBooks | null = null;
  /**
   * Faction standing (docs/factions.html): what a load pays by the faction it belongs to and the player's
   * standing with it, and the bars a delivery moves. Null until the game wires it.
   */
  fac: CargoFactions | null = null;
  /**
   * While the player drives a train: the stations on its line by how far ahead of its front they lie
   * (behind negative). Goods turning up at one of them for a station are sent on down the line, never back.
   */
  railLine: (() => Map<RailStation, number> | null) | null = null;

  /** Whether the player drives a submarine this frame: submarine work shows, and turns up, only then. */
  private inSub = false;
  /** Whether the player is flying a helicopter this frame: helicopter work shows, and turns up, only then. */
  private flyingHeli = false;
  /**
   * How the world's own work shows (set by the missions each frame): 'all' as it is, 'dim' faded behind
   * a mission under way, 'only' not at all (the first drive, where only its own goods are out).
   */
  focus: 'all' | 'dim' | 'only' = 'all';
  /**
   * Is this load for the player to see now? Helicopter work only from a helicopter; nothing but a mission's in the
   * first drive; and from a train, only what a train can carry the whole way (`railBound`).
   */
  private shown(it: CargoItem): boolean {
    return (!it.type.heli || this.flyingHeli) && (!it.type.jet || this.flyingJet || !!this.watched?.jet) && (!it.type.sub || this.inSub) && (!it.type.rail || this.onRails) && (!this.onRails || railBound(it)) && (!it.type.ultra || this.ultraRide(it.type)) && (this.focus !== 'only' || it.chain !== undefined);
  }
  /** Is the player driving one of the models this Ultra-Bulk work is for? It shows, and turns up, only then. */
  private ultraRide(t: CargoType): boolean { return !!t.ultra && !!this.playerDef && t.ultra.rides.includes(this.playerDef.id); }
  /** Seconds to the next Ultra-Bulk load. */
  private ubT = 8;
  /** Whether the player is driving a train this frame: a train's long-haul work shows only then. */
  private onRails = false;
  /** Every airport surveyed, near and far (main.ts from world/surveyor.ts): where a jet's long-haul work goes. */
  farAirports: (() => KnownAirport[]) | null = null;
  /** Ids for the places long-haul work is bound for before their counties are in memory: never a real site's. */
  private farId = -3_000_000;
  /** Seconds to the next long-haul load, and to the next look for the counties those waiting are bound for. */
  private lhT = 10;
  private lhResolveT = 0;
  /** Faded behind the mission under way: anybody's goods, not the mission's own. */
  private faded(it: CargoItem): boolean { return this.focus === 'dim' && it.chain === undefined; }
  /** Whether the player is flying a jet this frame: jet work shows, and turns up, only then. */
  private flyingJet = false;

  /**
   * Every model driving on the island right now, the player's included: the island's own traffic, the
   * hired drivers and the rival firms (set by main.ts from game/traffic.ts, which owns all three). Work
   * written for one model (`veh` in game/cargoTypes.ts) only turns up while one of them is about, so a
   * prom party never waits at a kerb on an island with no limousine on it.
   */
  modelsAbout: (() => Set<string>) | null = null;
  /** The player's boats out in a cell (main.ts): the boat work kept waiting there is for them. */
  seaDemand: ((w: World) => SeaDemand | null) | null = null;
  /** Tiles by sea from (x, z) in a cell's frame to one of its harbours, for this boat; null when no way (main.ts, via the cell's traffic). */
  seaRoute: ((w: World, def: VehicleDef, x: number, z: number, port: number) => number | null) | null = null;
  /** Where a boat of this model berths at a harbour, in the cell's frame. */
  seaBerth: ((w: World, def: VehicleDef, port: number) => { x: number; z: number } | null) | null = null;
  /** Harbour-to-harbour sails already measured, by cell, model and the two harbours (they don't move). */
  private seaLegs = new Map<string, number | null>();
  /** Each trading island's sites as last built, with the revision and label they were built at (rebuildSites). */
  private siteCache = new Map<World, { rev: number; label: string; sites: Site[] }>();
  /**
   * How far by sea each harbour is from a boat, by the boat's 8-tile square, for SEA_NEAR_KEEP seconds:
   * spawnSea used to sail every boat to every harbour again every 3 s, a whole-sea search each (340 to
   * 410 ms frames in the lag audit, Oct 2026).
   */
  private seaNear = new Map<string, { tiles: number; at: number }>();
  /** Has this frame's route-finding been spent (traffic.ts routesSpent)? Then new sea routes wait. */
  routesBusy: () => boolean = () => false;
  private seaT = 0;
  private about = new Set<string>();
  private aboutAt = -1;
  private models(): Set<string> {
    if (this.aboutAt !== this.frame) {
      this.about = this.modelsAbout?.() ?? new Set<string>();
      if (this.playerDef) this.about.add(this.playerDef.id);
      this.aboutAt = this.frame;
    }
    return this.about;
  }
  /** Ticks once a frame, so the models about are gathered once however many loads ask. */
  private frame = 0;

  /** Is there a vehicle about that this work was written for? */
  private wanted(t: CargoType): boolean {
    return !t.veh || t.veh.some((id) => this.models().has(id));
  }

  /**
   * Does this end of a trip sit in the sort of town the work asks for? A load with a `tier` or a
   * `style` needs one end of its trip to suit; the other may be anywhere, so a city's film crew can
   * still be driven out to a landmark in the country.
   */
  private suits(t: CargoType, s: Site): boolean {
    if (t.tier && !(s.tier && t.tier.includes(s.tier))) return false;
    if (t.style && !(s.style && t.style.includes(s.style))) return false;
    return true;
  }

  /** Where the player was last frame, in world tiles, for the float over an abandoned load. */
  private lastVeh = new THREE.Vector3();

  /**
   * The vehicle in the player's hands and where it stands, written each frame. New goods are fitted to
   * it (game/fit.ts): a load the player could carry is given a time limit this vehicle can actually
   * meet, and pairs of places it cannot reach are passed over in favour of ones it can.
   */
  playerDef: VehicleDef | null = null;
  playerAt: Place | null = null;
  /** Where the player's drivers out working are, world tiles (main.ts): goods turn up near them too. */
  fleetAt: (() => { x: number; z: number }[]) | null = null;
  /**
   * Who the island's work is written for (game/cargoDemand.ts): the player, the hired drivers and the
   * rival firms' vehicles out on the road (main.ts). Set, it replaces the timers: loads are made to keep
   * each of them supplied, near, with what it can carry, and nothing is made for nobody.
   */
  carriers: (() => Carrier[]) | null = null;
  private demandT = 0;
  /** Seconds each carrier has gone short with nothing near to make for it (by key): past DEMAND.dryLure, a lure. */
  private dry = new Map<string, number>();
  /** From-sites (any kind of goods) per DEMAND.grid square, for "where is there more work" (rebuildSites). */
  private busyGrid = new Map<number, number>();
  /** What the demand made and why, for the study and the console: pr.cargo.demandLog. */
  demandStats = { near: 0, lure: 0, home: 0, ambient: 0, culled: 0, short: 0 };
  /** Told about every load the player delivers by hand, so a request can tick its step off. */
  onDelivered: (it: CargoItem) => void = () => {};
  /** From a train: which way along the line a load in the hold goes, and how many stops (main.ts, game/railWay.ts). */
  railNote: ((it: CargoItem) => RailNote | null) | null = null;
  /** A load's card in the cargo list clicked: show where it is going (main.ts). */
  onPickLoad: ((it: CargoItem) => void) | null = null;
  /** Why a load in the hold may not be put down yet (a convoy's, waiting for its vehicles: Missions.heldBack), or null. */
  heldBack: ((it: CargoItem) => string | null) | null = null;
  /** Why a load may not be picked up in this vehicle (a mission's that only rides in certain models: Missions.loadWhy), or null. */
  loadWhy: ((it: CargoItem, def: VehicleDef) => string | null) | null = null;
  /** The player has loaded goods a rival firm's driver was on the way for. */
  onSnatch: ((it: CargoItem) => void) | null = null;
  /** A rival firm's driver has picked up goods waiting within sight of the player (`claim` is its claim id). */
  onRivalTook: ((it: CargoItem, claim: number) => void) | null = null;
  /**
   * First refusal (docs/rivals.html): the carrier a load is held for while it is young — its town's
   * preferred carrier — or '' when anyone may take it.
   */
  refusal: ((it: CargoItem) => string) | null = null;

  /** Is this load held for some carrier other than `who` ('you', a firm id, or '' for the anonymous CPU)? */
  refused(it: CargoItem, who: string): boolean {
    if (!this.refusal || it.born === undefined) return false;
    const holder = this.refusal(it);
    return !!holder && holder !== who;
  }
  /** Seconds since the load turned up. */
  ageOf(it: CargoItem): number { return this.time - (it.born ?? this.time); }
  /**
   * The suggested order to drop the hold in (docs/manifests.html): load id to which drop it is, 1 first,
   * or empty when everything aboard goes to one place. Advice only: nothing is enforced or scored.
   */
  dropOrder = new Map<number, number>();
  private orderKey = '';
  private orderT = 0;

  constructor(scene: THREE.Scene, readonly hud: CargoHud, private wallet: Wallet) {
    scene.add(this.group);
    hud.onAbandon = (id) => this.abandon(id);
    hud.onPick = (id) => { const it = this.hold.find((q) => q.id === id); if (it) this.onPickLoad?.(it); };
  }

  /** What abandoning a load costs: a share of what it was worth when it turned up, and never nothing. */
  fineFor(it: CargoItem): number {
    if (it.culture !== undefined) return 0;
    return Math.max(ABANDON_MIN, Math.round((it.value0 * ABANDON_SHARE) / 5) * 5);
  }

  /**
   * Throw a load out of the hold for good. The player pays the penalty (the wallet may go into the
   * red), the goods are gone, and the town they came from books it as a load nobody delivered.
   */
  abandon(id: number): boolean {
    const it = this.hold.find((h) => h.id === id);
    if (!it) return false;
    // cultural goods are not anybody's order: set down, they go back to where they were found, at no cost
    if (it.culture !== undefined) {
      this.hold = this.hold.filter((h) => h !== it);
      this.onCultureDropped?.(it);
      this.refreshInventory();
      return true;
    }
    const fine = this.fineFor(it);
    this.hold = this.hold.filter((h) => h !== it);
    this.wallet.fine(fine, 'fines');
    this.books?.expired(it);
    const at = this.lastVeh.clone();
    at.y += 0.5;
    this.hud.float(`−${money(fine)} abandoned ${it.type.icon}`, at, 'fine');
    this.hud.setCash(this.wallet.cash);
    this.refreshInventory();
    return true;
  }

  get cash(): number { return this.wallet.cash; }
  /** Is this island one whose goods are in play just now? */
  trades(w: World): boolean { return this.islands.includes(w); }

  /**
   * Set which islands have goods on them, the first being the one the player is on. Goods already
   * waiting on an island that has dropped out of range go with it; anything in the hold stays, and
   * its destination ring comes back when that island is in range again.
   */
  setIslands(list: World[]): void {
    if (list.length === this.islands.length && list.every((w, k) => w === this.islands[k])) return;
    const live = new Set(list);
    for (const it of [...this.items]) if (!live.has(it.w)) this.unplace(it);
    this.islands = list;
    this.home = list[0] ?? null;
    this.rebuildSites();
    if (!list.length) {
      this.dests.clear();
      for (const m of this.doorMarks.values()) disposeDoorMarker(m);
      this.doorMarks.clear();
      this.hud.clearTags();
      this.hud.hideTip();
      this.hud.setPrompt(null);
      this.hovered = null;
      return;
    }
    if (this.timers.size) return;
    // a world that is already busy: one of most kinds waiting, the rest on their way
    for (const t of CARGO) {
      this.timers.set(t.id, rand(t.every[0], t.every[1]));
      // under the demand the board fills round whoever is about, within a second or two, not at random
      if (this.carriers) continue;
      if (t.heli || t.jet || t.sub || !this.wanted(t)) continue;
      if (Math.random() < 0.75) this.spawn(t, null);
    }
  }

  /** Work out the places goods come from and go to again (islands changed, or something was bulldozed). */
  /**
   * `changed`: an island whose buildings or ground just changed, built afresh; every other trading island's
   * sites are kept from last time (by its revision and label). A crossing used to build all ~2,400 sites
   * of every trading island again, in one frame, each time the trading set changed (the lag audit, Oct 2026).
   */
  rebuildSites(changed?: World): void {
    if (changed) this.siteCache.delete(changed);
    const trading = new Set(this.islands);
    for (const w of [...this.siteCache.keys()]) if (!trading.has(w)) this.siteCache.delete(w);
    this.sites = [];
    for (const w of this.islands) {
      const label = this.islands.length > 1 ? w.name : '';
      let c = this.siteCache.get(w);
      if (!c || c.rev !== w.revision || c.label !== label) {
        const list: Site[] = [];
        buildSites(w, list, label);
        c = { rev: w.revision, label, sites: list };
        this.siteCache.set(w, c);
      }
      for (const site of c.sites) this.sites.push(site);
    }
    this.sites.forEach((site, k) => { site.id = k; });
    // anything aboard or waiting keeps pointing at a live site with the same name and place
    const at = (site: Site) => `${site.w.cx},${site.w.cz}|${site.kind}|${site.lx}|${site.lz}`;
    const byPlace = new Map<string, Site>();
    for (const site of this.sites) if (!byPlace.has(at(site))) byPlace.set(at(site), site);
    const find = (site: Site) => (byPlace.get(at(site))?.w === site.w ? byPlace.get(at(site))! : site);
    for (const it of [...this.items, ...this.hold, ...this.carried]) {
      it.to = find(it.to);
      if (it.from) it.from = find(it.from);
    }
    this.byKind.clear();
    this.byBuilding.clear();
    for (const s of this.sites) {
      let l = this.byKind.get(s.kind);
      if (!l) this.byKind.set(s.kind, (l = []));
      l.push(s);
      if (s.b && s.port < 0 && !this.byBuilding.has(s.b)) this.byBuilding.set(s.b, s);
    }
    // where the work is: every site something is fetched from, counted by grid square
    this.busyGrid.clear();
    for (const s of this.sites) {
      if (!FROM_KINDS.has(s.kind)) continue;
      const k = gridKey(s.x, s.z);
      this.busyGrid.set(k, (this.busyGrid.get(k) ?? 0) + 1);
    }
  }

  private sitesOf(kinds: SiteKind[]): Site[] {
    return kinds.flatMap((k) => this.byKind.get(k) ?? []);
  }

  /** Every live site of these kinds: what a request's template fills itself from. */
  sitesOfKinds(kinds: SiteKind[]): Site[] { return this.sitesOf(kinds); }

  /** New goods of type t at a place that makes them (usually near `near`), bound for somewhere that wants them. */
  spawn(t: CargoType, near: { x: number; z: number } | null, within?: { x: number; z: number }[]): CargoItem | null {
    if (!this.islands.length || this.items.length >= (within ? DEMAND.most : MAX_WAITING)) return null;
    // long-haul and Ultra-Bulk work come only from their own spawners, priced there (base 0 here would give it away)
    if (t.longHaul || t.ultra) return null;
    let froms = this.sitesOf(t.from).filter((s) => !this.items.some((it) => it.from === s));
    // ambient work under the demand: only where somebody could matter to it, and never beside another load
    if (within) froms = froms.filter((s) => within.some((p) => Math.hypot(s.x - p.x, s.z - p.z) <= DEMAND.relevant) && !this.crowded(s.x, s.z));
    // a load cut to a size or a style of town starts in one where it can, and must end in one if it cannot
    if (t.tier || t.style) {
      const good = froms.filter((s) => this.suits(t, s));
      if (good.length) froms = good;
      else if (!this.sitesOf(t.to).some((s) => this.suits(t, s))) return null;
    }
    if (near && Math.random() < 0.6) {
      const close = froms.filter((s) => Math.hypot(s.x - near.x, s.z - near.z) < 70);
      if (close.length) froms = close;
    }
    const tos = this.sitesOf(t.to);
    if (!froms.length || !tos.length) return null;
    const line = tos.some((s) => s.station) ? this.railLine?.() ?? null : null;
    // the best pair seen that did not suit the player's vehicle: the island still needs work for the CPU
    let spare: { from: Site; to: Site } | null = null;
    for (let attempt = 0; attempt < 7; attempt++) {
      const from = pick(froms);
      const dist = (s: Site) => Math.hypot(s.x - from.x, s.z - from.z);
      // at a station on the line the player's train is running: only stations further along the way it faces
      const at = from.station && line ? line.get(from.station) : undefined;
      const ahead = (s: Site) => at === undefined || (!!s.station && (line!.get(s.station) ?? -Infinity) > at + 12);
      const cut = !(t.tier || t.style) || this.suits(t, from);
      // something must be able to make the whole trip: a door only a boat reaches trades with places a boat reaches
      const carried = (s: Site) => (from.waterOnly || s.waterOnly ? boatable(from) && boatable(s) : true);
      const ok = tos.filter((s) => s !== from && (s.port < 0 || s.port !== from.port) && dist(s) >= 12 && ahead(s) && carried(s)
        && (cut || this.suits(t, s))
        && (s.w === from.w || (s.port >= 0 && from.port >= 0) || joinedByLand(s.w, from.w) || !!t.jet || !!t.sub));
      if (!ok.length) continue;
      // a jet's work goes as far as there are airports; everything else prefers a comfortable trip
      const comfy = t.jet ? ok : ok.filter((s) => dist(s) <= 120);
      const to = pick(comfy.length ? comfy : ok);
      // the fit: a load the player's vehicle could take gets a limit that vehicle can really meet, and
      // a pair it could never get to is passed over while there are attempts left to find a better one
      const fit = this.playerDef && this.playerAt ? offerable(this.playerDef, this.playerAt, from, to, t) : null;
      // (sub work is the player's alone: a trip the sub they're in can't make is never made at all)
      if (fit && !fit.ok && (attempt < 5 || t.sub)) {
        spare ??= { from, to };
        continue;
      }
      return this.make(t, from, to, fit?.urgency ?? pick(t.urgency ?? DEFAULT_URGENCY));
    }
    return spare && !t.sub ? this.make(t, spare.from, spare.to, pick(t.urgency ?? DEFAULT_URGENCY)) : null;
  }

  // ---- the demand (game/cargoDemand.ts): work made for somebody --------------------------------

  /** A carrier's spot as the fit layer reads it. */
  private placeOf(c: Carrier): Place {
    return { w: c.w, lx: c.lx, lz: c.lz, x: c.x, z: c.z, port: -1 };
  }

  /** Could this carrier take this load, wherever it is? Its hold, its order's cells, the roads, first refusal. */
  private takes(c: Carrier, it: CargoItem): boolean {
    return takesType(c, it.type) && reachesSite(c.def, it.from) && reachesSite(c.def, it.to)
      && (!it.from || inReach(c, it.from.w, it.to.w)) && !this.refused(it, c.who);
  }

  /** Is this load still waiting for anybody to take: on the ground, unclaimed, not a request's step, with time left? */
  private open(it: CargoItem): boolean {
    return !it.claimedBy && it.chain === undefined && !it.sea && it.ttl > DEMAND.minTtl;
  }

  /** Loads waiting within DEMAND.near of this carrier that it could take. */
  private supplyOf(c: Carrier): number {
    let n = 0;
    for (const it of this.items) if (this.open(it) && Math.hypot(it.x - c.x, it.z - c.z) <= DEMAND.near && this.takes(c, it)) n++;
    return n;
  }

  /** Is there a load waiting (anyone's, any kind) within DEMAND.cluster of this place? Then another there adds nothing. */
  private crowded(x: number, z: number): boolean {
    for (const it of this.items) if (!it.claimedBy && Math.hypot(it.x - x, it.z - z) < DEMAND.cluster) return true;
    return false;
  }

  /** How much work there is round a place: the sites goods come from within DEMAND.busyR (the busy grid), and loads waiting there now. */
  private busyAt(x: number, z: number): number {
    const r = Math.ceil(DEMAND.busyR / DEMAND.grid), gx = Math.floor(x / DEMAND.grid), gz = Math.floor(z / DEMAND.grid);
    let n = 0;
    for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) n += this.busyGrid.get((gx + dx) * 100003 + (gz + dz)) ?? 0;
    for (const it of this.items) if (this.open(it) && Math.hypot(it.x - x, it.z - z) <= DEMAND.busyR) n += 4;
    return n;
  }

  /**
   * The demand's turn: drop the goods nobody is near any more, then make the loads the carriers are
   * shortest of (whoever is furthest under what it wants kept near it, the player and anyone looking for
   * work first) and, with nobody short, a little ambient work for the island's own haulers.
   */
  private spawnDemand(dt: number): void {
    this.demandT -= dt;
    if (this.demandT > 0) return;
    const tick = DEMAND.tick - this.demandT;
    this.demandT = DEMAND.tick;
    if (this.focus === 'only') return;
    const cs = this.carriers!();
    this.cullFar(cs, tick);
    if (!cs.length) return;
    // (a carrier nothing can be made for this tick is passed over for the next: the player standing somewhere with no
    // work left every hired driver elsewhere with none, since the one most short always came first, docs/farfleet.html)
    const none = new Set<Carrier>();
    // one new reach flood a turn, and a few ms of looking at most (11 Nov 2026 perf audit: a turn whose spawns
    // failed walked every carrier, a fresh 60–150 ms flood for each new model or road network, 300–500 ms frames);
    // a carrier whose answer had to wait is looked at again next turn, not marked dry
    const t0 = performance.now();
    reachBudget(1);
    try {
    for (let made = 0; made < DEMAND.perTick && this.items.length < DEMAND.most; made++) {
      if (performance.now() - t0 > DEMAND_MS) break;
      let best: Carrier | null = null, bestScore = 0;
      for (const c of cs) {
        if (none.has(c)) continue;
        const short = wantOf(c) - this.supplyOf(c);
        if (short <= 0) { this.dry.delete(c.key); continue; }
        const score = short * DEMAND.weight[c.kind] * (c.looking ? 2 : 1);
        if (score > bestScore) { bestScore = score; best = c; }
      }
      if (!best) { if (!this.spawnAmbient(cs)) break; continue; }
      const it = this.spawnForCarrier(best, tick);
      if (!it && reachDeferred()) break;
      if (!it) { this.demandStats.short++; none.add(best); made--; if (none.size >= cs.length) break; continue; }
    }
    } finally { reachBudget(null); }
    // forget the shortfalls of carriers no longer about
    if (this.dry.size > cs.length * 2) {
      const keys = new Set(cs.map((c) => c.key));
      for (const k of [...this.dry.keys()]) if (!keys.has(k)) this.dry.delete(k);
    }
  }

  /** Goods waiting where no carrier is within DEMAND.far of them, for DEMAND.farGrace seconds: nobody is coming, and they go. */
  private cullFar(cs: Carrier[], tick: number): void {
    for (const it of [...this.items]) {
      if (it.claimedBy || it.chain !== undefined || it.sea || it.type.heli || it.type.jet || it.type.sub || it.longHaul || it.type.ultra) { it.far = 0; continue; }
      const near = cs.some((c) => Math.hypot(it.x - c.x, it.z - c.z) <= DEMAND.far);
      it.far = near ? 0 : (it.far ?? 0) + tick;
      if (it.far > DEMAND.farGrace) { this.unplace(it); this.demandStats.culled++; }
    }
  }

  /**
   * One load for this carrier: a kind of work it can carry (weighted by how often the kind turns up and
   * how keen its vehicle is on it), fetched from a place a short drive from it that has no load waiting
   * beside it, going somewhere its order allows that its vehicle can really reach in the time. With
   * nothing to be had near it for a few seconds, a lure: a load from as near as there is, to busier country.
   */
  private spawnForCarrier(c: Carrier, tick: number): CargoItem | null {
    const kinds = CARGO.filter((t) => takesType(c, t) && this.wanted(t) && this.countOf(t) < t.max + 2);
    const pool = kinds.map((t) => ({ v: t, w: affinity(c.def, t) / ((t.every[0] + t.every[1]) / 2) }));
    for (let attempt = 0; attempt < 5 && pool.length; attempt++) {
      const t = weighted(pool);
      if (!t) break;
      const it = this.spawnNear(t, c, false);
      if (it) { this.dry.delete(c.key); if (c.looking) c.wake?.(); return it; }
      pool.splice(pool.findIndex((e) => e.v === t), 1);
    }
    const dry = (this.dry.get(c.key) ?? 0) + tick;
    this.dry.set(c.key, dry);
    if (dry < DEMAND.dryLure) return null;
    // nothing to be had round it: a load that carries it on to where there is more
    const order = [...kinds].sort(() => Math.random() - 0.5);
    for (const t of order.slice(0, 6)) {
      const it = this.spawnNear(t, c, true);
      if (it) { this.dry.delete(c.key); if (c.looking) c.wake?.(); return it; }
    }
    return null;
  }

  /** Loads of this kind waiting now. */
  private countOf(t: CargoType): number {
    let n = 0;
    for (const it of this.items) if (it.type === t) n++;
    return n;
  }

  /**
   * A load of type t for carrier c. Near: fetched within DEMAND.near (not under its wheels, not beside
   * another load), going anywhere a comfortable trip away; homeward for a hired driver far from base.
   * A lure: fetched as near as DEMAND.lurePick allows, going to the busiest place in reach of the trip.
   */
  private spawnNear(t: CargoType, c: Carrier, lure: boolean): CargoItem | null {
    const reach = lure ? DEMAND.lurePick : DEMAND.near;
    let froms = this.sitesOf(t.from).filter((s) => {
      const d = Math.hypot(s.x - c.x, s.z - c.z);
      return d <= reach && d >= DEMAND.close && !s.waterOnly && reachesSite(c.def, s) && (!c.home || inReach(c, s.w, s.w))
        && !this.items.some((it) => it.from === s) && !this.crowded(s.x, s.z);
    });
    if (t.tier || t.style) {
      const good = froms.filter((s) => this.suits(t, s));
      if (good.length) froms = good;
      else if (!this.sitesOf(t.to).some((s) => this.suits(t, s))) return null;
    }
    if (!froms.length) return null;
    // a lure starts from the nearest of them; near work from any, the closer a little likelier
    if (lure) froms.sort((a, b) => Math.hypot(a.x - c.x, a.z - c.z) - Math.hypot(b.x - c.x, b.z - c.z));
    const tos = this.sitesOf(t.to);
    const at = this.placeOf(c);
    const homeward = !lure && c.base && Math.hypot(c.x - c.base.x, c.z - c.base.z) > DEMAND.homePull ? c.base : null;
    for (let attempt = 0; attempt < 4; attempt++) {
      const from = lure ? froms[Math.min(attempt, froms.length - 1)] : weighted(froms.map((s) => ({ v: s, w: 1 / (12 + Math.hypot(s.x - c.x, s.z - c.z)) })))!;
      const dist = (s: Site) => Math.hypot(s.x - from.x, s.z - from.z);
      const cut = !(t.tier || t.style) || this.suits(t, from);
      let ok = tos.filter((s) => s !== from && (s.port < 0 || s.port !== from.port) && dist(s) >= 12 && !s.waterOnly
        && (cut || this.suits(t, s)) && reachesSite(c.def, s) && inReach(c, from.w, s.w)
        && (s.w === from.w || (s.port >= 0 && from.port >= 0) || joinedByLand(s.w, from.w)));
      if (!ok.length) continue;
      let to: Site;
      if (lure) {
        // where there is more: the busiest destination a trip's length away, out of this carrier's patch
        ok = ok.filter((s) => dist(s) <= DEMAND.lureTrip && Math.hypot(s.x - c.x, s.z - c.z) >= DEMAND.near * 0.6);
        if (!ok.length) continue;
        const sample = ok.length > 40 ? [...ok].sort(() => Math.random() - 0.5).slice(0, 40) : ok;
        let bestBusy = -1;
        to = sample[0];
        for (const s of sample) { const b = this.busyAt(s.x, s.z); if (b > bestBusy) { bestBusy = b; to = s; } }
      } else {
        const comfy = ok.filter((s) => dist(s) <= 120);
        const pool = comfy.length ? comfy : ok;
        if (homeward) {
          // a driver far from base: a trip that ends nearer home than it starts, if there is one, and of a
          // handful of those the one that ends nearest (the 3-year check, Oct 2026: a gentler pull let the
          // fleet drift out from 150 to 250 tiles)
          const fromHome = Math.hypot(from.x - homeward.x, from.z - homeward.z);
          const back = pool.filter((q) => Math.hypot(q.x - homeward.x, q.z - homeward.z) < fromHome);
          const use = back.length ? back : pool;
          to = use[Math.floor(Math.random() * use.length)];
          for (let k = 0; k < 7; k++) {
            const q = use[Math.floor(Math.random() * use.length)];
            if (Math.hypot(q.x - homeward.x, q.z - homeward.z) < Math.hypot(to.x - homeward.x, to.z - homeward.z)) to = q;
          }
        } else to = pool[Math.floor(Math.random() * pool.length)];
      }
      // a faction the player has fallen out with makes no work for them, and its doors are shut (docs/factions.html)
      if (c.kind !== 'rival' && this.fac && !this.fac.offered(t, from, to)) continue;
      // a stronghold's loads are the player's own work (docs/strongholds.html)
      if (t.self && c.kind !== 'you') continue;
      const fit = offerable(c.def, at, from, to, t);
      if (!fit.ok) continue;
      const it = this.make(t, from, to, fit.urgency ?? pick(t.urgency ?? DEFAULT_URGENCY));
      it.for = c.kind;
      if (lure) this.demandStats.lure++; else if (homeward) this.demandStats.home++; else this.demandStats.near++;
      return it;
    }
    return null;
  }

  /**
   * With every carrier supplied: a little work for the island's own haulers, so a town still looks busy,
   * only within DEMAND.relevant of a carrier and never more than DEMAND.ambientPerCell per cell in reach.
   */
  private spawnAmbient(cs: Carrier[]): boolean {
    const live = this.islands.filter((w) => cs.some((c) => Math.hypot(c.x - (w.ox + N / 2), c.z - (w.oz + N / 2)) <= N / 2 + DEMAND.relevant));
    const quota = Math.round(DEMAND.ambientPerCell * live.length);
    let ambient = 0;
    for (const it of this.items) if (!it.for && this.open(it)) ambient++;
    if (ambient >= quota) return false;
    const kinds = CARGO.filter((t) => !t.heli && !t.jet && !t.sub && !t.sea && !t.missionOnly && this.wanted(t) && this.countOf(t) < t.max);
    const t = weighted(kinds.map((k) => ({ v: k, w: 1 / ((k.every[0] + k.every[1]) / 2) })));
    if (!t) return false;
    const c = cs[Math.floor(Math.random() * cs.length)];
    const it = this.spawn(t, { x: c.x, z: c.z }, cs);
    if (it) this.demandStats.ambient++;
    return !!it;
  }

  /** Every cell with a boat of the player's out in it keeps some harbour-to-harbour work waiting (SEA_WORK). */
  private keepSeaWork(): void {
    if (!this.seaDemand || this.items.length >= MAX_WAITING + SEA_WORK.over) return;
    for (const w of this.islands) {
      const d = this.seaDemand(w);
      if (!d || !d.boats) continue;
      const want = Math.min(SEA_WORK.most, SEA_WORK.base + SEA_WORK.perBoat * d.boats);
      const waiting = this.items.filter((it) => !it.claimedBy && it.ttl > 30 && seaLoadIn(w, it)).length;
      if (waiting < want) this.spawnSea(w, d);
    }
  }

  /**
   * One load for the boats of a cell: of a type their holds take, from one of its harbours to another
   * of its harbours at least a short sail away, each end one the boats can berth at.
   */
  spawnSea(w: World, d: SeaDemand): CargoItem | null {
    const berths = this.sites.filter((s) => s.w === w && harbourSite(s) && (d.big ? s.major : true));
    if (new Set(berths.map((s) => s.port)).size < 2) return null;
    const kinds = new Set(berths.map((s) => s.kind));
    const types = CARGO.filter((t) => !t.heli && !t.jet && !t.sub && !t.longHaul && !t.ultra && this.wanted(t) && d.holds.has(t.cls) && t.units <= d.capacity
      && t.from.some((k) => kinds.has(k)) && t.to.some((k) => kinds.has(k)));
    // the sea between two harbours, measured once (a harbour a short walk away can be a long sail round)
    // a route not yet known, with this frame's route-finding spent: the load waits for the next look
    let deferred = false;
    const leg = (a: Site, b: Site): number | null => {
      const key = `${w.cx},${w.cz}|${d.def.id}|${a.port}|${b.port}`;
      if (this.seaLegs.has(key)) return this.seaLegs.get(key)!;
      if (this.seaRoute && this.routesBusy()) { deferred = true; return null; }
      const at = this.seaBerth?.(w, d.def, a.port);
      const tiles = at && this.seaRoute ? this.seaRoute(w, d.def, at.x, at.z, b.port) : Math.hypot(b.x - a.x, b.z - a.z);
      this.seaLegs.set(key, tiles);
      return tiles;
    };
    // how far each harbour is by sea from the nearest of the boats: the near ones get the work first
    const fromBoats = new Map<number, number>();
    const byBoat = (port: number): number => {
      let best = fromBoats.get(port);
      if (best !== undefined) return best;
      best = Infinity;
      if (this.seaRoute) {
        for (const p of d.at) {
          const key = `${w.cx},${w.cz}|${d.def.id}|${port}|${Math.floor(p.x / 8)},${Math.floor(p.z / 8)}`;
          const known = this.seaNear.get(key);
          let tiles: number;
          if (known && this.time - known.at < SEA_NEAR_KEEP) tiles = known.tiles;
          else if (this.routesBusy()) { deferred = true; continue; }
          else {
            tiles = this.seaRoute(w, d.def, p.x, p.z, port) ?? Infinity;
            this.seaNear.set(key, { tiles, at: this.time });
          }
          best = Math.min(best, tiles);
        }
        if (this.seaNear.size > 2000) for (const [k, v] of this.seaNear) if (this.time - v.at >= SEA_NEAR_KEEP) this.seaNear.delete(k);
      } else best = 0;
      fromBoats.set(port, best);
      return best;
    };
    for (let attempt = 0; attempt < 6 && types.length; attempt++) {
      const t = pick(types);
      // a harbour with a van's load waiting at it can still have one for the boats, but not two for the boats
      let froms = berths.filter((s) => t.from.includes(s.kind) && !this.items.some((it) => it.sea && it.from === s));
      const near = froms.filter((s) => byBoat(s.port) <= SEA_WORK.near);
      if (near.length) froms = near;
      else froms = froms.filter((s) => byBoat(s.port) < Infinity);
      if (!froms.length) { if (deferred) return null; continue; }
      const from = pick(froms);
      // somewhere a sensible sail away: not round the far side of the island for a harbour just over the hill
      const tos = berths.filter((s) => {
        if (!t.to.includes(s.kind) || s.port === from.port) return false;
        const crow = Math.hypot(s.x - from.x, s.z - from.z);
        if (crow < 12) return false;
        const sail = leg(from, s);
        return sail !== null && sail <= SEA_WORK.longest && sail <= crow * SEA_WORK.detour + SEA_WORK.slack;
      });
      if (!tos.length) { if (deferred) return null; continue; }
      const to = pick(tos);
      // it pays for the sail, not for the crow's flight
      const it = this.make(t, from, to, pick(t.urgency ?? DEFAULT_URGENCY), leg(from, to) ?? undefined);
      it.sea = true;
      return it;
    }
    return null;
  }

  /** Put one consignment of this type on the ground, from one place to another, with this time limit. */
  private make(t: CargoType, from: Site, to: Site, u: Urgency, trip?: number): CargoItem {
    const dist = trip ?? Math.hypot(to.x - from.x, to.z - from.z);
    const span = URGENCY[u].ttl;
    const ttl = Number.isFinite(span) ? rand(t.ttl[0], t.ttl[1]) * span : Infinity;
    // a canyon ranch down its mule trail is hard to reach: what goes to or from it pays a premium (world/canyonWorks.ts)
    const mul = (this.valueMul?.(from) ?? 1) * (from.b?.remote || to.b?.remote ? REMOTE_PAY : 1);
    const value = mul === 1 ? valueOf(t, dist, u, ttl) : Math.round(valueOf(t, dist, u, ttl) * mul);
    const it: CargoItem = {
      id: this.nextId++, type: t, w: from.w, lx: from.lx, lz: from.lz,
      x: from.x, z: from.z, y: from.y, from, to, urgency: u,
      value, value0: value, ttl, life: ttl, claimedBy: 0, claimName: '', marker: null, born: this.time,
    };
    this.place(it);
    return it;
  }

  // ---- long haul (the user, 28 Oct 2026): $5,000–$19,999, five counties or more, for a jet or a train ----------

  /** Now and then, in a jet or a train: a long-haul load at an airport stand or a station near by; and the far places those waiting are bound for, once their counties are in memory. */
  private longHaulTick(dt: number, veh: Rider, def: VehicleDef): void {
    this.lhResolveT -= dt;
    if (this.lhResolveT <= 0) { this.lhResolveT = 1; this.resolveLongHaul(); }
    this.lhT -= dt;
    if (this.lhT > 0) return;
    this.lhT = rand(LONG_HAUL.every[0], LONG_HAUL.every[1]);
    if (this.focus === 'only' || this.items.filter((it) => it.longHaul).length >= LONG_HAUL.most) return;
    if (isJet(def)) this.spawnLongJet(veh, def as AirDef);
    else if (def.kind === 'rail') this.spawnLongRail(veh, def);
  }

  /** The long-haul kinds this vehicle could carry, of a jet's or a train's. */
  private longKinds(def: VehicleDef, jet: boolean): CargoType[] {
    return CARGO.filter((t) => t.longHaul && (jet ? !!t.jet : !!t.rail) && this.holdsClass(def, t.cls) && t.units <= def.capacity);
  }

  /** The stand or station nearest the vehicle, among those of these kinds within reach with no long-haul load waiting already. */
  private longFrom(kinds: SiteKind[], veh: Rider, ok: (s: Site) => boolean): Site | null {
    let best: Site | null = null, bd: number = LONG_HAUL.reach;
    for (const s of this.sitesOf(kinds)) {
      const d = Math.hypot(s.x - veh.x, s.z - veh.z);
      if (d < bd && ok(s) && !this.items.some((it) => it.longHaul && it.from === s)) { bd = d; best = s; }
    }
    return best;
  }

  /** A jet's: at an airport it can land at, for a surveyed airport it can land at five counties or more away. */
  private spawnLongJet(veh: Rider, def: AirDef): void {
    const kinds = this.longKinds(def, true);
    if (!kinds.length || !def.jet) return;
    const from = this.longFrom(['airport', 'intl'], veh, (s) => reachesSite(def, s));
    if (!from) return;
    const far = (this.farAirports?.() ?? []).filter((a) => Math.max(Math.abs(a.cx - from.w.cx), Math.abs(a.cz - from.w.cz)) >= LONG_HAUL.min && (a.major || def.jet!.runway <= 22));
    if (!far.length) return;
    const own = kinds.filter((q) => q.from.includes(from.kind));
    const a = pick(far), t = pick(own.length ? own : kinds);
    const to: Site = { id: this.farId--, kind: a.major ? 'intl' : 'airport', name: `${a.name} (${a.code})`, w: from.w, lx: a.gx - from.w.ox, lz: a.gz - from.w.oz, x: a.gx, z: a.gz, y: a.y, port: -1, major: a.major };
    this.makeLongHaul(t, from, to, [a.cx, a.cz]);
  }

  /** A train's: at a station on a line, for a station five counties or more down that line (world/rail.ts, nothing generated). */
  private spawnLongRail(veh: Rider, def: VehicleDef): void {
    const kinds = this.longKinds(def, false);
    if (!kinds.length) return;
    const from = this.longFrom([...new Set(kinds.flatMap((t) => t.from))], veh, (s) => !!s.station);
    if (!from) return;
    const own = kinds.filter((t) => t.from.includes(from.kind));
    if (!own.length) return;
    const t = pick(own);
    const sh = hashString(from.w.seed);
    const dests: StationRef[] = [];
    for (const line of railLines(sh, from.w.cx, from.w.cz)) {
      for (const d of line.sides) {
        for (const st of stationsAlong(sh, from.w.cx, from.w.cz, d, LONG_HAUL.railCells)) {
          if (!t.to.includes(st.kind) || Math.max(Math.abs(st.cx - from.w.cx), Math.abs(st.cz - from.w.cz)) < LONG_HAUL.min) continue;
          if (!dests.some((q) => q.cx === st.cx && q.cz === st.cz)) dests.push(st);
        }
      }
    }
    if (!dests.length) return;
    const st = pick(dests);
    // the middle of its county until that county is in memory and the station itself can be found (resolveLongHaul)
    const x = (st.cx + 0.5) * N, z = (st.cz + 0.5) * N;
    const to: Site = { id: this.farId--, kind: st.kind, name: st.name, w: from.w, lx: x - from.w.ox, lz: z - from.w.oz, x, z, y: from.y, port: -1, major: false };
    this.makeLongHaul(t, from, to, [st.cx, st.cz]);
  }

  /** A long-haul load waiting at `from`, for `to` in county `cell`: its value set by how many counties off that is. */
  private makeLongHaul(t: CargoType, from: Site, to: Site, cell: [number, number]): CargoItem {
    const cells = Math.max(Math.abs(cell[0] - from.w.cx), Math.abs(cell[1] - from.w.cz));
    const value = Math.min(LONG_HAUL.top, Math.round((LONG_HAUL.base + (cells - LONG_HAUL.min) * LONG_HAUL.perCell + rand(0, LONG_HAUL.spread)) / 10) * 10);
    const it: CargoItem = {
      id: this.nextId++, type: t, w: from.w, lx: from.lx, lz: from.lz, x: from.x, z: from.z, y: from.y, from, to, urgency: 'none',
      value, value0: value, ttl: LONG_HAUL.ttl, life: LONG_HAUL.ttl, claimedBy: 0, claimName: '', marker: null, born: this.time,
      longHaul: { cell, cells },
    };
    this.place(it);
    return it;
  }

  /** Long-haul loads bound for a county now in memory: pointed at the real airport or station there. */
  private resolveLongHaul(): void {
    for (const it of [...this.items, ...this.hold]) {
      const lh = it.longHaul;
      if (!lh || lh.done) continue;
      const w = this.islands.find((q) => q.cx === lh.cell[0] && q.cz === lh.cell[1]);
      if (!w) continue;
      const kinds: SiteKind[] = it.type.jet ? ['airport', 'intl'] : [it.to.kind];
      let best: Site | null = null, bd = Infinity;
      for (const s of this.sitesOf(kinds)) {
        if (s.w !== w || (it.type.jet && it.to.major && !s.major)) continue;
        // a station by its name first, then whatever of the kind is nearest where it was thought to be
        const d = (s.name === it.to.name ? 0 : 1e6) + Math.hypot(s.x - it.to.x, s.z - it.to.z);
        if (d < bd) { bd = d; best = s; }
      }
      if (!best) continue;
      it.to = best;
      lh.done = true;
      if (it.marker && this.items.includes(it)) aimCargoMarker(it.marker, it.to.x - it.x, it.to.z - it.z);
    }
  }

  // ---- Ultra-Bulk (the user, 28 Oct 2026): 50–100 units for Big Blue, the big freight trains and the Jumbo ------

  /** Now and then, in a ride Ultra-Bulk work is for: a load it can take, near it, bound somewhere it can really drop it. */
  private ultraTick(dt: number, veh: Rider, def: VehicleDef): void {
    this.ubT -= dt;
    if (this.ubT > 0) return;
    this.ubT = rand(ULTRA_BULK.every[0], ULTRA_BULK.every[1]);
    if (this.focus === 'only' || !this.home) return;
    const kinds = CARGO.filter((t) => t.ultra?.rides.includes(def.id) && this.holdsClass(def, t.cls) && t.units <= this.capacityFor(def));
    if (!kinds.length || this.items.filter((it) => it.type.ultra?.rides.includes(def.id)).length >= ULTRA_BULK.most) return;
    // (a route not measured yet, with this frame's route-finding spent: another look soon)
    if (!this.spawnUltra(pick(kinds), veh, def)) this.ubT = Math.min(this.ubT, 6);
  }

  /** One Ultra-Bulk load of type t for the player's ride: from a place it loads at near it, to one it can reach. */
  spawnUltra(t: CargoType, veh: Rider, def: VehicleDef): CargoItem | null {
    const u = t.ultra;
    if (!u) return null;
    const near = (s: Site) => Math.hypot(s.x - veh.x, s.z - veh.z) <= ULTRA_BULK.reach;
    // (a harbour, stand or yard with ordinary work waiting can still have Ultra-Bulk, but not two of it)
    const free = (s: Site) => !this.items.some((it) => it.from === s && it.type.ultra);
    let from: Site | null = null, to: Site | null = null, trip = 0;
    if (def.kind === 'water') {
      // harbour to harbour in the cell the ship is in, each a berth it fits, both a sail it can make: the sails
      // measured once and kept (the same keys as the boats' harbour work), a few new ones a look at most
      const w = this.home!;
      if (!this.seaRoute) return null;
      let budget = 3;
      const sail = (key: string, x: number, z: number, port: number): number | null | undefined => {
        if (this.seaLegs.has(key)) return this.seaLegs.get(key)!;
        if (budget <= 0 || this.routesBusy()) return undefined;
        budget--;
        const tiles = this.seaRoute!(w, def, x, z, port);
        this.seaLegs.set(key, tiles);
        return tiles;
      };
      const sx = veh.x - w.ox, sz = veh.z - w.oz;
      const berths = this.sitesOf(u.from).filter((s) => s.w === w && harbourSite(s) && reachesSite(def, s) && near(s) && free(s));
      for (const f of berths.sort(() => Math.random() - 0.5).slice(0, 3)) {
        // from the ship's 8-tile square to the pick-up
        if (!sail(`${w.cx},${w.cz}|${def.id}|${f.port}|${Math.floor(sx / 8)},${Math.floor(sz / 8)}`, sx, sz, f.port)) continue;
        const at = this.seaBerth?.(w, def, f.port);
        if (!at) continue;
        const tos = this.sitesOf(u.to).filter((s) => s.w === w && harbourSite(s) && reachesSite(def, s) && s.port !== f.port);
        for (const s of tos.sort(() => Math.random() - 0.5)) {
          const leg = sail(`${w.cx},${w.cz}|${def.id}|${f.port}|${s.port}`, at.x, at.z, s.port);
          if (leg && leg >= ULTRA_BULK.minTrip) { from = f; to = s; trip = leg; break; }
        }
        if (from) break;
      }
    } else if (def.kind === 'rail') {
      // station to station along the line the train is on, the drop further down it than the pick-up
      const line = this.railLine?.();
      if (!line) return null;
      const along = (s: Site) => (s.station ? line.get(s.station) : undefined);
      const froms = this.sitesOf(u.from).filter((s) => { const d = along(s); return d !== undefined && d >= -8 && near(s) && free(s); });
      for (const f of froms.sort(() => Math.random() - 0.5).slice(0, 4)) {
        const at = along(f)!;
        const tos = this.sitesOf(u.to).filter((s) => { const d = along(s); return s !== f && d !== undefined && d - at >= ULTRA_BULK.minTrip; });
        if (!tos.length) continue;
        from = f; to = pick(tos); trip = along(to)! - at;
        break;
      }
    } else if (isJet(def)) {
      // an international's stand to another international, or out over the horizon from this one
      const froms = this.sitesOf(u.from).filter((s) => reachesSite(def, s) && near(s) && free(s));
      if (froms.length) {
        const f = pick(froms);
        const tos = this.sitesOf(u.to).filter((s) => reachesSite(def, s) && (s.kind === 'overseas' ? s.w === f.w : Math.hypot(s.x - f.x, s.z - f.z) >= ULTRA_BULK.minTrip + 20));
        if (tos.length) { from = f; to = pick(tos); trip = Math.hypot(to.x - f.x, to.z - f.z); }
      }
    }
    if (!from || !to) return null;
    const value = Math.min(ULTRA_BULK.top, Math.round((t.units * (ULTRA_BULK.perUnit + ULTRA_BULK.perUnitTile * Math.min(trip, ULTRA_BULK.tripCap))) / 10) * 10);
    const it: CargoItem = {
      id: this.nextId++, type: t, w: from.w, lx: from.lx, lz: from.lz, x: from.x, z: from.z, y: from.y, from, to, urgency: 'none',
      value, value0: value, ttl: ULTRA_BULK.ttl, life: ULTRA_BULK.ttl, claimedBy: 0, claimName: '', marker: null, born: this.time,
    };
    this.place(it);
    return it;
  }

  /**
   * One step of a town's request (or a mission's load): the goods it asks for, held for the player so they never
   * expire and no hired driver takes them, marked in mission yellow with the chain's own colour as a badge so
   * they read as a chain on the ground (docs/cargolook.html).
   */
  spawnFor(t: CargoType, from: Site, to: Site, value: number, chain: number, colour: number): CargoItem | null {
    if (!this.islands.length) return null;
    const it = this.make(t, from, to, 'none');
    it.value = value;
    it.value0 = value;
    it.ttl = Infinity;
    it.life = Infinity;
    it.chain = chain;
    it.chainColour = colour;
    it.claimedBy = CHAIN_CLAIM;
    it.claimName = 'yours';
    // the marker is rebuilt in mission yellow, with the chain's colour as its badge
    this.remark(it);
    return it;
  }

  /** A chain has been given up or has lapsed: its goods go back to being anybody's, and expire as usual. */
  unchain(it: CargoItem): void {
    it.chain = undefined;
    it.chainColour = undefined;
    it.claimedBy = 0;
    it.claimName = '';
    it.ttl = Math.min(it.ttl, 120);
    it.life = Math.max(it.life === Infinity ? 120 : it.life, it.ttl);
    if (this.hold.includes(it)) return;
    this.remark(it);
  }

  // ---- supply chains (docs/supplychains.html): what the player's plants put at their kerbs -------------------

  /** A building's own cargo site, while its island is in memory. */
  siteOfBuilding(b: Building): Site | null { return this.byBuilding.get(b) ?? null; }

  /**
   * A plant's made load at its kerb, held for the player's fleet (`for: 'you'`, no time limit until its plant opens
   * it). Bound for, in order: the nearest plant of the fleet's that takes it in, the nearest other door of the
   * fleet's that wants it, or any place a comfortable trip away that wants it (`own` ranks a site 3, 2 or 0). Its
   * worth is the kind's (a re-based one's when made, game/chains/made.ts) at the trip, times its pedigree.
   */
  produce(from: Site, t: CargoType, made: { key: string; steps: number; scale: number }, own: (s: Site) => number): CargoItem | null {
    if (!this.islands.length) return null;
    const kinds = new Set<SiteKind>(t.to);
    for (const [kind, rs] of recipeBook()) if (rs.some((r) => r.takes.some((s) => s.ids.includes(t.id)))) kinds.add(kind as SiteKind);
    const dist = (s: Site) => Math.hypot(s.x - from.x, s.z - from.z);
    const ok = this.sitesOf([...kinds]).filter((s) => s !== from && (s.port < 0 || s.port !== from.port) && dist(s) >= 8 && !s.seabed
      && (from.waterOnly || s.waterOnly ? boatable(from) && boatable(s) : true)
      && (s.w === from.w || (s.port >= 0 && from.port >= 0) || joinedByLand(s.w, from.w)));
    // ready-mix, panels and asphalt are wanted most by a building going up (docs/supplychains.html, chain 5): a site
    // under its cranes takes them at its gate while it stands; fireworks by a show on now (chain 19)
    let to: Site | null = null;
    let crowd = 1;
    if (SITE_GOODS.has(t.id)) {
      const near = this.buildingSites().filter((s) => dist(s) >= 8 && dist(s) <= 140 && (s.w === from.w || joinedByLand(s.w, from.w)));
      if (near.length) to = near.reduce((a, b) => (dist(b) < dist(a) ? b : a));
    } else if (t.id === 'fireworks') {
      const on = (this.liveEvents?.() ?? []).filter((e) => e.now && Math.hypot(e.x - from.x, e.z - from.z) <= 140);
      const w = on.length ? this.islands.find((q) => on[0].x >= q.ox && on[0].x < q.ox + N && on[0].z >= q.oz && on[0].z < q.oz + N) : null;
      if (on.length && w) {
        to = { id: -4_000_000 - this.nextId, kind: 'plaza', name: `${on[0].name} (on now)`, w, lx: on[0].x - w.ox, lz: on[0].z - w.oz, x: on[0].x, z: on[0].z, y: surfaceY(w, on[0].x - w.ox, on[0].z - w.oz), port: -1, major: false };
        crowd = EVENT_PAY;
      }
    }
    if (!to && !ok.length) return null;
    // the fleet's own doors first, nearest first, within a long drive; else anybody's, a comfortable trip away
    for (const rank of [3, 2]) {
      if (to) break;
      const mine = ok.filter((s) => own(s) === rank && dist(s) <= 200 && (t.to.includes(s.kind) || rank === 3));
      if (mine.length) { to = mine.reduce((a, b) => (dist(b) < dist(a) ? b : a)); break; }
    }
    if (!to) {
      const wanted = ok.filter((s) => t.to.includes(s.kind));
      if (!wanted.length) return null;
      const comfy = wanted.filter((s) => dist(s) <= 120);
      const pool = comfy.length ? comfy : wanted;
      to = pool[Math.floor(Math.random() * pool.length)];
    }
    const u = (t.urgency ?? DEFAULT_URGENCY)[Math.floor(Math.random() * (t.urgency ?? DEFAULT_URGENCY).length)];
    const figures = MADE_FIGURES[t.id];
    const priced = figures ? { ...t, ...figures } : t;
    const nominal = Number.isFinite(URGENCY[u].ttl) ? rand(t.ttl[0], t.ttl[1]) * URGENCY[u].ttl : Infinity;
    // the ladder (game/chains/value.ts): worth what went into it and more, times its pedigree, never a gold load's worth
    const value = Math.min(MADE_TOP, Math.max(5, Math.round((valueOf(priced, dist(to), u, nominal) * made.scale * pedigreeMul(made.steps) * crowd) / 5) * 5));
    const it = this.make(t, from, to, u);
    it.value = value;
    it.value0 = value;
    it.ttl = Infinity;
    it.life = Infinity;
    it.for = 'you';
    it.made = { key: made.key, steps: made.steps };
    return it;
  }

  /**
   * A building the Dozer knocked down leaves rubble (docs/supplychains.html, chain 5): `n` loads on its plot, held for
   * the player a good while, bound for the nearest recycling centre or crusher by land. Returns how many were put out.
   */
  dropRubble(w: World, lx: number, lz: number, n: number): number {
    const t = cargoById('rubble');
    if (!t || !this.islands.includes(w)) return 0;
    const x = w.ox + lx, z = w.oz + lz;
    const tos = this.sitesOf(['recyclingCentre', 'crusher']).filter((s) => s.w === w || joinedByLand(s.w, w));
    if (!tos.length) return 0;
    const to = tos.reduce((a, b) => (Math.hypot(b.x - x, b.z - z) < Math.hypot(a.x - x, a.z - z) ? b : a));
    let put = 0;
    for (let k = 0; k < n; k++) {
      const ox = lx + (k - (n - 1) / 2) * 0.6;
      const at: Site = { id: -3_000_000 - this.nextId, kind: 'landmark', name: 'Rubble', w, lx: ox, lz, x: w.ox + ox, z, y: surfaceY(w, ox, lz), port: -1, major: false };
      const it = this.make(t, at, to, 'relaxed');
      it.for = 'you';
      it.ttl = it.life = 600;
      put++;
    }
    return put;
  }

  /** What's on now near the camera (game/events/stage.ts listing), for fireworks: set by main.ts. */
  liveEvents: (() => { x: number; z: number; name: string; now: boolean }[]) | null = null;

  /**
   * Every building going up on an island in memory (a town's growth or the fleet's blueprints, render/construction.ts),
   * as a door at its gate for the goods a site takes (SITE_GOODS): not in `sites`, made fresh when asked.
   */
  buildingSites(): Site[] {
    const out: Site[] = [];
    for (const w of this.islands) for (const b of w.allBuildings) {
      if (!b || b.gone || b.grownAt === undefined || builtShare(b) >= 1) continue;
      const p = anchor(w, b);
      if (!p) continue;
      out.push({ id: -5_000_000 - b.uid, kind: b.kind, name: `Building site · ${siteName(w, b)}`, w, lx: p.x, lz: p.z, x: p.x + w.ox, z: p.z + w.oz, y: surfaceY(w, p.x, p.z), port: -1, major: false, b });
    }
    return out;
  }

  /** Where a load is now: waiting on the ground, aboard somebody, or gone (delivered, expired, its island away). */
  whereIs(id: number): 'ground' | 'aboard' | 'gone' {
    if (this.items.some((it) => it.id === id)) return 'ground';
    if (this.hold.some((it) => it.id === id)) return 'aboard';
    for (const it of this.carried) if (it.id === id) return 'aboard';
    return 'gone';
  }

  /**
   * A load a fetcher has claimed for one of the fleet's plants (docs/supplychains.html): bound for the plant's door
   * now, its worth scaled to the new trip (the island's own loads are abstract: nobody at the old door is waiting).
   */
  repoint(it: CargoItem, to: Site): void {
    const from = it.from ?? { x: it.x, z: it.z };
    const was = Math.hypot(it.to.x - from.x, it.to.z - from.z), now = Math.hypot(to.x - from.x, to.z - from.z);
    const ratio = valueOf(it.type, now, it.urgency, it.life) / Math.max(1, valueOf(it.type, was, it.urgency, it.life));
    it.to = to;
    it.value = Math.max(5, Math.round((it.value * ratio) / 5) * 5);
    it.value0 = Math.max(5, Math.round((it.value0 * ratio) / 5) * 5);
    if (it.marker) aimCargoMarker(it.marker, to.x - it.x, to.z - it.z);
  }

  /** A made load its plant no longer holds for the fleet: anybody's now, with an ordinary while to wait. */
  openMade(id: number, ttl: number): void {
    const it = this.items.find((q) => q.id === id);
    if (!it || !it.for) return;
    it.for = undefined;
    it.ttl = ttl;
    it.life = ttl;
  }

  /**
   * Cultural goods waiting where they were found (game/culture.ts): held for the player like a request's step,
   * with no time limit, in culture's royal violet, going to the HQ (`to`, kept up to date by the host).
   */
  spawnCulture(t: CargoType, id: number, from: { w: World; lx: number; lz: number; y: number; name: string }, to: Site, value: number): CargoItem {
    const site: Site = { id: -2_000_000 - id, kind: 'landmark', name: from.name, w: from.w, lx: from.lx, lz: from.lz, x: from.w.ox + from.lx, z: from.w.oz + from.lz, y: from.y, port: -1, major: false };
    const it: CargoItem = {
      id: this.nextId++, type: t, w: from.w, lx: from.lx, lz: from.lz, x: site.x, z: site.z, y: from.y,
      from: site, to, urgency: 'none', value, value0: value, ttl: Infinity, life: Infinity,
      claimedBy: CHAIN_CLAIM, claimName: 'yours', marker: null, born: this.time, culture: id,
    };
    this.place(it);
    return it;
  }

  /** Cultural goods already aboard when a game is loaded: back in the hold as they were. */
  cultureAboard(t: CargoType, id: number, from: { w: World; x: number; z: number; y: number; name: string }, to: Site, value: number): CargoItem {
    const site: Site = { id: -2_000_000 - id, kind: 'landmark', name: from.name, w: from.w, lx: from.x - from.w.ox, lz: from.z - from.w.oz, x: from.x, z: from.z, y: from.y, port: -1, major: false };
    const it: CargoItem = {
      id: this.nextId++, type: t, w: from.w, lx: site.lx, lz: site.lz, x: from.x, z: from.z, y: from.y,
      from: site, to, urgency: 'none', value, value0: value, ttl: Infinity, life: Infinity,
      claimedBy: 0, claimName: '', marker: null, culture: id,
    };
    this.hold.push(it);
    this.refreshInventory();
    return it;
  }

  /** Take goods off the ground for good, without a word (cultural goods whose home town has changed). */
  removeItem(it: CargoItem): void {
    this.unplace(it);
    const k = this.hold.indexOf(it);
    if (k >= 0) { this.hold.splice(k, 1); this.refreshInventory(); }
  }

  /**
   * A hired driver has been called away and has set a load down at the kerb (game/convoy.ts). It is
   * nobody's fault and nobody's fine: the goods stand where they were left and go back on the market
   * for whoever wants them next, with a reasonable while to wait.
   */
  setDown(it: CargoItem, w: World, lx: number, lz: number, y: number): void {
    this.carried.delete(it);
    if (this.items.includes(it)) return;
    it.w = w; it.lx = lx; it.lz = lz;
    it.x = w.ox + lx; it.z = w.oz + lz; it.y = y;
    it.from = null;
    it.claimedBy = 0;
    it.claimName = '';
    it.ttl = Math.min(it.ttl, SET_DOWN_TTL);
    it.life = Math.max(it.life === Infinity ? SET_DOWN_TTL : it.life, it.ttl);
    if (it.marker) { disposeCargoMarker(it.marker); it.marker = null; }
    this.place(it);
  }

  /** Goods left by the roadside move to wherever the vehicle dropped them. */
  private place(it: CargoItem): void {

    this.remark(it);
    this.items.push(it);
  }

  /**
   * A load's look now (game/cargoLook.ts): mission yellow, culture violet, the colour of the faction it would
   * please most, or white. The dull grey for what the vehicle can't carry is the marker's own, frame by frame.
   */
  private lookOf(it: CargoItem): ReturnType<typeof cargoLook> {
    const plain = it.chainColour === undefined && it.culture === undefined;
    return cargoLook({ chainColour: it.chainColour, culture: it.culture !== undefined, longHaul: !!it.longHaul, ultra: !!it.type.ultra, favours: plain && !it.longHaul && !it.type.ultra ? this.fac?.favours(it) ?? null : null });
  }

  /** Build (or build again) a waiting load's marker in its look, pointing its arrow at the drop. */
  private remark(it: CargoItem): void {
    if (it.marker) { disposeCargoMarker(it.marker); it.marker = null; }
    const look = this.lookOf(it);
    it.look = look;
    it.marker = buildCargoMarker(look, it.type.cls, false, it.culture !== undefined ? goodModelId(it.type.name) : it.type.id);
    aimCargoMarker(it.marker, it.to.x - it.x, it.to.z - it.z);
    it.marker.group.position.set(it.x, it.y + 0.04, it.z);
    this.group.add(it.marker.group);
  }

  /** The colour a load's price tag is printed in: its look's, readable (a dark faction's rim). */
  private inkOf(it: CargoItem): string {
    const l = it.look;
    const c = !l ? it.type.color : l.faction ? factionInk(l.faction) : l.badge !== undefined ? MISSION_YELLOW : l.key === 'c' ? CULTURE_VIOLET : l.key === 'L' ? LONG_HAUL_GOLD : l.key === 'U' ? ULTRA_LIME : NO_FACTION_WHITE;
    return `#${c.toString(16).padStart(6, '0')}`;
  }

  /**
   * A faction's own vehicle has called by (game/factions/factionTraffic.ts): one load of its own kind waiting
   * within `r` of (x, z), made for nobody in particular and claimed by nobody, is taken away as the island's
   * trade. Returns it, or null.
   */
  takeFor(test: (it: CargoItem) => boolean, x: number, z: number, r: number): CargoItem | null {
    const it = this.items.find((q) => !q.for && !q.claimedBy && q.chain === undefined && !q.longHaul && !q.type.ultra && Math.hypot(q.x - x, q.z - z) <= r && test(q));
    if (!it) return null;
    this.unplace(it);
    this.cpuDelivered++;
    this.books?.delivered(it, false, 0);
    return it;
  }

  private unplace(it: CargoItem): void {
    const k = this.items.indexOf(it);
    if (k >= 0) this.items.splice(k, 1);
    if (it.marker) { disposeCargoMarker(it.marker); it.marker = null; }
    if (this.hovered === it) this.hovered = null;
  }

  /** Hold space taken by something that isn't cargo: a night run's contraband (game/smuggling.ts). */
  extraUnits = 0;
  /** Hold space taken by a rush's goods (game/rushes, docs/rushes.html): they ride outside the cargo list. */
  rushUnits = 0;
  /** The last frame's step, for markers that ease in and out. */
  private frameDt = 1 / 60;
  /** The card for what `extraUnits` is (the night run's contraband, game/smuggling.ts), for the cargo list. */
  extraRow: (() => ExtraRow | null) | null = null;
  /**
   * Cultural goods (game/culture.ts, docs/passport.html) are ordinary loads with `culture` set; the culture
   * system answers for them. `cultureWhy` adds its one rule to the load verdict (five units a vehicle),
   * `cultureTip` is the line on the hover card, `onCulture` hears of a delivery at the HQ (after the usual pay)
   * and `onCultureDropped` of a load left behind, which goes back to where it was found.
   */
  cultureWhy: ((it: CargoItem) => string | null) | null = null;
  cultureTip: ((it: CargoItem) => string) | null = null;
  /** Why a load can't be handed in where it has arrived (a consignment at a hall whose town is not ready for it, docs/culturegate.html), or null. */
  cultureDue: ((it: CargoItem) => string | null) | null = null;
  onCulture: ((items: CargoItem[], paid: number) => void) | null = null;
  onCultureDropped: ((it: CargoItem) => void) | null = null;
  /** Whether cultural goods can be handed over now: false while the HQ's home town isn't known. */
  cultureOpen: (() => boolean) | null = null;
  /** What goods put out at this place are worth just now, as a multiplier: a town in festival (game/culture.ts). */
  valueMul: ((from: Site) => number) | null = null;
  /**
   * The hold lent by the vehicles in formation behind you (game/formation.ts), rewritten every frame
   * by its owner: their units, the classes between them, and their names. A load rides with the
   * formation, so what you can pick up is your own vehicle and everything holding station with it.
   */
  formation: { units: number; classes: CargoClass[]; names: string[] } = { units: 0, classes: [], names: [] };

  /** What the vehicle you drive can take, with the formation behind it. */
  capacityFor(def: VehicleDef): number { return def.capacity + this.formation.units; }
  /** Is this a kind of goods you or one of the vehicles with you can carry? */
  private holdsClass(def: VehicleDef, c: CargoClass): boolean {
    return def.holds.includes(c) || this.formation.classes.includes(c);
  }
  /**
   * Bounties another system wants drawn with the rest, rewritten by its owner each frame: the night
   * runs' contacts and buyers (game/smuggling.ts). Keys live above GOODS_TAG's range.
   */
  extraTags: CargoTag[] = [];
  /** The same for a second owner: lit bookmarks (docs/passport.html). */
  moreTags: CargoTag[] = [];

  used(): number { return this.hold.reduce((s, it) => s + it.type.units, 0) + this.extraUnits + this.rushUnits; }

  // ---- the player ----

  /**
   * One frame: new goods turn up and old ones expire, markers pulse (their rings drawn at this
   * vehicle's reach), deliveries happen when the vehicle stops at a destination, and the HUD follows.
   * `mouse` is the pointer when it may hover goods; `live` is false while the game is paused.
   */
  update(dt: number, veh: Rider, def: VehicleDef, camera: THREE.Camera, yaw: number, mouse: { x: number; y: number } | null, live: boolean, overview = false): void {
    if (!this.islands.length) return;
    this.time += dt;
    this.frameDt = dt;
    this.frame++;
    // what the fit layer measures every new load against: the vehicle in the player's hands, and where it stands
    this.playerDef = def;
    this.flyingHeli = isHelicopter(def);
    this.inSub = def.kind === 'water' && !!def.dive;
    this.flyingJet = isJet(def);
    this.onRails = def.kind === 'rail';
    this.playerAt = this.home
      ? { w: this.home, lx: veh.x - this.home.ox, lz: veh.z - this.home.oz, x: veh.x, z: veh.z, port: -1 }
      : null;
    if (dt > 0) {
      // the demand writes the road work for whoever is about; a train or a boat in the player's hands still
      // gets the old timers' station and harbour work besides (its stops are not anywhere a van goes)
      if (this.carriers) { const t0 = performance.now(); this.spawnDemand(dt); jobNote('cargo demand', performance.now() - t0, t0); }
      if (!this.carriers || def.kind === 'rail' || def.kind === 'water') for (const t of CARGO) {
        const left = (this.timers.get(t.id) ?? 0) - dt;
        if (left > 0) { this.timers.set(t.id, left); continue; }
        // the wait until the next one is cut by how keen this work's takers are (game/affinity.ts): mostly
        // the vehicle in the player's hands, and partly the keenest model out on the island — so a
        // limousine's island fills with weddings, a tipper's with gravel, and a fleet of buses with outings
        const keen = 0.7 * affinity(def, t) + 0.3 * keenestOf(this.models(), t);
        this.timers.set(t.id, rand(t.every[0], t.every[1]) / keen);
        // helicopter work turns up only while the player is flying one
        if (t.heli && !this.flyingHeli) continue;
        if (t.jet && !this.flyingJet) continue;
        if (t.sub && !this.inSub) continue;
        // work written for one model waits for one of them to be on the island (the player's or anybody's)
        if (!this.wanted(t)) continue;
        // in the first drive nothing turns up but its own goods
        if (this.focus === 'only') continue;
        // near the player, or near one of their drivers out working: goods turn up where the fleet is too
        if (this.items.filter((it) => it.type === t).length < t.max) {
          const crew = this.fleetAt?.() ?? [];
          this.spawn(t, crew.length && Math.random() < crew.length / (crew.length + 1.5) ? crew[Math.floor(Math.random() * crew.length)] : veh);
        }
      }
      this.seaT -= dt;
      if (this.seaT <= 0 && this.focus !== 'only') {
        this.seaT = SEA_WORK.every;
        this.keepSeaWork();
      }
      this.longHaulTick(dt, veh, def);
      this.ultraTick(dt, veh, def);
      for (const it of [...this.items]) {
        if (it.claimedBy) {
          // held for the CPU vehicle on its way, or for the player as a chain's step
          if (it.claimUntil === undefined) continue;
          // in a driver's manifest: a quarter of the clock, and the claim lapses when its deadline passes
          it.ttl -= dt * CLAIM_RATE;
          if (this.time > it.claimUntil) this.release(it, it.claimedBy);
        } else it.ttl -= dt;
        if (it.ttl <= 0) {
          // a plant's made load was never the town's to lose: its plant counts it instead
          if (it.made) this.onMadeGone?.(it);
          else this.books?.expired(it);
          this.unplace(it);
        }
      }
      // a load aboard is worth a little less every second, the more so the tighter its limit
      // an ambulance's siren keeps the clocks from biting as hard
      const slow = 1 - (def.siren ?? 0);
      for (const it of this.hold) {
        // a cold box keeps the ice cream from melting (docs/supplychains.html)
        const rate = URGENCY[it.urgency].decay * slow * (def.coldHold && COLD_GOODS.has(it.type.id) ? 1 - def.coldHold : 1);
        if (rate) it.value = Math.max(it.value0 * VALUE_FLOOR, it.value - it.value0 * rate * dt);
        // people in a convertible: how much of the ride was under an open sky
        if (def.convertible && it.type.cls === 'people') {
          it.ride ??= { t: 0, down: 0 };
          it.ride.t += dt;
          if (!roofUp()) it.ride.down += dt;
        }
      }
      // and so is a load in anybody else's
      for (const it of this.carried) {
        if (this.hold.includes(it) || this.items.includes(it)) { this.carried.delete(it); continue; }
        const rate = URGENCY[it.urgency].decay;
        if (rate) it.value = Math.max(it.value0 * VALUE_FLOOR, it.value - it.value0 * rate * dt);
      }
    }

    const reach = reachOf(def);
    // a standing moved (a rung crossed, a bar full): the loads it changes are coloured again
    const rev = this.fac?.version() ?? 0;
    if (rev !== this.lookRev) {
      this.lookRev = rev;
      for (const it of this.items) if (it.marker && it.look?.key !== this.lookOf(it).key) this.remark(it);
    }
    for (const it of this.items) {
      // helicopter work stays out of sight until the player is in a helicopter
      it.marker!.group.visible = this.shown(it);
      setCargoMarkerGrey(it.marker!, !carries(def, it.type));
      const alpha = it.ttl < BLINK && !it.claimedBy ? 0.35 + 0.65 * (0.5 + 0.5 * Math.cos(this.time * (8 + (BLINK - it.ttl) * 0.6))) : 1;
      poseCargoMarker(it.marker!, this.time, ringOf(def, reach, !!it.type.rail || !!it.from?.station), alpha * (this.faded(it) ? DIM : 1));
    }

    if (live) this.deliver(veh, def);
    this.solveDrops(veh, def, dt);
    this.syncDestinations(reach, def);
    const door = this.syncDoors(veh, def, ringOf(def, reach, false), yaw);

    const pos = this.v.set(veh.x, veh.y, veh.z);
    this.lastVeh.copy(pos);
    this.hud.setCash(this.wallet.cash, this.wallet.lastSource);
    this.hud.setHold(this.used(), this.capacityFor(def));
    // bounties: green over the destinations of what's aboard, and in its look's colour over goods waiting nearby
    const tags = [...this.dests.values()].map((d) => {
      // with drops in more than one place, each tag carries its number in the suggested order
      const it = this.hold.find((h) => h.to.id === d.site.id);
      const n = it ? this.dropOrder.get(it.id) : undefined;
      const dim = this.focus === 'dim' && !this.hold.some((h) => h.to.id === d.site.id && h.chain !== undefined);
      return { key: d.site.id, text: n ? `${nth(n)} ${money(d.value)}` : money(d.value), pos: new THREE.Vector3(d.site.x, d.site.y + 0.9, d.site.z), dim, n, value: d.value } as CargoTag;
    });
    // from the overview a bounty over every load is unreadable; the towns carry the summary instead
    if (!overview) {
      for (const it of this.items) {
        if (!this.shown(it) || Math.hypot(it.x - veh.x, it.z - veh.z) > TAG_RANGE) continue;
        const marks = it.look ? tagMarks(it.look) : { pre: '', post: '' };
        tags.push({
          key: GOODS_TAG + it.id, text: `${it.type.ultra ? 'ULTRA ' : ''}${marks.pre}${money(it.value)}${marks.post}`, pos: new THREE.Vector3(it.x, it.y + 0.85, it.z),
          goods: true, color: carries(def, it.type) ? this.inkOf(it) : GREY_TAG, dim: this.faded(it),
        } as (typeof tags)[number]);
      }
    }
    tags.push(...this.extraTags, ...this.moreTags);
    this.hud.updateTags(tags, camera, yaw, pos, this.time);
    this.hud.updateFloats(dt, camera);

    // hover card
    this.hovered = mouse ? this.itemAt(mouse.x, mouse.y, camera) : null;
    if (this.hovered && mouse) this.hud.showTip(`${this.hovered.id}|${Math.ceil(this.hovered.ttl)}|${this.used()}|${def.id}|${this.verdict(this.hovered, veh, def).text}`, this.tipHtml(this.hovered, veh, def), mouse.x, mouse.y);
    else this.hud.hideTip();

    // "Space to go in" at a door; else "Space to load" for the nearest goods in reach
    const near = this.nearest(veh, reach);
    if (door && live) {
      this.hud.setPrompt(this.stoppedFor(veh, def)
        ? `<kbd>Space</kbd> go into <span class="ic">${door.icon}</span> <b>${esc(door.name)}</b>`
        : `<span class="ic">${door.icon}</span> <span class="no">Stop in the ring to go in</span>`);
    } else if (near && live) {
      const vd = this.verdict(near, veh, def);
      this.hud.setPrompt(vd.kind === 'ok'
        ? `<kbd>Space</kbd> load <span class="ic">${near.type.icon}</span> <b>${esc(near.type.name)}</b> <em>${money(near.value)}</em>`
        : `<span class="ic">${near.type.icon}</span> <span class="no">${esc(vd.text)}</span>`);
    } else this.hud.setPrompt(null);

    this.invTimer -= dt;
    if (this.hud.invOpen && (this.invTimer <= 0 || this.hud.dirty)) {
      this.invTimer = 0.25;
      this.hud.renderInventory(def, this.hold, this.wallet.cash, this.delivered, veh, yaw, (it) => this.net(it), (it) => this.fineFor(it), this.dropOrder, this.formation, this.extraRow?.() ?? null, def.kind === 'rail' ? this.railNote : null);
    }
  }

  /**
   * Solve the hold's drop order again when what is aboard changes, and every couple of seconds as the
   * player drives, so the numbers follow where they are. The same solver the fleet packs its runs with.
   */
  private solveDrops(veh: Rider, def: VehicleDef, dt: number): void {
    this.orderT -= dt;
    const key = this.hold.map((it) => it.id).join(',');
    if (key === this.orderKey && this.orderT > 0) return;
    if (key !== this.orderKey) this.refreshInventory();
    this.orderKey = key;
    this.orderT = 2;
    if (new Set(this.hold.map((it) => it.to.id)).size < 2) { this.dropOrder = new Map(); return; }
    const pace = Math.max(0.3, def.topSpeed * 0.5);
    this.dropOrder = solveOrder({ x: veh.x, z: veh.z }, this.hold.map((it) => ({
      id: it.id, px: it.x, pz: it.z, dx: it.to.x, dz: it.to.z, units: it.type.units,
      value: it.value, value0: it.value0, decay: URGENCY[it.urgency].decay, tax: 0, ttl: Infinity, aboard: true,
    })), pace);
  }

  /** Force the I panel to redraw now (after loading, delivering or switching vehicles). */
  private refreshInventory(): void { this.invTimer = 0; }
  /** Something aboard that isn't in `hold` changed (an import crate): draw the cargo list again. */
  pokeInventory(): void { this.invTimer = 0; }

  get inventoryOpen(): boolean { return this.hud.inventoryOpen; }

  /** Show or hide the cargo list (always up while driving, out of the way of windows and tools). */
  showInventory(on: boolean): void {
    this.hud.setInventoryShown(on);
    if (on) this.invTimer = Math.min(this.invTimer, 0);
  }

  /** Waiting goods drawn under screen point (mx, my), if any. */
  private itemAt(mx: number, my: number, camera: THREE.Camera): CargoItem | null {
    let best: CargoItem | null = null, bestD = 34;
    const W = window.innerWidth, H = window.innerHeight;
    for (const it of this.items) {
      if (!this.shown(it)) continue;
      this.v.set(it.x, it.y + 0.35, it.z).project(camera);
      if (this.v.z > 1) continue;
      const d = Math.hypot(((this.v.x + 1) / 2) * W - mx, ((1 - this.v.y) / 2) * H - my);
      if (d < bestD) { bestD = d; best = it; }
    }
    return best;
  }

  private nearest(veh: Rider, reach: number): CargoItem | null {
    let best: CargoItem | null = null, bestD = reach;
    for (const it of this.items) {
      if (!this.shown(it)) continue;
      const d = Math.hypot(it.x - veh.x, it.z - veh.z);
      if (d <= bestD) { bestD = d; best = it; }
    }
    return best;
  }

  private verdict(it: CargoItem, veh: Rider, def: VehicleDef): Verdict {
    const t = it.type, cap = this.capacityFor(def), free = cap - this.used();
    const lent = this.formation.units;
    const with_ = lent ? ` with ${this.formation.names.length} in formation` : '';
    if (t.ultra && !t.ultra.rides.includes(def.id)) return { kind: 'bad', text: `Ultra-Bulk: only ${ultraRideNames(t)} can carry ${t.name}` };
    if (!this.holdsClass(def, t.cls)) return { kind: 'bad', text: `${def.name} can’t carry ${CLASS_LABEL[t.cls]}` };
    if (t.units > cap) return { kind: 'bad', text: `Too big for ${def.name}${with_}: ${t.units} units, holds ${cap}` };
    if ((t.sea || it.sea) && def.kind !== 'water') return { kind: 'bad', text: `${t.name} go by boat, harbour to harbour` };
    if (t.rail && def.kind !== 'rail') return { kind: 'bad', text: `${t.name} go by train, station to station` };
    if (def.kind === 'rail' && !railBound(it)) return { kind: 'bad', text: `${t.name}: a train carries only station to station` };
    const ride = this.loadWhy?.(it, def);
    if (ride) return { kind: 'bad', text: ride };
    const culture = it.culture !== undefined ? this.cultureWhy?.(it) : null;
    if (culture) return { kind: 'bad', text: culture };
    if (!reachesSite(def, it.to)) return { kind: 'bad', text: it.to.port < 0 ? `${def.name} can’t reach ${it.to.name}` : `${def.name} is too big for ${it.to.name}` };
    if (t.units > free) return { kind: 'bad', text: `No room${with_}: needs ${t.units} unit${t.units === 1 ? '' : 's'}, ${free} free` };
    const away = Math.hypot(it.x - veh.x, it.z - veh.z);
    const verb = def.kind === 'water' ? 'Sail' : def.kind === 'air' ? 'Fly' : 'Drive';
    if (isJet(def)) {
      if (!veh.grounded) return { kind: 'far', text: 'Land and taxi to the stand to load' };
      if (away > reachOf(def)) return { kind: 'far', text: `Taxi into the ring to load · ${Math.round(away)} tiles away` };
      if (Math.abs(veh.v) >= STOP_SPEED) return { kind: 'far', text: 'Stop to load' };
      return { kind: 'ok', text: 'Space or click to load' };
    }
    if (it.from?.seabed && !reachesSite(def, it.from)) return { kind: 'bad', text: def.kind === 'water' && def.dive ? `Too deep down for ${def.name}: it dives in ${def.dive.need} steps of water, this lies in ${it.from.depth ?? 0}` : 'Only a submarine reaches the seabed' };
    if (away > reachOf(def)) return { kind: 'far', text: `${verb} into the ring to load · ${Math.round(away)} tiles away` };
    if (it.from?.seabed && !veh.sounded) return { kind: 'far', text: 'Dive, stop over the ring and press Shift to go down to it' };
    if (def.kind === 'air' && veh.y - it.y > FLY_LOW) return { kind: 'far', text: 'Fly lower to load · Shift' };
    return { kind: 'ok', text: 'Space or click to load' };
  }

  /** What a load pays once the towns at either end have taken their levy. */
  net(it: CargoItem): number {
    return it.value - this.taxOn(it);
  }

  private taxOn(it: CargoItem): number {
    if (it.culture !== undefined) return 0;
    const rate = this.books?.taxOf(it) ?? 0;
    return rate > 0 ? Math.max(1, Math.round(it.value * rate)) : 0;
  }

  private tipHtml(it: CargoItem, veh: Rider, def: VehicleDef): string {
    const t = it.type, vd = this.verdict(it, veh, def);
    const rate = this.books?.taxOf(it) ?? 0;
    const tax = rate > 0 ? `<dt>Tax</dt><dd class="tax">${Math.round(rate * 100)}% · −${money(this.taxOn(it))}</dd>` : '';
    const trip = Math.round(Math.hypot(it.to.x - it.x, it.to.z - it.z));
    const from = it.from ? esc(it.from.name) : 'Left by the roadside';
    return `<header><span class="ic">${t.icon}</span><b>${esc(t.name)}</b><em>${money(it.value)}</em></header>
      <p>${esc(t.blurb)}</p>
      <dl><dt>From</dt><dd>${from}</dd><dt>To</dt><dd>${esc(it.to.name)} · ${trip} tiles</dd>
      <dt>Size</dt><dd>${t.units} unit${t.units === 1 ? '' : 's'} of ${CLASS_LABEL[t.cls]}</dd>
      <dt>Limit</dt><dd><b class="u-${it.urgency}">${URGENCY[it.urgency].label}</b>${URGENCY[it.urgency].decay ? ' · value falls once aboard' : ''}</dd>
      <dt>Expires</dt><dd>${it.culture !== undefined ? 'no limit' : it.claimedBy ? 'held' : Number.isFinite(it.ttl) ? clock(Math.ceil(it.ttl)) : 'no limit'}</dd>${tax}</dl>
      ${it.culture !== undefined ? `<div class="claim culture">${esc(this.cultureTip?.(it) ?? 'Cultural cargo: hand it in at your HQ or the hall of a town you hold.')}</div>` : it.claimedBy > 0 ? `<div class="claim">A CPU ${esc(it.claimName)} is on its way for it</div>` : rivalClaim(it.claimedBy) ? `<div class="claim rival">${esc(it.claimName)} · take it first and it’s yours</div>` : it.claimedBy < 0 ? `<div class="claim fleet">${esc(it.claimName)} is on the way for it · your fleet</div>` : ''}
      ${it.longHaul ? `<div class="claim longhaul">Long haul · ${it.longHaul.cells} counties away · ${t.rail ? 'by train' : 'by jet'}</div>` : ''}
      ${t.ultra ? `<div class="claim ultra">Ultra-Bulk · ${t.units} units · ${esc(ultraRideNames(t))} only</div>` : ''}
      <div class="verdict ${vd.kind}">${esc(vd.text)}</div>`;
  }

  /** Click on the canvas: load the goods under the cursor. Returns whether the click hit goods. */
  click(mx: number, my: number, veh: Rider, def: VehicleDef, camera: THREE.Camera): boolean {
    const it = this.itemAt(mx, my, camera);
    if (!it) return false;
    this.load(it, veh, def);
    return true;
  }

  // ---- the factions' vehicles (docs/factions.html) ----------------------------------------------

  /**
   * The Saucer's tractor beam: the nearest goods it could take within `r` tiles of the point under it come
   * up into the hold, wherever it is hovering. Returns what came aboard, or null.
   */
  beamUp(veh: Rider, def: VehicleDef, r: number): CargoItem | null {
    const near = this.items.filter((it) => this.shown(it) && Math.hypot(it.x - veh.x, it.z - veh.z) <= r)
      .sort((a, b) => Math.hypot(a.x - veh.x, a.z - veh.z) - Math.hypot(b.x - veh.x, b.z - veh.z));
    const still = { ...veh, x: veh.x, y: veh.y, z: veh.z, v: 0, grounded: true } as unknown as Rider;
    const it = near.find((q) => this.verdict(q, still, def).kind === 'ok');
    if (!it) return null;
    this.load(it, still, def);
    return this.hold.includes(it) ? it : null;
  }

  /** Goods made aboard (a trawler's catch): straight into the hold, bound for `to`. Null when the hold has no room. */
  stow(t: CargoType, def: VehicleDef, at: { w: World; x: number; y: number; z: number; name: string }, to: Site, value: number): CargoItem | null {
    const used = this.hold.reduce((s, it) => s + it.type.units, 0) + this.extraUnits + this.rushUnits;
    if (used + t.units > this.capacityFor(def)) return null;
    const from: Site = { id: -3_000_000 - this.nextId, kind: 'minorPort', name: at.name, w: at.w, lx: at.x - at.w.ox, lz: at.z - at.w.oz, x: at.x, z: at.z, y: at.y, port: -1, major: false };
    const it: CargoItem = {
      id: this.nextId++, type: t, w: at.w, lx: from.lx, lz: from.lz, x: at.x, z: at.z, y: at.y,
      from, to, urgency: 'standard', value, value0: value, ttl: Infinity, life: Infinity, claimedBy: 0, claimName: '', marker: null,
    };
    this.hold.push(it);
    this.refreshInventory();
    return it;
  }

  /** The nearest place of these kinds to (x, z), world tiles, among the islands in memory. */
  nearestSite(kinds: SiteKind[], x: number, z: number): Site | null {
    let best: Site | null = null, d0 = Infinity;
    for (const s of this.sitesOf(kinds)) { const d = Math.hypot(s.x - x, s.z - z); if (d < d0) { d0 = d; best = s; } }
    return best;
  }

  /** Put ashore whatever aboard passes `test`, as if at its door (the Pelican on a beach). */
  landAt(veh: Rider, def: VehicleDef, test: (it: CargoItem) => boolean): void { this.deliver(veh, def, false, test); }

  /** Space: load the nearest goods in reach. */
  loadNearest(veh: Rider, def: VehicleDef): void {
    const reach = reachOf(def);
    const inReach = this.items.filter((it) => this.shown(it) && Math.hypot(it.x - veh.x, it.z - veh.z) <= reach)
      .sort((a, b) => Math.hypot(a.x - veh.x, a.z - veh.z) - Math.hypot(b.x - veh.x, b.z - veh.z));
    if (!inReach.length) return;
    this.load(inReach.find((it) => this.verdict(it, veh, def).kind === 'ok') ?? inReach[0], veh, def);
  }

  private load(it: CargoItem, veh: Rider, def: VehicleDef): void {
    const vd = this.verdict(it, veh, def);
    const at = new THREE.Vector3(veh.x, veh.y + 0.4, veh.z);
    if (vd.kind !== 'ok') { this.hud.float(vd.text, at, 'bad'); return; }
    this.unplace(it);
    if (rivalClaim(it.claimedBy)) this.onSnatch?.(it);
    it.claimedBy = 0;
    this.hold.push(it);
    deeds.best('fullLoad', this.hold.length);
    this.hud.float(`${it.type.icon} ${it.type.name} loaded`, at, 'info');
    this.refreshInventory();
  }

  /** Stopped enough to hand goods over: on the ground and still, or for a plane that can't stop, at stall speed (a jet in flight hands overseas loads over). */
  private stoppedFor(veh: Rider, def: VehicleDef): boolean {
    const jet = isJet(def);
    const minSpeed = def.kind === 'air' ? (def as AirDef).minSpeed : 0;
    return jet ? !veh.grounded || Math.abs(veh.v) < STOP_SPEED
      : minSpeed > 0 ? Math.abs(veh.v) <= minSpeed + 0.3 : Math.abs(veh.v) < STOP_SPEED;
  }

  /** The door ring the vehicle is in, if any: a mission's, or the destination of goods aboard that go in through one. */
  private doorAt(veh: Rider, def: VehicleDef): Door | null {
    const reach = reachOf(def);
    for (const d of this.allDoors()) if (Math.hypot(d.x - veh.x, d.z - veh.z) <= reach) return d;
    return null;
  }

  private allDoors(): Door[] {
    const out = [...this.doors];
    // a shop's own ring gives way to a mission's at the same door (the first drive's auto shop)
    // and none at all while the first drive holds the world to its own work
    if (this.focus !== 'only') for (const d of this.shopDoors) if (!d.shut?.() && !this.doors.some((m) => Math.hypot(m.x - d.x, m.z - d.z) < 3)) out.push(d);
    for (const it of this.hold) {
      if (!it.door || out.some((d) => d.key === `site:${it.to.id}`)) continue;
      out.push({ key: `site:${it.to.id}`, x: it.to.x, z: it.to.z, y: it.to.y, name: it.door.name, icon: it.door.icon });
    }
    return out;
  }

  /** The missions' doors, replacing the last list. */
  setDoors(list: Door[]): void { this.doors = list; }

  /** The Vehicle Shops' and Dealers' doors, replacing the last list. */
  setShopDoors(list: Door[]): void { this.shopDoors = list; }

  /** Build, pose and put away the entrance rings; the one the vehicle is in, if any. */
  private syncDoors(veh: Rider, def: VehicleDef, reach: number, yaw: number): Door | null {
    const all = this.allDoors();
    const keys = new Set(all.map((d) => d.key));
    for (const [k, m] of this.doorMarks) {
      if (keys.has(k)) continue;
      disposeDoorMarker(m);
      this.doorMarks.delete(k);
    }
    const inside = this.doorAt(veh, def);
    const ready = !!inside && this.stoppedFor(veh, def);
    // a new ring of counties brings dozens of doors at once, each two canvases of lettering and three
    // materials: a couple a frame (the one the vehicle is in at once), the rest in the frames after
    let made = 0;
    const shops = new Set(this.shopDoors);
    for (const d of all) {
      let m = this.doorMarks.get(d.key);
      // a shop's sign only near it: out of reach it is put away (or never made)
      const shopFar = shops.has(d) && d !== inside ? Math.hypot(d.x - veh.x, d.z - veh.z) : 0;
      if (shopFar > SHOP_NEAR) { if (m) m.group.visible = false; continue; }
      if (m) m.group.visible = true;
      if (!m) {
        if (made >= DOORS_A_FRAME && d !== inside) continue;
        made++;
        m = buildDoorMarker(d.icon, d.name, d.look, d.theme);
        m.group.position.set(d.x, d.y + 0.05, d.z);
        this.group.add(m.group);
        this.doorMarks.set(d.key, m);
      }
      const far = d.fade ? Math.hypot(d.x - veh.x, d.z - veh.z) : 0;
      const alpha = (d.fade ? FADE_MIN + (1 - FADE_MIN) * Math.min(1, Math.max(0, (FADE_FAR - far) / (FADE_FAR - FADE_NEAR))) : 1)
        * (d.spent?.() ? SPENT_ALPHA : 1)
        * (shopFar > SHOP_NEAR - SHOP_FADE ? Math.max(0, (SHOP_NEAR - shopFar) / SHOP_FADE) : 1);
      // a mission's space bar shows within KEY_NEAR tiles of its diamond
      const near = d.look === 'mission' && Math.hypot(d.x - veh.x, d.z - veh.z) <= KEY_NEAR;
      poseDoorMarker(m, this.time, reach, yaw, ready && inside === d, alpha, near, this.frameDt);
    }
    return inside;
  }

  /** The Vehicle Shop or Dealer whose ring the vehicle stands in, by its outlet key, or null: G at a ring (docs/hqwindow.html). */
  shopAt(veh: Rider, def: VehicleDef): string | null {
    const d = this.doorAt(veh, def);
    return d?.key.startsWith('shop:') ? d.key.slice(5) : null;
  }

  /**
   * Space: go in at the door the vehicle is in, if it is in one. True when Space was the door's (it
   * then loads nothing), whether or not the vehicle had stopped.
   */
  pressDoor(veh: Rider, def: VehicleDef): boolean {
    const d = this.doorAt(veh, def);
    if (!d) return false;
    if (!this.stoppedFor(veh, def)) {
      this.hud.float('Stop first', new THREE.Vector3(veh.x, veh.y + 0.4, veh.z), 'bad');
      return true;
    }
    if (d.key.startsWith('site:')) this.deliver(veh, def, true);
    else if (d.key.startsWith('shop:')) this.onShop?.(d.key.slice(5));
    else if (d.key.startsWith('tavern:')) this.onTavern?.(d.key.slice(7));
    else this.onDoor?.(d.key);
    return true;
  }

  /**
   * Stopped (or, for a plane that can't stop, at stall speed) inside a destination ring: unload everything
   * bound there. Goods that go in through a door wait for Space there (`door`), and only they go then.
   */
  private deliver(veh: Rider, def: VehicleDef, door = false, force?: (it: CargoItem) => boolean): void {
    if (!this.hold.length) return;
    const jet = isJet(def);
    if (!this.stoppedFor(veh, def)) return;
    const reach = reachOf(def);
    const due = this.hold.filter((it) => {
      if (force) return it.culture === undefined && force(it);
      if (!!it.door !== door) return false;
      // cultural goods are handed over only while the fleet has a hall to take them, and a consignment only at a town ready for it
      if (it.culture !== undefined && this.cultureOpen && !this.cultureOpen()) return false;
      if (it.culture !== undefined && this.cultureDue?.(it)) return false;
      const d = Math.hypot(it.to.x - veh.x, it.to.z - veh.z);
      if (it.to.kind === 'overseas') return jet && !veh.grounded && d <= OVERSEAS_R;
      if (it.to.seabed) return !!veh.sounded && d <= reach;
      if (jet) return !!veh.grounded && d <= reach;
      return d <= reach && (def.kind !== 'air' || veh.y - it.to.y <= FLY_LOW);
    });
    // a convoy's load waits for the vehicles meant to come in with it
    if (this.heldBack && !force) for (let k = due.length - 1; k >= 0; k--) if (this.heldBack(due[k])) due.splice(k, 1);
    if (!due.length) return;
    // people who rode with the roof down most of the way pay more for the view
    let scenic = 0;
    if (def.convertible) {
      for (const it of due) {
        if (it.type.cls !== 'people' || !it.ride || it.ride.t <= 0 || it.ride.down / it.ride.t < TOP_DOWN_SHARE) continue;
        const extra = Math.round(it.value * TOP_DOWN_BONUS);
        it.value += extra;
        scenic += extra;
        deeds.add('topDown');
      }
    }
    // the working vehicles' knacks: a full bus, a limousine's VIPs, a tipper's bulk
    let knack = 0, knackName = '';
    const people = this.hold.filter((it) => it.type.cls === 'people').length;
    const parcels = this.hold.filter((it) => it.type.cls === 'parcel').length;
    for (const it of due) {
      let share = 0;
      if (it.type.cls === 'people' && def.fareBox) { share += Math.min(0.5, def.fareBox * (people - 1)); knackName = 'Full bus'; }
      if (it.type.cls === 'people' && def.vip) { share += def.vip; knackName = 'VIP fares'; }
      if (it.type.cls === 'bulk' && def.tipper) { share += def.tipper; knackName = 'Tipped'; }
      if (it.type.cls === 'parcel' && def.postal) { share += def.postal + Math.min(0.2, 0.03 * (parcels - 1)); knackName = 'First class'; }
      // a faction vehicle's own work (docs/factions.html): a Mixer's cement, an Interceptor's evidence
      if (def.bonus && def.bonus.ids.includes(it.type.id)) { share += def.bonus.share; knackName = def.bonus.label; }
      const more = this.fac?.extra?.(it, def) ?? 0;
      if (more > 0) { share += more; knackName = 'Sights seen'; }
      if (share <= 0) continue;
      const extra = Math.round(it.value * share);
      it.value += extra;
      knack += extra;
    }
    // a faction's own work pays by the player's standing with it (docs/factions.html)
    let facExtra = 0, facName = '';
    if (this.fac) {
      for (const it of due) {
        const m = this.fac.payMul(it);
        if (m === 1) continue;
        const extra = Math.round(it.value * (m - 1));
        it.value += extra;
        facExtra += extra;
        facName = this.fac.name(it) ?? facName;
      }
    }
    // the Passport's treats (game/passportRewards.ts): passengers pay more with every town size stamped, a
    // wonder's visitors with every wonder
    let passport = 0;
    for (const it of due) {
      if (it.culture !== undefined) continue;
      let m = it.type.cls === 'people' ? rewards.peopleMul() : 1;
      if (WONDER_KINDS.has(it.to.kind as string) || (it.from && WONDER_KINDS.has(it.from.kind as string))) m *= rewards.wonderMul();
      if (m === 1) continue;
      const extra = Math.round(it.value * (m - 1));
      it.value += extra;
      passport += extra;
    }
    const total = due.reduce((s, it) => s + it.value, 0);
    const taxes = due.map((it) => this.taxOn(it));
    const tax = taxes.reduce((s, v) => s + v, 0);
    this.hold = this.hold.filter((it) => !due.includes(it));
    this.wallet.earn(total - tax, 'cargo');
    this.delivered += due.length;
    due.forEach((it, k) => { if (it.culture === undefined) this.books?.delivered(it, true, it.value - taxes[k]); });
    for (const it of due) this.onDelivered(it);
    if (this.fac) for (const it of due) if (it.culture === undefined) this.fac.delivered(it, 'you', veh);
    // deeds: what your own hand delivered
    deeds.add('loads', due.length);
    deeds.add('cash', total);
    due.forEach((it, k) => {
      if (it.culture === undefined && !it.type.madeOnly) deeds.mark('cargoTypes', it.type.id);
      // the Cone Zone deed: sundaes from the fleet's own parlour, in a Sundae (docs/supplychains.html)
      if (def.id === 'sundae' && it.type.id === 'sundaes' && it.made) deeds.add('coneZone');
      if (it.urgency === 'urgent') deeds.add('urgent');
      if (it.w.cx !== it.to.w.cx || it.w.cz !== it.to.w.cz) deeds.add('across');
      deeds.best('payday', Math.round(it.value - taxes[k]));
      if (RAIL_CARGO.has(it.type.id) || (it.type.cls === 'people' && STATION_KINDS.has(it.to.kind as string))) deeds.add('railLoads');
      // by weight and by hold, the long and the ultra hauls, the deep, the acts (the user, 28 Oct 2026)
      deeds.add('tonnage', it.type.units);
      deeds.best('heaviest', it.type.units);
      if (it.type.cls === 'freight') deeds.add('freightLoads');
      else if (it.type.cls === 'bulk') deeds.add('bulkLoads');
      else if (it.type.cls === 'container') deeds.add('containerLoads');
      if (it.longHaul) deeds.add('longHauls');
      if (it.type.ultra) deeds.add('ultraLoads');
      deeds.best('farthest', Math.max(Math.abs(it.w.cx - it.to.w.cx), Math.abs(it.w.cz - it.to.w.cz), it.longHaul?.cells ?? 0));
      if (it.to.seabed || it.from?.seabed) deeds.add('deepLoads');
      if (it.type.id === 'touringBand' || it.type.id === 'awayTeam') deeds.add('roadie');
      nextWorldDeeds(it);
    });
    // a round in one of the Post's own (the Mail Truck, the Nightflyer): a faction vehicle's trick
    if (def.faction === 'post') deeds.mark('tricks', 'post');
    // cultural goods: the culture system takes them from here (points, the festival, the town's books)
    const culture = due.filter((it) => it.culture !== undefined);
    if (culture.length) this.onCulture?.(culture, culture.reduce((s, it) => s + it.value, 0));
    // the gross in green, and what the towns took in red just under it
    this.hud.float(`+${money(total)}`, new THREE.Vector3(veh.x, veh.y + 0.5, veh.z), 'cash');
    if (knack > 0) this.hud.float(`${knackName} +${money(knack)}`, new THREE.Vector3(veh.x, veh.y + 0.7, veh.z), 'info');
    if (scenic > 0) this.hud.float(`Top down +${money(scenic)}`, new THREE.Vector3(veh.x, veh.y + 0.7, veh.z), 'info');
    if (passport > 0) this.hud.float(`Passport +${money(passport)}`, new THREE.Vector3(veh.x, veh.y + 0.8, veh.z), 'info');
    if (facExtra) this.hud.float(`${facName} ${facExtra > 0 ? '+' : '−'}${money(Math.abs(facExtra))}`, new THREE.Vector3(veh.x, veh.y + 0.9, veh.z), facExtra > 0 ? 'info' : 'tax');
    if (tax > 0) this.hud.float(`−${money(tax)} tax`, new THREE.Vector3(veh.x, veh.y + 0.5, veh.z), 'tax');
    // overseas, the hold is filled again on the spot with the return trip home
    const back = due.filter((it) => it.to.kind === 'overseas' && it.from);
    for (const it of back) {
      const home = it.from!, at = it.to;
      const dist = Math.hypot(home.x - at.x, home.z - at.z);
      const value = valueOf(it.type, dist, 'relaxed', Infinity);
      const ret: CargoItem = {
        id: this.nextId++, type: it.type, w: home.w, lx: at.x - home.w.ox, lz: at.z - home.w.oz, x: at.x, z: at.z, y: at.y,
        from: at, to: home, urgency: 'relaxed', value, value0: value, ttl: Infinity, life: Infinity, claimedBy: 0, claimName: '', marker: null,
      };
      this.hold.push(ret);
    }
    if (back.length) this.hud.float(`${back.length} return load${back.length === 1 ? '' : 's'} aboard for ${back[0].from!.name}`, new THREE.Vector3(veh.x, veh.y + 0.9, veh.z), 'info');
    this.refreshInventory();
  }

  /**
   * A hard knock with a limousine's VIPs aboard: every people fare in the hold loses a tenth. Returns
   * what it cost, for the float.
   */
  vipKnock(def: VehicleDef): number {
    let lost = 0, broke = 0;
    for (const it of this.hold) {
      // breakables (docs/supplychains.html): glass, fireworks, a racehorse, instruments, a satellite, in anything
      const people = it.type.cls === 'people' && !!def.vip;
      if (!people && !it.type.fragile) continue;
      const cut = it.value * 0.1;
      it.value -= cut;
      if (people) lost += cut; else broke += cut;
    }
    if (lost > 0) this.hud.float(`VIPs rattled −${money(lost)}`, new THREE.Vector3(this.lastVeh.x, this.lastVeh.y + 0.7, this.lastVeh.z), 'tax');
    if (broke > 0) this.hud.float(`Fragile! −${money(broke)}`, new THREE.Vector3(this.lastVeh.x, this.lastVeh.y + 0.85, this.lastVeh.z), 'tax');
    return lost + broke;
  }

  /** A green ring at every destination of the goods aboard, tagged with what they'll pay. */
  private syncDestinations(reach: number, def: VehicleDef): void {
    const want = new Map<number, { site: Site; value: number }>();
    const gold = new Set<number>(), lime = new Set<number>();
    for (const it of this.hold) {
      // goods for a shop's door show its entrance ring instead
      if (it.door) continue;
      if (it.longHaul) gold.add(it.to.id);
      if (it.type.ultra) lime.add(it.to.id);
      const d = want.get(it.to.id);
      if (d) d.value += it.value;
      else want.set(it.to.id, { site: it.to, value: it.value });
    }
    // and the followed vehicle's, at its own reach
    const far = new Set<number>();
    for (const it of this.watched?.items ?? []) {
      if (want.has(it.to.id)) continue;
      far.add(it.to.id);
      const d = want.get(it.to.id);
      if (d) d.value += it.value;
      else want.set(it.to.id, { site: it.to, value: it.value });
    }
    // another player's, followed: only where and what for, as their game sent it (net/remote.ts dropsOf)
    for (const q of this.watched?.drops ?? []) {
      const id = -1 - ((((Math.round(q.x) & 0xffff) << 16) | (Math.round(q.z) & 0xffff)) >>> 0);
      far.add(id);
      const d = want.get(id);
      if (d) d.value += q.value;
      else want.set(id, { site: { id, kind: 'drop', x: q.x, y: q.y, z: q.z } as unknown as Site, value: q.value });
    }
    for (const [id, d] of this.dests) {
      if (want.has(id)) continue;
      disposeCargoMarker(d.marker);
      this.dests.delete(id);
    }
    for (const [id, d] of want) {
      let m = this.dests.get(id);
      if (!m) {
        const marker = buildCargoMarker(gold.has(id) ? LONG_HAUL_GOLD : lime.has(id) ? ULTRA_LIME : DEST_COLOR, null);
        marker.group.position.set(d.site.x, d.site.y + 0.05, d.site.z);
        this.group.add(marker.group);
        m = { marker, site: d.site, value: 0 };
        this.dests.set(id, m);
      }
      m.value = d.value;
      const dim = this.focus === 'dim' && !this.hold.some((h) => h.to.id === id && h.chain !== undefined);
      const r = d.site.kind === 'overseas' ? OVERSEAS_R : far.has(id) ? this.watched!.reach : ringOf(def, reach, !!d.site.station || this.hold.some((h) => h.to.id === id && h.type.rail));
      poseCargoMarker(m.marker, this.time, r, dim ? DIM : 1);
    }
  }

  /** After switching vehicles: keep what the new one can carry; the rest is left by the roadside for a while. */
  refit(def: VehicleDef, veh: { x: number; y: number; z: number }, home: World | null): void {
    const w = home;
    let used = 0;
    const keep: CargoItem[] = [], left: CargoItem[] = [];
    for (const it of this.hold) {
      // (a train's long haul stays a train's: it is not driven off by road)
      if (def.holds.includes(it.type.cls) && used + it.type.units <= def.capacity && reachesSite(def, it.to) && (!it.type.rail || def.kind === 'rail') && (!it.type.ultra || it.type.ultra.rides.includes(def.id))) { keep.push(it); used += it.type.units; }
      else left.push(it);
    }
    this.hold = keep;
    // cultural goods that don't fit go back to where they were found rather than to the roadside
    for (const it of left.filter((q) => q.culture !== undefined)) this.onCultureDropped?.(it);
    left.splice(0, left.length, ...left.filter((q) => q.culture === undefined));
    left.forEach((it, k) => {
      const a = (k / Math.max(1, left.length)) * Math.PI * 2;
      it.x = veh.x + Math.sin(a) * 0.7;
      it.z = veh.z + Math.cos(a) * 0.7;
      it.w = w ?? it.w;
      it.lx = it.x - it.w.ox;
      it.lz = it.z - it.w.oz;
      it.y = w ? Math.max(surfaceY(w, it.lx, it.lz), groundY(w, it.lx, it.lz) - 0.01) : veh.y;
      it.from = null;
      it.ttl = it.life = DROP_TTL;
      this.place(it);
    });
    if (left.length) this.hud.float(`${left.length} left by the roadside`, new THREE.Vector3(veh.x, veh.y + 0.4, veh.z), 'bad');
    this.refreshInventory();
  }

  // ---- CPU haulers ----

  /**
   * Goods nobody has claimed with at least `minTtl` seconds left. A CPU hauler only takes work that
   * starts and ends on its own island; runs across the water are the player's to make. Work put out for
   * the player's boats (SEA_WORK) is left for them.
   */
  openJobs(minTtl: number, on?: World): CargoItem[] {
    // the island's own haulers take the island's own work: a load made for a carrier (game/cargoDemand.ts) is left for it
    return this.items.filter((it) => !it.claimedBy && !it.for && !it.sea && !it.type.heli && !it.type.jet && !it.type.sub && !it.longHaul && !it.type.ultra && !it.type.self && it.ttl > minTtl && (!on || (it.w === on && it.to.w === on)) && !this.refused(it, ''));
  }

  /**
   * Loads waiting on `on` that are bound for a cell right next to it — the next county, or the island
   * over the causeway — for a CPU hauler that will drive them over the border.
   */
  crossJobs(minTtl: number, on: World): CargoItem[] {
    return this.items.filter((it) => !it.claimedBy && !it.for && !it.type.heli && !it.type.jet && !it.type.sub && !it.longHaul && !it.type.ultra && !it.type.self && it.ttl > minTtl && it.w === on && it.to.w !== on && !this.refused(it, '')
      && Math.abs(it.to.w.cx - on.cx) + Math.abs(it.to.w.cz - on.cz) === 1);
  }

  /**
   * Work for a hired jet on a stand at runway r (game/jetPilots.ts): the jet loads waiting at its airport that go
   * where it can land (an airport at one of `goals`) or overseas from this international, the richest place's
   * first, up to its hold; or, with none waiting, one made for it the way the player's are. All for one place,
   * and collected into its hold at once.
   */
  jetWork(def: AirDef, r: Runway, uid: number, name: string, goals: Runway[], want?: JetWant): CargoItem[] {
    return this.jetLoad(this.jetReserve(def, r, uid, name, goals, undefined, want), uid);
  }

  /** A hired jet's reserved loads (jetReserve) taken aboard: those still on the ground and still its. */
  jetLoad(items: CargoItem[], uid: number): CargoItem[] {
    return items.filter((it) => this.collect(it, -uid));
  }

  /**
   * Work for a hired jet at this runway's stand, held for it but left on the apron where it waits (for `secs`, or
   * until taken): what it will load at the end of its turnaround, so a player following it sees what it is
   * picking up (game/jetPilots.ts), as a road vehicle drives to its pickups. All bound for one place it can reach.
   * `want`: its crew order (orders.ts jetWant): what it takes and where, and Long haul's gold work first.
   */
  jetReserve(def: AirDef, r: Runway, uid: number, name: string, goals: Runway[], secs?: number, want?: JetWant): CargoItem[] {
    if (!def.jet || want?.none) return [];
    const st = r.stands[0];
    const at = (s: Site | null | undefined, x: number, z: number) => !!s && Math.hypot(s.x - x, s.z - z) < 3;
    const froms = this.sitesOf(['airport', 'intl']).filter((s) => at(s, st.x, st.z));
    if (!froms.length) return [];
    if (want?.far) {
      const lh = this.jetFar(def, froms, want);
      if (lh) { this.claim(lh, -uid, name, secs); return [lh]; }
    }
    const mid = { x: (r.ax + r.bx) / 2, z: (r.az + r.bz) / 2 };
    const goes = (s: Site) => reachesSite(def, s) && (s.kind === 'overseas'
      ? s.w === r.w && Math.hypot(s.x - mid.x, s.z - mid.z) < OVERSEAS_OUT + 60
      : goals.some((g) => fitsRunway(def.jet!.runway, g) && at(s, g.stands[0].x, g.stands[0].z)));
    const fits = (t: CargoType) => !!t.jet && !t.longHaul && !t.ultra && def.holds.includes(t.cls) && t.units <= def.capacity;
    const key = (s: Site) => `${Math.round(s.x)},${Math.round(s.z)}`;
    // what waits here already, grouped by where it goes
    const by = new Map<string, CargoItem[]>();
    for (const it of this.items) {
      if (it.claimedBy || it.chain !== undefined || !fits(it.type) || !froms.includes(it.from!) || !goes(it.to)) continue;
      if (want && !want.ok(it.type, it.urgency, it.from!, it.to)) continue;
      by.set(key(it.to), [...(by.get(key(it.to)) ?? []), it]);
    }
    // the richest place's first, as the order weighs it (a preferred type, a crossing it prefers)
    const worth = (b: CargoItem[]) => b.reduce((n, it) => n + it.value * (want ? want.weight(it.type, it.from!, it.to) : 1), 0);
    let batch = [...by.values()].sort((a, b) => worth(b) - worth(a))[0] ?? [];
    if (!batch.length) {
      const types = CARGO.filter((t) => fits(t) && froms.some((s) => t.from.includes(s.kind)) && (!want || want.kind(t)));
      for (let tries = 0; tries < 6 && !batch.length && types.length; tries++) {
        const t = pick(types), from = froms.find((s) => t.from.includes(s.kind))!;
        const urg = (to: Site) => (t.urgency ?? DEFAULT_URGENCY).filter((u) => !want || want.ok(t, u, from, to));
        const tos = this.sitesOf(t.to).filter((s) => s !== from && goes(s) && Math.hypot(s.x - from.x, s.z - from.z) >= 12 && urg(s).length > 0);
        if (tos.length) { const to = pick(tos); batch = [this.make(t, from, to, pick(urg(to)))]; }
      }
    }
    const out: CargoItem[] = [];
    let used = 0;
    for (const it of batch) {
      if (used + it.type.units > def.capacity) continue;
      this.claim(it, -uid, name, secs);
      out.push(it);
      used += it.type.units;
    }
    return out;
  }

  /**
   * Long haul for a hired jet (orders.ts jetWant far): a gold long-haul load at its airport that it can carry, one
   * waiting there already (the player's offers) or else one made for it, for a surveyed airport five counties or more
   * off that it can land at, as the player's own are made (spawnLongJet). Null with none to be had. The far airport
   * is never in memory: the jet flies there and back as to an overseas point (game/jetPilots.ts goalOf).
   */
  private jetFar(def: AirDef, froms: Site[], want: JetWant): CargoItem | null {
    const takes = (t: CargoType) => !!t.jet && !!t.longHaul && def.holds.includes(t.cls) && t.units <= def.capacity && want.kind(t);
    const waiting = this.items.find((it) => it.longHaul && !it.claimedBy && it.from && froms.includes(it.from) && takes(it.type));
    if (waiting) return waiting;
    const from = froms.find((s) => reachesSite(def, s));
    if (!from || !def.jet) return null;
    const kinds = this.longKinds(def, true).filter(takes);
    const far = (this.farAirports?.() ?? []).filter((a) => Math.max(Math.abs(a.cx - from.w.cx), Math.abs(a.cz - from.w.cz)) >= LONG_HAUL.min && (a.major || def.jet!.runway <= 22));
    if (!kinds.length || !far.length) return null;
    const own = kinds.filter((q) => q.from.includes(from.kind));
    const a = pick(far), t = pick(own.length ? own : kinds);
    const to: Site = { id: this.farId--, kind: a.major ? 'intl' : 'airport', name: `${a.name} (${a.code})`, w: from.w, lx: a.gx - from.w.ox, lz: a.gz - from.w.oz, x: a.gx, z: a.gz, y: a.y, port: -1, major: a.major };
    return this.makeLongHaul(t, from, to, [a.cx, a.cz]);
  }

  /** A hired jet over the overseas point: the return loads for those it handed over, home to the airport they came from. */
  jetBack(done: CargoItem[]): CargoItem[] {
    const out: CargoItem[] = [];
    for (const it of done) {
      if (!it.from) continue;
      const home = it.from, at = it.to;
      const value = valueOf(it.type, Math.hypot(home.x - at.x, home.z - at.z), 'relaxed', Infinity);
      const ret: CargoItem = {
        id: this.nextId++, type: it.type, w: home.w, lx: at.x - home.w.ox, lz: at.z - home.w.oz, x: at.x, z: at.z, y: at.y,
        from: at, to: home, urgency: 'relaxed', value, value0: value, ttl: Infinity, life: Infinity, claimedBy: 0, claimName: '', marker: null,
      };
      this.carried.add(ret);
      out.push(ret);
    }
    return out;
  }

  // ---- crewed trains (docs/crewtrains.html): the beat stock, and what a hired driver hands in and takes on -------

  /** Each beat station's stock: units owed to it so far, by station and kind of train (`passenger` / `freight`). */
  private beatOwed = new Map<string, number>();

  /** A station's site in memory (its platform's), or null. */
  private stationSite(st: RailStation): Site | null {
    for (const s of this.sitesOf(STATION_SITE_KINDS)) if (s.station === st) return s;
    return null;
  }

  /**
   * The beat stock (the user, 4 Nov 2026: no spamming trains at one station for more cargo, but enough that two fleet
   * trains on one beat are kept going). Station-to-station loads along every beat a hired driver is working, at a rate
   * sized from the beat's round trip so that two trains on it run about three fifths full and one nearly full. The
   * rate is the station's, not the train's: a third train on the beat shares what two are given, and a station on two
   * beats takes the faster of their rates, never both. What waits at a station is capped at two calls' worth.
   */
  beatStock(beats: BeatWork[], dt: number): void {
    // each station, at the most any beat it is on asks of it
    const want = new Map<string, { st: RailStation; rate: number; cap: number; beat: BeatWork }>();
    for (const b of beats) {
      if (b.stops.length < 2 || b.trip <= 0) continue;
      // units a second for the beat as a whole: 2.4 holds a round trip (two trains, both ways, three fifths full)
      const rate = (BEAT_FILL * b.capacity) / b.trip / b.stops.length;
      // (two full calls' worth waits at most: a train finds a hold's worth, the next train another)
      const cap = Math.max(...this.beatTypes(b).map((t) => t.units), 2 * b.capacity);
      for (const st of b.stops) {
        const key = `${beatKey(st)}|${b.freight ? 'f' : 'p'}`;
        const had = want.get(key);
        if (!had || had.rate < rate) want.set(key, { st, rate, cap, beat: b });
      }
    }
    for (const k of [...this.beatOwed.keys()]) if (!want.has(k)) this.beatOwed.delete(k);
    for (const [key, w] of want) {
      const owed = (this.beatOwed.get(key) ?? 0) + w.rate * dt;
      const from = this.stationSite(w.st);
      const types = this.beatTypes(w.beat).filter((t) => from && t.beat!.from.includes(from.kind));
      if (!from || !types.length) { this.beatOwed.set(key, 0); continue; }
      // what waits here already, of the beat's own
      const waiting = this.items.reduce((n, it) => n + (it.from === from && it.type.beat && types.includes(it.type) ? it.type.units : 0), 0);
      const t = types[Math.floor(Math.random() * types.length)];
      if (waiting + t.units > w.cap) { this.beatOwed.set(key, Math.min(owed, t.units)); continue; }
      if (owed < t.units) { this.beatOwed.set(key, owed); continue; }
      // bound for another stop of the beat, a station of a kind it goes to
      const tos = w.beat.stops.filter((s) => s !== w.st).map((s) => this.stationSite(s)).filter((s): s is Site => !!s && t.beat!.to.includes(s.kind) && Math.hypot(s.x - from.x, s.z - from.z) >= 12);
      if (!tos.length) { this.beatOwed.set(key, 0); continue; }
      const to = tos[Math.floor(Math.random() * tos.length)];
      this.make(t, from, to, 'relaxed');
      this.beatOwed.set(key, owed - t.units);
    }
  }

  /** The kinds of beat work a train of this kind carries (its holds). */
  private beatTypes(b: BeatWork): CargoType[] {
    // (a freight's is the goods work, which alone is taken at a goods yard; a passenger train's the rest)
    return CARGO.filter((t) => t.beat && b.holds.includes(t.cls) && t.units <= b.capacity && (b.freight ? t.beat.from.includes('goodsYard') : !t.beat.from.includes('goodsYard')));
  }

  /**
   * A crewed train has called at a station (docs/crewtrains.html): what is aboard for here is handed in, and what waits
   * here for another stop of its beat comes aboard, as much as the hold takes, the stops still ahead of it first.
   * `ahead`: the beat's stops from here to the end it is bound for, in order. Returns what to pay and what was loaded.
   */
  crewCall(st: RailStation, beat: RailStation[], ahead: RailStation[], aboard: CargoItem[], def: VehicleDef, uid: number, name: string): { drop: CargoItem[]; take: CargoItem[] } {
    const here = this.stationSite(st);
    // (a long haul's return load is bound for the beat's end by name: it was made with that county out of memory)
    const at = (s: Site | null | undefined) => !!s && (s.station === st || (!!here && s === here) || (s.id < 0 && s.name === st.name));
    const drop = aboard.filter((it) => at(it.to));
    const left = aboard.filter((it) => !drop.includes(it));
    let used = left.reduce((n, it) => n + it.type.units, 0);
    const take: CargoItem[] = [];
    if (!here) return { drop, take };
    const onBeat = (s: Site | null | undefined) => !!s?.station && s.station !== st && beat.includes(s.station);
    const cands = this.items.filter((it) => it.from === here && (!it.claimedBy || it.claimedBy === -uid) && it.chain === undefined && !it.longHaul && !it.type.ultra
      && railBound(it) && onBeat(it.to) && def.holds.includes(it.type.cls) && it.type.units <= def.capacity && !this.refused(it, ''));
    // the stops ahead first (a load for one behind rides to the end and back), the richest first
    const score = (it: CargoItem) => it.value * (ahead.includes(it.to.station!) ? 1 : 0.6);
    cands.sort((a, b) => score(b) - score(a));
    for (const it of cands) {
      if (used + it.type.units > def.capacity) continue;
      if (!this.collect(it, -uid)) continue;
      it.claimName = name;
      take.push(it);
      used += it.type.units;
    }
    return { drop, take };
  }

  // ---- long haul for crewed trains (docs/crewtrains.html) ----

  /** A site out of memory, at a world point: a long haul's far station, or the beat end a return load is bound for. */
  private farSite(kind: SiteKind, name: string, x: number, z: number, y: number, near: Site): Site {
    return { id: this.farId--, kind, name, w: near.w, lx: x - near.w.ox, lz: z - near.w.oz, x, z, y, port: -1, major: false };
  }

  /** A long haul's value, as the player's own are priced: by how many counties off it is bound. */
  private longValue(cells: number): number {
    return Math.min(LONG_HAUL.top, Math.round((LONG_HAUL.base + (Math.max(LONG_HAUL.min, cells) - LONG_HAUL.min) * LONG_HAUL.perCell + rand(0, LONG_HAUL.spread)) / 10) * 10);
  }

  /**
   * A long-haul load for a crewed train at an end of its beat, bound for one of `dests` (5–14 counties on along the
   * line past that end, from the world plan), taken aboard at once; null when none of the long-haul kinds fits.
   */
  crewLong(st: RailStation, def: VehicleDef, room: number, dests: StationRef[], uid: number, name: string): CargoItem | null {
    const from = this.stationSite(st);
    if (!from || !dests.length) return null;
    const all = this.longKinds(def, false).filter((t) => t.units <= room);
    const own = all.filter((t) => t.from.includes(from.kind));
    for (const t of [...(own.length ? own : all)].sort(() => Math.random() - 0.5)) {
      const ok = dests.filter((d) => t.to.includes(d.kind));
      if (!ok.length) continue;
      const d = pick(ok);
      const to = this.farSite(d.kind, d.name, (d.cx + 0.5) * N, (d.cz + 0.5) * N, from.y, from);
      const it = this.makeLongHaul(t, from, to, [d.cx, d.cz]);
      if (!this.collect(it, -uid)) return null;
      it.claimName = name;
      return it;
    }
    return null;
  }

  /**
   * At the far station: a return load for each long haul handed in there, the same kind, bound back for the beat's end
   * it came from (`home`, a world point and its county), priced by how far it goes. Carried at once.
   */
  railBack(done: CargoItem[], home: { name: string; kind: SiteKind; x: number; z: number; y: number; cx: number; cz: number }, uid: number, name: string): CargoItem[] {
    const out: CargoItem[] = [];
    for (const it of done) {
      const at = it.to;
      const from = this.farSite(at.kind, at.name, at.x, at.z, at.y, at);
      const to = this.farSite(home.kind, home.name, home.x, home.z, home.y, at);
      const cells = Math.max(Math.abs(Math.floor(at.x / N) - home.cx), Math.abs(Math.floor(at.z / N) - home.cz));
      const value = this.longValue(cells);
      const ret: CargoItem = {
        id: this.nextId++, type: it.type, w: at.w, lx: from.lx, lz: from.lz, x: at.x, z: at.z, y: at.y, from, to, urgency: 'none',
        value, value0: value, ttl: Infinity, life: Infinity, claimedBy: -uid, claimName: name, marker: null, born: this.time,
        longHaul: { cell: [home.cx, home.cz], cells },
      };
      this.carried.add(ret);
      out.push(ret);
    }
    return out;
  }

  /** A far run's load as a save keeps it (its kind, value and where it is bound), aboard again on load; null for a kind gone. */
  farCarried(k: { type: string; value: number; to: { name: string; kind: string; x: number; z: number; cx: number; cz: number } }, uid: number, name: string): CargoItem | null {
    const t = CARGO.find((q) => q.id === k.type);
    const w = this.islands[0];
    if (!t || !w) return null;
    const near = { w } as Site;
    const to = this.farSite(k.to.kind as SiteKind, k.to.name, k.to.x, k.to.z, 0, near);
    const it: CargoItem = {
      id: this.nextId++, type: t, w, lx: to.lx, lz: to.lz, x: to.x, z: to.z, y: 0, from: to, to, urgency: 'none',
      value: k.value, value0: k.value, ttl: Infinity, life: Infinity, claimedBy: -uid, claimName: name, marker: null, born: this.time,
      longHaul: { cell: [k.to.cx, k.to.cz], cells: 5 },
    };
    this.carried.add(it);
    return it;
  }

  /** How much of a station's beat stock is waiting, for the console and the gate: units by station name. */
  beatWaiting(): Record<string, number> {
    const out: Record<string, number> = {};
    for (const it of this.items) if (it.type.beat && it.from) out[it.from.name] = (out[it.from.name] ?? 0) + it.type.units;
    return out;
  }

  /** Hold goods for a vehicle on its way; with `deadline`, only for that many seconds (a manifest's claim). */
  claim(it: CargoItem, agent: number, name: string, deadline?: number): void {
    it.claimedBy = agent;
    it.claimName = name;
    it.claimUntil = deadline === undefined ? undefined : this.time + deadline;
  }

  release(it: CargoItem, agent: number): void {
    if (it.claimedBy !== agent) return;
    it.claimedBy = 0;
    it.claimName = '';
    it.claimUntil = undefined;
  }

  /** The CPU vehicle has arrived: take the goods off the ground if they're still there for it. */
  collect(it: CargoItem, agent: number): boolean {
    // still there and nobody else's: a claim that lapsed on the way (a manifest's deadline, a driver held up in
    // traffic) is no reason to drive off without it; the user watched a driver pull up to a load and leave it (19 Oct 2026)
    if (!this.items.includes(it) || (it.claimedBy && it.claimedBy !== agent)) return false;
    it.claimedBy = agent;
    if (rivalClaim(agent) && this.nearPlayer(it)) this.onRivalTook?.(it, agent);
    this.unplace(it);
    it.claimUntil = undefined;
    this.carried.add(it);
    return true;
  }

  /** Goods the player can see, waiting within RIVAL_SEEN tiles of where they were last frame. */
  private nearPlayer(it: CargoItem): boolean {
    return !!this.home && this.shown(it) && Math.hypot(it.x - this.lastVeh.x, it.z - this.lastVeh.z) <= RIVAL_SEEN;
  }

  /** A load has left a driver's hold some way other than delivery or being set down: it stops ticking. */
  uncarry(it: CargoItem): void { this.carried.delete(it); }

  /** A hired driver's load passes to the player as they take the wheel. */
  takeAboard(it: CargoItem): void {
    this.carried.delete(it);
    if (!this.hold.includes(it)) this.hold.push(it);
  }

  /**
   * How many more loads the fleet may claim on this island: it never holds claims on more than half
   * of what is waiting there, so the board stays readable for the player driving on it.
   */
  fleetRoom(w: World): number {
    let waiting = 0, mine = 0;
    for (const it of this.items) {
      if (it.w !== w || it.claimedBy === CHAIN_CLAIM) continue;
      waiting++;
      if (fleetClaim(it.claimedBy)) mine++;
    }
    return Math.floor(waiting / 2) - mine;
  }

  /** How many more loads the rival firms together may claim on this island: never more than a third of what waits there. */
  firmRoom(w: World): number {
    let waiting = 0, theirs = 0;
    for (const it of this.items) {
      if (it.w !== w || it.claimedBy === CHAIN_CLAIM) continue;
      waiting++;
      if (rivalClaim(it.claimedBy)) theirs++;
    }
    return Math.floor(waiting / 3) - theirs;
  }

  /**
   * A rival firm's driver has delivered: the towns take their levy (half, where the firm is preferred),
   * the books count the trade as the firm's, and the net is returned for the firm to split with its driver.
   */
  deliverFirm(it: CargoItem, at: { x: number; y: number; z: number }, firm: string, name: string): number {
    const gross = Math.round(it.value);
    const rate = this.books?.taxOf(it, firm) ?? 0;
    const tax = rate > 0 ? Math.max(1, Math.round(it.value * rate)) : 0;
    const net = Math.max(0, gross - tax);
    this.carried.delete(it);
    this.cpuDelivered++;
    this.books?.delivered(it, false, 0, undefined, firm);
    this.hud.float(`+${money(net)} · ${name}`, new THREE.Vector3(at.x, at.y + 0.4, at.z), 'cpu');
    return net;
  }

  /**
   * One of the player's vehicles has delivered with a hired driver at the wheel. The towns' levy comes
   * off as it would for the player, the driver keeps their share of the rest, and the cut goes to the
   * wallet; the towns book the whole net as the player's trade. Returns what each side got.
   */
  deliverFleet(it: CargoItem, at: { x: number; y: number; z: number }, cut: number, driver: string, nose: boolean, extra = 0): { you: number; kept: number; tax: number; net: number; rep: { text: string; colour: string } | null } {
    const gross = Math.round(it.value * (nose ? 1.1 : 1) * (this.fac?.payMul(it) ?? 1) * (1 + extra));
    const rep = this.fac?.delivered(it, 'crew', at) ?? null;
    const tax = this.taxOn(it);
    const net = Math.max(0, gross - tax);
    const you = Math.round(net * cut);
    this.carried.delete(it);
    this.wallet.earn(you, 'cargo', 'crew');
    this.books?.delivered(it, true, net, driver);
    const pos = new THREE.Vector3(at.x, at.y + 0.5, at.z);
    this.hud.float(`+${money(you)} · ${driver}`, pos, 'fleet');
    if (tax > 0) this.hud.float(`−${money(tax)} tax`, pos, 'tax');
    return { you, kept: net - you, tax, net, rep };
  }

  /** What a load pays a fleet driver's split, before it is delivered: the net after tax. */
  netFleet(it: CargoItem, nose: boolean): number {
    return Math.max(0, Math.round(it.value * (nose ? 1.1 : 1) * (this.fac?.payMul(it) ?? 1)) - this.taxOn(it));
  }

  deliverCpu(it: CargoItem, at: { x: number; y: number; z: number }): void {
    this.carried.delete(it);
    this.cpuDelivered++;
    this.books?.delivered(it, false, 0);
    this.hud.float(`+${money(it.value)}`, new THREE.Vector3(at.x, at.y + 0.4, at.z), 'cpu');
  }

  /**
   * Waiting loads counted up by the town they are standing in, keyed by cell and town id. Anything
   * out in the country or down at a harbour is left out: on the overview it has nothing to sit under.
   */
  jobsByTown(): Map<string, { n: number; value: number }> {
    const out = new Map<string, { n: number; value: number }>();
    for (const it of this.items) {
      // (Ultra-Bulk work is for the player in a ride of its, not the town's board)
      if (it.type.ultra) continue;
      const x = Math.floor(it.lx), z = Math.floor(it.lz);
      if (!inB(x, z)) continue;
      const town = it.w.townId[idx(x, z)];
      if (town < 0) continue;
      const key = `${it.w.cx},${it.w.cz}#${town}`;
      const e = out.get(key);
      if (e) { e.n++; e.value += it.value; }
      else out.set(key, { n: 1, value: it.value });
    }
    return out;
  }

  /** Console: goods of type id (or any) at a random place, e.g. pr.cargo.debugSpawn('container'). */
  debugSpawn(id?: string): CargoItem | null {
    const t = cargoById(id) ?? pick(CARGO);
    return this.spawn(t, null);
  }
}
