import { DAYS_PER_YEAR } from '../render/season';

/**
 * Fleet birthdays (docs/phonelist.html item 9, the user, 10 Nov 2026): a fleet has a birthday every game year from the
 * day it was founded (the save's `founded`). All that day balloons float over every vehicle and building it owns
 * (render/fleetBadges.ts `balloons`, put on by main.ts while BIRTHDAY.on), and as the day comes round during play the
 * player is wished many happy returns with a gift of diamonds, more on the big ones: the 1st, 5th, 10th, 25th, 50th
 * and 100th.
 *
 * Only the day turning over during play pays (a game loaded on its birthday shows the balloons but pays nothing again).
 */

export const BIRTHDAY = { on: false, years: 0 };

/** The big birthdays, and what each pays in diamonds; an ordinary one pays one. */
const MILESTONES: Record<number, number> = { 1: 3, 5: 10, 10: 25, 25: 50, 50: 100, 100: 250 };

export interface BirthdayNews { years: number; diamonds: number; milestone: boolean }

let last: { day: number; on: boolean } | null = null;

/** Forget the day seen last: a new game or a load starts fresh (and pays nothing for the day it is loaded on). */
export function resetBirthday(): void { last = null; BIRTHDAY.on = false; BIRTHDAY.years = 0; }

/**
 * Called as the game runs, with the hour the fleet was founded and the game's day now: keeps BIRTHDAY up to date, and
 * returns the news the moment a birthday begins during play (else null).
 */
export function birthdayTick(foundedHour: number, days: number): BirthdayNews | null {
  const day = Math.floor(days), first = Math.floor(foundedHour / 24);
  const age = day - first;
  const on = age > 0 && age % DAYS_PER_YEAR === 0;
  const years = Math.floor(age / DAYS_PER_YEAR);
  const was = last;
  last = { day, on };
  BIRTHDAY.on = on;
  BIRTHDAY.years = on ? years : 0;
  // only the day coming round while the game runs
  if (!on || !was || was.day === day || was.on) return null;
  const milestone = years in MILESTONES;
  return { years, diamonds: MILESTONES[years] ?? 1, milestone };
}

/** "1st", "2nd", "23rd". */
export function ordinal(n: number): string {
  const s = ['th', 'st', 'nd', 'rd'], v = n % 100;
  return `${n}${s[(v - 20) % 10] ?? s[v] ?? s[0]}`;
}
