// ---- 6. the Mausoleum at Halicarnassus ----------------------------------------------------------------

const mausoleum: Draw = (k, W, D) => {
  const cz = -0.4, E = Math.min(W, D) / 2 - 0.45;
  // the precinct wall and its gateway
  k.box(0, 0, -E, 2 * E, 0.5, 0.25, LIME2);
  for (const sx of [-1, 1]) {
    k.box(sx * E, 0, 0, 0.25, 0.5, 2 * E, LIME2);
    k.box(sx * (E + 1.1) / 2, 0, E, E - 1.1, 0.5, 0.25, LIME2);
    column(k, sx * 1.0, 0, E, 1.3, 0.1, MARBLE, true);
    k.glowBox(sx * 1.6, 0, E + 0.3, 0.12, 0.06, 0.12, DARK, FLOOD, GOLD_GLOW);
  }
  k.box(0, 1.3, E, 2.4, 0.18, 0.5, MARBLE2);
  k.gable(0, 1.48, E, 2.4, 0.35, 0.5, MARBLE, MARBLE);
  // the podium, banded with friezes, lions along its cornice
  const pb = steps(k, 0, 0, cz, 7.0, 6.0, 2, 0.15, 0.2, MARBLE2);
  const ph = 2.4, pw = 6.2, pd = 5.2;
  k.box(0, pb, cz, pw, ph, pd, MARBLE2);
  k.box(0, pb + 0.7, cz, pw + 0.02, 0.22, pd + 0.02, RED);
  k.box(0, pb + 1.95, cz, pw + 0.02, 0.3, pd + 0.02, BLUE);
  for (let i = 0; i < 12; i++) k.box(-pw / 2 + 0.3 + i * ((pw - 0.6) / 11), pb + 2.0, cz + pd / 2 + 0.02, 0.12, 0.2, 0.02, GOLD);
  const ct = pb + ph;
  k.box(0, ct, cz, pw + 0.3, 0.15, pd + 0.3, MARBLE);
  const lion = (x: number, z: number, yaw: number) => k.turned(yaw, () => {
    const c = Math.cos(-yaw), s = Math.sin(-yaw), lx = x * c + z * s, lz = -x * s + z * c;
    k.box(lx, ct + 0.15, lz, 0.18, 0.2, 0.42, GOLD2);
    k.box(lx, ct + 0.28, lz + 0.2, 0.2, 0.2, 0.16, GOLD2);
  });
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    lion(sx * (pw / 2 - 0.1), cz + sz * (pd / 2 - 0.5), sz > 0 ? 0 : Math.PI);
    lion(sx * (pw / 2 - 1.1), cz + sz * (pd / 2 + 0.05), sz > 0 ? 0 : Math.PI);
  }
  // the colonnade round the tomb chamber
  const cy = ct + 0.15, CH = 1.6;
  k.box(0, cy, cz, 4.4, CH, 3.4, MARBLE);
  k.box(0, cy, cz + 1.71, 0.8, 1.2, 0.02, ARCH);
  for (let i = 0; i < 7; i++) for (let j = 0; j < 6; j++) {
    if (i > 0 && i < 6 && j > 0 && j < 5) continue;
    column(k, -2.7 + i * 0.9, cy, cz - 2.2 + j * 0.88, CH, 0.13, MARBLE, true);
  }
  for (let i = 0; i < 6; i++) figure(k, -2.25 + i * 0.9, cy, cz + 2.2, 0.62, MARBLE, false);
  const ey = cy + CH;
  k.box(0, ey, cz, 6.0, 0.4, 5.0, MARBLE);
  k.box(0, ey + 0.2, cz, 6.02, 0.1, 5.02, BLUE);
  // the stepped pyramid roof
  const n = 12, sh = 0.14;
  for (let i = 0; i < n; i++) {
    const f = i / n;
    k.box(0, ey + 0.4 + i * sh, cz, 6.0 - 4.2 * f, sh, 5.0 - 3.6 * f, scale(MARBLE, 0.92 + (i % 2) * 0.05));
  }
  // the four-horse chariot on the top
  const qy = ey + 0.4 + n * sh, qz = cz;
  k.box(0, qy, qz, 1.7, 0.2, 1.3, MARBLE2);
  const ry = qy + 0.2;
  for (let i = 0; i < 4; i++) {
    const x = -0.5 + i * 0.33;
    k.box(x, ry + 0.28, qz + 0.15, 0.16, 0.24, 0.5, BRONZE);
    k.box(x, ry, qz - 0.03, 0.12, 0.3, 0.1, BRONZE2);
    k.box(x, ry, qz + 0.33, 0.12, 0.3, 0.1, BRONZE2);
    k.bar([x, ry + 0.45, qz + 0.35], [x, ry + 0.72, qz + 0.5], 0.06, BRONZE);
  }
  k.box(0, ry, qz - 0.42, 0.7, 0.36, 0.34, BRONZE2);
  for (let w = 0; w < 2; w++) k.cyl(-0.38 + w * 0.76, ry, qz - 0.42, 0.18, 0.06, BRONZE2, 8);
  figure(k, -0.15, ry + 0.2, qz - 0.42, 0.62, BRONZE);
  figure(k, 0.17, ry + 0.2, qz - 0.48, 0.55, BRONZE, false);
  // cypresses in the precinct's corners, floods round the podium
  for (const [x, z] of [[-E + 0.7, -E + 0.7], [E - 0.7, -E + 0.7], [-E + 0.7, E - 1.4], [E - 0.7, E - 1.4]]) cypress(k, x, 0, z, 1.3);
  floods(k, -3.3, cz + 3.25, 3.3, cz + 3.25, 4);
  floods(k, -3.3, cz - 3.25, 3.3, cz - 3.25, 3);
  floods(k, -3.8, cz - 2, -3.8, cz + 2, 3);
  floods(k, 3.8, cz - 2, 3.8, cz + 2, 3);
};

export const ANCIENT_DRAW: Record<AncientKind, Draw> = { colossus, pharos, hangingGardens, templeArtemis, statueZeus, mausoleum };
