import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, GLASS, METAL, TAU, WARM_GLOW, WHITE, WOOD, type Draw, type Kit, type P3 } from '../kit';

/**
 * The Fjordlands: a boat shed at the water's edge, a salmon farm's net pens, a fisherman's cabin on
 * stilts with cod on the rack, and the white A-frame cathedral. Falu red and ochre boards, grey rock,
 * deep green water.
 */

const FALU = hex(0x8e2a1e), OCHRE = hex(0xc08a2c), GREY_BOARD = hex(0x6e6a64), ROOF = hex(0x2a2c30), SLATE = hex(0x3c4046);
const ROCK = hex(0x74777a), ROCK_DARK = hex(0x5c5f63), SEA = hex(0x2f6878), SEA_DEEP = hex(0x25525f), TURF = hex(0x5e8a44);
const PILE = hex(0x5a4632), COD = hex(0xd9cfb4), NET = hex(0x2c3034), FLOAT = hex(0xe8a02c);
const CONCRETE = hex(0xfaf8f2), PAVE = hex(0x8a8984), PAVE_EDGE = hex(0x6e6d69), BIRCH = hex(0xeeeade), BIRCH_LEAF = hex(0x7fae4a);
const EVENING: Sched = [18, 23.5, 1.4], LATE: Sched = [17, 25, 1.6];

/** A small open boat lying along z, bow toward +z: a hull, a pointed bow, thwarts. */
function rowboat(k: Kit, x: number, y: number, z: number, len: number, w: number, col: RGB): void {
  const h = 0.06, body = len * 0.62;
  k.box(x, y, z - len * 0.19, w, h, body, col, scale(WOOD, 0.8));
  const zb = z + len * 0.12, tip: P3 = [x, y + h * 1.25, zb + len * 0.38], I: P3 = [x, y + h / 2, zb + 0.02];
  k.tri([x - w / 2, y + h, zb], [x + w / 2, y + h, zb], tip, scale(WOOD, 0.8), [x, y, zb]);
  k.quad([x - w / 2, y, zb], [x - w / 2, y + h, zb], tip, [x, y, zb + len * 0.3], col, I);
  k.quad([x + w / 2, y, zb], [x + w / 2, y + h, zb], tip, [x, y, zb + len * 0.3], col, I);
  for (const t of [-0.12, 0.08]) k.box(x, y + h, z + t * len - len * 0.19, w, 0.012, 0.03, col);
}

// ---- a boat shed (1 × 1) -------------------------------------------------------------------------------

/** A naust: a small timber boat shed, its big double doors in the gable facing the water, a slipway and a rowing boat. */
const boatShed: Draw = (k, _W, _D, _b, r) => {
  const wall = r() < 0.6 ? FALU : r() < 0.5 ? GREY_BOARD : OCHRE;
  const sx = -0.13, sz = -0.13, sw = 0.46, sl = 0.62, sh = 0.26;
  // a footing of rough stone, then the shed
  k.box(sx, 0, sz, sw + 0.06, 0.05, sl + 0.04, ROCK);
  k.box(sx, 0.05, sz, sw, sh, sl, wall);
  k.gable(sx, 0.05 + sh, sz, sw + 0.07, 0.22, sl + 0.06, ROOF, wall, true);
  const fz = sz + sl / 2;
  // the doors: white frame, two dark leaves, a little loft window over them
  k.box(sx, 0.05, fz + 0.004, 0.34, 0.25, 0.012, WHITE);
  for (const s of [-1, 1]) k.box(sx + s * 0.078, 0.05, fz + 0.012, 0.145, 0.225, 0.01, scale(wall, 0.62));
  k.box(sx, 0.35, fz + 0.035, 0.08, 0.08, 0.01, WHITE);
  k.pane(sx, 0.36, fz + 0.04, 0.055, 0.055, 1, DARK, EVENING, WARM_GLOW);
  for (const s of [-1, 1]) k.box(sx + s * (sw / 2 - 0.012), 0.05, fz + 0.004, 0.03, sh, 0.012, WHITE);
  // the slipway: two runners down to the water's edge and the ties under them
  for (const s of [-1, 1]) k.bar([sx + s * 0.11, 0.06, fz], [sx + s * 0.11, 0.02, 0.47], 0.016, PILE);
  for (let i = 0; i < 4; i++) k.box(sx, 0.005, fz + 0.05 + i * 0.075, 0.32, 0.03 - i * 0.004, 0.035, WOOD);
  // a rowing boat drawn up beside it, oars across
  rowboat(k, 0.3, 0.015, 0.05, 0.46, 0.13, WHITE);
  k.bar([0.22, 0.09, -0.12], [0.4, 0.09, 0.12], 0.008, WOOD);
  // a few shore rocks
  for (const [rx, rz, s] of [[0.36, -0.36, 0.13], [0.22, -0.4, 0.08], [-0.42, 0.4, 0.09]] as const) k.box(rx, 0, rz, s, s * 0.5, s * 0.8, ROCK_DARK, ROCK);
};

// ---- a fish farm (3 × 3) -------------------------------------------------------------------------------

/** A floating net pen: a fat black ring, a handrail, and a bird net strung up to a pole in the middle. */
function pen(k: Kit, x: number, z: number, rad: number): void {
  k.cyl(x, 0.03, z, rad - 0.02, 0.008, SEA_DEEP, 12);
  k.hoop(x, 0.05, z, rad, 0.032, NET, 12, 'xz');
  k.hoop(x, 0.17, z, rad, 0.01, METAL, 12, 'xz');
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU, px = x + Math.cos(a) * rad, pz = z + Math.sin(a) * rad;
    k.box(px, 0.05, pz, 0.02, 0.12, 0.02, METAL);
    k.bar([px, 0.17, pz], [x, 0.36, z], 0.007, WHITE);
    const b = a + TAU / 12;
    k.bar([x + Math.cos(b) * rad, 0.17, z + Math.sin(b) * rad], [x, 0.36, z], 0.007, WHITE);
  }
  k.box(x, 0.03, z, 0.025, 0.34, 0.025, NET);
  k.box(x, 0.03, z, 0.09, 0.05, 0.09, FLOAT);
}

/** A salmon farm from the bank: round net pens on the water, a feed barge with its silo, a walkway out from the shore. */
const fishFarm: Draw = (k, W, D) => {
  const hd = D / 2, shore = -hd + 0.5;
  // the bank along the back, the water in front of it
  k.box(0, 0, (shore + hd - 0.1) / 2, W - 0.2, 0.03, hd - 0.1 - shore, SEA);
  k.box(0, 0, (-hd + 0.1 + shore) / 2, W - 0.2, 0.07, shore + hd - 0.1, ROCK, TURF);
  for (const [rx, s] of [[-1.1, 0.16], [-0.5, 0.11], [0.95, 0.14], [1.25, 0.1]] as const) k.box(rx, 0, shore + 0.02, s * 1.4, s * 0.5, s, ROCK_DARK, ROCK);
  // the pens
  const pens: [number, number, number][] = [[-0.78, 0.72, 0.5], [0.5, 0.82, 0.46], [-0.72, -0.4, 0.4]];
  for (const [px, pz, pr] of pens) pen(k, px, pz, pr);
  // the feed barge: a grey pontoon, a red hut and a silo
  const bx = 0.78, bz = -0.28;
  k.box(bx, 0.03, bz, 0.84, 0.09, 0.56, SLATE, PAVE);
  k.box(bx - 0.2, 0.12, bz - 0.02, 0.3, 0.2, 0.34, FALU);
  k.gable(bx - 0.2, 0.32, bz - 0.02, 0.34, 0.1, 0.38, ROOF, FALU, true);
  k.pane(bx - 0.2, 0.2, bz + 0.15, 0.16, 0.08, 1, DARK, LATE, WARM_GLOW);
  k.box(bx - 0.2 + 0.151, 0.12, bz - 0.08, 0.01, 0.16, 0.08, WHITE);
  k.cyl(bx + 0.2, 0.2, bz - 0.04, 0.13, 0.3, METAL, 8);
  k.cone(bx + 0.2, 0.5, bz - 0.04, 0.13, 0.08, scale(METAL, 0.85), 8);
  k.cone(bx + 0.2, 0.2, bz - 0.04, 0.13, -0.08, scale(METAL, 0.8), 8);
  for (const [lx, lz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) k.box(bx + 0.2 + lx * 0.1, 0.12, bz - 0.04 + lz * 0.1, 0.025, 0.1, 0.025, DARK);
  // feed hoses out to each pen, floating on the water
  for (const [px, pz] of pens) k.bar([bx - 0.05, 0.13, bz + 0.2], [px, 0.2, pz], 0.012, NET);
  // the walkway: out from the bank to the barge, and on between the pens
  const wy = 0.06;
  k.box(0.2, wy, (shore + bz) / 2 - 0.1, 0.14, 0.035, bz - shore + 0.2, WOOD);
  k.box(0.28, wy, bz, 0.3, 0.035, 0.14, WOOD);
  k.box(-0.12, wy, 0.18, 0.14, 0.035, 0.9, WOOD);
  k.box(-0.05, wy, 0.18, 0.64, 0.035, 0.14, WOOD);
  for (const z of [shore + 0.1, bz]) k.box(0.2 + 0.06, wy, z - 0.18, 0.02, 0.13, 0.02, PILE);
  k.bar([0.26, wy + 0.13, shore], [0.26, wy + 0.13, bz - 0.1], 0.008, PILE);
  // a workboat tied up at the barge
  rowboat(k, bx + 0.58, 0.03, bz - 0.02, 0.42, 0.13, OCHRE);
};

// ---- a rorbu (1 × 1) -----------------------------------------------------------------------------------

/** A fisherman's cabin: falu red with white trim, half of it out over the water on piles, a deck, and cod on the drying rack. */
const rorbu: Draw = (k, W, D) => {
  const hd = D / 2;
  // rock behind, water in front
  k.box(0, 0, 0.2, W - 0.1, 0.025, hd - 0.05 + 0.25, SEA);
  k.box(0, 0, -0.25, W - 0.1, 0.13, 0.4, ROCK_DARK, ROCK);
  k.box(-0.3, 0, -0.02, 0.22, 0.09, 0.12, ROCK_DARK, ROCK);
  // the floor and deck, on piles where it leaves the rock
  const fy = 0.15, cx = -0.08, cz = -0.04, cw = 0.48, cl = 0.58, ch = 0.26;
  k.box(cx + 0.03, fy - 0.025, 0.12, cw + 0.22, 0.025, 0.66, WOOD);
  for (const px of [cx - 0.26, cx + 0.03, cx + 0.34]) for (const pz of [0.02, 0.22, 0.42]) k.box(px, 0, pz, 0.035, fy - 0.02, 0.035, PILE);
  // the cabin
  k.box(cx, fy, cz, cw, ch, cl, FALU);
  k.gable(cx, fy + ch, cz, cw + 0.07, 0.2, cl + 0.06, ROOF, FALU, true);
  const fz = cz + cl / 2, ex = cx + cw / 2;
  for (const [px, pz] of [[cx - cw / 2, fz], [ex, fz], [cx - cw / 2, cz - cl / 2], [ex, cz - cl / 2]] as const) k.box(px, fy, pz, 0.03, ch, 0.03, WHITE);
  // door and window to the deck, a window down the side, all trimmed white
  k.box(cx - 0.11, fy, fz + 0.004, 0.1, 0.19, 0.012, WHITE);
  k.box(cx - 0.11, fy, fz + 0.012, 0.07, 0.17, 0.008, scale(FALU, 0.6));
  k.box(cx + 0.1, fy + 0.08, fz + 0.004, 0.13, 0.11, 0.012, WHITE);
  k.pane(cx + 0.1, fy + 0.095, fz + 0.011, 0.1, 0.08, 1, DARK, EVENING, WARM_GLOW);
  k.box(cx, fy + ch + 0.04, fz + 0.034, 0.07, 0.07, 0.01, WHITE);
  for (const wz of [cz - 0.12, cz + 0.14]) {
    k.box(ex + 0.004, fy + 0.08, wz, 0.012, 0.11, 0.13, WHITE);
    k.pane(ex + 0.011, fy + 0.095, wz, 0.1, 0.08, 0, DARK, EVENING, WARM_GLOW);
  }
  // the deck rail along the water
  const dz = 0.43;
  for (const px of [cx - 0.3, cx + 0.03, cx + 0.36]) k.box(px, fy, dz, 0.022, 0.11, 0.022, WHITE);
  k.bar([cx - 0.3, fy + 0.11, dz], [cx + 0.36, fy + 0.11, dz], 0.01, WHITE);
  // the drying rack on the rock: two trestles, a pole, a row of split cod
  const rx = 0.34, z0 = -0.4, z1 = -0.04, top = 0.5;
  for (const z of [z0, z1]) for (const s of [-1, 1]) k.bar([rx + s * 0.09, 0.12, z], [rx, top, z], 0.012, PILE);
  k.bar([rx, top, z0 - 0.04], [rx, top, z1 + 0.04], 0.012, PILE);
  for (let i = 0; i < 6; i++) k.box(rx, top - 0.13, z0 + 0.04 + i * 0.056, 0.035, 0.12, 0.022, i % 2 ? COD : scale(COD, 0.88));
  // a stove pipe
  k.box(cx - 0.1, fy + ch + 0.1, cz - 0.12, 0.03, 0.16, 0.03, DARK);
};

// ---- the arctic cathedral (the wonder, 12 × 12) --------------------------------------------------------

/** A birch: a white stem and a light, open crown. */
function birch(k: Kit, x: number, y: number, z: number, s: number): void {
  k.box(x, y, z, 0.06 * s, 0.6 * s, 0.06 * s, BIRCH);
  k.band(x, z, y + 0.4 * s, 0.1 * s, y + 0.62 * s, 0.26 * s, 7, scale(BIRCH_LEAF, 0.85));
  k.band(x, z, y + 0.62 * s, 0.26 * s, y + 0.95 * s, 0.17 * s, 7, BIRCH_LEAF);
  k.cone(x, y + 0.95 * s, z, 0.17 * s, 0.16 * s, scale(BIRCH_LEAF, 1.1), 7);
}

/**
 * The Arctic Cathedral: a run of tall white triangular slabs stepping down from the front, glass between
 * them, and the whole front gable one wall of glass behind a slim cross, warm after dark. It stands on a
 * paved terrace up a flight of steps.
 */
const arcticCathedral: Draw = (k, W, D) => {
  const hw = W / 2, hd = D / 2;
  // the terrace, its steps down to the road, low walls round the other three sides
  const ty = 0.22, tw = W - 1.4, tz0 = -hd + 0.5, tz1 = hd - 1.5, tc = (tz0 + tz1) / 2;
  k.box(0, 0, tc, tw, ty, tz1 - tz0, PAVE_EDGE, PAVE);
  for (let i = 0; i < 3; i++) k.box(0, 0, tz1 + 0.14 + i * 0.26, 4.6, ty - (i + 1) * 0.055, 0.28, PAVE_EDGE, PAVE);
  k.box(0, ty, tz0 + 0.1, tw, 0.22, 0.16, CONCRETE);
  for (const s of [-1, 1]) {
    k.box(s * (tw / 2 - 0.08), ty, tc, 0.16, 0.22, tz1 - tz0, CONCRETE);
    k.box(s * (tw / 4 + 1.2), ty, tz1 - 0.08, tw / 2 - 2.4, 0.22, 0.16, CONCRETE);
  }
  k.box(0, ty, tz1 - 2.0, 2.2, 0.012, 3.6, hex(0xb4b0a6));
  // the slabs: each a white triangular prism, tallest at the front, stepping down toward the choir and
  // up again a little over it
  const n = 9, pitch = 0.86, zf = 2.2, slope = 2.2;
  const width = (i: number) => (i < 7 ? 5.0 - i * 0.3 : 3.2 + (i - 6) * 0.35);
  for (let i = 0; i < n; i++) {
    const w = width(i), z = zf - 0.3 - i * pitch;
    k.gable(0, ty, z, w, (w / 2) * slope, 0.6, CONCRETE, i === 0 ? CONCRETE : scale(CONCRETE, 0.9), true);
    // the strip of glass between this slab and the next, set in from both
    if (i < n - 1) {
      const gw = Math.min(w, width(i + 1)) - 0.3;
      k.gable(0, ty, z - pitch / 2, gw, (gw / 2) * slope, pitch - 0.58, GLASS, GLASS, true);
    }
  }
  // the front: glass from the floor to the peak, in rows between white mullions, and the cross before it
  const fw = width(0), fh = (fw / 2) * slope, rows = 13, rh = (fh - 0.5) / rows;
  for (let j = 0; j < rows; j++) {
    const y0 = ty + 0.12 + j * rh, half = (fw / 2) * (1 - (y0 + rh - 0.05 - ty) / fh) - 0.12;
    if (half < 0.12) continue;
    const cols = Math.max(1, Math.round((half * 2) / 0.62)), pw = (half * 2) / cols;
    for (let c = 0; c < cols; c++) {
      const px = -half + (c + 0.5) * pw;
      if (j < 3 && Math.abs(px) < 0.55) continue;   // the doors
      k.pane(px, y0, zf + 0.004, pw - 0.05, rh - 0.05, 1, GLASS, LATE, WARM_GLOW);
    }
  }
  k.box(0, ty, zf + 0.06, 0.1, fh - 0.35, 0.07, CONCRETE);
  k.box(0, ty + fh * 0.58, zf + 0.06, 1.5, 0.1, 0.07, CONCRETE);
  // the doors under a flat canopy
  k.box(0, ty, zf + 0.03, 1.0, 0.95, 0.04, hex(0x6a4a30));
  k.box(0, ty, zf + 0.055, 0.04, 0.95, 0.02, DARK);
  k.box(0, ty + 0.97, zf + 0.3, 1.5, 0.07, 0.6, CONCRETE);
  for (const s of [-1, 1]) k.box(s * 0.68, ty, zf + 0.54, 0.07, 0.97, 0.07, CONCRETE);
  // lamps down the forecourt, birches along the sides
  for (const s of [-1, 1]) {
    for (const lz of [tz1 - 0.5, tz1 - 2.0]) {
      k.box(s * 1.5, ty, lz, 0.05, 0.5, 0.05, DARK);
      k.glowBox(s * 1.5, ty + 0.5, lz, 0.12, 0.1, 0.12, WHITE, [17.5, 30.5, 1.5], WARM_GLOW);
    }
    for (const [bz, bs] of [[tz1 - 1.0, 1.6], [0.6, 2.0], [-1.8, 1.7], [-3.9, 2.1]] as const) birch(k, s * (tw / 2 - 0.85), ty, bz, bs);
    birch(k, s * (hw - 0.4), 0, hd - 0.9, 1.4);
  }
};

export const FJORDS_DRAW: Partial<Record<RegionBuildingKind, Draw>> = { boatShed, fishFarm, rorbu, arcticCathedral };
