import type { Building, BuildingKind, World } from '../world/tiles';
import { MODEL_NAMES } from './buildings/kit';
import { TRADE_NAMES, tradeOf } from './buildings/roofIcons';
import { kindDrawing, modelOf } from './townMesh';

/**
 * What a building's model makes it, when that is more particular than its kind (the user, 9 Nov 2026): a shop
 * with a key on its roof is a Locksmith, a shack drawn as a bait shop a Bait Shop, a police station in a
 * Japanese town a Kōban. `name` is the model's own name (kit MODEL_NAMES); `kind` is set instead when the model
 * is another kind's own (a lakeside chippy drawn as a diner), for the caller to name as that kind. Null when it
 * is just its kind. The storefronts (Auto Shop, dealer, tavern) keep their own names.
 */
export function modelName(w: World | null, b: Building): { name: string } | { kind: BuildingKind } | null {
  // a storefront, or a kind asked for by itself ({ kind } as Building: a key's labels)
  if (b.storefront || b.seed === undefined) return null;
  // the trade on its roof (roofIcons.ts), whichever of the shop models it is
  if (b.kind === 'shop') return { name: TRADE_NAMES[tradeOf(b)] };
  if (!w) return null;
  const d = modelOf(w, b);
  const name = MODEL_NAMES.get(d);
  if (name) return { name };
  const kind = kindDrawing(d);
  return kind && kind !== b.kind ? { kind } : null;
}
