import { N, idx, inB, type World } from '../world/tiles';
import type { Happening } from './events/calendar';
import { KIND_OF } from './events/kinds';
import { nearestRoad } from './nearRoad';

/**
 * Meteorites (the user, 27 Oct 2026): a meteor shower (game/events) leaves a few stones on the ground round where
 * it was watched, and for a day after it they wait there as the Visitors' cultural goods (game/culture.ts): carried
 * home to the HQ they raise the town's Visitors culture like any other import.
 *
 * Where they fall is worked out from the shower and its county alone, as the shower itself is, so every player
 * online sees the same craters; what is picked up is each player's own (culture lives in the player's save), so one
 * player taking a stone home never takes it from another.
 *
 * Headless: the host gives the county and the shower's middle, so the gate can run it (npm run culture).
 */

export const METEOR = {
  /** Game hours a stone waits after the shower ends. */
  keep: 24,
  /** Stones a shower leaves: 3 to 5. */
  fewest: 3, most: 5,
  /** How far from the shower's middle they come down, tiles. */
  near: 6, far: 34,
  /** The furthest a stone lies from a road, tiles: off-road, never out of reach. */
  road: 7,
};

/** One stone: where it came down and when, and its place in the shower's fall. */
export interface Fall {
  /** `<shower id>#<n>`: the same for every player. */
  id: string;
  n: number;
  cx: number; cz: number;
  /** World tiles. */
  x: number; z: number;
  /** The game hour it comes down. */
  t: number;
  /** The game hour it is gone. */
  until: number;
}

const u01 = (h: number, k: number): number => {
  let x = Math.imul(h ^ Math.imul(k + 1, 0x9e3779b1), 0x85ebca6b);
  x ^= x >>> 13; x = Math.imul(x, 0xc2b2ae35); x ^= x >>> 16;
  return (x >>> 0) / 4294967296;
};

/** Open, dry, unbuilt ground a car can drive onto: every edge of the tile drivable, and a road near. */
function landable(w: World, lx: number, lz: number): boolean {
  if (!inB(lx, lz)) return false;
  const i = idx(lx, lz);
  if (w.water[i] >= 0 || w.blocked[i] || w.road[i] > 0 || w.edges[i] !== 15) return false;
  return nearestRoad(w, lx + 0.5, lz + 0.5, METEOR.road) >= 0;
}

/** The stones a shower over `w` leaves, round `mid` (world tiles): the same every time it is asked. */
export function fallsOf(e: Happening, w: World, mid: { x: number; z: number }): Fall[] {
  if (e.kind !== 'meteorShower') return [];
  const n = METEOR.fewest + Math.floor(u01(e.h, 701) * (METEOR.most - METEOR.fewest + 1));
  const dur = e.end - e.start || KIND_OF.meteorShower.dur;
  const out: Fall[] = [];
  const taken: { x: number; z: number }[] = [];
  for (let k = 0, tries = 0; k < n && tries < 60 * n; tries++) {
    const a = u01(e.h, 800 + tries * 2) * Math.PI * 2;
    const r = METEOR.near + Math.sqrt(u01(e.h, 801 + tries * 2)) * (METEOR.far - METEOR.near);
    const gx = mid.x + Math.cos(a) * r, gz = mid.z + Math.sin(a) * r;
    const lx = Math.floor(gx - w.ox), lz = Math.floor(gz - w.oz);
    if (lx < 0 || lz < 0 || lx >= N || lz >= N || !landable(w, lx, lz)) continue;
    // spread out: never two within a few tiles
    if (taken.some((q) => Math.hypot(q.x - lx, q.z - lz) < 5)) continue;
    taken.push({ x: lx, z: lz });
    // they come down through the night's shower, a stone every so often
    const t = e.start + dur * (0.15 + 0.7 * ((k + u01(e.h, 900 + k) * 0.8) / n));
    out.push({ id: `${e.id}#${k}`, n: k, cx: w.cx, cz: w.cz, x: w.ox + lx + 0.5, z: w.oz + lz + 0.5, t, until: e.end + METEOR.keep });
    k++;
  }
  return out;
}
