import type { TownKind } from '../world/tiles';
import { press } from './press/desk';
import { CARRIAGE, Carriage, YOU } from './carriage';
import { DEEDS, TIER_COLOURS, TIER_POINTS, TIERS, type Deeds } from './deeds';

/**
 * Territory (docs/territory.html, docs/standing.html). A town's territory is the top rung of the carriage
 * ladder (game/carriage.ts): 35% of its trade and a 1.25× lead over the next fleet, kept down to 28%. On top
 * of that, the town's property: a holder that owns over 5% of it and 1.25× the next fleet's holdings (kept
 * while it has 4% and is still the top owner) holds it as strong territory; a holder out-owned by another
 * fleet with over 5% of the town (until that fleet drops under 4% or the holder catches up) holds it
 * contested, and nobody is paid for it. Every other town the player holds pays diamonds by the game hour, by
 * its size; every deed tier pays its points; and diamonds are spent on the tech trees (game/tech.ts).
 *
 * Shares are the carriage's, which gives far towns their background trade, so a town the player has stopped
 * serving slips back to nobody's over hours. Property is judged on the island in memory and remembered, so a
 * far town is judged on what was last seen of it.
 */
export const TERRITORY = {
  /** The holder's share of the town's property value that makes it strong (or another's that contests it), and keeps it so. */
  strong: 0.05, strongKeep: 0.04,
  /** The holder's lead over the next fleet's property that strong needs. */
  strongLead: 1.25,
  /** Diamonds a game day, weak and strong, by the kind of town (measured: docs/territory.html, "The analysis"). */
  yield: { rural: 1, suburb: 2, city: 4, metro: 8, mega: 20 } as Record<TownKind, number>,
  strongYield: { rural: 2, suburb: 3, city: 6, metro: 12, mega: 30 } as Record<TownKind, number>,
  /** The first town a save ever takes pays this on the spot. */
  firstTown: 5,
  /** Scales the background trade of towns not being simulated: halve it and far towns hold ~70 h longer. */
  away: 1,
  /** A held town this many game hours from slipping gets its warning card. */
  warnHours: 24,
};

/** What a town is worth, and who owns what of it: from the island in memory. */
export interface Property { total: number; by: Map<string, number> }

/** One town as territory sees it: its holder, and what was last seen of its property. */
export interface Holding {
  /** The holder ('' for nobody), whether strong, and the game day it was taken. */
  who: string; strong: boolean; since: number;
  /** The town's property value, and each named owner's part of it, when last judged in memory. */
  value: number; own: Record<string, number>;
  /** Its kind, as last known. */
  kind: TownKind;
  /** The fleet that out-owns the holder there, contesting it ('' for none). */
  contested: string;
  /** The slipping card has been shown for this spell of neglect. */
  warned?: boolean;
}

interface TerritoryHost {
  carriage: Carriage;
  /** The game clock in hours. */
  hours(): number;
  /** A town's kind, from the island in memory or the atlas; null if it isn't known. */
  kindOf(key: string): TownKind | null;
  /** A town's name, for the cards. */
  nameOf(key: string): string;
  /** A town's property, while its island is in memory; null otherwise. */
  property(key: string): Property | null;
  /** A carrier's name, for the cards. */
  carrierName(who: string): string;
  announce(title: string, body: string): void;
  /**
   * The balance changed: `whole` whole diamonds came in (0 for a spend, or an hour's pay that didn't
   * cross a whole one), in the fleet's colour for a town or the tier's for a deed.
   */
  paid(whole: number, source: 'town' | 'deed' | 'bonus', colour?: string): void;
}

/** The saved form. */
export interface SavedTerritory {
  diamonds: number;
  earned: number;
  firstTown: boolean;
  deedsPaid: string[];
  towns: Record<string, [string, number, number, number, Record<string, number>, string, string?]>;
  /** The diamonds' account (the HQ's Diamonds tab). Optional: a save from before it starts one. */
  ledger?: GemLedger;
}

/**
 * One line of the diamonds' account: the game hour, how many (spent ones negative), what kind, what for, and
 * the town key it came from. A town's hourly pay is gathered into one line a town a game day.
 */
export interface GemEntry { h: number; n: number; kind: 'town' | 'deed' | 'bonus' | 'spend' | 'pvp'; what: string; key?: string }
/** The account: its latest lines, and lifetime totals by what paid (or what was bought), since `from` (game hour). */
interface GemLedger {
  recent: GemEntry[];
  towns: Record<string, number>;
  deeds: number;
  tiers: number;
  bonus: Record<string, number>;
  spent: Record<string, number>;
  /** PvP Challenge boards held (docs/challenges.html), by board name. Optional: an account from before them has none. */
  pvp?: Record<string, number>;
  from: number;
}
const LEDGER_KEEP = 120;
const blankLedger = (h: number): GemLedger => ({ recent: [], towns: {}, deeds: 0, tiers: 0, bonus: {}, spent: {}, from: h });

const round2 = (n: number) => Math.round(n * 100) / 100;
const round4 = (n: number) => Math.round(n * 1e4) / 1e4;

export class Territory {
  /** The balance, to the fraction (the hourly pay is fractional); the chip shows whole diamonds. */
  diamonds = 0;
  /** The diamonds' account: where every one came from and went (the HQ's Diamonds tab). */
  ledger: GemLedger = blankLedger(0);
  /** Everything ever paid in; spending never lowers it. */
  earned = 0;
  firstTown = false;
  /** "deedId:tier" already paid into this save. */
  readonly deedsPaid = new Set<string>();
  readonly towns = new Map<string, Holding>();
  /** Goes up when any town changes hands or strength: the maps redraw their layer. */
  version = 0;
  /** Told when a town changes hands: `was` and `now` are carriers, '' for nobody. */
  onChange: ((key: string, was: string, now: string) => void) | null = null;

  constructor(private host: TerritoryHost) {}

  // ---- reading ----

  /** Who holds the town ('' for nobody), whether strong, and who contests it ('' for nobody). */
  status(key: string): { who: string; strong: boolean; contested: string } {
    const h = this.towns.get(key);
    return h ? { who: h.who, strong: h.strong, contested: h.who ? h.contested : '' } : { who: '', strong: false, contested: '' };
  }

  holder(key: string): string { return this.towns.get(key)?.who ?? ''; }

  /** A town's name, near or far. */
  nameOf(key: string): string { return this.host.nameOf(key); }

  /** Every town a carrier holds. */
  heldBy(who: string): string[] {
    return [...this.towns].filter(([, h]) => h.who === who).map(([k]) => k);
  }

  /** Diamonds a game day a town pays its holder. */
  yieldOf(kind: TownKind, strong: boolean): number {
    return (strong ? TERRITORY.strongYield : TERRITORY.yield)[kind] ?? 0;
  }

  /** What the player's towns pay a game day, and how many (strong and contested among them). */
  daily(): { perDay: number; towns: number; strong: number; contested: number } {
    return this.dailyOf(YOU);
  }

  /** The same for any carrier: the maps' legend and the metrics. A contested town pays nothing. */
  dailyOf(who: string): { perDay: number; towns: number; strong: number; contested: number } {
    let perDay = 0, towns = 0, strong = 0, contested = 0;
    for (const h of this.towns.values()) {
      if (h.who !== who) continue;
      towns++;
      if (h.strong) strong++;
      if (h.contested) contested++;
      else perDay += this.yieldOf(h.kind, h.strong);
    }
    return { perDay, towns, strong, contested };
  }

  /** The town's property as last judged: its value, and each named owner's part. */
  propertyOf(key: string): { total: number; own: Record<string, number> } {
    const live = this.host.property(key);
    if (live) {
      const own: Record<string, number> = {};
      for (const [o, v] of live.by) if (o && v > 0) own[o] = v;
      return { total: live.total, own };
    }
    const h = this.towns.get(key);
    return { total: h?.value ?? 0, own: { ...(h?.own ?? {}) } };
  }

  /** The fleet other than `who` that owns the most of the town, and how much; null when nobody else owns any. */
  topOwner(key: string, who = YOU): { who: string; value: number; share: number } | null {
    const p = this.propertyOf(key);
    let top: { who: string; value: number; share: number } | null = null;
    for (const [o, v] of Object.entries(p.own)) if (o !== who && v > (top?.value ?? 0)) top = { who: o, value: v, share: p.total > 0 ? v / p.total : 0 };
    return top;
  }

  /** The player's share of a town's property, as last judged. */
  propertyShare(key: string, who = YOU): number {
    const live = this.host.property(key);
    if (live) return live.total > 0 ? (live.by.get(who) ?? 0) / live.total : 0;
    const h = this.towns.get(key);
    return h && h.value > 0 ? (h.own[who] ?? 0) / h.value : 0;
  }

  /**
   * Dollars of property more `who` would need in the town for strong territory: over 5% of it and 1.25× the
   * next fleet's holdings (buying shifts nobody else's). 0 when it has it.
   */
  propertyGap(key: string, who = YOU): number {
    const p = this.propertyOf(key);
    const mine = p.own[who] ?? 0;
    const next = this.topOwner(key, who)?.value ?? 0;
    // lots change hands, so the town's total stands
    const need = Math.max(TERRITORY.strong * p.total + 1 - mine, TERRITORY.strongLead * next - mine);
    return Math.max(0, Math.ceil(need));
  }

  /** Dollars more trade `who` must carry for the town (with everyone else as they are) to take it. 0 when they hold it. */
  tradeGap(key: string, who = YOU): number {
    return this.host.carriage.gap(key, who);
  }

  /** Game hours until the holder's share falls below the keep with no more service from them (Carriage.outlook). */
  outlook(key: string, who = YOU): number {
    return this.host.carriage.outlook(key, who, CARRIAGE.keep);
  }

  // ---- the hourly tally ----

  /**
   * The property tests for a town held by `who`: strong (over 5% and 1.25× the next fleet's holdings, kept
   * at 4% while still the top owner), or contested by the fleet that out-owns it with over 5% (until that
   * fleet is under 4% or the holder catches up). `h` is the holding as it was, for the keeps.
   */
  private judge(h: Holding, who: string): { strong: boolean; contested: string } {
    if (!who || !(h.value > 0)) return { strong: false, contested: '' };
    const mine = h.own[who] ?? 0;
    let top = '', topV = 0;
    for (const [o, v] of Object.entries(h.own)) if (o !== who && v > topV) { top = o; topV = v; }
    const kept = h.who === who;
    const strong = kept && h.strong
      ? mine / h.value >= TERRITORY.strongKeep && mine >= topV
      : mine / h.value > TERRITORY.strong && mine >= TERRITORY.strongLead * topV;
    const keepC = kept && h.contested === top;
    const enough = keepC ? topV / h.value >= TERRITORY.strongKeep : topV / h.value > TERRITORY.strong;
    const contested = !strong && top && topV > mine && enough ? top : '';
    return { strong, contested };
  }

  /** Once a game hour: every town with a tally takes its holder from the carriage ladder, and the player's towns pay. */
  hourly(): void {
    const carriage = this.host.carriage;
    let changed = false;
    for (const key of carriage.keys()) {
      carriage.touch(key);
      if (this.judgeTown(key, true)) changed = true;
    }
    if (changed) this.version++;
  }

  /** The carriage has given a town a new holder: judge it now, so the news comes with the load that did it. */
  turned(key: string): void {
    if (this.judgeTown(key, false)) this.version++;
  }

  /** One town: its holder from the carriage, its property tests, the news, and (`pay`) an hour's diamonds. True if it changed. */
  private judgeTown(key: string, pay: boolean): boolean {
    const day = Math.floor(this.host.hours() / 24);
    let changed = false;
    const who = this.host.carriage.preferred(key);
    const was = this.towns.get(key);
    const kind = this.host.kindOf(key) ?? was?.kind ?? null;
    const live = this.host.property(key);
    if (!who && !was) return false;
    const h: Holding = was ?? { who: '', strong: false, since: day, value: 0, own: {}, kind: kind ?? 'rural', contested: '' };
    if (kind) h.kind = kind;
    this.towns.set(key, h);
    if (live) {
      h.value = Math.round(live.total);
      h.own = {};
      for (const [o, v] of live.by) if (o && v > 0) h.own[o] = Math.round(v);
    }
    const { strong, contested } = this.judge(h, who);
    if (who !== h.who) {
      const from = h.who;
      h.who = who;
      h.since = day;
      h.warned = false;
      h.strong = false;
      h.contested = '';
      changed = true;
      this.said(key, from, who);
      this.onChange?.(key, from, who);
    }
    const name = this.host.nameOf(key);
    if (strong !== h.strong) {
      h.strong = strong;
      changed = true;
      if (who === YOU && strong) press.write({ k: 'territoryStrong', who: 'you', town: key, f: { town: name } });
      if (who === YOU && strong) this.host.announce('Strong territory', `${name} · you own ${(this.propertyShare(key) * 100).toFixed(1)}% of it, more than anyone · no levy there · ◆ ${this.yieldOf(h.kind, true)} a day`);
      else if (who === YOU) this.host.announce('No longer strong', `${name} · keep 4% of its property, and more than any other fleet, to stay strong`);
    }
    if (contested !== h.contested) {
      const before = h.contested;
      h.contested = contested;
      changed = true;
      if (who === YOU && contested) press.write({ k: 'territoryContested', who: 'you', town: key, f: { town: name, firm: this.host.carrierName(contested) } });
      if (who === YOU && contested) this.host.announce(`${name} is contested`, `${this.host.carrierName(contested)} owns more of it than you · no ◆ there until you own more property than them`);
      else if (who === YOU) this.host.announce(`${name} is settled`, `nobody out-owns you there now · ◆ ${this.yieldOf(h.kind, h.strong)} a day again`);
      else if (contested === YOU) this.host.announce(`You contest ${name}`, `you own more of it than ${this.host.carrierName(who)}, who carries its trade · they earn no ◆ there`);
      else if (before === YOU) this.host.announce(`${name}: no longer contested by you`, `${this.host.carrierName(who)} earns its ◆ again`);
    }
    if (!who && !h.value) this.towns.delete(key);
    // the player's town: an hour's pay unless contested, and a word when it's about to slip
    if (who === YOU && pay) {
      if (!h.contested) this.pay(this.yieldOf(h.kind, h.strong) / 24, 'town', undefined, name, key);
      const left = this.outlook(key);
      if (!h.warned && left < TERRITORY.warnHours) {
        h.warned = true;
        this.host.announce(`${this.host.nameOf(key)} is slipping`, 'Deliver here, or pick up here, to keep it');
      } else if (h.warned && left > TERRITORY.warnHours * 2) h.warned = false;
    }
    return changed;
  }

  private said(key: string, from: string, now: string): void {
    const name = this.host.nameOf(key);
    if (now === YOU) {
      const h = this.towns.get(key);
      press.write({ k: 'territoryWon', who: 'you', town: key, f: { town: name, from: from ? this.host.carrierName(from) : '' } });
      this.host.announce('Territory', `${name} is yours · half the levy and first refusal on its loads · ◆ ${h ? this.yieldOf(h.kind, false) : 1} a day`);
      if (!this.firstTown) {
        this.firstTown = true;
        this.pay(TERRITORY.firstTown, 'bonus', undefined, `Your first territory: ${name}`, key);
        this.host.announce('Your first territory · ◆ ' + TERRITORY.firstTown, 'Towns you hold pay diamonds every day: spend them on new vehicles in the tech trees');
      }
    } else if (from === YOU) {
      this.host.announce(`Lost ${name}`, now ? `to ${this.host.carrierName(now)}` : 'its own trade has taken it back');
      press.write({ k: 'territoryLost', who: 'you', town: key, f: { town: name, to: now ? this.host.carrierName(now) : '' } });
    }
  }

  // ---- the purse ----

  /**
   * Diamonds in: to the balance, to the lifetime and to the account (`what` paid them, `key` the town where).
   * The chip bursts for every whole diamond crossed.
   */
  pay(n: number, source: 'town' | 'deed' | 'bonus', colour?: string, what?: string, key?: string): void {
    if (!(n > 0)) return;
    const before = Math.floor(this.diamonds + 1e-9);
    this.diamonds += n;
    this.earned += n;
    this.note(n, source, what ?? (source === 'town' ? 'A town' : source === 'deed' ? 'An achievement' : 'A bonus'), key);
    this.host.paid(Math.floor(this.diamonds + 1e-9) - before, source, colour);
  }

  /** A PvP Challenge board held (docs/challenges.html): its hour's share of ◆ a day, on a line of its own a board a game day. */
  payPvp(n: number, what: string, key: string): void {
    if (!(n > 0)) return;
    const before = Math.floor(this.diamonds + 1e-9);
    this.diamonds += n;
    this.earned += n;
    this.note(n, 'pvp', what, key);
    this.host.paid(Math.floor(this.diamonds + 1e-9) - before, 'bonus');
  }

  /** Spend (`what` on, for the account): false (and nothing taken) when there isn't enough. */
  spend(n: number, what = 'Spent'): boolean {
    if (!(n > 0) || this.diamonds + 1e-6 < n) return false;
    this.diamonds = Math.max(0, this.diamonds - n);
    this.note(-n, 'spend', what);
    this.host.paid(0, 'bonus');
    return true;
  }

  /** A line in the account, and the lifetime totals. A town's hourly pay joins its line for the game day. */
  private note(n: number, kind: GemEntry['kind'], what: string, key?: string): void {
    const L = this.ledger, h = round2(this.host.hours());
    if (kind === 'town') L.towns[what] = round2((L.towns[what] ?? 0) + n);
    else if (kind === 'deed') { L.deeds += n; L.tiers++; }
    else if (kind === 'bonus') L.bonus[what] = round2((L.bonus[what] ?? 0) + n);
    // (to four places: a twenty-fourth of a diamond an hour rounded to two lost a twentieth of it a day)
    else if (kind === 'pvp') (L.pvp ??= {})[what] = round4((L.pvp[what] ?? 0) + n);
    else L.spent[what] = round2((L.spent[what] ?? 0) - n);
    if (kind === 'town' || kind === 'pvp') {
      const day = Math.floor(h / 24);
      for (let k = L.recent.length - 1; k >= Math.max(0, L.recent.length - 40); k--) {
        const e = L.recent[k];
        if (e.kind === kind && e.key === key && Math.floor(e.h / 24) === day) { e.n = kind === 'pvp' ? round4(e.n + n) : round2(e.n + n); e.h = h; L.recent.push(L.recent.splice(k, 1)[0]); return; }
      }
    }
    L.recent.push({ h, n: kind === 'pvp' ? round4(n) : round2(n), kind, what, ...(key ? { key } : {}) });
    if (L.recent.length > LEDGER_KEEP) L.recent.splice(0, L.recent.length - LEDGER_KEEP);
  }

  /** The towns paying diamonds now: name, ◆ a day, strong or not, and the contested ones that pay nothing. */
  paying(): { key: string; name: string; perDay: number; strong: boolean; contested: boolean }[] {
    const out: { key: string; name: string; perDay: number; strong: boolean; contested: boolean }[] = [];
    for (const [key, h] of this.towns) {
      if (h.who !== YOU) continue;
      out.push({ key, name: this.host.nameOf(key), perDay: h.contested ? 0 : this.yieldOf(h.kind, h.strong), strong: h.strong, contested: !!h.contested });
    }
    return out.sort((a, b) => b.perDay - a.perDay || a.name.localeCompare(b.name));
  }

  /** Pay every deed tier the player holds that this save hasn't paid yet. */
  syncDeeds(deeds: Deeds): void {
    for (const d of DEEDS) {
      const t = deeds.tier(d);
      for (let k = 1; k <= t; k++) {
        const id = `${d.id}:${k}`;
        if (this.deedsPaid.has(id)) continue;
        this.deedsPaid.add(id);
        this.pay(TIER_POINTS[k - 1], 'deed', TIER_COLOURS[k - 1], `${d.name} · ${TIERS[k - 1]}`);
      }
    }
  }

  /**
   * A new world, or a save from before diamonds: it starts with the diamonds of every tier the player has
   * already won in their other games, counted as earned, and paid silently.
   */
  startFrom(deeds: Deeds): number {
    let n = 0;
    for (const d of DEEDS) {
      const t = deeds.tier(d);
      for (let k = 1; k <= t; k++) {
        const id = `${d.id}:${k}`;
        if (this.deedsPaid.has(id)) continue;
        this.deedsPaid.add(id);
        n += TIER_POINTS[k - 1];
      }
    }
    this.diamonds += n;
    this.earned += n;
    if (n > 0) this.note(n, 'bonus', 'Achievements from your other games');
    return n;
  }

  // ---- saving ----

  clear(): void {
    this.diamonds = 0;
    this.earned = 0;
    this.firstTown = false;
    this.deedsPaid.clear();
    this.towns.clear();
    this.ledger = blankLedger(this.host.hours());
    this.version++;
  }

  toSave(): SavedTerritory {
    const towns: SavedTerritory['towns'] = {};
    for (const [k, h] of this.towns) towns[k] = [h.who, h.strong ? 1 : 0, h.since, h.value, h.own, h.kind, h.contested];
    return { diamonds: round2(this.diamonds), earned: round2(this.earned), firstTown: this.firstTown, deedsPaid: [...this.deedsPaid], towns, ledger: this.ledger };
  }

  /** False when the save had no territory record: the caller starts it from the player's deeds. */
  fromSave(s: SavedTerritory | undefined): boolean {
    this.clear();
    if (!s) return false;
    this.diamonds = Number(s.diamonds) || 0;
    this.earned = Math.max(this.diamonds, Number(s.earned) || 0);
    this.firstTown = !!s.firstTown;
    // the account as saved; a save from before it starts one from now (what was earned before shows as one sum)
    const L = s.ledger;
    this.ledger = L && Array.isArray(L.recent)
      ? { recent: L.recent.slice(-LEDGER_KEEP), towns: { ...(L.towns ?? {}) }, deeds: Number(L.deeds) || 0, tiers: Number(L.tiers) || 0, bonus: { ...(L.bonus ?? {}) }, spent: { ...(L.spent ?? {}) }, ...(L.pvp ? { pvp: { ...L.pvp } } : {}), from: Number(L.from) || 0 }
      : blankLedger(this.host.hours());
    for (const id of s.deedsPaid ?? []) this.deedsPaid.add(id);
    for (const [k, row] of Object.entries(s.towns ?? {})) {
      if (!Array.isArray(row)) continue;
      const [who, strong, since, value, own, kind, contested] = row;
      this.towns.set(k, { who: String(who ?? ''), strong: !!strong, since: Number(since) || 0, value: Number(value) || 0, own: { ...(own ?? {}) }, kind: (kind as TownKind) ?? 'rural', contested: String(contested ?? '') });
    }
    return true;
  }

  /** The console: pr.territory. */
  console() {
    return {
      list: () => [...this.towns].map(([k, h]) => `${this.host.nameOf(k)} (${k}): ${h.who ? this.host.carrierName(h.who) : 'nobody'}${h.strong ? ' · STRONG' : ''}${h.contested ? ` · CONTESTED by ${this.host.carrierName(h.contested)}` : ''} · ${h.kind} · property $${h.value.toLocaleString('en-US')}${h.who === YOU ? ` · ◆ ${this.yieldOf(h.kind, h.strong)}/day · slips in ${Math.round(this.outlook(k))} h` : ''}`),
      give: (n: number) => { this.pay(n, 'bonus', undefined, 'A gift from the console'); return Math.floor(this.diamonds); },
      /** Credit the player (or `who`, a firm's id) with dollars of a town's trade, and run the tally: for testing and bots. */
      carry: (key: string, dollars: number, who = YOU) => { this.host.carriage.credit(key, who, dollars); this.hourly(); return this.status(key); },
      shares: (key: string) => this.host.carriage.shares(key).map((x) => `${x.who || 'haulers'} ${(x.share * 100).toFixed(1)}%`).join(' · '),
      state: () => ({ diamonds: round2(this.diamonds), earned: round2(this.earned), ...this.daily() }),
      tiers: TIERS,
    };
  }
}
