/**
 * The tech trees (docs/territory.html, "Tech trees"): every model in three trees, land, sea and air, one
 * per dealer trade (the trains are the top of the land tree). Each tree starts with three models
 * unlocked; the rest are unlocked with diamonds, a tier at a time, each tier twice the one before. A
 * node needs any one of its parents. Unlocking a model only puts it on sale: it is still bought with
 * cash, at a dealer (a train only at a train dealer, at a station). A model the fleet has ever owned is
 * unlocked whatever the tree says.
 *
 * Every model is on a tree (audit 23 Oct 2026). Military hardware comes late in each tree, from tier 6, and
 * always behind a civilian model of its kind (the Bumblebee after the Swift, the Badger after the Stomper).
 * Since 27 Oct 2026 each tree is drawn as named branch rows (ROWS): a node stands in one cell of its row, its
 * parents on the same row or the row beside it, so the branches split from the starters in the first tiers
 * and no line crosses another (game/techLayout.ts checks it).
 * The factions' own models stand at the far end of their tree as `standing` nodes: no diamonds, no parents,
 * on sale once the faction counts the player Honoured or Sworn (tech.gate, docs/factions.html).
 */
import { NEXT_WORLD } from '../world/nextWorld';

export type Tree = 'land' | 'sea' | 'air';
export const TREES: Tree[] = ['land', 'sea', 'air'];
export const TREE_LABEL: Record<Tree, string> = { land: 'Land', sea: 'Sea', air: 'Air' };
export const TREE_ICON: Record<Tree, string> = { land: '🚗', sea: '⛵', air: '✈️' };

export interface TechNode {
  /** The model's id (game/vehicles.ts). */
  id: string;
  tree: Tree;
  /** 0 for a starter; 1..8 otherwise (the fighter 9 and the carrier 10, past the end on purpose). */
  tier: number;
  /** Unlocked when any one of these is. */
  from: string[];
  /**
   * The branch row it stands on in the map (ROWS, game/techLayout.ts): one node a cell, parents on the same
   * row or the one beside it, so every line runs along its branch and bends once. 0 for a faction's own.
   */
  row: number;
  /** A word on what it heads, for the window, when the row's name doesn't say it (the military hardware). */
  branch?: string;
  /**
   * A faction's own model: earned, not bought with diamonds. Its tier is 0 (no diamonds) and it has no
   * parents; it is on sale once `faction` counts the player at `rung` (5 Honoured, 6 Sworn).
   */
  standing?: { faction: string; rung: number };
}

/**
 * The branch rows of each tree, top to bottom, as the map names them. A row is one line of choices: what you
 * unlock on it early (◆ 4–32) is what leads to its late models (◆ 64 up), so the rows split from the starters
 * in the first tiers and never cross.
 */
export const ROWS: Record<Tree, string[]> = {
  land: ['Sightseeing', 'Fares', 'Town', 'Rough', 'Racing', 'Service', 'Haulage'],
  sea: ['Shore', 'Speed', 'Deep', 'Passage', 'Cargo'],
  air: ['Hot air', 'Airship', 'Wings', 'Rotors'],
};

const n = (tree: Tree, id: string, tier: number, from: string[], row: number, branch?: string): TechNode => ({ id, tree, tier, from, row, branch });
/** A faction's own model, at the end of its tree. */
const own = (tree: Tree, id: string, faction: string, rung: number): TechNode => ({ id, tree, tier: 0, from: [], row: 0, standing: { faction, rung } });

