export const TECH_BY_ID = new Map(TECH.map((t) => [t.id, t]));

/** Diamonds a tier costs: 4, 8, 16, 32, 64, 128, 256, 512 (and 1024, 2048 for the fighter and the carrier). */
export const tierCost = (tier: number): number => (tier <= 0 ? 0 : 4 * 2 ** (tier - 1));

/** A model every fleet has from the start (a faction's own model has no diamond tier either, but isn't one). */
export const isStarter = (t: TechNode | undefined): boolean => !!t && t.tier === 0 && !t.standing;

export const STARTERS: string[] = TECH.filter(isStarter).map((t) => t.id);

type NodeState = 'unlocked' | 'open' | 'locked';

interface TechHost {
  /** Models the fleet owns now: always unlocked. */
  owned(): string[];
  /** Diamonds to spend: false (nothing taken) when there aren't enough. */
  spend(n: number, what?: string): boolean;
  balance(): number;
  /** `group`: stacks with the others of its group in the notification log. */
  announce(title: string, body: string, group?: string): void;
  /** Something was unlocked: dealers restock, menus redraw. */
  changed(): void;
}

export class Tech {
  /** Models unlocked with diamonds (or grandfathered), beyond the starters. */
  readonly unlocked = new Set<string>();
  /** Goes up on every unlock. */
  version = 0;

  constructor(private host: TechHost) {}

  /**
   * The factions' say (docs/factions.html): why a model is not on sale to this player whatever the trees
   * say — a faction's own vehicle not yet earned, or military hardware the Army won't sell them — or null.
   */
  gate: ((id: string) => string | null) | null = null;

  /** May this model be sold? A model outside the trees (a patrol car, something new) always may, unless a faction keeps it. */
  has(id: string): boolean {
    const node = TECH_BY_ID.get(id);
    // unlocked already (with diamonds, or before the factions kept it) stays unlocked; owned is unlocked for
    // good: selling it later doesn't lock it again
    if (this.unlocked.has(id)) return true;
    // (a faction's own model owned now is on sale while it's owned, but isn't kept: its faction still has the say)
    if (this.host.owned().includes(id)) { if (node && !node.standing) this.unlocked.add(id); return true; }
    if (this.gate?.(id)) return false;
    if (!node || node.tier === 0) return true;
    return false;
  }

  state(id: string): NodeState {
    if (this.has(id)) return 'unlocked';
    const node = TECH_BY_ID.get(id);
    return node && node.from.some((p) => this.has(p)) ? 'open' : 'locked';
  }

  cost(id: string): number { return tierCost(TECH_BY_ID.get(id)?.tier ?? 0); }

  /** Why it can't be unlocked now, or null. */
  whyNot(id: string): string | null {
    const s = this.state(id);
    if (s === 'unlocked') return 'Already unlocked';
    const kept = this.gate?.(id);
    if (kept) return kept;
    if (s === 'locked') return 'Unlock one of the models before it first';
    if (this.host.balance() + 1e-6 < this.cost(id)) return `Needs ◆ ${this.cost(id)} · you have ◆ ${Math.floor(this.host.balance())}`;
    return null;
  }

  /** Told after each unlock with diamonds (the teaching missions, game/coach.ts). */
  onUnlocked: ((id: string) => void) | null = null;

  /** Unlock with diamonds; a message when it can't be done. */
  unlock(id: string, name = id): string | null {
    const why = this.whyNot(id);
    if (why) return why;
    if (!this.host.spend(this.cost(id), `Unlocked the ${name}`)) return 'Not enough diamonds';
    this.unlocked.add(id);
    this.version++;
    this.host.announce('Unlocked', `${name} · on sale at any dealer that stocks it`, 'Unlocks');
    this.host.changed();
    this.onUnlocked?.(id);
    return null;
  }

  /** Open nodes in a tree, cheapest first: what the player could unlock next. */
  open(tree: Tree): TechNode[] {
    return TECH.filter((t) => t.tree === tree && this.state(t.id) === 'open').sort((a, b) => a.tier - b.tier);
  }

  clear(): void { this.unlocked.clear(); this.version++; }

  toSave(): string[] { return [...this.unlocked]; }

  /** A save from before the trees (`saved` undefined) keeps everything it owns, and the rest locks. */
  fromSave(saved: string[] | undefined, owned: string[]): void {
    this.unlocked.clear();
    for (const id of saved ?? []) if (TECH_BY_ID.has(id) && !TECH_BY_ID.get(id)!.standing) this.unlocked.add(id);
    for (const id of owned) if (TECH_BY_ID.has(id) && TECH_BY_ID.get(id)!.tier > 0) this.unlocked.add(id);
    this.version++;
  }

  console() {
    return {
      list: () => TECH.map((t) => `${t.tree} ${t.standing ? `${t.standing.faction}@${t.standing.rung}` : `T${t.tier}`} ${t.id}: ${this.state(t.id)}${this.state(t.id) === 'open' ? ` · ◆ ${this.cost(t.id)}` : ''}`),
      unlock: (id: string) => this.unlock(id) ?? 'unlocked',
      all: () => { for (const t of TECH) if (!t.standing) this.unlocked.add(t.id); this.version++; this.host.changed(); return 'everything unlocked'; },
    };
  }
}
