import * as THREE from 'three';
import type { World } from '../../world/tiles';
import { LIDO_BOARDS, LIDO_HALL, blockOf, lidoFrame, type LidoPlan } from '../../render/buildings/lidoPlan';
import { BatherMesh, MEETS, Splashes, lidoPlanOf } from '../pools';
import { KIND_OF } from './kinds';
import type { Happening } from './calendar';
import type { Place, Pt } from './venues';
import { Crowd, block } from './props';
import { HOUR_S, Show, clamp01, u01, type ShowCtx } from './shows';

/**
 * A swim meet at a town's lido (docs/events.html, after): the lanes roped, flags strung over each end, the
 * stand and the rim full, and three races of two lengths, heats then the final, each called to the blocks,
 * started on the horn, swum, touched in, and put up on a scoreboard on the changing rooms' roof. The public
 * are out of the water while it is on (pools.ts MEETS). Like every show, all of it is worked out from the clock.
 */

const LANES = [0xe2412f, 0xf2c14e, 0x3f9b4a, 0x2f7fb5, 0x8e5cc7, 0xf28c38];
const SKINS = [0xe0b48a, 0xc68e62, 0x8d5a3b, 0xf0caa4, 0xa86e48];
const HEATS = ['Heat 1', 'Heat 2', 'Final'];
/** A race's parts, in seconds: called to the blocks, on them, the dive, then the swim; after it, the results. */
const CALL = 6, MARKS = 2.5, DIVE = 0.8, AFTER = 7;

export class SwimMeetShow extends Show {
  private plan: LidoPlan;
  private f: { ox: number; oy: number; oz: number; c: number; s: number; yaw: number };
  private racers: BatherMesh;
  private splash: Splashes;
  private crowd: Crowd;
  private officials: Crowd;
  private score: { canvas: HTMLCanvasElement; tex: THREE.CanvasTexture; key: string };
  private splashed = new Set<string>();
  private n: number;

  constructor(e: Happening, ctx: ShowCtx, w: World, place: Place) {
    super(e, ctx);
    const b = place.lot!;
    this.plan = lidoPlanOf(b);
    const f = lidoFrame(b);
    this.f = { ox: w.ox + f.ox, oy: f.oy, oz: w.oz + f.oz, c: Math.cos(f.yaw), s: Math.sin(f.yaw), yaw: f.yaw };
    this.n = this.plan.lanes;
    const p = this.plan, r = p.pool, y = p.rim;
    this.b = b;

    // lane ropes where the model has none (the hall's are built in), floats red at the ends
    const L = Math.abs(p.race.turn - p.race.start);
    if (p.model !== LIDO_HALL) {
      for (let i = 1; i < this.n; i++) {
        for (const [u0, u1, col] of [[0, 0.16, 0xe2412f], [0.16, 0.84, i % 2 ? 0xf4f2ec : 0x2f7fb5], [0.84, 1, 0xe2412f]] as const) {
          const a = this.lane(i - 0.5, u0), c = this.lane(i - 0.5, u1);
          this.prop((a.x + c.x) / 2, p.wy - 0.002, (a.z + c.z) / 2, p.along === 'x' ? L * (u1 - u0) : 0.012, 0.01, p.along === 'x' ? 0.012 : L * (u1 - u0), col);
        }
      }
    }
    // the blocks, where the model has none
    if (p.model !== LIDO_BOARDS && p.model !== LIDO_HALL) {
      for (let i = 0; i < this.n; i++) { const q = this.lane(i, -0.03); this.prop(q.x, y, q.z, 0.05, 0.035, 0.05, 0xf4f2ec); }
    }
    // backstroke flags strung across each end on two poles
    const across = p.along === 'x' ? [r.z0 - 0.08, r.z1 + 0.08] : [r.x0 - 0.08, r.x1 + 0.08];
    for (const u of [0.12, 0.88]) {
      const a = this.lane(-0.5, u), c = this.lane(this.n - 0.5, u);
      const ends = p.along === 'x' ? [{ x: a.x, z: across[0] }, { x: a.x, z: across[1] }] : [{ x: across[0], z: a.z }, { x: across[1], z: a.z }];
      for (const q of ends) this.prop(q.x, 0, q.z, 0.012, 0.22, 0.012, 0xb9bdc2);
      const k = Math.round(Math.hypot(c.x - a.x, c.z - a.z) / 0.07);
      for (let j = 0; j <= k; j++) {
        const t = j / Math.max(1, k), q = { x: ends[0].x + (ends[1].x - ends[0].x) * t, z: ends[0].z + (ends[1].z - ends[0].z) * t };
        this.prop(q.x, 0.19, q.z, 0.028, 0.03, 0.028, LANES[j % LANES.length]);
      }
    }
    // the scoreboard, up on the changing rooms' roof, facing the water (-x in the model's frame)
    const canvas = document.createElement('canvas');
    canvas.width = 256; canvas.height = 160;
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    this.score = { canvas, tex, key: '' };
    const blk = blockOf(p.W, p.D), at = this.world(blk.cx - 0.05, blk.cz);
    const roof = this.f.oy + 0.33;
    for (const dz of [-0.18, 0.18]) { const q = this.world(blk.cx, blk.cz + dz); block(this.g, q.x, roof, q.z, 0.02, 0.08, 0.02, 0x8c8a84); }
    const face = new THREE.Mesh(new THREE.PlaneGeometry(0.46, 0.29), new THREE.MeshBasicMaterial({ map: tex, toneMapped: false }));
    face.position.set(at.x, roof + 0.22, at.z);
    face.rotation.y = this.f.yaw - Math.PI / 2;
    this.g.add(face);
    // its back and frame, the club's blue
    const back = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.33, 0.02), new THREE.MeshStandardMaterial({ color: 0x2f5d8a }));
    back.position.set(at.x, roof + 0.22, at.z);
    back.rotation.y = this.f.yaw - Math.PI / 2;
    back.translateZ(-0.012);
    this.g.add(back);

    // the crowd: the stand's seats first, then the deck, then round the lot
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    const seats = p.seats.slice();
    for (let k = seats.length - 1; k > 0; k--) { const j = Math.floor(u01(e.h, k) * (k + 1)); [seats[k], seats[j]] = [seats[j], seats[k]]; }
    for (const s of seats.slice(0, 44)) { const q = this.world(s[0], s[2]); this.crowd.add(q.x, q.z, this.f.oy + s[1] + 0.005); }
    for (let k = 0; this.crowd.size < 56 && k < 300; k++) {
      const d = p.deck[k % p.deck.length];
      const q = this.world(d.x0 + u01(e.h, 300 + k) * (d.x1 - d.x0), d.z0 + u01(e.h, 600 + k) * (d.z1 - d.z0));
      this.crowd.add(q.x, q.z, this.f.oy);
    }
    // the officials in white: the starter at the blocks' end, timekeepers along the side
    this.officials = new Crowd(this.g, ctx.ground, 0, [0xf4f2ec]);
    for (const [i, u] of [[-0.9, -0.08], [this.n - 0.1, -0.08], [this.n - 0.1, 0.5]] as const) { const q = this.lane(i, u); this.officials.add(q.x, q.z, this.f.oy + p.rim); }

    this.racers = new BatherMesh(this.g, 8);
    this.splash = new Splashes(this.g, 12);
  }

  private b: NonNullable<Place['lot']>;

  /** A point in the model's frame, in world tiles. */
  private world(x: number, z: number): Pt { return { x: this.f.ox + x * this.f.c + z * this.f.s, z: this.f.oz - x * this.f.s + z * this.f.c }; }

  /** Lane i's middle (fractions for the ropes between) at u along it, 0 the start wall to 1 the turn, in the model's frame. */
  private laneLocal(i: number, u: number): Pt {
    const p = this.plan, r = p.pool;
    const a = p.race.start + (p.race.turn - p.race.start) * u;
    const [c0, c1] = p.along === 'x' ? [r.z0, r.z1] : [r.x0, r.x1];
    const c = c0 + ((i + 0.5) * (c1 - c0)) / this.n;
    return p.along === 'x' ? { x: a, z: c } : { x: c, z: a };
  }
  private lane(i: number, u: number): Pt { const q = this.laneLocal(i, u); return this.world(q.x, q.z); }

  /** A box prop on the lido, (x, z) world tiles, its foot `y` above the lot's floor, sized along the model's frame. */
  private prop(x: number, y: number, z: number, w: number, h: number, d: number, col: number): void {
    block(this.g, x, this.f.oy + y, z, w, h, d, col, this.f.yaw);
  }

  centre(): Pt | null { const r = this.plan.pool; return this.world((r.x0 + r.x1) / 2, (r.z0 + r.z1) / 2); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF[e.kind];
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    // the public are out of the water from when the meet gets ready till it is over (pools.ts)
    if (out) MEETS.add(this.b); else MEETS.delete(this.b);
    if (!out) { this.crowd.shown = 0; return; }
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.officials.shown = now >= e.start - 0.3 ? this.officials.size : 0;
    const p = this.plan, L = Math.abs(p.race.turn - p.race.start);
    // three races in the event's hours; each its own share of them
    const span = (e.end - e.start) * HOUR_S, heatLen = span / HEATS.length;
    const t = (now - e.start) * HOUR_S;
    const heat = Math.min(HEATS.length - 1, Math.max(0, Math.floor(t / heatLen)));
    const ht = t < 0 ? -1 : t - heat * heatLen;
    const swim = heatLen - CALL - MARKS - DIVE - AFTER;
    // each racer's pace this race: the slowest touches in at the end of the swim
    const pace = (i: number) => 0.8 + 0.2 * u01(e.h, heat * 16 + i);
    const done = (i: number) => swim * pace(i);
    this.racers.begin();
    let cheer = 0;
    const a0 = this.lane(0, 0), a1 = this.lane(0, 1), towards = Math.atan2(a1.x - a0.x, a1.z - a0.z);
    for (let i = 0; i < this.n && ht >= 0; i++) {
      const suit = LANES[i % LANES.length], skin = SKINS[Math.floor(u01(e.h, 40 + heat * 8 + i) * SKINS.length)];
      const r0 = ht - CALL - MARKS - DIVE;
      if (ht < CALL + MARKS) {
        // behind the block, swinging the arms; up on it for the marks
        const on = ht >= CALL;
        const q = this.lane(i, on ? -0.03 : -0.06);
        this.racers.put(q.x, this.f.oy + p.rim + (on ? 0.035 : 0), q.z, towards, on ? 0.55 : 0, suit, skin, on ? 0 : Math.sin(t * 6 + i) * 0.3);
      } else if (r0 < 0) {
        // the dive: out over the water in an arc
        const k = (ht - CALL - MARKS) / DIVE, a = this.lane(i, -0.03 + k * 0.14);
        this.racers.put(a.x, this.f.oy + p.rim + 0.035 + Math.sin(k * Math.PI) * 0.06 - k * 0.07, a.z, towards, 0.6 + k * 1.1, suit, skin);
      } else {
        if (!this.splashed.has(`${heat}:${i}`)) { this.splashed.add(`${heat}:${i}`); const q = this.lane(i, 0.11); this.splash.add(q.x, this.f.oy + p.wy, q.z, 0.8); }
        const fin = done(i);
        if (r0 < fin) {
          // two lengths: out to the turn and back
          const dist = (2 * L * r0) / fin, back = dist > L;
          const q = this.lane(i, back ? 0.95 - ((dist - L) / L) * 0.9 : 0.11 + (dist / L) * 0.84);
          this.racers.put(q.x, this.f.oy + p.wy - 0.014 + Math.sin(t * 9 + i) * 0.003, q.z, back ? towards + Math.PI : towards, Math.PI / 2 - 0.12, suit, skin, Math.sin(t * 7 + i * 2) * 0.4);
          cheer = Math.max(cheer, 0.35 + 0.65 * clamp01((r0 / fin - 0.85) / 0.15));
        } else {
          // touched in: treading water at the wall, then climbing out
          const q = this.lane(i, 0.05);
          const outNow = r0 > swim + AFTER * 0.5;
          if (outNow) { const s = this.lane(i, -0.1); this.racers.put(s.x, this.f.oy + p.rim, s.z, towards + Math.PI, 0, suit, skin); }
          else this.racers.put(q.x, this.f.oy + p.wy - 0.085, q.z, towards + Math.PI, 0, suit, skin);
          if (r0 - fin < 2) cheer = 1;
        }
      }
    }
    this.racers.end();
    this.splash.update(dt);
    this.crowd.cheer = cheer;
    this.crowd.update(dt);
    this.officials.update(dt);
    this.board(ht < 0 ? -1 : heat, ht - CALL - MARKS - DIVE, done, swim);
  }

  /** The scoreboard: every lane with the clock running, each one's time and place as it touches in. */
  private board(heat: number, r0: number, done: (i: number) => number, swim: number): void {
    // the clock shown is a 100 m's: the whole swim is a minute, so the fastest touch in at about 48 seconds
    const shown = (t: number) => (t / swim) * 60;
    const lanes = Array.from({ length: this.n }, (_, i) => i);
    const finished = heat < 0 || r0 < 0 ? [] : lanes.filter((i) => r0 >= done(i)).sort((a, b) => done(a) - done(b));
    const running = heat >= 0 && r0 >= 0 && finished.length < this.n;
    const key = `${heat}|${finished.join(',')}|${r0 < 0 ? 'b' : 'r'}|${running ? Math.floor(r0 * 4) : ''}`;
    if (key === this.score.key) return;
    this.score.key = key;
    const g = this.score.canvas.getContext('2d')!;
    const clock = (s: number) => `${Math.floor(s / 60)}:${(s % 60).toFixed(2).padStart(5, '0')}`;
    g.fillStyle = '#14181d';
    g.fillRect(0, 0, 256, 160);
    g.fillStyle = '#ffb347';
    g.font = 'bold 20px monospace';
    g.textAlign = 'center';
    g.fillText(heat < 0 ? 'SWIM MEET' : `${HEATS[heat].toUpperCase()} · 100 FREE`, 128, 24);
    g.font = 'bold 15px monospace';
    g.textAlign = 'left';
    if (heat < 0 || r0 < 0) {
      g.fillStyle = '#9fd8ff';
      g.fillText(heat < 0 ? 'SWIMMERS TO THE POOL' : 'TAKE YOUR MARKS', 22, 82);
      this.score.tex.needsUpdate = true;
      return;
    }
    // the ones in first, in order, with their times; the rest in lane order with the clock still running
    const order = [...finished, ...lanes.filter((i) => !finished.includes(i))];
    order.slice(0, 6).forEach((i, k) => {
      const fin = finished.includes(i), y = 34 + k * 20;
      g.fillStyle = `#${LANES[i % LANES.length].toString(16).padStart(6, '0')}`;
      g.fillRect(12, y + 3, 10, 13);
      g.fillStyle = fin && k === 0 ? '#ffe14f' : fin ? '#f4f2ec' : '#7f8a96';
      const secs = fin ? shown(done(i)) : shown(r0);
      g.fillText(`${fin ? k + 1 : ' '}  LANE ${i + 1}   ${clock(secs)}`, 30, y + 15);
    });
    this.score.tex.needsUpdate = true;
  }

  dispose(): void {
    MEETS.delete(this.b);
    this.racers.dispose();
    this.splash.dispose();
    this.crowd.dispose();
    this.officials.dispose();
    this.score.tex.dispose();
    super.dispose();
  }
}
