/**
 * The circuits' missions (docs/circuits.html). Coming up to a circuit, its race director has something
 * for the player (Missions.nearCircuit offers it there and then): a Hot Lap against the clock, a grid
 * slot on Race Day, or a run in with what a meeting needs — racing slicks, race fuel, a race car on its
 * transporter, or a load of fans for the stands.
 */
import type { World, Building } from '../../world/tiles';
import { circuitsOf, frameOf, planOf, toIsland } from '../../world/circuits';
import { lapEstimate, LAPS } from '../circuitRace';
import { cargoById, type CargoType } from '../cargoTypes';
import { valueOf, type Site } from '../cargo';
import { offerable, spanOf } from '../fit';
import { personName } from '../mayor';
import type { MissionCtx } from './missions';
import type { Giver, Obj, PlaceRef } from './model';
import { siteRef, type Draft, type Template } from './templates';

/** Coming this near a circuit (tiles) brings its director out with work. */
export const CIRCUIT_NEAR = 80;

interface CircuitPick { w: World; b: Building; key: string; name: string; at: PlaceRef; d: number }

/** The circuits in memory, nearest the player first, within `max` tiles: each with its gate as the place to head for. */
export function circuitsNear(c: MissionCtx, max = 220): CircuitPick[] {
  const out: CircuitPick[] = [];
  for (const w of c.worlds) {
    for (const b of circuitsOf(w)) {
      const f = frameOf(b), p = planOf(b);
      const d = Math.hypot(w.ox + f.ox - c.at.x, w.oz + f.oz - c.at.z);
      if (d > max) continue;
      const name = w.works.find((g) => g.buildings.includes(b))?.name ?? 'the circuit';
      const q = toIsland(f, p.gateX, p.D / 2 + 0.6);
      out.push({ w, b, key: `${w.cx},${w.cz}#${b.uid}`, name, at: { x: w.ox + q.x, z: w.oz + q.z, cell: [w.cx, w.cz], name }, d });
    }
  }
  return out.sort((a, b) => a.d - b.d);
}

/** The circuit's race director, who hands out its work. */
const director = (k: CircuitPick): Giver => ({ who: 'director', name: `${personName(`circuit|${k.key}`).split(' ')[0]}, race director`, at: k.at, town: null });

/** A circuit's name short enough for a line: "Kestrel Motor Speedway" → "Kestrel". */
const shortName = (name: string): string => {
  const w = name.replace(/^(The|Circuit de|Autodromo di) /, '').split(' ');
  return w[0].length > 3 ? w[0] : w.slice(0, 2).join(' ');
};

/** A load of this kind for the circuit, from somewhere in reach that has one. */
function toCircuit(c: MissionCtx, k: CircuitPick, ids: string[]): { type: CargoType; from: Site; to: Site; value: number } | null {
  const to = c.sites(['raceCircuit']).find((s) => s.b === k.b);
  if (!to) return null;
  for (const id of ids) {
    const type = cargoById(id);
    if (!type) continue;
    const froms = c.sites(type.from as string[])
      .filter((s) => Math.hypot(s.x - to.x, s.z - to.z) < 180 && spanOf(s, to) >= 12)
      .sort((a, b) => Math.hypot(a.x - c.at.x, a.z - c.at.z) - Math.hypot(b.x - c.at.x, b.z - c.at.z)).slice(0, 8);
    for (const from of froms) {
      const fit = offerable(c.def, c.at, from, to, type, true);
      if (!fit.ok || !fit.urgency) continue;
      return { type, from, to, value: valueOf(type, fit.dist, fit.urgency, fit.seconds) };
    }
  }
  return null;
}

function deliverTo(p: { type: CargoType; from: Site; to: Site; value: number }, n: number): Obj {
  const from = siteRef(p.from), to = { ...siteRef(p.to), name: 'the circuit' };
  let label = `${n > 1 ? `${n}× ` : ''}${p.type.name} → Circuit`;
  if (label.length > 28) label = `Deliver ${p.type.name.toLowerCase()}`.slice(0, 28);
  return { t: 'deliver', label, icon: p.type.icon, cargo: p.type.id, from, to, n, value: p.value };
}

const gateLand = (c: MissionCtx): string | null => (c.def.kind !== 'land' ? 'road cars only' : circuitsNear(c, 220).length ? null : 'no circuit near');

const hotLap: Template = {
  id: 'circuit:hotlap', thread: 'car', kind: 'race', side: true, cooldown: 36,
  gate: gateLand,
  bind(c) {
    const k = circuitsNear(c, 220)[0];
    if (!k) return null;
    // flat out and lifting only where the corners make you, then a fair margin for a first go
    const est = lapEstimate(planOf(k.b), c.def.topSpeed);
    const secs = Math.ceil(est * 1.28 * 2) / 2;
    const who = director(k);
    const name = shortName(k.name);
    return {
      title: 'Hot Lap', why: `Set a clean lap of ${name} in under ${secs.toFixed(1)} s in your ${c.def.name}. Beat the clock and the team fits racing tyres.`,
      details: `${who.name.split(',')[0]} wants to see what your ${c.def.name} can do on a proper track. Drive in at the gate, get up to speed and take the chequered line flying.`,
      giver: who, hero: { kind: 'part', slot: 'tyres', tier: 1 }, caption: 'Racing tyres',
      objs: [{ t: 'lap', label: `Race a lap under ${secs.toFixed(1)} s`, icon: '⏱️', at: k.at, key: k.key, secs }],
      reward: [{ r: 'part', slot: 'tyres', tier: 1 }, { r: 'cash', n: 250 }],
    };
  },
};

const raceDay: Template = {
  id: 'circuit:raceday', thread: 'car', kind: 'race', side: true, cooldown: 48,
  gate: gateLand,
  bind(c) {
    const k = circuitsNear(c, 220)[0];
    if (!k) return null;
    const who = director(k);
    return {
      title: 'Race Day', why: `Take a grid slot at ${shortName(k.name)}: ${LAPS} laps against five cars just like yours. Finish in the top three.`,
      details: `A one-make race: every car on the grid is a ${c.def.name}, so what you have fitted is your edge. The stands will be full.`,
      giver: who, hero: { kind: 'trophy' }, caption: 'The winner’s cup',
      objs: [{ t: 'grid', label: 'Race to a top three finish', icon: '🏁', at: k.at, key: k.key, top: 3 }],
      reward: [{ r: 'part', slot: 'gearbox', tier: 1 }, { r: 'cash', n: 650 }],
    };
  },
};

/** A run in with what a meeting needs: the load, how many, the title and the why. */
function supply(id: string, o: { thread: 'car' | 'fleet'; ids: string[]; n: number; title: string; why: (from: string, name: string) => string; pay: number; hours: number }): Template {
  return {
    id, thread: o.thread, kind: 'job', side: true, cooldown: 36,
    gate: gateLand,
    bind(c) {
      const k = circuitsNear(c, 220)[0];
      if (!k) return null;
      const p = toCircuit(c, k, o.ids);
      if (!p) return null;
      const from = siteRef(p.from).name.toLowerCase();
      const why = o.why(from, shortName(k.name));
      const d: Draft = {
        title: o.title, why: why.length <= 130 ? why : o.why(from, 'the circuit').slice(0, 130),
        giver: director(k), hero: { kind: 'crate', colour: p.type.color }, caption: p.type.name,
        objs: [deliverTo(p, o.n)],
        reward: [{ r: 'cash', n: Math.round((p.value * o.n * o.pay) / 10) * 10 }],
        hours: o.hours,
      };
      return d;
    },
  };
}

const slicks = supply('circuit:slicks', {
  thread: 'fleet', ids: ['raceTyres'], n: 1, title: 'Fresh Rubber', pay: 2.2, hours: 10,
  why: (from, name) => `The teams at ${name} are on their last set. Bring racing slicks from the ${from} before race day.`,
});
const fuel = supply('circuit:fuel', {
  thread: 'fleet', ids: ['raceFuel'], n: 1, title: 'Fuel for the Rig', pay: 2.2, hours: 10,
  why: (from, name) => `The fuel rig at ${name} runs dry tonight. Haul race fuel in from the ${from}.`,
});
const racecar = supply('circuit:car', {
  thread: 'fleet', ids: ['raceCar'], n: 1, title: 'Car for the Grid', pay: 2.4, hours: 12,
  why: (from, name) => `A team at ${name} is a car short. Collect it from the ${from} on something with room for it.`,
});
const fans = supply('circuit:fans', {
  thread: 'car', ids: ['raceFans'], n: 3, title: 'Fan Bus', pay: 1.8, hours: 8,
  why: (from, name) => `The stands at ${name} want filling. Run three loads of race fans in from the ${from}.`,
});

export const CIRCUIT_TEMPLATES: Template[] = [hotLap, raceDay, slicks, fuel, racecar, fans];
