import type { Town, TownKind, World } from '../../world/tiles';
import type { TownDigest } from '../../world/townDigest';
import type { TownShape } from '../../world/townShape';
import type { TownLedger } from '../ledger';
import type { TownIndex } from '../townIndex';
import { esc, money } from '../cargoHud';

/**
 * What a tab of the town card (docs/townregister.html) is drawn from. The card gathers it; the tab files only
 * turn it into markup, so the gate can draw them without a page.
 */
export interface TabCtx {
  key: string;
  /** The island and town while they are in memory; null far. */
  w: World | null;
  t: Town | null;
  shape: TownShape | null;
  kind: TownKind;
  name: string;
  /** The town's digest: live near, the last one taken far (null for a town never in memory this session). */
  digest: TownDigest | null;
  index: TownIndex;
  /** Its books, if anything has happened there. */
  ledger: TownLedger | null;
  /** Near: its mood and prosperity now. */
  mood: { mood: string; p: number } | null;
  /** Game hours now. */
  hours: number;
  /** A building kind's label. */
  label(kind: string): string;
  /** A town's name as a link that selects it. */
  link(key: string, name: string): string;
  /** Where the player's vehicle and the HQ are, in world tiles. */
  player: { x: number; z: number } | null;
  hq: { x: number; z: number; name: string } | null;
}

export function farNote(): string {
  return '<p class="note far">Drive nearer to see its streets: only its books are in memory.</p>';
}

export function dl(rows: [string, string][]): string {
  return `<dl>${rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
}

export function tick(ok: boolean, text: string): string {
  return `<span class="tick ${ok ? 'ok' : ''}">${ok ? '✓' : '○'} ${esc(text)}</span>`;
}

export function perHour(n: number): string {
  return n < 9.95 ? `$${n.toFixed(1)}/h` : `${money(n)}/h`;
}

export function hoursText(h: number): string {
  if (!Number.isFinite(h) || h > 24 * 30) return 'a long while';
  if (h < 1.5) return 'an hour';
  if (h < 36) return `${Math.round(h)} game hours`;
  return `${Math.round(h / 24)} game days`;
}

export const cap = (s: string): string => (s ? s[0].toUpperCase() + s.slice(1) : s);
export const pretty = (s: string): string => s.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
export const plural = (n: number, one: string, many = `${one}s`): string => `${n.toLocaleString('en-US')} ${n === 1 ? one : many}`;

/** "1st", "2nd", "3rd", "11th"… */
export function ordinal(n: number): string {
  const t = n % 100;
  const s = t >= 11 && t <= 13 ? 'th' : n % 10 === 1 ? 'st' : n % 10 === 2 ? 'nd' : n % 10 === 3 ? 'rd' : 'th';
  return `${n}${s}`;
}

/**
 * A town's trade over its days as a line, oldest on the left, against the dashed level a town its size expects.
 * Days it grew a building get a dot. Null with fewer than two days kept.
 */
export function tradeChart(l: TownLedger | null, norm: number, wide = 300, high = 54): string | null {
  const hist = l?.hist;
  if (!hist || hist.length < 2) return null;
  const days = [...hist].reverse();
  const grown = [...(l!.histGrown ?? [])].reverse();
  const max = Math.max(norm * 1.25, ...days) || 1;
  const step = wide / Math.max(1, days.length - 1);
  const y = (v: number) => (high - 4 - (v / max) * (high - 8)).toFixed(1);
  const pts = days.map((v, k) => `${(k * step).toFixed(1)},${y(v)}`).join(' ');
  const dots = days.map((v, k) => (k > 0 && grown[k] > grown[k - 1] ? `<circle cx="${(k * step).toFixed(1)}" cy="${y(v)}" r="2.6"/>` : '')).join('');
  const ny = y(norm);
  return `<svg class="tc-chart" viewBox="-3 0 ${wide + 6} ${high}" preserveAspectRatio="none" role="img" aria-label="Trade over its last ${days.length} days">`
    + `<line class="norm" x1="0" x2="${wide}" y1="${ny}" y2="${ny}"/><polyline points="${pts}"/><g class="grew">${dots}</g></svg>`;
}

/** When a far town's digest was taken: "As of day 12", or "Surveyed from afar" for a survey's copy. */
export function asOf(day: number): string {
  return day < 0 ? 'Surveyed from afar' : `As of day ${day + 1}`;
}

/** Tiles between two points in world tiles, as words. */
export function farText(tiles: number): string {
  if (tiles < 24) return 'here';
  const counties = tiles / 256;
  return counties < 0.75 ? `${Math.round(tiles)} tiles` : `${counties < 1.5 ? 'about a county' : `about ${Math.round(counties)} counties`} (${Math.round(tiles).toLocaleString('en-US')} tiles)`;
}

export { esc, money };
