import * as THREE from 'three';
import { N, DIRS, STEP, RailBit, RoadType, World, type RailEra, type RailPath, type StationKind } from '../world/tiles';
import { nodeAt, nodeCenter, nodeProblem, planRoutesLazy, settlePlan, planAcross, acrossFrom, raiseEnds, routeWithBridges, LIFT_MAX, STRAIT_SPAN, type Route, type RouteMode, type RoutePlan, type StraitDeck } from '../world/roads';
import {
  MIN_GAP, isBuiltRail, layRail, layStation, nearestRail, offsetPoints, railAt, shapeRail, stationLot, stationName, stationProblem,
  unlayLastRail, unlayLastStation, type RailSpec, type StationSpec,
} from '../world/railBuild';
import { anchorAt, firstPiece, heightsOf, pointsOf, raisedJoin, routeProblem, specOf, straitRoutes, SEA_CLEAR, type Anchor } from '../world/railRoute';
import { STATION_LOT } from '../world/railPlan';
import { buildRailGhost } from '../render/railMesh';
import { buildOutline, buildDashedLine, disposeObject } from '../render/roadMesh';
import { railTileIcon } from '../render/toolIcons';
import { buildingIconInto } from './passportStamps';
import { railCost, stationCost, type Wallet } from './economy';
import { money } from './cargoHud';
import type { Input } from './input';
import { clamp } from '../util/math';
import { el } from '../util/dom';
import { undoRaze } from '../world/railUndo';

/** The three periods a track can be laid in: the look of its ballast and sleepers, and the trains that run it. */
const ERAS: { era: RailEra; label: string; sub: string }[] = [
  { era: 'steam', label: 'Steam-era track', sub: 'timber sleepers · the old trains' },
  { era: 'streamline', label: 'Streamliner track', sub: 'the diesels and the streamliners' },
  { era: 'modern', label: 'Modern track', sub: 'concrete sleepers · the expresses' },
];
const STATIONS: { kind: StationKind; label: string; sub: string }[] = [
  { kind: 'halt', label: 'Halt', sub: 'a platform and a shelter' },
  { kind: 'townStation', label: 'Town station', sub: 'a station house and canopy' },
  { kind: 'cityStation', label: 'City station', sub: 'a concourse, a footbridge' },
  { kind: 'terminus', label: 'Terminus', sub: 'the grand shed' },
  { kind: 'goodsYard', label: 'Goods yard', sub: 'freight: sidings and a shed' },
  { kind: 'harbourDepot', label: 'Depot', sub: 'containers and a crane' },
];
const MODES: { mode: RouteMode; label: string; sub: string }[] = [
  { mode: 'flat', label: 'Flattest', sub: 'detours around hills' },
  { mode: 'short', label: 'Shortest viable', sub: 'fewest tiles' },
  { mode: 'hairpin', label: 'Switchbacks', sub: 'zigzags up a mountain' },
];
/** The road the planner is asked to plan as: a narrow one, whose spans and grades suit a single track. */
const AS_ROAD = RoadType.Paved;
/** How far a parallel track looks for the line it follows, in tiles. */
const PARALLEL_REACH = 4;
/** A deck's reach across water, in tiles, plain and with big bridges on (as far as a road's longest, 2 Nov 2026). */
const SPAN = 14, BIG_SPAN = STRAIT_SPAN;
/** The plan's search, a frame (ms), toward the end under the cursor (world/roads.ts planRoutesLazy). */
const PLAN_MS = 8;
const fmt = (steps: number) => String(Math.round(steps * 2) / 2);
const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
/** Tiles of deck in a path: its samples on a bridge, a quarter tile each. */
const deckOf = (p: RailPath): number => Math.round(p.under.reduce((n, u) => n + (u >= 3 && u <= 6 ? 0.25 : 0), 0));

/** What the road builder lends its Rails side: its picks, its layer, its tip, its wallet and its callbacks. */
export interface RailHost {
  w: () => World | null;
  pick(cx: number, cy: number): THREE.Vector3 | null;
  cellAt(x: number, z: number): { w: World; d: number; ox: number; oz: number } | null;
  addPreview(o: THREE.Object3D | null): void;
  clearPreview(): void;
  setTip(kind: 'ok' | 'bad' | 'none', title: string, body: string): void;
  hideTip(): void;
  placeTip(mx: number, my: number): void;
  wallet: Wallet;
  /** Tiles of a cell changed: redraw them and tell everything that reads the world. */
  onChange(w: World, tiles: number[]): void;
  /** Why undo can't be used (online), or null. */
  undoBarred(): string | null;
  layer: THREE.Group;
}

/** One cell's half of a planned track: the spec it lays, the path it shapes into, and where the cell sits relative to home. */
interface Part { w: World; spec: RailSpec; path: RailPath; ox: number; oz: number }
/** A planned track: its parts (one per cell) and what it is, for the tip. */
interface Made { parts: Part[]; tiles: number; deck: number; climb: number; drop: number; bridges: number; tunnels: number }

/**
 * The builder's Rails side (docs/trains.html, "Laying your own track"). Track is laid as roads are: a click
 * for the start, the cheapest route to the cursor drawn as a ghost, a click to lay it. A start or an end on a
 * line already there (the generator's, or one laid here) becomes a junction: the new track runs along that
 * line a little way and curves off it. Shift while picking the end lays a parallel track instead: the nearest
 * line is followed at the gap the start was clicked at, as far as the cursor projects along it. + and − raise
 * the start and the end as they raise a road's. Stations are placed with a click, R to turn them, on level
 * ground with a street along the back of the lot; each comes with its platform track, whose buffers a track
 * started from either end carries on from.
 */
export class RailTool {
  readonly box = el('div', 'rb-side rb-rails');
  private era: RailEra = 'steam';
  /** The station kind picked, or null when laying track. */
  private station: StationKind | null = null;
  private stTurn = 1;
  private mode: RouteMode = 'flat';
  private big = false;
  private bore = false;
  private liftA = 0;
  private liftB = 0;
  private start: Anchor | null = null;
  /**
   * The county the track being laid starts in, and where it sits from the one the player is in (tiles): home, or
   * a neighbour clicked in (the user, 2 Nov 2026: track should run on across county lines). Null with no start.
   */
  private base: { w: World; ox: number; oz: number } | null = null;
  private plan: RoutePlan | null = null;
  /** The plan from the start that may run out over deep water (for an end out at sea), made when first wanted. */
  private seaPlan: RoutePlan | null = null;
  /** The preview waits on a plan's search reaching this end (-1: all of it): update() searches on, then previews again. */
  private waiting: { plan: RoutePlan; target: number } | null = null;
  /** How long a route may search for now: a frame's slice while previewing, all it takes for a click. */
  private budget = PLAN_MS;
  private across = new Map<number, RoutePlan>();
  private startMark: THREE.Object3D | null = null;
  /** The last thing hovered, so the preview is only made again when it moves. */
  private hoverSig = '';
  private why = '';
  /** The track last planned under the cursor, laid by the next click. */
  private made: Made | null = null;
  /** Every track and station laid since the side was last opened here, for undo. */
  private history: { w: World; kind: 'rail' | 'station'; cost: number }[] = [];
  private eraBtns = new Map<RailEra, HTMLButtonElement>();
  private stBtns = new Map<StationKind, HTMLButtonElement>();
  private modeBtns = new Map<RouteMode, HTMLButtonElement>();
  private routePill: HTMLButtonElement | null = null;
  private bigBtn: HTMLButtonElement | null = null;
  private boreBtn: HTMLButtonElement | null = null;
  private liftEl: HTMLElement | null = null;
  private countEl = el('span', 'rb-rcount');
  private drawn = false;
  private icons = new Map<RailEra, HTMLImageElement>();

  /** A track laid in cell `w`, for its save delta; a station likewise; one taken back. */
  onRail: ((w: World, spec: RailSpec) => void) | null = null;
  /** Track laid by hand: how many tiles, whether it was a parallel track, and how many of its ends joined a line (the rail lesson, the deeds). */
  onLaid: ((tiles: number, parallel: boolean, junctions: number) => void) | null = null;
  onStation: ((w: World, spec: StationSpec) => void) | null = null;
  /** A track or station taken back: `at`, a tile to bulldoze it by (world/railUndo.ts), so a log already sent can say so. */
  onUndone: ((w: World, at: { x: number; z: number } | null) => void) | null = null;

  constructor(private host: RailHost) {
    this.buildPanel();
    this.sync();
  }

  get drawing(): boolean { return this.start !== null; }
  /** R turns the station on this side, so the game leaves the camera lock alone while one is picked. */
  get usesR(): boolean { return this.station !== null; }

  /** Esc: a half-drawn track is let go of, or a picked station put back; true when there was one. */
  cancel(): boolean {
    if (this.start) { this.clearStart(); this.host.clearPreview(); return true; }
    if (this.station) { this.setStation(null); return true; }
    return false;
  }

  /** The side is up: draw the squares' pictures once. */
  opened(): void {
    if (!this.drawn) {
      this.drawn = true;
      for (const [era, img] of this.icons) { try { img.src = railTileIcon(era); img.hidden = false; img.nextElementSibling?.remove(); } catch { /* the swatch stays */ } }
      for (const [kind, b] of this.stBtns) {
        const img = b.querySelector('img') as HTMLImageElement | null;
        const [w, d] = STATION_LOT[kind];
        if (img) buildingIconInto(img, kind, 'classic', { w, d, floors: 1 });
      }
    }
    this.hoverSig = '';
    this.count();
    this.sync();
  }

  /** The side is put down (another side, the tool closed, a new cell): nothing half drawn survives. */
  closed(): void {
    this.clearStart();
    this.host.clearPreview();
    this.host.hideTip();
  }

  setWorld(): void { this.history = []; this.clearStart(); this.count(); }

  private count(): void {
    const w = this.host.w();
    if (!w) return;
    const mine = w.rails.filter((p) => isBuiltRail(p) && !w.stations.some((st) => st.path === p.id));
    let tiles = 0;
    for (const p of mine) tiles += p.length;
    const st = w.stations.filter((s) => w.rails[s.path] && isBuiltRail(w.rails[s.path])).length;
    this.countEl.textContent = mine.length || st ? `${mine.length} track${mine.length === 1 ? '' : 's'} laid · ${Math.round(tiles)} tiles${st ? ` · ${st} station${st === 1 ? '' : 's'}` : ''}` : 'No track laid yet';
  }

  // ---- the frame ----------------------------------------------------------------------------------

  update(input: Input): void {
    const w = this.host.w();
    if (!w) return;
    ERAS.forEach((e, k) => { if (input.justPressed(`Digit${k + 1}`)) this.setEra(e.era); });
    STATIONS.forEach((s, k) => { if (input.justPressed(`Digit${k + 4}`)) this.setStation(s.kind); });
    if (input.justPressed('KeyF')) this.setMode(MODES[(MODES.findIndex((m) => m.mode === this.mode) + 1) % MODES.length].mode);
    if (input.justPressed('KeyV')) this.setBig(!this.big);
    if (input.justPressed('KeyN')) this.setBore(!this.bore);
    if (input.justPressed('KeyZ')) this.undo();
    if (input.justPressed('Equal') || input.justPressed('NumpadAdd')) this.setLift(this.lift + 1);
    if (input.justPressed('Minus') || input.justPressed('NumpadSubtract')) this.setLift(this.lift - 1);
    if (input.justPressed('KeyR') && this.station) { this.stTurn = (this.stTurn + 1) & 3; this.hoverSig = ''; }
    const click = input.takeClick();
    const shift = input.down('ShiftLeft') || input.down('ShiftRight');
    if (this.station) {
      if (click) { const h = this.host.pick(click.x, click.y); if (h) this.clickStation(w, h); }
      const h = input.hasMouse ? this.host.pick(input.mouseX, input.mouseY) : null;
      const sig = h ? `st|${this.station}|${this.stTurn}|${Math.floor(h.x)},${Math.floor(h.z)}` : 'none';
      if (sig !== this.hoverSig) { this.hoverSig = sig; this.previewStation(w, h); }
      if (h) this.host.placeTip(input.mouseX, input.mouseY);
      return;
    }
    if (click) {
      const h = this.host.pick(click.x, click.y);
      if (h) this.click(h, shift);
    }
    const h = input.hasMouse ? this.host.pick(input.mouseX, input.mouseY) : null;
    const sig = h ? `${this.start ? 'b' : 'a'}|${shift ? 's' : ''}|${h.x.toFixed(1)},${h.z.toFixed(1)}` : 'none';
    if (sig !== this.hoverSig) { this.hoverSig = sig; this.preview(h, shift); }
    else if (this.waiting && settlePlan(this.waiting.plan, this.waiting.target, performance.now() + PLAN_MS)) this.preview(h, shift);
    if (h) this.host.placeTip(input.mouseX, input.mouseY);
  }

  /**
   * Where a point picked (tiles from the player's county) lies: before a start, the county under it, home or a
   * neighbour; after, the start's county (d -1) or one beside it (d its side). `h` in that start county's tiles.
   */
  private where(h: THREE.Vector3): { w: World; base: { w: World; ox: number; oz: number }; d: number; h: THREE.Vector3 } | null {
    if (!this.base) {
      const c = this.host.cellAt(h.x, h.z);
      if (!c) return null;
      const base = { w: c.w, ox: c.ox, oz: c.oz };
      return { w: c.w, base, d: -1, h: new THREE.Vector3(h.x - c.ox, h.y, h.z - c.oz) };
    }
    const b = this.base, x = h.x - b.ox, z = h.z - b.oz;
    const dx = x < 0 ? -1 : x >= N ? 1 : 0, dz = z < 0 ? -1 : z >= N ? 1 : 0;
    const at = new THREE.Vector3(x, h.y, z);
    if (!dx && !dz) return { w: b.w, base: b, d: -1, h: at };
    // a corner county: build to the border first and carry on from there
    if (dx && dz) return null;
    const d = dx === 1 ? 0 : dx === -1 ? 2 : dz === 1 ? 1 : 3;
    return b.w.nbr[d] ? { w: b.w, base: b, d, h: at } : null;
  }

  /** A preview object drawn in the start county's tiles, put where that county is. */
  private show(o: THREE.Object3D | null, base: { ox: number; oz: number }): void {
    if (o) { o.position.x += base.ox; o.position.z += base.oz; }
    this.host.addPreview(o);
  }

  private click(hit: THREE.Vector3, shift: boolean): void {
    const at = this.where(hit);
    if (!at) return;
    const { w, h } = at;
    if (!this.start) {
      const { a, why } = anchorAt(w, h.x, h.z, true);
      if (!a) { this.host.setTip('bad', 'Can’t start here', why); return; }
      const low = this.seaLow(a, this.liftA);
      if (low) { this.host.setTip('bad', 'Too low over the sea', low); return; }
      this.base = at.base;
      this.setStart(w, a, h);
      return;
    }
    const cell = { d: at.d };
    if (shift && cell.d < 0) { this.layParallel(w, h); return; }
    // (the preview has nearly always searched this far already; a quick click finishes the search here)
    this.budget = Infinity;
    let made: Made | null;
    try { made = cell.d < 0 ? this.routeHome(w, h) : this.routeAcross(w, cell.d, h); } finally { this.budget = PLAN_MS; }
    if (!made) { if (this.why) this.host.setTip('bad', 'Can’t lay it there', this.why); return; }
    const cost = this.priceOf(made);
    if (!this.host.wallet.spend(cost, 'roads')) { this.host.setTip('bad', 'Not enough cash', `This track costs ${money(cost)}\nYou have ${money(this.host.wallet.cash)}`); return; }
    this.lay(made, cost);
  }

  /** The start placed: the plan is made from its node, and its mark drawn. */
  private setStart(w: World, a: Anchor, h: THREE.Vector3): void {
    const base = this.base;
    this.clearStart();
    this.base = base;
    this.start = a;
    this.liftB = this.liftA;
    // buffers with no open ground past them: only Shift's parallel track goes on from there (no plan to route)
    this.plan = a.node >= 0 ? planRoutesLazy(w, a.node, false, this.mode, this.span(), undefined, this.big, this.bore, false, true, !!a.wet) : null;
    this.seaPlan = a.wet ? this.plan : null;
    this.across.clear();
    const g = new THREE.Group();
    const [cx, cz] = a.node >= 0 ? nodeCenter(a.node, false) : [h.x, h.z];
    const o = buildOutline(w, cx - 0.5, cz - 0.5, cx + 0.5, cz + 0.5, 0xe2412f);
    if (o) g.add(o);
    if (a.join) { const m = buildOutline(w, h.x - 0.3, h.z - 0.3, h.x + 0.3, h.z + 0.3, 0xe2412f); if (m) g.add(m); }
    if (this.base) g.position.set(this.base.ox, 0, this.base.oz);
    this.startMark = g;
    this.host.layer.add(g);
    this.hoverSig = '';
    this.sync();
  }

  private clearStart(): void {
    this.start = null;
    this.base = null;
    this.plan = null;
    this.seaPlan = null;
    this.made = null;
    this.across.clear();
    if (this.startMark) { this.host.layer.remove(this.startMark); disposeObject(this.startMark); this.startMark = null; }
    this.hoverSig = '';
    this.sync();
  }

  // ---- routing ---------------------------------------------------------------------------------------

  /** The longest deck a track may reach across: a narrow road's span, or much further with big bridges on. */
  private span(): number { return this.big ? BIG_SPAN : SPAN; }

  /** The track from the start to the point hovered in home, or null with `why` set. */
  private routeHome(w: World, h: THREE.Vector3): Made | null {
    this.why = '';
    if (this.start && this.start.node < 0) { this.why = 'No open ground past those buffers to route from: hold Shift to run on beside a line'; return null; }
    if (!this.plan || !this.start) return null;
    const { a: endA, why } = anchorAt(w, h.x, h.z, true);
    if (!endA) { this.why = why; return null; }
    if (endA.node < 0) { this.why = 'No open ground past those buffers to end at: end short of them'; return null; }
    if (endA.node === this.start.node) return null;
    const low = this.seaLow(endA, this.liftB, true);
    if (low) { this.why = low; return null; }
    // out over deep water at either end: the plan that may run out to sea
    const plan = endA.wet && !this.start.wet ? this.planAfloat(w) : this.plan;
    if (!plan || !this.ready(plan, endA.node)) return null;
    const r = routeWithBridges(plan, endA.node, AS_ROAD, { boats: true });
    if (!r || r.nodes.length < 2) { this.why = 'No viable route: cliffs, deep water or buildings in the way'; return null; }
    const up = this.raise(w, r, this.start, endA);
    if (!up) return null;
    const sunk = this.sunk(plan, up);
    if (sunk) { this.why = sunk; return null; }
    const problem = routeProblem(w, up);
    if (problem) { this.why = problem; return null; }
    const made = specOf(w, up, this.start, endA, this.era);
    if (!made.spec) { this.why = made.why; return null; }
    const shaped = shapeRail(w, made.spec, w.rails.length);
    if (!shaped.path) { this.why = shaped.why ?? 'Can’t lay it there'; return null; }
    return this.stats([{ w, spec: made.spec, path: shaped.path, ox: 0, oz: 0 }], [up]);
  }

  /** The plan searched far enough for `target` (-1: all of it) inside the budget, else the preview waits on it. */
  private ready(plan: RoutePlan, target: number): boolean {
    if (settlePlan(plan, target, performance.now() + this.budget)) return true;
    this.waiting = { plan, target };
    return false;
  }

  /** The track on over the border into the neighbour across side d: two halves meeting at the line, both on the ground there. */
  private routeAcross(w: World, d: number, h: THREE.Vector3): Made | null {
    this.why = '';
    if (this.start && this.start.node < 0) { this.why = 'No open ground past those buffers to route from: hold Shift to run on beside a line'; return null; }
    if (!this.plan || !this.start) return null;
    const nb = w.nbr[d];
    if (!nb) return null;
    let far = this.across.get(d);
    if (!far) {
      // the far side is seeded from every border node: the whole plan first
      if (!this.ready(this.plan, -1)) return null;
      far = planAcross(this.plan, nb, d, this.span(), this.big, this.bore); this.across.set(d, far);
    }
    const end = nodeAt(h.x - DIRS[d][0] * N, h.z - DIRS[d][1] * N, false);
    const ep = nodeProblem(nb, end, false);
    if (ep) { this.why = ep; return null; }
    if (nb.rail[end] & (RailBit.Track | RailBit.Pad | RailBit.Loop)) { this.why = 'A railway is in the way over there: end short of it'; return null; }
    const back = routeWithBridges(far, end, AS_ROAD, { boats: true });
    if (!back) { this.why = 'No clean way over the border there'; return null; }
    // over the strait: a bridge in two halves meeting at the line, at the strait deck's height
    const sd = far.strait?.get(back.nodes[0]);
    const halves = sd ? this.straitHalves(d, sd, back) : null;
    if (sd && !halves) return null;
    if (!halves && back.nodes.length < 2) { this.why = 'No clean way over the border there'; return null; }
    const near = halves ? null : routeWithBridges(this.plan, acrossFrom(back.nodes[0], d, false), AS_ROAD, { boats: true });
    if (!halves && (!near || near.nodes.length < 2)) { this.why = 'No clean way over the border there'; return null; }
    // a strait bridge stands where it is built, whatever − and + ask for
    const a = halves ? halves[0] : this.raise(w, near!, this.start, null, this.liftA, 0), b = halves ? halves[1] : a && this.raise(nb, back, null, null, 0, this.liftB);
    if (!a || !b) return null;
    const sunk = halves ? null : this.sunk(this.plan, a);
    if (sunk) { this.why = sunk; return null; }
    const pa = routeProblem(w, a) ?? routeProblem(nb, b);
    if (pa) { this.why = pa; return null; }
    // the border point: on the line itself, at one height both halves share
    const lastN = a.nodes[a.nodes.length - 1];
    const at = d % 2 === 0 ? Math.floor(lastN / N) : lastN % N;
    const bx = d === 0 ? N : d === 2 ? 0 : at + 0.5, bz = d === 1 ? N : d === 3 ? 0 : at + 0.5;
    const hA = heightsOf(w, a), hB = heightsOf(nb, b);
    const yLine = Math.max(hA[hA.length - 1], hB[0]);
    const specA: RailSpec = { p: [...pointsOf(a, hA), bx, bz, yLine], era: this.era, b: { kind: 'border', side: d, at } };
    // a track carried on from a line's buffers, or off it at a turnout, takes its lead on the near side (2 Nov 2026)
    if (this.start.join) {
      const led = specOf(w, a, this.start, { node: lastN, join: null, side: 1 }, this.era);
      if (!led.spec) { this.why = led.why; return null; }
      specA.p = [...led.spec.p, bx, bz, yLine];
      specA.a = led.spec.a;
    }
    const back2 = (d + 2) & 3;
    const fbx = back2 === 0 ? N : back2 === 2 ? 0 : at + 0.5, fbz = back2 === 1 ? N : back2 === 3 ? 0 : at + 0.5;
    const specB: RailSpec = { p: [fbx, fbz, yLine, ...pointsOf(b, hB)], era: this.era, a: { kind: 'border', side: back2, at } };
    const sa = shapeRail(w, specA, w.rails.length), sb = shapeRail(nb, specB, nb.rails.length);
    if (!sa.path || !sb.path) { this.why = sa.why ?? sb.why ?? 'Can’t lay it there'; return null; }
    return this.stats([{ w, spec: specA, path: sa.path, ox: 0, oz: 0 }, { w: nb, spec: specB, path: sb.path, ox: DIRS[d][0] * N, oz: DIRS[d][1] * N }], [a, b]);
  }

  /** A track over the strait to the next county (world/railRoute.ts straitRoutes): its two halves, or null with `why` set. */
  private straitHalves(d: number, sd: StraitDeck, back: Route): [Route, Route] | null {
    const r = straitRoutes(this.plan!, d, sd, back);
    if ('why' in r) { this.why = r.why; return null; }
    return r.halves;
  }

  private stats(parts: Part[], routes: Route[]): Made {
    let tiles = 0, deck = 0, climb = 0, drop = 0, bridges = 0, tunnels = 0;
    parts.forEach((p, k) => {
      tiles += p.path.length;
      for (let i = 1; i < p.path.y.length; i++) { const dy = (p.path.y[i] - p.path.y[i - 1]) * 2; if (dy > 0) climb += dy; else drop -= dy; }
      deck += deckOf(p.path);
      for (const b of routes[k].bridges) { if (b.level) continue; if (b.tunnel) tunnels++; else bridges++; }
    });
    return { parts, tiles: Math.round(tiles), deck, climb, drop, bridges, tunnels };
  }

  /**
   * The route raised as − and + ask (`la` at the start, `lb` at the end): kept SEA_CLEAR over deep water wherever it
   * runs out over it, and a branch off (or onto) a line on a viaduct over the sea meeting it at that line's height.
   */
  private raise(w: World, r: Route, sa: Anchor | null, sb: Anchor | null, la = this.liftA, lb = this.liftB): Route | null {
    const atA = sa ? raisedJoin(w, sa) : undefined, atB = sb ? raisedJoin(w, sb) : undefined;
    const a = atA !== undefined ? Math.max(la, 1) : la, b = atB !== undefined ? Math.max(lb, 1) : lb;
    if (a <= 0 && b <= 0) return r;
    const up = raiseEnds(w, AS_ROAD, r.nodes, r.bridges, a, b, { sea: SEA_CLEAR, atA, atB });
    if (up.why) { this.why = up.why; return null; }
    return { nodes: r.nodes, bridges: up.bridges, raised: up.raised };
  }

  /** The plan from the start that may run out over deep water: made once for this start, when an end out at sea is first wanted. */
  private planAfloat(w: World): RoutePlan | null {
    if (!this.start || this.start.node < 0) return null;
    this.seaPlan ??= planRoutesLazy(w, this.start.node, false, this.mode, this.span(), undefined, this.big, this.bore, false, true, true);
    return this.seaPlan;
  }

  /**
   * Why an end out over the open sea can't stand at this lift (the user, 3 Nov 2026: high enough for every boat to pass
   * under), or null. A branch off a line on a viaduct takes that line's height and needs no lift of its own.
   */
  private seaLow(a: Anchor, lift: number, end = false): string | null {
    if (!a.wet || a.join || lift >= SEA_CLEAR) return null;
    return `Out over the sea the track stands on a viaduct at least ${SEA_CLEAR} steps over the water, so every boat passes under: press + to raise the ${end ? 'end' : 'start'} (${lift ? `${lift} step${lift === 1 ? '' : 's'} now` : 'on the water now'})`;
  }

  /** Why the route would leave track down on deep water (a stretch out at sea no deck carries), or null. */
  private sunk(plan: RoutePlan | null, r: Route): string | null {
    const wet = plan?.wet;
    if (!wet) return null;
    const held = new Uint8Array(r.nodes.length);
    for (const br of r.bridges) for (let k = br.from; k <= br.to; k++) held[k] = 1;
    for (let k = 0; k < r.nodes.length; k++) if (wet[r.nodes[k]] && !held[k]) return 'It would run along the sea itself: raise the end out over the water too (+), or end it on dry land';
    return null;
  }

  // ---- parallel track (Shift) ----------------------------------------------------------------------

  /**
   * The parallel track Shift asks for: the line nearest the cursor, followed at the gap the start stands from
   * it, from where the start projects onto it to where the cursor does.
   */
  private parallel(w: World, h: THREE.Vector3): { spec: RailSpec; path: RailPath; q: RailPath; gap: number } | null {
    this.why = '';
    if (!this.start) return null;
    // carrying a line on from its buffers (or off it): that line is where the track starts, not the one it runs beside
    const own = this.start.join?.q ?? null;
    const far = nearestRail(w, h.x, h.z, PARALLEL_REACH + 6, true, own);
    if (!far) { this.why = `No line within ${PARALLEL_REACH + 6} tiles of the cursor to run beside`; return null; }
    const q = far.p;
    // from the buffers it carries on from (at the gap that line already keeps), else from the start's node
    const cont = this.start.join?.cont ? railAt(this.start.join.q, this.start.join.cont === 'start' ? 0 : this.start.join.q.length) : null;
    const [sx, sz] = cont ? [cont.x, cont.z] : nodeCenter(this.start.node, false);
    // where the start projects onto that line, and how far off it stands
    let i0 = -1, d0 = Infinity;
    for (let i = 0; i < q.s.length; i++) { const d = Math.hypot(q.xz[i * 2] - sx, q.xz[i * 2 + 1] - sz); if (d < d0) { d0 = d; i0 = i; } }
    if (i0 < 0 || d0 > PARALLEL_REACH) { this.why = `The start is ${d0 > 99 ? 'far' : Math.round(d0) + ' tiles'} from the ${q.name}: start within ${PARALLEL_REACH} tiles of it`; return null; }
    const s0 = q.s[i0];
    const a0 = railAt(q, s0);
    const off = -a0.tz * (sx - a0.x) + a0.tx * (sz - a0.z);
    const sign = off >= 0 ? 1 : -1;
    const gap = sign * Math.max(MIN_GAP, Math.round(Math.abs(off) * 2) / 2);
    const s1 = q.s[far.i];
    if (Math.abs(s1 - s0) < 2) { this.why = `Move the cursor along the ${q.name}: the track runs from the start to where the cursor is beside it`; return null; }

    const spec: RailSpec = { p: offsetPoints(q, gap, s0, s1), era: this.era, nm: q.name };
    // joined to the buffers it carries on from, so the two run as one line
    if (cont && this.start.join) {
      const e = this.start.join.cont === 'start' ? 0 : this.start.join.q.length;
      spec.p = [cont.x, cont.z, cont.y / STEP, ...spec.p];
      spec.a = { kind: 'join', path: this.start.join.q.id, s: e, dir: this.start.join.cont === 'start' ? 1 : -1 };
    }
    const shaped = shapeRail(w, spec, w.rails.length);
    if (!shaped.path) { this.why = shaped.why ?? 'Can’t lay it there'; return null; }
    const clash = this.clash(w, shaped.path, q, Math.abs(gap), own);
    if (clash) { this.why = clash; return null; }
    return { spec, path: shaped.path, q, gap };
  }

  /** Whether a path comes too near another line (not `q`, which it keeps `gap` from, nor `own`, which it carries on): the reason, or null. */
  private clash(w: World, p: RailPath, q: RailPath | null, gap: number, own: RailPath | null = null): string | null {
    const near = Math.min(0.9, gap - 0.2);
    for (const o of w.rails) {
      if (o === q || o === own) continue;
      for (let i = 0; i < p.s.length; i += 2) {
        const x = p.xz[i * 2], z = p.xz[i * 2 + 1];
        for (let j = 0; j < o.s.length; j += 2) {
          if (Math.abs(o.xz[j * 2] - x) < near && Math.abs(o.xz[j * 2 + 1] - z) < near && Math.hypot(o.xz[j * 2] - x, o.xz[j * 2 + 1] - z) < near) return `Too close to the ${o.kind === 'loop' ? 'passing loop' : o.name}`;
        }
      }
    }
    return null;
  }

  private layParallel(w: World, h: THREE.Vector3): void {
    const par = this.parallel(w, h);
    if (!par) { if (this.why) this.host.setTip('bad', 'No parallel track there', this.why); return; }
    const cost = railCost(this.era, Math.round(par.path.length), deckOf(par.path));
    if (!this.host.wallet.spend(cost, 'roads')) { this.host.setTip('bad', 'Not enough cash', `This track costs ${money(cost)}\nYou have ${money(this.host.wallet.cash)}`); return; }
    const laid = layRail(w, par.spec);
    if (!laid.path) { this.host.wallet.earn(cost, 'refunds'); this.host.setTip('bad', 'Can’t lay it there', laid.why); return; }
    this.onRail?.(w, par.spec);
    this.onLaid?.(Math.round(par.path.length), true, 0);
    this.host.onChange(w, laid.tiles);
    this.history.push({ w, kind: 'rail', cost });
    this.count();
    this.clearStart();
    this.host.setTip('ok', `Parallel track laid · ${money(cost)}`, `Beside the ${par.q.name}, ${Math.abs(par.gap)} tiles over\nClick to start the next track`);
  }

  // ---- laying ----------------------------------------------------------------------------------------

  private priceOf(m: Made): number { return railCost(this.era, m.tiles, m.deck); }

  private lay(m: Made, cost: number): void {
    const laid: { w: World; tiles: number[] }[] = [];
    for (const p of m.parts) {
      const r = layRail(p.w, p.spec);
      if (!r.path) { this.host.setTip('bad', 'Can’t lay it there', r.why); continue; }
      laid.push({ w: p.w, tiles: r.tiles });
      this.onRail?.(p.w, p.spec);
      this.history.push({ w: p.w, kind: 'rail', cost: laid.length === 1 ? cost : 0 });
    }
    if (!laid.length) { this.host.wallet.earn(cost, 'refunds'); return; }
    this.onLaid?.(m.tiles, false, m.parts.reduce((n, p) => n + (p.spec.a ? 1 : 0) + (p.spec.b ? 1 : 0), 0));
    for (const l of laid) this.host.onChange(l.w, l.tiles);
    this.count();
    // carry on from the end just laid, from its buffers, at the height it ended at; across the border or at a
    // junction, start afresh
    const last = m.parts[m.parts.length - 1];
    this.liftA = this.liftB;
    const was = this.base ?? { ox: 0, oz: 0 };
    if (!last.spec.b) {
      // the next track starts at its buffers, in the county it ended in (over the border too)
      const e = railAt(last.path, last.path.length);
      const { a } = anchorAt(last.w, e.x - e.tx * 0.2, e.z - e.tz * 0.2);
      if (a) {
        this.clearStart();
        this.base = { w: last.w, ox: was.ox + last.ox, oz: was.oz + last.oz };
        this.setStart(last.w, a, new THREE.Vector3(e.x, 0, e.z));
        this.host.setTip('ok', m.parts.length > 1 ? 'Laid across the border' : 'Track laid', `${money(cost)}\nCarry on from its end, or Esc`);
        return;
      }
    }
    this.clearStart();
    this.host.setTip('ok', m.parts.length > 1 ? 'Laid across the border' : 'Track laid', `${money(cost)}\nClick to start the next track`);
  }

  private undo(): void {
    const why = this.host.undoBarred();
    if (why) { this.host.setTip('bad', 'No undo', why); return; }
    const last = this.history.pop();
    if (!last) { this.host.setTip('none', 'Nothing to undo', 'Only track laid since the builder was opened here can be taken back'); return; }
    // where to bulldoze it by, found while it is still down: both undos take the county's newest path
    const newest = last.w.rails[last.w.rails.length - 1];
    const at = newest ? undoRaze(last.w, newest) : null;
    const r = last.kind === 'station' ? unlayLastStation(last.w) : unlayLastRail(last.w);
    if (!r) { this.host.setTip('bad', 'Can’t take that back', 'Something was laid on it since'); return; }
    this.onUndone?.(last.w, at);
    this.host.onChange(last.w, r.tiles);
    if (last.cost) this.host.wallet.earn(last.cost, 'refunds');
    this.clearStart();
    this.count();
  }

  // ---- stations --------------------------------------------------------------------------------------

  /** The lot a station of the kind picked would take under the cursor: centred on it, turned by R. */
  private lotUnder(h: THREE.Vector3): { x: number; z: number; f: number } {
    const f = this.stTurn;
    const [W, D] = STATION_LOT[this.station!];
    const alongX = f === 1 || f === 3;
    const w = alongX ? W : D, d = alongX ? D : W;
    return { x: Math.round(h.x - w / 2), z: Math.round(h.z - d / 2), f };
  }

  private previewStation(w: World, h: THREE.Vector3 | null): void {
    this.host.clearPreview();
    if (!h || !this.station) { this.host.hideTip(); return; }
    const cell = this.host.cellAt(h.x, h.z);
    if (!cell || cell.d >= 0) { this.host.setTip('bad', 'Build stations at home', `Stations go up in ${w.name}: pan back over its ground`); return; }
    const { x, z, f } = this.lotUnder(h);
    const why = stationProblem(w, this.station, x, z, f);
    const { lot, a, b } = stationLot(this.station, x, z, f);
    this.host.addPreview(buildOutline(w, lot.x, lot.z, lot.x + lot.w, lot.z + lot.d, why ? 0xd2564f : 0x45e0ff));
    this.host.addPreview(buildDashedLine(w, a.x, a.z, b.x, b.z));
    const label = STATIONS.find((s) => s.kind === this.station)!.label;
    const cost = stationCost(this.station);
    if (why) this.host.setTip('bad', `No ${label.toLowerCase()} here`, `${why}\nR to turn it`);
    else {
      const afford = this.host.wallet.canAfford(cost);
      this.host.setTip(afford ? 'ok' : 'bad', `${label} · ${money(cost)}`, `${stationName(w, this.station, h.x, h.z)} · the platform runs along the dashed line\nR to turn it · ${afford ? 'click to build' : `you have ${money(this.host.wallet.cash)}`}`);
    }
  }

  private clickStation(w: World, h: THREE.Vector3): void {
    if (!this.station) return;
    const cell = this.host.cellAt(h.x, h.z);
    if (!cell || cell.d >= 0) return;
    const { x, z, f } = this.lotUnder(h);
    const why = stationProblem(w, this.station, x, z, f);
    const label = STATIONS.find((s) => s.kind === this.station)!.label;
    if (why) { this.host.setTip('bad', `No ${label.toLowerCase()} here`, why); return; }
    const cost = stationCost(this.station);
    if (!this.host.wallet.spend(cost, 'roads')) { this.host.setTip('bad', 'Not enough cash', `A ${label.toLowerCase()} costs ${money(cost)}\nYou have ${money(this.host.wallet.cash)}`); return; }
    const spec: StationSpec = { kind: this.station, x, z, f, era: this.era, nm: stationName(w, this.station, h.x, h.z), sd: (Math.random() * 2 ** 31) | 0 };
    const r = layStation(w, spec);
    if (!r.st) { this.host.wallet.earn(cost, 'refunds'); this.host.setTip('bad', `No ${label.toLowerCase()} here`, r.why); return; }
    this.onStation?.(w, spec);
    this.host.onChange(w, r.tiles);
    this.history.push({ w, kind: 'station', cost });
    this.count();
    this.hoverSig = '';
    this.host.setTip('ok', `${r.st.name} built`, `${money(cost)}\nLay track from either end of its platform: pick a track and click on the buffers`);
  }

  // ---- the preview and the tip ------------------------------------------------------------------------

  private preview(hit: THREE.Vector3 | null, shift: boolean): void {
    this.host.clearPreview();
    this.made = null;
    this.waiting = null;
    if (!hit) { this.host.hideTip(); return; }
    const at = this.where(hit);
    if (!at) { this.host.hideTip(); return; }
    const { w, h, base } = at;
    const cell = { d: at.d };
    const era = ERAS.find((e) => e.era === this.era)!.label;
    if (!this.start) {
      const { a, why } = anchorAt(w, h.x, h.z, true);
      if (!a) { this.show(this.nodeOutline(w, nodeAt(h.x, h.z, false), 0xd2564f), base); this.host.setTip('bad', 'Can’t start here', why); return; }
      const low = this.seaLow(a, this.liftA);
      if (a.node >= 0) this.show(this.nodeOutline(w, a.node, low ? 0xd2564f : 0xffffff), base);
      if (low) { this.host.setTip('bad', 'Too low over the sea', low); return; }
      // the first piece as a ghost: carried on from the buffers, a turnout off the line, or a stub on open ground (raised, at its lift)
      const first = firstPiece(w, a, this.era, this.liftA);
      const piece = first ? shapeRail(w, first, w.rails.length) : null;
      if (piece?.path) this.show(buildRailGhost(w, piece.path), base);
      if (a.join) {
        const q = a.join.q;
        this.host.setTip('ok', a.join.cont ? `Carry the ${q.name} on` : `Junction off the ${q.name}`, `${era} · ${a.join.cont ? 'from its buffers' : 'a turnout: the track runs along the line a little, then off it'}${a.wet ? '\nout over the water: it leaves at the line’s own height' : ''}\nclick to place the first end`);
      } else if (a.wet) {
        this.host.setTip('ok', 'Start out over the sea', `${era} · on a viaduct ${this.liftA} steps over the water (− +) · every boat passes under\nclick to place the first end`);
      } else {
        this.host.setTip('ok', 'Start here', `${era} · ${this.liftA ? `starts ${this.liftA} step${this.liftA === 1 ? '' : 's'} up` : 'starts on the ground'} (− +)\nclick to place the first end · or click on a line to join it`);
      }
      return;
    }
    if (shift && cell.d < 0) {
      const par = this.parallel(w, h);
      if (!par) { this.host.setTip('bad', 'No parallel track there', this.why || 'Move along the line'); return; }
      this.show(buildRailGhost(w, par.path), base);
      const deck = deckOf(par.path);
      const cost = railCost(this.era, Math.round(par.path.length), deck);
      const afford = this.host.wallet.canAfford(cost);
      this.host.setTip(afford ? 'ok' : 'bad', `Parallel track · ${Math.round(par.path.length)} tiles · ${money(cost)}`, `Beside the ${par.q.name}, ${Math.abs(par.gap)} tiles over, at its own heights${deck ? ` · ${deck} tiles of deck` : ''}\n${afford ? 'click to lay it' : `you have ${money(this.host.wallet.cash)}`} · let go of Shift to route freely`);
      return;
    }
    const m = cell.d < 0 ? this.routeHome(w, h) : this.routeAcross(w, cell.d, h);
    this.made = m;
    if (!m) {
      const [ax, az] = this.start.node >= 0 ? nodeCenter(this.start.node, false) : [h.x, h.z];
      this.show(buildDashedLine(w, ax, az, h.x, h.z), base);
      if (this.waiting) { this.host.setTip('none', 'Finding the way…', 'Looking at every way there: a moment'); return; }
      this.host.setTip('bad', this.liftA || this.liftB ? 'Can’t raise it like that' : 'Can’t lay it there', `${this.why || 'No viable route: cliffs, deep water or buildings in the way'}${this.liftA || this.liftB ? `\n${this.heightsText()}` : ''}`);
      return;
    }
    for (const p of m.parts) { const g = buildRailGhost(p.w, p.path); g?.position.set(p.ox, 0, p.oz); this.show(g, base); }
    const cost = this.priceOf(m);
    const afford = this.host.wallet.canAfford(cost);
    const hills = m.climb < 0.25 && m.drop < 0.25 ? 'Dead level the whole way' : `▲ ${fmt(m.climb)}  ▼ ${fmt(m.drop)} steps`;
    const spans = m.bridges || m.tunnels ? `\n${[m.bridges ? `${m.bridges} bridge${m.bridges === 1 ? '' : 's'}` : '', m.tunnels ? `${m.tunnels} tunnel${m.tunnels === 1 ? '' : 's'}` : ''].filter(Boolean).join(', ')} · ${m.deck} tiles of deck` : m.deck ? `\n${m.deck} tiles of deck` : '';
    const endB = m.parts[0].spec.b;
    const ends = [this.start.join ? (this.start.join.cont ? 'carried on from the buffers' : `a turnout off the ${this.start.join.q.name}`) : '', endB?.kind === 'join' ? `joins the ${w.rails[endB.path ?? -1]?.name ?? 'line'}` : ''].filter(Boolean).join(' · ');
    const border = m.parts.length > 1 ? `\nOn over the border into ${m.parts[1].w.name}` : '';
    const lifted = this.liftA || this.liftB ? `\n${this.heightsText()}` : '';
    this.host.setTip(afford ? 'ok' : 'bad', `${m.tiles} tiles · ${money(cost)}`, `${hills}${spans}${ends ? `\n${ends}` : ''}${lifted}${border}\n${MODES.find((q) => q.mode === this.mode)!.label} · ${afford ? 'click to lay it' : `you have ${money(this.host.wallet.cash)}`} · Shift for a parallel track`);
  }

  private nodeOutline(w: World, node: number, color: number): THREE.Object3D | null {
    const [cx, cz] = nodeCenter(node, false);
    return buildOutline(w, cx - 0.5, cz - 0.5, cx + 0.5, cz + 0.5, color);
  }

  private heightsText(): string {
    const f = (v: number) => (v ? `${v} step${v === 1 ? '' : 's'} up` : 'on the ground');
    return `Starts ${f(this.liftA)} → ends ${f(this.liftB)} (− + set the end)`;
  }

  // ---- settings -----------------------------------------------------------------------------------------

  private setEra(e: RailEra): void {
    this.era = e;
    this.station = null;
    this.sync();
    this.hoverSig = '';
  }

  private setStation(k: StationKind | null): void {
    this.station = this.station === k ? null : k;
    this.clearStart();
    this.host.clearPreview();
    this.sync();
    this.hoverSig = '';
  }

  private setMode(m: RouteMode): void {
    if (m === this.mode) return;
    this.mode = m;
    this.replan();
  }

  private setBig(on: boolean): void { if (on === this.big) return; this.big = on; this.replan(); }
  private setBore(on: boolean): void { if (on === this.bore) return; this.bore = on; this.replan(); }

  /** The plan has to be made again: the route or what it may bridge has changed. */
  private replan(): void {
    this.sync();
    const w = this.base?.w ?? this.host.w();
    if (w && this.start && this.start.node >= 0) { this.plan = planRoutesLazy(w, this.start.node, false, this.mode, this.span(), undefined, this.big, this.bore, false, true, !!this.start.wet); this.seaPlan = this.start.wet ? this.plan : null; this.across.clear(); }
    this.hoverSig = '';
  }

  private get lift(): number { return this.start ? this.liftB : this.liftA; }
  private setLift(n: number): void {
    const v = clamp(n, 0, LIFT_MAX);
    if (!this.start) { if (v === this.liftA && v === this.liftB) return; this.liftA = this.liftB = v; }
    else { if (v === this.liftB) return; this.liftB = v; }
    this.sync();
    this.hoverSig = '';
  }

  // ---- the panel ----------------------------------------------------------------------------------------

  private buildPanel(): void {
    const row = el('div', 'rb-row');
    ERAS.forEach((e, k) => {
      const btn = el('button', 'rb-sq');
      btn.type = 'button';
      btn.tabIndex = -1;
      btn.title = `${e.label} · ${e.sub}`;
      const img = el('img', 'rb-img');
      img.alt = '';
      img.hidden = true;
      this.icons.set(e.era, img);
      btn.append(img, el('i', `rb-sw sw sw-rail-${e.era}`), el('span', 'nm', e.label), el('span', 'pr', `${money(railCost(e.era, 1))}/tile`), el('kbd', 'rb-k', String(k + 1)));
      btn.addEventListener('click', () => { this.setEra(e.era); btn.blur(); });
      this.eraBtns.set(e.era, btn);
      row.append(btn);
    });
    STATIONS.forEach((s, k) => {
      const btn = el('button', 'rb-sq rb-bsq');
      btn.type = 'button';
      btn.tabIndex = -1;
      const [w, d] = STATION_LOT[s.kind];
      btn.title = `${s.label} · ${s.sub} · ${w}×${d} tiles · ${money(stationCost(s.kind))}`;
      const img = el('img', 'rb-ic');
      img.alt = '';
      btn.append(img, el('span', 'nm', s.label), el('span', 'pr', money(stationCost(s.kind))), el('kbd', 'rb-k', String(k + 4)));
      btn.addEventListener('click', () => { this.setStation(s.kind); btn.blur(); });
      this.stBtns.set(s.kind, btn);
      row.append(btn);
    });
    row.addEventListener('wheel', (e) => { row.scrollLeft += e.deltaY + e.deltaX; e.preventDefault(); e.stopPropagation(); }, { passive: false });

    const pills = el('div', 'rb-pills');
    const route = el('div', 'rb-drop');
    this.routePill = el('button', 'rb-pill drop');
    this.routePill.type = 'button';
    this.routePill.tabIndex = -1;
    const menu = el('div', 'rb-menu');
    menu.hidden = true;
    for (const m of MODES) {
      const b = el('button', 'rb-mi');
      b.type = 'button';
      b.tabIndex = -1;
      b.append(el('b', '', m.label), el('span', '', m.sub));
      b.addEventListener('click', () => { this.setMode(m.mode); menu.hidden = true; });
      this.modeBtns.set(m.mode, b);
      menu.append(b);
    }
    this.routePill.addEventListener('click', () => { menu.hidden = !menu.hidden; this.routePill!.blur(); });
    addEventListener('pointerdown', (e) => { if (!route.contains(e.target as Node)) menu.hidden = true; });
    route.append(this.routePill, menu);
    const toggle = (label: string, key: string, title: string, on: () => void): HTMLButtonElement => {
      const b = el('button', 'rb-pill tog');
      b.type = 'button';
      b.tabIndex = -1;
      b.title = title;
      b.innerHTML = `<i class="dot"></i>${label} <kbd>${key}</kbd>`;
      b.addEventListener('click', () => { on(); b.blur(); });
      return b;
    };
    this.bigBtn = toggle('Big bridges', 'V', 'Flyovers over roads and lines, and long spans over water', () => this.setBig(!this.big));
    this.boreBtn = toggle('Tunnels', 'N', 'With this on, the line bores straight through any hill in its way that is three tiles thick or more, rather than climbing it: drag the route across the hill', () => this.setBore(!this.bore));
    const height = el('div', 'rb-pill rb-lift');
    height.title = 'How high the track starts and ends: − and + (the keys too) before the first click set the start, after it the end';
    const down = el('button', 'rb-step', '−'), up = el('button', 'rb-step', '+');
    for (const b of [down, up]) { b.type = 'button'; b.tabIndex = -1; }
    this.liftEl = el('span', 'rb-lv');
    down.addEventListener('click', () => { this.setLift(this.lift - 1); down.blur(); });
    up.addEventListener('click', () => { this.setLift(this.lift + 1); up.blur(); });
    height.append(down, this.liftEl, up);
    const par = el('span', 'rb-pill rb-note');
    par.innerHTML = '<kbd>Shift</kbd> parallel track · click a line to join it';
    par.title = 'Hold Shift while picking the end to lay a track beside the nearest line, keeping the gap the start was clicked at. Click on any line to start a junction from it, or to end on one';
    const undo = el('button', 'rb-pill act');
    undo.type = 'button';
    undo.tabIndex = -1;
    undo.innerHTML = 'Undo <kbd>Z</kbd>';
    undo.title = 'Take back the last track or station laid, and its cost';
    undo.addEventListener('click', () => { this.undo(); undo.blur(); });
    pills.append(route, height, this.bigBtn, this.boreBtn, par, undo, this.countEl);
    this.box.append(row, pills);
  }

  private sync(): void {
    for (const [e, b] of this.eraBtns) b.classList.toggle('on', e === this.era && !this.station);
    for (const [k, b] of this.stBtns) b.classList.toggle('on', k === this.station);
    for (const [m, b] of this.modeBtns) b.classList.toggle('on', m === this.mode);
    const route = MODES.find((m) => m.mode === this.mode);
    if (this.routePill && route) this.routePill.innerHTML = `Route: <b>${esc(route.label)}</b> ▾ <kbd>F</kbd>`;
    this.bigBtn?.classList.toggle('on', this.big);
    this.boreBtn?.classList.toggle('on', this.bore);
    if (this.liftEl) {
      const f = (v: number) => (v ? `+${v}` : 'ground');
      this.liftEl.innerHTML = !this.start ? `Start <b>${f(this.liftA)}</b>` : `Start ${f(this.liftA)} · End <b>${f(this.liftB)}</b>`;
      this.liftEl.parentElement?.classList.toggle('on', this.liftA > 0 || this.liftB > 0);
    }
  }
}
