import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { NEXT_080, NEXT_WORLD } from '../world/nextWorld';

/**
 * Cargo you can tell apart by its shape (docs/cargolook.html phase 2, the user, 22 Oct 2026): 76 shapes for
 * the 247 cargo types, each type a small variation of its shape (how many, what they hold, a prop), so the
 * colour can say who a load is for and the model what it is.
 *
 * A model is built once per type from a few primitives, merged into one geometry with a group per material,
 * and cached: every marker of that type shares it. Its materials are the marker's own, by slot:
 *   0 paint (the look's colour), 1 dark (a deeper shade of it), 2 pale (the look's rim, or a neutral),
 *   3 skin (people's faces and hands).
 * Units are the marker's lift (render/cargoMarkers.ts, scaled 1.5): it stands on y = 0 within about
 * ±0.2 across and under 0.4 tall, below the gem at 0.48.
 */

export const Mat = { Paint: 0, Dark: 1, Pale: 2, Skin: 3 } as const;
export type Mat = (typeof Mat)[keyof typeof Mat];
const MODEL_MATS = 4;

type Part = { geo: THREE.BufferGeometry; mat: Mat };

const prim = new Map<string, THREE.BufferGeometry>();
/** A primitive, made once: only positions and normals, unindexed, so any of them merge with any other. */
function base(key: string, make: () => THREE.BufferGeometry): THREE.BufferGeometry {
  let g = prim.get(key);
  if (!g) {
    const m = make();
    const n = m.index ? m.toNonIndexed() : m;
    g = new THREE.BufferGeometry();
    g.setAttribute('position', n.getAttribute('position'));
    g.setAttribute('normal', n.getAttribute('normal'));
    prim.set(key, g);
  }
  return g;
}
const BOX = () => base('box', () => new THREE.BoxGeometry(1, 1, 1));
const CYL = (taper: number, seg: number) => base(`cyl${taper.toFixed(2)}:${seg}`, () => new THREE.CylinderGeometry(0.5 * taper, 0.5, 1, seg));
const BALL = (seg: number) => base(`ball${seg}`, () => new THREE.SphereGeometry(0.5, seg, Math.max(4, Math.round(seg * 0.7))));
const ROCK = () => base('rock', () => new THREE.IcosahedronGeometry(0.5, 0));
const RING = (tube: number, arc: number) => base(`torus${tube.toFixed(2)}:${arc.toFixed(2)}`, () => new THREE.TorusGeometry(0.5, tube, 6, 16, arc));

const tmpM = new THREE.Matrix4(), tmpQ = new THREE.Quaternion(), tmpE = new THREE.Euler(), tmpP = new THREE.Vector3(), tmpS = new THREE.Vector3();

/** The parts of one model, laid out in the lift's frame. */
class ModelKit {
  parts: Part[] = [];
  private put(g: THREE.BufferGeometry, mat: Mat, x: number, y: number, z: number, sx: number, sy: number, sz: number, rx = 0, ry = 0, rz = 0): void {
    tmpE.set(rx, ry, rz);
    tmpQ.setFromEuler(tmpE);
    tmpM.compose(tmpP.set(x, y, z), tmpQ, tmpS.set(sx, sy, sz));
    this.parts.push({ geo: g.clone().applyMatrix4(tmpM), mat });
  }
  /** A box `w` × `h` × `d`, its base at y (or centred there with `mid`). */
  box(mat: Mat, w: number, h: number, d: number, x = 0, y = 0, z = 0, ry = 0, rx = 0, rz = 0): this {
    this.put(BOX(), mat, x, y + h / 2, z, w, h, d, rx, ry, rz);
    return this;
  }
  /** A box centred at (x, y, z). */
  boxAt(mat: Mat, w: number, h: number, d: number, x: number, y: number, z: number, ry = 0, rx = 0, rz = 0): this {
    this.put(BOX(), mat, x, y, z, w, h, d, rx, ry, rz);
    return this;
  }
  /** An upright cylinder of radius r (top radius r·taper), its base at y. */
  cyl(mat: Mat, r: number, h: number, x = 0, y = 0, z = 0, taper = 1, seg = 12): this {
    this.put(CYL(taper, seg), mat, x, y + h / 2, z, r * 2, h, r * 2);
    return this;
  }
  /** A cylinder lying along x (axis 'x') or z, centred at (x, y, z). */
  lie(mat: Mat, r: number, len: number, x: number, y: number, z: number, axis: 'x' | 'z' = 'x', taper = 1, seg = 12, ry = 0): this {
    if (axis === 'x') this.put(CYL(taper, seg), mat, x, y, z, r * 2, len, r * 2, 0, ry, -Math.PI / 2);
    else this.put(CYL(taper, seg), mat, x, y, z, r * 2, len, r * 2, Math.PI / 2, ry, 0);
    return this;
  }
  /** A cylinder from its centre, tipped by rx/rz. */
  tilt(mat: Mat, r: number, h: number, x: number, y: number, z: number, rx: number, rz: number, taper = 1, seg = 8): this {
    this.put(CYL(taper, seg), mat, x, y, z, r * 2, h, r * 2, rx, 0, rz);
    return this;
  }
  /** A cone standing on y. */
  cone(mat: Mat, r: number, h: number, x = 0, y = 0, z = 0, seg = 12): this {
    this.put(CYL(0, seg), mat, x, y + h / 2, z, r * 2, h, r * 2);
    return this;
  }
  /** A ball (sx, sy, sz radii) centred at (x, y, z). */
  ball(mat: Mat, rx: number, x: number, y: number, z: number, ry = rx, rz = rx, seg = 10, rotY = 0): this {
    this.put(BALL(seg), mat, x, y, z, rx * 2, ry * 2, rz * 2, 0, rotY, 0);
    return this;
  }
  rock(mat: Mat, r: number, x: number, y: number, z: number, spin = 0): this {
    this.put(ROCK(), mat, x, y, z, r * 2, r * 1.6, r * 2, spin, spin * 1.7, spin * 0.6);
    return this;
  }
  /** A ring of radius R and tube t·R, lying flat (axis 'y'), or standing facing x or z; `arc` < 2π for a part, turned `roll` round its own axis. */
  torus(mat: Mat, R: number, tube: number, x: number, y: number, z: number, axis: 'x' | 'y' | 'z' = 'y', arc = Math.PI * 2, spin = 0, roll = 0): this {
    const rx = axis === 'y' ? Math.PI / 2 : 0, ry = axis === 'x' ? Math.PI / 2 : spin;
    this.put(RING(tube, arc), mat, x, y, z, R * 2, R * 2, R * 2, rx, ry, roll);
    return this;
  }

  // ---- shared bits

  /** A standing figure at (x, z): body in `body`, head of skin, `h` tall (0.17 an adult). */
  person(x: number, z: number, o: { h?: number; body?: Mat; hat?: 'cap' | 'hard' | 'sun' | 'peak' | 'dome' | 'top' | 'scarf'; skirt?: boolean } = {}): this {
    const h = o.h ?? 0.17, s = h / 0.17, body = o.body ?? Mat.Paint;
    if (o.skirt) this.cyl(body, 0.045 * s, 0.11 * s, x, 0, z, 0.55, 10);
    else this.cyl(body, 0.035 * s, 0.11 * s, x, 0, z, 0.82, 10);
    if (o.hat === 'dome') {
      this.ball(Mat.Paint, 0.05 * s, x, 0.15 * s, z, 0.045 * s);
      this.tilt(Mat.Pale, 0.004, 0.05 * s, x - 0.02 * s, 0.205 * s, z, 0, 0.4).tilt(Mat.Pale, 0.004, 0.05 * s, x + 0.02 * s, 0.205 * s, z, 0, -0.4);
      return this;
    }
    this.ball(Mat.Skin, 0.032 * s, x, 0.14 * s, z, 0.032 * s, 0.032 * s, 8);
    const top = 0.17 * s;
    if (o.hat === 'cap') this.cyl(Mat.Dark, 0.034 * s, 0.016 * s, x, top - 0.012 * s, z);
    else if (o.hat === 'hard') this.ball(Mat.Pale, 0.036 * s, x, top - 0.012 * s, z, 0.022 * s).cyl(Mat.Pale, 0.042 * s, 0.004 * s, x, top - 0.014 * s, z);
    else if (o.hat === 'sun') this.cyl(Mat.Pale, 0.055 * s, 0.006 * s, x, top - 0.012 * s, z).cyl(Mat.Pale, 0.028 * s, 0.022 * s, x, top - 0.012 * s, z);
    else if (o.hat === 'peak') this.cyl(Mat.Dark, 0.036 * s, 0.022 * s, x, top - 0.014 * s, z).box(Mat.Dark, 0.03 * s, 0.005 * s, 0.03 * s, x, top - 0.014 * s, z + 0.03 * s);
    else if (o.hat === 'top') this.cyl(Mat.Dark, 0.026 * s, 0.045 * s, x, top - 0.01 * s, z).cyl(Mat.Dark, 0.042 * s, 0.005 * s, x, top - 0.012 * s, z);
    else if (o.hat === 'scarf') this.torus(Mat.Pale, 0.032 * s, 0.35, x, 0.115 * s, z);
    return this;
  }
  /** A row of n figures across x, `gap` apart, centred. */
  crowd(n: number, gap: number, fn: (x: number, z: number, k: number) => void, z = 0, stagger = 0): this {
    for (let k = 0; k < n; k++) fn((k - (n - 1) / 2) * gap, z + (k % 2 ? stagger : -stagger), k);
    return this;
  }
  /** A pallet under goods. */
  pallet(w = 0.26, d = 0.26): this { return this.box(Mat.Dark, w, 0.035, d); }

  /** The parts merged: one geometry, a group per material, unindexed. */
  merge(): THREE.BufferGeometry {
    const by: THREE.BufferGeometry[][] = [[], [], [], []];
    for (const p of this.parts) by[p.mat].push(p.geo);
    const groups: THREE.BufferGeometry[] = [];
    const mats: number[] = [];
    by.forEach((list, m) => {
      if (!list.length) return;
      groups.push(list.length === 1 ? list[0] : mergeGeometries(list)!);
      mats.push(m);
    });
    const out = mergeGeometries(groups, true)!;
    // mergeGeometries numbers its groups 0..n-1 in order: give each its material's slot
    out.groups.forEach((g, k) => { g.materialIndex = mats[k]; });
    for (const p of this.parts) p.geo.dispose();
    for (const g of groups) if (!this.parts.some((p) => p.geo === g)) g.dispose();
    out.computeBoundingBox();
    // anything that dips below the ground (a rock, a wheel, a ring standing up) lifts the whole model onto it
    const low = out.boundingBox!.min.y;
    if (low < 0) { out.translate(0, -low, 0); out.computeBoundingBox(); }
    out.computeBoundingSphere();
    return out;
  }
}

/** One of the 76 shapes: its cargo class, the types it carries (in order: a type's index is its variant), and how it's built. */
interface Shape { cls: string; ids: string[]; build: (k: ModelKit, v: number, id: string) => void }

const P = Mat.Paint, D = Mat.Dark, L = Mat.Pale;
const pick = <T,>(v: number, xs: T[]): T => xs[v % xs.length];
/** The 0.8.0 works' cargo (game/cargoTypes.ts WORKS_080_CARGO), listed only when it is: always last, so no older type's variant moves. */
const n080 = (...ids: string[]): string[] => (NEXT_080 ? ids : []);

