      if (id === 'ferry' || id === 'cruise') k.torus(L, 0.05, 0.3, 0, 0.05, -0.1, 'z');
      if (id === 'charter' || id === 'floatPlane') k.box(L, 0.24, 0.008, 0.04, 0, 0.21, -0.07);
      if (id === 'lateFares') k.box(D, 0.03, 0.03, 0.02, 0, 0.2, 0).box(L, 0.05, 0.006, 0.05, 0, 0.2, 0);
