/** Each cultural good's shape and variant, by its name. */
const BY_GOOD = new Map<string, { shape: string; v: number }>();
for (const [name, s] of Object.entries(CULTURE_SHAPES)) s.goods.forEach((g, v) => BY_GOOD.set(g, { shape: name, v }));
export const goodShapeOf = (name: string): { shape: string; v: number } | undefined => BY_GOOD.get(name);
/** The model a cultural good's marker asks for: by its name, since a culture:N id is one load's. */
export const goodModelId = (name: string): string => `good:${name}`;

/** Each cargo type's shape and its variant (its place in the shape's list). */
const BY_ID = new Map<string, { shape: string; v: number }>();
for (const [name, s] of Object.entries(SHAPES)) s.ids.forEach((id, v) => BY_ID.set(id, { shape: name, v }));
export const shapeOf = (id: string): { shape: string; v: number } | undefined => BY_ID.get(id);

const cache = new Map<string, THREE.BufferGeometry>();
/**
 * The merged model of a cargo type (or of a cultural good, by goodModelId), made once and shared by every marker
 * of it; null for one with no shape of its own (contraband, a good no style sends), which keeps its class's plain model.
 */
export function cargoModel(id: string): THREE.BufferGeometry | null {
  const hit = cache.get(id);
  if (hit) return hit;
  const good = id.startsWith('good:') ? BY_GOOD.get(id.slice(5)) : undefined;
  const s = good ?? BY_ID.get(id);
  if (!s) return null;
  const k = new ModelKit();
  if (good) CULTURE_SHAPES[good.shape].build(k, good.v);
  else SHAPES[s.shape].build(k, s.v, id);
  const g = k.merge();
  cache.set(id, g);
  return g;
}
